window.__SUMMARY_PARTS__=window.__SUMMARY_PARTS__||[];window.__SUMMARY_PARTS__.push([{"i":40000,"as":"利用原位高分辨率透射电子显微镜与分子动力学模拟，在450°C下还原铁酸锶时捕捉到了一种未被报道过的空位有序中间相。该相作为结构缓冲，随后坍塌为无限层结构。在反向氧化过程中，其相变路径在200°C时出现了分叉。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["还原温度[SrFeO3]: 450度","表征技术[原子尺度相变动力学]: 原位高分辨透射电子显微镜结合分子动力学模拟"]},{"i":40001,"as":"为探究[FeFe]-氢化酶CbA5H对氧气抑制具可逆性的原因，研究提供了1.96埃高分辨率X射线晶体结构。结构证实，其氧稳定性归功于一个保守的半胱氨酸硫醇基团作为保护性配体，该配体直接配位金属活性中心，防止了不可逆的氧气损伤。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":7.0,"t":7.0},"kp":["催化特性[[FeFe]-氢化酶]: 最快的析氢酶","氧稳定性机制[CbA5H]: 活性位点附近的蛋白支架重排允许配体配位金属中心，形成高氧化态","氧抑制特性[常规[FeFe]-氢化酶]: 不可逆抑制","氧抑制特性[CbA5H]: 可逆抑制"]},{"i":40002,"as":"报道了一系列NCN钳形配体支撑的铋(III)有机金属催化剂。该主族元素催化剂打破了常规过渡金属的限制，通过调控二次配位球效应，成功在均相电催化质子还原析氢反应中实现了对反应性低价中间体的可控访问与高催化活性。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["催化剂体系[均相电催化质子还原]: 对位区铋（主族元素系统）","调控机制[二次配位球]: 控制反应性低价中间体以突破活性-过电位比例关系"]},{"i":40003,"as":"研究提出一种通用的脱氧金属光氧化还原C(sp3)-C(sp)偶联策略，通过NHC介导活化和镍催化，实现醇与炔基溴直接偶联转化为炔烃。该反应在温和、氧化还原中性条件下进行，适用底物范围广泛，包括药物、肽类、核苷和天然产物等复杂醇类分子，为制备点击化学所需的炔烃提供了实用平台。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["耦合策略[醇直接炔基化]: 脱氧金属光氧化还原C(sp3)-C(sp)偶联","催化体系[反应条件]: NHC介导的醇活化与镍催化","反应环境[反应条件]: 氧化还原中性及温和条件"]},{"i":40004,"as":"研究人员开发了ZrCl3-CH4体系，通过爆炸性成核在碳布上直接构建富含缺陷的超致密ZrC纳米岛，作为锚定铂单原子的超稳定平台。该策略使ZrC颗粒表面数密度比传统方法提高两个数量级，并消除了游离碳污染。Pt1@ZrC纳米岛电极在水电解中展现出协同效应，其质量活性分别是商业Pt@C催化剂的116倍和132倍。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":8.0,"t":7.0},"kp":["表面数量密度提升[ZrC颗粒]: 相比传统方法提升2个数量级","催化剂结构[析氢反应]: 铂单原子修饰的超致密富缺陷ZrC纳米岛"]},{"i":40005,"as":"研究开发了一种用于质子交换膜水电解的超低铱阳极催化剂。该催化剂采用电纺钛锆复合氧化物纳米棒作为载体，富含锐钛矿的异质结构有效稳定了TiO2并强化了IrOx的界面锚定。多孔纳米棒网络改善了铱的利用率和传质。在0.2 mgIr cm-2的负载量下，该催化剂在酸性析氧反应中展现出高活性和稳定性。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":8.0,"t":7.0},"kp":["载体材料[质子交换膜水电解阳极]: 电纺钛锆复合氧化物纳米棒异质结构","稳定机制[局部配位环境]: 富锐钛矿型TiO2稳定化与调节局部氧配位环境以强锚定超低Ir"]},{"i":40006,"as":"研究设计并合成了带有炔基或腈基“弹头”的环戊烯基γ-氨基丁酸类似物，作为高效的人鸟氨酸转氨酶(hOAT)灭活剂。这些化合物经历酶催化的γ-去质子化形成酮亚胺中间体，随后发生互变异构导致不可逆抑制。该灭活机制基于第二次去质子化策略，实现了对hOAT的高效靶向抑制。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["灭活机制[人鸟氨酸转氨酶]: 基于第二次去质子化策略的机制导向","抑制剂结构[hOAT]: γ-氨基丁酸的乙炔基和腈取代的环戊烯类似物"]},{"i":40007,"as":"研究通过在聚甲炔链上增加空间位阻，合成了四种新型的七甲川苯并噻唑染料，成功设计出能在短波红外(SWIR)波段发射荧光的二维J-聚集体。增加空间位阻显著改变了分子的自组装介晶相态和光物理性质，克服了单体微小变化会剧烈影响二维或管状J-聚集体形貌的挑战，为光通信和诊断领域提供了低成本材料。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["发光波段[J聚集体结构]: 近红外和短波红外","聚集体形貌[结构工程挑战]: 难以精确设计的二维或管状结构"]},{"i":40008,"as":"研究结合分子动力学和量子力学/分子力学自由能模拟，探究了隐花色素4a(Cry4a)中色氨酸自由基阳离子的去质子化及潜在的质子偶联电子转移(PCET)途径。结果显示，第三个色氨酸有限的溶剂可及性显著抑制了其去质子化效应。该研究揭示了蛋白质-溶剂界面在控制质子偶联反应性中的关键作用。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["自由基对产生机制[隐花色素4a光激发后]: 沿色氨酸四联体进行电子转移","磁性敏感机制[隐花色素4a]: 自由基对重组动力学"]},{"i":40009,"as":"对先前发表的关于“仿生碳自由基催化”研究的学术文章进行勘误与内容更正。","scd":{"b":2.0,"i":1.0,"r":3.0,"d":2.0,"t":5.0},"kp":[]},{"i":40010,"as":"研究利用四氰基醌二甲烷(TCNQ)和热稳定性极高的S=1/2四唑啉基自由基制备了电荷转移络合物，并获得了一种在低温下具有大磁阻的非凡多晶型物。X射线晶体学显示，该1:1络合物形成具有D-A-A-D堆积基序的四聚体单元。两种受体-受体二聚体均表现出强π键合特征，平面间距为3.1 Å，单重态-三重态能隙约为-3 kcal mol-1。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["磁阻特性[TCNQ与S=1/2四唑啉基自由基电荷转移络合物低温下]: 大磁阻","晶体组装结构[1:1供体-受体络合物多晶型物]: D-A-A-D堆积基序的四聚体单元"]},{"i":40011,"as":"研究开发了一种不依赖溶剂的光催化解聚新方法。该方法利用多种商业化光催化剂，将催化活性与溶剂解耦，在非氯化介质中实现对自由基通量的精确控制。这种方法无需含氯溶剂作为自由基来源，即可在温和条件下对聚甲基丙烯酸甲酯等商业全碳骨架聚合物实现接近定量的解聚收率(>95%)，为塑料闭环回收提供了新途径。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["反应温度[商业聚甲基丙烯酸酯无溶剂光催化解聚]: ≤150 °C","[传统全碳骨架聚合物解聚条件]: 需要高温(>400 °C)或大量氯化溶剂提供自由基"]},{"i":40012,"as":"研究提出一种通过氧化还原反应对锂电池内部的金属锂(Li0)进行高原子序数元素染色的方法，以实现多模态可视化。重金属离子(Mn+)被Li0还原并形核为纳米颗粒附着在表面，从而在电子束或X射线下有效增强金属锂的可见度。该技术能够在纳米到宏观尺度上空间识别并观察嵌入SEI中的非活性Li0形貌和分布。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["识别技术[电池内部金属锂多模态可视化]: 通过氧化还原反应用高-Z元素对金属锂(Li0)进行染色"]},{"i":40013,"as":"研究探讨了在手性锰(I)络合物催化的氢膦酸化反应中，由配体脱芳构化驱动的金属-配体合作(MLC)机制的作用。通过综合表征和动力学研究，确定了溶液中催化剂的结构，并分离出脱芳构化和非脱芳构化的催化活性中间体。研究证实，尽管该反应存在多种可行的催化路径，但脱芳构化引发的MLC机制在反应中发挥了关键作用。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["催化体系[锰(I)催化氢膦酸化]: 手性锰(I)络合物","[配体脱芳构化]: 驱动金属-配体合作(MLC)的关键机理特征"]},{"i":40014,"as":"研究提出一种在温和条件下无需催化剂即可从甲醇水溶液高效制氢的微滴策略。在3.5升放大反应器中以海水为水源，实现了968.1 μmol h-1的产氢速率，液相主要产物为甲醛。该性能优于大多数光催化甲醇脱氢系统。机理研究证实了微滴界面在促进甲醇脱氢反应中的关键驱动作用。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":8.0,"t":6.0},"kp":["产氢速率[甲醇水溶液微滴界面无催化剂制氢(3.5L反应器,海水为水源)]: 968.1 μmol h-1"]},{"i":40015,"as":"研究考察了球磨过程中香草醛与巴比妥酸发生的Knoevenagel缩合反应动力学。与溶液反应的一级动力学不同，机械化学呈S型动力学曲线，具有自催化特征。通过在不同材质和研磨频率的反应容器中进行实验，排除了颗粒断裂或流变性质改变是加速唯一原因的假说，证实了反应加速源于试剂在机械力环境下的力学行为变化。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["反应动力学[溶液法克诺文格尔缩合反应]: 遵循一级反应动力学","反应动力学[球磨机械化学克诺文格尔缩合反应]: 呈S型曲线，具有慢诱导期后迅速加速的力加速自催化特征"]},{"i":40016,"as":"探讨准一维材料CrZr4Te14在压力诱导下，从反铁磁性向单带超导性转变的多带超导物理机制。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":3.0,"t":5.0},"kp":["[准一维CrZr4Te14材料]: 压力诱导下从反铁磁性向单带超导性发生多带超导转变"]},{"i":40017,"as":"研究通过将具有内在空腔的纯烃类分子笼溶解于大位阻溶剂中，制备了II型多孔液体。结构分析和分子动力学模拟证实，溶剂被有效排除在分子笼空腔之外，在液态下成功保留了源于分子笼的永久孔隙率。该烃类笼在固态下对CO2表现出强烈的物理吸附亲和力，并在埃尺度限制下通过四极矩相互作用，为乙烯/乙烷的溶液选择性分离提供了新材料。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["材料体系[乙烯/乙烷分离]: II型多孔液体 (溶解于空间位阻大、尺寸排阻溶剂中的刚性纯烃类分子笼)"]},{"i":40018,"as":"介绍一种合成孪生二甲基反式十氢萘萜类化合物的通用方法，涉及复杂有机分子合成技术。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[复杂有机分子合成]: 开发合成孪生二甲基反式十氢萘萜类化合物的通用方法"]},{"i":40019,"as":"研究证实电解质工程可显著提高糠醛(FF)电催化加氢转化为2-甲基呋喃(2MF)的选择性。在pH=2的铜催化剂上，与硫酸盐电解质(54.8%)相比，磷酸基电解质在-0.5 V vs RHE下将2MF的选择性提升至72.1%。原位表面增强拉曼光谱表明，H3PO4能与吸附的糠醛形成氢键，从而有效抑制竞争性析氢和糠醇副产物生成。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[电解质工程]: 极大增强糠醛(FF)电催化加氢转化为2-甲基呋喃(2MF)的选择性"]},{"i":40020,"as":"研究开发了一种铱催化的动态动力学拆分策略，实现了外消旋C2-取代吡啶的直接不对称氢化，无需预活化步骤即可高效合成手性哌啶。该策略的核心在于原位生成碘化氢，它能瞬时激活吡啶环并支持高效的催化循环。这一方法克服了芳香环固有的稳定性和催化剂失活等难题，拓展了不对称氢化的立体化学多样性。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["催化剂体系[基于动态动力学拆分的吡啶不对称氢化]: 铱催化体系"]},{"i":40021,"as":"研究提出了一种从简单原料模块化组装密集取代四氢呋喃(THF)的新方法。该策略具有两大核心优势：一是模块化组装，二是能实现精确的化学、区域、非对映和对映选择性。它成功克服了在精确立体控制下构建具有多个邻位手性中心的复杂sp3-杂环的挑战，为天然产物和药物合成提供了通用且稳健的方法。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["合成技术挑战[多取代四氢呋喃]: 需要在精确立体控制下构建多取代sp3-杂环，目前缺乏通用且稳健的快速合成方法","[密集取代四氢呋喃]: 传统合成方法通常步骤繁多且仅针对单一目标结构定制"]},{"i":40022,"as":"研究开发了一种基于级联不对称脱芳构化的多环骨架发散组装方法。以吲哚为底物，通过邻氯醌诱导的不对称脱芳构化和氮杂普林环化，原位生成桥环类酚鎓中间体。通过精确控制这类高活性碳正离子中间体的转化路径，实现了复杂手性多环分子的高选择性骨架重排和多样化合成。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["合成技术挑战[碳正离子介导的骨架重排]: 高度活泼的碳正离子中间体转化路径的调控极具挑战，但以选择性方式进行骨架重排具有极高的合成价值","[多环结构的发散组装]: 报道了通过吲哚/氮杂普林环化和铼类中间体选择性转化的级联不对称脱芳构化实现手性多环结构的发散组装"]},{"i":40023,"as":"研究结合真空紫外光解离光谱和量子化学计算，探究了118 nm光电离驱动下不饱和腈（丙烯腈、3-丁烯腈、4-戊烯腈）与水在气相冷环境中的离子-分子反应。实验表明，产物高度依赖于腈前体的烷基链长度。短链丙烯腈与水反应，成功实现了气相腈-水簇中非生物肽类键的形成，为星际介质中生命起源分子的形成路径提供了证据。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[非生物肽键形成机制]: 结合真空紫外-红外光解离光谱和量子化学从头计算方法，探究冷气相星际介质和行星大气环境中不饱和化合物离子-分子反应形成肽键的路径"]},{"i":40024,"as":"提出结合主动采样与SHAP证据压缩的大语言模型方法，用于暖通空调系统的高效故障诊断。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[HVAC系统故障诊断]: 结合主动采样与SHAP证据压缩的大语言模型方法"]},{"i":40025,"as":"介绍一种基于物理强化学习的分体式空调节能控制算法，并通过真实硬件实验验证其有效性。","scd":{"b":5.0,"i":5.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[分体式空调节能控制]: 物理强化学习算法","[硬件验证]: 真实硬件实验验证有效性"]},{"i":40026,"as":"提出一种基于冲突规避的联合多任务学习框架，旨在提升电力系统稳定性评估的准确性与效率。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[电力系统稳定性评估]: 冲突规避的联合多任务学习框架"]},{"i":40027,"as":"研究指出，近几十年夏季北大西洋急流(NAJ)在东部大西洋上空发生了显著的向赤道偏移，这一现象主要由内部气候变率主导。先进的数值模拟表明，夏季北大西洋“变暖洞”是导致该偏移的关键因素。该区域特征通过湍流热释放机制影响了大气环流，从而驱动了急流位置的异常变化。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[夏季北大西洋急流]: 受内部气候变化影响向赤道移动"]},{"i":40028,"as":"研究使用钡离子(Ba2+)作为探针，探究了电压门控K+通道(KCNQ1)孔隙与电压传感器结构域(VSD)及调节亚基之间的关联。研究发现，外部Ba2+对通道的阻断具有电压依赖性，且电压依赖的Ba2+解阻断主导了通道开启。Ba2+探针反映出VSD激活状态的变化，证实了通道孔道在VSD激活后发生的细微构象变化。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[电压门控K+通道]: 钡离子探明VSD和调节亚基相关的孔隙细微变化"]},{"i":40029,"as":"研究提出了一种用于高温（125°C以上）和超低能耗神经形态应用的全二维离子门控突触晶体管（A2D-HTIGST）。该器件采用二硫化钨（WS2）作为通道，硫代磷酸铜铟（CuInP2S6）作为离子门控层，六方氮化硼（h-BN）作为电子屏障，石墨烯作为电极。该技术解决了传统突触晶体管在高温环境下难以实现低能耗和最优性能的挑战。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["工作温度[全二维离子门控突触晶体管]: >125°C","[神经形态应用]: 引入全二维(A2D)高温离子门控突触晶体管，以解决高温下实现低能耗和最优性能的挑战"]},{"i":40030,"as":"研究人员提出了一种界面溶剂热合成策略，用于制备具有强手性光学活性的超亲水离子盐衍生手性螺旋共价有机框架（COF）。该方法将水相中的超亲水离子胺与有机相中的醛单体分离，实现了结晶动力学的高效调控和分子到手性尺度的有效放大。合成的阴离子、阳离子和两性离子螺旋COF表现出优异的手性光学性质，椭圆度超过3600 mdeg，不对称因子绝对值高达0.07。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[手性螺旋COF合成]: 界面溶剂热合成结合超亲水离子盐","[手性光学活性]: 具有强手性光学活性和高效分子到介观尺度的手性放大"]},{"i":40031,"as":"","scd":null,"kp":[]},{"i":40032,"as":"研究设计了一个名为UNITE的通用游离DNA（cfDNA）特征集成深度学习框架，用于无创癌症检测。该框架基于0.1倍深度的浅层全基因组测序（sWGS）数据提取“基因组区域-片段长度”矩阵。通过使用来自26种癌症类型的1432个病例和631个对照共2063个血浆样本的sWGS数据，研究验证了该多特征AI框架在低肿瘤负荷癌症筛查中的有效性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[癌症检测]: 游离DNA(cfDNA)浅层全基因组测序","[检测框架]: 可扩展深度学习框架(UNITE)"]},{"i":40033,"as":"利用高分辨率体内MRI技术，研究探讨了先天性失明对人类早期视觉皮层的影响。研究发现，先天失明个体的视觉皮层中代表铁和髓鞘的标记物R2*和MTsat水平降低。同时，其灰质和浅层白质的扩散率增加、取向分散度升高且神经突密度降低。研究结果证明了感官经验的缺失会直接影响人类大脑皮层的微观结构和髓鞘形成。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[先天性失明]: 减少人类视觉皮层的髓鞘形成"]},{"i":40034,"as":"研究提出了一种由高输出纤维介电弹性体执行器（DEA）驱动的无电机髋部外骨骼。通过双极性分子设计克服了弹性体的内在限制，开发出的纤维DEA能够提供381.6 mN·mm−2的阻塞应力、260 J/kg的能量密度和1664 W/kg的功率密度。这种轻量化、高顺应性的无电机设计为下肢行走辅助和疲劳降低提供了一种全新的技术路径。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":5.0},"kp":["[髋部外装动力]: 高输出纤维介电弹性体执行器","[外装系统特点]: 无电机设计"]},{"i":40035,"as":"研究揭示了无镉胶体量子点发光二极管（QD-LED）在工作过程中的纳米级形态和化学降解机制。研究发现，InP/ZnSe/ZnS（红光）和ZnTeSe/ZnSe/ZnS（蓝光）QD-LED在运行中核心功能层会发生颗粒粗化和层变薄。此外，器件内部会产生氧和氢成分的扩散，且氧会积聚在铝电极与ZnMgO电子传输层（ETL）的界面处，这些变化共同导致了器件寿命的限制。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":6.0,"t":5.0},"kp":["QD-LEDs发光颜色[核心功能层材料]: 红色发光(InP/ZnSe/ZnS)和蓝色发光","[工作过程退化机制]: 核心功能层发生纳米级形态变化（颗粒粗化和层变薄）"]},{"i":40036,"as":"研究提出了一种利用DNA导向和鸟嘌呤特异性化学的单壁碳纳米管（CNT）缺陷逆向设计策略。该方法引入的鸟嘌呤缺陷被定义为sp2缺陷，不同于传统的sp3缺陷，它在实现性能可调的同时保留了CNT晶格的π共轭结构。该策略成功应用于五种不同的单手性CNT，实现了依赖于手性的高分辨率发射特性调控。","scd":{"b":8.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["缺陷工程[单壁碳纳米管发射调谐]: 逆向设计策略，利用DNA导向和鸟嘌呤特异性化学引入sp2缺陷"]},{"i":40037,"as":"","scd":null,"kp":[]},{"i":40038,"as":"","scd":null,"kp":[]},{"i":40039,"as":"","scd":null,"kp":[]},{"i":40040,"as":"","scd":null,"kp":[]},{"i":40041,"as":"研究在BiFeO3（BFO）外延薄膜中发现了一种机械辅助的极化反转路径。仅使用面外电场进行极化反转需要约4伏电压并会形成共存极化态；而在施加机械压力的情况下，正向矫顽电压可大幅降低甚至降至0伏，实现自发极化反转。该机制从根本上改变了极化反转的能量学，为多铁性材料的确定性域结构控制提供了新方法。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.5,"t":5.0},"kp":["[铁电极化控制]: 识别出外延BiFeO3薄膜中的一种机械辅助极化翻转路径，从根本上改变了翻转能学"]},{"i":40042,"as":"研究成功合成了具有nbo拓扑结构的三维结晶共价有机框架（3D COF）。该材料由刚性方形平面单体四环戊四苯基（TCTP）和螺硼酸盐连接构成。理论计算表明TCTP核心的高刚性有效抑制了框架形成过程中的结构波动。通过微晶电子衍射（MicroED）技术，确定其结构为非互穿立方框架，解决了带有螺硼酸盐连接的3D COF结构表征难题。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["拓扑结构[3D结晶共价有机框架]: nbo拓扑","合成构筑单元[3D COF]: 刚性方形单体TCTP和螺硼酸酯连接","刚性表现[TCTP核心]: 理论计算显示其刚性高于酞菁"]},{"i":40043,"as":"研究通过在弛豫铁电钙钛矿基体中精心设计原子尺度的化学异质性，显著提升了无铅介电陶瓷的储能能力。以(Bi0.5Na0.5)TiO3基弛豫铁电体为基础，通过操纵耦合的A/B亚晶格占据关联，在块体陶瓷中同时实现了大极化、低滞后损耗和高击穿强度。该设计为先进脉冲功率和高电压电子设备介电电容器的研发提供了有效途径。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.5,"t":5.0},"kp":["能量存储能力[介电陶瓷]: 超高能量密度和效率","[提升机制]: 弛豫铁电钙钛矿基体中刻意工程化的原子级化学异质性"]},{"i":40044,"as":"","scd":null,"kp":[]},{"i":40045,"as":"研究通过将电化学门控与局部热激活相结合，在单个可扩展的模拟组件中成功实现了多功能电化学记忆特性。该器件不仅具备基础的ON/OFF开关功能，还实现了线性多态模拟电阻调节、非线性易失性开关、脉冲、振荡和随机复杂功能。这一设计突破了单一器件功能的局限性，为人工智能信息处理的高效神经形态计算提供了新硬件基础。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[新型电子器件功能]: 线性多态模拟电阻调节、非线性易失性开关、脉冲、振荡和随机等复杂功能","[技术目的]: 通过相共存实现多功能电化学记忆，以支持高效的类脑计算"]},{"i":40046,"as":"利用聚合物支撑的质膜（PSPM）结合DNA-PAINT超分辨显微镜技术，研究首次直接可视化了细胞焦亡过程中天然GSDMD（Gasdermin D）孔道的纳米结构。定量分析表明，GSDMD组装成异质性的大分子环状结构，这直接关联着细胞膜透化作用。研究还揭示了棕榀酰化缺陷的C191A突变体无法形成完整的孔道，证明了脂质修饰对GSDMD孔稳定性的驱动作用。","scd":{"b":8.5,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[GSDMD孔结构成像方法]: 结合聚合物支撑质膜(PSPMs)与DNA-PAINT超分辨显微镜直接观察天然纳米结构"]},{"i":40047,"as":"为解决自发荧光量子产率低和光谱重叠的限制，研究开发了一种双光子光热（2PPT）显微镜技术，用于对细胞内源性发色团（如NADH和FAD）进行亚微摩尔级别的无标记成像。该技术通过测量发色团的光学吸收而非荧光，利用双光子吸收产生的局部热瞬变来捕获特异性信号。该技术成功实现了对线粒体在化疗反应中代谢变化的高灵敏度监测。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[细胞内发色团检测技术]: 双光子光热显微镜技术克服了自发荧光量子产率低和光谱重叠的缺陷","检测对象[内在发色团]: NADH和FAD","检测灵敏度[光热显微镜]: 亚微摩尔级成像"]},{"i":40048,"as":"研究报道了一种用于无氧化剂金催化反应的半稳定邻近引导N-杂环卡宾（NHC）配体平台（ImQun）。开发出的最佳金催化剂ImQunDippNMe2AuCl具有极短的N原子与Au中心螯合距离，在无氧化剂反应中表现出极佳的催化活性。这一合理设计的配体为Au(I)/Au(III)催化循环提供了通用且高效的解决方案，可媲美传统的钯催化体系。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["催化体系[无氧化剂金催化]: 金(I)/金(III)催化转化","配体特征[Au(I)/Au(III)催化]: 半稳定邻近引导的N-杂环卡宾(NHC)氮碳配体"]},{"i":40049,"as":"研究发现，微生物代谢产生的短链脂肪酸（丙酸和丁酸）通过直接结合p38α MAP激酶，促进其与TAB1的相互作用并激活自身磷酸化。激活的p38α随后磷酸化TRAF3的丝氨酸85位点，抑制其K63连接的多泛素化，从而阻断TBK1-IRF3的激活途径。这一机制显著降低了巨噬细胞的活化水平，在溃疡性结肠炎患者中证实了其有效抑制肠道炎症的作用。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["激酶靶向结合[短链脂肪酸(SCFAs)]: 丙酸和丁酸直接结合p38α MAP激酶","信号抑制机制[p38α激活后]: 抑制TRAF3的K63连接多聚泛素化","磷酸化位点[TRAF3]: 丝氨酸85"]},{"i":40050,"as":"","scd":null,"kp":[]},{"i":40051,"as":"基于全球森林样地数据集，研究发现群落冠层叶片特征沿三个维度变化：叶片经济性、叶片密度和氮磷比。这三个特征维度的地理变化受不同变量驱动：落叶树种比例决定叶片经济性，土壤有效磷和温度决定叶片密度，温度决定氮磷比。这些叶片特征维度共同解释了生态系统尺度森林最大光合作用60.2%的变异。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["群落冠层叶片特征[全球森林群落]: 沿叶片经济、叶片密度和氮磷比(N:P)三个维度排列"]},{"i":40052,"as":"","scd":null,"kp":[]},{"i":40053,"as":"","scd":null,"kp":[]},{"i":40054,"as":"","scd":null,"kp":[]},{"i":40055,"as":"研究开发了一种双通道微流体平台，包含源自类器官的子宫内膜上皮细胞和原代基质细胞。该模型重现了子宫内膜的关键生理特征，包括上皮极化、基质蜕膜化、细胞外囊泡释放和激素诱导的容受性。使用小鼠胚胎和人类囊胚进行验证，结果显示胚胎在模型中展现出初始粘附特征，包括通过极性滋养外胚层建立胚胎-上皮接触等。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["微流体平台[体外模拟人类胚胎粘附]: 包含器官衍生的子宫内膜上皮细胞和原代基质细胞的双通道系统","生理学特征[子宫内膜微流体模型]: 能够重现上皮极化、基质蜕膜化、细胞外囊泡释放和激素诱导的容受性"]},{"i":40056,"as":"","scd":null,"kp":[]},{"i":40057,"as":"","scd":null,"kp":[]},{"i":40058,"as":"","scd":null,"kp":[]},{"i":40059,"as":"","scd":null,"kp":[]},{"i":40060,"as":"","scd":null,"kp":[]},{"i":40061,"as":"窄带隙锡铅钙钛矿子电池中Sn/Pb分布不均匀会产生陷阱态并加速降解，阻碍了全钙钛矿串联太阳能电池的发展。研究引入S-烯丙基-L-半胱氨酸（SALC）作为配体，利用其与碘化亚锡（SnI2）的强烈硫醚配位作用，调节结晶动力学。该分子稳定策略实现了空间上均匀的Sn/Pb分布，减少了缺陷，从而制备出高效且稳定的全钙钛矿串联太阳能电池。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[Sn-Pb钙钛矿结晶]: 存在Sn/Pb分布不均问题","[分子稳定策略]: 采用硫醚配位增强均质性"]},{"i":40062,"as":"为解决单网络弹性体刚度与韧性难以兼顾，且坚韧的多网络弹性体抗疲劳性有限的痛点，研究开发出由坚硬的弹性体微粒通过较软的第二网络连接而成的双网络颗粒弹性体（DNGE）。其局部变化的成分和结构使DNGE能够有效分散应力，并在拉伸至中等应变时重复耗散能量，从而兼具了出色的韧性和良好的抗疲劳性能。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["材料体系[软机器人/可穿戴电子]: 抗疲劳坚韧双网络颗粒弹性体","[双网络颗粒弹性体]: 克服了传统弹性体的刚度-韧性妥协和抗疲劳性差的问题"]},{"i":40063,"as":"","scd":null,"kp":[]},{"i":40064,"as":"","scd":null,"kp":[]},{"i":40065,"as":"","scd":null,"kp":[]},{"i":40066,"as":"","scd":null,"kp":[]},{"i":40067,"as":"","scd":null,"kp":[]},{"i":40068,"as":"研究引入了一种新型深度卷积神经网络（NN）增强的贝叶斯全局分析方法，用于研究最高能重离子碰撞中的体观测量。该框架结合了相对论性2+1D二阶粘性流体动力学、动力学冻结以及微扰量子色动力学（QCD）。神经网络的应用显著加速了模型参数的贝叶斯推断，为提取重离子碰撞中的QCD物质属性提供了高效分析工具。该成果发表于《Physical Review C》。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":8.0},"kp":["[最高能重离子碰撞分析]: 神经网络增强的贝叶斯全局分析","流体力学模型[重离子碰撞]: 相对论性2+1D二阶粘性流体力学"]},{"i":40069,"as":"","scd":null,"kp":[]},{"i":40070,"as":"","scd":null,"kp":[]},{"i":40071,"as":"","scd":null,"kp":[]},{"i":40072,"as":"该研究探讨了玻色子Hofstadter模型中填充因子为ν=1/2的分数陈绝缘体的手性边激发现象。手性边缘激发是拓扑有序系统的标志性特征，在连续分数量子霍尔态中由手性Luttinger液体理论描述。研究重点在于验证这些场论预测能否在离散晶格模型中被精确识别与表征。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":8.0},"kp":["手性边激发[ν=1/2分数陈绝缘体]: 连续极限分数量子霍尔状态的χLL理论预测"]},{"i":40073,"as":"该研究针对金红石二氧化钛（TiO2）(111)极性表面的结构稳定性机制展开探讨。极性表面在催化和电子器件中具有重要作用，但其表面结构常因内在不稳定性而发生重构，其中熵（特别是振动熵）在表面补偿与重构中发挥的具体作用是该研究的核心要点。研究揭示了振动熵驱动的表面补偿机制。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":8.0},"kp":["[金红石TiO2(111)极性表面]: 存在振动熵驱动的补偿机制"]},{"i":40074,"as":"化学短程有序是多主元合金原子结构的内在特征，对其结构的有效控制能显著提升合金的强度和塑性。针对实验表征SRO极具挑战的现状，该研究提出并验证了利用正电子湮灭技术来识别多主元合金中化学短程有序结构的方法，为高性能合金的结构设计与优化提供了技术手段。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":8.0},"kp":["表征方法[多主元合金化学短程有序]: 正电子湮灭技术","[化学短程有序结构调控]: 可显著提升多主元合金的强度和延展性"]},{"i":40075,"as":"研究首次在实验中演示了通过三维螺旋注入方案实现超紧凑存储环中的光束存储。实验在一个周长22厘米、具有4.7纳秒旋转周期的弱聚焦环中，利用140纳秒的脉冲切割磁铁，成功存储了动量为297 keV/c的电子束。该方案利用闪烁体探测器验证了纳秒级周期的光束存储技术。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":8.0,"t":9.0},"kp":["电子束动量[超紧凑存储环]: 297 keV/c","环周长[弱聚焦环]: 22 cm","旋转周期[电子束]: 4.7 ns","脉冲宽度[脉冲磁铁]: 140 ns"]},{"i":40076,"as":"","scd":null,"kp":[]},{"i":40077,"as":"","scd":null,"kp":[]},{"i":40078,"as":"","scd":null,"kp":[]},{"i":40079,"as":"该研究在分数量子霍尔效应的Chern-Simons-Landau-Ginzburg理论框架下，探讨了任意子准粒子（涡旋）的相互作用。研究表明，该系统明确实现了第一类或第二类超导的混合化特性。通过高斯定律，每个涡旋同时携带磁通量和电荷，揭示了任意子束缚态与混合超导电性之间的内在联系。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":6.0,"t":8.0},"kp":["超导类型[任意子束缚态]: 实现了第一类或第二类超导的杂化"]},{"i":40080,"as":"针对生物衍生聚酯酰胺热熔胶的可回收性与强度研究文章发布的作者更正声明，修正相关细节。","scd":{"b":4.0,"i":8.0,"r":3.0,"d":4.0,"t":5.0},"kp":[]},{"i":40081,"as":"","scd":null,"kp":[]},{"i":40082,"as":"","scd":null,"kp":[]},{"i":40083,"as":"","scd":null,"kp":[]},{"i":40084,"as":"","scd":null,"kp":[]},{"i":40085,"as":"","scd":null,"kp":[]},{"i":40086,"as":"研究开发了一种结合基于样本的量子对角化（SQD）与定域活性空间自洽场（LASSCF）的量子-经典混合工作流LASSQD，用于解决过渡金属络合物强关联基态的求解难题。在多个铁基络合物上的测试表明，LASSQD在大幅降低计算成本的同时，其计算结果与LASSCF的偏差保持在1 kcal/mol以内。成本的降低归因于对精确且组合庞大的基态波函数的稀疏近似。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["混合算法[LASSQD]: 结合基于样本的量子对角化(SQD)与定域活性空间自洽场(LASSCF)","[过渡金属络合物基态求解]: 降低了强关联活性空间的计算成本"]},{"i":40087,"as":"","scd":null,"kp":[]},{"i":40088,"as":"探讨可进化人工智能系统的发展，强调设定操作风险阈值以确保AI安全可控的必要性。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["安全治理[可进化人工智能系统]: 必须设定操作风险阈值以确保AI的安全可控"]},{"i":40089,"as":"针对光催化合成过氧化氢（H2O2）过程中电荷快速重组导致效率受限的问题，受自然光合作用类囊膜分步电子转移启发，研究设计出一种D-A1-A2（供体-受体1-受体2）仿生有机笼。该分子架构通过能量梯度使供受体有序排列，实现了抑制重组的顺序电荷转移（RS-SCT）过程，从而显著提升光催化H2O2的产量。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["分子构架[光催化合成过氧化氢]: 仿生D-A1-A2有机笼","[电荷转移机制]: 抑制重组的顺序电荷转移"]},{"i":40090,"as":"聚焦质子交换膜水电解槽技术，研究如何缓解铱阳极因氢气引发的性能降解问题。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":4.0,"t":5.0},"kp":["技术目标[质子交换膜水电解槽]: 缓解铱阳极因氢气引发的性能降解问题"]},{"i":40091,"as":"","scd":null,"kp":[]},{"i":40092,"as":"研究醚基电解液中浓度变化如何驱动溶剂化结构转变，深化对电池内部机制的理解。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["溶剂化结构[醚基电解液]: 浓度变化（浓度交叉）可驱动其发生转变"]},{"i":40093,"as":"介绍一种双功能共聚物策略，通过阴离子锚定实现锡铅钙钛矿的氧化安全p型掺杂。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["掺杂策略[锡铅钙钛矿]: 阴离子锚定双功能共聚物实现氧化安全p型掺杂"]},{"i":40094,"as":"电化学C-N键形成是生产胺类等高附加值产物的可持续途径。与广泛使用的多相和固态催化剂不同，该研究展示了分子电催化剂的应用。通过利用单氢化物分子催化剂从CO2和硝酸盐分子中形成电化学C-N键，分子催化剂凭借其易于调节金属中心、配体和次级配位球的优势，为构建结构-活性关联基础知识库提供了有效途径。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["反应物[电化学C-N键形成]: CO2和硝酸盐（及含氮小分子）","目标产物[电化学C-N键形成]: 胺和酰胺等高价值产物","催化剂[C-N键形成]: 分子电催化剂"]},{"i":40095,"as":"研究提出一种光诱导铜催化策略，通过分子内1,5-氢原子转移（HAT），实现了环烷基胺的位点和立体选择性去对称β-C(sp3)-H炔基化。该方法成功在无张力环系统中完成了对映C(sp3)-H键的去对称化自由基交叉偶联，一步构建了形成C(sp3)-C(sp)键的多个连续立体中心。研究采用联萘酚与三齿配体的新型组合，在复杂手性分子及药物合成中极具应用价值。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["催化剂[环烷基胺β-C(sp3)-H炔基化]: 铜催化","反应条件[β-C(sp3)-H炔基化]: 光诱导","[去对称化反应]: 实现位点和立体选择性的多相邻立体中心构建"]},{"i":40096,"as":"针对水系电解质中电化学氮还原反应（NRR）受析氢反应（HER）严重限制的问题，研究利用密度泛函理论计算和微动力学建模，探讨了非水电解质中质子供体对Ru(0001)表面质子耦合电子转移（PCET）的影响。结果表明，增加质子供体的空间位阻可显著提高HER中Volmer步骤的能垒，从而在不显著减慢NRR的情况下抑制HER竞争，实现NRR的高选择性。","scd":{"b":7.5,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["竞争机制[水电解质NRR阴极]: 吸附H(*H)的过早积累会抑制N2吸附并促进析氢反应(HER)","抑制策略[非水电解质NRR]: 引入分子质子供体并通过空间位阻调节以在不显著降低NRR速率的情况下抑制HER"]},{"i":40097,"as":"研究成功合成并表征了首个四价铈（Ce4+）氢化铝络合物，打破了高氧化态铈与还原性氢化物配体在氧化还原化学上的不匹配限制。该络合物[Ce4+(κ2-H3AlC(TMS)3)(NP(tBu)3)3]通过单晶XRD、核磁共振、紫外可见近红外光谱及密度泛函理论（DFT）进行了结构确认，并利用循环伏安法和小分子反应评估了其基础反应特性。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":7.0,"t":5.0},"kp":["配体络合物[高氧化态铈]: 首例Ce4+氢化铝络合物（突破了氧化还原化学性质不匹配的限制）","合成络合物[具体物质]: [Ce4+(κ2-H3AlC(TMS)3)(NP(tBu)3)3] (CeHAl)"]},{"i":40098,"as":"研究通过元素掺杂策略合成了锰掺杂的四氧化三钴（Mn-doped Co3O4），展现出比纯Co3O4更优的催化性能、耐水性和长期耐久性。研究表明，Mn掺杂赋予了材料相对较高的Co3+含量和氧空位，有利于CO催化氧化。同时，由于Mn的d电子数少于Co，导致体系具有更高的d带中心，这阻碍了电子从Mn向CO分子的交换，从而削弱了CO吸附，使催化活性达到Sabatier最优状态。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["催化剂[CO氧化反应]: 锰掺杂的Co3O4 (Mn-doped Co3O4)","催化机制[Mn掺杂Co3O4]: 锰驱动能级调节，抑制CO的电子捐赠并削弱CO吸附，达到Sabatier最佳反应性","催化性能[Mn掺杂Co3O4对比纯Co3O4]: 具有显著优越的催化性能、耐水性及长期耐久性"]},{"i":40099,"as":"微生物生物膜会催化钛腐蚀。常见海洋微生物海藻希瓦氏菌在钛表面生长时，会消耗氧气在金属界面处形成厌氧微环境，并将TiO2还原为低价钛氧化物，导致钝化膜变薄。电化学分析表明，该过程使腐蚀率增加了六倍。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["腐蚀机制[微生物诱导钛腐蚀]: 海洋微生物（Shewanella algae）还原黄素破坏钛表面TiO2钝化膜的稳定性","破坏机理[富氧条件下钛钝化膜]: 微生物还原的黄素催化破坏电子绝缘的TiO2钝化膜"]},{"i":40100,"as":"分析可再生能源基础设施建设中，企业经验与社区抵制行为之间的社会与经济博弈。","scd":{"b":1.0,"i":3.0,"r":5.0,"d":2.0,"t":4.0},"kp":[]},{"i":40101,"as":"通过自下而上的策略，由离散的[Ni9]团簇合成了一种基于[Ni36]纳米笼的金属有机框架（[Ni9]-MOF）。该材料在强碱（8 M NaOH）和强酸（1 M HCl）条件下均表现出极佳的稳定性。它利用电子作为清洁氧化剂，在环境条件下通过电催化环己醇氧化高效合成己二酸，且具有高可回收性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["电催化剂[碱性介质中电催化合成己二酸]: MOF骨架中的超耐碱[Ni36]纳米笼","合成路径[己二酸电合成]: 环己醇在环境条件下以电子作为清洁氧化剂的电催化氧化反应"]},{"i":40102,"as":"通过溶液过饱和法，在体相锡颗粒上原位涂覆了高杨氏模量的NaF层。NaF涂层的机械限制效应有效抑制了锡在充放电过程中的体积膨胀和机械应力，避免了颗粒破裂。同时，该涂层促使形成均匀致密的固体电解质界面膜，显著提高了库仑效率和钠存储的持久性。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":7.0,"t":5.0},"kp":["失效机理[Sn负极钠离子电池]: 钠化过程中产生的高体积膨胀导致显著的内部应力，引发颗粒破裂和粉化","改性策略[Sn负极表面修饰]: 通过溶液过饱和路线原位涂覆高杨氏模量的NaF层","机械限制效应[NaF涂层]: 减轻脱钠/钠化过程中的应力以实现持久的钠存储"]},{"i":40103,"as":"直接合成了p型PbS量子点墨水，其量子点尺寸、光吸收和p型电子特性可调。该墨水克服了传统固相配体交换法导致的配体置换不完全和氧化不均匀问题。在6英寸硅晶圆衬底上制备出了高度均匀的导电p型薄膜，为晶圆级短波红外光电设备的可扩展制造突破了制造瓶颈。","scd":{"b":7.5,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["制备瓶颈[PbS量子点均质结]: 缺乏高效的p型量子点墨水直接合成法","技术缺陷[固态配体交换(SSLE)制备p型层]: 存在配体置换不完全和氧化不均匀的问题","应用目标[PbS量子点墨水]: 晶圆级短波红外(SWIR)成像"]},{"i":40104,"as":"提出了一种基于内在动力学稀疏表示的无监督功能子空间聚类方法（FRID）。FRID通过分析介观尺度的神经记录，识别具有共享微电路连接和信息编码特性的神经元（即介观功能组学）。在模拟复杂网络和经验性钙成像记录中，FRID的准确度显著优于基于放电相关性的聚类方法。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["聚类算法[单神经元水平脑功能图谱构建]: 基于内蕴动力学稀疏表示的功能子空间聚类(FRID)","技术优势[FRID无监督方法]: 解决了紧密相互作用的神经群之间异步和异质性的放电模式挑战"]},{"i":40105,"as":"戴琼海专访探讨光电集成领域的发展现状、技术瓶颈、底层架构创新及未来演进路径。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":3.0,"t":6.0},"kp":["技术瓶颈[光电集成领域]: 探讨架构创新及未来演进路径（无具体参数）"]},{"i":40106,"as":"提出一种结合人类与法学大模型的可信强化学习方法，旨在提升配电网运行的安全性。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["强化学习方法[配电网运行安全]: 结合人类与大语言模型的混合可信方法"]},{"i":40107,"as":"研究含氢中心的多载体能源系统，探讨双层随机规划与能源管理技术在系统优化中的应用。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["优化技术[含氢中心多载体能源系统]: 双层随机规划与能源管理"]},{"i":40108,"as":"开发了一种名为自发滴滴芯吸的方法，将载盐吸附剂集成到三维多孔基底中。该方法克服了松散粉末形式的载盐纳米多孔材料在设备集成上的困难，构建了机械性能稳固且水汽可及的吸附剂模块，为推进吸附式大气集水和热能储存应用的可扩展化提供了有效途径。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["复合材料特性[载盐纳米多孔固体]: 结合了吸湿盐的高吸水能力和纳米多孔吸附剂的孔隙率与蒸汽可及性","集成策略[大气集水及热能存储器件]: 采用自发滴滴芯吸技术以解决盐分和松散粉末形态对实际设备集成的挑战"]},{"i":40109,"as":"利用BERT模型与并行加速技术构建数据驱动模型，旨在提升短期光伏发电功率预测的准确性。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":3.0,"t":5.0},"kp":["预测模型[短期光伏发电功率]: 基于并行加速和BERT的数据驱动模型"]},{"i":40110,"as":"对（硅）-罗丹明染料中咕吨骨架的氨基进行结构修饰，开发出一类双四嗪荧光探针。这种修饰缩短了连接子并优化了淬灭状态，实现了在单一染料支架内的高效荧光淬灭与开启。其单功能衍生物与现有的点击化学标记策略完全兼容，荧光增强最高可达极显著水平，适用于活细胞生物正交标记。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["染料结构[荧光点击染料]: 基于呫吨支架氨基基团修饰的（硅）-罗丹明","连接子特征[双四嗪荧光染料]: 具有特别短的连接子"]},{"i":40111,"as":"分析欧洲氢能跨境管道建设，研究在不同补贴政策下跨国联盟的成本分摊方案与经济性。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":3.0,"t":4.0},"kp":[]},{"i":40112,"as":"以南非为例，探讨实施碳税政策如何在实现气候减排目标与维持市场价格稳定之间取得平衡。","scd":{"b":3.0,"i":4.0,"r":5.0,"d":3.0,"t":4.0},"kp":[]},{"i":40113,"as":"","scd":null,"kp":[]},{"i":40114,"as":"","scd":null,"kp":[]},{"i":40115,"as":"","scd":null,"kp":[]},{"i":40116,"as":"","scd":null,"kp":[]},{"i":40117,"as":"","scd":null,"kp":[]},{"i":40118,"as":"","scd":null,"kp":[]},{"i":40119,"as":"","scd":null,"kp":[]},{"i":40120,"as":"","scd":null,"kp":[]},{"i":40121,"as":"通过综合分析跨越北方、温带和热带森林的机载激光雷达数据和地面森林清查数据，研究发现气候不仅直接影响森林初级生产力，还通过调节森林冠层结构多样性产生间接影响。冠层结构多样性在调节气候对生产力的影响中发挥着关键且巨大的作用。研究还观察到，冠层结构多样性热点区域与初级生产力热点区域在纬度分布上表现出显著的一致性。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":8.0,"t":5.0},"kp":["调节效应[森林初级生产力]: 冠层结构多样性介导并调节气候变化对跨生物群落森林生产力的影响"]},{"i":40122,"as":"","scd":null,"kp":[]},{"i":40123,"as":"","scd":null,"kp":[]},{"i":40124,"as":"","scd":null,"kp":[]},{"i":40125,"as":"开发了一种名为EpiSewer的贝叶斯半机械废水监测模型，用于实时估计病原体传播动态。该模型综合考量了感染动态、病原体脱落及测量噪声（如异常值和未检出），能够直接从原始废水浓度和流量数据中推导出有效再生数和疫情增长率，完全无需预先对数据进行平滑、插补或去除异常值。在跨季节的多病原体监测中验证了其有效性。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["废水监测模型[病原体传播动态估计]: EpiSewer（贝叶斯半机制模型，同时处理感染动态、病原体脱落、测量噪声和异常值）"]},{"i":40126,"as":"","scd":null,"kp":[]},{"i":40127,"as":"","scd":null,"kp":[]},{"i":40128,"as":"基于美国多年数据，研究可再生能源配额制政策对调节碳排放与经济增长关系的实际影响。","scd":{"b":1.5,"i":4.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[美国可再生能源组合标准(2001-2022)]: 调节碳排放与经济增长关系"]},{"i":40129,"as":"开发基于金属有机框架与碳化硅的复合材料，研究其在高效吸附重金属及去除有机污染物中的应用。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["吸附与去除材料[重金属锶与环丙沙星]: 金属有机框架/碱蚀碳化硅复合材料"]},{"i":40130,"as":"研究利用MnOx/ZSM-5催化剂调控甲烷直接选择性氧化反应。Mn单原子催化剂主要生成C1产物（甲酸和甲醇），选择性约为78.8%；而Mn纳米颗粒催化剂则专一生成液态含氧化合物，乙酸选择性高达81.8%且稳定性优异。表征与理论计算表明，C1与C2产物选择性的切换由完全不同的甲烷活化机制决定。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":8.0,"t":6.0},"kp":["催化剂[甲烷直接选择性氧化(DSOM)]: 高度分散的MnOx/ZSM-5（包含单原子和纳米颗粒形式）","产物选择性[Mn单原子催化剂]: C1产物（甲酸和甲醇）联合选择性约为78.8%","产物选择性[Mn纳米颗粒催化剂]: 主要导向C2含氧化合物"]},{"i":40131,"as":"通过调节材料的氧空位与界面结构，研究二氧化碳光催化选择性转化为乙烷的高效反应技术。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["光催化转化[CO2选择性生产乙烷]: 通过对称差异氧空位基序调节Au-CeOx界面"]},{"i":40132,"as":"胶体单层MoS2常受硫空位引起的非辐射复合限制，倾向于形成带电激子。研究发现，环境条件下的紫外光照射可通过简单的氧化化学激活MoS2明亮的中性激子发射。该处理使光致发光强度提高两个数量级以上，发生显著蓝移，激子寿命从0.07纳秒激增至6.14纳秒，证实发光机制由带电激子复合转变为中性激子复合。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["中性激子发射[胶体MoS2单层]: 可通过简单的氧化化学处理实现有效激活","缺陷抑制机制[胶体MoS2单层]: 氧化化学处理可克服硫空位引起的电荷掺杂和陷阱态（缺陷诱导的非辐射复合）"]},{"i":40133,"as":"探讨人工智能技术如何赋能太阳能电池产业，带动从生产制造到系统优化的全产业链技术升级。","scd":{"b":3.0,"i":4.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[太阳能电池产业链]: 人工智能技术带动从生产制造到系统优化的全产业链升级"]},{"i":40134,"as":"评估不同大气条件下，5兆瓦与22兆瓦大型风力涡轮机在不同规模下的气动弹性载荷响应特性。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":4.0,"t":5.0},"kp":["风力涡轮机规模[气动弹性载荷响应评估]: 5 MW 和 22 MW"]},{"i":40135,"as":"针对长航时无人机动力需求，评估煤油燃料固态氧化物燃料电池与燃气轮机混合系统在不同场景下的运行及瞬态特性。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[长航时无人机动力]: 煤油燃料SOFC-GT混合动力系统多场景运行及瞬态特性评估"]},{"i":40136,"as":"金属氢键有机框架（HNNU-X，X=O, S, Se）能够利用空气、水和自然光直接合成乙醛。在室外无牺牲剂条件下，HNNU-Se表现出557.1 μmol g⁻¹ h⁻¹的乙醛生成率及95%的电子选择性。机制显示，[Zn(tpy)]2+阳离子作为位点捕获并活化空气中的二氧化碳，[XCN]-阴离子作为质子穿梭体促进快速质子转移，营造富质子微环境以克服动力学障碍。","scd":{"b":8.5,"i":3.0,"r":6.0,"d":8.0,"t":5.0},"kp":["催化剂[大气CO2人工光合作用合成乙醛]: 金属氢键有机框架 (HNNU-X, X=O, S, Se)","乙醛生成速率[HNNU-Se催化剂]: 557.1 μmol g⁻¹ h⁻¹","电子选择性[HNNU-Se催化剂]: 95%"]},{"i":40137,"as":"研究为大型螺旋装置（LHD）开发了模拟中性束电流驱动的程序。该程序集成了电磁感应、新经典输运（DKES/PENTA）和快离子分布函数（TASK3D-a和TASK/FP）计算模块。代码针对等离子体电流演化进行了基准测试并应用于实际LHD放电。结果显示，模拟的等离子体电流在趋势和绝对值上均与测量值相似。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["[大型螺旋装置(LHD)中性束电流驱动]: 开发集成电磁感应、新经典输运和快离子分布函数求解器的随时间演化模拟代码"]},{"i":40138,"as":"采用选区激光熔化（SLM）技术制备了含Y2O3的氧化物弥散强化（ODS）低活化铁素体/马氏体钢。相比普通RAFM钢，SLM成型的ODS-RAFM钢晶粒更细，具有更长的高温蠕变寿命，这与氧化物钉扎再结晶晶粒有关。在辐照环境下，ODS-RAFM钢表现出优异的稳定性，板条宽度仅轻微增加，硬化率低于RAFM钢。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["高温蠕变寿命[选区激光熔化成形的ODS-RAFM钢]: 在相同条件下比普通RAFM钢更长"]},{"i":40139,"as":"研究采用通量管方法，深入探讨了仿星器实际构型中气球模式的非线性饱和现象。为克服仿星器平衡求解器中存在的不精确力平衡问题，研究开发了一种变分方法来精确计算通量管能量。结果显示，对于线性上处于气球不稳定的轮廓，存在一种横跨等离子体小半径10%至20%的饱和（平衡）通量管状态。该通量管位移结构特征在全非线性MHD模拟中得到了有效重现。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":5.0,"t":3.0},"kp":["计算方法[仿星器中气球模式的非线性饱和]: 基于通量管法并发展变分方法计算通量能量以克服无力平衡误差问题"]},{"i":40140,"as":"SONIC偏滤器代码被用于模拟计算JA DEMO托卡马克中杂质氩和聚变产物氦的输运。在Psep约250 MW、辐射分数为0.8的条件下，增加氘气注入率至200 Pa m³s⁻¹，可将局部脱靶靶板上的峰值热负荷降至10 MW m⁻²以下，同时维持较低的分离层电子密度（2.0-2.5×10¹⁹ m⁻³）。此外，还评估了圆顶排气槽处的偏滤器中性粒子和气体压力。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":7.0,"t":4.0},"kp":["氘气喷射率[JA DEMO脱靶偏滤器]: 50–200 Pa m³s⁻¹","分离功率[JA DEMO脱靶偏滤器]: ~250 MW","辐射比例[JA DEMO脱靶偏滤器]: 0.8","模拟工具[杂质和聚变产物输运计算]: SONIC偏滤器代码"]},{"i":40141,"as":"在QUEST装置中，通过高场侧注入电子回旋波（ECW）实现了向电子伯恩斯坦波（EBW）的有效模式转换。EBW能在高密度等离子体中传播，并在低电子温度下提供高效的加热和电流驱动。实验明确观察到了由环向和径向磁场反转方向的EBW驱动电流，该特性对闭合磁通面的形成起到关键作用。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":6.0,"t":4.0},"kp":["波转换模式[QUEST高场侧注入电子回旋波]: 有效转化为电子伯恩斯坦波(EBW)","等离子体启动[QUEST使用电子伯恩斯坦波电流驱动]: 完全无感（非感应）启动"]},{"i":40142,"as":"提出了一种专门计算中性束注入（NBI）电离原子激发离子回旋发射（ICE）增长率的方法。通过引入依赖于速度的幂律分布和 pitch 角的高斯分布来建立NBI电离原子分布函数。计算表明，速度梯度对增长率的贡献与幂律指数成正比，而 pitch 角的各向异性贡献则与标准差的平方成正比。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["增长率计算[NBI粒子激发的离子回旋发射]: 采用特定的临时(ad hoc)方法计算近垂直传播快磁声波的增长率","分布函数模型[电离NBI原子]: 依赖于粒子速度的幂律分布和俯仰角的高斯分布"]},{"i":40143,"as":"本文研究了在TCV托卡马克装置中，等离子体三角形对双零（DN）L模式等离子体功率分配、刮削层（SOL）输运及边界湍流的影响。实验表明，三角形显著控制偏滤器内外靶板的功率分配：在高三角形下，仅少部分排气功率到达内靶；而在低三角形下，该比例显著上升。与解析模型对比表明，这不仅意味着极向径向输运的减少，还暗示了高场侧交叉场输运的增强。此外，偏滤器探针测量显示，低三角形下等离子体的剖面展宽，同时边界湍流的波动水平也有所降低。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":6.0,"t":4.0},"kp":["等离子体三角形度[TCV双零L模式边界湍流与功率共享]: 强烈影响偏滤器内外靶板之间的功率分配"]},{"i":40144,"as":"由于JT-60SA规划不进行氘氚（DT）运行，研究提出利用氦-3注入结合500 keV高能中性束的聚变方案来产生Alpha粒子。该方案旨在弥补当前缺乏大型DT运行装置的局限，用于研究未来反应堆中DT聚变产生的Alpha粒子的生成机制与限制特性，为ITER的相关研究提供基础数据。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":5.0,"t":4.0},"kp":["研究目标[JT-60SA D-3He场景]: 分析D-3He聚变方案作为替代方案的α粒子产生与限制"]},{"i":40145,"as":"为解决EAST托卡马克在大型瞬态扰动误差下固定参数PID控制器导致执行器饱和的问题，研究开发了基于深度强化学习的等离子体形状控制器。该控制器在现有等通量控制方案下运行，在模拟的丰富扰动环境中进行训练，并通过定制的奖励函数直接针对大扰动条件下的鲁棒性进行优化，从而提升调节性能。","scd":{"b":6.0,"i":5.0,"r":6.0,"d":6.0,"t":6.0},"kp":["控制算法[EAST抗大瞬态扰动等离子体形状控制]: 深度强化学习控制器（解决固定参数PID导致执行器饱和问题）"]},{"i":40146,"as":"为EAST开发了一款快速放电模拟器，将快速集成托卡马克建模工具METIS与自由边界平衡代码FBT耦合。METIS通过自洽求解热和粒子输运提供等离子体分布的演化，生成的输出直接用于FBT计算实现特定等离子体形状所需的极向场（PF）线圈电流。该耦合策略为探索可行的操作空间和制定控制波形提供了可靠的工具。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":5.0,"t":5.0},"kp":["放电模拟器[EAST托卡马克]: 耦合METIS快速集成建模工具与FBT自由边界平衡代码构建"]},{"i":40147,"as":"研究人员开发了名为ESR2D的二维傅里叶空间全局回旋特征值代码，专门用于求解托卡马克装置中离子温度梯度（ITG）模式的二维回旋特征值问题。该代码在极向傅里叶空间中推导并求解了回旋特征值方程，且未对通行离子或捕获离子作任何简化假设。在包含绝热电子的线性ITG旋风基准测试中，ESR2D代码的计算结果与GENE、NLT和ORB5等回旋初值代码高度吻合。此外，研究还发现系统中同时存在两个ITG模式的环向分支。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":5.0,"t":4.0},"kp":["模拟工具[托卡马克离子温度梯度模式]: ESR2D（二维傅里叶空间全局回旋特征值代码）","数值验证[ESR2D代码]: 在线性ITG Cyclone基准测试中表现良好"]},{"i":40148,"as":"为推动聚变系统数字孪生的发展，‘欧洲聚变理论与高级模拟协调（E-TASC）’计划于2021年启动。该项目利用高保真百亿亿次计算和多保真度模型（包括基于人工智能的代理模型），包含15个理论、模拟、验证与确认（TSVV）项目及5个高级计算中心。这一多团队协作模式在开发聚变装置数字孪生方面取得了实质性科学进展。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":4.0,"t":5.0},"kp":["聚变系统数字孪生[E-TASC倡议]: 包含15个TSVV，利用高保真百亿亿次计算和多保真度模型"]},{"i":40149,"as":"利用MARS-F代码结合REORBIT模块，研究模拟了DIII-D托卡马克中施加三维磁场后，中断后失控电子（RE）撞击中心柱的环向分布相位。通过追踪测试电子在内外三维场下的导向中心漂移轨道，并采用三种不同安全因子轮廓的平衡态，研究发现占主导地位的磁流体动力学不稳定性模式为m/n=2/1、3/2和1/1。施加n=1的共振磁扰动（RMP）能够引发MHD不稳定性与磁扰动之间的锁定现象。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":6.0,"t":4.0},"kp":["失控电子损失模拟[DIII-D施加3D场]: 采用MARS-F代码结合REORBIT模块追踪测试粒子的导向中心漂移轨道"]},{"i":40150,"as":"ITER中子活化系统（NAS）通过气动传输线将样品置于等离子体附近，利用中子活化后测量样品的诱导放射性来重建总中子产额。研究系统量化了NAS中子学模型中的主要不确定性来源，重点关注NAS辐照端几何建模及其对托卡马克中子输运计算的影响，确保总中子产额和第一壁注量测量的可靠性。","scd":{"b":5.0,"i":6.0,"r":5.0,"d":6.0,"t":5.0},"kp":["中子产额测量[ITER中子激活系统]: 利用气动传输线将小样品材料置于等离子体附近进行中子活化，随后通过伽马射线计数站测量感应放射性"]},{"i":40151,"as":"为研究动态等离子体表面相互作用，开发了新型线性等离子体发生器升级版Pilot-PSI（UPP）。该装置首次将高通量等离子体暴露与原位离子束分析（IBA）耦合，可产生电子温度可调、密度高达特定量级的稳态氢等离子体。同时，利用p或He离子束分析材料表层，或同步诱导辐射损伤，实现氢同位素传输、动态滞留及等离子体辐照下缺陷稳定化的同步研究。","scd":{"b":7.0,"i":6.0,"r":7.0,"d":8.0,"t":6.0},"kp":["线性等离子体发生器[高通量等离子体与表面相互作用]: 升级版 Pilot-PSI (UPP)，首次耦合高通量等离子体暴露和操作离子束分析(IBA)"]},{"i":40152,"as":"HL-3托卡马克正在建设一套6MW离子回旋频率范围（ICRF）加热系统，计划于2026年9月投入使用。该系统旨在提供中心离子加热并产生高能粒子，射频范围为25-50MHz，脉冲持续时间最高达5秒。针对氘等离子体，采用氢少数离子和氘二次谐波加热方案（f=33MHz，B0=2.2T）；针对氘-氚等离子体，采用氦-3基频和氚二次谐波方案（f=25MHz，B0=2.5T）。系统射频发生器由4个1.5MW的发射单元组成。","scd":{"b":6.0,"i":6.0,"r":6.0,"d":7.0,"t":6.0},"kp":["ICRF加热系统功率[HL-3托卡马克]: 6 MW","射频范围[ICRF加热系统]: 25-50 MHz","脉冲持续时间[ICRF加热系统]: 最高5 s","可用时间[HL-3托卡马克ICRF系统]: 2026年9月"]},{"i":40153,"as":"TCV托卡马克中观察到了环向模数n=0的轴对称全局阿尔文本征模。这些本征模在多个频率下出现，证实了其由阿尔文连续谱的周期性结构决定的本质特征。线性MHD计算预测了n=0 GAEs的径向分裂现象，该计算结果与近期在亚回旋频率范围内观察到的GAEs径向分裂高度一致。建模分析证实，这些n=0 GAEs主要位于阿尔文连续谱极小值下方的频段。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":6.0,"t":4.0},"kp":["环向模数[全局阿尔文本征模式]: n=0 (轴对称)"]},{"i":40154,"as":"在EAST托卡马克中，共振磁扰动（RMP）被证实能够触发并维持离子温度通道的内部输运垒。通过调整RMP线圈的相位、环向模数和电流，可以主动控制该离子内部输运垒。在保持其他放电设置不变的情况下，仅调整RMP线圈配置即可高重现性地形成输运垒。对比实验结果表明，高环向模数的RMP比低环向模数更有利于离子输运垒的形成。实验与建模结果均证实了强磁扰动在其中的关键作用。","scd":{"b":8.0,"i":5.0,"r":7.0,"d":6.0,"t":7.0},"kp":["控制方法[离子内部输运势垒]: 调整共振磁扰动(RMP)的相位、环向模数和线圈电流","技术效果[EAST托卡马克]: RMP可触发并维持离子温度通道的可持续内部输运势垒"]},{"i":40155,"as":"本研究利用FAR3d回转流体力学代码进行非线性模拟，分析了JET氘-氚（D-T）放电中由快离子引起的扰动及其对高能粒子输运的影响。经验证模拟表明，环向阿尔文本征模（TAEs）和鱼骨模分别由ICRH加速的穿过型氘离子和捕获型氢离子诱发失稳。多重高能粒子模拟揭示了不同高能粒子物种之间存在显著的非线性耦合作用，这种耦合效应甚至在阿尔法粒子占比极低的情况下，依然对其粒子约束产生强烈影响。","scd":{"b":7.0,"i":5.0,"r":6.0,"d":6.0,"t":5.0},"kp":["模拟代码[JET DT放电多重高能粒子输运]: FAR3d回转流体非线性模拟代码"]},{"i":40156,"as":"本研究使用COREDIV代码对JET带有钨偏滤器和铍壁的高电流高功率基准脉冲（含92%氚和8%氢）进行了集成数值模拟。该代码自洽地求解了核心区等离子体与杂质的一维径向输运方程，以及刮削层中的二维多流体输运。模拟属于“半解释性”，即通过调整输运系数以匹配辐射分布、镍浓度、SOL辐射和Zeff等实验数据。在COREDIV模型的假设和现有实验约束条件下，模拟分析了杂质的传输特性和来源。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["燃料组分[JET高功率基线脉冲]: 92%氚 + 8%氢","偏滤器与壁材料[JET-ILW]: 钨偏滤器和铍壁"]},{"i":40157,"as":"在间接驱动惯性约束聚变中，黑腔辐射驱动温度与冲击波速度和内爆速度相关，而辐射驱动对称性是决定热点对称性的关键参数。研究提出一种新方法，通过测量沿两个正交方向重新发射的X射线辐射通量，同时确定胶囊上的辐射温度和P2不对称性。使用高Z替代胶囊解耦了黑腔与内爆胶囊间的相互作用。基于自相似理论给出了不透明度和状态方程对P2不对称性测量的影响。演示实验在神光100kJ激光装置上完成。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["测量方法[间接驱动惯性约束聚变]: 通过测量两个正交方向上的再发射X射线辐射通量，同时确定辐射温度和P2不对称性"]},{"i":40158,"as":"为推进我国磁约束聚变能发展战略，中国确定在ITER上测试氦冷陶瓷增殖剂实验包层模块（CN HCCB TBM）。自2023年2月起，ITER为应对工程与技术挑战，开始开发旨在尽早进入核运行阶段并降低初期部分运行参数的新基准情景。为响应ITER 2024年新基准要求，CN HCCB TBM团队据此开展了进一步的设计优化与工程分析。本文重点阐述了针对该模块更新的热工水力分析等初步工程评估工作，以提升其在反应堆新运行策略下的工程性能与制造可行性。","scd":{"b":7.0,"i":6.0,"r":6.0,"d":7.0,"t":5.0},"kp":["测试包层模块概念[ITER中国]: 氦冷陶瓷增殖剂(TBM)"]},{"i":40159,"as":"","scd":null,"kp":[]},{"i":40160,"as":"针对水性锌离子电池中由水引起的析氢和锌枝晶问题，研究开发了一种基于同源约束策略的机器学习辅助设计范式。该范式采用线性核支持向量回归模型结合留一法交叉验证，筛选出DL-谷氨酸和DL-组氨酸两种具有卓越水结构调节能力的氨基酸衍生添加剂。实验研究表明，这些添加剂能够重构电解液的水分子结构，从而有效提升电池的电化学性能和抑制枝晶生长。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["设计范式[水系锌离子电池添加剂筛选]: 基于同源约束策略的机器学习辅助设计"]},{"i":40161,"as":"自旋轨道矩驱动的自旋霍尔纳米振荡器在纳米级微波设备领域极具应用潜力，降低振荡的阈值电流是实现稳健振荡的关键。研究通过晶体学工程在PtBi合金中显著增强了体自旋霍尔效应。实验提取结果表明，合金的自旋霍尔效率从Pt100.0Bi0.0的0.07大幅提升至Pt94.0Bi6.0的0.24以及Pt91.3Bi8.7的0.19。这种性能的增强主要源于合金中体主导的 exter持性扩展机制。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["核心要求[自旋霍尔纳米振荡器]: 降低阈值电流以获得鲁棒的振荡"]},{"i":40162,"as":"为解决传统化疗药物靶向性差的问题，研究设计了一种肿瘤微环境响应性的细胞膜包被纳米复合材料（ZnO2@MO-D@Mn-CeO2@CM）。该材料以过氧化锌为核心，外层包裹载药介孔有机二氧化硅（乳腺癌模型负载阿霉素，白血病模型负载柔红霉素），介孔由掺锰二氧化铈纳米颗粒门控，最外层覆盖同源细胞膜。该纳米材料能够在肿瘤微环境中实现治疗成分的释放，用于实体瘤和白血病的多模态联合治疗。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["纳米复合材料结构[实体瘤和白血病治疗]: ZnO2核心、载药介孔有机二氧化硅(MO-D)以及细胞膜伪装"]},{"i":40163,"as":"研究通过生物矿化策略合成了一种基于钆-白蛋白纳米结构的T1-T2双模态MRI平台。通过共封装全氟五苯基-15-冠-5醚（PFCE）和光敏剂IR780，构建了诊疗一体化探针IR780@PFCE@Gd-BSA (IPGB)。该探针在1.5T、3.0T和9.4T的临床及临床前MRI系统中均展现出强烈的19F MRI信号和T1-T2造影增强效果，实现了1H/19F多模态成像。此外，该探针还展现出卓越的光动力治疗（PDT）效果。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["纳米结构[T1-T2双模态MRI平台]: 仿生矿化合成的钆-白蛋白纳米结构","共包封装物[多功能治疗诊断平台]: 全氟-15-冠-5-苯基醚(PFCE)和光敏剂IR780"]},{"i":40164,"as":"为解决介电弹性体在低电场下难以获得大驱动应变的问题，研究提出了一种互穿聚合物网络（IPN）策略。该策略将含有动态二硫键的聚氨酯脲弹性体的物理交联与聚乙二醇二甲基丙烯酸酯的共价交联相结合。制得的IPN交联弹性体具有较低的初始杨氏模量（1.05 MPa），易于在小应变下发生形变；并在中等应变时表现出明显的应变硬化现象，从而有效抑制了机电不稳定性。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["交联网络策略[低电场高驱动应变介电弹性体]: 结合动态二硫键物理交联的互穿聚合物网络(IPN)","聚合物基体[互穿聚合物网络]: 含有动态二硫键的聚氨酯-脲弹性体"]},{"i":40165,"as":"针对牙龈卟啉单胞菌传统检测方法灵敏度低、耗时长等问题，研究开发了一种超灵敏的无线侧流免疫分析平台（WLFIAP）。该平台深度集成了荧光纳米DNA步行器与微电子技术。研究合成了一种新型荧光金属有机框架复合材料（PCNP6），其荧光强度比商用PCNs高约16.95倍，且荧光寿命显著延长。结合具有卓越运动动力学和连续性的四足DNA步行器，进一步放大了检测信号，实现了对目标病原体的超灵敏检测。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["检测平台[超灵敏无线侧流免疫分析]: 基于荧光纳米DNA walker与微电子技术深度融合构建的平台","发光材料[超灵敏检测牙龈卟啉单胞菌]: 超亮金属有机骨架荧光纳米材料(PCNs@Coumarin 6)"]},{"i":40166,"as":"针对石墨烯基固体接触离子选择性电极难以规模化制造的瓶颈，研究提出了一种可持续的制造方法。该方法将源自硬木生物炭的衍生物转化为类石墨烯纳米片，制成可打印墨水，并通过高通量丝网印刷技术制备出生物衍生石墨烯固体接触离子选择性电极。通过在印刷电极表面修饰聚氯乙烯（PVC）基离子敏感膜，该电极成功应用于水培溶液中营养物质的监测。","scd":{"b":6.0,"i":4.0,"r":4.0,"d":5.0,"t":5.0},"kp":["原材料[生物衍生石墨烯固态接触离子选择性电极]: 硬木生物炭衍生的石墨烯","制造工艺[规模化生产固态接触电极]: 高通量丝网印刷技术 patterning"]},{"i":40167,"as":"研究结合ZIF-8前驱体的全固态合成与直接受限热解技术，成功将PtFe合金纳米颗粒均匀锚定在氮掺杂碳载体上，制备出PtFe/NC催化剂。该催化剂的Pt负载量仅为1.59 wt%，在酸性氧还原反应中表现出极佳的性能。其半波电位高达0.897V，质量活性达2.34 A mgPt-1（@0.90V，无iR补偿），分别是商业20 wt% Pt/C催化剂（0.14 A mgPt-1）的17倍，展现出巨大的实用潜力。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["合成工艺[低Pt载量且尺寸可控的PtFe合金]: 结合ZIF-8前驱体的全固态合成与直接限制性热解","催化剂形态[酸性氧还原反应]: 氮掺杂碳均匀锚定的PtFe合金纳米颗粒"]},{"i":40168,"as":"针对全固态锂硫电池复杂多相演化机制难以分析的问题，研究设计了一种原位电池，能够在实际工作条件下实时进行硫K边X射线吸收光谱监测。同时，引入了结合主成分分析和约束优化的混合方法，有效解决了光谱峰严重重叠的难题，实现了稳健的定量光谱反卷积。研究结果清楚地揭示了放电过程中的两步反应路径：单质硫直接还原为Li2S2，随后进一步还原为Li2S。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["原位检测方法[全固态锂硫电池多相演化]: 实时硫K边X射线吸收光谱","检测环境[原位同步加速器表征]: 可在实际工作条件下运行的定制原位电池"]},{"i":40169,"as":"为实现碳纤维增强聚合物复合材料的高灵敏结构健康监测，研究通过共价键合和π-π相互作用的协同，在碳纤维/环氧树脂复合材料中构建了苝二酰亚胺/氧化石墨烯（PDI/GO）异质结定制多功能中间相。由GO和PDI通过π-π堆积形成的异质结，借由长程电子离域引发的高效电子转移，展现出机械响应的荧光“关-开”行为。与CF-PDI相比，CF-PDI/GO不仅表现出荧光淬灭特性，同时实现了材料增强和双模式损伤监测。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["异质结构建[碳纤维/环氧树脂复合材料双模式自感知]: 苝二酰亚胺/氧化石墨烯(PDI/GO)异质结定制中间相","界面作用机制[PDI/GO异质结工程化中间相]: 共价键合与π-π相互作用的协同"]},{"i":40170,"as":"为解决钙钛矿太阳能电池界面缺陷钝化与电荷提取难以平衡的挑战，研究提出了一种氟化驱动的多位点锚定策略。该策略使用3-氟-4-(氨基甲基)吡啶铵二碘化物（3-F-AMP）作为 outstanding 钝化材料。3-F-AMP中的氟化作用调节了分子偶极矩并形成近乎平面的几何结构，使得氟原子、质子化氨基和质子化吡啶氮位点能够与钙钛矿表面发生协同相互作用。这种多位点锚定策略有效抑制了缺陷的形成，从而实现了高效且稳定的钙钛矿太阳能电池。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["钝化策略[高效稳定钙钛矿太阳能电池]: 氟化驱动的多位点锚定策略","分子钝化剂[钙钛矿电池界面缺陷抑制]: 3-氟-4-(氨甲基)吡啶铵二碘化物(3-F-AMP)"]},{"i":40171,"as":"针对烧伤创面易感染耐甲氧西林金黄色葡萄球菌（MRSA）等耐药菌引发的难治性感染问题，研究通过介孔普鲁士蓝与聚合物聚六亚甲基双胍（PHMB）共组装，构建了一种多功能纳米抗菌剂。该纳米复合材料不仅对MRSA表现出显著的杀菌功效，还具备调节炎症微环境的能力。得益于介孔普鲁士蓝固有的多酶模拟活性，该纳米复合颗粒能够有效清除炎症因子，从而促进感染烧伤创面的愈合。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["纳米抗菌剂[烧伤创面多重耐药感染治疗]: 介普鲁士蓝与聚己缩胍共组装的纳米复合物(mPB@PHMB)"]},{"i":40172,"as":"针对在非质子电解质中实现电化学CO2加氢还原的挑战，研究提出了一种通过寄生析氧反应利用活性质子的策略。该策略通过电化学环境工程，使阴极能够在无需添加任何质子溶剂的条件下，将CO2还原为甲酸盐。研究采用一种解耦的质子生成方案，实现了质子从阳极室到阴极室受控的体外传输。阴极和阳极分别使用非质子和水基溶剂作为电解液。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["质子源供给策略[非质子介质电化学还原CO2制备甲酸盐]: 利用寄生氧析出反应产生并递送的活性质子"]},{"i":40173,"as":"研究人员通过整合两种具有互补带隙结构的光敏共价有机框架，构建了混合纳米纤维气凝胶（PCNF-A-x）。该设计促进了界面的有效杂化，最小化了电荷转移电阻，并将电荷载流子寿命延长至7.86纳秒。优化后的材料在加铀天然海水中实现了1023.88 mg/g的铀吸附容量，去除率高达99.99%。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["光催化剂[铀吸附]: 具有互补带隙结构的混合共价有机框架纳米纤维气凝胶","瓶颈缺陷[单组分COF]: 光生电子-空穴对快速复合"]},{"i":40174,"as":"研究开发了一种氧化应激响应的纳米复合材料（RDB），通过“鸡尾酒策略”治疗阿尔茨海默病。该系统利用牛血清白蛋白通过gp60受体介导的内吞作用穿透血脑屏障。在高水平过氧化氢的微环境中，RDB响应释放多奈哌齐和RuO2-TPP。其中RuO2-TPP靶向线粒体并中断氧化应激级联反应，进而修复线粒体。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["纳米复合物[阿尔茨海默病治疗]: RuO2-TPP/Don@BSA (RDB)","跨血脑屏障机制[gp60受体介导的胞吞作用]: 利用牛血清白蛋白(BSA)实现跨膜","响应特性[微环境响应]: 氧化应激响应"]},{"i":40175,"as":"研究展示了在简单的二元Ge-Te系统中实现仅选择器存储器（SOM）的操作，该系统无需缓冲层、界面工程或有毒元素。通过系统地调整化学计量比，确定了一个明确的组成窗口，该窗口表现出显著的SOM行为，具有高达约1.5V的极性相关阈值电压偏移。基于脉冲的电学测量揭示了记忆窗口与组成相关的权衡关系。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["仅选择器存储器(SOM)[二元Ge-Te硫族化物系统]: 无需缓冲层、界面工程或有毒元素"]},{"i":40176,"as":"研究评估了在NU-1000多孔框架中引入含碱性基团的有机聚合物（聚甲基丙烯酸甲酯和聚甲基丙烯酸二氨基乙酯）对持久性农药苯线磷光降解的影响。NU-100能将苯线磷光氧化为有毒的苯线磷亚砜，但进一步转化为无毒水解产物的能力有限。杂化材料则通过连续的氧化-水解途径有效促进了这种转化。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["光降解催化剂[持久性农药]: 负载碱性有机聚合物的NU-1000杂化物","农药靶标[光降解对象]: 线灭磷"]},{"i":40177,"as":"研究首次展示了使用完全溶液处理的刮涂碳顶部电极的有机太阳能电池。引入了由溶液处理的铝掺杂氧化锌纳米颗粒薄膜和通过80°C原子层沉积生长的20纳米厚氧化锡层组成的坚固电子传输层架构。该架构有效保护底层有机层免受碳电极处理过程中溶剂的破坏，提供了一种低成本、可回收的金属接触替代方案。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["顶部电极[有机太阳能电池]: 全溶液处理的刮涂碳电极","顶部电极特点[替代传统金属接触]: 低成本且可回收"]},{"i":40178,"as":"研究设计了一种金属离子纳米系统，用于高效装载RNA并靶向递送至巨噬细胞。该系统通过金属离子介导的NF-κB途径有效抑制TNF-α的产生并调节巨噬细胞极化。此外，全氟化碳的掺入赋予了纳米载体储氧能力，从而提高了缺氧环境下的基因递送效率。在小鼠模型中，TNF-α水平显著降低，为肝纤维化治疗提供了有效策略。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["纳米系统[肝纤维化治疗]: 基于金属离子的靶向siRNA递送系统","药理机制[巨噬细胞调节]: 通过金属离子介导的NF-κB通路抑制TNF-α产生并调节巨噬细胞极化"]},{"i":40179,"as":"研究通过形态工程策略构建了由堆叠的超薄纳米片组成的纳米花状Fe-N-C催化剂，具有分级多孔结构。这种独特的结构具有互联的超薄纳米片和丰富的大孔，共同建立了高效的气体传输路径。该设计克服了传统催化剂由于微孔主导限制氧气传输的瓶颈，有效减少了质子交换膜燃料电池中的氧气传输阻力。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["阴极催化剂[质子交换膜燃料电池]: 具有分级孔隙度的纳米花状Fe-N-C","瓶颈缺陷[传统微孔Fe-N-C催化剂]: 显著的氧传输阻力导致氧气难以接触活性位点并加剧电极水淹"]},{"i":40180,"as":"研究系统调查了沉积在平坦和微结构掺杂硅上的超薄介电纳米涂层（二氧化钛、特氟龙、金刚石、氮化硼和氧化铝）。这些纳米涂层不仅能在250纳米至20微米的宽频带上保持或增强发射率，还能对润湿性提供广泛控制。其中，金刚石涂层表面在中红外波段表现出最高的宽带发射率和角度各向同性，实现了兼具高发射率和环境稳定性的表面。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["表面涂层[高发射率硅表面]: 超薄介电纳米涂层(包括二氧化钛、聚四氟乙烯、金刚石、氮化硼和氧化铝)"]},{"i":40181,"as":"研究利用离子喷射沉积生长的MoS2薄膜和剥离的单层MoS2化学电阻器，结合原位微聚焦X射线光电子能谱技术，探究了MoS2检测二氧化氮（NO2）的微观机制。研究揭示了由NO2诱导的电阻变化源于动态电荷重新分布，并阐明了形貌、缺陷和厚度如何影响电荷转移过程，为低功耗化学电阻传感器机制提供了深入理解。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["气敏材料[NO2检测]: MoS2薄膜","生长工艺[薄膜制备]: 离子化射流沉积(IJD)","传感机制[MoS2-NO2相互作用]: 动态电荷重新分布"]},{"i":40182,"as":"研究提出了一种解释振动强耦合（VSC）效应的宏观凝聚理论。通过将分子集合置于光学微腔中，VSC能够改变基态化学反应速率并表现出相变行为。研究发现，由于VSC的多体性质，大多数VSC效应可以通过形成宏观凝聚态来解释，而不仅仅是依赖单激发图像的振动极化子和暗态，从而解释了当集体拉比分裂超过阈值时才产生效应的现象。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":5.0,"t":4.0},"kp":["振动强耦合(VSC)[分子系综置于光学微腔]: 可在无光源(暗态)下修改基态化学反应速率常数并表现出相变行为","效应起始条件[VSC生效阈值]: 仅在集体Rabi劈裂达到特定值时开始"]},{"i":40183,"as":"研究引入了一种可重构的单次光谱方法，实现了对光谱带宽、分辨率和采集速度的完全可编程控制。该方法克服了传统单次光谱系统中光谱带宽、分辨率和采集速度之间固有的不兼容性。通过实现可编程导航，该技术能够以高达86飞米的光谱分辨率捕获完整的瞬态事件，为生物医学诊断和环境监测等领域的快速过程分析提供了关键见解。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":8.0,"t":5.0},"kp":["光谱分辨率[可重构单次光谱]: 86飞米"]},{"i":40184,"as":"","scd":null,"kp":[]},{"i":40185,"as":"","scd":null,"kp":[]},{"i":40186,"as":"","scd":null,"kp":[]},{"i":40187,"as":"","scd":null,"kp":[]},{"i":40188,"as":"研究结合生物正交非经典氨基酸标记、荧光激活细胞分选和宏基因组学，评估了农药多样性对土壤中活跃抗生素抗性基因的影响。结果表明，与未处理对照组相比，低和高农药多样性均显著增加了活跃ARG的丰度。然而，总ARG丰度并未表现出显著变化。研究揭示了农药多样性在驱动农业土壤活跃微生物群落中抗生素抗性增殖方面具有特定的作用机制。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["残留水平[农业土壤含多种农药]: 约60%"]},{"i":40189,"as":"","scd":null,"kp":[]},{"i":40190,"as":"研究揭示了玉米中苯丙氨酸生物合成的关键机制，发现所有七种预苯酸脱水酶（ADTs）均定位于叶绿体质体球。遗传分析证实仅ADT2.2对植物和种子发育不可或缺，其丢失导致种子严重缺乏苯丙氨酸。这种代谢阻断直接降低了tRNA的装载，从而抑制蛋白质翻译。研究还发现苯丙氨酸饥饿不成比例地影响了特定蛋白质的合成，将苯丙氨酸生物合成与翻译稳态联系起来。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["酶活性[玉米ADT2.2]: 对分枝酸和预苯酸表现出高催化活性","亚细胞定位[玉米苯丙氨酸生物合成]: 全部7种分枝酸脱水酶(ADTs)特异性定位在叶绿体质体球中"]},{"i":40191,"as":"","scd":null,"kp":[]},{"i":40192,"as":"","scd":null,"kp":[]},{"i":40193,"as":"苯甲醇广泛存在于种子植物中，是合成植物激素水杨酸的关键前体。然而，植物中负责合成苯甲醇的酶一直未被发现。近期研究综合运用生化和遗传学等方法证实，在矮牵牛花中，两种仅相差三个氨基酸且依赖NADPH的苯甲醛还原酶，负责催化苯甲醇及其下游衍生物（苯甲酸苄酯和水杨酸甲酯）的合成。此外，抑制该酶的表达会显著降低病原体感染后矮牵牛茎部的水杨酸水平。该发现直接证明了苯甲醛还原酶是水杨酸生物合成途径中最后一种未被鉴定的关键酶。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["代谢路径[植物水杨酸生物合成]: 苯甲醇作为中间体苯甲酸苄酯的前体参与依赖苯丙氨酸的水杨酸合成"]},{"i":40194,"as":"","scd":null,"kp":[]},{"i":40195,"as":"","scd":null,"kp":[]},{"i":40196,"as":"","scd":null,"kp":[]},{"i":40197,"as":"基于15,499名英国生物样本库健康参与者的数据，研究人员构建了血浆蛋白质组学预训练模型ProLM。该模型可捕获基线蛋白质表达关系并预测16种常见慢性疾病。经过微调，ProLM的风险评分在预测全部16种疾病时优于年龄与性别模型，并在14种和11种疾病中分别超越了ASCVD方程和35变量临床模型。GDF15等蛋白的表达在临床确诊前15年即发生变化。","scd":{"b":8.0,"i":5.0,"r":8.0,"d":8.0,"t":7.0},"kp":["预训练样本量[血浆蛋白质组学模型ProLM]: 15,499名相对健康的UK Biobank参与者","预测能力[ProLM微调后]: 支持16种常见慢性疾病的预测"]},{"i":40198,"as":"","scd":null,"kp":[]},{"i":40199,"as":"","scd":null,"kp":[]},{"i":40200,"as":"","scd":null,"kp":[]},{"i":40201,"as":"","scd":null,"kp":[]},{"i":40202,"as":"巨型病毒编码了大量未知功能的蛋白质。研究整合交联质谱、定量蛋白质组学、计算工具和冷冻电镜数据，解析了完整墨尔本病毒颗粒的蛋白质架构。研究将88种病毒蛋白分配到不同的病毒粒子亚区室，提出了25种内膜蛋白的拓扑结构，并在冷冻电镜数据中指定了8个衣壳组件。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["研究方法[巨型病毒蛋白质组织与结构解析]: 整合交联质谱、定量蛋白质组学、计算工具和冷冻电镜数据"]},{"i":40203,"as":"受珊瑚群落的多级协作机制启发，研究人员开发了一种核壳结构仿生微胶囊反应器(MY-E@SS)。其多功能仿生外壳可保护工程细菌安全通过胃肠道。到达肠道发炎部位后，细菌感知病理微环境并响应式释放抗炎肽。在雄性炎症性肠病小鼠模型中，该系统展现出优异的生物相容性和靶向治疗效果。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":6.0,"t":6.0},"kp":["微胶囊反应器[IBD治疗工程益生菌仿生]: 核壳结构仿生微胶囊反应器（MY-E@SS）","仿生机制[微胶囊多功能壳层]: 受珊瑚群落防御保护-危险感知-组织修复的多级协同机制启发"]},{"i":40204,"as":"通过体外进化技术，研究人员偶然发现了一种新型核酶连接酶。当RNA底物亲核的2'-羟基旁存在3'-磷酸基时，该核酶能够催化底物自身的2'-羟基攻击其5'-三磷酸基团。这种对3'-磷酸基团的依赖机制与基于蛋白质的RNA修复途径相似，表明核酶催化的3'-磷酸化RNA连接或为原始细胞提供了RNA修复途径。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":6.0},"kp":["底物要求[核酶连接酶催化反应]: RNA底物必须具有邻近核糖的3'末端磷酸基团","催化机制[核酶连接酶]: RNA底物自身的5'-三磷酸基团受到其2'-羟基的亲核攻击"]},{"i":40205,"as":"","scd":null,"kp":[]},{"i":40206,"as":"基于三明治架构开发出全柔性热电发电机(f-TEG)。采用n型Bi2Te2.7Se0.3和p型Bi0.5Sb1.5Te3作为热电活性单元，液态金属为电极。封装使用掺入20wt%氮化铝(AlN)陶瓷纳米颗粒的PDMS复合材料，使其热导率达到0.45 W m-1 K-1。该设备能有效回收人体废热，实现了自供电手势识别功能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["n型热电材料[柔性热电器件]: Bi2Te2.7Se0.3","p型热电材料[柔性热电器件]: Bi0.5Sb1.5Te3","电极材料[柔性热电器件]: 液态金属"]},{"i":40207,"as":"结合表面色素数据集与卫星海洋颜色观测，研究开发了南大洋诊断色素框架，解析1998至2024年间南极春夏两季的浮游植物群落组成。与2015-2024年期间相比，1998-2014年9月海冰范围出现约7%的阶梯式下降。受海冰影响区域的春季硅藻对总叶绿素的贡献增加约10%，而南极洲区域则减少约3%。","scd":{"b":4.0,"i":2.0,"r":7.0,"d":7.0,"t":4.0},"kp":["技术框架[南大洋表面浮游植物群落组成解析]: 诊断色素框架","时间跨度[南大洋浮游植物群落分析]: 1998年至2024年"]},{"i":40208,"as":"通过在自由活动的啮齿动物脊髓表面包裹不穿透神经组织的超薄圆周电极阵列，实现对脊髓信号的记录。深度学习解码器利用与中枢模式发生器节律一致的低频脊髓振荡，实现了R²=0.97的运动意图解码，并以94.4%的准确率分类了八种感觉模式。在急性麻醉猪模型中验证了其跨物种有效性。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":5.0},"kp":["电极阵列[脊髓记录]: 单一超薄圆周电极阵列，贴合脊髓且不穿透神经组织","解码功能[脊髓圆周记录]: 同时解码运动意图、分类感觉输入并区分内脏感觉输入","记录周期[自由活动大鼠短期植入]: 最长可达三天"]},{"i":40209,"as":"为解决从含噪观测数据中发现控制方程的挑战，提出了一种结构化算子学习框架。该框架将方程发现问题重构为受约束的动态推断问题，集成了谱分解、物理引导的稀疏投影和跨视图一致性正则化。通过将动力学分解为尺度解析组件，该框架实现了从混乱数据到物理上可解释的确定性映射。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["技术框架[数据驱动方程发现]: 结构化算子学习框架，将方程发现重构为物理上可解释的确定性映射"]},{"i":40210,"as":"","scd":null,"kp":[]},{"i":40211,"as":"电催化C-N偶联合成尿素的过程中，常利用脲酶催化尿素分解为铵根离子(NH4+)来定量尿素的产量。研究发现，所有四种商业脲酶中均存在NH4+杂质，这会导致尿素浓度出现假阳性结果。即使是含有最低NH4+杂质的脲酶，其产生的假阳性产率也会对催化剂性能评估造成实质性干扰，必须进行比色校正。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["尿素定量方法[电催化尿素合成]: 利用脲酶催化尿素分解为铵离子(NH4+)的比色校正法"]},{"i":40212,"as":"将Cu、Mn、W等金属掺杂剂掺入RuO2中，研究双位点电子转移对析氧反应活性和稳定性的影响。Mn掺杂会加剧Ru-O轨道耦合并建立单向电子转移，导致高压下Ru过氧化并加速性能衰退。相反，W掺杂调节了能带中心以减少轨道重叠，削弱Ru-O共价性并实现双向电子转移，有效提升了催化稳定性。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["双位点电子转移[非铱酸性析氧反应催化剂]: 掺杂金属(如Cu、Mn、W)与Ru形成M-Ru位点介导电荷转移","掺杂元素[RuO2催化剂改性]: Cu、Mn、W","掺杂效应[Mn掺杂]: 强化双位点协同催化活性与稳定性"]},{"i":40213,"as":"研究使用基于蛭石的二维纳米通道探讨了溶解离子对纳米尺度水传输的调节作用。结果表明，强烈水合的离子会显著减慢水传输速度，而弱水合离子则能实现超快渗透。红外光谱分析证实，离子依赖性的氢键网络重构是导致这种水传输行为差异的核心机制。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[受限水传输机制]: 纳米受限环境下的溶解离子通过重塑氢键网络实现对水传输的调制","[传输通道]: 蛭石基二维纳米通道"]},{"i":40214,"as":"研究通过在WO3外延薄膜中施加外延剪切应变，成功使其稳定为具有极性的低对称性三斜晶相结构。这种极性薄膜结构能在极大的厚度和较高温度下持续存在。原子尺度分析表明，氧八面体倾斜模式的改变促使了这种极性相变与对称性降低现象的发生，为氧化物电子学提供了新路径。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[三氧化钨(WO3)薄膜]: 通过外延剪切应变诱导出极性相"]},{"i":40215,"as":"手性反铁磁体Mn3Sn在自旋轨道扭矩(SOT)切换中存在固有机制和焦耳热辅助机制的竞争。通过调节磁性层厚度发现，较厚器件的切换受焦耳热干扰，而减小厚度则能显现出固有的自旋轨道扭矩机制。这有效避免了热失稳问题，为开发具有皮秒级超快动力学的下一代反铁磁存储器提供了关键物理依据。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["[反铁磁存储器件动态响应]: 皮秒级超快动力学特性","[自旋轨道扭矩切换]: 焦耳热导致磁序失稳时，切换时间受限至纳秒或更长"]},{"i":40216,"as":"为克服低温合金的强度-延展性权衡限制，研究在超细晶NiCoCr基多主元合金中设计了分层纳米排序(HNO)架构。该架构由无关联σ相弥散体(~70nm)、双峰共格L12析出相(~5和26nm)及局部化学有序区(~0.7nm)组成。该多尺度微观结构成功使合金在极低温下同时实现2.0GPa以上的超高屈服强度与优异的均匀延伸率。","scd":{"b":9.0,"i":4.0,"r":8.0,"d":9.0,"t":8.0},"kp":["屈服强度[低温合金]: ≥2.0 GPa","[低温合金材料]: 超细晶NiCoCr基多主元合金","[微观结构设计]: 结合增材制造与定制后处理，基于Eshelby夹杂理论构建分层纳米有序(HNO)架构"]},{"i":40217,"as":"研究利用胶束嵌入机制，成功在金纳米棒和三角纳米棱镜等各向异性等离子体纳米颗粒表面实现了导电聚合物(聚吡咯，PPy)斑点的位点选择性功能化。聚吡咯成核位点的选择性由纳米颗粒局部曲率和表面活性剂(SDS)浓度共同决定，并能通过HCl掺杂有效控制聚吡咯与金界面的电荷转移。","scd":{"b":7.0,"i":3.0,"r":8.0,"d":5.0,"t":8.0},"kp":["[等离子体纳米颗粒表面功能化]: 利用胶束嵌入决定聚吡咯(PPy)在金属纳米颗粒表面的成核位点，实现位点选择性导电聚合物贴片定位"]},{"i":40218,"as":"研究基于中性原子阵列可编程量子模拟器，利用投影对称群框架分析了红宝石晶格上Z2量子自旋液体(QSL)的对称性分数化模式。通过系统比较所有可能平均场假设的静态结构因子与密度矩阵重整化群计算结果，精确识别出微观层面实现的Z2量子自旋液体候选态，并详细分析了动态结构因子供未来实验参考。","scd":{"b":9.0,"i":2.0,"r":9.0,"d":6.0,"t":8.0},"kp":["[量子物质模拟]: 基于中性原子阵列的可编程量子模拟器","[量子自旋液体]: 采用投影对称群框架描述红宝石晶格上里德堡阵列合成的拓扑有序Z2量子自旋液体"]},{"i":40219,"as":"研究开发了一种基于(Bi,Sb)2Se3材料的超高柔性光电刺激器(OES)。该材料独特的平行一维链晶体结构兼顾了优异的柔性与光电载流子传输效率。该刺激器在仅0.55 μW cm−2的极弱近红外光强下即可实现稳健的光电转换，能够有效将组织衰减的微弱光转化为电信号，为无创心脏重塑等生物电子医疗提供了新方案。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":7.0,"t":8.0},"kp":["[超柔性光电刺激器]: 能够将组织衰减后的微弱光信号高效转化为电刺激信号"]},{"i":40220,"as":"结合聚焦离子束与原位球差校正透射电镜及DFT计算，研究揭示了二维Bi2O2Se纳米器件各向异性离子迁移的原子机制。由于O2-和Se2-离子在面内与面外的迁移势垒存在显著差异，导致两种不同取向的器件表现出截然相反的电阻开关行为。该发现为理解晶体各向异性控制二维忆阻器中的离子迁移提供了直接证据。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":6.0,"t":8.0},"kp":["[Bi2O2Se纳米器件离子迁移]: 表现出由晶体学各向异性主导的平面内与平面外截然不同的电学行为及电阻开关特性"]},{"i":40221,"as":"为克服微观结构表征中空间分辨率、采样区域与通量间的技术矛盾，研究提出了一种高分辨率、高通量的局部变形映射(LDM)技术。实验利用纳米模具压制微结构表面形成纳米柱阵列，通过分析塑性响应实现材料扩散映射。该技术能在宏观面积(约cm²)上实现约10 nm²的分辨率并生成海量数据，实现了对微结构变形敏感的化学成分解析。","scd":{"b":7.0,"i":3.0,"r":8.0,"d":6.0,"t":8.0},"kp":["[局部变形映射(LDM)表征技术]: 兼顾高空间分辨率、大采样面积和高通量，通过纳米模具压印微结构确定塑性变形中局部原子的扩散路径"]},{"i":40222,"as":"研究利用同步加速器低温软X射线断层扫描和光谱显微技术，在亚细胞分辨率下直观观察了细菌与缺钙羟基磷灰石(CDHA)纳米柱基质的相互作用。CDHA不仅通过纳米拓扑结构引发细菌机械性膜破裂和细胞质渗出，还与周围环境进行离子交换产生化学杀伤。这种机械与化学协同的接触式杀菌机制为同时支持骨再生和抗感染的合成骨移植材料提供了新策略。","scd":{"b":6.0,"i":4.0,"r":8.0,"d":7.0,"t":8.0},"kp":["[纳米结构骨移植材料]: 由α-磷酸三钙合成的缺钙羟基磷灰石(CDHA)纳米柱","[杀菌机制]: 对革兰氏阳性菌(枯草芽孢杆菌)具有机械损伤与环境离子交换化学作用相协同的接触式杀灭活性"]},{"i":40223,"as":"研究在氮化镓光声子混合集成平台上，基于布里渊散射的斯托克斯与反斯托克斯过程，首次实现了单向行波声子波导参量放大器。该器件的问世填补了声子集成电路(PnICs)中有源信号放大组件的空白，为经典与量子领域的纳米级声子控制、增强声子相互作用强度以及高级信号处理开辟了全新途径。","scd":{"b":8.0,"i":3.0,"r":9.0,"d":6.0,"t":8.0},"kp":["[声子集成电路]: 行波声子波导作为先进信号处理的关键有源组件","[信号处理]: 依赖集成行波声子参量放大器"]},{"i":40224,"as":"原位同步辐射X射线衍射表明，在1.5×10³ A cm⁻²的稳态直流电流下，六方η-Cu6Sn5相能够在原本应发生η→η′相变的热处理条件下保持稳定。电流通过各向异性弹性形变（c轴膨胀约1.3%，基底面收缩约0.8%）改变了晶格受力状态。这证明稳态电流不仅引发电迁移损伤，还可作为一种稳定金属晶体热力学相的调控场。","scd":{"b":8.0,"i":3.0,"r":9.0,"d":9.0,"t":8.0},"kp":["电流密度[稳态载流金属晶体]: 1.5×10^3 A cm^-2","相稳定性[稳态电流作用下]: 保留各向异性容纳电流的六边形η-Cu6Sn5相","[稳态电流]: 偏置晶格稳定性并抑制η → η′相变"]},{"i":40225,"as":"研究构建了由手性Co1/3TaS2与非手性范德华铁磁体Fe3GeTe2组成的全范德华异质结构。该结构界面展现出两种由界面手性诱导的非常规自旋轨道扭矩，成功在无需外加磁场的情况下，以极低电流密度（约10⁶ A cm⁻²）实现了垂直磁化翻转。这验证了界面手性在突破传统手性块材限制、实现低能耗自旋电子器件方面的巨大潜力。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":6.0,"t":8.0},"kp":["[全范德华异质结构]: 实现无磁场条件下的高能效界面手性诱导开关"]},{"i":40226,"as":"为解决光催化中光生载流子极易复合的难题，研究采用拓扑晶格收缩策略成功合成了具有高孔隙率和极低缺陷密度的闪锌矿ZnO多孔单晶。原位电镜证实，S/O原子沿{222}晶面通道的优先迁移引发外延成核，界面应变则促使空位聚结为互联纳米孔。该结构优化了电荷传输与质量扩散，显著抑制了光生载流子复合，大幅提升了甲烷光氧化效率。","scd":{"b":8.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["[多孔单晶ZnO整体材料]: 具有高结晶度、高相纯度和高孔隙率","[拓扑晶格收缩策略]: 原位合成同时优化光吸收、电荷传输和质量扩散"]},{"i":40227,"as":"为解决全波电磁仿真训练数据获取成本高的问题，研究提出基于元电路嵌入表面(MCES)的数据驱动逆向电磁设计框架。通过将固定的拓扑结构与可由集总元件灵活实现的元电路结合，设计重点从计算昂贵的全波仿真转向电路级建模。该框架仅用普通笔记本电脑即可生成超600万样本数据，极大拓展了人工智能在频率和振幅等多维电磁设计中的应用能力。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["架构设计[大规模数据驱动逆电磁设计]: 元电路嵌入表面(MCES)框架，包含固定结构拓扑和可通过集总组件实现的柔性元电路"]},{"i":40228,"as":"针对弹热蓄冷器中相变不均匀导致效率受限的问题，研究受针叶树结构启发，设计了一种多层弹热蓄冷器。该设计通过在三层结构中改变管道数量以匹配材料固有的相变应力分布，有效缓解了局部应力过度集中和相变不完全现象。在同等商业级NiTi材料下，该蓄冷器实现了45.5K的无负载温差，较均匀基准提升了12.4%，并成功应用于往复式弹冷水冷机。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":4.0},"kp":["弹热蓄热体[针叶树形多层结构]: 几何形状与可变相变应力相匹配以克服不均匀相变"]},{"i":40229,"as":"通过中子衍射对超大体积高纯铈样品在85-295K及最高8GPa条件下的结构演化进行追踪，发现铈的高压晶体结构高度依赖于压缩路径。在室温下缓慢压缩（0.25 GPa hr⁻¹）会形成正交晶相，这打破了传统认为固体在高压下仅由热力学平衡决定结构的认知。实验直接证明了微观结构遗传和动力学路径在材料高压相变选择中具有决定性影响。","scd":{"b":6.0,"i":1.0,"r":5.0,"d":5.0,"t":3.0},"kp":["样品体积[高压条件下铈的中子衍射]: ~60 mm3"]},{"i":40230,"as":"","scd":null,"kp":[]},{"i":40231,"as":"","scd":null,"kp":[]},{"i":40232,"as":"","scd":null,"kp":[]},{"i":40233,"as":"研究揭示了二维界面流变学在控制界面聚合（制备聚酰胺脱除盐水的标准方法）动力学中的关键作用。通过利用光反应性两亲分子精确调节水-油界面的界面流变学，实现了对界面聚合过程中图案化流体不稳定性的控制，进而调控了膜表面形貌。最终制备出的聚酰胺膜展现出宏观形貌特征。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["[聚酰胺脱盐膜]: 界面流变学（二维流变）主导界面聚合动力学并决定膜物理结构"]},{"i":40234,"as":"为解决水系锌空气电池中锌负极存在的枝晶生长、析氢反应、腐蚀等问题，研究在电解液中引入四氟硼酸铟作为功能性添加剂。结果表明，铟的引入有效调节了锌的成核行为，促进锌均匀沉积，显著抑制了枝晶形成。此外，与铟形成的动态合金界面参与了可逆的沉积/溶解过程，从而增强了锌负极的界面稳定性，实现了超高可逆的锌-空气电池。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[锌阳极]: In(BF4)3添加剂原位构建Zn-In合金层以抑制枝晶生长、析氢反应、腐蚀和体积变形"]},{"i":40235,"as":"研究使用双功能GPI锚定物结合自旋标记脂质和功率饱和电子顺磁共振（EPR）分析技术，量化了探针在POPC和DPPC脂质体中对膜束缚和可溶自旋弛豫剂的可达性。研究揭示了糖基磷脂酰肌醇（GPI）和GPI锚定蛋白在脂质双层中具有独特的、相依赖性的界面构象和方向。","scd":{"b":6.0,"i":1.0,"r":5.0,"d":6.0,"t":4.0},"kp":["[脂质双层中GPI及GPI锚定蛋白]: 展现出独特的、相位依赖性的方向特征"]},{"i":40236,"as":"研究提出了一种利用草酸铁光催化实现未活化酮与未活化烯烃直接分子间还原偶联的策略。该催化平台通过内球还原途径将酮转化为羟自由基，有效克服了极性不匹配的不利影响，使其能够与烯烃发生反应，成功实现了Csp3-Csp3键的构建。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[酮和烯烃分子间还原偶联]: 草酸铁光催化实现Csp3-Csp3键构建"]},{"i":40237,"as":"研究利用交联自旋标记电子自旋共振技术探究了淀粉样低聚物的结构。发现在洗涤剂胶束中，淀粉样圆柱蛋白K11V的低聚物状态从六聚体增加到了八聚体。这揭示了K11V多肽具有类似洗涤剂的毒性机制，即八聚体结构（由Alphafold模拟证实为β桶结构，利用洗涤剂分子的无支链疏水尾部稳定孔隙）会从生物膜中提取脂质。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":5.0},"kp":["[淀粉样蛋白圆柱蛋白K11V]: 在去污剂胶束中由六聚体增加为八聚体","[淀粉样蛋白寡聚体]: 表现出类似去污剂的毒性机制"]},{"i":40238,"as":"为实现对肿瘤光疗预后中性粒细胞募集的实时、无串扰监测，研究提出了“时空异步”双模态探针设计策略，开发了顺序激活的荧光/光声（FL/PA）探针HD-LN。该探针首先被肿瘤高表达的亮氨酸氨基肽酶（LAP）激活，引发荧光信号开启，并恢复光声信号，从而实时准确地监测光疗后的中性粒细胞募集过程。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["探针设计策略[病理过程中多生物标志物监测]: 时空异步双模态","[光疗预后中性粒细胞募集]: 实时准确且无串扰的非侵入性监测"]},{"i":40239,"as":"结构电池旨在将能量存储与承重功能整合到单一材料系统中，为轻量化电气化提供新范式。该文章明确了将结构电池从实验室可行性推向实际部署系统所需的科学与工程发展路线图。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[结构电池部署]: 将能量存储与承载功能合并为单一材料系统的科学和工程路线图"]},{"i":40240,"as":"为解决硅负极在锂离子电池中无控体积膨胀导致的严重机械损伤问题，研究引入了一种具有机械互锁交联的聚丙烯酸粘合剂。该设计通过拓扑驱动的分子运动均匀耗散电极内的应力，在压延和循环过程中保持了表面孔隙率和电极完整性，在高电极密度下实现了稳定的电池运行和快充性能的提升。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["粘结剂[硅负极体系]: 具有机械互锁交联的聚丙烯酸","[电极应力耗散]: 通过拓扑驱动的分子运动均匀分散应力，保持压延和循环过程中的表面孔隙率与电极完整性"]},{"i":40241,"as":"对探究OR7A10 GPCR工程化改造以增强CAR-NK细胞疗法治疗实体瘤疗效的相关文章进行勘误。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[实体瘤治疗技术]: OR7A10 GPCR工程化改造增强CAR-NK细胞疗法"]},{"i":40242,"as":"被称为龙脑香科的热带巨树，其水分运输系统已经进化出克服重力效应和抵抗水分胁迫的能力。研究表明，无论是高大的树木还是较小的树木，都同样容易受到干旱的严重影响。","scd":{"b":2.0,"i":2.0,"r":4.0,"d":3.0,"t":3.0},"kp":["水传输系统[热带龙脑香科巨树]: 演化出抵抗重力并抵御水分胁迫的机制"]},{"i":40243,"as":"","scd":null,"kp":[]},{"i":40244,"as":"","scd":null,"kp":[]},{"i":40245,"as":"为解决钙钛矿-有机串联太阳能电池中宽带隙混合卤化物钙钛矿存在的卤化物混合不均和光致卤化物偏析问题，研究在钙钛矿前驱体溶液中引入了光可转化添加剂TDB。在结晶过程中，TDB通过抑制富溴相的快速沉淀加速卤化物混合，改善初始均匀性；在光照下，TDB转化为新物种以稳定混合卤化物相。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["光转换稳定剂[宽带隙钙钛矿前驱体溶液]: 4-[3-(三氟甲基)-3H-双吖丙啶-3-基]苄胺 (TDB)","[宽带隙混合卤化物钙钛矿]: 解决高溴含量导致的初始卤化物混合不均和光致卤化物分离问题"]},{"i":40246,"as":"研究利用机器学习加速的晶体结构预测方法，在250 GPa高压下对La-Sc-H系统进行了广泛搜索，确认了计量比为La2ScH36的晶体结构与观察到的次生相一致。第一性原理计算表明，La2ScH36是潜在的室温超导体，其超导临界温度Tc为369-412 K；考虑结构稳定性，提出次生相采用缺氢的La2ScH36-x构型。","scd":{"b":9.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["压力[La-Sc-H系统晶体结构预测]: 250 GPa","次生相结构[高压La-Sc-H系统]: Fm3¯m La2ScH36"]},{"i":40247,"as":"","scd":null,"kp":[]},{"i":40248,"as":"","scd":null,"kp":[]},{"i":40249,"as":"探讨极端工况下固态钠金属电池中原位生成均匀界面相的技术，旨在实现无枝晶生长与性能稳定。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":4.0,"t":5.0},"kp":["[固态钠金属电池极端工况]: 原位生成均匀界面相以抑制枝晶生长并保持性能稳定"]},{"i":40250,"as":"对利用室温等离子印刷技术制备高性能金属氧化物电子器件的研究论文进行作者更正说明。","scd":{"b":4.0,"i":3.0,"r":3.0,"d":2.0,"t":3.0},"kp":["[器件制备]: 室温等离子印刷技术制备高性能金属氧化物电子器件"]},{"i":40251,"as":"对基于网状化学原理对晶体框架内局部限域进行精确编程以实现特定功能的研究内容进行勘误。","scd":{"b":4.0,"i":3.0,"r":3.0,"d":2.0,"t":3.0},"kp":["[材料设计原理]: 基于网状化学原理对晶体框架内局部限域进行精确编程"]},{"i":40252,"as":"研究通过设计由两种化学性质不同的铁磁体（CoB和CoFeB）构成的合成反铁磁体，利用外磁场和层间交换对子晶格的不对称作用作为有效场，在合成反铁磁体中发现了非常规斯格明子。在不同的磁场机制下，分别产生了常规极性斯格明子和反极性斯格明子。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["合成反铁磁体[非常规斯格明子工程]: 由化学性质不同的CoB和CoFeB两种铁磁体构成","[纳米级信息载体]: 具有拓扑保护特性的自旋纹理"]},{"i":40253,"as":"天文学家在太阳系外发现了被称为赤藓酮糖的“真正的糖”分子。该分子含有四个碳原子，是目前在太空中探测到的最复杂的糖类分子，这一发现为揭示生命的起源提供了重要线索。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["原子数[太阳系外发现的最复杂真正的糖分子]: 4个碳原子"]},{"i":40254,"as":"基于嫦娥六号（CE6）从月球背面采集的样本地球化学数据，研究对比了月球正面与背面的岩性差异。发现CE6斜长岩富含镁，且其镁铁质岩套样本的钾、稀土元素和磷（KREEP）含量较低。通过系统对比月球岩浆洋（LMO）不同产物层，揭示了月球远近不对称性的形成起源。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":8.0,"t":8.0},"kp":["岩石成分[嫦娥六号月背样品斜长岩]: 比正面样品更具镁质","成分特征[嫦娥六号月背样品Mg套样品]: 具有更低的钾、稀土元素和磷 (KREEP) 含量"]},{"i":40255,"as":"为解决有机分子电化学氧化脱氢（ODH）反应速率慢的问题，研究通过选择性浸出NiV层状双氢氧化物中的钒离子，制备出富含金属空位的Ni(OH)2。实验和计算表明，催化剂中的金属空位提高了Ni-O基序中氧的氧化还原活性，加速了有机分子的亲核ODH过程，并成功实现了生物质衍生物的氧化脱氢。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["催化剂[醇/醛和伯胺电化学氧化脱氢]: 富含金属空位的氢氧化镍 (VM-Ni(OH)2)","[催化剂制备工艺]: NiV-层状双氢氧化物中的钒离子选择性浸出"]},{"i":40256,"as":"为实现对机械互锁超分子体系复杂拓扑结构的精确控制，研究采用调节配位角度的方法。通过设计两种具有不同咔唑-吡啶连接角度的配体，并结合特定的结构单元，成功合成了雪花形折叠组件、818结和闭合三节链等四种独特拓扑结构。单晶X射线衍射分析证实了配体角度决定了产物的几何构型。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":4.0,"t":4.0},"kp":["合成策略[复杂拓扑结构互锁分子]: 调节配体的咔唑-吡啶连接角度","配体连接角度[配体L1和L2]: 存在差异化设计","合成结构[配位驱动分子组装]: 分子镊子等多种独特拓扑结构"]},{"i":40257,"as":"锂硫电池具有高能量密度，但受限于硫氧化还原动力学缓慢和多硫化物穿梭效应。电催化是加速多硫化物转化和改善电池性能的有效策略。其中，金属-氮-碳催化剂表现出显著的催化潜力。研究表明，催化剂的配位环境及氮物种类型（如吡啶氮或吡咯氮）会深刻影响其催化活性。研究团队提出了一种调节Fe-N-C催化剂中初级壳层氮的方法，旨在深入揭示配体结构与硫氧化还原机制之间的关系。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":4.0},"kp":["催化剂[多硫化物转化]: 金属-氮-碳 (Fe-N-C)","限制因素[锂硫电池性能提升]: 硫氧化还原动力学缓慢及多硫化物穿梭效应","优化策略[Fe-N-C电催化]: 调节初级壳层氮以改善配位环境"]},{"i":40258,"as":"生物活性分子中杂原子的种类能显著影响其理化与生物学性质。为了寻找新的治疗机会，研究团队开发了一种直接骨架编辑策略，可通过简单的一锅法两步反应，将易得的氧杂环丁烷转化为氮杂环丁烷。该转化利用芳香胺和脂肪胺，在路易斯酸介导下发生分子间氨解，随后发生分子内Mitsunobu型脱水环化构建氮杂环丁烷环。这种非氧化还原骨架编辑平台具有广泛的底物范围和优异的官能团兼容性。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":5.0,"t":4.0},"kp":["合成工艺[氧杂环丁烷转化为氮杂环丁烷]: 两步一锅法直接骨架编辑","反应物范围[直接骨架编辑]: 广泛的芳香族和脂肪族胺类"]},{"i":40259,"as":"有机硼酸酯是多组分构建化学键的多功能平台。研究团队提出了一种模块化且具有高非对映选择性的合成方案，实现了直接胺化诱导的烯基硼酸酯络合物的1,2-迁移，以获取无保护的β-氨基硼酸酯。该反应使用商业化胺化试剂二苯基膦酰羟胺（DPPH），通过快速形成丙啶𬭩离子并发生1,2-迁移进行。结合原位红外光谱和密度泛函理论的研究揭示了该反应的机理。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":5.0,"t":4.0},"kp":["合成工艺[β-氨基硼酸酯模块化合成]: 亲电胺化诱导的1,2-硼酸酯迁移","非对映选择性[1,2-迁移反应]: 极高","产物特性[烯基硼酸酯络合物胺化]: 无保护β-氨基硼酸酯"]},{"i":40260,"as":"研究人员正在通过重写DNA和染色质上的化学标签来调节基因的表达。这种表观遗传编辑技术无需改变底层DNA序列，即可实现对目标基因表达的精确上调或下调。这为针对各种遗传疾病和生理机制的干预提供了一种全新的途径。","scd":{"b":4.0,"i":2.0,"r":3.0,"d":2.0,"t":3.0},"kp":["编辑机制[表观遗传编辑]: 重写DNA和染色质上的化学标签","应用目标[表观遗传编辑]: 调控基因表达"]},{"i":40261,"as":"手性有机氯化物是合成与药物化学中备受青睐的基序。研究团队开发了一种结合有机催化和生物催化的级联反应，可将易得的醛转化为对映体富集的β-氯胺。在接近中性的条件下，该方法以高达88%的产率和大于99:1的对映体比率获得多种β-氯胺。将pH值提升至9.5时，同一系统可直接生成手性氮丙啶，实现了通过pH值调控单一平台获取两类高价值产物。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":7.0,"t":4.0},"kp":["催化系统[手性β-氯胺和氮丙啶合成]: 有机催化与生物催化级联集成","产率[手性β-氯胺合成]: 最高达88%","反应条件[生物催化级联]: 近中性条件优化"]},{"i":40262,"as":"在铜电极上的二氧化碳电化学还原反应中，产物形成机理一直存在未解之谜。研究提出一个机理框架，指出铜表面存在位点异质性：OC-CO偶联主要发生在具有强一氧化碳亲和力的高活性“少数位点”上，而大部分铜表面位点相对惰性。分子抑制剂的结构与有效性之间的相关性表明，这些高活性的CuCO位点极可能位于高曲率的纳米结构上。该框架阐明了CO覆盖度与反应级数之间的矛盾。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":6.0,"t":4.0},"kp":["活性位点[铜表面CO2电化学还原]: 具有位点异质性的少数位点","反应机制[C2+产物形成]: OC-CO耦合优先在特定少数位点发生"]},{"i":40263,"as":"能够将机械力转化为光学信号的力致变色基团在聚合物损伤检测中极具价值。研究团队通过9-π-延伸蒽的[4 + 2]光二聚反应，制备出一种新型光学力探针。该探针在200°C以上具有优异的热稳定性和光化学稳健性。在低添加量（≤5 wt%）下，该探针成功应用于商用聚甲基丙烯酸甲酯、聚苯乙烯、热塑性聚氨酯和聚乙烯的共混物中。功能化后的热塑性聚氨酯在经历熔融加工后仍能实现机械化学激活。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":6.0,"t":4.0},"kp":["热稳定性[蒽[4+2]光电二聚体力学探针]: 大于200°C","制备方法[高发射率9-π延伸蒽]: [4+2]光二聚化反应","材料特性[光学力探针]: 具有优异的光化学鲁棒性"]},{"i":40264,"as":"Li6.5La3Zr1.5Ta0.5O12(LLZTO)石榴石型材料是全固态锂电池的有望电解质，但面临烧结和晶界问题的挑战。研究团队通过添加1.0 wt%的YSZ进行钇的过饱和掺杂，合成了LLYZTO。在退火过程中，晶界处形成了La-Y-O(LYO)纳米级中间相。这种材料纳米工程方法提升了压痕断裂韧性，增加了临界电流密度并提高了本体离子电导率，同时保持了低电子电导率。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":8.0,"t":4.0},"kp":["掺杂工艺[石榴石电解质克服烧结与晶界限制]: 钇(Y)过饱和掺杂","掺杂剂用量[钇掺杂LLYZTO合成]: 1.0 wt% 的 (Y2O3)0.08(ZrO2)0.92 (YSZ)","掺杂后化学式[钇过饱和掺杂]: Li6.72La3.00Y0.22Zr1.28Ta0.50O12 (LLYZTO)"]},{"i":40265,"as":"锌基电池具备提供长时间储能的潜力，但传统锌电极在充放电循环过程中容易发生退化。为此，研究人员开发了一种新型流动锌浆液电池。该技术将锌纳米颗粒分散在导电网络中，并使用特定配体来稳定浆液。这种锌浆液实现了可逆的Zn/Zn2+转化，从而保障了电池的持久稳定运行。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":5.0,"t":4.0},"kp":["电极结构[长时流动储能锌电池]: 锌纳米粒子分散于导电网络中的锌浆","稳定机制[锌浆流动电池]: 使用配体稳定锌浆","电化学特性[配体稳定的锌浆]: 可逆的 Zn/Zn2+ 转化"]},{"i":40266,"as":"宽带隙黄铜矿Cu2ZnSnS4(CZTS)是串联光伏电池的潜在顶部电池材料，但受限于高开路电压损耗。这种损耗主要源于设计的全局组分与早期结晶时形成的局部化学环境不匹配，元素扩散诱发了第二相和有害缺陷。研究提出了一种缺陷调控策略，能够稳定局部化学环境并抑制扩散诱导的第二相，从而维持理想的结晶路径。该方法促进了良性缺陷的形成，减少有害缺陷，使CZTS太阳能电池的开路电压达到847 mV。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["开路电压[宽带隙CZTS太阳能电池早期局部化学调节]: 847 mV","性能瓶颈[宽带隙Cu2ZnSnS4]: 存在严重的开路电压损耗，主要由设计的全局成分与早期结晶形成的局部化学不匹配引起","[早期结晶过程]: 元素扩散诱导二次相和有害缺陷的产生"]},{"i":40267,"as":"研究LiFSI与氟代碳酸乙烯酯电解质体系中，浓度变化对固体电解质界面（SEI）特性的影响机制。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["固体电解质界面特性[LiFSI与氟代碳酸乙烯酯电解质体系]: 浓度变化对其特性的影响机制"]},{"i":40268,"as":"利用机器学习模型分析并预测高镍氧化物电池阴极材料的热失控指标，助力电池安全性能评估。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["热失控指标[高镍氧化物阴极]: 利用机器学习模型进行定量分析和预测"]},{"i":40269,"as":"采用数据驱动方法深入分析高维钠电池电解质体系，揭示影响离子电导率的关键化学因素。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[离子电导率]: 采用数据驱动方法揭示影响高维钠电池电解质体系离子电导率的关键化学因素"]},{"i":40270,"as":"开发离域π电子平面化共轭配体，解决全蓝光钙钛矿发光二极管的发光效率与稳定性问题。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["配体材料[全蓝光钙钛矿发光二极管]: 离域π电子平面化共轭配体"]},{"i":40271,"as":"提出一种瞬态热处理技术，对空气降解的钠离子电池层状氧化物阴极进行非平衡态恢复再生。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":4.0,"t":5.0},"kp":["[阴极恢复]: 瞬态热处理技术对空气降解的钠离子电池层状氧化物阴极进行非平衡态恢复再生"]},{"i":40272,"as":"将化学或光输入转化为机械响应在合成组装体中具有挑战性。研究团队开发了含有刺激响应可断裂聚碳酸酯双分子层的刚性聚合物囊泡。在化学或光触发下，该囊泡能够发生单向伸长、内陷和解组装等可编程的形态变化。机理上，化学能的局部耗散在囊泡膜上建立了反应梯度。疏水嵌段被触发断裂后转化为较小的分子，从而引发囊泡的机械变形。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["形变响应机制[刚性聚合物囊泡]: 拥有刺激可裂解的聚碳酸酯双层","机械形变特征[化学或光触发]: 可发生单向伸长、内陷和分解等程序化形状转变"]},{"i":40273,"as":"主要针对四价镨量子位中利用晶体场增加中间耦合及减少退相干的研究内容进行官方更正说明。","scd":null,"kp":["退相干特性[四价镨量子位]: 增加晶体场驱动中间耦合并最大限度地减少退相干"]},{"i":40274,"as":"传统染料敏化光电合成电池需要光敏剂和催化剂配合。在这项研究中，一种同时具备光吸收和燃料生成能力的单组分光活性分子催化剂[Cp*Ir(4,4'-Y2-bpy)Cl][Cl]被锚定在介孔锡掺杂氧化铟(ITO)电极上。该催化剂无需额外的光敏剂或牺牲还原剂，即可在水中实现光电化学析氢。光谱电化学表明，其遵循向ITO注入电荷的单位点析氢机制，这与溶液中观察到的双金属机制形成对比。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["催化剂[光电化学H2析出]: [Cp*Ir(4,4'-Y2-bpy)Cl][Cl]单组分分子光活性催化剂","光阳极[介孔锡掺杂氧化铟]: 具有光吸收和燃料生成双重功能的催化剂锚定基底","[光电化学H2析出]: 无需额外染料敏化即可在水中实现析氢"]},{"i":40275,"as":"基于有机羰基电极材料的锂有机电池具有可持续性，但面临材料在电解液中严重溶解的挑战。传统策略多关注调节静态的溶剂-电极材料相互作用。研究团队提出了一种动态溶剂化结构调控策略。在传统电解液中，有机羰基电极材料会在动态电化学过程中取代阴离子参与溶剂化，从而加剧溶解和降解。该新策略通过调节动态溶剂化结构，抑制了材料在动态过程中的溶解，实现了长寿命的锂有机电池。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["核心挑战[锂有机电池有机羰基电极材料]: 在电解质中存在高溶解度问题","[动态溶剂化结构调节]: 可调控有机羰基电极材料溶解行为以实现长寿命电池"]},{"i":40276,"as":"","scd":null,"kp":[]},{"i":40277,"as":"水微滴可作为特殊的反应容器，其气-水界面处的超强电场能产生活性自由基和水合电子，从而诱发宏观水溶液中无法发生的化学反应。研究证实，水微滴能在室温且无催化剂的条件下，诱导二硫化碳(CS2)迅速聚合成聚碳硫化物固体。表征结果显示，该聚合物由高度交联的共轭碳碳双键和碳硫网络组成，并掺入了氢元素。机理研究证实该反应涉及电子转移介导的自由基过程。","scd":{"b":9.0,"i":2.0,"r":9.0,"d":7.0,"t":7.0},"kp":["反应条件[二硫化碳聚合]: 水微滴中室温自发进行","聚合物产物[二硫化碳]: 聚（碳硫化物）固体","反应驱动力[空气-水界面]: 超高电场产生活性自由基和水合电子"]},{"i":40278,"as":"探讨高比例可再生能源电力系统的频率安全理论、评估方法及其实际应用，保障电网稳定。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[频率安全]: 理论、评估方法及应用保障高渗透率可再生能源综合电力系统电网稳定"]},{"i":40279,"as":"研究在多重不确定性条件下，流域水风光综合能源系统面向提升系统弹性的随机短期调度策略。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":[]},{"i":40280,"as":"浮游植物细胞向水中分泌的各类化学物质会形成局部微环境，即“藻圈”。尽管已知藻圈介导着浮游植物与细菌间的相互作用，但单细胞周围的化学梯度尚未被直接测量。研究团队利用拉曼微光谱技术，对半径在特定尺寸范围内的不同物种的单个浮游植物细胞周围的岩藻黄素代谢物浓度分布进行了微米尺度的精确成像。结果揭示了浮游植物细胞分泌物存在极其陡峭的浓度梯度，打破了经典理想扩散模型的假设。","scd":{"b":6.0,"i":3.0,"r":8.0,"d":6.0,"t":6.0},"kp":["空间检测精度[藻圈微环境化学梯度]: 微米级拉曼微光谱测量","[浮游植物单细胞分泌物]: 形成尖锐的化学梯度，不符合经典理想扩散假设"]},{"i":40281,"as":"针对印度尼西亚棕榈油行业的零毁林承诺(ZDCs)实施效果进行了因果评估。研究整合了企业ZDC执行情况、供应链联系和森林覆盖等详细数据。结果显示，棕榈油供应链中的供应商对ZDCs实现了极高的合规性，但这种合规并未带来额外的环保效益。零毁林承诺主要促进了供应商的行为达标，但在没有承诺也会发生保护的情况下，未能产生超越常规发展轨迹的实质性额外降毁林效果。","scd":{"b":3.0,"i":4.0,"r":7.0,"d":5.0,"t":4.0},"kp":["合规性评估[印尼棕榈油行业零毁林承诺]: 实现了高度合规性","额外性评估[印尼棕榈油行业零毁林承诺]: 缺乏额外性（未产生超越承诺发生条件外的广泛益处）"]},{"i":40282,"as":"","scd":null,"kp":[]},{"i":40283,"as":"","scd":null,"kp":[]},{"i":40284,"as":"","scd":null,"kp":[]},{"i":40285,"as":"研究发现植物组蛋白脱乙酰酶HDA19是调节盐胁迫敏感性的关键表观遗传调控因子。HDA19缺失的拟南芥突变体表现出对干旱、高温和盐胁迫的耐受性。通过赖氨酸乙酰化分析，确认HDA19的特异性底物是组蛋白H3.3上非典型的K27/K36双乙酰化标记。在盐胁迫下，该标记在野生型植株中减少，而在hda19突变体中增加。模拟组成型双乙酰化的实验进一步证实了其对抗逆性的调控作用。","scd":{"b":6.0,"i":2.0,"r":8.0,"d":6.0,"t":5.0},"kp":[]},{"i":40286,"as":"研究分析了全球19个大都市圈约3000条公交线路（年客流量超40亿人次）的数据，揭示了一个关于拥挤控制下公交发车频率的稳健标度律。研究发现，公交频率(f)与需求量(d)和时间(t)的比例关系呈现特定的幂律分布特征。这为城市在不确定性下合理分配有限交通资源以维持出行流动性提供了量化理论基础。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["样本规模[城市公交系统标度律分析]: 全球19个大都市区约3000条路线（年客流量超40亿）","频率标度律[拥挤控制下的公交系统]: 频率随需求变化呈现稳健的标度律特征"]},{"i":40287,"as":"","scd":null,"kp":[]},{"i":40288,"as":"研究揭示了内应力在攀缘植物卷须扭动动态中的核心控制作用。实验表明，在低轴向拉力下，黄瓜卷须的曲率呈指数饱和；而在高于临界阈值的外力下，卷须无法盘绕但会形成内在的盘绕倾向应力。生长场评估证实曲率源于差异性生长。研究构建了自向性形态弹性生长模型，指出在无外力负载时，卷须曲率的产生完全受限于其内应力。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["低牵引力响应[黄瓜卷须]: 曲率随时间呈指数饱和至极限值","高牵引力响应[超过临界阈值]: 卷须无法盘绕但产生内在易盘绕应力及固有残余曲率","曲率来源[攀缘植物卷须]: 差异化生长产生内应力控制扭动动态"]},{"i":40289,"as":"","scd":null,"kp":[]},{"i":40290,"as":"","scd":null,"kp":[]},{"i":40291,"as":"","scd":null,"kp":[]},{"i":40292,"as":"","scd":null,"kp":[]},{"i":40293,"as":"","scd":null,"kp":[]},{"i":40294,"as":"本研究开发了一种可涂绘的皮肤干电极，专为可靠的无线传感和人机交互设计。该电极能在具有层级纹理的皮肤表面形成超共形界面，通过厚度梯度设计最小化界面应力，解决了皮肤变形出汗时接触不良以及软硬设备连接不稳的问题。该电极实现了10.8 kΩ cm的低接触阻抗，并因其高度可定制的特性，适合儿童及对传统设备敏感人群长期使用。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["电极类型[无线传感与人机交互]: 可涂漆的皮肤干电极","[电极接触与连接设计]: 具备坚固的皮肤贴合及设备连接，克服了皮肤变形出汗及软硬设备机械不匹配问题"]},{"i":40295,"as":"","scd":null,"kp":[]},{"i":40296,"as":"探讨视觉几何原理的启动机制或应用，可能涉及计算机视觉、空间认知或视觉感知计算模型。","scd":null,"kp":[]},{"i":40297,"as":"","scd":null,"kp":[]},{"i":40298,"as":"研究探讨了假定的氧化还原酶Pbr1在内质质质量控制和酵母Fks1葡聚糖合酶折叠中的作用。Fks1作为多次跨膜蛋白催化亚基，其复杂的跨膜结构在内质网中的生物发生具有挑战性。通过整合定量形态学和全局遗传互作分析，研究揭示了必需基因PBR1在支持跨膜极性或带电残基有效折叠及维护内质网质量控制中的关键功能。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["催化亚基[酵母β-(1,3)-葡聚糖合酶]: Fks1","折叠环境要求[大跨度跨膜蛋白生物发生]: 支持质膜葡聚糖合成且在ER中高效生物发生"]},{"i":40299,"as":"","scd":null,"kp":[]},{"i":40300,"as":"","scd":null,"kp":[]},{"i":40301,"as":"传统超分辨率荧光显微镜要求相同荧光分子依次发光以分辨亚衍射距离。本研究提出了一种新的概念框架，利用具有强度零点的激发光束（MINFLUX超分辨技术），能够不间断地解析和追踪相距仅几纳米且持续发光的相同点散射体。该技术克服了传统方法无法同时追踪多个紧密聚集荧光分子的局限，实现了对经历纳米级随机位置变化的散射体的持续光学分辨率。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["光学分辨率范围[相距数纳米的相同荧光分子追踪]: 纳米级（亚衍射距离）","技术限制[传统超分辨荧光显微镜]: 需要相同荧光分子依次发射以区分","探测方法[实现亚衍射区域不间断光学分辨]: 使用带有特定强度的激发束探测"]},{"i":40302,"as":"研究提出动物基因组中内源序列与水平转移基因（HGT）融合可产生“HGT嵌合体”，即同一开放阅读框内包含非后生动物和后生动物来源区域的基因。研究团队开发了分子系统发育学管线，对319个高质量节肢动物基因组进行分析，鉴定出274个高可信度的HGT嵌合体，对应跨不同节肢动物的104个独立起源事件，揭示了基因融合在水平转移进化创新中的关键作用。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["基因来源机制[进化创新/新基因产生]: 基因重复、基因融合、水平基因转移（HGT）","嵌合基因结构[HGT-chimeras/动物基因组水平转移基因演化]: 同一开放阅读框内包含非后生动物和后生动物来源区域"]},{"i":40303,"as":"","scd":null,"kp":[]},{"i":40304,"as":"","scd":null,"kp":[]},{"i":40305,"as":"","scd":null,"kp":[]},{"i":40306,"as":"基于对高草草原生态系统长达6年的实验性干旱研究，发现干旱重塑了土壤细菌、真菌和原生生物的群落组成，导致微生物多样性和生物量持续下降。时间衰减关系及群落差异分析显示，在干旱条件下，土壤微生物群落的演替轨迹出现日益分化的现象。尽管随机过程在群落组装中依然占主导地位，但干旱长期改变了其分化演替进程，影响了生态系统恢复力。","scd":{"b":6.0,"i":1.0,"r":7.0,"d":6.0,"t":6.0},"kp":["实验周期[高草草原生态系统实验性干旱]: 6年","生态影响[干旱对地下生物多样性的重塑]: 细菌、真菌和原生群落的分化演替"]},{"i":40307,"as":"","scd":null,"kp":[]},{"i":40308,"as":"","scd":null,"kp":[]},{"i":40309,"as":"磁振子（Magnons）为基于自旋的信息传输提供了一种超快且无损的途径。研究报道了在超薄反铁磁体LaFeO3层之间限制的BiFeO3层中，磁振子的传输特征及其固有的各向异性。该发现对于理解反铁磁材料中自旋信息的非破坏性读取和超快动力学传输具有重要意义，为下一代自旋电子学器件的材料选择和异质结构设计提供了物理基础。","scd":{"b":7.0,"i":1.0,"r":7.0,"d":6.0,"t":6.0},"kp":[]},{"i":40310,"as":"","scd":null,"kp":[]},{"i":40311,"as":"研究利用迁移学习（TL）解决了核物理数据驱动模型在训练数据受限时的优化波动和采样偏差问题。通过预训练深度神经网络（DNN），模型成功实现了从α衰变到更复杂的集群衰变物理机制的预测迁移。这展示了机器学习在处理放射性衰变极端情况下的强大泛化能力，为有限实验数据下的原子核动力学预测提供了有效工具。","scd":{"b":5.0,"i":1.0,"r":7.0,"d":6.0,"t":6.0},"kp":["学习方法[解决数据驱动模型随机初始化波动和采样偏差]: 迁移学习（首先预训练深度神经网络）","模型架构[数据驱动核物理模型]: 深度神经网络（DNNs）"]},{"i":40312,"as":"","scd":null,"kp":[]},{"i":40313,"as":"","scd":null,"kp":[]},{"i":40314,"as":"研究引入了一种简化的Connes-Narnhofer-Thirring量子动力学熵版本，用于量子系统。该指标量化了通过持续监测可观测量而获得的关于初始条件的信息量。通过监测系统的热力学性质，可以获得非零的熵增长率。该研究探讨了量子动力学熵的普朗克界限，发表于《物理评论快报》（Phys. Rev. Lett. 137, 030402）。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":6.0,"t":6.0},"kp":["数学模型[简化的量子系统动力学熵]: Connes-Narnhofer-Thirring量子动力学熵简化版","物理意义[连续监测可观测值的熵增长率]: 量化从初始条件获得的信息量"]},{"i":40315,"as":"热操作是推导量子系统热力学限制的核心量子信道。然而，热操作最初是基于实现程序而非基本原理定义的。尽管已有其他替代的热过程模型，但它们表现出明显的局限性。该研究探讨了热操作模型在信息平衡方面的定义与基本物理原理之间的联系，发表于《物理评论快报》（Phys. Rev. Lett. 137, 030403）。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":6.0,"t":6.0},"kp":["热操作定义[推导量子系统热力学限制]: 由实现程序定义而非基本原理定义的量子信道","理论重构目标[热过程的替代模型]: 基于信息平衡和基本原理定义"]},{"i":40316,"as":"量子纠缠能突破标准量子极限提升计量精度，但这种优势常因粒子丢失而消失。研究证明，信息加扰机制通过将编码参数的信息分散到多体关联中，从而保护了计量精度。对于Haar随机加扰，这种保护作用得到了证实。该研究表明加扰能够有效保护计量学优势，发表于《物理评论快报》。","scd":{"b":9.0,"i":1.0,"r":5.0,"d":7.0,"t":8.0},"kp":["技术机制[在粒子损失下保护纠缠计量优势]: 信息扰乱（将编码参数信息分散到多体关联中）","适用模型[保障精度的扰乱机制]: Haar随机扰乱"]},{"i":40317,"as":"","scd":null,"kp":[]},{"i":40318,"as":"近期理论研究表明，螺线管等离子体湍流能显著增强聚变反应率，但目前缺乏直接测量这些流体的标准诊断方法。研究提出了一种通过激光偏振旋转来检测等离子体湍流的方法。该方法能够直接测量高能量密度等离子体中的螺线管流，并能区分螺线管湍流和压缩湍流。研究成果发表于《物理评论快报》。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":8.0},"kp":["检测方法[螺线管等离子体湍流直接测量与区分]: 激光偏振旋转检测","物理效应[高能量密度等离子体中的螺线管湍流]: 显著增强聚变反应性"]},{"i":40319,"as":"受近期扭曲双层二碲化钼（MoTe2）实验的启发，研究提出了一种关于总填充因子为4/3的分数拓扑绝缘体边缘的无序相互作用理论。该理论探讨了在无序和相互作用存在下，分数拓扑绝缘体边缘的对称性定位问题，为理解相关实验现象提供了理论基础，发表于《物理评论快报》。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":7.0,"t":8.0},"kp":["参数条件[分数拓扑绝缘体边理论]: ${ν}_{tot}=4/3$","实验对象[分数拓扑绝缘体]: 扭转${\\mathrm{MoTe}}_{2}$"]},{"i":40320,"as":"磁子频率梳由一系列离散频率线组成，是磁子自旋电子学的前沿方向，在信息处理和传感领域具有应用潜力。尽管三磁子散射被广泛认为是其产生机制，但该研究提出并实现了受激磁子频率梳。这项技术拓展了磁子频率梳的控制手段，为其在先进信息技术中的应用奠定了基础，发表于《物理评论快报》。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":7.0,"t":8.0},"kp":["离散频率线[受激磁频率梳]: 由三磁子散射过程产生"]},{"i":40321,"as":"研究提出了一种针对手性活性固体的新理论框架。这种固体由于活性扭矩的作用，允许局部的内部旋转。该理论阐明了在生物和合成系统相关的结构无序材料中，奇数弹性是如何产生的。这项研究揭示了无序手性活性材料中奇特的力学响应机制，发表于《物理评论快报》。","scd":{"b":8.0,"i":1.0,"r":6.0,"d":6.0,"t":8.0},"kp":["局部内部旋转[无序手性活性固体]: 由活性扭矩驱动产生","奇怪弹性[手性活性材料]: 在结构无序材料中涌现"]},{"i":40322,"as":"研究提出了一个关于可变形介质中物质传输的“Pushy 随机游走”最小模型。在该模型中，运动的示踪粒子能够排开障碍物，从而在二维和一维系统中产生全新的扩散行为。该模型有助于理解复杂介质中的粒子运动和传输机制，研究成果发表于《物理评论快报》。","scd":{"b":7.0,"i":1.0,"r":5.0,"d":5.0,"t":8.0},"kp":["扩散行为[Pushy随机游走最小模型]: 运动示踪剂在1D和2D可变形介质中位移障碍物从而产生新扩散行为"]},{"i":40323,"as":"研究人员利用中子自旋回波光谱学和脉冲场梯度核磁共振技术，研究了非缠结和弱缠结聚异戊二烯（PI）熔体的动力学。通过与高度缠结的PI熔体光谱进行比较，证实了长时间尺度下的布朗扩散现象。实验结果验证了合作动力学广义朗之万方程理论的基本预测，发表于《物理评论快报》。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":8.0},"kp":["动力学行为[非缠结与弱缠结聚异戊二烯(PI)熔体]: 观察到布朗扩散等爬行与合作动力学"]},{"i":40324,"as":"研究开发了多羧基树枝状脂肽以通过铂配位提高顺铂的载药量并改善肿瘤靶向性。结构-活性关系研究确定了DG3为最佳脂肽，由此制备的纳米颗粒具有高载药量、良好稳定性和递送效率。结合STING激动剂，该系统通过促进细胞毒性T细胞浸润和树突状细胞成熟、减少调节性T细胞，协同增强了胰腺癌的化学免疫治疗效果。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":7.0,"t":7.0},"kp":["最优脂肽[构建高载药脂质纳米颗粒]: DG3","递送效率[顺铂/胰腺癌化学免疫治疗]: 通过铂配位与肿瘤靶向实现高药物装载、良好稳定性和高递送效率"]},{"i":40325,"as":"","scd":null,"kp":[]},{"i":40326,"as":"TRIUMF超冷先进中子源（TUCAN）合作组报告了由超流液氦-4驱动的超冷中子源的首批实验结果。该设施旨在对中子电偶极矩进行高精度测量。实验共产生了数量为(9.3±0.8)×10^5的超冷中子。这一进展标志着新一代中子电偶极矩精确测量实验的顺利进行，发表于《物理评论C》。","scd":{"b":9.0,"i":4.0,"r":8.0,"d":8.0,"t":9.0},"kp":["超冷中子产量[TRIUMF散裂驱动超流液氦(He-II)源]: (9.3±0.8)×10^5"]},{"i":40327,"as":"在三聚体钌氧化物Ba4Ru3O10中，研究通过结构、热力学和输运性质的同时测量，揭示了该材料中存在一种被强烈钉扎的密度波不稳定性。此前，这种反铁磁氧化物一直被认为是一种纯粹的磁性绝缘体。这一发现证明了该材料中存在隐藏的密度波相变，研究成果发表于《物理评论快报》。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":6.0,"t":9.0},"kp":["密度波[三聚体钌酸盐反铁磁绝缘体]: 结构、热力学和输运性质中同时显现出强烈钉扎的隐藏密度波"]},{"i":40328,"as":"研究在原子层面上直接观察了多组分固体分子结中的动态能量传输过程。在金表面自组装单分子层光激发后，揭示了早期的能量转移时间序列：能量从金表面层传输出去。该研究直接观测了单分子结的能量传输动力学，证实了其具有高热导率，为分子器件热管理提供了新见解，发表于《物理评论快报》。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":9.0},"kp":["能量传输动力学[金表面自组装烷基硫醇单分子结]: 光激发后能量从金表面层向分子链传输具有明确的时间序列"]},{"i":40329,"as":"在幺正演化下，以简单态初始化的混沌量子系统会迅速产生高复杂性，使得经典模拟变得困难。这种在稳定子形式体系中经典模拟的困难程度被称为魔法资源，可通过稳定子范数来量化。研究将热场双态中的魔法动力学与量子混沌的光谱形状因子直接联系起来，研究成果发表于《物理评论快报》。","scd":{"b":8.0,"i":1.0,"r":6.0,"d":5.0,"t":9.0},"kp":["经典模拟难度[幺正演化下的混沌量子系统]: 可通过稳定器形式化中的魔法资源进行量化"]},{"i":40330,"as":"研究提出了一种基于物理的工作流，用于预测托卡马克破裂期间的三维热负荷。该方法将垂直位移事件的磁流体力学（MHD）模拟与真实三维第一壁模型上的磁场线追踪相结合。研究通过JET实验数据验证了该方法的可靠性，并将其应用于2024年新基准的钨装甲ITER装置中，评估了破裂热负荷及其三维局部化特征。","scd":{"b":6.0,"i":6.0,"r":6.0,"d":7.0,"t":7.0},"kp":["3D热负荷预测[托卡马克垂直位移事件]: 结合了垂直位移事件MHD模拟、3D第一壁磁场线追踪和瞬态壁热响应的物理工作流"]},{"i":40331,"as":"研究首次在TCV托卡马克中观察到了离子回旋辐射（ICE）。测得的ICE频率与磁轴处的氘离子回旋频率高度吻合，其时间变化与平衡演变及磁轴的移动一致。核心ICE主要在电子回旋共振加热和中性束注入共同作用的阶段观察到。频谱中不仅以二次谐波为主，还检测到频率啁啾和分支分裂等精细结构。","scd":{"b":7.0,"i":6.0,"r":8.0,"d":7.0,"t":9.0},"kp":["[等离子体离子回旋辐射现象]: 首次在TCV托卡马克中观测到","[等离子体核芯离子回旋辐射观测条件]: 电子回旋共振加热(ECRH)与中性束注入(NBI)联合作用阶段"]},{"i":40332,"as":"研究提出了一种覆盖托卡马克整个生命周期的等离子体破裂预测策略。针对早期缺乏破裂数据的问题，设计了仅需非破裂样本进行训练的异常检测预测器，从首次放电即开始提供保护。随着后期放电场景的演变和高性能运行阶段的到来，该策略融合了多种预测方法以维持模型的预测性能，从而在冷启动到持续运行期间最大化保护装置。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":5.0,"t":7.0},"kp":["[大型托卡马克装置破裂危害]: 等离子体破裂会造成严重损伤，特别是在ITER等大型装置中"]},{"i":40333,"as":"本研究通过GPEC中的阻力磁流体动力学内层模型，量化分析了阻力扰动托卡马克平衡中表征屏蔽电流和穿透场的两个关键指标。结果表明，这两个指标在同一阻力模型下能产生高度相似的主导耦合模式，但在具体缩放和全局扭曲结构影响上存在差异。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[托卡马克谐振响应量化指标]: 使用代表屏蔽电流和穿透场的指标，通过电阻磁流体力学渐近匹配解进行检验"]},{"i":40334,"as":"聚对苯二甲酸乙二醇酯（PET）因耐热性差在高温环境中的应用受限。本文综述了提高PET耐热性的多种策略，主要聚焦于调节分子流动性、控制结晶行为和利用复合材料增强。具体方法包括分子结构改性、添加成核剂、优化加工工艺及聚合物共混，并对比了这些方法的机理与优势。","scd":{"b":4.0,"i":8.0,"r":6.0,"d":5.0,"t":4.0},"kp":["PET[聚对苯二甲酸乙二醇酯]: 具有优异的机械强度、化学稳定性和成本效益，但耐热性低限制了其在高温环境的应用","[提高PET耐热性策略]: 侧重于调节分子流动性"]},{"i":40335,"as":"","scd":null,"kp":[]},{"i":40336,"as":"骨组织工程中，控制微组织的结构整合与功能成熟是一大挑战。研究证实，将亚微米级球霰石颗粒作为可编程材料预载入前成骨细胞，可调节球体行为。结合机器学习岭回归分析，研究量化了颗粒定位、球体力学性能、成骨活性和融合动力学，实现了对复合球体行为的精确控制。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[骨组织工程复合细胞-材料构建]: 细胞内加载亚微米球霰石颗粒可作为可编程的基于材料的参数来调节球体行为"]},{"i":40337,"as":"针对现有表面增强拉曼散射（SERS）基底局限于单相检测的缺陷，研究利用木薯淀粉的凝胶特性和原位还原能力，通过糊化、回生和冷冻干燥构建了负载银纳米颗粒的三维自交联可塌陷淀粉气凝胶（ACA）。该基底能够实现复杂基质中多相痕量污染物的高灵敏度和全覆盖检测。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["SERS基底[木薯淀粉气凝胶负载银纳米颗粒]: 构建三维AgNPs decorated cassava s气凝胶以解决单相检测和多功能集成基底短缺的缺陷"]},{"i":40338,"as":"骨关节炎的特征是软骨下骨重塑异常。研究发现，骨细胞中的小清蛋白（Pvalb）是关键的机械感觉调节因子。在过度机械负荷下，Pvalb表达受抑，激活Ca²⁺-CaMKIV-CREB信号通路。靶向恢复骨细胞中的Pvalb表达可维持钙稳态，有效减轻骨关节炎的疾病表型。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[骨关节炎病理过程调控]: 骨细胞中的小清蛋白(Pvalb)是关键机械感应调节器，骨靶向恢复Pvalb可延缓骨关节炎进展"]},{"i":40339,"as":"研究提出了一种由自热引起阻塞的流体忆阻器（SIBM）。在周期性电压刺激下，其通过热触发的可逆沉淀产生记忆效应，表现出阈值型单极性电阻开关和明显的负微分电阻（NDR）特性。基于此构建的流体忆阻器阵列成功实现了多种神经形态功能和重复记忆操作。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":6.0},"kp":["自热引起的阻塞忆阻器(SIBM)[神经形态离子计算]: 记忆效应源于热触发的可逆沉淀"]},{"i":40340,"as":"草类植物拥有独特的哑铃形保卫细胞。研究发现，非草类禾本目植物的气孔力学极小，而草类通过增加副卫细胞面积，使保卫细胞能够通过置换副卫细胞来提高最大气孔孔径和响应速度。这一解剖学变化和力学交互作用是草类气孔进化和高效生理响应的关键。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["草类气孔力学[进化特征]: 具有哑铃形保卫细胞解剖结构，且与邻近表皮细胞的机械相互作用极小"]},{"i":40341,"as":"研究利用硬X射线光电子能谱分析了FAPbI3钙钛矿太阳能电池中钙钛矿吸收层与空穴传输层的埋底界面。结果发现界面处存在Pb和I离子渗透，形成了非钙钛矿Pb物种和新的N 1s峰。这些由沉积引起的化学修饰表明，界面相互作用显著影响钙钛矿电池的效率和长期稳定性。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[钙钛矿太阳能电池(FAPbI3)]: 界面现象和埋入界面的化学相互作用及电子结构对器件性能和长期稳定性有关键影响"]},{"i":40342,"as":"","scd":null,"kp":[]},{"i":40343,"as":"","scd":null,"kp":[]},{"i":40344,"as":"","scd":null,"kp":[]},{"i":40345,"as":"","scd":null,"kp":[]},{"i":40346,"as":"","scd":null,"kp":[]},{"i":40347,"as":"","scd":null,"kp":[]},{"i":40348,"as":"","scd":null,"kp":[]},{"i":40349,"as":"","scd":null,"kp":[]},{"i":40350,"as":"","scd":null,"kp":[]},{"i":40351,"as":"现有基因序列预测模型无法泛化到训练集之外的细胞类型。研究开发了名为Corgi的上下文感知序列到功能模型。该模型整合了DNA序列与反式调节因子的表达数据，能够精准预测未包含在训练集中的细胞类型的染色质可及性、组蛋白修饰和基因表达，实现了跨序列和跨细胞类型的高效预测。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[现有序列到功能模型]: 无法外推超出训练数据集包含的细胞类型和条件","[Corgi模型]: 上下文感知的序列到功能预测模型，通过整合DNA序列和反式调节因子表达预测染色质可及性"]},{"i":40352,"as":"","scd":null,"kp":[]},{"i":40353,"as":"","scd":null,"kp":[]},{"i":40354,"as":"","scd":null,"kp":[]},{"i":40355,"as":"为解决供体肝脏短缺及常温机械灌注评估受限的问题，研究开发了一种临床部署的双室生化监测（DCBM）平台。该平台集成了双通道微流控、多重电化学传感、兼容胆汁的防污界面和无线数据传输，能够自动在线测量灌注液和胆汁中的pH值、乳酸和葡萄糖。在七个人类供体肝脏中，该平台测量结果与标准方法高度一致。","scd":{"b":7.0,"i":7.0,"r":8.0,"d":8.0,"t":8.0},"kp":["[双室生化监测(DCBM)平台]: 临床部署的人体肝脏常温机械灌注系统，集成了双通道双室连续生化监测"]},{"i":40356,"as":"海洋生态系统的关键服务高度依赖中浮游生物（200-20,000 µm）的体型大小。基于全球生物图像数据集，研究揭示了铁在塑造根足虫、群体固氮菌和甲壳类动物体型结构及其相关生物地理学中的关键作用。研究强调，大气的铁源对固氮菌和根足虫至关重要，而包含有机和无机化合物的总铁则对甲壳类等生物群落的体型结构变化产生显著影响。","scd":{"b":6.5,"i":2.0,"r":7.0,"d":7.5,"t":5.0},"kp":["体型尺寸范围[中海平面浮游生物]: 200-20,000 µm"]},{"i":40357,"as":"物质相的稳定性通常仅在静态扰动下成立。该研究证明了一种普遍存在的物理现象：由随时间变化的局域哈密顿量驱动的演化态，可以在瞬时能谱的特定能量窗口内发生指数级局域化，并在通用的时间相关扰动下存活。将这种能量空间局域化应用于具有高能量屏障的经典和量子LDPC码，证明系统在通用时间相关扰动下，可在原始码字附近保持局域化状态长达指数级的时间。","scd":{"b":8.5,"i":1.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[时间相关量子多体系统]: 针对时间相关扰动保持稳定的量子相态并具有通用能量空间局域化现象"]},{"i":40358,"as":"","scd":null,"kp":[]},{"i":40359,"as":"在高温下高效吸附分离乙炔（C2H2）和二氧化碳（CO2）具有节能意义，但传统吸附剂主客体相互作用热稳定性差。受聚合物线性分子组装启发，研究人员开发了微孔晶体NTU-103。其一维螺旋流道在348K下，通过主客体和客体间的协同作用，将吸附的C2H2稳定组装成“纳米线”状结构并隔离CO2。该机制使NTU-103在高温下仍具备高效的C2H2/CO2分离能力。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":8.0,"t":5.0},"kp":["C2H2/CO2分离温度[NTU-103微孔晶体吸附]: 348 K","[NTU-103吸附剂]: 一维螺旋流道将吸附的C2H2分子组装成“纳米线”状结构以在高温下增强分离效果"]},{"i":40360,"as":"过渡金属催化剂上苯酚的电催化加氢（ECH）能选择性生成环己酮，但其机制尚不明确。结合分子动力学模拟与电极电位控制，研究证实阴极极化通过表面介导的电荷转移，使烯醇-酮平衡向酮式方向移动，从而促进芳香环加氢生成环己酮。此外，带负电的表面通过静电作用将环己酮稳定在亚稳态的“悬浮”状态，在动力学上抑制了其进一步加氢。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":7.5,"t":5.0},"kp":["[苯酚电催化氢化机制]: 阴极极化通过表面介导机制使烯醇-酮平衡向酮式（环己酮）移动"]},{"i":40361,"as":"体积电容无法直接量化决定器件掺杂能力的电活性电荷载流子密度。该研究引入有效体积电容（Ceff* = C* · η，η为掺杂效率）作为评估指标。研究发现，亲离子侧链虽促进离子摄取，但会将离子隔离在共轭主链之外，降低掺杂效率；相反，去除侧链可增加离子对电化学活性主链位点的可及性，使有机电化学晶体管的掺杂效率接近100%。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["有效体积电容(Ceff*)[有机电化学晶体管掺杂效率]: Ceff* = C* · η（有效体积掺杂指标）"]},{"i":40362,"as":"浓度极化驱动的矿物结垢是从锂离子电池浸出液中回收金属的电膜技术面临的挑战。研究提出电场辅助有机酸控制（eF-OAC）原理，利用电场将有机酸引入膜基质，通过配体与金属的配位作用溶解富含氢氧化物的垢层，并促进金属离子的选择性迁移与结晶，从而防止膜结垢并实现金属有效回收。实验与理论计算揭示了浓度极化在膜界面富集金属氢氧化物的结垢机制。","scd":{"b":7.0,"i":4.0,"r":6.5,"d":7.5,"t":5.5},"kp":["[电场辅助有机酸控制(eF-OAC)]: 利用有机酸进行配体-金属配位以防止电膜技术中矿物质结垢并回收金属"]},{"i":40363,"as":"为从钢厂尾气中回收一氧化碳（CO），传统Cu(I)基吸附剂结合力过强且工作容量低。研究开发了一种以ZIF衍生多孔碳为载体、具有双配位Cu(I)结构的热分散开放金属位点吸附剂（15Cu(I)/ZPC-1）。该吸附剂在10-30埃孔隙中分散15 mmol/g的Cu(I)，在298K、0.1-1 bar条件下，CO工作容量高达3.21 mmol/g，创下了目前可回收Cu(I)基吸附剂的最高纪录。","scd":{"b":7.5,"i":3.0,"r":6.5,"d":8.0,"t":5.0},"kp":["Cu(I)配位数[ZIF衍生多孔碳(ZPC)上的开放金属位点]: 双配位Cu(I)，即(≡C–O)CuCl","[Cu(I)基π络合吸附剂]: 具有过强结合强度和低工作容量的缺点"]},{"i":40364,"as":"针对电容去离子技术中Ag与导电基质异质界面电荷传输电阻大的问题，研究人员通过原位蚀刻还原策略，将Ag单原子和纳米颗粒以共价键形式连接在多孔MXene（HMX）上。共价连接促进了Ag到HMX的电子转移，并在Ag表面形成缺电子态，从而促进法拉第脱氯反应。同时，带有丰富面内纳米孔的HMX纳米片进一步提升了界面电子传输和脱氯性能。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":7.5,"t":5.0},"kp":["[Ag-多孔MXene界面键合]: 通过原位刻蚀还原策略将Ag单原子和纳米颗粒共价连接至多孔MXene，降低异质界面电荷转移阻抗"]},{"i":40365,"as":"高能锂离子电池对高硅含量的硅碳复合负极需求迫切，但存在界面不兼容和机械不稳定性问题。研究设计了一种通过界面-机械协同作用解决上述难题的分子工程粘合剂。该粘合剂结合了疏水性软共聚物和亲水性硬共聚物，实现了两亲性界面粘合，并具备能适应硅体积剧烈变化的机械性能。该设计在实际软包电池中实现了高面积容量和长寿命。","scd":{"b":6.0,"i":5.5,"r":7.0,"d":8.0,"t":5.5},"kp":["电极材料[硅基负极]: 高硅含量硅石墨复合负极","[粘合剂设计要求]: 需同时实现对硅和石墨的强力粘附、适应硅的巨大体积变化并保持高本体稳定性"]},{"i":40366,"as":"","scd":null,"kp":[]},{"i":40367,"as":"","scd":null,"kp":[]},{"i":40368,"as":"在多层高Tc铜氧化物中，内部CuO2面（IPs）比外层（OPs）更纯净。利用角分辨光电子能谱对五层和三层铜氧化物进行研究，发现仅IPs在低温下具有超导性，而OPs保持金属性。模型计算显示超导邻近效应可忽略不计。这种层间解耦形成了一种理想结构：单层超导CuO2面被重掺杂的金属性外层屏蔽，从而免受掺杂层引起的无序影响，显著增强了超导相干性。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":8.0,"t":7.0},"kp":["超导相干性[多层铜氧化物外层金属屏蔽]: 仅内部CuO2平面呈现超导性，外层平面在低温下保持金属性","[层间电荷分布]: 理论模型计算表明超过95%的屏蔽电荷被消除"]},{"i":40369,"as":"压缩技术是降低机械振荡器噪声的有效手段，但声子激光器（光学激光的机械类似物）的经典压缩尚未实现。研究基于悬浮光力学系统中的微尺度球体，实验展示了热机械压缩多模声子激光器。通过脉冲调制捕获激光产生的非绝热频移，基频模声子激光被压缩了3.15 ± 0.35 dB。同时，二次谐波模式的声子激光也实现了同步压缩。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[声子激光器]: 首次在悬浮光力学系统中实现热机械压缩态的微球声子激光器","[压缩降噪]: 能够在一个正交分量上减少噪声并增加在另一个正交分量上的噪声"]},{"i":40370,"as":"","scd":null,"kp":[]},{"i":40371,"as":"钙钛矿太阳能电池的可扩展制造受限于环境水氧导致的结晶脆弱性，特别是在刮刀涂布的预退火阶段。研究提出表面限制保护策略，通过在钙钛矿前驱体墨水中引入二丙基铵三氟乙酸盐（DPTA），自组装形成一层致密表面层。这层屏障在关键的预退火阶段选择性地屏蔽湿膜免受环境侵蚀，稳定了PbI2·NMP中间体，有效防止了钙钛矿的预退火降解。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":7.0},"kp":["[刀片涂层钙钛矿预退火结晶]: 采用表面限制保护策略内在稳定常温环境下的钙钛矿薄膜形成过程","[添加剂]: 引入三氟乙酸二丙铵(DPTA)至钙钛矿前驱体墨水中自发形成保护"]},{"i":40372,"as":"脱氢是构建复杂有机分子烯烃的有效策略。研究利用钯和铜催化体系，实现了多个β,γ-和γ,δ-C–H键的位点选择性脱氢。该方法能够对C-H和碳碳双键进行立体和区域选择性的氧化，包括在二萜烯中实现空间位阻较大的C-H键氧化，超越了传统氧化方法。这为复杂萜烯合成中的净位点选择性氧化提供了新途径。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":7.0,"t":7.0},"kp":["位点选择性[β,γ-和γ,δ-C-H键脱氢]: 由特定钯催化剂控制实现多位点选择性脱氢","[复杂有机分子合成]: 作为实现复杂萜烯净位点选择性氧化的可靠切入点"]},{"i":40373,"as":"在复杂三维结构外表面进行微纳米级保形薄膜图案化对软机器人等领域至关重要。研究利用光刻定义的剥离掩模和支架架构，提出一种稳健的图案化方法。该技术能在高达90度的倾斜表面实现保形薄膜图案化，特征尺寸从100微米到100纳米，结合掩模收缩技术甚至可达到30纳米以下尺度，克服了传统方法分辨率低和表面贴合度差的问题。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[3D结构薄膜图案化]: 采用具有支架架构的剥离掩模在复杂三维结构外表面实现微纳级保形薄膜涂层图案化","[技术优势]: 解决了现有方法难以在复杂3D结构上实现高分辨率图案化、厚度可控性差和表面保形性不足的问题"]},{"i":40374,"as":"针对数据驱动动力学学习的可靠性与不可靠性边界问题，研究利用对抗动力系统给出了解答。在Koopman算子学习（一种通过线性谱对象表示非线性动力学的框架）中，研究设计了具有收敛性和认证保证的最优数据驱动谱算法。该算法在物理系统中广泛存在的条件下有效，为Koopman算子近似建立了收敛理论，并解决了该领域长期存在的开放性问题。","scd":{"b":7.5,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[数据驱动学习边界]: 利用对抗动力系统识别数据驱动学习的可学习与不可学习状态边界","[Koopman算子学习]: 揭示了非线性动力学表示中系统行为能够可靠从数据中学习的边界条件"]},{"i":40375,"as":"本文提出了一种验证者发起的量子数字签名（VIQDS）方案。与传统的签名者发起方案不同，该方案允许验证者在需要时才请求认证，签名者仅需响应一次，且认证后无需进一步交互即可完成验证。该技术结合了量子零知识证明，将认证转变为按需工作流，有效减少了不必要的通信与存储开销，非常适用于验证行为偶发的分布式服务和审计基础设施。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[量子消息认证]: 提出由验证者发起的量子数字签名(VIQDS)方案，仅在需要时请求认证且签名者仅响应一次","[验证机制]: 签发后验证过程无需进一步交互"]},{"i":40376,"as":"为解决二维钙钛矿生长缺陷和应变限制载流子传输的问题，本文提出了一种近平衡等温（NEIT）生长范式。该范式具有类似活性聚合的活性生长特性，将结晶限制在初始晶核内，实现了超低成核密度，成功制备出厘米级且结晶度提高的PEA2PbI4等单晶材料。此方法大幅提升了前驱体利用率，其中Pb-n1的利用率达到89%，远超传统方法的约13%。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[二维钙钛矿单晶生长]: 采用近平衡等温(NEIT)生长范式，展现类似活性聚合的活性生长特性","[晶体生长控制]: 将结晶过程主要限制在初始晶核中，从而减少生长诱导的缺陷和应变","[核心优势]: 实现超亮且具有长寿命载流子的二维钙钛矿"]},{"i":40377,"as":"本文研究了不同官能团的聚酰亚胺（PI）粘合剂在锂离子电池硅基负极中的作用。实验表明，含酰胺基团的PI-DABA粘合剂能有效抵抗电解液溶胀，并与硅材料产生强界面相互作用。相比之下，含酯基的PI-APAB在电解液中会发生严重溶胀并过度与Li+配位，导致机械性能下降；无额外极性基团的PI-PDA虽抗溶胀，但与硅的界面作用较弱。结果表明PI-DABA有效维持了电极完整性。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["粘合剂[硅基负极]: 聚酰亚胺(PI)粘合剂","粘合剂[PI-DABA(含酰胺基团)]: 能有效抗电解液溶胀并对硅材料具有强界面相互作用","粘合剂[PI-APAB]: 吸附力和结合力弱于PI-DABA(基于技术内涵的对比性推断特征)"]},{"i":40378,"as":"","scd":null,"kp":[]},{"i":40379,"as":"撤回一篇关于开发纳米结构α-MnO2/碳纸复合材料，以电吸附去除Ni2+/Mn2+离子的论文。","scd":{"b":1.0,"i":1.0,"r":2.0,"d":2.0,"t":5.0},"kp":[]},{"i":40380,"as":"","scd":null,"kp":[]},{"i":40381,"as":"当前的玻璃体替代物（如气体和硅油）仅能解决外科手术面临的即时挑战，却忽视了被替代组织的长期生理功能。为满足再生医学的需求，眼科临床亟需实现范式转变，开发持久且具有仿生特性的水凝胶替代物来永久性替换玻璃体。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":3.0,"t":4.0},"kp":["玻璃体替代物[长期临床需求]: 持久且仿生的水凝胶替代品","[短期手术填充剂]: 气体和硅油（缺乏长期组织功能替代作用）"]},{"i":40382,"as":"高能量存储密度的介电材料是实现设备小型化和系统集成的关键。随着材料制造技术的进步，介电材料的击穿强度已逼近理论极限。为进一步提升介电材料的储能性能，未来的研究和重点应转向增强材料的极化特性。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[击穿强度]: 接近理论极限","[储能性能进一步提升的途径]: 极化增强"]},{"i":40383,"as":"","scd":null,"kp":[]},{"i":40384,"as":"程方教授专访，讲述其从手工研磨镜片到参与西河太阳空间任务的中国太阳观测发展史。","scd":{"b":2.0,"i":2.0,"r":3.0,"d":2.0,"t":2.0},"kp":[]},{"i":40385,"as":"芳烃体系中惰性的碳碳键阻碍了酚类原料的直接多样化转化。本文报道了一种简单高效的氮化策略，可裂解酚类芳环，将其转化为氰基戊二烯酸酯、酰胺和酸等非环状含氮产物。该方法还能实现相应芳环的骨架跃迁，生成五元、六元和七元含氮杂环，成功解锁了骨架与官能团的多样性。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[芳香系统碳碳键]: 高度惰性，阻碍酚类原料的直接多样化","[酚类开环转化策略]: 可控且可编程的氮化策略"]},{"i":40386,"as":"“扣合二聚体”决定了硅和锗(100)半导体表面的关键性质。每个二聚体由一个路易斯酸性的“向下”原子和一个路易斯碱性的“向上”原子组成，形成极化基元。本研究利用杯[4]吡咯配体在双核Ge(II)配合物中强制形成独特的顺式弯曲几何结构，生成了极化的Ge-Ge单元。该分子系统成功模拟了Ge(100)扣合二聚体的两亲性质。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["Ge(100)表面扣合二聚体[核心原子属性]: '下'原子表现为路易斯酸性，'上'原子表现为路易斯碱性"]},{"i":40387,"as":"本研究通过温度梯度合成法调控CsPbCl3:Yb纳米晶体中镱离子的晶格位点占据（间隙或取代），显著提升了量子切割效率。优化的纳米晶体薄膜与晶体硅光伏集成后，在380纳米波长下实现了117.2%的外量子效率，并获得26.00%的认证光电转换效率。该策略为突破肖克利-奎瑟极限的光伏技术提供了理论基础。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":9.0,"t":7.0},"kp":["量子切割效率[CsPbCl3:Yb纳米晶]: 通过温度梯度合成调控Yb离子间隙与取代位占据","外量子效率[优化后的纳米晶薄膜集成c-Si PV]: 117.2% ± 2.9%","测试条件[外量子效率]: 380 nm波长，功率密度为30 μW/cm²","光电转换效率[认证后c-Si PV]: 26.00%"]},{"i":40388,"as":"在反向偏压下工作的金属卤化物钙钛矿二极管必须同时被视为半导体器件和电化学电池。反向偏压会引发电化学反应，产生高浓度的移动缺陷。这些移动离子缺陷导致了器件具有极低的击穿电压，并加速了电池性能的退化。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[反向偏压下移动缺陷浓度]: 高浓度","[反向偏压导致器件退化机制]: 低击穿电压与电池快速退化"]},{"i":40389,"as":"传统理论假设聚合反应中化学控制反应的速率系数与链长无关。本研究利用多尺度建模挑战了这一假设，证明在可逆加成-断裂链转移（RAFT）聚合中，聚合物-聚合物反应表现出显著的链长效应。当增长聚合物自由基与高分子量RAFT试剂反应时，反应熵的收敛会出现延迟，其链长效应会持续存在，这与使用低分子量RAFT试剂在10个单体添加内即达到平衡的现象截然不同。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["速率系数[传统化学控制聚合反应]: 假设与链长无关","反应熵链长收敛[RAFT聚合反应]: 表现出显著的链长效应"]},{"i":40390,"as":"撤回关于利用纳米级共价有机框架进行线粒体靶向光动力疗法的相关研究论文。","scd":{"b":0.0,"i":0.0,"r":0.0,"d":0.0,"t":0.0},"kp":[]},{"i":40391,"as":"反卡莎发射在光电子学成像、传感和白光LED领域具有重要应用前景。甘菊环分子具有两个明亮单重态，能从S2态发出反卡莎发射，是新型材料制造的理想候选者。然而，目前对甘菊环光物理机制的理解仍存在空白。研究发现，溶剂诱导的（反）芳香性变化能够导致甘菊环的反卡莎发射发生失活。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["反卡莎发射[甘菊环]: 易从S2态发射并具有两个明亮单重态","[白光LED应用]: 双光子发射"]},{"i":40392,"as":"硫醇官能团的过硫化是一个重要的生理过程，通常涉及还原态硫对部分氧化态硫的还原。本文报道了两种双核钴(II)-亚硝酸配合物与硫代羧酸反应，以65%-72%的高产率生成过硫化配合物，同时副产71%-80%的一氧化氮。通过结构表征和波谱分析以及对照实验，证实了反应中间体双核钴配合物的生成。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["过硫化配合物[双核钴(II)-亚硝酸盐配合物与RC(O)SH反应]: 高产率生成","过硫化机制[巯基官能团]: 由全还原硫还原部分氧化硫实现"]},{"i":40393,"as":"本文利用环对亚苯基衍生物独特的径向共轭和大环刚性，合理设计并合成了三种多孔有机圆柱体（POCys）。通过动态硼酸酯键对两个儿茶酚官能化的环对亚苯基进行同轴共价组装，构建了具有大固有空腔和互连通道网络的结构。其中一种多孔圆柱体表现出1241 m²/g的高BET比表面积和优异的气体吸附能力。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["多孔有机圆柱体[合成机制]: 通过动态硼酸酯键对儿茶酚功能化的环对亚苯基进行同轴共价组装","结构特征[多孔有机圆柱体]: 具有大的本征内腔和相互连接的通道"]},{"i":40394,"as":"热原电池（TGC）利用氧化还原反应的熵变将热能转化为电能。本研究发现脂肪族链的内在振动熵变（ΔSint）可显著提升热原电池的热电势，并进一步利用相变带来的熵变实现最大化输出。为此设计合成了共聚物P(NIPAM-co-ABFC)，该材料协同整合了振动熵和相变熵，有效增强了热电性能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["热电势增强机制[n型热原电池]: 脂肪族链的内在振动熵变(ΔSint)"]},{"i":40395,"as":"为最大化活性材料的电子转移数，本文在锂金属固态电池中引入了电化学耦合氧原子转移（OAT）新范式。使用碳载铁纳米颗粒同时作为OAT催化剂和转换型正极材料，实现了ClO4-的八电子阴离子还原，转化率超过50%，放电比容量达1150 mAh/g，能量密度高达1950 Wh/kg。该研究为电池系统基于氧阴离子的阴极氧化还原奠定了基础。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["碳载铁纳米颗粒[锂金属固态电池]: 兼具氧原子转移催化剂和转换型正极活性材料双重功能","电子转移数[p区含氧阴离子还原]: 每个活性物质公式单元转移八个电子"]},{"i":40396,"as":"传统金属有机框架（MOFs）依赖配位键构建。本研究提出了一种不依赖配位键的新型框架化学，利用质子转移促进的库仑力和氢键相互作用。酸性Keggin型多金属氧酸盐（POMs）质子化碱性胺分子后，在室温混合下自组装成结晶框架。溶剂酸度可调控质子转移和电荷平衡，驱动结构从π堆叠有机阵列演化为类MOF的节点-连接体网络。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["框架组装机制[库仑金属有机框架]: 依托质子转移促进的库仑相互作用和氢键相互作用（非配位键）","自组装前驱体[库仑金属有机框架]: 酸性Keggin型多金属氧酸盐质子化碱性胺分子形成互补的有机阳离子和无机阴离子"]},{"i":40397,"as":"本文报道了两种基于铜环状三核单元（Cu-CTU）的二维异孔共价金属有机框架的合成。异孔CMOFs的二氧化碳吸附量是同孔类似物的两倍。此外，将光敏单元引入异孔CMOFs中促进了光捕获和电荷分离，在光催化二氧化碳还原反应中实现了3548 μmol g⁻¹ h⁻¹的CO生成速率，选择性高达94.7%，展现出优异的光催化性能。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["光催化剂[CO2光还原]: 二维铜环状三核单元基异孔共价金属有机框架","催化效能[异孔共价金属有机框架]: 异孔结构比同孔类似物展现出更优的CO2光还原活性"]},{"i":40398,"as":"研究了纳米粒子结构对五氧化二钒（V2O5）质子耦合电子转移（PCET）反应的影响。通过Rietveld精修对不同形貌的V2O5进行表面刻面的半定量测量。研究发现，V2O5的PCET过程通过质子插入耦合电子转移（PICET）发生，其中氢原子（H·）扩散到颗粒内部，并分析了该过程的热力学特征。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["反应影响因素[质子耦合电子转移]: 纳米颗粒的形貌和表面晶面显著影响金属氧化物PCET的热力学和动力学"]},{"i":40399,"as":"开发了一种光催化系统，能将氨基环丙烷转化为γ-内酰胺。该系统通过连续的单原子扩环和外围多样化反应实现转化，在可预测的条件下完成了数百个合成实例。该方法不仅能够形成γ-内酰胺，还能通过六种不同的成键反应在γ位点上实现多样化修饰，为饱和小环的多原子插入提供了可靠途径。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["光催化系统[氨基环丙烷转化]: 通过连续的C-/N-单原子[n + 2]扩环直接转化为γ-内酰胺并实现外围多样化"]},{"i":40400,"as":"综述了酶激活荧光探针（EAFPs）的设计策略及其在生物医学领域的应用。酶在细胞代谢中起关键调节作用，其异常与疾病发生发展密切相关。EAFPs能够以高时空分辨率和多功能生物传感能力捕获异常的酶动态。文章重点介绍了此类探针的分子工程、传感机制和基础设计原理，以及其在生物学机制解析和病理研究中的概念验证应用。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":4.0,"t":3.0},"kp":["检测技术[酶激活荧光探针]: 能够实时监测酶的真实活性并捕获疾病相关的异常酶动力学"]},{"i":40401,"as":"研究了通过Adatom修饰选择性钝化台阶位点以控制铂电极双电层结构的方法。铂(111)电极具有真实的双电层窗口（0.40-0.60 VRHE），而阶梯状铂表面由于在所有电位范围内均有氢或羟基吸附，无法直接测量双电层电容。研究利用羟基吸附的特性来抑制特定台阶的亥姆霍兹电容，进而分析不同台阶表面表现出的电位依赖性羟基吸附行为。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["真实双层窗口[Pt(111)/HClO4界面]: 0.40-0.60 VRHE","台阶位点钝化[阶梯状Pt表面]: 采用Adatom（吸附原子）修饰选择性钝化低配位台阶位点以实现双电层电容的测量"]},{"i":40402,"as":"报道了一种通过催化不对称骨架编辑合成手性三芳基甲烷的方法。利用铑催化剂和重氮酯，通过去对称化或动力学拆分对吲哚环进行对映选择性单碳插入。该技术实现了芳环转化，首次成功构建了外骨架碳中心立体结构，以中等到良好的产率和高对映选择性（高达96% ee）获得了多种含不同芳香/杂芳香组合的光学活性三芳基甲烷。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["催化骨架编辑[手性三芳基甲烷合成]: 利用铑催化重氮酯对吲哚环进行对映选择性单碳插入（去对称化或动力学拆分），首次构建了环外碳中心立体中心"]},{"i":40403,"as":"","scd":null,"kp":[]},{"i":40404,"as":"","scd":null,"kp":[]},{"i":40405,"as":"","scd":null,"kp":[]},{"i":40406,"as":"四项关键前沿技术正在推动科学家对地球最后未测绘区域——深海的科学探索与研究。这些技术包括深海钻探船、海底传感器以及被重新利用的废弃互联网通信电缆，它们为改变和加深人类对深海环境的认知提供了强大的硬件支持。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":3.0,"t":4.0},"kp":["深海探测技术[海底勘测]: 深海钻探船、海底传感器以及被重新利用的互联网电缆"]},{"i":40407,"as":"更正关于用于高温聚合物电解质膜燃料电池的铜离子交联薄膜的相关研究内容。","scd":{"b":4.0,"i":2.0,"r":1.0,"d":2.0,"t":3.0},"kp":["[高温聚合物电解质膜燃料电池]: 铜离子交联薄膜(内容更正)"]},{"i":40408,"as":"本研究指出，欧洲当前的充电基础设施规划忽视了单向智能充电（V1G）与车网互动（V2G）技术带来的灵活性潜力。通过构建成本最优化的能源系统模型，研究发现V1G能实现绝大部分的系统成本节约（每年190至420亿欧元），并大幅降低对基础设施的需求。相比之下，V2G虽仅带来有限的额外成本节约（每年最高25亿欧元），却能创造高达每年64亿欧元的电力平衡市场收益。此外，V2G在以光伏为主导及电网扩建受限的能源系统中部署最具成本效益。各国充电需求存在差异，反映出其规划在设施利用率或系统灵活性最大化之间的不同侧重。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":7.0,"t":4.0},"kp":["充电灵活性技术[欧洲能源系统]: V1G实现大部分系统成本节约"]},{"i":40409,"as":"通过控制固态反应路径提升了全真空沉积钙钛矿太阳能电池的性能。研究发现，醋酸甲脒与碘化铅直接反应形成FAPbI3晶种层，显著降低了前驱体结晶及转化为α相钙钛矿的势垒。此外，过量的醋酸酯钝化了晶界缺陷并抑制了非辐射复合。最终，该太阳能电池实现了25.53%的光电转换效率和优异的电致发光外量子效率。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["固态反应路径[全真空沉积钙钛矿电池]: 醋酸甲脒与碘化铅直接反应形成FAPbI3晶种层"]},{"i":40410,"as":"研究通过竞争性配位驱动的相演化，制备具有均匀量子阱的纯相准二维钙钛矿材料。","scd":{"b":7.0,"i":2.0,"r":2.0,"d":3.0,"t":3.0},"kp":["工艺特征[准二维迪恩-雅各布森钙钛矿]: 竞争性配位驱动相演化制备均匀量子阱纯相"]},{"i":40411,"as":"分析了中国2853个县级市电解氢需求的水资源时空限制。研究发现，到2030年和2050年，约30%的电解氢需求将面临水资源限制，在更严格的用水限制下该比例将超过50%。这种水资源瓶颈可能会使中国在2030年面临1.74至2.99亿吨二氧化碳当量的碳减排机会风险，为此提出了针对不同城市的解决方案。","scd":{"b":5.0,"i":4.0,"r":8.0,"d":9.0,"t":4.0},"kp":["可再生氢生产目标[中国2050年]: 40-75 Mt/年","水资源限制分析[中国电解氢需求]: 覆盖2853个县级市"]},{"i":40412,"as":"","scd":null,"kp":[]},{"i":40413,"as":"极端天气不仅影响净零排放电力系统的供需，还导致系统压力在整个欧洲大陆蔓延。研究利用影子价格方法识别出被称为“系统定义事件”的高压时期，并分析了其对电力系统的影响。研究强调了配置足够“弹性备用发电容量”的必要性，但由于天气多变及相关风险，这些备用容量的财务可行性面临巨大挑战，文章同时区分了短期与长期的弹性挑战。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":6.0,"t":4.0},"kp":["应力识别方法[零碳电力系统极端天气备用投资]: 基于影子价格识别系统定义事件及影响"]},{"i":40414,"as":"","scd":null,"kp":[]},{"i":40415,"as":"探讨材料制备或处理中的一步蚀刻和剥离技术，涉及其工艺原理与应用方向。","scd":{"b":5.0,"i":2.0,"r":1.0,"d":2.0,"t":3.0},"kp":["[材料制备]: 一步蚀刻和剥离工艺"]},{"i":40416,"as":"展示了一种能够与哺乳动物传入神经整合的神经形态人工接口。现有的听力损失治疗方法仅适用于听觉神经通路完整的患者，而这种新型接口能够绕过受损的听觉通路，直接实现由语音控制的运动行为。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":7.0,"t":8.0},"kp":["[人工神经形态接口]: 绕过受损听觉通路并与传入神经整合以实现语音控制运动行为"]},{"i":40417,"as":"研究证实，光子的线性动量可以作为一种有效场，确定性地写入反铁磁畴。这一物理机制为通过光学手段精确控制和操纵隐藏磁序提供了一条强有力的全新途径。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":8.0},"kp":["[光子线性动量]: 可作为有效场确定性地写入反铁磁畴"]},{"i":40418,"as":"利用三维透射电子显微镜技术，在约50纳米直径的多壁碳纳米管内对水溶液和空气进行纳米级限制，揭示了纳米密闭空气-水界面存在强电场的直接证据。重构的多相结构显示了约10纳米的气体结构域，曲率分析表明存在约10 MPa的排斥压力以阻止水膜坍缩，这与界面处数伏特每纳米量级的强电场相吻合。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":8.0,"t":8.0},"kp":["碳纳米管直径[多壁碳纳米管]: ~50 nm","气相区域尺寸[纳米多相结构重构]: ~10 nm"]},{"i":40419,"as":"通过使用钛作为阻挡层，防止镓从共晶镓铟液态金属中析出，成功实现了液态金属与硅纳米薄膜的结合。基于此技术构建的液态金属电路阵列成功实现了视觉获取和深度感知功能。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["阻挡层材料[液态金属与硅纳米膜键合]: 钛","[共晶镓铟液态金属]: 通过钛阻挡层防止镓浸出并实现视觉采集与深度感知"]},{"i":40420,"as":"在块体铁电晶体中发现了拓扑涡旋结构，并证实其能够直接增强材料的压电响应。研究开发了一种机械辅助电场极化技术，成功调控了涡旋畴的密度，将涡旋核心密度从常规极化样品的0.01 μm−2大幅提升至21 μm−2。这种可控的极化方法将块体铁电体的拓扑结构与宏观压电性能建立了直接联系。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":7.0,"t":8.0},"kp":["材料体系[块状铁电体拓扑涡旋]: Pb(Mg1/3Nb2/3)O3–PbTiO3晶体","[拓扑涡旋结构]: 直接增强压电响应"]},{"i":40421,"as":"","scd":null,"kp":[]},{"i":40422,"as":"一颗曾被认为只是普通太空岩石的天体，被证实拥有类似彗星的尾巴。这一发现揭示了被称为“黑暗彗星”的神秘天体及其独特的运动特征。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":5.0,"t":8.0},"kp":["[天体特征]: 具有类似彗星的彗尾","[天体状态]: 曾被认为是普通太空岩石"]},{"i":40423,"as":"","scd":null,"kp":[]},{"i":40424,"as":"","scd":null,"kp":[]},{"i":40425,"as":"一种细菌自毁机制被改造为潜在的治疗方法，能够选择性消除患病细胞。在小鼠癌症模型实验中，基于该机制的CRISPR酶靶向DNA粉碎技术成功消除了肿瘤细胞。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[细菌自毁机制]: 经过重新设计可作为潜在疗法选择性消除小鼠肿瘤模型中的癌细胞"]},{"i":40426,"as":"","scd":null,"kp":[]},{"i":40427,"as":"磷独特的化学性质使其在技术领域的应用远超农业肥料范畴。专家探讨了基于磷平行经济的技术发展，这些技术广泛应用于电池、半导体和量子材料等前沿领域。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":4.0,"t":4.0},"kp":["应用领域[磷化学]: 电池、半导体和量子材料"]},{"i":40428,"as":"研究人员利用温度跃变红外光谱和分子动力学模拟，首次捕捉到肽段缩聚最初微秒内的分子事件与动力学信息。结果揭示，固有无序蛋白的结构转变和早期组装发生在超快时间尺度上，主链氢键被证实是稳定相变初期的关键介体。","scd":{"b":8.5,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["时间分辨率[多肽缩合初始时刻观测]: 首个微秒级","研究方法[克服传统时空分辨率限制]: 温度跃变红外光谱结合分子动力学模拟"]},{"i":40429,"as":"基于半经典密度-电势泛函理论，研究了阶梯电极双电层的微结构与热力学。该理论准确捕捉了阶梯状金和银电极的微分电容及零自由电荷电位（PZFC）随台阶密度变化的实验趋势。与平坦电极不同，阶梯电极的PZFC偏离了最小电容电位，需引入局部PZFC来描述异质表面充电条件。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["理论模型[阶梯电极微观热力学]: 半经典密度-泛函理论","[原子级阶梯]: 显著影响电化学活性和稳定性并表现出结构不稳定性"]},{"i":40430,"as":"研究开发了一种突破传统元素池限制的机器学习（ML）方法，包含以往未被研究的元素，用于加速发现CO2加氢合成乙醇的高效催化剂。基于58种初始催化剂在240-400°C下的274个数据点，通过“ML预测+实验验证”闭环系统进行24次迭代，成功开发了新型高效催化剂。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[机器学习辅助催化剂开发]: 超越传统元素池引入未研究过的新元素以加速发现新型CO2加氢合成乙醇催化剂"]},{"i":40431,"as":"开发了一种基于单电极机制的非接触式摩擦纳米发电机（TENG）传感器，能够实现物体距离和速度的时空协同解耦。该技术克服了多维信号解耦的挑战，推动了非接触式智能身份识别在医疗保健、远程安全和增强现实等领域的应用。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":4.0,"t":4.0},"kp":["应用方向[非接触式摩擦纳米发电机]: 智能身份识别等非接触式人机交互"]},{"i":40432,"as":"通过共掺杂Eu2+和Dy3+离子构建可逆微小光电化学层状微型电池结构，在SrZnOS基质中 engineered 出双亚稳态高密度陷阱，实现可见光激发下的稳定红色发光。该材料在468nm激发下产生620nm的强红光，其发射强度与商用材料在紫外线照射下相当，并展现出涵盖红光余辉及光/热/机械响应的多模态发光特性。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["发光特性[Eu2+和Dy3+共掺杂SrZnOS]: 多模态红色发光","[微观结构设计]: 构建可逆的微小光电化学层状微型单元电池结构","[陷阱状态]: 高密度双亚稳态陷阱"]},{"i":40433,"as":"金属有机框架（MOFs）的性能高度依赖于其形态。本研究以沸石咪唑酯骨架（ZIFs）为模型，通过简单调整前体条件实现了钴基MOF的多功能形态控制，为优化比表面积、活性位点可及性和吸附容量提供了有效策略。","scd":{"b":4.5,"i":2.0,"r":5.0,"d":5.0,"t":4.0},"kp":["[形态控制]: 通过简单调整前体条件实现钴金属有机骨架的多功能形态控制以增强催化活性"]},{"i":40434,"as":"通过控制Er3+在BaYF5纳米晶体内的富集，开发出热结晶BaYF5:Yb,Er玻璃陶瓷，克服了上转换效率低和掺杂剂分布不均的问题。热结晶缩短了离子间距离，促进了Yb3+-Er3+协同敏化和Er3+-Er3+能量迁移，实现了超亮上转换发光，可用于超快、低能耗的全光数据编码和逻辑运算。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["材料[上转换发光玻璃陶瓷]: 热结晶BaYF5:Yb,Er","[超亮上转换实现机制]: 通过掺杂剂富集克服低上转换效率"]},{"i":40435,"as":"开发了一种无贵金属核壳催化剂Cu@CoFe2O4，可在单一系统中同时驱动阳极葡萄糖氧化和阴极析氢或葡萄糖加氢。在1M KOH和1.3V vs RHE条件下，葡萄糖转化率达97.5%，甲酸盐法拉第效率为91.2%，析氢法拉第效率达100%；在中性电解质中可将葡萄糖选择性还原为山梨醇。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":8.0,"t":5.0},"kp":["催化剂[生物质葡萄糖转化及析氢]: 无贵金属核壳结构Cu@CoFe2O4","葡萄糖转化率[1 M KOH碱性条件]: 97.5%"]},{"i":40436,"as":"分析海湾国家气温上升对电力需求的推动作用，以及气候与电力系统间的关系。","scd":{"b":1.5,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["影响关系[海湾国家气温上升]: 推动电力需求增长"]},{"i":40437,"as":"研究探讨在可变电价机制下，消费者可能面临利益受损的具体条件与情境。","scd":{"b":1.5,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["研究核心[可变电价机制]: 探讨消费者利益受损的具体条件与情境"]},{"i":40438,"as":"合成了一种嵌入反芳香族环辛四烯（COT）单元的BODIPY稠合纳米石墨烯（BNG2）。X射线晶体学证实其具有对映异构双螺旋结构。由于COT单元显著的抗芳香特性，该纳米石墨烯在紫外-可见-近红外（NIR-II，1000-1700nm）区域展现出强烈的吸收和手性光学响应，在生物成像和光探测器领域具应用潜力。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["光谱响应区域[反芳香族环辛四烯嵌入/BODIPY 稠合纳米石墨烯]: 1000-1700 nm"]},{"i":40439,"as":"受光合作用系统II中氢键网络质子传递功能的启发，利用万古霉素衍生碳点在CoFe层状双氢氧化物（LDH）电催化剂上构建了人工质子转移通道。动力学同位素效应测量表明，该碳点网络有效引导了质子耦合电子转移（PCET）机制，将水氧化反应的动力学同位素效应从初级（2.00）转变为次级（≤1.49），实现了可持续控制。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["催化剂[OER人工质子转移路径]: CoFe层状双氢氧化物电催化剂(LDH)","介体材料[OER质子耦合电子转移]: 万古霉素衍生碳点"]},{"i":40440,"as":"提出一种可扩展的全硅胶机械变色弹性体（ASMCE）用于智能窗户。该设计通过微米孔散射策略实现了可见光至近红外光谱的宽带光学调制，在0-80%应变下实现了75.8%的超高太阳光调制能力（ΔTsol）。该智能窗户具备结构简单、响应迅速、静态零功耗及长期耐用的特点。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["功耗[机械变色智能窗户静态模式]: 零功耗","材料[全硅酮机械变色弹性体]: 具有宽带光学调制能力且耐用可扩展"]},{"i":40441,"as":"合成了一种管壁官能团可调的卟啉基共价有机框架（COF366）作为水系锌碘电池的碘正极宿主。羟基功能化的COF366-OH结合物理限域和路易斯酸碱相互作用，实现了52 wt%的高碘负载量，并显著提升了氧化还原反应动力学，有效改善了电池性能。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["宿主材料[水系锌碘电池碘正极]: 具有可调内壁官能团的卟啉基共价有机框架(COF366)"]},{"i":40442,"as":"基于层状两亲性嵌段共聚物薄膜开发出可再生杀菌表面。该薄膜由疏水可水解嵌段和经季铵化的亲水嵌段自组装而成。表面结合了阳离子杀菌作用，并在溶剂退火形成平行层状结构后，通过可控释放机制实现了快速响应和长期可重复使用的杀菌效果。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":6.0},"kp":["杀菌表面[可再生杀菌应用]: 结合接触杀灭与可控释放的层状结构双亲性二嵌段共聚物薄膜"]},{"i":40443,"as":"研究将致癌转录因子HOXB13微型化为金属钉合仿生物，该仿生物能以序列特异性和甲基敏感性的方式靶向结合DNA。利用V269X仿生物突变体分析发现，亮氨酸可通过与5-甲基胞嘧啶（5mC）的甲基-甲基接触及减少与胞嘧啶的甲基-π相互作用，进一步增强甲基敏感性和特异性。研究揭示了HOXB13与甲基化DNA之间分子相互作用的新机制。","scd":{"b":8.0,"i":2.0,"r":5.0,"d":6.0,"t":6.0},"kp":["DNA结合特性[微型化HOXB13拟似物]: 序列特异性且对甲基化敏感","材料[金属钉合HOXB13拟似体]: 5-甲基胞嘧啶(5mC)靶向识别剂"]},{"i":40444,"as":"硼中子捕获治疗（BNCT）是一种针对癌症的双靶向放射疗法，但受限于缺乏高性能硼递送剂。二十面体碳硼烷具有极高的硼密度和代谢稳定性，但其超疏水性阻碍了应用。研究开发了一类以硼为中心的碳硼烷基自由基，通过形成可扩展的B-B单键构建出双硼碳硼烷，作为多功能硼载体直接解决了疏水性、肿瘤靶向和修饰性受限的长期瓶颈，为BNCT提供了新型硼递送剂。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["载体材料[硼中子捕获治疗(BNCT)]: 具有高硼密度和优异代谢稳定性的二十面体碳硼烷"]},{"i":40445,"as":"针对甲烷光催化氧化偶联（OCM）中甲基自由基C-C偶联缓慢及过度氧化问题，研究开发了由SrTiO3覆盖层包覆的Au纳米颗粒催化剂（Au@SrTiO3）。SrTiO3载体与覆盖层捕获光生空穴以活化甲烷C-H键，使C-C偶联选择性提升至93%。该催化剂连续稳定运行超300小时，乙烷生成速率为155 μmol h-1，是无覆盖层Au/SrTiO3的7倍。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["催化剂[甲烷光催化氧化偶联(OCM)]: SrTiO3包覆的Au纳米颗粒(Au@SrTiO3)"]},{"i":40446,"as":"","scd":null,"kp":[]},{"i":40447,"as":"研究通过施加外部电场对双金属Ti2TaC2 MXene的近费米能级电子结构进行重构，增强了光电诱导的电荷转移和等离子体相关的电磁增强效应。这种电门控Ti2TaC2 SERS基底将罗丹明6G（R6G）的检测限降至10^-13 M，检测性能较单一光激发提升了三个数量级，为非贵金属高灵敏度分子传感提供了可调谐的新路径。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":8.0,"t":6.0},"kp":["最低检测限[外加电场双金属MXene(Ti2TaC2) SERS基底]: 10^-13 M","灵敏度提升[相对纯光激发]: 提升三个数量级"]},{"i":40448,"as":"主题为铝电解节能技术。内容回顾多物理场仿真与能耗预测等动态建模方法，探讨其在铝电解过程中提升能量优化效率的研究进展。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":4.0,"t":3.0},"kp":["优化方法[铝电解过程]: 多物理场仿真与能耗预测动态建模"]},{"i":40449,"as":"主题为水风光互补发电系统的可靠性。内容分析互补系统电力短缺的发生条件与时间模式，探讨其对电力规划的具体影响。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":4.0,"t":3.0},"kp":[]},{"i":40450,"as":"主题为印度能源转型与脱碳路径。内容构建多层次的系统模型，模拟通过部门耦合实现碳中和战略的未来能源演变情景。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":4.0,"t":3.0},"kp":["脱碳战略[印度能源转型]: 通过部门耦合实现碳中和的多层次系统模型模拟"]},{"i":40451,"as":"主题为燃料电池耐久性评估。探讨将原位监测的膜电极组件参数与外部特征相融合，用于质子交换膜燃料电池跨尺度寿命的评估方法。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":4.0,"t":4.0},"kp":["评估方法[质子交换膜燃料电池]: 融合原位监测膜电极组件参数与外部特征的跨尺度耐久性评估"]},{"i":40452,"as":"主题为配电网与电动汽车充电规划。内容提出一种随机规划框架，在考虑生态可持续性的前提下，优化不平衡电网中分布式能源充电站布局。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":4.0,"t":3.0},"kp":["[配电网规划]: 考虑生态可持续性的不平衡电网分布式能源电动汽车充电站随机规划框架"]},{"i":40453,"as":"主题为农业光伏在东非的应用。内容对农光互补系统进行技术经济性评估，并结合利益相关者观点分析其推广的可行性与效益。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":4.0,"t":3.0},"kp":["[农光互补系统]: 结合利益相关者观点进行技术经济性评估与可行性分析"]},{"i":40454,"as":"主题为城市电力系统脱碳。研究探讨在空间可再生能源受限和系统灵活性约束下，高密度城市脱碳的边际条件成本与碳排放范围。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":4.0,"t":3.0},"kp":["[城市电力系统脱碳]: 探讨空间可再生能源受限和系统灵活性约束下的边际条件成本与碳排放范围"]},{"i":40455,"as":"主题为电动汽车充电负荷预测。介绍一种混合注意力机制的序列到序列模型，通过融合气象与价格弹性因素提升充电负荷预测精度。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[电动汽车充电负荷预测]: 基于混合注意力机制的Seq2Seq模型，融合气象与价格弹性因素提升预测精度"]},{"i":40456,"as":"主题为充电模式对电网负荷的影响。运用可解释机器学习算法，分析不同类型车辆异构充电行为特征，评估其对城市电网负载的潜在冲击。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[城市电网负载评估]: 运用可解释机器学习算法分析不同类型车辆的异构充电行为及其潜在冲击"]},{"i":40457,"as":"研究合成了一系列以2,4,6-三甲酰基间苯三酚为受体、含不同数量末端氨基的氮杂环为给体的共价有机框架。其中，含2,4,6-三氨基嘧啶的COF在光催化水和氧气生成过氧化氢（H2O2）中表现出最高活性。光电化学测量和密度泛函理论计算揭示了该给体-受体结构在光催化太阳能转化为化学能过程中的高效机制。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["光催化剂[光催化产过氧化氢]: 由2,4,6-三甲酰基间苯三酚受体单元和含氮杂环构建的含嘧啶共价有机框架"]},{"i":40458,"as":"研究氢基炼钢与碳管理技术集成的效率驱动型经济性分析，聚焦绿色冶金的经济可行性。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[氢基炼钢]: 集成碳管理技术的效率驱动型经济性分析与绿色冶金可行性研究"]},{"i":40459,"as":"利用电池电压和电化学阻抗谱分析100kW质子交换膜水电解槽电堆性能不一致性，评估运行稳定性。","scd":{"b":5.0,"i":6.0,"r":6.0,"d":6.0,"t":5.0},"kp":["功率规模[质子交换膜水电解槽电堆]: 100kW","[性能评估方法]: 利用电池电压和电化学阻抗谱分析电堆电池性能不一致性及运行稳定性"]},{"i":40460,"as":"","scd":null,"kp":[]},{"i":40461,"as":"","scd":null,"kp":[]},{"i":40462,"as":"哺乳动物细胞因杨氏模量低而对机械和环境应力极其敏感。研究开发了一种低温休眠硅化策略，利用低温休眠期细胞膜短暂的通透性，使硅酸在胞内积累并发生蛋白质介导的缩合，形成覆盖细胞的无定形二氧化硅网络。该技术在不破坏细胞存活率和增殖能力的前提下，实现了无机硅与活体哺乳动物细胞的深度整合，显著增强了细胞的非生理环境抗性。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["杨氏模量[哺乳动物细胞]: 0.1~10.0 kPa (取决于F-肌动蛋白细胞骨架组织)","[非遗传功能连续性策略]: 低温休眠硅化策略实现无机二氧化硅增强在活细胞内的深度集成"]},{"i":40463,"as":"研究证明，基于大语言模型的全自动AI分析师能够低成本、大规模地复现人类多元化数据分析研究中出现的结论分歧现象。在该框架中，每个AI分析师针对同一固定数据集和假设独立执行完整分析流程，另由AI审计员检查方法有效性。测试表明，AI分析师生成的分析在效应大小上表现出显著的离散性，揭示了分析决策对实证结论的重要影响。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["AI分析师[基于大语言模型]: 能够低成本、大规模地产生与人类独立团队相同的分析发散性"]},{"i":40464,"as":"","scd":null,"kp":[]},{"i":40465,"as":"植物茉莉酸信号通路会促进高代谢成本的防御反应，引发生长与防御的权衡。研究鉴定出细胞周期蛋白依赖性激酶8（CDK8）是协调这一过程的转录调控因子。在拟南芥中，CDK8在茉莉酸信号增强时抑制植物生长并降低种子产量，同时根据硫元素的可用性调节免疫反应。转录组和代谢物分析表明，CDK8能放大茉莉酸触发的免疫和硫反应性防御机制。","scd":{"b":5.0,"i":1.0,"r":5.0,"d":4.0,"t":4.0},"kp":["CDK8[拟南芥茉莉酸信号通路]: 作为转录调控因子抑制生长并降低条件下的种子产量"]},{"i":40466,"as":"","scd":null,"kp":[]},{"i":40467,"as":"","scd":null,"kp":[]},{"i":40468,"as":"","scd":null,"kp":[]},{"i":40469,"as":"针对刚性折纸由几何约束引发的自由度及运动路径等非直观运动学特征，研究开发了一个通用移动性分析框架。通过解析推导至四阶的运动学相容性条件，明确了高阶相容性分析在确定刚性可折叠性中的作用。具备无穷小机制的折纸结构被严格划分为规则折纸、分叉折纸和摇摆折纸三类，有效揭示了复杂折纸结构的运动学特性。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[刚性折纸通用移动性分析框架]: 首先分析推导出运动学兼容性条件以揭示不确定的运动学特征（包括自由度数量及复杂构型下的运动路径）"]},{"i":40470,"as":"","scd":null,"kp":[]},{"i":40471,"as":"","scd":null,"kp":[]},{"i":40472,"as":"","scd":null,"kp":[]},{"i":40473,"as":"","scd":null,"kp":[]},{"i":40474,"as":"传统光镊在介观尺度和脆弱生物样本操作中，受限于基底粘附和摩擦力，需要极高的激光功率从而损伤样本。研究开发了介电悬浮光镊（DL-OT），将交流介电悬浮与光阱相结合。利用负介电泳（n-DEP）主动抵消法向力，DL-OT消除了固-固接触和近壁粘滞阻力，从根本上克服了传统光镊的瓶颈，实现了安全、强大的介观生物操控。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["介电悬浮光镊(DL-OT)[介观生物操控]: 集成交流介电悬浮功能以克服基底摩擦和粘附损伤"]},{"i":40475,"as":"为了解决类器官形态发生中异质性高且缺乏时空控制的问题，研究提出一种基于材料的策略。该策略利用光可调聚乙二醇（PEG）水凝胶，通过时空控制机制优化培养条件，成功实现了人类肠道类器官（HIOs）的确定性隐窝形成。该方法能够精确控制细胞外微环境，生成具有可预测隐窝形态和细胞组成的类器官，且各项特征与体内组织高度一致。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["基质软化策略[人类肠道类器官隐窝形成]: 实现对形态发生的时空控制并降低异质性"]},{"i":40476,"as":"","scd":null,"kp":[]},{"i":40477,"as":"","scd":null,"kp":[]},{"i":40478,"as":"","scd":null,"kp":[]},{"i":40479,"as":"","scd":null,"kp":[]},{"i":40480,"as":"","scd":null,"kp":[]},{"i":40481,"as":"针对Wendelstein 7-X中湍流减少、具有高密度梯度、中等温度梯度和低等离子体β的放电现象，回旋动理学模拟表明，微撕裂模式（MTM）湍流主导了该条件下的物质输运。模拟得出的热流和粒子通量与实验测量结果完全吻合，证实了微撕裂湍流在特定高密度梯度等离子体传输过程中的关键作用。","scd":{"b":8.0,"i":6.0,"r":8.0,"d":7.0,"t":9.0},"kp":["微撕裂模式湍流[Wendelstein 7-X高密度梯度低等离子体beta放电]: 主导热和粒子的输运过程"]},{"i":40482,"as":"","scd":null,"kp":[]},{"i":40483,"as":"","scd":null,"kp":[]},{"i":40484,"as":"针对软薄膜材料的深度压痕测试，研究指出硬质基底效应会导致薄膜测量的表观刚度被放大数个数量级。传统解释压痕的“10%规则”在深压痕条件下不再适用。研究重新评估了带有刚性基底的软薄膜（如生物细胞或软涂层）的力学机制，为精确解析超深压痕实验数据提供了修正方案和理论指导。","scd":null,"kp":[]},{"i":40485,"as":"基于经验性耦合道模型计算俘获截面，并结合统计模型计算存活概率，研究采用双核系统模型对超重元素116的合成过程进行了详细的理论计算。理论结果系统性地重现了超重核合成的实验数据，为未来超重元素的合成与机制探索提供了关键的理论预测依据。","scd":{"b":7.0,"i":1.0,"r":7.0,"d":6.0,"t":9.0},"kp":["超重元素116合成[双核系统模型]: 结合经验耦合通道模型与统计模型系统重现捕获截面和存活概率"]},{"i":40486,"as":"研究实现了基于铝-27、镱-171和锶-87的光学原子钟之间的高精度频率比测量。测量的总分数不确定性达到或低于3.2×10^-18。这一测量精度满足了对秒进行重新定义的重要里程碑标准，标志着光学原子钟在时间频率基准领域的重大技术突破。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":9.0,"t":8.0},"kp":["频率比测量总分数不确定性[基于Al+、Yb和Sr的光学原子钟]: ≤3.2×10^-18"]},{"i":40487,"as":"","scd":null,"kp":[]},{"i":40488,"as":"","scd":null,"kp":[]},{"i":40489,"as":"","scd":null,"kp":[]},{"i":40490,"as":"","scd":null,"kp":[]},{"i":40491,"as":"研究在锂取代的NaNbO3材料中发现了一种通过极化态重构来调控铁电性质的新几何途径。结合第一性原理密度泛函理论计算和锂-7固态核磁共振技术，研究证实热驱动可以诱导材料中共存的极化态发生重构。这一几何机制为新型铁电材料的设计和物理性能调控提供了新策略。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":8.0},"kp":["铁电性质调控[Li取代NaNbO3]: 通过热驱动的极化态重构实现几何调控路径"]},{"i":40492,"as":"经典热力学认为热量自发从高温流向低温，而研究发现在具有不确定因果顺序的量子过程中，热量可以发生反常流动。研究展示了当量子系统经历两次具有不确定因果顺序的热化过程时，构建的量子奥托发动机能够打破经典热力学的方向性限制。这一发现揭示了量子因果不确定性与热力学反常现象之间的直接联系。","scd":{"b":9.0,"i":1.0,"r":7.0,"d":5.0,"t":8.0},"kp":["量子奥托发动机[具有不确定因果顺序的热化过程]: 产生反常热流（自发从低温流向高温）"]},{"i":40493,"as":"针对分子时间分辨EPR信号的手性诱导自旋选择性（CISS）效应，研究提出了一种类自旋界面微观机制。在供体-手性桥-受体（D-χB-A）复合物中，基于双电子Lindblad模型，光激发电荷转移电子在手性桥中穿梭时，与充当局域磁矩的残余供体电子发生交换。该机制在不依赖金属界面的条件下，准确定量地重现了实验中观测到的自旋极化现象。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":6.0,"t":7.0},"kp":["手性诱导自旋选择性效应[供体-手性桥-受体复合物]: 产生定量解释时间分辨EPR信号差异的类分子内自旋界面机制"]},{"i":40494,"as":"为了深入理解三元纳米颗粒的形成机制，研究利用温度分辨X射线散射和显微光谱等技术，探究了Cu3-xP与二苄基二硒化物（Bn2Se2）反应形成Cu3PSe4纳米颗粒的过程。研究发现Cu3-xP通过表面与Se配位导致碎裂并重排为Cu-Se二元相；部分被氧化的P先形成P-Se键，随后才最终结晶生成Cu3PSe4，明确了中间相的无序演化特征。","scd":{"b":5.0,"i":2.0,"r":7.0,"d":8.0,"t":7.0},"kp":["[三元纳米颗粒合成]: 由Cu3-xP和二苄基二硒化物反应形成胶体Cu3PSe4纳米颗粒","[中间体演化机制]: Se表面配位导致Cu3-xP发生碎裂化"]},{"i":40495,"as":"","scd":null,"kp":[]},{"i":40496,"as":"","scd":null,"kp":[]},{"i":40497,"as":"研究在Alcator C-Mod托卡马克装置上利用实验数据库和预测模型，分析了ELMy和EDA H模式转换中的等离子体与中性粒子传输特性。高分辨率测量表明，台基密度和分离线密度对中性粒子源的响应机制在不同H模式下存在差异，且EDA模式中的准相干结构表现得更为显著。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":7.0,"t":5.0},"kp":["等离子体模式[Alcator C-Mod]: ELMy H-mode 和 EDA H-mode","诊断方法[等离子体基座与分离线分析]: 高分辨率汤姆逊散射测量"]},{"i":40498,"as":"研究扩展了用于研究岛偏滤器物理的仿星器两点模型（STPM），以评估对流功率份额和目标板前功率耗散等因素的影响。研究发现，仿星器特有的扩散限制状态不利于排灰性能；增加对流功率份额对排灰尤为有害，而动量损失因子参数化也对排灰性能产生直接影响。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["输运模型[托卡马克偏滤器]: Stangeby两点模型","输运模型[仿星器偏滤器]: 仿星器两点模型(STPM)","再循环机制[仿星器]: 扩散限制机制(diffusion-limited regime)"]},{"i":40499,"as":"本文介绍了ITER电子回旋（EC）系统中上部发射器（UL）和容器外波导（EW）系统的最终设计方案。作为EC系统的核心组件，UL与EW主要负责等离子体加热、电流驱动以及磁流体动力学稳定，对于实现和维持核聚变所需的高温至关重要。据目前的ITER基准配置，欧洲贡献了4个UL和5套EW系统。这些系统在欧洲与ITER组织的采购协议框架下已完成最终设计阶段，并于2025年7月发布了最终设计文件包以供最终设计审查。该文件包核心包含设计说明档案等，标志着该关键系统的研发取得重要进展。","scd":{"b":6.0,"i":6.0,"r":6.0,"d":6.0,"t":6.0},"kp":["核心系统[ITER EC系统]: 电子回旋(EC)上部发射器(UL)和容器外波导(EW)","系统功能[ITER托卡马克核聚变]: 等离子体加热、电流驱动和磁流体力学稳定"]},{"i":40500,"as":"研究使用三维、自洽的通量驱动双流体GBS代码，首次对COMPASS托卡马克边缘进行了全尺寸湍流模拟。模拟结果基于标准L模式放电数据，涵盖了从外侧中平面到偏滤器区域的刮除层。结果显示，模拟与实验在多数可观测值的分布轮廓、幅度和涨落水平上取得了良好的一致性。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["仿真代码[COMPASS托卡马克边缘湍流]: 三维自洽通量驱动的双流体Global Braginskii Solver (GBS)代码","验证数据集[标准L-mode放电]: 结合四个诊断系统提供43个可观测分布图"]},{"i":40501,"as":"研究提出了一种光驱动光催化方法，利用异质半导体二氧化钛（TiO₂）纳米管，在温和的反应条件下实现炔烃与硝基芳烃的直接酰胺化反应。该方法具有高达95%的优异产率，能够形成碳-氮键，适用于合成制药相关的酰胺及对生物活性分子进行后期修饰。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["收率[光催化炔烃与硝基芳烃直接酰胺化]: 高达95%","[光催化剂]: 异质半导体TiO2纳米管"]},{"i":40502,"as":"针对传统薄片锐度测量耗时长、成本高且浪费材料等缺点，本研究提出了一种基于高剪切响应流体的非破坏性锐度评估方法。该方法采用定制的流体配方检测微米级边缘变化，建立了结合Hiemenz和Falkner-Skan解的阻力分解框架，并利用仿真预测真实流体行为，最终在专用实验平台上成功建立了边缘半径与切割阻力之间的关系模型。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["边缘检测灵敏度[流体法表征刀片锐度]: 微米级"]},{"i":40503,"as":"研究通过多组分共组装策略，成功合成了一种异金属铕-铋簇嵌入的抗钨酸盐材料。该材料在水溶液中展现出强烈的荧光发射，作为高灵敏度荧光传感器检测抗坏血酸时，实现了0.038 μM的低检测限，线性范围为40-200 μM。该材料还可结合智能手机辅助进行现场检测。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[传感材料]: 异金属EuIII-BiIII簇嵌入抗钨酸盐","[检测模式]: 双模式抗坏血酸检测（集成荧光传感和智能手机辅助现场检测）","[分子式]: (HDMEA)9 Na18H3{[Bi10Eu2(H2O)4(DMEA)2(H2OA)4W10O36][B-α-SbW9O33]6}·124H2O"]},{"i":40504,"as":"研究通过涉及1000多名参与者和121种双人对战棋盘游戏的大规模行为学研究，探讨了人们如何推理全新问题。结果表明，人们在首次接触新游戏或评估其公平性及趣味性时，展现出了系统性和适应性理性的决策能力，即使在未进行深入思考之前也是如此。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[认知机制]: 使用快速且平面的模拟对新游戏进行推理和决策"]},{"i":40505,"as":"针对传统单尺度微结构难以平衡柔性压力传感器高灵敏度与宽检测范围的问题，本研究提出了一种具有微/纳米协同效应的分层结构架构。结合飞秒激光加工和精密成型技术，实现了高质量、低成本和可扩展的结构制造，赋予了压力传感器优异的传感性能。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[界面微结构]: 激光诱导不规则分层界面结构","[器件性能]: 实现高灵敏度与宽检测范围的平衡"]},{"i":40506,"as":"受青蛙脚垫和章鱼吸盘启发，研究提出了一种在热缩片上生成负模板的新方法，用于构建图案可调的仿生多结构微针贴片（PBMMs）以促进伤口愈合。热缩片经热处理后能保留微结构并直接作为模板，大幅提升了制造速度和成本效益。集成的六边形框架和环形吸盘仿生结构赋予了贴片强大的粘附力。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[仿生灵感]: 仿青蛙脚垫和章鱼吸盘结构","[制备工艺]: 在收缩塑料上生成负模板以构建图案可调的仿生多结构微针贴片"]},{"i":40507,"as":"针对高感染性病毒气溶胶的捕获难题，研究开发了一种由掺杂钛酸钡的聚苯乙烯与聚多巴胺表面涂层协同结合的自供电静电纳米纤维膜。该纤维膜在高达15 L/min的流速下仍保持90%以上的捕获效率，突破了传统生物采样器的流速限制，可用于高效捕获并量化病毒气溶胶。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":5.0,"t":4.0},"kp":["目标气溶胶尺寸[病毒气溶胶]: <300 nm","[膜材料工艺]: 压电BaTiO3掺杂聚苯乙烯协同耦合静电粘合制备纳米纤维膜"]},{"i":40508,"as":"针对骨关节炎（OA）的致病机制，研究将白藜芦醇（Res）和具有超氧化物歧化酶（SOD）及过氧化氢酶（CAT）活性的铂纳米酶负载于金属有机框架（MOF）上，并修饰透明质酸（HA）合成了PMRH纳米颗粒。该纳米颗粒通过清除活性氧（ROS）并抑制Wnt/β-连环蛋白信号通路，有效改善了对早期骨关节炎的防治效果。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":5.0,"t":4.0},"kp":["[纳米酶催化活性]: 具有超氧化物歧化酶(SOD)和过氧化氢酶(CAT)活性","[治疗机制]: 调节微环境并抑制Wnt/β-Catenin通路","[药物载体]: 金属有机框架(MOF)"]},{"i":40509,"as":"针对钙钛矿多晶薄膜中固有缺陷和界面应变阻碍商业化的问题，研究提出了一种低温液体辅助振动应力消除（LTL-VSR）策略。该物理策略通过高频振动诱导空化崩溃和共振晶格滑移，去除纳米级杂质、消灭离子空位，使残余应力降低十倍以上且无热损伤，从而显著提升钙钛矿太阳能电池的效率和稳定性。","scd":{"b":6.0,"i":4.0,"r":4.0,"d":5.0,"t":4.0},"kp":["[应力消除策略]: 低温液体辅助振动应力消除(LTL-VSR)","[工艺效果]: 直接解决多晶薄膜材料退化的根本原因（本征缺陷和界面应变）"]},{"i":40510,"as":"研究通过在聚丙烯酸（PAA）基质中固定铜（Cu）原子形成双齿螯合，合成了具有高分散Cuδ+活性位点的PAA-Cu电催化剂。这种配位环境精确调节了Cu的局部电子结构并使其d带中心上移。密度泛函理论计算表明，稳定的Cuδ+位点能有效促进电催化CO2还原过程中的C-C偶联反应。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":5.0,"t":4.0},"kp":["活性位点[eCO2RR反应]: 高度分散且稳定的Cuδ+ (0 < δ < 1)","配位方式[PAA-Cu催化剂]: 双齿配位","选择性挑战[Cu基电催化剂]: 易于生成混合C2+产物导致乙醇选择性和产率较差"]},{"i":40511,"as":"研究针对有机电化学晶体管（OECTs）中单电容模型无法解释电解质性质影响性能的问题，提出了一种结合电容耦合和电阻分压的全新阻抗模型。该模型解释了电解质浓度对开态电流、关态电流、开关比和阈值电压的调制作用，并成功预测了高频信号下阈值电压的频率依赖性偏移。适当增加门电压可优化性能。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["性能影响参数[OECTs]: 电解质浓度","调控指标[电解质浓度调节]: 开态电流、关态电流(Ioff)、开关比和阈值电压(VT)","物理模型[有机电化学晶体管]: 基于阻抗的新型模型(解释电解质电压分配)"]},{"i":40512,"as":"一种纳米结构的金表面能够根据光子成对到达探测器的倾向（即量子统计特性）来对光进行过滤和分类。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":2.0,"t":4.0},"kp":["光滤波机制[纳米结构金表面]: 基于光子成对到达探测器趋势的量子统计"]},{"i":40513,"as":"数字虚拟人正在中国社会中承担多种角色，包括管理医院、开展讲座以及提供陪伴服务。然而，相关的法律体系目前正在努力跟进和适应这一技术的发展与广泛应用。","scd":{"b":2.0,"i":6.0,"r":3.0,"d":2.0,"t":5.0},"kp":["应用场景[人工智能化身]: 医院运营、讲座授课和提供情感陪伴"]},{"i":40514,"as":"研究表明，某些核苷酸能够充当“分子胶”，通过将蛋白质粘合在一起来控制细胞的代谢过程。这一发现引发了对细胞自然产生的其他小分子是否具备类似能力的探讨。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":2.0,"t":4.0},"kp":["生物学功能[核苷酸]: 作为“分子胶”控制代谢并感知自身丰度"]},{"i":40515,"as":"研究分析了复杂任务中43个皮质区域的神经元如何编码认知、感觉和运动变量。发现神经代码的结构具有尺度依赖性。在整个皮层尺度上，神经选择性是分类的，其跨区域组织方式反映了它们的解剖连接结构。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":["分析规模[大脑皮层表征]: 覆盖43个皮层区域的14,000+个单元","研究对象[神经计算]: 皮层神经元对认知、感觉和运动变量的分类编码特征"]},{"i":40516,"as":"基于钠离子的电池正在进入大规模量产阶段。相比传统锂电池，钠离子电池成本更低且安全性更高。这项技术有望在电动汽车及其他储能应用中成为锂离子电池的有效替代方案。","scd":{"b":5.0,"i":8.0,"r":4.0,"d":3.0,"t":5.0},"kp":["产业化状态[钠离子电池]: 正在进入大规模量产阶段","性能优势[钠离子电池对比锂电池]: 成本更低且安全性更高"]},{"i":40517,"as":"","scd":null,"kp":[]},{"i":40518,"as":"","scd":null,"kp":[]},{"i":40519,"as":"研究开发出由聚多巴胺支撑的复合氧化石墨烯膜(GOMs)，具有可调且稳定的层间距。该膜在干燥状态下的层间距低至5.9埃，在水环境中能够精确筛分水合半径差异小于0.1埃的铷离子和钾离子，实现了高达5320的铷钾分离因子。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["层间距[聚多巴胺支撑的复合氧化石墨烯膜]: 亚纳米级别且具有亚埃级可调性","材料特性[堆叠氧化石墨烯膜]: 结构坚固，实现快速且选择性的离子传输"]},{"i":40520,"as":"研究提出一种无催化剂的废塑料升级回收策略。该技术利用微滴界面原位生成的羟基自由基，在温和条件下将聚烯烃和橡胶等多种废塑料氧化裂解为羧酸（二酸）。该方法消除了催化剂失活等挑战，显著降低了技术门槛与成本。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["转化策略[废塑料升级回收]: 无催化剂","反应机制[微滴界面]: 原位生成羟基自由基以实现双键的氧化断裂"]},{"i":40521,"as":"针对肝细胞癌(HCC)，研究开展了表达显性负效TGFβ受体II的GPC3特异性装甲CAR T细胞(C-CAR031)的首次人体试验。36名晚期难治性HCC患者接受了四个剂量水平（0.75×10^6至4.0×10^6个细胞/公斤）的输注。部分患者报告出现细胞因子释放综合征。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":6.0,"t":6.0},"kp":["靶点[肝细胞癌]: 磷脂酰肌醇蛋白聚糖-3 (GPC3)","靶点[肿瘤微环境]: 转化生长因子-β (TGFβ)","改造技术[CAR T细胞]: 显性负性TGFβ受体II (dnTGFβRII)装甲","疗效[dnTGFβRII装甲CAR T细胞]: 增强抗肿瘤活性"]},{"i":40522,"as":"实验研究了70Zn原子核的光子强度函数(γSF)。发现70Zn原子核在激发态跃迁至低能态时，其γSF在低能区域表现出显著增强。这种低能增强特性对理解恒星中的元素合成机制以及原子核结构具有重要影响。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":6.0,"t":6.0},"kp":["[低能强化电磁特性]: 70Zn原子核低能区γSF增强性质尚未明确"]},{"i":40523,"as":"","scd":null,"kp":[]},{"i":40524,"as":"在由菱面体四层石墨烯和伯纳尔双层石墨烯组成的莫尔平带系统中，发现了丰富的新型量子反常霍尔绝缘体。在填充因子v=1和v=3附近，实现了陈数从|C|=1到|C|=7的整数态；并在v=2/3附近观测到陈数为C=7/3的分数陈绝缘体。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":6.0,"t":6.0},"kp":["物理体系[分数陈绝缘体]: 扭曲菱形石墨烯(基于伯纳双层和菱面体四层石墨烯的莫尔平带系统)","研究意义[无磁场晶格系统]: 探索分数电荷激发和任意子统计"]},{"i":40525,"as":"","scd":null,"kp":[]},{"i":40526,"as":"","scd":null,"kp":[]},{"i":40527,"as":"","scd":null,"kp":[]},{"i":40528,"as":"研究提出原子尺度梯度应变工程概念，以Pd@Pt核壳四面体为模型系统，在3至4个原子层厚的Pt{111}晶格外延壳层中构建了从边缘到中心逐渐松弛的晶格应变梯度（约-8%至-2%）。这种单粒子应变梯度将高压缩位点的氧气活化与中度压缩位点的*OH减弱在空间上连接起来。","scd":{"b":8.5,"i":3.5,"r":6.0,"d":7.0,"t":6.0},"kp":["催化剂模型系统[高性能燃料电池单粒子应变工程]: Pd@Pt核壳四面体","设计概念[异质电催化剂原子级控制]: 原子尺度梯度应变"]},{"i":40529,"as":"研究钒液流电池分流管电解质平衡的建模、实验验证与控制方法，优化电池运行性能。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[钒液流电池]: 研究分流管电解质平衡的建模、实验验证与控制方法以优化运行性能"]},{"i":40530,"as":"研究为固态电池中的富锂锰基氧化物正极引入了一种基于硫脲衍生物的表面修饰策略。该策略有效解决了可逆性差、容量衰减和结构坍塌等问题，显著提升了电池性能，修饰后的正极初始放电容量达到220.2 mAh g⁻¹。","scd":{"b":7.5,"i":3.5,"r":6.0,"d":7.0,"t":6.0},"kp":["正极材料[固态电池]: 富锂锰基氧化物","表面涂层[解决高电位界面不稳定性及氧释放结构坍塌]: 硫脲衍生涂层"]},{"i":40531,"as":"研究开发了集成双光子与光声显微镜(TPM-PAM)技术。该系统利用透明微环谐振器超声波传感器，在清醒小鼠体内实现了对单个神经元钙活动与单个红细胞氧气释放的实时同步成像，能够精确量化单个红细胞的氧合水平、流动和氧气释放速率。","scd":{"b":8.0,"i":2.5,"r":6.0,"d":7.0,"t":6.0},"kp":["检测系统[在体单细胞神经代谢成像]: 集成双光子和光声显微镜(TPM-PAM)","[单细胞分辨率的实时动态]: 同步成像单神经元钙活动与红细胞氧气释放"]},{"i":40532,"as":"研究开发了基于分子胶的PROTAC技术(MGPROTAC)，将分子胶稳定剂与VHL配体结合，靶向捕获14-3-3/雌激素受体α(ERα)复合物。冷冻电镜揭示了全新的VHL与14-3-3ζ接触面，该策略成功诱导了部分无序的ERα蛋白的泛素化与降解。","scd":{"b":8.5,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["技术策略[靶向无明确结合口袋的蛋白]: MGPROTAC（分子胶-PROTAC偶联物）","作用机制[雌激素受体α泛素化]: 捕获14-3-3/ERα复合物并促进合作性复合物形成与靶向泛素化"]},{"i":40533,"as":"小麦寡糖转移酶TaOST1B与小麦黄花叶病毒(WYMV)编码的P1蛋白相互作用，通过糖基化P1第116位的天冬酰胺残基来增强其RNA沉默抑制功能。这促使P1在细胞核内大量积累并阻断钙调素结合，从而促进病毒感染。而未糖基化的P1则会失去功能并被26S蛋白酶体降解。","scd":{"b":7.5,"i":2.5,"r":6.0,"d":7.0,"t":6.0},"kp":["宿主因子[小麦黄花叶病毒感染]: 寡糖转移酶TaOST1B","作用靶点[增强P1的RNA沉默抑制功能]: P1第116位天冬酰胺残基N-糖基化修饰"]},{"i":40534,"as":"研究发现，口服肠道菌群代谢物丁酸盐可诱导CD4⁺ T细胞持续产生白细胞介素-10(IL-10)，从而建立起持久的肠道免疫耐受。这种免疫调节作用在停药后仍能提供长效的肠道炎症保护，并在无菌小鼠中同样观察到了丁酸盐建立的肠道条件性免疫环境。","scd":{"b":7.5,"i":2.5,"r":6.0,"d":6.0,"t":6.0},"kp":["代谢物干预[肠道免疫耐受]: 口服肠道微生物代谢物丁酸盐","[上皮-T细胞串扰]: 丁酸盐表观遗传学许可持续的上皮-T细胞相互作用以维持稳态"]},{"i":40535,"as":"研究提出了名为CenSegNet的深度学习框架，用于对异质组织中的中心体进行高通量分割和表型分析。将其应用于127名患者的911个乳腺癌组织微阵列核心，实现了对中心体异常的定量分析，发现数量和结构异常的亚型在空间分布与预后特征上表现出明显的解耦机制。","scd":null,"kp":["深度学习框架[高通量中心体表型分析]: CenSegNet","[上皮癌中心体异常]: 提供跨成像模态的空间和单细胞分辨率精准分割与表型分析"]},{"i":40536,"as":"","scd":null,"kp":[]},{"i":40537,"as":"","scd":null,"kp":[]},{"i":40538,"as":"","scd":null,"kp":[]},{"i":40539,"as":"","scd":null,"kp":[]},{"i":40540,"as":"","scd":null,"kp":[]},{"i":40541,"as":"研究开发了一种名为ADAPT-M的微流控定量分析工作流程，能够在一周内直接从富集的展示文库中快速、并行测量蛋白质的结合亲和力和解离行为。该技术无需基因合成和人工蛋白质纯化。在针对新冠病毒Omicron BA.1受体结合域的计算设计文库应用中，ADAPT-M成功筛选出高富集变体，并揭示许多富集的结合剂实际缺乏真正的结合能力。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["分析工作流[富集蛋白质库的定量体外测量]: ADAPT-M","[结合亲和力与解离行为]: 直接从富集展示文库中进行快速、平行的微流控定量表征"]},{"i":40542,"as":"","scd":null,"kp":[]},{"i":40543,"as":"","scd":null,"kp":[]},{"i":40544,"as":"","scd":null,"kp":[]},{"i":40545,"as":"","scd":null,"kp":[]},{"i":40546,"as":"","scd":null,"kp":[]},{"i":40547,"as":"","scd":null,"kp":[]},{"i":40548,"as":"","scd":null,"kp":[]},{"i":40549,"as":"","scd":null,"kp":[]},{"i":40550,"as":"","scd":null,"kp":[]},{"i":40551,"as":"探讨通过孔静电重建离子共价有机框架，以提升锂离子传输效率和界面稳定性的技术机制。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":3.0,"t":5.0},"kp":["[离子共价有机框架(COF)]: 通过孔静电重建提升锂离子传输效率和界面稳定性"]},{"i":40552,"as":"开发基于“支柱效应”稳定的层状氧化物钠离子电池正极材料，旨在提升材料空气稳定性与加工性能。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[钠离子电池正极材料]: 基于“支柱效应”稳定的层状氧化物，提升材料空气稳定性与加工性能"]},{"i":40553,"as":"通过机械信号分析方法，揭示磷酸铁锂电极内部存在的空间异质性特征，助力评估电极性能。","scd":{"b":5.5,"i":3.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[磷酸铁锂电极]: 存在空间异质性特征，可通过机械信号分析方法揭示"]},{"i":40554,"as":"利用数据驱动方法进行金属有机框架材料设计，以优化其在光电化学反应中的催化表现。","scd":{"b":6.5,"i":2.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[金属有机框架(MOFs)设计]: 采用数据驱动方法优化其在光电化学反应中的催化表现"]},{"i":40555,"as":"本年度的科维理纳米科学奖表彰了“转角电子学”领域的研究成果。这一奖项突显了简单的研究方法如何深刻地塑造和推动纳米科学领域的探索与发展。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[纳米科学研究范式]: 转向电子学(Twistronics)"]},{"i":40556,"as":"研究提出了一种结合固态交换核磁共振（NMR）和马尔可夫链分析的集成方法，用于多尺度定量分析聚合物电解质中的离子传输机制。该方法成功揭示了基于刚性聚阴离子的复合聚合物电解质中存在的快速且具有协同效应的锂离子传输路径。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["电解质[快速锂离子传输]: 基于刚性聚阴离子的复合聚合物","分析方法[多尺度量化锂离子传输路径贡献]: 固态交换核磁共振(NMR)结合马尔可夫链分析"]},{"i":40557,"as":"研究人员认为，批量生产适用于佩戴舒适型增强现实（AR）眼镜的波导元件在不久的将来将成为可能。这一技术进展有望推动AR技术的广泛普及和应用。","scd":{"b":3.0,"i":6.0,"r":3.0,"d":3.0,"t":4.0},"kp":["[AR眼镜光波导]: 即将具备大规模量产的技术可行性"]},{"i":40558,"as":"在豆科植物与根瘤菌共生过程中，大豆Qa-SNARE蛋白GmSYP111a是感染_thread_形成的关键调节因子。受体激酶GmSymRKβ在Ser-8和Ser-128位点磷酸化GmSYP111a，引发网格蛋白介导的内吞作用，导致复合物重新定位至细胞内囊泡。这种磷酸化与囊泡运输的直接耦合是触发豆科植物根瘤形成的关键机制。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":8.0,"t":7.0},"kp":["磷酸化位点[GmSymRKβ受体激酶介导的GmSYP111a蛋白]: Ser-8 和 Ser-128"]},{"i":40559,"as":"研究利用细菌、植物和哺乳动物数据集，对现有的纳米孔DNA甲基化检测工具进行了系统评估。结果表明，旧模型仍是研究CpG甲基化的可靠选择，而新模型在识别非CpG背景下的5-甲基胞嘧啶、6-甲基腺嘌呤和4-甲基胞嘧啶方面有显著提升。研究还评估了工具对甲基化干扰的敏感性、计算性能以及测序深度和甲基化丰度的影响。","scd":{"b":4.0,"i":5.0,"r":7.0,"d":7.0,"t":6.0},"kp":["检测模型选择[CpG甲基化研究]: 较旧的模型仍为可靠选择","性能表现[新型纳米孔甲基化检测模型]: 在其他碱基修饰检测上表现出显著优势"]},{"i":40560,"as":"人类FANCJ解旋酶负责解析DNA复制过程中停滞的G四链体（G4）结构。研究利用冷冻电镜技术解析了FANCJ与含G4的DNA底物及ATPγS结合的结构。结果显示，Fe-S结构域直接参与结合G4，结构引导的突变实验证实该界面对于G4的结合与解旋至关重要。此外，结构捕捉了与ATP水解相关的开放和闭合构象状态，揭示了其沿5'单链DNA进行定向转位的分子机制。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":8.0,"t":7.0},"kp":["复合物结构[人源FANCJ结合含G4的DNA底物及ATPγS]: 解析了揭示G4识别和解旋机制的冷冻电镜结构","核心生物学功能[复制叉停滞处的FANCJ解旋酶]: 解析G4结构以维持基因组稳定"]},{"i":40561,"as":"单电子转移（SET）还原是有机化合物激活的基本策略。传统SET反应的选择性取决于底物的氧化还原电位，难以还原热力学不利的底物。本研究提出一种脱离底物氧化还原电位限制的全新选择性范式，利用超强光还原剂进行外层SET反应。该策略使得原本难以还原的反应物发生选择性反应，解决了热力学上难以实现氧化还原的底物偶联反应难题。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["选择性控制机制[单电子转移(SET)还原反应]: 实现优先还原较难还原反应物的非传统选择性"]},{"i":40562,"as":"研究提出了一种基于单个霍尔传感器的可拉伸多模态变形传感器。该传感器无需依赖复杂的计算建模或机器学习算法，即可测量并区分拉伸、弯曲、扭转和按压等机械变形的大小与模式。其核心机制依赖于可拉伸磁性薄膜的特定布局设计。该技术有效避免了传统多模态传感器复杂的系统集成问题，为软体机器人和可拉伸电子设备提供了简化的智能感知方案。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["系统架构[单霍尔传感器]: 具备自模式识别能力的可拉伸多模态形变传感"]},{"i":40563,"as":"传统基于马赫-曾德尔干涉仪（MZI）的可编程光子处理器受限于波长无关路由，难以实现并行处理。本研究展示了一种支持波分复用（WDM）的多核并行可编程光子信号处理器。该架构采用可重构六边形网格，利用集成了过耦合微环谐振器的MZI作为波长选择性移相器。这些单元实现了1 THz的自由光谱范围和4.3 mW/π的调谐功率，成功突破了并行处理的瓶颈。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["光子处理器件架构[波分复用(WDM)技术]: 支持多核并行处理的可编程光子信号处理器"]},{"i":40564,"as":"针对静态纳米孔难以分离性质高度相似分子的问题，研究构建了一个描述纳米孔动力学控制传输与分离的预测性框架。研究表明，在波动的周期性电势中存在最佳的波动速率，该速率依赖于分子质量，从而将微小的质量差异转化为显著的动力学差异。结合软多孔晶体的量子化学能景，研究确定了决定选择性分离的两个关键因素：能垒波动的幅度以及纳米孔动力学与分子运动之间的对齐程度。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["质量选择性传输机制[动态纳米孔波动周期势场]: 在最佳波动速率下最大化扩散，该速率依赖于分子质量"]},{"i":40565,"as":"","scd":null,"kp":[]},{"i":40566,"as":"金属纳米团簇为揭示机械发光（ML）机制提供了理想模型。研究观察到结晶于非中心对称三方空间群的Cu7纳米团簇晶体在机械应力下发出明亮的绿光。通过压电实验和理论计算证实，晶体机械形变引发的突现压电效应导致了内部偶极子的不对称分布，从而驱动了机械发光现象。该发现阐明了原子级精确纳米团簇晶体中力致发光的物理机制。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["机械发光驱动力[原子级精确的Cu7纳米团簇晶体]: 突现压电效应"]},{"i":40567,"as":"针对异构体分离难题，研究通过氢键大环两亲性分子的动态适应正交组装，合理设计并构建了高度取向的多孔膜。大环分子在垂直方向发生亲水外壳的螺旋扩展，形成溶致液晶凝胶。通过对具有相同氢键的不相容孔隙进行同步控制，制备出排列良好的手性向列相结构。该膜有效克服了混合基质膜中聚合物与吸附剂兼容性差的问题，实现了高效分离。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["成膜策略[异孔结构混合基质膜]: 正交组装与可逆适应机制","分离性能[高定向多孔膜]: 实现具有合适渗透性和选择性的高效异构体分离"]},{"i":40568,"as":"研究结合结构分析、跃迁率测量和量子计算，探究了外延钒薄膜中氢的扩散行为。核反应分析表明，在单轴应变的β相中，氢迁移在约70K时始于八面体位点之间。通过监测由氢分布变化引起的电阻时间演变，实现了扩散系数的定量估算。研究阐明了晶体对称性降低（单轴应变）对氢量子隧道效应及扩散行为的具体影响，增进了对钒基材料储氢机制的理解。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["质子隧道效应影响机制[外延钒薄膜中氢扩散]: 降低晶体对称性可促进氢的量子隧穿行为"]},{"i":40569,"as":"非侵入式脑机接口（BCI）在学习效率和控测精度上存在挑战。研究提出一种整合人类运动学习与自适应机器学习的感觉引导联合学习框架。在31名无BCI经验参与者中，该框架实现了技能的快速获取，一维和二维运动想象任务的在线离散准确率分别达86.0%和77.5%，连续控制准确率为77.5%和66.9%。机制上，触觉引导减少了用户的动作探索，显著加速了控制技能的获取。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["受试者[无BCI经验 novice]: 31人","[脑机接口]: 感觉引导人机联合学习框架"]},{"i":40570,"as":"","scd":null,"kp":[]},{"i":40571,"as":"研究揭示了嘌呤核苷酸作为“代谢物胶”，将嘌呤生物合成的限速酶PPAT与其抑制剂NUDT5拴系在一起的机制。这种作用使细胞能够感知嘌呤水平并建立合成的反馈控制。自20世纪50年代使用的硫嘌呤类化疗药物也能胶合相同的复合物，但采用了不同的分子取向以增强其功能。这一发现证实了分子胶在人类细胞中提供内源性调节的作用。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["分子胶[人源细胞内源调控]: 嘌呤核苷酸","[抑制机制]: 嘌呤核苷酸系结嘌呤生物合成限速酶PPAT及其抑制剂NUDT5"]},{"i":40572,"as":"","scd":null,"kp":[]},{"i":40573,"as":"研究证明了机械超材料的断裂行为可以通过利用弹性不稳定性进行主动编程。研究结合了多尺度实验与理论，展示了如何通过设计引发弹性失稳来桥接材料传统的失效模式。这一方法突破了以往仅被动表征传统晶格结构断裂性能的局限，为设计具有高断裂阻力和定制化力学性能的抗断裂材料提供了全新的可编程平台。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["断裂阻力[机械超材料]: 通过弹性不稳定性进行编程设计"]},{"i":40574,"as":"研究提出一种准纯金属有机框架（MOF）膜（MOF体积占比超90%）的新型膜架构。该膜采用工业可靠的溶液加工技术实现规模化制造，分离性能接近纯MOF膜。其核心在于一种融合相方法，将MOF与聚合物融合为单一伪连续相，赋予MOF类似聚合物的表面特性，允许进行流变学控制的加工。该技术有效解决了高能耗气体分离中MOF膜规模化应用的瓶颈。","scd":{"b":7.0,"i":6.0,"r":7.0,"d":7.0,"t":6.0},"kp":["MOF含量[准纯MOF膜]: >90 vol%","[成膜工艺]: 行业可靠的溶液加工技术"]},{"i":40575,"as":"研究提出了一种用于可逆质子陶瓷电池氧电极的自旋配位混合价传输设计原理。通过在Pr0.5Ba0.5Co0.7Fe0.3O3-δ（PBCF）中引入铟，诱导钴（Co）的选择性迁移和界面尖晶石相重排，自组装形成Co3O4尖晶石层。这种异质界面工程不仅增加了活性位点，还将体相电荷传输与界面氧化还原动力学本征耦合，驱动了体相自旋-价态的重构，从而显著提升了电催化效率。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["异质界面[可逆质子陶瓷电池氧电极]: 钙钛矿-尖晶石相","[诱导元素]: 铟","[电催化机制]: 自旋配位混合价传输"]},{"i":40576,"as":"针对金属氮化物因强共价键导致合成需要高温的难题，研究开发了一种通过氨气压力控制熔盐合成胶体金属氮化物的新方法。该方法利用氨气压力进行调节，成功在熔盐体系中实现了结晶金属氮化物（如GaN、TiN）的合成。该技术为光电子、能源和医疗等领域的金属氮化物材料提供了一种条件温和且可控的胶体合成途径。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["合成路径[熔盐中胶体金属氮化物]: 氨压力控制"]},{"i":40577,"as":"拓扑量子计算通过编织非阿贝尔任意子来实现量子门，但最简单的非阿贝尔推广无法仅靠编织实现通用计算。研究证明，将任意子融合作为计算原语，能够使这些最小非阿贝尔拓扑有序态实现通用性。研究在量子硬件上制备了S3量子双倍的54比特基态，成功演示了通过编织和融合任意子操作来实现通用量子门，为拓扑量子计算提供了可行路径。","scd":{"b":9.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["通用门[量子计算]: 编织和融合非阿贝尔任意子"]},{"i":40578,"as":"研究利用10米分辨率卫星影像和机器学习技术，绘制了38个欧洲国家的六类半天然开放湿地类型及土地扰动分布图。结果显示欧洲湿地高度破碎，约27-33%位于小斑块中，且相对于未受干扰的基线估计有大量土壤碳流失。将受扰动面积转化为欧盟《自然恢复法》的恢复目标后，发现部分国家的国家承诺与实际所需的恢复面积基本一致，但整体恢复需求分布不均。","scd":{"b":4.0,"i":5.0,"r":7.0,"d":8.0,"t":6.0},"kp":["恢复目标[欧盟湿地]: 到2030年恢复至少30%未处于良好状态的湿地生态系统","[空间测绘技术]: 10米分辨率卫星图像与机器学习"]},{"i":40579,"as":"","scd":null,"kp":[]},{"i":40580,"as":"抗体偶联药物(ADCs)通过向肿瘤细胞选择性递送细胞毒性剂推动了癌症治疗，但其疗效受限于对单一靶抗原的依赖，导致对异质性肿瘤靶向受限并产生耐药性。本研究提出一种体内生物正交连接策略，通过系统给药生成功能性抗体-ADC点击构建体。该平台将治疗性抗体和ADC与反式环辛烯和四嗪部分偶联，通过顺序给药实现体内连接，为异质性肿瘤的增强靶向药物递送提供模块化方案。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["偶联策略[抗体-药物偶联物 ADC]: 体内生物正交点击化学","[逆转耐药性]: 模块化体内抗体-ADC点击构建体"]},{"i":40581,"as":"","scd":null,"kp":[]},{"i":40582,"as":"岛屿国家对实现联合国可持续发展目标7至关重要，但其能源转型的可行性尚不明确。基于对1800多个有人居住岛屿的高分辨率评估及5000万份小时需求与可再生资源记录，研究表明许多岛屿无法实现具有弹性的低碳电力系统。超过一半的岛屿面临高于可负担阈值的转型成本，主要集中在东南亚、沿海非洲和西太平洋。增加气候韧性要求使7%的岛屿进入更高成本类别。预计到2050年，技术进步可使电力平准化成本降低约4%。","scd":{"b":5.0,"i":4.0,"r":8.0,"d":9.0,"t":5.0},"kp":["评估样本[弹性能源岛屿]: 超1800个有人居住岛屿","[基础数据]: 5000万条需求和可再生资源的小时记录","[转型经济障碍]: 超过一半岛屿面临高于其基于收入的负担能力的转型成本"]},{"i":40583,"as":"广泛观测突出了萜类化合物对城市空气质量的重要性，但现有排放框架无法准确捕捉其排放量和空间变异性。研究结合改进的排放清单、机载通量测量和地面移动测量，协调了观测和模拟的城市萜类排放量，在大洛杉矶地区发现了强烈的、未被充分代表的人为排放源。增强的生物源清单显著缩小了异戊二烯通量的模型与观测差距，而单萜烯的剩余差距主要由人为部门解释，这些排放源自此前被忽视的食品工业。","scd":{"b":5.0,"i":4.0,"r":7.0,"d":8.0,"t":5.0},"kp":["城市萜类化合物排放源[洛杉矶地区]: 强烈的、未被充分表征的人为排放源"]},{"i":40584,"as":"","scd":null,"kp":[]},{"i":40585,"as":"","scd":null,"kp":[]},{"i":40586,"as":"","scd":null,"kp":[]},{"i":40587,"as":"","scd":null,"kp":[]},{"i":40588,"as":"","scd":null,"kp":[]},{"i":40589,"as":"由于出色的代谢稳定性，硫代磷酸酯基序被广泛视为天然磷酸基团的替代品，并应用于反义寡核苷酸等治疗模式。虽然可通过蛋白质激酶和ATPγS将硫代磷酸盐安装在蛋白质上，但该方法成本高昂且难以规模化。为此，研究发明了一种ATPγS回收策略，通过使用专门设计的试剂克服了需使用超化学计量昂贵ATPγS的局限性，使生物催化硫代磷酸化具备实用性。","scd":{"b":6.5,"i":4.0,"r":7.0,"d":6.0,"t":6.0},"kp":["硫代磷酸化修饰[蛋白质生物催化]: 蛋白激酶结合ATPγS (adenosine-5′-O-(3-thio-triphosphate))"]},{"i":40590,"as":"控制量子多体动力学的材料工程极具挑战性。本研究引入了量子统计等离子体超晶体，这是一种由光学近场介导的多粒子动力学产生禁忌量子统计带的结构，能够实现不同类型光的选择性透射。该功能源于由充当超原子的纳米天线组成的等离子体结构。统计在允许带内的多光子场可无畸变传播，而处于禁止带内的场则被抑制或驱动至最近的可达统计状态。这些能带由结构的几何形状决定。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":6.0},"kp":["量子统计等离子体超晶体[多粒子动力学]: 产生禁戒量子统计能带，实现对不同类型光的选择性透射"]},{"i":40591,"as":"粮食系统是突破地球边界的主要原因。研究表明，到2050年，向健康饮食（采用EAT-Lancet参考饮食）、提高生产力和将食物浪费减半的粮食系统转型将导致全球农业的根本性重组，部分趋势将与历史脱节。使用十个全球经济模型的多模型集合进行的情景模拟显示，农业系统将发生中位数为6%的重组变革。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["粮食系统转型影响时间[健康饮食导向]: 2050年"]},{"i":40592,"as":"","scd":null,"kp":[]},{"i":40593,"as":"传统机械系统依赖电子元件来存储和处理信息。本研究引入了一种气动忆阻器，通过利用弹性双稳定性，在单个机械装置中实现了记忆与计算的集成。由此产生的依赖于历史的压力-流动行为能够在无需电子元件的情况下实现可编程的机械逻辑，为自适应的非冯·诺依曼机械智能提供了新途径。","scd":{"b":9.0,"i":3.0,"r":7.0,"d":5.0,"t":6.0},"kp":["忆阻器类型[具有弹性多稳定性]: 气动忆阻器","计算与存储机制[集成内存与计算]: 单一机械装置","忆阻特性[利用弹性双稳态实现]: 历史依赖的压力-流量行为","逻辑器件[无电子元件可编程]: 可编程机械逻辑","系统架构[提供机械智能新途径]: 自适应、非冯·诺依曼架构"]},{"i":40594,"as":"分析不同生物原料对甲醇喷射制氢强化生物燃料工艺设计与技术经济性能的具体影响。","scd":{"b":5.0,"i":5.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[制氢强化生物燃料工艺]: 分析了不同生物原料对甲醇喷射工艺设计与技术经济性能的具体影响"]},{"i":40595,"as":"提出一种考虑风光互补与多重不确定性的虚拟电厂参与电力市场的两阶段分布式鲁棒竞价策略。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[虚拟电厂电力市场竞价]: 提出考虑风光互补与多重不确定性的两阶段分布式鲁棒竞价策略"]},{"i":40596,"as":"提出基于运行信息融合的混合储能电动拖拉机分级自适应能量管理策略，优化整车能效。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[混合储能电动拖拉机]: 提出基于运行信息融合的分级自适应能量管理策略以优化整车能效"]},{"i":40597,"as":"研究采用模型与数据驱动融合的方法，对实际磷酸铁锂电池组的充电状态（SOC）进行精准估算。","scd":{"b":4.0,"i":4.0,"r":4.0,"d":4.0,"t":4.0},"kp":["充电状态估算[磷酸铁锂电池组]: 采用模型与数据驱动融合方法进行精准估算"]},{"i":40598,"as":"探讨利用大语言模型指导能源系统拓扑重构的安全强化学习算法，提升系统运行的安全与效率。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["能源系统拓扑重构[大模型指导安全强化学习]: 提升系统运行的安全与效率"]},{"i":40599,"as":"评估一种用于地下深部冷却的无动力上流二氧化碳制冷系统，分析其热力学、经济与环境综合性能。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["制冷系统[地下深处冷却]: 采用无动力上流二氧化碳制冷系统"]},{"i":40600,"as":"","scd":null,"kp":[]},{"i":40601,"as":"纳米晶体超晶格通常通过改变浓度、溶剂条件或颗粒表面化学来形成，但这些方法同时改变了粒子间势能的多个因素。研究表明，纳米晶体反应介质中存在的低聚物通过耗散机制驱动超晶格的形成。以PbTe纳米晶体为模型系统，研究在粗反应混合物中确定了油酸铅低聚物，表征了其溶液结构，并量化了其对粒子间势能的贡献，确立了耗散作用是控制自发超晶格形成的主要短程相互作用。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["纳米晶体超晶格组装驱动力[反应介质]: 寡聚物物种通过耗竭机制驱动超晶格形成"]},{"i":40602,"as":"提出一种不确定性感知提取框架，为基于MILP的电力系统运行制定可信赖且感知风险的安全规则。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["安全规则制定[MILP电力系统运行]: 采用不确定性感知提取框架实现可信赖且感知风险"]},{"i":40603,"as":"分析电子燃料替代可大幅削减电池材料需求的优势，及其给英国净零交通目标带来的新挑战与困境。","scd":{"b":5.0,"i":4.0,"r":7.0,"d":6.0,"t":5.0},"kp":["材料需求削减倍数[电子燃料替代电池]: 9倍"]},{"i":40604,"as":"","scd":null,"kp":[]},{"i":40605,"as":"","scd":null,"kp":[]},{"i":40606,"as":"高分辨率、广色域显示器需要高效的蓝色发光二极管(LED)。研究人员通过添加能产生氢键网络的异构体分子来稳定钙钛矿晶体的八面体结构，成功制造出高效、稳定且色饱和度高的钙钛矿蓝色LED。这种由异构分子产生的氢键网络有效稳定了钙钛矿发光层。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["蓝色发光二极管[钙钛矿发光层稳定]: 添加同分异构体分子生成氢键网络，稳定八面体晶体结构"]},{"i":40607,"as":"水分解催化剂内建电场的成像难题阻碍了建立电子结构与催化行为之间的直接关系。研究以铁掺杂和氧空位(Ov)共修饰的钴镍双金属氧化物为模型，利用差分相位对比扫描透射电子显微镜，建立了Fe与Ov协同效应在原子级水平上增强内建电场的明确图像。异质Fe离子引入额外的电子传导通路以增强电场强度，而Ov则作为吸收站点吸引电子，导致局部电场显著增强，协同提升了析氧反应性能。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["水裂解催化剂[析氧反应增强]: 铁掺杂与氧空位(Ov)协同改性钴镍双金属氧化物"]},{"i":40608,"as":"本研究引入分子N,N'-二苯基硫脲（DPTA）精确控制电荷载体浓度和晶格生长，以工程化改造锡基钙钛矿半导体（CsSnI3）。结果表明，在1018 cm-3的载流子浓度下，其光致发光量子效率（PLQE）达到36%。高分辨率透射电子显微镜证实了该方法能实现均匀性，有效解决了高电流密度下发光二极管（LED）效率滚降的问题。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["近红外发光二极管[锡基钙钛矿半导体抑制效率滚降]: 引入分子N,N'-二苯基硫脲(DPTA)进行工程化修饰"]},{"i":40609,"as":"本研究设计了一种聚酮亚胺网络，能够在温和条件下无需消耗试剂或催化剂实现闭环回收，同时在使用期间保持稳健的机械性能。在分子层面，受阻酮亚胺键由于酮和胺反应物的空间位阻，具有足够的柔韧性以解聚成低聚物。该设计成功克服了聚合物网络高动态键与材料稳定性之间的权衡难题。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["聚酮亚胺网络[闭环可回收条件]: 温和条件下不消耗催化剂即可解聚实现闭环回收"]},{"i":40610,"as":"本研究调查了高分子量麦谷蛋白亚基1Dx5的N端结构域（1Dx5-NTD）的水合诱导缔合行为。水合后，1Dx5-NTD形成塌陷的异质集合体，并发生分子间缔合形成三聚体到约70000聚体的组装体。这些缔合主要由有利的焓相互作用决定，并受中等离子强度调节，揭示了面筋网络拓扑形成的分子原理。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["面筋网络拓扑[高分子量麦谷蛋白亚基1Dx5的水合行为]: 发生整体偏向的二硫化物化学交联协调形成多维网络"]},{"i":40611,"as":"本研究使用发光二维金属有机纳米片LMOF-601作为平台，探讨了蛋白质吸附与肽键水解之间的相互作用。LMOF-601的纳米片形态增强了表面可及性并最大程度减少了扩散限制，能够通过基于连接体的发光实时观察蛋白质与MOF的相互作用。研究成功将吸附过程与反应性水解过程解耦，阐明了不同理化性质的蛋白质在MOF界面的行为机制。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["催化活性[Zr基MOF]: 具有类蛋白酶活性","吸附与水解机制[发光二维金属有机纳米片LMOF-601]: 蛋白质展开控制肽键水解"]},{"i":40612,"as":"研究人员警告称，被“投毒”或篡改的信息数据集会欺骗并破坏自主分析数据的人工智能代理的可靠性。这表明数据安全直接决定人工智能工具决策的准确性与可信度。","scd":{"b":2.0,"i":4.0,"r":4.0,"d":2.0,"t":5.0},"kp":["[被篡改/投毒的信息]: 破坏自主分析数据工具的可靠性"]},{"i":40613,"as":"研究在软硬需求双重约束下，电动汽车车队如何通过优化调度以高效实现车辆到电网（V2G）服务。","scd":{"b":4.0,"i":4.0,"r":4.0,"d":3.0,"t":4.0},"kp":["优化调度[软硬需求约束电动汽车车队]: 高效实现车辆到电网（V2G）服务"]},{"i":40614,"as":"评估考虑可再生资源逆变器非线性耦合影响的电力系统暂态稳定性，为新能源电网安全运行提供参考。","scd":{"b":4.0,"i":4.0,"r":4.0,"d":3.0,"t":4.0},"kp":["暂态稳定性评估[新能源电网运行]: 需考虑可再生资源逆变器非线性耦合影响"]},{"i":40615,"as":"提出两阶段替代建模方法，利用卫星图像实时估算云层特性与地表向下长波辐射，助力气象能源分析。","scd":{"b":4.0,"i":4.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[卫星图像实时估算]: 两阶段替代建模方法，用于提取云层特性与地表向下长波辐射"]},{"i":40616,"as":"本研究利用多催化剂协同作用，实现了羧酸的脱二氧膦酰化反应。该反应适用于脂肪族和芳香族底物，具有广泛的底物范围和良好的官能团耐受性，并在复杂分子的后期修饰中表现优异。此外，该方案还建立了一种正式的脱氧偶联方法，能够从羧酸与醛或醇中快速获取烯烃。机理研究揭示了远程相互作用的关键机制。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":5.0,"t":4.0},"kp":["脱二氧膦酰化反应[多催化剂协同]: 适用于脂肪族和芳香族底物，具有良好普适性和官能团兼容性"]},{"i":40617,"as":"本研究结合分子动力学、3D-RISM溶剂化分析、炼金自由能计算和量子pKa位移预测等多种模拟方法，表征了SAMURI核酶催化位点特异性RNA烷基化的构象和电子因素。模拟表明，尽管SAMURI的整体折叠结构保持稳定，但其特定的局部构象和电子特征决定了其利用S-腺苷甲硫氨酸（SAM）或合成辅因子进行催化反应的活性机制。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":5.0,"t":4.0},"kp":["[SAMURI核酶催化的RNA烷基化反应]: 支持使用S-腺苷甲硫氨酸(SAM)或合成辅因子ProSeDMA实现RNA位点特异性化学修饰"]},{"i":40618,"as":"本研究表明，大环导向的超分子倾向可以强制产生分子内重原子效应，从而激活潜在的 自旋禁戒跃迁，实现高效的自敏化氧化反应。通过将含有醛和溴取代基的柔性客体封装在葫芦脲中，成功利用超分子限制实现了对自旋禁戒的系间窜越（ISC）过程的有效调控，证明了重原子效应是一种依赖于几何构象的超分子参数。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":5.0,"t":4.0},"kp":["[超分子限制控制激发态反应途径]: 重原子效应可作为依赖于几何构型的超分子参数调节系间窜越(ISC)"]},{"i":40619,"as":"本研究报道了两种新型钒簇[V2As17]3-和[V2Sb17]4-，它们包含由单个桥接原子连接的冠状VPn8单元。电喷雾电离质谱监测表明其生长路径涉及VPn8和短暂出现的VPn9单元。密度泛函理论计算揭示，其氧化还原活性轨道具有Pn-Pn反键特征，这两个团簇映射了连接完全分离的碎片与单个融合Pn17单元之间的势能面片段。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":6.0,"t":4.0},"kp":["[过渡金属团簇成核生长途径]: 监测到包含VPn8和VPn9单元的生长路径"]},{"i":40620,"as":"本研究提出了一种通过脉冲驱动配对电合成的氧化还原调节新范式。使用原子级有序的CuPd催化剂，在无隔膜电解池中以CH3OH和NO2-为原料。在周期性交替变化的优化脉冲电位（Ea = 1.3 V, ta = 10 s; Ec = -0.7 V, tc = 10 s）下，两极可同时合成甲酰胺。该系统打破了传统单极C-N偶合的限制，实现了高达85.6%的法拉第效率（FE）。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":7.0,"t":4.0},"kp":["合成策略[甲酰胺电合成]: 氧化还原调节中间管理的脉冲驱动配对电合成","[传统单极C-N偶联]: 存在对电极大量电子消耗导致法拉第效率和总电子利用率低的瓶颈"]},{"i":40621,"as":"","scd":null,"kp":[]},{"i":40622,"as":"本研究开发了一种前所未有的单铜接力双催化级联序列，用于高效构建独特的芳香族N-桥联[10]轮烯（NBA）框架（又称cycl[3,2,2]吖嗪）。该反应机制涉及铜催化的10π电环化反应，结合控制实验和密度泛函理论计算得到了验证。该合成方法具有广泛的官能团耐受性，并可扩展应用于不同的衍生物，克服了非苯环状共轭体系合成的挑战。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":5.0,"t":4.0},"kp":["合成方法[N-桥环烯]: 单铜继电器双催化级联序列"]},{"i":40623,"as":"","scd":null,"kp":[]},{"i":40624,"as":"提出提取电网感知代表日的方法，用于基于风险的配电网络托管容量进行快速分析与评估。","scd":{"b":4.0,"i":4.0,"r":3.0,"d":3.0,"t":3.0},"kp":["[配电网络托管容量快速分析]: 提取电网感知代表日进行基于风险的快速分析与评估"]},{"i":40625,"as":"构建使用动态更新时间融合变压器的框架，实现风力涡轮机在线状态监测与早期故障预警。","scd":{"b":4.0,"i":4.0,"r":3.0,"d":3.0,"t":3.0},"kp":["[风力涡轮机在线故障预警]: 构建使用动态更新时间融合变压器的框架实现状态监测与早期预警"]},{"i":40626,"as":"探讨通过思维链（CoT）推理对大语言模型进行两阶段微调的技术，以实现智能电网环境下的配电网故障服务恢复。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[配电网服务恢复]: 采用思维链(CoT)推理对大语言模型进行两阶段微调实现故障服务恢复"]},{"i":40627,"as":"研究质子交换膜燃料电池堆在两千小时重型恒流条件下的降解机制，重点分析PTFE驱动的多尺度协同效应。","scd":{"b":7.0,"i":5.0,"r":7.0,"d":7.0,"t":4.0},"kp":["恒流测试条件[PEMFC堆阴极气体扩散层降解机制]: 2000小时重型恒流工况","[降解驱动因素]: PTFE驱动的多尺度协同效应"]},{"i":40628,"as":"针对交互能源系统中响应不确定性的问题，提出基于悲观斯塔克尔伯格博弈方法的耦合鲁棒决策模型。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":["[交互能源系统鲁棒决策]: 提出基于悲观斯塔克尔伯格博弈方法的耦合决策模型以应对响应不确定性"]},{"i":40629,"as":"比较工业能源系统规划中多准则决策（MCDM）方法，为相关能源规划的稳健决策支持提供理论与技术对比。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":3.0},"kp":["[工业能源系统稳健规划]: 比较多准则决策(MCDM)方法以提供决策支持"]},{"i":40630,"as":"提出一种针对现实车队中处于分散充电阶段的锂离子电池健康状态（SOH）进行精准估计的方法与技术。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[分散充电阶段]: 提出针对现实车队中锂离子电池健康状态（SOH）的精准估计方法"]},{"i":40631,"as":"探讨偏远社区向净零排放的阶段性过渡路径，提出一种自适应的多阶段随机鲁棒优化方法以应对不确定性。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":3.0,"t":3.0},"kp":["优化方法[偏远社区向净零过渡]: 自适应多阶段随机鲁棒优化方法"]},{"i":40632,"as":"研究表明，格陵兰岛西南冰盖边缘每个消融季都会出现降低表面反照率并加速融化的“暗区”。结合实验室测量、物理和概率模型分析发现，该区域变暗主要是由冰尘物质的积累和冰柱的致密化驱动的，其次是微藻大量繁殖的发展。矿物粉尘颗粒物并不直接导致该区域变暗。","scd":{"b":6.0,"i":1.0,"r":8.0,"d":6.0,"t":4.0},"kp":["[格陵兰岛西南冰盖]: 地表过程导致表面反照率降低和融化速率增强，并形成暗区"]},{"i":40633,"as":"","scd":null,"kp":[]},{"i":40634,"as":"","scd":null,"kp":[]},{"i":40635,"as":"基于格陵兰冰盖的大体积粒雪空气样本，本研究首次重建了可追溯到20世纪90年代初的大气甲烷团簇同位素组成。测量表明，1993年左右的大气∆12CH2D2比2020年代中期低10 ± 2 per mil，这可能是过去一千年来的最低水平。这一同位素变化归因于工业时期全球甲烷排放受到前所未有的巨大人为扰动。","scd":{"b":7.0,"i":1.0,"r":9.0,"d":7.0,"t":4.0},"kp":["测量指标[格陵兰岛冰盖地下空气]: 团簇同位素组成(可追溯至20世纪90年代初)"]},{"i":40636,"as":"本研究证明了在薄膜元素流动铁磁体中存在狄拉克磁振子。通过研究原子级设计的六方密排钴薄膜，证实了此类结构中的磁振子与石墨烯中的狄拉克电子非常相似。这一发现突破了流动磁性机制和维度效应复杂性带来的局限，首次在3d薄层磁体中确立了狄拉克磁振子的存在。","scd":{"b":9.0,"i":1.5,"r":6.0,"d":5.0,"t":5.0},"kp":["准粒子特性[薄元素流动铁磁体]: 存在狄拉克磁振子"]},{"i":40637,"as":"本研究演示了一种基于存储于单个原子中的高维（HD）量子存储器或“量子比特”的光子量子网络。通过干涉和检测原子量子比特存储器发射的高维时间箱编码单光子，预示了成对原子量子比特能级之间最大纠缠的贝尔态。此方法将量子网络的纠缠成功比例提升至传统50%限制之上，并显著扩展了量子信息容量。","scd":{"b":9.0,"i":3.5,"r":6.0,"d":6.5,"t":5.0},"kp":["量子网络系统[高维量子存储器]: 基于存储于单个原子中的“qudits”实现","光子编码机制[高维量子网络]: 时间箱编码"]},{"i":40638,"as":"本研究设计了一种无线单片人工叶片，将隧穿氧化物钝化接触硅底部吸收体与缺陷控制的钒酸铋（BiVO4）顶部吸收体相结合，用于光化学联产氢气和化学品。通过互补能带结构扩展光收集，纳米多孔BiVO4和微金字塔硅确保了高光电压。表面富含氧空位的非晶BiVO4还原壳层改善了空穴传输和催化活性，实现了无偏压选择性的甘油氧化反应，使其能够作为独立的光化学器件运行。","scd":{"b":7.5,"i":3.5,"r":6.0,"d":7.0,"t":5.0},"kp":["人工叶片结构[无线单片叶子光化学联产]: 集成隧道氧化物钝化接触硅底部吸收体与缺陷控制的钒酸铋(BiVO4)顶部吸收体","高光电压机制[纳米孔BiVO4与微锥硅结合]: 确保高光电压"]},{"i":40639,"as":"隐藏的遗传变异（CGV）在正常条件下无症状，但在暴露时会破坏表型的稳定性。研究发现，在拟南芥中，替代性剪接作为一种渠道化机制来缓冲CGV。功能未知的基因HIKI1中的天然单核苷酸多态性表现为CGV，当SKIP基因功能受损时，会依赖遗传背景破坏胚胎发育的鲁棒性。","scd":null,"kp":["隐蔽遗传变异缓冲机制[拟南芥表型鲁棒性]: 可变剪接充当通道化机制"]},{"i":40640,"as":"","scd":null,"kp":[]},{"i":40641,"as":"本研究挑战了气候变暖导致洪水减少的普遍误解。传统日尺度数据掩盖了次降水强度的增加。在阿尔卑斯流域中，日径流预测系统性地低估了洪水变化。采用小时尺度数据时，由于次每日降水的加剧足以抵消融雪的减少，受积雪影响强烈的流域的洪水变化甚至可能由负转正。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["洪水预测误差机制[气候变暖下的洪水灾害评估]: 每日分辨率数据掩盖了次日至降雨加剧，导致河流流量预测系统性低估洪水变化"]},{"i":40642,"as":"生物通过生物钟适应季节变化，但其整合季节线索的分子机制尚不清楚。研究发现，在黑腹果蝇中，核心生物钟基因timeless (tim)的替代性剪接能够通过调节生物钟神经肽PDF的表达与活性来控制季节性反应。该发现揭示了tim基因剪接在介导昆虫季节适应中的关键作用。","scd":{"b":8.0,"i":1.5,"r":6.0,"d":5.0,"t":5.0},"kp":["季节适应调节机制[核心生物钟基因剪接]: 通过冬季门控机制实现"]},{"i":40643,"as":"有袋动物胚胎在极短妊娠期后出生，幼崽需立即使用提前发育的前肢爬行。对脂尾袋鼺和灰色短尾负鼠的研究表明，这种前肢形态发生的加速向上游延伸至侧板中胚层（LPM）形成的最早期。前肢场在相对独立于其他轴向结构的情况下被特化，揭示了侧板中胚层形态发生过程的灵活性。","scd":null,"kp":["肢体形态发生[有袋动物侧板中胚层]: 进化出极端加速以满足极短妊娠后前肢早熟发育的功能约束"]},{"i":40644,"as":"着丝粒周围异染色质确保染色体准确分离，由富含A/T的卫星DNA组成。利用杂交小鼠胚胎模型比较不同物种的卫星阵列发现，卫星DNA序列的变异影响着异染色质的形成、染色体乘客复合物（CPC）的募集以及与有丝分裂纺锤体的相互作用。特定A/T序列能募集PRC1，从而改变着丝粒周围的包装。","scd":{"b":8.0,"i":1.5,"r":6.0,"d":5.0,"t":5.0},"kp":["序列基础[着丝粒周围异染色质的形成与功能]: A/T富含型卫星DNA序列"]},{"i":40645,"as":"","scd":null,"kp":[]},{"i":40646,"as":"","scd":null,"kp":[]},{"i":40647,"as":"与长英质岩浆作用相关的热液硫化物矿床是亲铜金属的重要来源。对东北北大山花岗岩基性包体中单斜辉石包裹的硫化物包裹体的研究表明，岩浆上地壳侵位期间发生了富铜、富锌硫化物液体、硅酸盐液体和水流体之间的不混溶现象。富铁硫化物熔体包裹体中高度富集铜（约2628 ppm）、锌（约233 ppm）等金属。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["亲铜金属富集机制[长英质热液矿床形成]: 镁铁质补给和流体介导的硫化物溶解"]},{"i":40648,"as":"","scd":null,"kp":[]},{"i":40649,"as":"","scd":null,"kp":[]},{"i":40650,"as":"","scd":null,"kp":[]},{"i":40651,"as":"在单晶溴化铅铯（CsPbBr3）中实现了由高于带隙的光照或热激发独立驱动的可逆且极性相反的光学开关。研究测量到中红外透射率在3至20微米波长范围内的可调变化，在20微米处变化超过10%。在光和热的作用下表现出相反的极性，调制时间小于1毫秒，展现了下一代光电设备的动态开关潜力。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["光学开关特性[软晶格卤化物钙钛矿单晶]: 相反且可逆的光学开关"]},{"i":40652,"as":"","scd":null,"kp":[]},{"i":40653,"as":"对欠掺杂YBa2Cu3O6+x (YBCO)施加强烈的太赫兹脉冲实验揭示了其独特的物理特性。在超导转变温度Tc与赝能隙温度T*之间，观察到与超导态相似的反射率边缘以及二次谐波产生现象。这些现象为该材料中存在高达赝能隙温度T*的局部超导涨落提供了实验证据。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["温度范围[超导转变温度与赝能隙温度之间]: Tc<T<T*","赝能隙温度[材料参数]: T*≈400 K","非线性光学效应[强太赫兹脉冲泵浦下的探测脉冲调制]: 产生类似频率的二次谐波产生","光学响应特征[强太赫兹脉冲激发]: 呈现类似超导态的反射率边","物理机制[解释反射率与二次谐波特征]: 下支约瑟夫森等离激元模式的参数放大"]},{"i":40654,"as":"","scd":null,"kp":[]},{"i":40655,"as":"","scd":null,"kp":[]},{"i":40656,"as":"","scd":null,"kp":[]},{"i":40657,"as":"","scd":null,"kp":[]},{"i":40658,"as":"","scd":null,"kp":[]},{"i":40659,"as":"","scd":null,"kp":[]},{"i":40660,"as":"","scd":null,"kp":[]},{"i":40661,"as":"","scd":null,"kp":[]},{"i":40662,"as":"","scd":null,"kp":[]},{"i":40663,"as":"","scd":null,"kp":[]},{"i":40664,"as":"","scd":null,"kp":[]},{"i":40665,"as":"利用配备矢量磁场的扫描隧道显微镜，研究者在强关联自旋三重态超导体UTe2中观察到了对密度波（PDW）和电荷密度波（CDW）交织的电子序。研究系统探究了不同CDW阶的演变与相互关联，证实了UTe2中存在异常的磁场敏感型CDW相。这一发现揭示了三重态超导体的各向异性磁场响应在CDW中的具体表现，为研究交织电子序提供了直接证据。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["电荷密度波(CDW)相位[强相关自旋三重态超导体UTe2]: 对磁场高度敏感，表现出交织对密度(PDW)和CDW阶的特征"]},{"i":40666,"as":"","scd":null,"kp":[]},{"i":40667,"as":"","scd":null,"kp":[]},{"i":40668,"as":"依托中国天舟一号和天舟六号飞船，研究者利用自动化生物反应器实现了人胚胎干细胞向原始生殖细胞、卵巢卵泡和精原干细胞的长效分化。航天环境使原始生殖细胞的分化效率降低约50%，并抑制了精原干细胞的增殖（降幅达26%）。多组学分析揭示了太空微环境对人类生殖细胞发育存在显著负面影响，表明生殖系统对太空飞行高度敏感。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["生殖细胞诱导发育[航天微重力环境]: 人类胚胎干细胞长期分化为人类诱导原始生殖细胞、卵巢卵泡和精原干细胞"]},{"i":40669,"as":"","scd":null,"kp":[]},{"i":40670,"as":"","scd":null,"kp":[]},{"i":40671,"as":"通过计算流体动力学-离散元方法（CFD-DEM）模拟，研究揭示了裂缝约束多孔介质（FCPM）中的超达西流动行为。在固定雷诺数下，适度的颗粒沉积会降低整体压降。在高雷诺数下，FCPM的压降不仅高于达西定律预测值（非达西行为），在某些条件下还会低于预测值。这一发现修正了颗粒沉积必然增加流体阻力的传统认知。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["流动行为模拟模型[裂缝约束多孔介质]: CFD-DEM耦合自由流与渗流模型","宏观流动行为[固定雷诺数]: 粒子迁移与沉积改变开放孔隙空间形成异质介质"]},{"i":40672,"as":"","scd":null,"kp":[]},{"i":40673,"as":"","scd":null,"kp":[]},{"i":40674,"as":"","scd":null,"kp":[]},{"i":40675,"as":"研究开发了一种受蜘蛛网启发的自组装“蜘蛛肽”（P1）。P1携带卟啉基团，在超声作用下产生活性氧（ROS）。进入胶质瘤细胞后，P1在线粒体周围形成网状纳米纤维并原位释放ROS，高效破坏线粒体能量代谢。结合胶质瘤外泌体递送系统，Evs@P1展现了卓越的血脑屏障穿透能力和同源靶向性，实现了对脑胶质瘤的非侵入性靶向声动力治疗。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":8.0,"t":5.0},"kp":["声敏剂载体[超声条件下]: 具有卟啉基序的自组装“蜘蛛肽”(P1)","[靶向机制]: 在神经胶质瘤细胞内围绕线粒体形成网状纳米纤维并释放ROS用于靶向治疗"]},{"i":40676,"as":"为解决可穿戴皮肤电极带来的外观伪影问题，研究开发出视觉与触觉上完全不可见的超柔性皮肤电极。该电极能够与皮肤完美贴合，佩戴者及旁观者均无法察觉其存在。感官实验及物理表征证实其具备极佳的隐蔽性和透气性，且不会对佩戴者的心理状态产生负面影响，从而为面部肌电信号监测和人机交互提供了适合长期日常使用的解决方案。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":4.0,"t":6.0},"kp":["表皮电极[外观特征]: 完全隐形且不可察觉，无外观伪影","[应用优势]: 解决传统表皮电极对佩戴者社交互动和自我认同的影响，实现舒适信号监测"]},{"i":40677,"as":"","scd":null,"kp":[]},{"i":40678,"as":"","scd":null,"kp":[]},{"i":40679,"as":"研究推出了名为SemiEpi的自动化分子束外延（MBE）生长平台。该平台结合原位反射高能电子衍射监测与实时反馈控制，并集成了物理信息机器学习模型，能够自主设计异质结构、识别最佳初始条件并提出生长实验方案。通过高密度InAs量子点的按需生长演示，证实了该系统可有效突破传统试错法的瓶颈，实现半导体异质结的定制化开发。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":6.0,"t":7.0},"kp":["半导体异质结构生长平台[分子束外延(MBE)]: SemiEpi自主平台","[控制机制]: 结合原位反射高能电子衍射(RHEED)监测和实时反馈控制实现多步按需生长"]},{"i":40680,"as":"研究基于原位激光还原制备的多孔激光诱导石墨烯复合物，开发出一种可通过前驱体pH值精确调控的超软、高拉伸、高黏附水凝胶。该水凝胶杨氏模量低至1.08千帕，拉伸率高达8000%，且具备优异的导电性和抗汗能力。其出色的皮肤贴合性使得电极能够在干燥或湿润条件下实现穿过毛发的并发生物信号监测，具有低皮肤接触阻抗和高信噪比。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":8.0,"t":6.0},"kp":["杨氏模量[原位功能化激光诱导石墨烯水凝胶]: 1.08千帕(kPa)","极限拉伸率[原位功能化激光诱导石墨烯水凝胶]: ~8000%","材料特性[水凝胶]: 超软、高拉伸、高粘性、可透气且可通过控制前驱体pH进行调节"]},{"i":40681,"as":"研究提出了NicheProt技术，一种结合3D光学显微镜引导和光漂白介导的细胞条形码编码方法。该技术能够从特定的微解剖组织区室中分离出完整的特定细胞类型。通过质谱分析，研究成功在发炎的小鼠脾脏中，基于空间位置定义了两种截然不同的CD11c+树突状细胞表型，实现了具有空间分辨率和细胞类型特异性的精准蛋白质组学解析。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":6.0,"t":6.0},"kp":["分析方法[空间蛋白质组学]: 3D光学显微镜引导和光漂白介导的细胞条形码技术","[技术优势]: 解决了传统激光显微切割结合质谱无法支持从特定组织微解剖区室中分离完整、特定细胞类型的问题"]},{"i":40682,"as":"","scd":null,"kp":[]},{"i":40683,"as":"针对新生儿血液采样监测葡萄糖和乳酸具有痛感和并发症风险的问题，研究人员开发了一种无创、可灌注的皮肤采样贴片。该贴片无需外部诱导即可收集低体积的体温调节汗液，并结合微流控生物传感器分析技术检测皮肤葡萄糖和乳酸水平。实验结果表明，该技术测得的皮肤葡萄糖水平与同时期的血液葡萄糖水平具有良好相关性，实现了分析物的无创精准测量。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":5.0,"t":6.0},"kp":["汗液采样机制[微流控贴片]: 可收集低体积体温调节汗液，无需外部诱发排汗","[应用特点]: 实现对新生儿和成人的无创、连续式葡萄糖和乳酸等分析物监测"]},{"i":40684,"as":"","scd":null,"kp":[]},{"i":40685,"as":"","scd":null,"kp":[]},{"i":40686,"as":"本质吸湿水凝胶（IHHs）通过肌苷和锌离子（Zn2+）的pH控制超分子配位组装而成。该材料在接近零相对湿度（RH）时即可开始吸附水分，在30% RH下水分吸附量可达0.17 g/g，同时在高湿度下仍能保持吸水膨胀放大特性。与需要易潮解盐的传统亲水凝胶相比，IHHs在极低湿度至高宽泛湿度范围内均展现出优异的大气取水和湿气吸附能力。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["吸附特性[本质吸湿水凝胶]: 能够在宽湿度范围内捕获水蒸气并在低相对湿度下有效吸附","[材料优势]: 能够在保持类固态特性的同时储存大量水分，克服了常规亲水凝胶需依赖易潮解盐的局限"]},{"i":40687,"as":"","scd":null,"kp":[]},{"i":40688,"as":"","scd":null,"kp":[]},{"i":40689,"as":"T细胞在形成免疫突触时其肌动蛋白细胞骨架会发生快速重组。研究人员利用透明聚合物波导芯片实现的单分子定位显微镜（SMLM），在超大视场下对激活的Jurkat T细胞和非激活T细胞进行了观察。该技术揭示了激活T细胞免疫突触内片状伪足和分支状肌动蛋白网络之间的结构差异，提供了一种高效的超分辨率成像手段。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["显微成像技术[光子波导芯片]: 透明聚合物波导芯片赋能的单分子定位显微镜(SMLM)","[观测能力]: 能够在大视场下高分辨解析激活的Jurkat T细胞中丝状肌动蛋白(F-actin)细胞骨架的结构变化"]},{"i":40690,"as":"","scd":null,"kp":[]},{"i":40691,"as":"","scd":null,"kp":[]},{"i":40692,"as":"针对联氨（N2H4）存储难以控制的挑战，研究开发了系列聚硝基框架（PNF-4、PNF-5和PNF-6）。该框架通过结构重排和大量氢键（PNF-6中多达36对）实现客体分子的精确固定，能够以分子级精度在每个晶胞中分别可编程封装四、五和六个联氨分子。这种精确的封装机制成功构建了一个高效的自氧化还原系统，实现了危险化学品的可控存储与应用。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["封装容量[聚硝基框架(PNFs)]: 每个晶胞可精准封装4、5或6个N2H4分子","[封装机制]: 实现联氨(N2H4)分子级精准和可编程封装，以构建卓越的自氧化还原系统"]},{"i":40693,"as":"","scd":null,"kp":[]},{"i":40694,"as":"","scd":null,"kp":[]},{"i":40695,"as":"","scd":null,"kp":[]},{"i":40696,"as":"为实现废水中氮污染物的高效回收，研究人员开发了一种无需添加试剂的微环境工程化电动膜。该膜在膜-废水界面通过水解离产生局部碱性环境，将铵根离子（NH4+）转化为氨气（NH3），并连续不断地将高纯度NH3提取穿过膜。其微环境工程设计有效提高了界面碱度并降低了气体传输阻力，实现了高通量与低能耗的结合。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":8.0},"kp":["界面化学机制[无试剂通电膜]: 在膜与废水边界通过水分解产生界面碱性，驱动NH4+转化为NH3","[系统优势]: 耦合了高渗透通量与低能耗，实现了从废水中反应性分离和回收氨(氮循环)"]},{"i":40697,"as":"尽管杂原子螺烯已有广泛研究，但由纯金属元素构成骨架的全金属螺烯一直是合成的重大挑战。研究成功合成并报道了一种受锑/硫醇盐保护的仿生全金属螺烯Pd11(PhSb)2。该结构通过精妙的设计克服了同时控制金属配位几何构型、螺旋传播和构型稳定性的难题，成功构建了具有刚性手性螺旋骨架的金属纳米团簇。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":5.0,"t":8.0},"kp":["[全金属Pd11螺旋烯]: 螺旋骨架完全由金属元素构成","[仿生全金属螺旋烯]: 具有刚性、螺旋手性骨架及显著光电特性"]},{"i":40698,"as":"","scd":null,"kp":[]},{"i":40699,"as":"为精确评估软组织弹性，研究人员开发了一种无线、紧凑的可穿戴生物力学系统。该设备利用振动旋转生物力学动力学，通过可调谐的皮肤接口实现跨解剖部位的深度控制测量。在针对癌症相关淋巴水肿和系统性硬皮病患者的临床研究中，该设备测得的数据与标准临床指标高度相关，为软组织疾病的医学评估提供了直接的生物力学洞察。","scd":{"b":6.0,"i":6.0,"r":7.0,"d":6.0,"t":8.0},"kp":["监测参数[可穿戴生物力学系统]: 皮肤及皮下组织的弹性模量","设备特征[软组织疾病医学评估]: 无线、紧凑的可穿戴系统，采用可调谐皮肤界面和旋转振动生物力学动力学"]},{"i":40700,"as":"研究提出了一种基于数字智能（Digintel）的可重编程超表面（DMS）。该超表面由数字寻址的双稳态单元构成，通过改变单元的稳定状态产生局部特征应变，从而实现数字控制的表面形态变化。通过对单元稳态进行数字编码，DMS实现了广泛的表面形态重塑，且其表面形态的复杂性和类型随着单元数量的增加呈指数级增长，能够精确设计目标表面。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":5.0,"t":8.0},"kp":["[Digintel超表面]: 由数字可寻址双稳态晶胞构建","[超表面变形]: 双稳态晶胞的构型切换可产生局部本征应变以实现广泛可重编程变形"]},{"i":40701,"as":"","scd":null,"kp":[]},{"i":40702,"as":"","scd":null,"kp":[]},{"i":40703,"as":"","scd":null,"kp":[]},{"i":40704,"as":"托卡马克装置中，有利与不利漂移构型下的高约束模式功率阈值存在差异，此差异在实验上与前者的径向电场阱更深有关。研究利用基于第一性原理的回旋动理学模拟，从基础物理层面揭示了径向电场漂移构型依赖性的起源及高约束模式接入的机制。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":9.0},"kp":["[托卡马克有利漂移构型]: 具有更深的径向电场(Er)势阱","[高约束模式(H-mode)功率阈值]: 在不同漂移构型间存在差异"]},{"i":40705,"as":"研究提出了一种超辐射参数穆斯堡尔辐射源（SPMR），以满足未来穆斯堡尔核中极窄X射线共振应用对极高峰值和平均光谱通量的需求。该辐射源通过利用空间微结构电子的散射机制来实现高强度的窄谱X射线输出。","scd":{"b":8.0,"i":2.0,"r":9.0,"d":5.0,"t":9.0},"kp":["辐射源[超辐射参数穆斯堡尔辐射(SPMR)]: 利用空间微结构电子散射产生极高峰值和平均光谱通量","[X射线共振应用]: 需要具有极高光谱通量的X射线源"]},{"i":40706,"as":"","scd":null,"kp":[]},{"i":40707,"as":"理论研究指出，在单光子正在发生反射的过程中移除镜子，会创造出一种包含无数光子的量子态。该理论揭示了通过改变光学边界条件，能够实现对光子量子态数量和分布的极端干预与改变。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":5.0,"t":9.0},"kp":["[截断光子过程]: 单光子反射过程中移除镜子会创造多光子量子态"]},{"i":40708,"as":"设备无关认证技术仅依靠观测统计数据即可验证量子系统，无需假设其内部结构。尽管目前已在自测试中对广泛的量子态和测量进行了最强的设备无关认证，但该研究进一步证实，量子网络中的任何单一量子门均可以实现完全独立于内部设备的认证。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":9.0},"kp":["[量子网络中的设备无关(DI)认证]: 仅基于观测统计验证量子系统，无需假设其内部结构","[任意单量子门]: 可在量子网络中独立于设备进行自测试认证"]},{"i":40709,"as":"Nucleus合作组织在开发用于探测相干弹性中微子-核散射的反应堆中微子的低温氧化铝（Al2O3）探测器中，成功观测到了由中子在铝上俘获引起的两个核反冲峰。这一结果为探测器在低能核反冲的探测与标定提供了关键物理数据。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":9.0},"kp":["核反冲峰数量[中子俘获于Al2O3探测器]: 2个","[Al2O3低温探测器]: 用于通过相干弹性中微子-核散射(CEνNS)探测反应堆中微子并观察到中子俘获引起的核反冲峰"]},{"i":40710,"as":"","scd":null,"kp":[]},{"i":40711,"as":"","scd":null,"kp":[]},{"i":40712,"as":"","scd":null,"kp":[]},{"i":40713,"as":"研究提出了一种用于全局核子-核光学模型计算的双向神经网络模拟器。现代核数据评估不仅需要精确的散射计算，还需要高效的参数优化和不确定性量化方法。该可微求解器支持基于梯度的算法，能够有效执行全局核散射计算及参数寻优。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":6.0,"t":9.0},"kp":["[核子-核光学模型计算]: 采用双向神经网络构建可微分求解器模拟器以实现高效不确定度量化和参数优化"]},{"i":40714,"as":"","scd":null,"kp":[]},{"i":40715,"as":"","scd":null,"kp":[]},{"i":40716,"as":"","scd":null,"kp":[]},{"i":40717,"as":"","scd":null,"kp":[]},{"i":40718,"as":"","scd":null,"kp":[]},{"i":40719,"as":"","scd":null,"kp":[]},{"i":40720,"as":"本期每日简报重点关注钠离子电池技术，指出钠离子电池具有改变全球能源存储格局的潜力。此外，简报还涵盖了远古蠕虫 handedness（左右侧倾向）的演化研究，以及科学家揭示深海奥秘的最新进展。","scd":{"b":3.0,"i":4.0,"r":3.0,"d":2.0,"t":6.0},"kp":["[钠离子电池]: 具有改变世界储能格局的潜力"]},{"i":40721,"as":"研究报道了一种利用Pd/Mo双金属催化剂和叔丁基过氧化氢（TBHP）氧化剂实现苯甲酸邻位直接二羟基化的方法。Mo成分通过提高TBHP的氧化能力并促进Pd-Ar中间体的氧化加成，显著推动了反应尤其是第二次羟基化过程。该双金属介导法可通过调节TBHP用量实现单羟基化产物的可控制备，并成功进行克级规模合成。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["催化剂[苯甲酸邻位二羟基化]: Pd/Mo双金属","氧化剂[苯甲酸邻位二羟基化]: 叔丁基过氧化氢(TBHP)","[二羟基化反应]: Mo组分通过提升TBHP氧化能力显著促进第二次羟基化步骤"]},{"i":40722,"as":"针对固态锂电池（SSLBs）电极体积膨胀和界面副反应导致的机械应力损伤问题，研究人员开发出一种基于梯度共价-非共价动态键的界面自修复聚合物电解质（SHPE）。该技术通过分子工程结合高强度硼酸酯键和超快动态响应氢键，实现了电池生命周期内的高效多界面室温自修复。这种快速动态交换机制有效解决了界面缺陷问题，保障了离子传输的稳定性。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":8.0,"t":6.0},"kp":["电压等级[界面自修复聚合物电解质(SHPE)]: 4.6V级锂金属电池","[界面自修复聚合物电解质(SHPE)]: 基于梯度共价-非共价动态键以实现多重界面自适应并缓解应力损伤"]},{"i":40723,"as":"针对传统磁场驱动磁化开关能耗高、扩展性差的问题，研究利用最优控制理论（OCT）生成精确整形的磁场脉冲。该方法在范德华磁体中实现了超快、确定性且极度节能的磁化开关过程。这一突破使得原本被淘汰的磁场驱动反转技术在现代信息存储架构中重新具备了与自旋转移矩（STT）和自旋轨道矩（SOT）等电流驱动技术相竞争的能力。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[磁化开关驱动机制]: 传统磁场驱动因高能耗、空间选择性差及可扩展性差已被自旋转移等电流驱动技术取代"]},{"i":40724,"as":"光催化甲烷转化面临C-H键活化需强氧化驱动力，而部分氧化产物易被过度氧化的矛盾。综述总结了包括聚合氮化碳（PCN）、金属有机框架（MOFs）和共价有机框架在内的有机半导体平台。这些材料的结构特征与传统无机材料存在根本差异，为在提高光催化通量的同时避免过度氧化、实现高附加值甲烷选择性转化提供了新的结构设计原则。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[光催化甲烷氧化]: 面临C-H键活化需高氧化驱动力与部分氧化中间产物易过度氧化之间的核心矛盾"]},{"i":40725,"as":"锂二氧化碳电池具有约2.8V的高放电电压和1876 Wh/kg的高理论能量密度，可实现储能与固碳双重功能。然而，多相界面的复杂反应路径和迟缓的充放电动力学导致电池可逆性差。本综述指出，开发高效阴极催化剂是解决此瓶颈的关键，并深入探讨了催化剂电子结构调节的机制与策略，以优化反应动力学并提升电池的综合性能。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":8.0,"t":6.0},"kp":["放电电压[锂二氧化碳电池]: ~2.8 V","理论能量密度[锂二氧化碳电池]: 1876 Wh/kg"]},{"i":40726,"as":"针对三阴性乳腺癌（TNBC）的免疫抑制微环境，研究人员开发了成纤维细胞激活蛋白（FAP）靶向纳米探针（FAP-IR1061）。该探针集成了第二近红外（NIR-II）荧光、磁共振（MR）和光声（PA）三模态成像功能，并具备高效的NIR-II光热转换能力。该平台能够实现精准的诊疗一体化，通过光热治疗等方式重新编程肿瘤微环境，克服TNBC的免疫治疗抗性。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["免疫抑制微环境机制[三阴性乳腺癌]: 肿瘤相关成纤维细胞通过FAP介导的ECM重塑及细胞因子分泌导致免疫治疗抗性"]},{"i":40727,"as":"为解决柔性钙钛矿-有机串联太阳能电池中晶界（GBs）引发的载流子复合和卤化物相分离问题，研究开发了一种将离子液体引入聚氨酯（PU）的导电聚合物复合材料。该材料能够有效钝化铅和FA相关缺陷，抑制卤化物分离并缓解残余应力。其在晶界间建立了高效的横向导电聚合物桥（CPB），显著增加了载流子扩散长度，从而大幅提升了器件的光伏性能与机械可靠性。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[富溴钙钛矿薄膜晶界]: 引发载流子复合加剧、光致晶格膨胀及相分离，严重降低光伏性能与可靠性"]},{"i":40728,"as":"双光子光刻技术（TPL）在制造复杂三维微结构时受限于缺乏有效的微尺度支撑去除手段。研究提出一种基于新型水溶性（W-S）光刻胶的通用牺牲支撑辅助TPL方法。该光刻胶兼具高打印分辨率和极快的溶解速度，其形成的牺牲支架可在温和的水性环境中10分钟内完全去除。这是目前已报道的可溶解TPL光刻胶中最快的溶解速度之一，成功实现了无约束的三维微加工。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[双光子光刻3D微加工]: 开发水溶性牺牲支架及光刻胶，解决无约束任意三维几何结构的微尺度支撑去除难题"]},{"i":40729,"as":"有机太阳能电池的功率转换效率受限于电压损失，难以同时实现非富勒烯受体的高发光和优异电荷传输性能。研究提出基于“蝴蝶效应”的分子设计概念，通过对A-DA'D-A型受体远端苯环进行甲氧基、甲基、氢和氟等细微取代基修饰，精确控制分子的固态堆积方式。这种远程修饰策略有效优化了分子间相互作用，为突破光伏性能瓶颈提供了新思路。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[非富勒烯受体分子设计]: 需克服分子结构与固态堆积间的非线性复杂关系，以实现高发光与优异电荷传输特性的同步提升"]},{"i":40730,"as":"无钴镍基层状氧化物正极因不可逆相变面临严重的结构退化。研究基于晶域工程，开发了一种简单的一步控制策略。该策略将局部有序的富锂Li2TMO3晶域（由LiNi6-x等组成）可控地集成到无钴层状氧化物基体中。这种晶域工程策略有效抑制了材料的结构退化，为开发高性能、高稳定性的无钴锂离子电池正极材料提供了创新的 bulk 设计方案。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[无钴镍基层状氧化物正极]: 通过晶域工程设计改善因除钴导致的不可逆相变及结构严重退化"]},{"i":40731,"as":"针对钙钛矿发光二极管中氧化铟锡（ITO）与钙钛矿界面能垒导致的电荷注入不平衡问题，研究首次引入完全非共轭的磷酸盐取代壳聚糖（NCPC）作为空穴注入层。NCPC增强了与ITO和空穴传输层的界面相互作用，有效降低了能垒并实现了良好的能级对齐。引入该材料显著降低了电荷注入势垒和非辐射复合，使红、绿、蓝三色器件的最大外量子效率得到大幅提升。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[钙钛矿发光二极管界面改性]: 利用非共轭磷酸盐取代壳聚糖作为高效空穴注入层，解决ITO/钙钛矿界面能垒引起的电荷注入失衡问题"]},{"i":40732,"as":"可充电铝硫电池具有高理论能量密度和成本效益，但面临硫正极反应动力学迟缓和严重的穿梭效应。研究开发了两种坚固的二维共价有机框架作为硫的载体，其特征是具有可接触的催化氮位点和限域微孔通道。通过调节不同长度的有机配体来精细调控微孔尺寸，对比表明，较小尺寸的微孔通道具有更高的限域能力，有效提升了电池的快充性能和长循环稳定性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["硫载体[铝硫电池催化剂]: 含有可接触催化氮位点的二维共价有机框架","微孔限域效应[铝硫电池催化体系]: 缓解多硫化物穿梭效应并改善反应动力学"]},{"i":40733,"as":"传统体外CAR免疫细胞制造工艺复杂且成本高昂，限制了其临床广泛应用。纳米载体驱动体内CAR工程成为新范式，该技术利用纳米载体直接将遗传物质递送至循环或组织驻留的免疫细胞中，从而大幅简化了生产流程。综述概述了CAR免疫细胞疗法的演进及体外方法的局限性，并深入探讨了纳米材料驱动的体内CAR细胞工程技术的最新进展和关键机制。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[CAR免疫细胞疗法]: 正向由复杂、高成本且个体差异大的传统体外制备向纳米材料驱动的体内工程范式转变"]},{"i":40734,"as":"深蓝色钙钛矿发光二极管（PeLEDs）的性能远落后于红绿光器件。传统低维或混合卤化物钙钛矿存在严重的俄歇复合、相分离等缺陷。尽管Pb/Sr混合B位成分工程能提供优异的光谱稳定性，但结晶过程中的成分偏析会导致薄膜质量差。研究提出成分均质化和介电调制策略，有效解决了Pb/Sr混合钙钛矿的异质性问题，显著提升了深蓝色发光二极管的发光效率和器件性能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["发光器件[深蓝PeLEDs]: 性能落后于红绿光器件","传统策略[低维或混合卤化物钙钛矿]: 存在严重的俄歇复合、相分离"]},{"i":40735,"as":"废旧锂离子电池的常规火法或湿法冶金回收主要关注金属提取，未能保留材料的功能价值。材料再生技术通过补充锂离子和结构重构恢复退化电极的性能，但受限于原料异质性。综述探讨了下一代锂离子电池回收策略，重点论述了从基础金属提取向原位电池修复技术的最新进展。新技术旨在降低能耗、减少二次废弃物并最大化保留材料价值。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["回收策略[废旧锂离子电池]: 需降低能耗、减少二次废料并保留材料价值","传统工艺[火法/湿法冶金]: 侧重金属提取，未能保留废旧电池的功能价值"]},{"i":40736,"as":"准固态聚合物电解质（QSPEs）在零下环境中面临低温离子传输与锂负极寄生反应的矛盾。研究通过聚合诱导相分离（PIPS）策略制备了分级异质QSPE。该双相结构在交联含氟聚合物框架内集成了高导电的DMSO-LiTFSI/LiBF4液体微域，采用协同的“双限域”机制。这种空间-界面双重限域设计有效抑制了锂枝晶生长，实现了极低温环境下安全稳定的锂金属电池运行。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":6.0,"t":5.0},"kp":["工作环境[准固态聚合物电解质]: 零下温度引发锂负极寄生反应和枝晶生长","材料设计[极性溶剂如DMSO]: 实现快速低温体相离子传输但引发寄生反应"]},{"i":40737,"as":"海水制氢受限于腐蚀性海洋环境对传统金属催化剂的破坏。研究提出一种接触电催化（CEC）策略，采用非金属氟化二氧化硅（F-SiO2）作为催化剂，通过机械搅拌扰动从海水中有效提取氢气。与难以在离子液体中起电的传统碳氟聚合物不同，F-SiO2基团能保持高效的接触起电性能。该技术为海水制氢提供了无金属、高稳定性的可持续解决方案。","scd":{"b":8.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["接触电催化策略[海水分解制氢]: 采用非金属氟化二氧化硅(F-SiO2)抵抗腐蚀环境"]},{"i":40738,"as":"锂离子电池边缘析锂通常被认为是负极主导的失效问题。研究揭示了LiFePO4（LFP）电池中阴极依赖的边缘锂沉积机制。LFP与石墨电极之间异步的晶格体积和厚度演变导致循环中产生多级膨胀-收缩。结合软包电池中心-边缘机械约束的固有差异，这种电化学-机械耦合行为逐步放大了机械异质性，驱动了LFP||石墨软包电池在低压边缘区域的优先锂沉积。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["边缘析锂机制[锂离子电池]: 受阴极影响，源于LiFePO4与石墨电极间的异步晶格体积和厚度演变"]},{"i":40739,"as":"针对海水电解制氢中水离解动力学迟缓和阴极易结垢的问题，研究通过构建由S桥键连接的Pt/NiS结构开发了高效析氢电催化剂。S桥键诱导强烈的电子转移，调节了电荷分布并增强了强金属-基底相互作用（SMSI）。原位表征表明，该结构能够破坏刚性的氢键网络，加速NiS上的水分子离解，并促进H*向Pt转移，从而大幅提升海水制氢的效率并实现防垢功能。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":6.0,"t":5.0},"kp":["析氢电催化剂[Pt/NiS结构]: 通过S桥键合构建，实现强烈的协同电子转移","S桥键合[Pt/NiS结构]: 破坏界面氢键网络以解决阴极结垢问题"]},{"i":40740,"as":"聚合物电介质在击穿强度、热稳定性和介电常数之间存在难以调和的矛盾。研究通过偶极子调控策略，利用柔性亚甲基连接基团将极性甲基磺酰基团限制在刚性半芳香族聚酰亚胺框架中。这种砜-亚甲基-苯酚的偶极子限制域结构将偶极响应与电荷传输解耦，成功克服了材料学三难困境，开发出适用于超高温薄膜电容器的极端环境电介质材料。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":6.0,"t":5.0},"kp":["聚合物介电材料[极端环境薄膜电容器]: 存在击穿强度、热稳定性和介电常数三者间的不兼容权衡"]},{"i":40741,"as":"近红外窄带吸收的有机半导体在光电探测器领域极具应用价值。研究报道了一种新型稠合醌型二茚二硒酚材料（QIDSe-C16），其在固态下形成J-聚集体，产生中心位于772纳米、半峰全宽仅为27纳米的极锐利吸收带。与硫类似物相比，硒取代显著提高了电荷迁移率。基于该材料优化的有机场效应晶体管在超窄带有机光电探测中表现出极高的响应度。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":6.0,"t":5.0},"kp":["半峰宽[QIDSe-C16材料固态J-聚体吸收带]: 27 nm"]},{"i":40742,"as":"研究团队开发了一种有机上转换器件（OUD），利用微腔谐振技术选择性放大电荷转移吸收带，将近红外辐射高效转化为可见光。该器件通过构建光学隔离层抑制重吸收损耗，实现光子-光子转换效率的显著提升，突破了传统有机半导体近红外吸收范围受限的瓶颈。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":6.0,"t":5.0},"kp":["光子上转换器件[有机上转换器件]: 利用分子间电荷转移吸收将近红外辐射转化为可见光"]},{"i":40743,"as":"本研究提出一种利用不混溶金属诱导表面偏析的策略，成功构建了核壳结构Bi-PtMn催化剂，用于直接甲醇燃料电池。该催化剂具有有序的PtMn核心和PtBi外壳，突破了传统Bi-Pt催化剂活性与选择性难以兼得的瓶颈，实现了优异的甲醇氧化反应性能与对无碳路径的高选择性。该催化剂的质量比活性高达61.81 A mgPt-1，分别是传统Bi-Pt和商用Pt/C催化剂的4.0倍和16.2倍，展现出作为实用阳极材料的巨大潜力。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["表面偏析策略[核壳Bi-PtMn催化剂]: 利用不混溶金属构建以打破本征活性与选择性权衡"]},{"i":40744,"as":"采用高熵策略开发出A位五元等摩尔阳离子钙钛矿阳极材料（Pr0.2Ba0.2La0.2Sr0.2Ca0.2FeO3），该材料在碳氢化合物燃料固体氧化物燃料电池中表现出优异的抗硫和抗结焦性能，有效解决了传统镍基阳极的中毒失活问题。","scd":{"b":8.0,"i":2.0,"r":4.0,"d":6.0,"t":5.0},"kp":["[碳氢化合物燃料固体氧化物燃料电池阳极]: 采用在A位引入五种等摩尔阳离子的高熵策略提升耐硫和抗结焦性能"]},{"i":40745,"as":"报道了一种氧化骨架编辑策略，通过镍介导的环化反应合成四重N-混乱[32]八菲林双金属络合物。随后在内侧α位进行选择性氧化，触发结构重组和氧原子嵌入，生成双联10-氧杂环戊烯金属络合物二聚体，这些产物展现出独特的双重电子结构特征。","scd":{"b":6.0,"i":1.0,"r":3.0,"d":5.0,"t":5.0},"kp":["[Ni介导的环化反应]: 合成表现出全局反芳香性的四重N-混乱[32]八菲林双金属络合物"]},{"i":40746,"as":"提出几何-电子-化学三重工程策略，开发了基于固有微孔聚合物（SCFPIM）的多功能人工固体电解质界面（ASEI）。该材料具有约0.57纳米的亚纳米通道，集成冠醚和-CF3基团，在高电流密度（≥3 mA cm-2）和大面容量（≥3 mAh cm-2）条件下实现了锂金属阳极的超稳定运行。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["工作电流密度[锂金属电池]: ≥ 3 mA cm⁻²","面容量[锂金属电池]: ≥ 3 mAh cm⁻²","人工SEI[锂金属阳极]: 具有负电亚1nm通道的固有微孔聚合物"]},{"i":40747,"as":"","scd":null,"kp":[]},{"i":40748,"as":"","scd":null,"kp":[]},{"i":40749,"as":"受一氧化碳脱氢酶激活机制启发，制备了氮掺杂碳负载的Re-Ni双原子催化剂（ReNi-N/C）。该催化剂具有相邻Re-Ni原子对，采用双齿吸附模式，在CO2电还原反应中实现-427.6 mA cm-2的CO部分电流密度和近100%法拉第效率，展现出超低过电势特性。","scd":{"b":8.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["催化剂[CO2电还原]: 具有双齿吸附模式的Re-Ni双原子催化剂","[Re-Ni双原子催化剂]: 受天然一氧化碳脱氢酶活化机制启发，诱导产生超低过电势"]},{"i":40750,"as":"开发了单相6H三重钙钛矿氧化物Ba3Co(Co0.25Ru0.75)2O9（BCCRO）作为碱性整体水分解双功能电催化剂。该催化剂在10 mA cm-2电流密度下，OER和HER过电势分别为178和32 mV，并在1 A cm-2高电流密度下稳定运行1000小时，表现出优异的催化活性和耐久性。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":7.0,"t":5.0},"kp":["工作电流密度[整体水分解]: 1 A cm⁻²","稳定运行时间[整体水分解]: 1000 小时","双功能催化剂[整体水分解]: 单相6H三重钙钛矿氧化物 Ba3Co(Co0.25Ru0.75)2O9"]},{"i":40751,"as":"基于Zr-MOF PCN-700构建了可编程发光传感平台，通过模块化连接体安装策略成功将20种不同功能的预制模块引入MOF结构中。这些模块具有可变的分子长度和构型，为特定分析物的定制化检测提供了低成本、高效率的解决方案，突破了传统MOF材料合成成本的限制。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["发光传感平台[金属有机框架(MOFs)]: 基于在金属有机框架中选点模块化安装构建的可编程平台"]},{"i":40752,"as":"系统综述了高熵材料电催化剂设计从实验驱动向理论和数据驱动的计算范式转变。重点阐述了密度泛函理论、分子动力学和机器学习在揭示催化机理和筛选最优组分中的核心作用，以及高通量计算与机器学习集成实现高效筛选的最新进展，并分析了当前方法面临的挑战。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[高熵电催化剂设计]: 经历由实验驱动向基于密度泛函理论(DFT)、分子动力学(MD)和机器学习(ML)的理论与数据驱动计算范式转变"]},{"i":40753,"as":"开发了水凝胶编织共价有机框架（HW-COF）智能膜，该膜具有正交且热响应方向相反的纳米通道结构。通过水凝胶与COF的协同热响应特性，成功克服了传统智能膜在渗透性和选择性之间的权衡限制，在水相分离领域展现出卓越的性能优势。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["智能膜[水凝胶编织COF膜]: 具有正交、相反热响应纳米通道以克服渗透性-选择性权衡"]},{"i":40754,"as":"提出层间限制策略，通过在KOH压缩的层间结构中稳定原子级分散的钴位点，精确重编程过乙酸的活化路径，使其几乎完全生成单线态氧（1O2），从根本上抑制了自由基的产生，为选择性氧化化学提供了精确的反应途径控制方法。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[过乙酸(PAA)活化]: 层间限制引导活化反应几乎完全产生单线态氧以抑制自由基生成"]},{"i":40755,"as":"通过配位竞争策略首次实现了具有定制暴露面的钙钛矿单晶合成。利用晶习修饰剂调控，实现了从立方（100）面到十二面体（110）面主导结构的形貌操控。非热力学（110）面的形成源于强烈的配位吸附能差异，为光电材料性能优化提供了新途径。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[钙钛矿单晶合成]: 通过吸附能差驱动，成功实现具有定制暴露晶面的单晶精准合成"]},{"i":40756,"as":"通过亚乙烯基桥和α,β'-连接吡咯单元合成了28π莫比斯芳香性N-混杂氧六菲林(2.1.1.1.1.1)，经氧化Cβ-Cβ融合获得稳定的Hückel反芳香性三重N-混杂氧六菲林(1.1.1.1.1.0)，该化合物表现出24π和28π系统的混合特征，并具有光热转换特性。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":6.5,"t":4.0},"kp":["芳香性特征[N-混杂六菲林(2.1.1.1.1.1)]: 28π莫比乌斯芳香性","合成修饰条件[稳定反芳香性卟啉类似物]: 引入亚乙烯基桥联和α,β′-连接的吡咯单元","[反芳香性化合物]: 具备奇特的反应活性和理化性质"]},{"i":40757,"as":"设计了包含二酮吡咯并吡咯-苯并噻二唑-二酮吡咯并吡咯（DBD）单元的三受体骨架结构，该骨架同时促进电化学氧化和还原过程。通过侧链化学调控，成功实现了有机混合离子电子导体中的双极传输特性，填补了n型和双极性OMIEC材料领域的研究空白。","scd":{"b":7.5,"i":2.5,"r":6.0,"d":6.0,"t":4.0},"kp":["材料类型[有机混合离子-电子导体]: p型材料主导，双极性及n型材料发展受限","性能瓶颈[双极性/电子传输OMIECs]: 缺乏在不影响性能的前提下承受电化学还原的坚固共轭骨架"]},{"i":40758,"as":"报道了一系列基于二环戊[b,j]菲骨架的同分异构开壳层多环烃的合成与表征。实验和理论研究表明，细微的结构异构化决定其独特的电子结构和性质，这些化合物表现出大的双自由基特征和高效近红外光热转换能力，在成像应用中具有显著优势。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.5,"t":4.0},"kp":["分子骨架[异构开壳层多环烃]: 基于二环戊烷并菲的二苯并二茚并菲双自由基","[有机双自由基结构异构化]: 调节基础性质及用于成像的高效近红外光热转换"]},{"i":40759,"as":"开发了一类两亲性框架核酸（ampFNAs），实现核酸分子机器的直接胞质递送。其中，修饰单个胆固醇基元的刚性棒状六螺旋束结构展现出最优的细胞结合和内化能力，通过胆固醇依赖性脂筏介导途径进入细胞，有效绕过内体陷阱，比商业转染试剂Lipo3000毒性更低。","scd":{"b":8.0,"i":2.0,"r":6.5,"d":6.5,"t":4.0},"kp":["递送屏障[核酸分子机器]: 细胞膜穿透和内体隔离双重障碍","[两亲性框架核酸]: 实现不依赖能量的脂质膜直接穿透和胞质递送","几何构型[单修饰胆固醇基团]: 刚性棒状六螺旋束结构展现出优越的递送性能"]},{"i":40760,"as":"开发了四种翼型二聚体受体异构体（Dimer-1至4），系统研究了端基（甲氧基取代EG1和无甲氧基EG2）不同共轭位点对分子堆积和光电性质的影响。其中Dimer-2（内侧两个EG1、外侧两个EG2）表现出优异的分子堆积和结晶度，使有机太阳能电池光电转换效率达到20.32%。","scd":{"b":7.5,"i":5.5,"r":6.0,"d":8.5,"t":4.0},"kp":["光电转换效率(PCE)[有机太阳能电池]: 20.32%","分子异构化[翼型二聚体受体]: 精确调控端基共轭位点以优化骨架几何构型并提升效率"]},{"i":40761,"as":"提出位点间距重构策略强化氢键网络，以1,3,5-三(4-羧基苯基)苯基有机框架（HOF-BTB）及其钠离子修饰类似物（Na-HOF-BTB）为模型系统验证。通过静电相互作用选择性重建亲水位点间距，形成连续的氢键网络，有效突破质子传输瓶颈，为电化学储能转换提供新材料。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.5,"t":4.0},"kp":["核心障碍[质子传导材料]: 架构引起的亲水位点分离阻碍连续氢键网络形成并限制质子传输","结构调控策略[质子传输]: 位点间距重构以构建完美氢键网络"]},{"i":40762,"as":"本研究通过顺序界面组装构建了一种多级光响应不对称介孔纳米通道。该器件在阳极氧化铝支架上集成了多巴胺识别的介孔TiO2层与具有光热活性的介孔碳/γ-Fe2O3异质结构。该系统成功解决了选择性分子结合与高效信号放大相耦合的难题。","scd":{"b":6.5,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["器件结构[光热调节传感]: 多级光响应不对称介孔纳米通道","[多巴胺识别]: 采用介孔TiO2实现分子识别与离子传输调节的耦合"]},{"i":40763,"as":"本研究通过磺酰亚胺与羟吲哚衍生物的不对称去对称化反应，成功合成了同时具有1,3-S(VI)和碳立构中心的手性磺酰亚胺。该转化采用手性N,N'-二氧化物/Ni(II)配合物作为路易斯酸催化剂，实现了高非对映和对映选择性的共轭加成，具备反应条件温和及官能团耐受性优异的特点。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["手性构建[磺酰亚胺衍生物去对称化]: 通过高立体选择性控制同时构建1,3-S(VI)和碳立构中心"]},{"i":40764,"as":"本研究对PtNi金属间纳米线的晶格应变进行了精确调控，以优化氧还原反应性能。通过将纳米线的有序度从4.5%调节至65.8%，研究发现在无序到有序转变过程中出现了特征性的双轴应变。该发现量化区分了传统认为的各向同性压缩模型，指出该相变诱发了晶格面内膨胀。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.5,"t":4.0},"kp":["结构演化调控[PtNi金属间化合物纳米线]: 有序度在4.5%至65.8%范围内动态调节","[晶格应变演化]: 揭示原子有序化过程中的双轴应变各向异性（纠正各向同性压缩的简化认知）","催化应用[铂基催化剂]: 氧还原反应(ORR)"]},{"i":40765,"as":"本研究利用方钠石（SOD）骨架的空间位阻效应，将钌纳米颗粒限制在SOD骨架内（Ru@SOD），并混合HY沸石引入远端酸性位点。该设计排除了苯和环己烯接触金属位点，使中间体环己烯的形成和转化仅限于酸性区域，阻断了环己烯从金属向相邻酸位点迁移的常规竞争路径，实现了对串联催化反应路径的精确控制。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["空间限域机制[方钠石(SOD)骨架隔离金属酸结构]: 利用空间位阻阻止大体积苯和环己烯接触金属位点","[串联催化路径重定向]: 将环己烯中间体的生成和转化严格限制在酸位点"]},{"i":40766,"as":"本研究开发了一种基于病毒介导的超分子自组装的抗病毒抑制剂。设计的环糊精单体包含金刚烷基单元、跨腔桥连结构和唾液酸（SA）配体。细胞感染实验表明，具有自组装和配体识别双重特性的SA功能化环糊精能够有效抑制SARS-CoV-2诱导的细胞病变，且无明显细胞毒性。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["功能性环糊精自组装抑制剂[病毒介导超分子组装]: 含金刚烷基单元(促进包含介导聚合)、跨CD空腔桥接(防止自包合)、唾液酸配体(结合刺突糖蛋白识别位点)","抑制剂设计机制[病毒感染阻断]: 适应性抑制剂"]},{"i":40767,"as":"本研究提出了一种“Click'n ROPISA”一锅法策略，将水相开环聚合诱导自组装与铜催化叠氮-炔基环加成反应相结合，制备出多肽荧光纳米颗粒。该方法实现了多肽纳米物体的形成与多种叠氮化荧光团共价结合的同步进行，所制备的组装体具有可见光谱范围内可调的发射特性。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["荧光纳米颗粒制备策略[一锅法偶联ROPISA与CuAAC]: 水相开环聚合诱导自组装(ROPISA)与铜催化叠氮-炔基环加成的原偶联","高分子单体[多肽纳米颗粒合成]: γ-丙炔基-L-谷氨酸N-羧基环内酸酐"]},{"i":40768,"as":"本研究发现LiNH2-2LiH复合氢化物（理论储氢容量10.29 wt.%）在紫外线照射下可实现光驱动可逆储氢。在0.8 W·cm−2的紫外光激发下，LiNH2发生均裂N─H键断裂，产生独特的光响应，同时释放H2。这克服了传统热驱动脱氢过程中热力学稳定和动力学缓慢的障碍。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":["储氢容量[LiNH2-2LiH复合氢化物]: 10.29 wt.%","释氢/加氢动力学[热驱动过程]: 受限于N-H和Li-H键断裂与形成的迟滞动力学及热力学稳定性","驱动机理[储氢脱氢反应]: 太阳能光热/光驱动可逆储氢"]},{"i":40769,"as":"本研究提出了一种非晶金属氧化物覆盖层策略，在Mo掺杂的BiVO4表面有效抑制了过氧化氢（H2O2）在纯水中的快速分解。该光催化方法克服了无机半导体表面介导H2O2分解的瓶颈，实现了H2O2的持续光催化生产。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["H2O2分解抑制[纯水体系光催化生产]: 通过覆盖层设计的BiVO4抑制表面介导的H2O2快速分解以实现持续生产"]},{"i":40770,"as":"本研究将野生型亚胺还原酶工程化改造为串联氨化酶（AHTanAm），用于连续的分子间还原胺化反应。该工程酶及其变体具有双重催化优势，能够从广泛可得的一级胺前体一锅法合成数百种叔胺，并对多个立体中心实现精确的立体化学控制。X射线晶体学揭示了其催化机制。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["工程酶催化剂[串联还原胺化合成叔胺]: 将野生型亚胺还原酶工程化改造为串联胺化酶(AHTanAm)","催化反应特性[生物合成]: 连续的分子间还原胺化"]},{"i":40771,"as":"本研究开发了一种可现场编程的磁光子超粒子，用于主动光操纵和转向。这是一种集成了磁性核心和纳米压印光子表面的微型结构，将光子超表面的可重构性与磁驱动的移动性相结合。该移动光子代理能够在复杂介质中主动传递和引导光流，适用于深度组织成像和精准光疗等领域。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["移动磁光子超粒子[主动光操纵与转向]: 现场可编程移动光子 agent，具备在复杂动态环境中主动传递和控制光流向的能力"]},{"i":40772,"as":"本研究提出了一种利用两束正交偏振激光激发前向受激布里渊散射（FSBS）的新机制。当共享的离子声波（IAW）模式被激发时，散射光与IAW相互作用产生的拍频波可作为FSBS的种子。模拟表明，该机制能抑制后向受激布里渊散射（BSBS），使双光束构型下的总背向散射反射率降低至与单光束相当的水平。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["前向受激布里渊散射(FSBS)[双正交偏振光束]: 由共享离子声波(IAW)模式下、散射光与IAW相互作用产生的拍频波提供种子激发","能量传递与抑制效应[激发的FSBS与后向SBS竞争]: 抑制了后向受激布里渊散射(BSBS)及共享IAW模式"]},{"i":40773,"as":"聚变功率测量是反应堆级磁约束聚变装置的关键基准。在氘-氚燃料混合物中，14 MeV的氚中子产额提供了机器聚变功率的直接测量。为解决中子产额测量的不确定性，采用了计量中子实验室评估、移动中子源（如252Cf）现场校准以及交叉校准等策略。未来BEST、ITER和DEMO等装置需要更高产额的中子源。","scd":{"b":5.0,"i":5.0,"r":6.0,"d":6.0,"t":5.0},"kp":["聚变功率分布[氘-氚燃料混合物]: 约4/5的聚变功率由中子带出等离子体体积","中子产额能量[氘-氚聚变直接测量基准]: 14 MeV"]},{"i":40774,"as":"TCV托卡马克开展了扩展实验，开发了以非感应驱动电流（特别是大比例自举电流）为主的长脉冲运行兼容场景，以实现优异的等离子体性能（归一化βN）。作为EUROfusion联合欧洲聚变装置计划的一部分，这些进展为新JT-60SA托卡马克的先进场景做了准备，并在最近的实验活动中实现了维持稳态的广泛放电。","scd":{"b":6.0,"i":5.0,"r":6.0,"d":5.0,"t":5.0},"kp":["等离子体电流驱动[TCV托卡马克长脉冲稳态运行]: 绝大部分由非感应电流(尤其是大比例自举电流)驱动","等离子体性能评估[高性能放电关键指标]: 归一化β(βN)"]},{"i":40775,"as":"本研究将分子动力学（MD）与物体动力学蒙特卡罗（OKMC）动态耦合，用于研究聚变材料铁和钨中缺陷的长期演化。该方法克服了MD无法模拟实验时间尺度的缺陷，同时弥补了OKMC缺乏级联形态和缺陷相互作用细节的问题，从而准确解析了材料在辐射环境下从皮秒级到实验级辐照周期的长期微观结构演变。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["缺陷演化模拟[铁和钨的辐照损伤长期动力学]: 分子动力学(MD)与物体动力学蒙特卡罗(okMC)的动态耦合","初始损伤时间尺度[辐照材料微结构演变]: 皮秒至纳秒级"]},{"i":40776,"as":"","scd":null,"kp":[]},{"i":40777,"as":"EAST的最新实验证明了钨（W）作为主壁面对等离子体材料与低/无硼覆盖的高约束（H模）运行兼容。实验在低归一化输入扭矩下实现了I型和II型ELMy H模。当分离层与主W限制器的距离低至4厘米时，小振幅高频II型ELMs仍能保持良好的H模能量约束。实验使用了电子回旋、中性束注入和低杂波等辅助加热，总功率达3至5兆瓦。","scd":{"b":6.0,"i":6.0,"r":6.0,"d":7.0,"t":6.0},"kp":["壁材料[EAST高约束H模]: 钨","硼覆盖要求[钨壁H模运行]: 低或无","归一化输入扭矩[兼容ITER的EAST运行]: 低","辅助加热手段[EAST等离子体]: 电子回旋(EC)、中性束注入(NBI)、低杂波(LHW)"]},{"i":40778,"as":"本研究提出了一种结合全向性和分段全向性（pwO）的仿星器配置优化方法。在OOPS优化框架内引入映射技术，将近似pwO挤压至高场侧。所得优化配置跨越了不同的磁场周期和纵横比，不仅与磁阱兼容，还展现出良好的新经典输运和自举电流特性，同时部分放宽了全向性的严格要求，是未来反应堆的潜在候选方案。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["优化方法[仿星器构型]: 结合全向性和分段全向性的优化方法","映射技术[高场侧pwO近似]: 挤压一般全向性场技术"]},{"i":40779,"as":"本文综述了全钨WEST托卡马克一期（2016-2021）和二期（2022年起）实验中面对等离子体部件（PFCs）的侵蚀和材料迁移。一期结果显示，PFC的总侵蚀归因于等离子体中的低Z杂质，且在高场侧（内侧）和低场侧（外侧）之间存在显著的不对称性。打击点附近测得的净侵蚀率小于0.5 nm/s，累计等离子体暴露约7小时后形成了厚度达50 μm的复杂沉积层。","scd":{"b":4.0,"i":6.0,"r":6.0,"d":6.0,"t":4.0},"kp":["实验阶段[WEST托卡马克一期与二期运行]: 一期(2016-2021), 二期(从2022起)","材料侵蚀机制[偏滤器等面向等离子体部件]: 归因于等离子体中的低Z杂质","侵蚀分布特征[偏滤器靶材]: 高场侧(内侧)与低场侧(外侧)之间存在强烈的不对称性"]},{"i":40780,"as":"本综述总结了直接海水电解制取绿氢的先进电催化剂开发策略。海水复杂成分中的高浓度氯离子会导致催化剂腐蚀和竞争副反应。文章重点归纳了近期旨在提升催化剂在恶劣盐水条件下的活性、选择性和长期稳定性的研究方法，以解决海水直接电解面临的性能和耐久性挑战。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":5.0,"t":3.0},"kp":["电解体系[绿色制氢]: 直接海水电解","性能影响因子[海水电解催化剂]: 高浓度氯离子(Cl-)"]},{"i":40781,"as":"","scd":null,"kp":[]},{"i":40782,"as":"","scd":null,"kp":[]},{"i":40783,"as":"","scd":null,"kp":[]},{"i":40784,"as":"研究首次利用可膨胀微球(EMs)实现了3D打印乙烯-醋酸乙烯酯(EVA)泡沫。EVA/EMs可膨胀长丝的EM含量为0-10 wt%，其定制密度范围为0.903-0.224 g/cm³。打印温度窗口取决于EM含量，且泡沫密度在230℃时达到最小值。微观结构分析显示出均匀的形貌特征。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["发泡微球含量[EVA可拉伸泡沫可打印长丝]: 0-10 wt%","密度范围[3D打印EVA/EM泡沫]: 0.903-0.224 g/cm3"]},{"i":40785,"as":"海藻在碳循环和可持续生物质中具有关键作用。研究揭示了两种反刍动物瘤胃生态系统内糖海带（一种褐藻）的分解代谢过程。实验结果表明，地理分布不同的反刍动物拥有保守的海藻酸盐利用基因座，这些基因座在瘤胃内的海藻降解过程中发挥着必不可少的代谢作用。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["碳源[可持续生物质应用]: 海藻","底物[反刍动物瘤胃生态系统代谢]: 褐藻 Saccharina latissima"]},{"i":40786,"as":"中缝背核(DRN)调控情绪和动机等行为。在斑马鱼中研究发现，DRN神经元中存在显著的空间拓扑结构，负责处理正在进行的活动和感觉运动反应。Gad1阳性DRN神经元在静息和感觉运动刺激期间表现出特定活动。DRN在前脑的轴突对感觉刺激和运动表现出拓扑组织的兴奋和抑制反应。","scd":{"b":6.5,"i":2.0,"r":4.0,"d":6.0,"t":5.0},"kp":["脑区功能[中缝背核(DRN)神经元]: 调节前脑感觉运动表征并参与防御行为","神经组织特征[DRN]: 具有分子学上截然不同且地形学有序的神经元分布"]},{"i":40787,"as":"针对多酚基碳点(PCDs)在阿尔茨海默病治疗中免疫清除快和病灶靶向差的问题，研究通过甘露糖-CD206受体-配体特异性相互作用，将甘露糖修饰的槲皮素纳米点锚定在BV2细胞膜片段上，制备出新型仿生纳米结构MQCM。该策略实现了84.3%的高锚定效率，并有效改善了纳米结构的稳定性。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["递送载体[阿尔茨海默病治疗]: 多酚基碳点(PCDs)","载体优势[多酚基碳点]: 固有的抗氧化活性、超小尺寸和良好的血脑屏障(BBB)渗透性","临床转化障碍[多酚基碳点]: 快速免疫清除和病灶靶向性差"]},{"i":40788,"as":"研究开发了一种由纳米颗粒修饰的液晶(LC)软界面微流控平台，用于检测水相痕量污染物。采用硅烷功能化的二氧化硅纳米颗粒修饰液晶与水相界面并诱导液晶应变。该传感器对工业染料和持久性化学品等分析物具有响应，在纳米颗粒浓度高时，检测限(LOD)达到0.1 ppb。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["界面修饰材料[微流控液晶传感平台]: 烷基封端硅烷功能化的二氧化硅纳米颗粒","检测目标[液晶软界面微流控传感器]: 工业染料、药物和持久性化学品等微量水溶液分析物"]},{"i":40789,"as":"针对阴离子脂质纳米颗粒(LNPs)在纯化过程中易发生重排和活性降低的稳定性限制，研究采用可裂解交联策略稳定阴离子LNPs。通过调节胆固醇衍生的酸可裂解交联剂和PEG-二胺的长度，在不替换母体LNP主要脂质成分的前提下，实现了结构稳定性与核酸释放之间的平衡。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["靶向倾向[阴离子辅助脂质LNP]: 偏向于脾脏表达","失稳机制[mRNA阴离子脂质纳米颗粒纯化]: 弱RNA-脂质相互作用引起纳米颗粒重排和活性降低","稳定策略[阴离子mRNA脂质纳米颗粒]: 引入胆固醇可裂解交联"]},{"i":40790,"as":"基于单层WSe2制备的并行通道可重构场效应晶体管(PC RFETs)，研究构建出紧凑型单晶体管三态内容寻址存储器(TCAM)单元。该并行通道配置实现了稳定的双极性传输，支持逻辑状态'0'、'1'和'不在乎'('X')三种并行搜索操作，克服了传统基于SRAM的TCAM需要至少16个晶体管的密度和功耗限制。","scd":{"b":7.5,"i":3.0,"r":4.0,"d":7.0,"t":5.0},"kp":["[SRAM基三态内容寻址存储器(TCAM)]: 需要至少16个晶体管实现一个存储单元","[三态内容寻址存储器(TCAM)]: 支持三种逻辑状态('0', '1'和'不关心'/'X')的并行搜索操作"]},{"i":40791,"as":"受细胞选择透过性膜的启发，研究开发了一种基于多维选择透过性膜中空微球的仿生酶固定化策略。该膜由带电聚电解质组成，通过尺寸选择截留和静电相互作用实现协同传质调控。在三酶级联反应中，通过调节表面电荷驱动互补底物的自组装，从而维持高效的反应微环境，提升级联催化效率。","scd":{"b":6.5,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["多酶级联催化系统[受限因素]: 大体积溶液中底物和中间体的不受控扩散与稀释导致整体效率受限","仿生酶固定化策略[核心机制]: 采用具有多维选择性渗透膜的中空微球来调节传质并维持高效的反应微环境"]},{"i":40792,"as":"针对抗菌高分子材料的活性-毒性权衡挑战，研究提出一种极性诱导稳定聚集策略，成功解耦了疏水性与毒性。通过设计不同长度疏水烷基链的马来酰亚胺基阳离子高分子，增加烷基链长度可促进其纳米聚集（最长碳链为廿二烷基）。这种大分子纳米聚集有效掩盖了疏水性，在保持优异抗菌功效的同时显著改善了宿主细胞毒性。","scd":{"b":6.5,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["大分子纳米聚集策略[解耦疏水性与毒性]: 通过极性诱导稳定聚集有效掩盖疏水性，在保留抗菌功效的同时降低宿主细胞毒性"]},{"i":40793,"as":"为解决极紫外(EUV)光刻技术在制造亚10纳米特征时随机变化和对准不准导致的图形转移可靠性问题，研究探索了在单层聚合物刷上使用区域选择性沉积(ASD)实现高精度图案化。通过调整铝前驱体以区域选择性渗透到聚合物中，增强了图案转移过程中的刻蚀选择性和化学稳定性。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":7.0,"t":5.0},"kp":["极紫外(EUV)光刻技术[图形化能力]: 能够实现小于10纳米的特征尺寸加工","铝前驱体[区域选择性渗透]: 调整前驱体以实现向聚合物中的选择性渗透，从而解决随机变化和套刻精度问题，实现高精度图案转移"]},{"i":40794,"as":"研究利用脉冲激光沉积技术制备了外延BiFeO3/KTaO3异质结，并在界面附近观察到反相边界(APBs)的形成。这些反相边界改变了局部极化特征，并促进了BiFeO3中带电畴壁的产生。结合高角环形暗场扫描透射电子显微镜和原子分辨率能量色散X射线光谱，成功阐明了这些反相边界的原子结构和化学组成。","scd":{"b":7.5,"i":2.0,"r":4.0,"d":6.0,"t":5.0},"kp":["BiFeO3/KTaO3界面制备工艺[成膜方法]: 脉冲激光沉积(PLD)","BiFeO3/KTaO3异质结界面[微观结构演变]: 界面附近形成反相边界(APBs)，进一步改变了局部极化特征并产生带电畴壁"]},{"i":40795,"as":"为解决无阳极液硅阳极在硫化物基全固态锂电池中因界面化学机械退化导致的低库伦效率和循环稳定性差的问题，研究将锂活性软金属（如In、Sn和Al）引入无阳极液硅电极，并通过辊转印技术进行预锂化。锂化软金属充当坚固的混合离子-电子导体，作为自适应导电相缓冲界面退化，有效减轻了电池故障。","scd":{"b":7.5,"i":4.0,"r":4.0,"d":7.0,"t":5.0},"kp":["无阳极液硅阳极[微硅材料含量]: ≥95 wt%","锂活性软金属[导电添加剂(如铟)]: 结合辊转印预锂化技术，克服硅界面化学机械快速降解导致的低初始库仑效率和循环稳定性差的问题"]},{"i":40796,"as":"可穿戴传感器通过非侵入或微创测量提供持续的健康监测，正在引发医疗分析领域的变革。文章综述了可穿戴设备在健康监测领域的最新进展，重点回顾了化学传感器在汗液、唾液、泪液、组织间液和脑脊液等生物流体中的应用，并深入讨论了该技术面临的挑战与未来发展方向。","scd":{"b":4.5,"i":2.0,"r":6.0,"d":3.0,"t":3.0},"kp":["可穿戴(生物)传感器[医疗健康监测应用]: 实现非侵入或微创测量以提供频繁或连续的患者监测"]},{"i":40797,"as":"研究采用“借用”表面增强拉曼光谱(SERS)策略，利用不同壳厚度的核壳Au@Cu2O纳米催化剂，探测了中性(KHCO3+KCl)和碱性(KOH)电解质中氧化铜表面的二氧化碳电还原路径。原位拉曼测量揭示了SERS效应在表观壳厚高达100纳米时依然存在，并分析了低频结合与高频结合的*CO中间体与电解机制的相关性。","scd":{"b":7.5,"i":3.0,"r":6.5,"d":7.0,"t":5.0},"kp":["表面增强拉曼光谱(SERS)[原位探测机制]: 采用“借用”策略，利用不同壳厚度的核壳Au@Cu2O纳米催化剂探查中性等条件下的表面CO2还原反应途径"]},{"i":40798,"as":"研究开发了一种工程化多肽水凝胶界面，将癌症干细胞(CSC)的快速诱导、原位途径监测和药物评价无缝集成。自组装的Fmoc-FF水凝胶提供3D微环境，与Fmoc-RGD多肽共组装后激活整合素介导的信号传导，在3天内实现MCF-7细胞的高效干性重编程。结合锰卟啉催化识别元件，实现了对细胞的原位监测与药物评价。","scd":{"b":7.0,"i":3.0,"r":6.5,"d":6.0,"t":5.0},"kp":["常规癌症干细胞模型构建与评价流程[耗时]: 15-30天","工程肽水凝胶界面[Fmoc-双苯丙氨酸自组装体系]: 集成快速干细胞诱导、原位途径监测和直接药物评价以缩短工作流程"]},{"i":40799,"as":"针对低温钠金属电池阳离子-溶剂相互作用弱和去溶剂化动力学迟缓的问题，研究引入环戊基甲基醚(CPME)作为低成本稀释剂，配制了NaPF6-二甘醇二甲醚(G2)/CPME局部高浓度电解液。通过空间位阻调节溶剂化结构，该策略在低温下形成了具有鲁棒无机界面相的固体电解质界面膜(SEI)，有效抑制了枝晶生长并提升了电池性能。","scd":{"b":7.5,"i":3.0,"r":6.5,"d":7.0,"t":5.0},"kp":["低温钠金属电池[失效机制]: 阳离子-溶剂相互作用受限和去溶剂化动力学缓慢导致盐沉淀或电解液凝固，阻碍离子传输","溶剂化结构[空间位阻稀释策略]: 通过调节空间位阻构建具有鲁棒无机固体电解质界面相(SEI)的电解液"]},{"i":40800,"as":"研究通过绿色凝聚过程，将多种化学性质稳定的Zr、Fe、Al和Ti基金属有机框架整合到明胶中，构建出多功能催化生物反应器复合材料。该复合材料具备高孔隙率且易于加工成片剂或整体柱等特定形状。其中，UiO-66(Zr)/明胶复合材料对亚甲基蓝等阳离子染料表现出高吸附能力和选择性，结合漆酶后可形成催化复合物用于污染物去除。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.5,"t":5.0},"kp":["MOF-生物聚合物复合材料[制备工艺]: 明胶与多种化学稳定的Zr、Fe、Al、Ti基金属有机框架通过绿色络合过程集成","UiO-66(Zr)/明胶复合材料[催化与修复]: 具备良好的MOF负载量、高孔隙率和高结晶度，可用于可持续催化和环境修复"]},{"i":40801,"as":"研究开发了一种具有动态除垢和静态杀灭双重功效的无氟水性聚氨酯防污涂料。该材料通过引入聚二甲基硅氧烷(PDMS)侧链降低表面能和弹性模量，在流体动力学剪切下实现优异的动态除垢性能；同时通过在主链共价接枝季铵盐，利用非释放型的“接触杀灭”机制克服了纯硅氧烷体系在静态环境下的防污局限，对大肠杆菌和金黄色葡萄球菌等表现出广谱防污能力。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":7.0,"t":5.0},"kp":["水性聚氨酯涂料[防污抗性]: 无氟且具备双效（动态和静态）防污效能","水性聚氨酯涂料[结构特性]: 侧链引入聚二甲基硅氧烷并在主链共价接枝季铵盐","水性聚氨酯涂料[物理特性]: 降低材料的表面能和弹性模量，并赋予涂层在水动力剪切力下优越的动态污损释放性能"]},{"i":40802,"as":"PeptiVerse是一个通用治疗性多肽特性预测平台，利用在蛋白质和化学数据上训练的大型基础模型进行开发。该平台接受氨基酸序列或修饰肽的SMILES作为输入，能够对经典序列和基于SMILES的化学修饰肽进行系统性的属性评估，并在多种多肽特性预测任务中提供了最先进的性能表现。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":4.0,"t":5.0},"kp":["治疗性肽[特性优势]: 结合了小分子和抗体的优点，提供靶点灵活性和低免疫原性","PeptiVerse[平台功能]: 利用大模型的泛化能力，实现对经典序列和基于SMILES表示的化学修饰肽的系统性可开发特性评估的统一平台"]},{"i":40803,"as":"","scd":null,"kp":[]},{"i":40804,"as":"研究开发了一种基于污泥活性炭的单原子催化剂（SBAC-SAC），同时稳定了Fe-N4、Fe2N6和2Fe-N4三种铁配位构型，用于高效活化过氧乙酸（PAA）。优化的SBAC-SAC/PAA系统实现了1.9829 min⁻¹的苯酚降解表观速率常数和86.12%的PAA利用效率，揭示了复杂配位环境下多种单原子构型在氧化剂活化与活性氧物种生成中的关键机制。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["单原子催化剂[制备载体]: 基于污泥活性炭（SBAC-SAC）开发，具备复杂配位环境及多种配位构象共存","Fe-N4单原子催化剂[催化机制]: 具备可调节的超快类芬顿反应高价铁-氧化生成路径"]},{"i":40805,"as":"针对钠离子电池硬碳负极中存在的固有性能权衡问题，提出了一种全新的瞬时锰辅助微观结构重建策略。利用设计的锰基和铵基前驱体在热解过程中的锰挥发和原位气体释放，独立定制硬碳的石墨域和孔隙结构并实现氮掺杂工程。该策略成功打破了关键结构参数间的固有耦合，显著提升了硬碳的储钠容量、倍率性能、循环稳定性和初始库仑效率。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.5,"t":5.0},"kp":["硬碳负极[钠离子电池]: 存在容量、倍率性能、循环稳定性和首效（ICE）之间的内在权衡限制","硬碳[微观结构重建策略]: 采用新型瞬时锰辅助微观结构重建策略，以打破无控制的缺陷产生和副反应导致的ICE折损限制"]},{"i":40806,"as":"","scd":null,"kp":[]},{"i":40807,"as":"","scd":null,"kp":[]},{"i":40808,"as":"","scd":null,"kp":[]},{"i":40809,"as":"","scd":null,"kp":[]},{"i":40810,"as":"","scd":null,"kp":[]},{"i":40811,"as":"圆柱体中硬球密堆积形成的手性螺旋结构对横截面变形极其敏感。通过模拟、理论和实验研究椭圆柱内的最密堆积发现，即便是极弱的截面变形也能触发全新相变。这些新相态要么消除了全局手性，要么使手性结构显著复杂化。这一机制解释了斑马鱼等生物管腔实验结果与已知理想圆管结构之间的差异。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["手性填料[约束变形敏感性]: 圆柱体内的硬球体堆积对椭圆形几何约束变形极其敏感，可用于解释斑马鱼等生物管内的已知堆积结构不匹配现象"]},{"i":40812,"as":"提出一种通过抑制不需要的辐射衰变途径来增强单光子发射器的新方法。利用定制光子带隙的W1硅光子晶体波导，选择性地将发射重定向到目标跃迁上。该方法能够在大的频率范围内实现高效的光子收集，允许对数十个铒离子掺杂剂进行单独寻址和分辨。该技术避免了光学共振器对极小模式体积和高Q值的苛刻要求，同时保持或延长了发射器的寿命。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":7.0,"t":7.0},"kp":["单光子发射器[增强机制]: 利用具有定制光子带隙的W1硅光子晶体波导，通过抑制辐射衰变提供了一种替代方法来规避光谐振器对小模式体积和高品质因数的限制要求"]},{"i":40813,"as":"太阳系诞生初期星子频繁发生碰撞破坏，而星云气体具有抑制碰撞的作用。研究表明，由星云气体消散引发的木星和土星长期共振扫掠，结合木星的平均运动共振，触发了大量偶发性的星子破坏性碰撞。当长期共振位于2-3个天文单位时碰撞发生并持续，这一强动力学机制解释了早期原行星盘内的剧烈碰撞环境。","scd":{"b":7.0,"i":1.0,"r":7.0,"d":5.0,"t":6.0},"kp":["星子破坏[诱发机制]: 偶发性破坏由气盘消散和强烈激发原行星盘的动力学机制共同导致，而星云气体能阻尼星子偏心率并抑制碰撞"]},{"i":40814,"as":"提出了一种全脑发育生物物理建模框架，用于真实再现产前大脑皮层折叠的动态过程。该框架整合了基于大规模产前磁共振成像数据推导的区域特异性生长场，结合解剖学上真实的几何形状，捕捉皮层扩张和厚度的时空变化。该模型从生物力学角度提供了可解释的机制，填补了现有模型缺乏解剖学真实性及关键皮层折叠特征捕捉能力的空白。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["皮质折叠[发育机制]: 引入整合特定区域、数据驱动型生物物理建模的全脑发育框架，以捕捉动态皮质折叠的关键标志和形态计量特征"]},{"i":40815,"as":"提出了一种能够同时、独立且动态地操控声波和电磁波的双物理可编程超表面。该超表面由324个可单独寻址且无线控制的微型电机驱动元件组成。每个元件都能对声波和电磁波实现1位反射相位调制。该技术克服了声波和电磁波物理性质及调谐机制差异的限制，实现了对两种波的亚波长尺度并发可编程控制。","scd":{"b":7.0,"i":3.0,"r":8.0,"d":5.0,"t":7.0},"kp":["可编程超表面[双物理调控]: 能够克服声波和电磁波物理性质及调谐机制差异，实现对声波和电磁波的同时可编程控制"]},{"i":40816,"as":"提出结合3D打印和电场诱导的应变工程晶面重塑策略，使Ti4O7晶体发生从(1 −2 0)晶面向高能(0 2 −2)晶面的主导转变。这一转变通过存储和释放应变能优先促进晶体生长，将活性位点从氧切换为钛，在抑制寄生水活化的同时，将活性氯生成速率提升至0.19 mg·min⁻¹·cm⁻²，达到与商用稳定阳极相当的水平。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["主导晶面过渡[应变诱导刻面策略]: 从(1 − 2 0)到高能(0 2 − 2)","合成技术[3D打印与电场诱导结合]: 实现应变能量的存储与释放以促进晶体择优生长"]},{"i":40817,"as":"展示了一种与CMOS兼容的波长级片上光谱仪。该光谱仪利用复杂光子谐振腔中逆向设计的准常态模式，将有效光路长度扩展到超出物理器件尺寸，从而产生高度解耦的光谱响应。该策略克服了扩散介质随机传输矩阵对噪声敏感且光路受限的精度瓶颈，在理论上达到最优状态，在极小器件尺寸下实现了高精度的光谱重构。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["器件尺寸[片上光谱仪]: 波长级","兼容性[光谱仪架构]: CMOS兼容","抗噪声机制[片上光谱仪]: 克服了多散射介质中因光程有限和随机传输矩阵导致的精度限制"]},{"i":40818,"as":"提出一种在光催化条件下利用胺/铵缓冲体系，实现未活化烯烃与烷基胺的高效反马尔可夫尼科夫氢胺化方法。该策略通过缓冲体系有效缓解了烷基胺单电子氧化生成的胺自由基阳离子中间体的去质子化问题，解决了传统反应需要过量烯烃以及使用α-手性烷基胺时对映体纯度严重侵蚀的挑战。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["反应条件[未活化烯烃与烷基胺的反马尔可夫尼科夫氢胺化]: 无需过量烯烃","对映体纯度[α-手性烷基胺参与反应]: 显著减少消旋化侵蚀"]},{"i":40819,"as":"提出了一种设备无关的深度学习超分辨率成像框架，可对点状发射体直接从单张分辨率受限相机图像中重建出超高分辨率图像。该模型使用涵盖广泛成像条件的多样化数值模拟数据集进行训练，具备跨不同光学设置的泛化能力。该技术完全消除了对详尽校准数据或光学系统参数的依赖，在保持超高精度的同时极大简化了部署流程。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["深度学习模型[超分辨率成像]: 设备无关且无需校准数据或光学系统参数的显式知识"]},{"i":40820,"as":"通过温和的配体取代，将Mo3S7纳米团簇均匀锚定在Ti3C2Tx MXene表面，有效调控了非平衡电子-声子相互作用。飞秒瞬态吸收光谱证实，Mo3S7纳米团簇引入了一条与内在电子-声子弛豫相竞争的快速能量收集路径，显著改变了光激发热载流子的弛豫过程，为通过化学控制减轻寄生热量积累提供了新策略。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["电子-声子相互作用调节[Ti3C2Tx MXene]: 通过表面锚定Mo3S7纳米团簇实现有效调控","能量弛豫[表面锚定Mo3S7纳米团簇]: 引入快速能量收集途径以抑制寄生热积累"]},{"i":40821,"as":"","scd":null,"kp":[]},{"i":40822,"as":"研究开发了一种基于形态的聚合物膜设计策略，利用引气化学气相沉积技术制备保形、无针孔的含氟聚合物薄膜，以增强滴状冷凝性能。通过控制膜厚度（≤100 nm与500 nm对比）和热退火处理，研究确立了纳米级聚集体形态、润湿性和冷凝动力学之间的结构-性能关系。实验表明，较薄的薄膜含有更小、更密集的聚集体且粗糙度较低，从而实现更高的成核密度。热退火则提高了结晶有序度并降低了接触角滞后。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["薄膜沉积形态[引发化学气相沉积]: 保形且无针孔的含氟聚合物薄膜","调控策略[聚合物膜形态]: 控制膜厚度与热退火以关联纳米级聚集态结构与滴状冷凝性能"]},{"i":40823,"as":"研究针对无序多孔材料中气体传输的预测难题，开发了一种广义的努森流动理论框架。研究推导出一个仅依赖平均孔径和孔隙率两个可测量结构参数的简洁渗透率方程。通过对超过5000个孔隙率范围在0至0.8之间的随机多孔网络进行蒙特卡洛模拟，验证了该理论的有效性（R² = 0.985）。非平衡分子动力学模拟进一步证实了该理论在聚合物等多孔膜材料中的适用性。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["渗透率方程[无序多孔材料中的Knudsen流动]: 广义理论框架，仅依赖于两个可测结构参数（平均孔径等）"]},{"i":40824,"as":"研究通过在极低温度（低至约50 mK）下测量高质量UTe2单晶的b轴热导率（κb/T），探究了其超导能隙的各向异性。结果显示，当温度趋于0时，κb/T表现出可忽略的残余热导率；外加磁场仅引起微弱的残余项增强。在H∥a的低磁场下观察到了阈值特征的扭折，表明准粒子垂直于磁场方向的输运发生了变化。超过该阈值后，沿磁场方向与垂直于磁场方向的输运呈现出强烈的各向异性。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":7.0},"kp":["热导率测量温度[高质量UTe2单晶]: 低至约50 mK","能隙各向异性[b轴热导率κb/T]: 极小的残余热导率，明确解析了伪点节点结构"]},{"i":40825,"as":"研究开发了一种无过渡金属和配体参与的碱催化方法，成功实现了硅杂环丁烷和苯并硅杂环丁烯中C(sp3)–Si键的区域选择性活化。该催化系统简单，可在空气气氛下顺利进行，无需惰性气体保护。多种硅杂环丁烷类底物与亲核试剂均能发生反应。该策略为生物活性分子的后期功能化提供了直接平台，能够合成多种含硅季碳骨架。机理研究初步揭示了该反应的路径。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["催化体系[硅杂环丁烷和苯并硅杂环丁烯]: 无过渡金属和无配体的碱催化","反应条件[C(sp3)-Si键活化]: 在空气气氛下无需惰性气体保护即可顺利进行"]},{"i":40826,"as":"研究开发了一种名为LuminoMem的超快、非易失性光电存储器件，专为内存计算设计。该器件采用浮栅架构，将半导体碲同时用作电荷存储层和中红外（约3.4 μm）发光介质，在单一设备中集成了电存储和光发射功能。这种设计打破了传统架构中独立读出电路和调制器造成的能耗与延迟瓶颈，克服了以往直接转换方法在开关速度或非易失性上的局限，实现了纳米级特征尺寸下的高效光电接口。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["存储器件特性[LuminoMem碲器件]: 超快、非易失性且具备中红外光致发光","系统优势[光电器件内存计算]: 克服了传统架构的读取电路瓶颈，实现直接转换"]},{"i":40827,"as":"研究利用失配化合物(SnS)1.15(TaS2)作为交替层状异质结构，探究了过渡金属二硫属化物解耦超导1H单层中的非常规超导性。通过输运、光电子能谱和扫描隧道光谱技术，证实SnS层将TaS2电子隔离成了独立的1H片层。在这种极限状态下，1H层上的隧道态密度揭示了其偏离常规各向同性s波配对的有序参数特征，展现了混合三重态-单重态的配对行为，为研究奇异超导态提供了新平台。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":6.0},"kp":["有序参数[1H单层过渡金属二硫属化物]: 混合三线态-单线态配对（显示非传统超导特征）","研究平台[失配化合物解耦超导]: (SnS)1.15(TaS2)异质结构"]},{"i":40828,"as":"","scd":null,"kp":[]},{"i":40829,"as":"","scd":null,"kp":[]},{"i":40830,"as":"研究开发了名为AlphaGEM的多功能工具箱，结合蛋白质结构比对、蛋白质语言模型和基于深度学习的预测技术，实现了高效的基因组挖掘以构建高质量的基因组规模代谢模型（GEM）。相比传统序列方法，AlphaGEM显著提高了同源关系的识别能力。该工具采用集成程序有效挖掘由非同源蛋白编码的暗代谢功能，从而扩展了物种特异性网络。该模型已在多种原核生物和真核生物中得到了验证。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["核心技术[非模式生物基因组规模代谢模型构建]: AlphaGEM工具箱","技术特征[GEM构建]: 结合蛋白质组规模结构比对、蛋白质语言模型(PLMSearch)和基于深度学习的暗代谢挖掘，增强同源关系识别"]},{"i":40831,"as":"","scd":null,"kp":[]},{"i":40832,"as":"针对现有语音脑机接口（BCI）需要大量特定患者数据导致难以部署的问题，研究通过将患者特有的神经数据对齐到共享的潜在空间，证明语音BCI可以基于跨患者合并的数据进行训练。研究利用典型相关分析和高密度微电极阵列技术克服了患者神经解剖学差异和电极放置不同带来的挑战。这一方法有效结合了多位患者的数据，加速了BCI系统的可用性和成功部署。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":5.0,"t":6.0},"kp":["数据采集需求[传统语音脑机接口]: 需要长时间收集大量患者特定数据","潜在表示[跨患者语音解码]: 采用多患者共享的潜在表示以克服神经解剖差异并加速部署"]},{"i":40833,"as":"","scd":null,"kp":[]},{"i":40834,"as":"","scd":null,"kp":[]},{"i":40835,"as":"","scd":null,"kp":[]},{"i":40836,"as":"研究在水相条件下，利用缺陷型Wells-Dawson多金属氧酸盐K10P2W17O61•20H2O作为配体，成功获得了分子体系中四价铽Tb(IV)存在的确凿证据。研究展示了配合物K16Tb(IV)(P2W17O61)2•39.85H2O的单晶结构，并通过广泛的光谱学表征证实了其结构特征。这一进展突破了高价镧系元素化学通常仅限于非水条件的限制，实现了环境条件下的稳定存在。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["配体特性[实现Tb(IV)多金属氧酸盐稳定]: 定制配体以促进在环境和水相条件下的四价镧系元素稳定性","价态[分子体系中的铽(Tb)]: 四价 (Tb(IV))"]},{"i":40837,"as":"研究展示了可见光波长下工作的交互式可寻址有机元设备，通过将超薄聚苯胺与等离子体纳米天线共形集成，实现了局部电化学调制的独立开关超表面像素。利用平面扇出架构构建了二维超表面阵列，其中每个像素在电子学上相互隔离，并在亚伏特电压下驱动，实现毫秒级开关动态。该技术克服了超表面像素尺寸缩小对电气互连和局部可调性带来的限制。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["活性材料[可见光波长二维可寻址有机元设备]: 超薄聚苯胺","集成工艺[有机元设备]: 超薄聚苯胺与等离激元纳米天线保形集成以实现像素级独立寻址"]},{"i":40838,"as":"本综述重点总结了截至2025年3月，地球储量丰富的3d过渡金属催化对映选择性C-H官能化反应的最新进展。内容涵盖了内界和外界两种反应机制，强调了3d金属催化剂有别于贵金属的独特内在性质和反应活性。文章详细讨论了该领域在复杂分子构架的从头构建和后期修饰中面临的挑战，以及推动这些技术发展的核心战略解决方案，展现了其在下一代合成范式中的潜力。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":5.0,"t":4.0},"kp":["催化剂类型[对映选择性C-H官能化]: 地球丰富的3d过渡金属催化剂","催化机制[地球丰富3d过渡金属]: 具有独特的内在性质和反应性谱图，用于复杂分子架构的从头构建和后期修饰"]},{"i":40839,"as":"探讨“预测然后优化”框架，利用大模型多步时间序列预测（LM-MTSF）为主动配电网的稳健运行提供数据驱动。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[主动配电网稳健运行优化]: 采用大模型多步时间序列预测（LM-MTSF）提供数据驱动的“预测然后优化”框架"]},{"i":40840,"as":"探讨风电功率波动对质子交换膜（PEM）水电解槽性能退化机制的影响，研究可再生能源制氢系统的耐久性。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":3.0,"t":5.0},"kp":["[质子交换膜(PEM)水电解槽]: 风电功率波动直接影响其性能退化机制"]},{"i":40841,"as":"提出一种基于模型的功率分配方法，用于优化电流波动下碱性水电解集群的运行策略，从而提升系统整体效率。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":3.0,"t":5.0},"kp":["[电流波动下碱性水电解集群]: 采用基于模型的功率分配方法提升系统整体效率"]},{"i":40842,"as":"提出一种可解释的因果分析方法，用于研究广域电动汽车充电需求时空预测中的误差来源及其因果关系。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[广域电动汽车充电需求时空预测误差]: 采用可解释的因果分析方法研究误差来源与因果关系"]},{"i":40843,"as":"研究针对无机氮源电合成有机氨基酸过程中面临的无机氨路径竞争性动力学抑制问题，开发了一种可编程反应网络分叉（PRNB）策略。研究指出反应瓶颈源于不可控的关键中间体羟胺(*NH2OH)。通过使用原子级精确的双位点金属烯，该策略将*NH2OH的反应途径从加氢转向C-N偶联，成功逆转了路径的选择性。这使得系统能够有效绕过竞争性的无机氨生成路径，实现了高选择性的氨基酸电合成。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["关键中间体[氨基酸电合成瓶颈]: 羟胺 (*NH2OH)","选择性控制[有机C-N偶联途径]: 通过编程反应网络分叉控制不可控的“守门人”中间体，以抑制竞争性无机氨(NH3)路径"]},{"i":40844,"as":"研究综合能源系统中混合储能系统的容量优化配置方法，旨在提升系统的经济性、可靠性与能源利用效率。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[综合能源系统混合储能]: 开展容量优化配置方法研究以提升经济性、可靠性与能源利用效率"]},{"i":40845,"as":"本综述系统回顾了卤化物正极活性材料在全固态锂电池中的发展历程，重点关注其在多电子反应机制和单相界面工程方面的最新突破。卤化物正极材料具有固有的高离子/电子电导率、多电子转移能力，以及消除非活性组分的单相电极架构潜力。文章强调了元素和结构单元如何控制离子和电子传输，深入探讨了反应机理、界面稳定性及循环过程中的结构演化等核心挑战。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["卤化物正极活性材料[全固态锂电池]: 具有本征高离子/电子电导率、多电子转移能力以及消除非活性组分的单相电极架构潜力"]},{"i":40846,"as":"介绍一种无线、生物可吸收的摩擦纳米发电机系统，用于术后疼痛管理与神经刺激，设备可在体内自行降解。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":3.0,"t":6.0},"kp":["材料特性[用于术后疼痛控制的摩擦电系统]: 无线、生物可吸收、可在体内自行降解","[疼痛管理与神经刺激]: 应用无线生物可吸收摩擦纳米发电机系统"]},{"i":40847,"as":"针对钙钛矿太阳能电池中异质层界面易发生横向化学聚集和纵向机械脱层的问题，研究引入了1,3,6,8-芘四磺酸四钠盐（PTS）超薄界面层来分子级稳定钙钛矿/C60界面。PTS分子中的磺酸基团锚定在钙钛ite界面上，而平行排列的芘核与C60分子建立了稳固的π-π相互作用。重建后的界面增强了粘附力并限制了C60分子的移动性，从而实现了双向的化学机械界面稳定效果，显著提升了光电性能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["界面稳定剂[钙钛矿太阳能电池分子层面稳定]: 1,3,6,8-芘四磺酸四钠盐 (PTS)","失效机制[钙钛矿/C60异质层界面]: 易发生面内化学聚集和面外机械剥离的并发问题"]},{"i":40848,"as":"研究通过大规模密度泛函理论计算，从分子轨道层面揭示双原子催化剂（DACs）的协同效应机制。分析表明，协同效应源于M1和M2位点d原子轨道组合形成的分子轨道。从M1-N3-M2-N3-C到M1-N4-M2-N4-C，M1/M2-N的键强出现平均弱化现象，这主要归因于轨道重叠方式从直接的dx2-y2轨道重叠转变为涉及b杂化的氮介导相互作用。该发现为理解双原子催化剂的结构稳定性和吸附行为提供了精确的分子轨道视角。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["协同催化机制[M1M2N6双原子催化剂]: 源于M1和M2位点之间d原子轨道组合形成的分子轨道","计算方法[双原子催化剂配位环境机制解析]: 大规模密度泛函理论(DFT)计算"]},{"i":40849,"as":"评论文章分析了国际能源署（IEA）在2021年与2026年初对2030年氢能部署预测之间存在的超过90%的巨大差距。尽管2026年的预测引发了对氢能在净零排放路径中长期作用的怀疑，但通过社会技术系统和采用准备度视角评估，氢能作为关键脱碳杠杆的潜力依然明显。特别是在中国和长途航空等特定领域，氢能正处于引领地位并展现出确定性前景。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":5.0,"t":7.0},"kp":["部署预测差距[国际能源署2030年氢能部署]: 90%以上（2021年预测与2026年早期评估相比）","关键脱碳潜力[特定情境下的氢能应用]: 通过社会技术系统和采用准备度视角评估，氢能在特定背景下（如中国）展现出作为关键脱碳杠杆的潜力"]},{"i":40850,"as":"文章报道了一种光催化硝基烷烃脱硝同构与交叉偶联合成烯烃的新策略。该方法通过光催化氧化简单未预功能化的硝基烷烃，原位生成α-硝基烷基自由基，随后与另一个硝基烷烃发生加成反应并进行双重脱硝，最终生成烯烃。该转化兼具亲核和亲电特性，打破了经典的McMurry型偶联反应限制，具备良好的底物普适性和可扩展性，提供了一种温和高效的烯化路线。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[光催化脱硝偶联]: 通过氧化简单未预官能化的硝基烷烃生成α-硝基烷基自由基"]},{"i":40851,"as":"设计一种新型超氟化分子片段，具备良好水溶性与可修饰性，适用于高分辨率的19F磁共振成像（MRI）应用。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["分子特性[3,5-双(2-六氟异丙氧基)苯基超氟化片段]: 具备良好水溶性与可修饰性","[高分辨率磁共振成像(19F MRI)]: 适用作超氟化部分"]},{"i":40852,"as":"研究开发了一种基于还原金红石TiO2上的Ti3+-O酸碱对的无贵金属催化剂，在无外部加热条件下实现了高效全光谱太阳能驱动非氧化乙烷脱氢（NOEDH）。在750℃下优化的还原TiO2展现出392.0 mmol g⁻¹ h⁻¹的乙烯生成速率，比未还原的原始TiO2高1107倍。同时，该催化剂实现了94.9%的乙烯选择性，突破了热力学平衡限制，表现出卓越的光热催化性能。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[太阳能驱动光热非氧化乙烷脱氢]: 无需外部加热且无贵金属催化剂即可实现高催化活性与高乙烯选择性","活性位点[还原金红石TiO2]: Ti3+-O酸碱对"]},{"i":40853,"as":"提出一种结合物理先验与解耦外源感知的深度学习网络，用于提升商业园区综合能源系统多能负荷预测的可靠性。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[商业园区级综合能源系统多能负荷预测]: 结合物理先验与解耦外源感知的深度学习网络提升可靠性"]},{"i":40854,"as":"针对质子交换膜燃料电池（PEMFCs）中全氟磺酸（PFSA）离聚物引起的铂催化剂中毒问题，研究引入了一种基于离聚物包覆单晶Pt(111)的电化学探针。该探针可量化PFSA的吸附覆盖度和强度，揭示了阳离子添加剂抑制Pt中毒的机制。研究发现阳离子水合能与PFSA吸附之间存在反相关性，并据此设计了一种水合性极低的四甲基铵锚定共价有机框架（COF）复合PFSA离聚物，有效提升了催化性能。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[全氟磺酸离聚物中毒评估]: 利用包覆离聚物的单晶Pt(111)电化学探针进行定量评估"]},{"i":40855,"as":"本综述总结了手性钙钛矿纳米晶在材料和器件工程领域的最新研究进展。手性钙钛矿纳米晶能够同时控制半导体器件中的自旋和光的偏振，从而实现无需磁性组件的高效自旋发光二极管。文章重点突出了该领域面临的关键机遇和挑战，为开发具备增强功能和更低制造复杂度的下一代光电技术提供了发展路线图。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[自旋发光二极管]: 采用手性钙钛矿纳米晶控制自旋和偏振，无需磁性组件"]},{"i":40856,"as":"最新实验表明压电效应不仅存在于固体中，也存在于特定液体中。室温离子液体、深共晶溶剂以及掺杂这些液体的固态聚合物电解质，在机械应力作用下通过压力诱导的瞬时结晶现象产生电荷。该过程在液相内部形成了暂时性的非中心对称结构域。这一新发现为柔性传感器、软体机器人以及无易碎组件的自供电能量收集系统开拓了全新应用方向。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[压电效应产生机制]: 室温离子液体、深共晶溶剂及其固态聚合物电解质在机械应力下通过压力诱导的瞬态结晶产生电荷","非中心对称结构域[液相中]: 压力诱导瞬态结晶形成暂态区域"]},{"i":40857,"as":"为高效分离丙炔/丙烯（C3H4/C3H6），研究开发了一种名为SJTU-520的高孔隙率坚固锆金属有机框架（MOF）。该材料在三维空间中融入了源自环四苯并辛的形状持久分子阵列，作为优先捕获C3H4的选择性位点。与传统超微孔MOF相比，SJTU-520克服了C3H4吸附容量低和吸附焓高的缺陷，实现了高C3H4吸附容量，并在1 bar下创下C3H4/C3H6吸附比的新纪录，为节能生产聚合物级C3H6提供了新途径。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[丙炔/丙烯分离]: 将形状持久的分子炔基陷阱排列到高孔隙度和坚固的锆金属有机框架中实现高效吸附分离"]},{"i":40858,"as":"研究报道了一种通过光诱导交叉脱硝烯化反应制备立体定向前三取代和四取代烯烃的新方法。在可见光激发下，原位生成的硝基烷烃发生脱硝交叉偶联的“光拼接”反应。该转化能够兼容多种含羰基和杂环的功能化硝基烷烃底物，弥补了传统烯烃复分解和羰基烯化反应在空间拥挤环境下的不足，并具备高效可放大的特点。机理研究证实了光引发的亲核-自由基取代与自由基耦合机制。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[交叉脱硝烯化]: 光诱导硝基烷烃交叉脱硝偶联合成立体定义的三取代和四取代烯烃"]},{"i":40859,"as":"研究利用多域弛豫色散核磁共振（NMR）技术，结合域选择性15N标记，解析了线性双泛素（Met1连接）与HOIL-1L NZF结构域的结合动力学路径。研究克服了序列相同结构域的光谱重叠问题，发现该结合过程经历了一个明显的三态途径，其中包含快速的中间态门控步骤。这一发现证明了分子识别不仅由最终复合物的结构互补性决定，还高度依赖于其形成的动力学路径。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[多域弛豫色散NMR]: 解析HOIL-1L选择性识别线性双泛素的中间门控结合途径"]},{"i":40860,"as":"研究提出了一种结合插层型LiNixCoyMn1-x-yO2（NCM）与转换型氧气（O2）的混合正极。通过原位电化学原子力显微镜（EC-AFM）证实，NCM正极的过锂化效应在放电过程中显著提升了材料的电子导电性并暴露出大量活性位点，从而诱导了Li2O2的生成。电化学测试表明，这种插层与转换机制的有效耦合大幅提升了高能量密度电化学储能器件的整体性能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["混合正极体系[锂离子/锂氧混合电池]: 结合插层型LiNixCoyMn1-x-yO2(NCM)与转换型氧气(O2)","[插层-转换耦合机制]: 原位揭示纳米尺度下的电化学储能结构-性能关系"]},{"i":40861,"as":"研究提出了一种还原性N-甲基化策略，能够在温和条件下将亚胺连接的共价有机框架（COFs）普遍转化为结晶的三级胺连接框架（NMe-COFs）。该转化不仅保留了原有的结构有序性，还赋予了材料强烈的给电子能力和氧化还原响应特性。在衍生材料中，COF-300-NMe展现出提高11倍的碘吸附量，并表现出独特的“开门”吸附特征。计算研究表明，这归因于结构柔性的增强。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["合成策略[共价有机框架后修饰]: 还原N-甲基化将亚胺连接的COFs温和转化为结晶叔胺连接的框架"]},{"i":40862,"as":"研究探讨了木质纤维素生物质衍生含氧化合物的电化学还原升级。由于生物质分子含有多个含氧官能团（如羟甲基和羰基），选择性还原特定基团极具挑战性。电化学测试表明，对于HMF衍生物，醇氢解过程（断裂C-O醇键）极为困难；而HMF本身在酸性水溶液中则容易发生醇氢解。这一差异主要归因于HMF与其衍生物分子结构中特定官能团的存在与否。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[电化学醇氢解]: 针对木质纤维素衍生的芳香族含氧化合物，实现特定含氧官能团的选择性还原"]},{"i":40863,"as":"研究结合实验与计算方法，系统探究了卤素取代对Cu6PS5X（X=Cl, Br, I及混合卤素）银辉石材料结构、晶格动力学及输运性质的影响。室温下所有组分均表现出平均立方F4̅3m结构，而局部结构分析揭示了偏离立方对称性的现象。研究结果为通过组分调控来精准调节Cu基银辉石材料的相演变、局部结构以及电子和离子输运特性提供了统一认识。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["研究对象[Cu基卤化物银辉石]: 调查卤化物取代对相演变、局部结构、晶格动力学及电子/离子输运性质的影响"]},{"i":40864,"as":"通过探索NbI4、Li2(CN2)和Li2O组成的反应体系，研究发现了两种新型铌氧碘化物团簇材料Nb6O3I15和Nb11O6I24。单晶X射线衍射结构表征显示，这两种化合物均基于蝴蝶形的氧覆盖铌簇[Nb4O]构建。在Nb6O3I15中，[Nb4O]核心通过两个[NbO]单元的延伸扩展，进一步形成了三维框架结构。该发现拓展了氧覆盖过渡金属团簇材料的结构多样性与化学探索边界。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":5.0,"t":5.0},"kp":["新发现材料[铌氧碘化物团簇]: Nb6O3I15和Nb11O6I24","能带结构[Nb6O3I15]: 零间接带隙和平带"]},{"i":40865,"as":"研究完成了甲藻来源的“超碳链化合物”苯酚A（benthol A）的全合成。合成过程证实，其骨架35个手性中心中位于C40的仲羟基构型在分离团队的原始分配中被错误指认。原始分配仅基于计算数据且置信度高达99.93%，产生了误导。这一多汇聚合成路线仅用32步最长线性序列成功合成了该复杂的海洋聚醚天然产物，纠正了先前的立体化学错误。","scd":{"b":5.0,"i":1.0,"r":5.0,"d":4.0,"t":5.0},"kp":["手性中心数量[Benthol A分子骨架]: 35","C40羟基构型[分离团队初始赋值]: 错误赋值"]},{"i":40866,"as":"研究提出了一种基于不对称配体修饰的化学策略，通过打破对称性将原始二维反铁磁金属有机框架转化为交变磁性候选材料。以酞菁铬为概念验证模型，不对称修饰降低了磁性Cr中心的局部位点对称性，成功产生了依赖于动量的自旋劈裂和各向异性。该工作证明了通过化学对称性破缺工程化诱导交变磁性转变的可行性，为自旋电子学材料的设计开辟了新途径。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[反铁磁体向交变磁体转变策略]: 基于不对称配体修饰的化学驱动对称性破缺","净磁化强度[交变磁体相态]: 为零"]},{"i":40867,"as":"研究开发了一种立体选择性合成脱氧核苷酸-磷酸-ADP核糖基探针（dN-P-ADPr）的方法。该探针代表末端DNA-ADP核糖基化的天然片段，利用温和且受控的糖基化反应构建了核糖基-磷酸键，并通过P(III)-P(V)偶联建立了焦磷酸桥。结合酶促分析，该探针成功破译了可逆DNA-磷酸ADP核糖基化的特异性分子机制，揭示了其在DNA损伤反应中的非典型生物学功能。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["化学探针[ADP-核糖基化分析]: 结构明确且立体选择性合成的核苷酸-磷酸-ADP-核糖基探针"]},{"i":40868,"as":"本综述详细介绍了气动智能纺织致动器的设计、制造、传感技术及其应用。这种柔软的可穿戴系统利用空气压力使织物产生运动，在触觉反馈、康复医疗和物理辅助等领域展现出巨大应用潜力。文章还指出了未来智能可穿戴技术向更智能、更舒适方向发展的研究趋势与技术路线。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[气动智能纺织品]: 利用气体压力使织物产生运动的软性可穿戴致动系统"]},{"i":40869,"as":"研究揭示了微滴中酚类物质加速的光自聚合促生棕碳的机制。在紫外光照射下，微滴中酚类物质的光解转化效率比体相溶液高出两个数量级。通过高分辨质谱和理论模拟证实，气-水界面（AWI）的界面限制低聚反应是生成具低聚物特征棕碳的主导途径。该研究深入解析了酚类物质在微滴界面快速转化为大气棕碳气溶胶的微观动力学机制。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["转化效率[微滴空气-水界面紫外光解]: 比本体溶液高2个数量级"]},{"i":40870,"as":"结合稀疏云端充电数据与TabNet深度学习算法，对共享电动自行车退役锂电池进行多故障模式的智能诊断。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[二次寿命锂电池多故障诊断]: 结合稀疏云端充电数据与TabNet深度学习算法进行智能诊断"]},{"i":40871,"as":"通过实验研究探讨风冷型质子交换膜燃料电池在高空低温低压环境下的无人机飞行特性与输出性能表现。","scd":{"b":5.0,"i":5.0,"r":5.0,"d":4.0,"t":5.0},"kp":["应用环境[风冷质子交换膜燃料电池无人机]: 高空低温低压环境下的飞行特性与输出性能表现"]},{"i":40872,"as":"二维红外光谱已成为研究生物分子结构、动力学和分子间相互作用的成熟方法。得益于激光技术的进步，目前仅需极少量样本即可在几分钟内获取数据，且支持在生理相关条件下进行测量。这项技术已成功转型为生物分析工具，能够有效表征样本特性，并为药物设计和生物医学诊断等领域的决策提供数据支持。","scd":{"b":4.0,"i":4.0,"r":6.0,"d":5.0,"t":3.0},"kp":["采集时间[2D-IR光谱数据集]: 数分钟内","测试条件[2D-IR光谱分析]: 生理相关条件且仅需极微量样品"]},{"i":40873,"as":"聚焦于设计具有低制造成本且能够实现快速非晶化的固态电解质材料，旨在推动全固态电池的商业化应用。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":4.0,"t":6.0},"kp":["固态电解质[全固态电池]: 低制造成本且能够实现快速非晶化","[固态电解质设计]: 推动全固态电池的商业化应用"]},{"i":40874,"as":"通过竞争性占空机制诱导晶界富集，开发无裂纹层状正极材料，提升钠离子电池结构稳定性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":4.0,"t":6.0},"kp":["[钠离子电池无裂纹层状正极]: 竞争性占空机制诱导晶界富集","结构稳定性[钠离子电池正极材料]: 消除裂纹并得到提升"]},{"i":40875,"as":"利用咔唑顶部界面分子工程，抑制混合卤化物钙钛矿太阳能电池的相分离，提升器件稳定性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":4.0,"t":6.0},"kp":["[混合卤化物钙钛矿太阳能电池相分离]: 利用咔唑顶部界面分子工程加以抑制","器件稳定性[混合卤化物钙钛矿太阳能电池]: 减轻相分离后得到提升"]},{"i":40876,"as":"通过调控芴基阴离子交换膜的分子量以增强聚合物链缠结，优化性能，助力高效CO2电解。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":3.5,"t":6.0},"kp":["聚合物链缠结[芴基阴离子交换膜]: 通过调控分子量来增强","[高效CO2电解]: 优化芴基阴离子交换膜分子量驱动链缠结以助力该过程"]},{"i":40877,"as":"针对《哈伯德激子的量子控制》一文发布的出版商更正启事，旨在对原文内容进行修订。","scd":{"b":8.5,"i":1.0,"r":5.0,"d":3.0,"t":5.0},"kp":[]},{"i":40878,"as":"最新空间站研究揭示了宇航员在太空微重力环境下身体消瘦的原因。实验表明，在微重力环境中培养的人类细胞，其产生的线粒体蛋白数量显著减少。这一发现指出线粒体功能的抑制是导致太空环境中生物体肌肉萎缩或身体消瘦的关键机制。","scd":{"b":6.5,"i":2.0,"r":5.0,"d":3.0,"t":6.0},"kp":["线粒体蛋白质产量[微重力环境培养的人体细胞]: 减少"]},{"i":40879,"as":"随着自动化工具加速了软件漏洞的发现与利用，网络安全防御面临前所未有的挑战。为跟上这一加速进程，各组织机构必须重新设计其网络安全防御体系和工作流程。研究人员和技术人员需做好充分准备，以应对由人工智能驱动的自动化攻击手段带来的安全威胁。","scd":{"b":4.0,"i":4.0,"r":4.0,"d":2.0,"t":5.0},"kp":["[自动化AI工具]: 加速软件漏洞的发现与利用，迫使组织重构防御和工作流"]},{"i":40880,"as":"全球人工智能安全领域的中心正在发生转移，英国正逐渐取代硅谷成为全球AI安全之都。英国凭借其不断发展壮大的AI安全生态系统，在该领域的影响力日益增强。这一趋势表明，英国在引领全球人工智能安全研究、政策制定及产业发展方面占据了核心地位。","scd":{"b":2.0,"i":3.0,"r":4.0,"d":2.0,"t":5.0},"kp":[]},{"i":40881,"as":"","scd":null,"kp":[]},{"i":40882,"as":"","scd":null,"kp":[]},{"i":40883,"as":"研究提出一种利用海上太阳能将甲烷和海水转化为氯甲烷的串联流动系统。该系统通过海水淡化产生淡水，产生的富含氯离子的高浓度海水在漂浮的Pt-TiO2光催化剂作用下发生甲烷氯化反应。其技术核心在于调整催化剂界面的酸碱微环境与电子结构，利用羟基和氯自由基高效实现碳氢键活化及偶联，为海洋可燃冰甲烷资源的利用提供了新路径。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[甲烷氯化为氯甲烷]: 串联流动系统耦合海水淡化与漂浮光催化剂的三相界面反应"]},{"i":40884,"as":"探讨玻璃态物质在高温活化环境下的传输解耦现象，揭示其动力学机理与高温下的行为特征。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":3.0,"t":6.0},"kp":["[玻璃态物质动力学]: 在高温活化环境下发生传输解耦现象"]},{"i":40885,"as":"评估海水环境对先进固体氧化物电解电池性能的影响，分析电解池及堆组件的降解机制。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":3.0,"t":5.0},"kp":["退化机制[海水环境下的固体氧化物电解电池]: 评估分析海水环境对电解池及堆组件降解行为的具体影响"]},{"i":40886,"as":"提出基于双曲偏微分方程的氢储能系统稳健规划模型，以增强电-水-气耦合网络的系统弹性。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["规划模型[双曲偏微分方程约束]: 应用于氢能存储系统稳健规划以实现电-水-气网络弹性"]},{"i":40887,"as":"结合变分不等式与合作博弈论，研究电力与天然气系统的分布式优化调度策略，实现多能协同。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[电力与天然气系统]: 结合变分不等式与合作博弈论实现分布式优化调度与多能协同"]},{"i":40888,"as":"针对海上风电场，考虑任务不确定性及气象预测，提出面向弹性的物联网维护规划与路线优化方法。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[海上风电场物联网]: 考虑任务不确定性及气象预测实现面向弹性的维护规划与路线优化"]},{"i":40889,"as":"探讨在以水电为主的电力系统中，高温地热资源的优化配置与利用策略，以提升系统整体效益。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[高温地热资源]: 在以水电为主的电力系统中进行优化配置与利用策略研究"]},{"i":40890,"as":"研究屋顶光伏在城市能源转型中对能源公平的影响，量化分析社会与能源之间的权衡关系。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[屋顶光伏]: 量化分析社会与能源转型中的能源公平及权衡关系"]},{"i":40891,"as":"利用扩展的输入输出线性规划框架，追踪并内生化电力系统扩容过程中的供应链碳排放。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[电力系统扩容]: 采用扩展的输入输出线性规划框架追踪并内生化供应链二氧化碳排放"]},{"i":40892,"as":"通过对123个国家进行聚类分析，评估不同转型背景下电气化进程对能源安全与公平的影响。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[电气化转型]: 通过对123个国家进行聚类分析评估能源安全与公平的影响"]},{"i":40893,"as":"探讨在单机成本不确定的条件下，采用稳健多目标优化算法进行风电场布局优化的方法。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[风电场布局优化]: 在单机成本不确定条件下采用稳健多目标优化算法"]},{"i":40894,"as":"Benthol A是一种提取自甲藻的海洋天然产物，具有强效抗疟疾和显著抗病毒活性。其结构包含一条具有72个碳原子的线性主链、35个立体中心及4个立体烯烃。研究团队首次完成了该复杂目标分子的全合成，并在合成过程中发现合成样本的碳-13核磁共振化学位移等数据存在明显偏差，从而证实并修正了原始提取团队通过波谱学指派的分子立体结构。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["碳原子数[Benthol A线性骨架]: 72个","手性中心数量[Benthol A线性骨架]: 35个","生物活性[Benthol A海洋天然产物]: 强效抗疟疾和显著的抗病毒活性"]},{"i":40895,"as":"质子交换膜水电解（PEMWE）技术与间歇性可再生能源结合是生产绿氢的关键技术，但阳极析氧反应（OER）中铱的高成本阻碍了其规模化应用。研究合成了四种晶相的氧化铱（亚稳态1T、3R、Tri及常规金红石相），并在实际PEMWE条件下证实了其OER活性具有严格的晶相依赖性。其中，1T-IrO2展现出优异的催化潜力，为通过晶体相工程降低铱用量提供了明确依据。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["阳极析氧反应(OER)催化剂[PEMWE]: 氧化铱(IrO2)","[相工程调控策略]: 提升催化剂本征活性以克服缓慢动力学并实现与间歇可再生能源的直接耦合"]},{"i":40896,"as":"混合锡-铅钙钛矿是构建高效全钙钛矿叠层太阳能电池的核心。研究表明，通过可控地引入甲基铵（MA）阳离子，能够有效调控混合锡-铅钙钛矿形成的热力学和结晶动力学。该策略促进了均匀成核，成功抑制了锡-铅的相偏析，并防止了二价锡离子的氧化。这种相均质化和缺陷化学的优化显著减少了非辐射复合，大幅提升了电池的光电转换效率。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["A位阳离子[混合锡铅钙钛矿]: 甲脒(FA)主导并掺入少量甲胺(MA)","[热力学景观调控]: 实现了相均匀性和结晶动力学的同步调节以提升全钙钛矿叠层太阳能电池效率"]},{"i":40897,"as":"","scd":null,"kp":[]},{"i":40898,"as":"研究成功研发出一种紧凑型的放射性分子源装置。这种微型化、桌面级的放射性分子制备与操控技术，为基础物理学验证提供了全新手段。该成果通过安全便捷地获取放射性分子，使得科学家能够在实验室常规条件下开展对原子核基本对称性等物理定律的极端敏感性测试，拓展了核物理与粒子物理的研究边界。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":[]},{"i":40899,"as":"","scd":null,"kp":[]},{"i":40900,"as":"探讨人工智能的谄媚行为（迎合用户偏好），并研究如何从社会层面对该现象进行校准。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":3.0,"t":6.0},"kp":["[谄媚人工智能]: 针对大模型迎合用户偏好的行为从社会层面进行校准"]},{"i":40901,"as":"研究实现了一种具有量子态操控能力的单电子存储器器件。该二维器件基于共面漏极-沟道-源极结构，有效克服了器件微缩带来的边缘电容效应。实验观测到，在单个电子数量发生改变时，器件表现出0.5伏的非易失性阈值电压漂移。此外，研究还验证了与编程电压相关的量子行为，并预测与观测到了由量子态转换引发的独特量子存储效应。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":7.0,"t":7.0},"kp":["器件结构[二维单电子存储器]: 共面漏极-沟道-源极结构","[边缘电容抑制效应]: 克服了尺寸缩小引发的边缘电容放大问题，成功观测到单电子存储与量子态操纵"]},{"i":40902,"as":"","scd":null,"kp":[]},{"i":40903,"as":"","scd":null,"kp":[]},{"i":40904,"as":"","scd":null,"kp":[]},{"i":40905,"as":"研究采用耦合结构引导的反向折叠模型与进化残基约束的蛋白质设计策略，成功生成了具有活性的最小CRISPR-Cas12类似核酸酶TnpB的变体（SynTnpBs）。高通量筛选表明，这些人工智能设计的变体在细菌、植物和人类细胞中均保留或超越了野生型的基因编辑活性。冷冻电镜结构解析揭示了变体在RNA-DNA界面间存在稳定接触，拓展了可编程基因组编辑的能力。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["设计策略[最小RNA引导核酸酶]: 耦合结构引导的逆折叠模型与演化约束的残基信息","[蛋白质工程结论]: 成功生成具有高催化活性的多样化TnpB变体，拓展了可编程基因组编辑能力"]},{"i":40906,"as":"研究利用原位透射电子显微镜，对几何受限纳米团簇内的固液相变进行了原子尺度观测。通过在可调纳米间隙内操控单个临界尺寸的铋纳米团簇，实现了其从准非晶态纳米盘、结晶纳米线到液态纳米液滴的可逆循环转变。实验证实，决定相变发生的关键参数是纳米团簇的长宽比而非体积。此外，空间受限状态还强制纳米线采取了特定的优先晶体取向。","scd":{"b":8.5,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["观测手段[临界尺寸铋纳米团簇的固液相变]: 原位透射电子显微镜","[几何受限纳米团簇]: 在纳米间隙中实现了从准非晶纳米盘到结晶纳米线再到液态纳米液滴的可逆循环"]},{"i":40907,"as":"研究结合沉积物岩芯、二氧化碳通量测量与遥感技术，量化了咸海干涸造成的有机碳流失。自1960年以来，裸露的湖床沉积物已释放了204±53太克碳，而植被生长的抵消量不足1%。这些巨大的碳排放量改变了区域碳收支核算，使咸海流域从碳汇转变为净碳源。若重新注水淹没，可阻止额外165±13太克碳的释放，证实了生态修复同样具有关键的气候调节价值。","scd":{"b":3.0,"i":4.0,"r":7.0,"d":9.0,"t":5.0},"kp":["碳释放量[咸海干涸裸露湖床沉积物]: 204 ± 53 太克碳"]},{"i":40908,"as":"研究成功在桌面级装置上实现了放射性分子的制备与光谱分析。通过结合微量放射性靶标制备、低温缓冲气体中的光驱动化学反应以及低背景光谱检测方法，合成了氢氧化镭、一氘氧化镭和一氟化镭分子（226RaOH、226RaOD、226RaF）。这些分子在实验中实现了气相合成与低温冷却，并在实验室坐标系下完成了高分辨率激光光谱测量，为精确核物理与粒子物理测试提供了新途径。","scd":{"b":8.5,"i":2.0,"r":8.0,"d":7.0,"t":6.0},"kp":["目标分子[冷放射性分子合成与光谱学]: 氢氧化镭、一氘氧化镭和一氟化镭(226RaOH, 226RaOD等)","[制备与表征技术]: 气相合成结合低温冷却与高分辨率激光光谱学"]},{"i":40909,"as":"研究通过热机械纳米成型技术合成了具有单晶特性的Weyl半金属砷化铌（NbAs）纳米线，其直径可控制在40纳米。测试表明，NbAs纳米线的电阻率随直径减小而降低，40纳米纳米线在室温下电阻率为10.5±1.9微欧·厘米，比块体材料低约70%。理论计算表明，这种电阻率的降低归因于有限温度下具有长载流子寿命的表面主导导电机制。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":8.0,"t":7.0},"kp":["材料尺寸[Weyl半金属NbAs纳米线]: 控制直径低至40纳米","室温电阻率[40纳米直径的NbAs纳米线]: 呈现随直径减小而降低的特性，满足下一代低阻互连需求"]},{"i":40910,"as":"针对“谄媚人工智能的社会校准”这一研究，学术界或读者的回应、评论与深入探讨。","scd":null,"kp":[]},{"i":40911,"as":"为解决环境条件下大面积打印钙钛矿薄膜的不均匀性问题，研究提出了一种相锁定策略，通过建立动态演化的水分缓冲晶间网络，实现了α相FAPbI3的时空均匀结晶。该方法有效防止了环境湿度引起的过早降解并消除了方向性不均匀现象。基于刮涂法制备的钙钛矿太阳能电池实现了26.7%的光电转换效率（认证效率为26.1%）。","scd":{"b":7.5,"i":4.0,"r":7.0,"d":8.0,"t":7.0},"kp":["薄膜相态[环境气相沉积FAPbI3钙钛矿]: 纯α相","[时空均匀结晶技术]: 采用“相锁定”策略建立动态演变的微环境，克服环境制备下的空间异质性降解"]},{"i":40912,"as":"强调深海采矿活动带来的环境与生态风险，呼吁国际社会及时建立和完善相关治理体系。","scd":null,"kp":[]},{"i":40913,"as":"人工智能语音神经假体技术能够帮助神经受损患者恢复日常交流与语言沟通能力。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":6.0},"kp":["[AI语音神经假体]: 可恢复神经损伤后的日常语言交流能力"]},{"i":40914,"as":"文章指出，尽管人工智能支持者认为该技术能让工作变得更快、更好、更便宜，从而将人类从繁重劳动中解放出来，但历史表明并非如此。正如第二次工业革命期间提高生产力的机器应用反而催生了强调严苛管理的科学管理体系，人工智能在科学出版等领域的实际应用效果可能并不符合其“高效廉价”的承诺。","scd":null,"kp":[]},{"i":40915,"as":"美国国家科学基金会（NSF）正在推行一项名为“X-Labs”的新倡议，旨在投入数十亿美元以开发具有经济回报的突破性技术。然而，学术界对此项资金分配计划持观望态度，并不确定他们是否能够广泛参与并从中受益。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":3.0,"t":7.0},"kp":[]},{"i":40916,"as":"","scd":null,"kp":[]},{"i":40917,"as":"斯堪的纳维亚雷达阵列（EISCAT_3D）将用于探测和绘制地球高层大气在太阳爆发扰动下的全新动态图像，以帮助科学家进一步揭示和探索极光的形成机制与相关未解之谜。","scd":{"b":6.0,"i":6.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[雷达阵列探测目标]: 极光之谜及上层大气受太阳风暴扰动的状态"]},{"i":40918,"as":"","scd":null,"kp":[]},{"i":40919,"as":"","scd":null,"kp":[]},{"i":40920,"as":"","scd":null,"kp":[]},{"i":40921,"as":"","scd":null,"kp":[]},{"i":40922,"as":"","scd":null,"kp":[]},{"i":40923,"as":"通用型人工智能智能体已被引入并在材料化学实验室中投入实际运行，协助科研人员进行材料化学领域的合成实验与相关研究工作。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":4.0,"t":6.0},"kp":["[材料化学实验室重编程]: 通用人工智能代理直接应用于实验室工作"]},{"i":40924,"as":"生成式人工智能技术被应用于Therabot系统中，能够实现基于循证医学的精准心理治疗服务的大规模扩展，从而为更多患者提供心理干预。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[生成式人工智能应用]: 实现循证心理治疗的规模化精准扩展"]},{"i":40925,"as":"亚马逊大豆禁令这一自愿的零森林砍伐协议正面临多重挑战。这些挑战不仅威胁到森林的生态保护，还可能对整个大豆产业部门造成负面影响与经济损失。","scd":{"b":2.0,"i":4.0,"r":5.0,"d":3.0,"t":4.0},"kp":[]},{"i":40926,"as":"研究发现，全球性入侵害虫橘小实蝇的雄性求偶行为是由交配过滤器的上下文依赖性转变引起的副产品。N-(3-甲基丁基)乙酰胺（MBA）是关键信号，在高雄性密度和雌性稀缺时会大量积累。当MBA积累量达到约1800纳克的阈值时，会拓宽雄性的交配过滤器，降低对潜在配偶的接受阈值，从而提高求偶动机并诱发过度活跃，促使雄性向已交配等次优雌性求偶。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":5.0,"t":5.0},"kp":[]},{"i":40927,"as":"","scd":null,"kp":[]},{"i":40928,"as":"","scd":null,"kp":[]},{"i":40929,"as":"受控委托实验表明，将任务委托给AI系统会带来人类委托人更倾向于要求利润最大化的不当行为，且AI比人类更容易服从的不道德风险。研究证实，相较于委托给人类，将任务委托给AI会产生更大的负面外部性，对第三方造成经济损害。测试表明，引入能够自掏腰包进行惩罚的第三方观察员（即举报人），可以有效遏制由人与AI委托授权所引发的不道德负面外部性。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":[]},{"i":40930,"as":"针对材料科学领域关于“弹性冰微纤维”的原始研究文章发布的勘误表，用于更正已发表的内容。","scd":{"b":2.0,"i":1.0,"r":3.0,"d":1.0,"t":5.0},"kp":[]},{"i":40931,"as":"针对个性化mRNA癌症新抗原疫苗定制周期长（通常超过三个月）的问题，研究引入了包含39个核苷酸的帽非依赖性翻译增强子（CITE）元件BBV来驱动RNA翻译。该技术克服了传统反义寡核苷酸（ASO）长度受限而无法编码蛋白质的缺点。通过结合BBV元件，无需依赖质粒发酵和体外转录（IVT）即可利用化学合成的RNA寡核苷酸编码蛋白质，从而实现个性化癌症疫苗的快速生产。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":6.0,"t":7.0},"kp":["个性化mRNA癌症疫苗生产周期[传统IVT工艺]: 超过三个月"]},{"i":40932,"as":"","scd":null,"kp":[]},{"i":40933,"as":"","scd":null,"kp":[]},{"i":40934,"as":"在孟加拉国砖业部门进行的一项随机对照试验表明，引入高效的生产方法虽然大幅提高了生产率，但在强制性劳动力市场中，并没有降低高度存在的劳动贩卖或童工比例。研究得出结论，在短期内，单靠生产率增长不足以改善强制性环境中的工作条件。","scd":{"b":2.0,"i":5.0,"r":7.0,"d":7.0,"t":5.0},"kp":["[孟加拉国砖业部门]: 强制性劳动力市场引入高效生产方法能显著提升生产率，但无法改善强制劳动或童工现象"]},{"i":40935,"as":"","scd":null,"kp":[]},{"i":40936,"as":"","scd":null,"kp":[]},{"i":40937,"as":"","scd":null,"kp":[]},{"i":40938,"as":"","scd":null,"kp":[]},{"i":40939,"as":"","scd":null,"kp":[]},{"i":40940,"as":"","scd":null,"kp":[]},{"i":40941,"as":"","scd":null,"kp":[]},{"i":40942,"as":"","scd":null,"kp":[]},{"i":40943,"as":"","scd":null,"kp":[]},{"i":40944,"as":"","scd":null,"kp":[]},{"i":40945,"as":"","scd":null,"kp":[]},{"i":40946,"as":"","scd":null,"kp":[]},{"i":40947,"as":"","scd":null,"kp":[]},{"i":40948,"as":"","scd":null,"kp":[]},{"i":40949,"as":"","scd":null,"kp":[]},{"i":40950,"as":"","scd":null,"kp":[]},{"i":40951,"as":"在钨环境稳态托卡马克(WEST)的L mode等离子体进行的X点辐射器(XPR)实验表明，X点上方可以维持稳定的辐射环约70秒，其时间尺度不受内在等离子体物理学的限制。这证明了基于X点涡旋驱动的辐射偏滤器动力学的稳定性和兼容性。","scd":{"b":7.0,"i":5.0,"r":6.0,"d":6.0,"t":8.0},"kp":["X点涡驱动辐射偏滤器稳定性[WEST托卡马克L-mode等离子体]: 在X点上方可维持稳定辐射环约70秒","[偏滤器维持时间限制因素]: 不受内在等离子体物理学特性的限制"]},{"i":40952,"as":"通过微波测量研究了II型超导薄膜中，当磁场从上方逼近临界磁场Hc2时正常相中新兴阿布里科索夫晶格的特征。这一发现证实了在Hc2上方存在超导涨落引发的阿布里科索夫晶格。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":8.0},"kp":["阿布里科索夫晶格动力学特征[第二类超导薄膜正常相]: 磁场从上方逼近上临界磁场Hc2时涌现微波特征"]},{"i":40953,"as":"研究了如二氧化铪(HfO2)等萤石氧化物的丰富可调相行为。发现掺杂可以有效诱导HfO2发生多晶转变。该机制为设计同时具备结构稳定性和高介电常数的非晶HfO2基高k材料提供了关键解决方案。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":8.0},"kp":["晶相行为[萤石氧化物(如HfO2)]: 表现出丰富且可调控的相变特性","[非晶高k材料设计]: 通过掺杂诱导多晶转变实现下一代电子器件所需的结构与性能要求"]},{"i":40954,"as":"单层二硒化钨（WSe₂）的激子谷相干通常由线偏振光诱导产生，而圆偏振光无法诱导。研究人员基于五能级模型开发了一个统一的微观开放量子系统框架，深入分析了不同偏振光对激子谷相干的影响，阐明了其中的微观物理机制。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":8.0},"kp":["激子能谷相干性[圆偏振光外部相干驱动]: 无法诱导产生","激子能谷相干性[线偏振光外部相干驱动]: 可诱导产生","理论框架[五能级模型开放量子系统]: 统一的、有微观基础的"]},{"i":40955,"as":"核磁共振测量技术证实了范德华反铁磁体三硫化镍磷（NiPS₃）中存在张-赖斯三重态基态。该成果为研究二维范德华磁性材料的电子结构和自旋相互作用提供了微观证据。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":8.0},"kp":["基态特性[范德华反铁磁体NiPS3]: Zhang-Rice三重态"]},{"i":40956,"as":"","scd":null,"kp":[]},{"i":40957,"as":"","scd":null,"kp":[]},{"i":40958,"as":"","scd":null,"kp":[]},{"i":40959,"as":"由环境记忆效应引发的非马尔可夫噪声是量子计算中最具挑战性的噪声源。研究基于量子控制理论提出并实验演示了一种无需校准的非马尔可夫噪声抑制方案，有效解决了量子计算中复杂噪声的抑制难题。","scd":{"b":6.5,"i":3.5,"r":6.0,"d":6.0,"t":8.0},"kp":["噪声抑制方案[非马尔可夫量子噪声]: 免校准且经实验演示"]},{"i":40960,"as":"","scd":null,"kp":[]},{"i":40961,"as":"","scd":null,"kp":[]},{"i":40962,"as":"","scd":null,"kp":[]},{"i":40963,"as":"","scd":null,"kp":[]},{"i":40964,"as":"利用高阶量子干涉技术在半导体中创建了“电子灯塔”，实现了对高度定向二维光电流光束的光学引导与控制。该研究展示了一种通过量子干涉产生定向光电流的新机制。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":8.0},"kp":["定向光电流控制[半导体二维光束]: 利用高阶量子干涉产生并光学操控的“电子灯塔”"]},{"i":40965,"as":"","scd":null,"kp":[]},{"i":40966,"as":"","scd":null,"kp":[]},{"i":40967,"as":"","scd":null,"kp":[]},{"i":40968,"as":"","scd":null,"kp":[]},{"i":40969,"as":"将地基引力波探测器的灵敏度扩展至低至5赫兹的长期难题受限于地面运动和惯性传感噪声。研究展示了与超高真空兼容的惯性隔离和位置传感技术，通过主动隔离平台实现了极低频段的低噪声检测。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":6.0,"t":8.0},"kp":["探测灵敏度[地基引力波探测器]: 扩展至5 Hz","限制因素[低于20Hz的地基引力波探测]: 地面运动和惯性传感噪声","核心技术[超高真空兼容惯性隔离]: 超高真空兼容的惯性隔离与位置传感技术"]},{"i":40970,"as":"研究发现，调谐至光学声子频率的中红外激光脉冲可以在磁性电介质中诱导磁化强度切换。在Epsilon近零区域，晶格激发产生的加热和非热应变共同作用，实现了光致磁化切换。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":8.0},"kp":["磁化强度切换[Epsilon近零区域]: 光致切换","诱导条件[磁性电介质的磁化切换]: 调谐至光学声子频率的中红外激光脉冲"]},{"i":40971,"as":"嵌入氧化铝纳米片的RuOx团簇催化剂在450°C的极低温度下实现了全氟化碳（CF₄）的完全水解，打破了现有催化剂的低温活性纪录。其优异性能归因于RuOx团簇与氧化铝之间的强电子相互作用，协同增强了C-F键的活化与质子供应。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["完全分解温度[CF4催化水解]: 450 ℃","催化剂[全氟烷基物质水解]: 嵌入介孔Al2O3纳米片的RuOx团簇"]},{"i":40972,"as":"开发了一种基于芳香族二酸酐交联的聚（l-赖氨酸）（PLL）氧化还原活性多肽平台，作为可持续钠离子电池正极材料。该“核心尺寸调制”策略同时调节了π共轭和孔隙率，平衡了电子离域、离子传输和结构稳定性，兼顾了高电化学性能与可降解性。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":7.0},"kp":["阴极材料[可持续钠离子电池]: 氧化还原活性聚（l-赖氨酸）(交联PLL支架)","技术挑战[可降解电化学储能体系]: 电子离域、离子传输与结构稳定性间的内在权衡"]},{"i":40973,"as":"在微波光机械腔内观测了超导鼓腔谐振器上的强非线性力，该力与量子涨落产生的卡西米尔力相符。该研究通过非线性动力学测量，成功分离并验证了低频电磁场对超导材料间卡西米尔力的具体贡献。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":4.0,"t":7.0},"kp":["非线性力[超导材料之间的近距离作用]: 兼容卡西米尔力的强非线性吸引力"]},{"i":40974,"as":"研究人员开发出一种具有凹面和金属间相特征的凹四面体Pt3In催化剂，用于质子交换膜燃料电池的阴极氧还原反应。该催化剂通过选择性湿化学刻蚀和铟辅助保形退火制备。在酸性介质中，其质量比活性达2.49 A mgPt-1，且在30000次循环后仍能保持97.8%的活性。在含磷酸盐电解质中，其质量比活性达到0.3 A mgPt-1。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["催化剂[质子交换膜燃料电池阴极氧还原]: 金属间化合物凹四面体Pt3In (i-ct-Pt3In)","合成工艺[集成凹面与金属间相结构]: 连续的Pt(111)选择性湿化学刻蚀法"]},{"i":40975,"as":"GA2AD是一个用于自动驾驶的通用自适应对抗训练框架。该框架将目标自动驾驶车辆视为黑盒，通过训练背景车辆模型生成切入、急刹车和超速等可控且具有挑战性的对抗性驾驶场景。该系统利用混合风险场评估周围车辆的交互风险，并通过激活函数和自适应切换模块决定对抗行为的实施与训练交替。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":7.0},"kp":["训练模型[自动驾驶自适应对抗训练]: 背景车辆模型","目标自动驾驶车辆模型[对抗训练]: 黑盒处理"]},{"i":40976,"as":"受视觉信号中波长选择性反馈启发，研究人员开发出一种合成聚合物纳米反应器系统，能够产生正交的、波长依赖性的正负反馈回路。该纳米反应器利用负载广谱DASA的聚合物囊泡封装酯酶，实现光门控渗透率切换。在光照下，系统以特定波长程序化水解乙酸乙酯产生乙酸，例如在590纳米黄光下通过光谱掩蔽效应介导正反馈。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["光门控聚合物纳米反应器[DASA功能化聚合物囊泡]: 具有正交、波长依赖性的正反馈与负反馈回路","功能化基团[广谱光响应]: 基于吡唑酮的给体-受体斯坦豪斯加合物(DASA)"]},{"i":40977,"as":"研究人员利用人工智能技术设计了自然界中不存在的全新功能性CRISPR酶。这种由AI设计的“分子剪刀”有效增强了CRISPR系统的基因编辑能力。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":4.0,"t":6.0},"kp":["CRISPR酶[AI辅助设计]: 具备自然界中不存在的全新功能"]},{"i":40978,"as":"","scd":null,"kp":[]},{"i":40979,"as":"气候变化重塑了风光等可再生能源的供应和电力需求，加剧了深度脱碳电网的资源充足性风险。基于12公里气候预测和县级电力系统优化模型的研究表明，到本世纪中叶，由于制冷需求上升与可再生能源发电量下降相叠加，气候变化导致资源不足的频率最高可增加至五倍。研究强调，微尺度的基础设施选址选择对缓解长期电力供应不足风险具有关键影响。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["气候变化[风能与太阳能系统]: 以区域特定的协同方式同时重塑可再生能源供应与电力需求","资源充足性风险[脱碳电网长期运行]: 由气象条件与系统设计的相互作用以及可再生能源发电的长期短缺驱动"]},{"i":40980,"as":"堆压力显著影响锂离子电池的退化机制，但其最优值此前尚不明确。近期，研究人员利用高精度堆压力控制与膨胀测量系统，发现了一个最佳压力窗口。该压力窗口能有效抑制关键的退化途径，使电池寿命延长一倍。这一突破通过力学手段成功建立了化学稳定性，为高性能电池的设计与优化提供了重要指导。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["电池寿命[抑制关键降解路径的最佳堆叠压力]: 翻倍","堆叠压力[锂离子电池高精度测控]: 存在可抑制降解路径的最佳压力窗口"]},{"i":40981,"as":"为解决氯化物固态电解质与富镍层状氧化物（如NCM811）在高压全固态电池中界面稳定性差的问题，研究人员通过在NCM811颗粒表面构建共形AlF3纳米壳层进行表面修饰。该结构设计有效提升了界面稳定性，抑制了高压运行条件下的持续性能衰减，从而获得更加稳定的富镍阴极性能。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["阴极材料[高压全固态电池]: 共形AlF3纳米壳包覆的富镍层状氧化物(NCM811)","固体电解质[全固态电池阴极]: 具有高离子传导率和良好抗氧化稳定性的氯化物基固态电解质"]},{"i":40982,"as":"研究人员设计了一种由CuS和钴卟啉组成的有机-无机异质结，实现在红外光下高效将二氧化碳还原为甲烷。该异质结具有长寿命的电荷分离状态，在红外光照射下，甲烷生成速率高达178.02 µmol g⁻¹ h⁻¹，且甲烷选择性达到96.5%。飞秒瞬态吸收光谱证实了异质结中强界面相互作用促进了载流子动力学。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["CH4生成速率[CuS-钴卟啉异质结红外光催化CO2还原]: 178.02 µmol g⁻¹","有机-无机异质结[红外光催化CO2还原]: HKUST-1衍生的CuS与钴卟啉(CoTPPS)","电荷分离态[CuS-钴卟啉异质结]: 长寿命"]},{"i":40983,"as":"针对锂-二氧化碳电池中硫尖晶石催化剂易发生氧化重构并影响性能的问题，研究人员通过温和氧化策略实现了NiCo2S4在电池运行过程中的受限重构。该机制揭示了重构后催化剂的氧化态对电池性能起决定性作用，受限重构策略成功提升了催化剂的活性和耐久性，实现了更稳定的锂-二氧化碳电池性能。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["催化剂活性与稳定性[锂-二氧化碳电池]: 取决于氧化重构后的氧化态","硫尖晶石催化剂[锂-二氧化碳电池]: 发生受限的氧化重构"]},{"i":40984,"as":"针对肩袖修复中腱骨界面同步再生的挑战，研究人员开发了一种可生物降解的自增强压电支架。该支架集成了压电材料的原位电刺激优势、电纺纤维的拓扑导向以及生物梯度结构，能够精准模拟天然腱骨界面的机械梯度和生化微环境，有效诱导干细胞的空间特异性分化，实现肌腱、纤维软骨和骨组织的功能性同步再生。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["压电支架[肩袖修复]: 可生物降解且自增强","组织再生[压电支架干预]: 实现肌腱、纤维软骨和骨组织的同步再生"]},{"i":40985,"as":"研究人员开发了一种自动化暗场电子断层扫描技术，能够以亚埃级精度对原子级薄层材料进行三维定量结构分析。通过将该技术应用于扭曲双层WSe2，精确观察到了由扭曲角度决定的结构弛豫现象，包括AB/BA堆叠域的形成。该技术直观揭示了光致和热致效应下扭曲双层系统的大层间解耦现象及非常规层间耦合机制。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["原子结构观测[扭曲双层WSe2]: 自动化暗场电子断层扫描技术","层间耦合[扭曲双层WSe2]: 呈现光致与热致的大层解耦现象"]},{"i":40986,"as":"电活性材料（如导电聚合物和压电纳米结构）能够模拟组织的天然电生理微环境，通过直接调节细胞器膜电位和离子动力学等亚细胞尺度的电信号，突破传统生化方法缺乏时空精度的限制，实现对干细胞命运的控制。这标志着再生医学和生物材料科学在利用局部电刺激调节细胞命运方面的新范式。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["电活性材料[细胞微环境调控]: 模拟组织原生电学微环境并直接调控亚细胞电信号（如细胞器膜电位和离子动力学）","材料体系[电活性材料类别]: 导电聚合物和压电纳米结构"]},{"i":40987,"as":"研究人员提出了一种基于离子的纳米流体记忆电阻器，工作于水溶液中，可构建密集连接的离子神经网络。该纳米流体记忆电阻器利用离子作为信息载体，具备可调的离子记忆和多种突触可塑性，这些特性能够通过电信号、光信号或光电组合信号进行调节。该技术为摒弃传统固态半导体电子载体的新型神经形态计算和离子计算提供了重要途径。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["信息载体[神经形态计算]: 以离子作为信息载体的纳米流体忆阻器","人工神经网络[架构特性]: 具有稳健连接和动态可塑性的离子基纳米流体架构"]},{"i":40988,"as":"研究人员基于包含光驱动分子马达和染料分子的液晶聚合物网络，开发出一种光响应软材料。该系统利用分子马达解耦光化学和光热效应，能够对特定波长的光产生选择性响应，实现跳跃、旋转和攀爬等高可编程性的复杂运动。紫外光触发的分子马达快速响应赋予了该软材料高时空精度的按需变形能力，适用于复杂环境下的下一代软体机器人。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["软材料致动[光化学与光热效应解耦]: 利用分子马达解耦光化学和光热效应，实现快速、智能、逼真的运动","材料体系[光响应智能软材料]: 液晶聚合物网络"]},{"i":40989,"as":"在全固态锂硫电池中，催化加速多硫化物转化时会不可避免地引发严重的硫化物固态电解质寄生分解，阻碍高倍率性能。为解耦高效硫转化与界面降解，研究人员设计了一种空间选择性催化剂架构。通过精确控制催化剂的尺寸，成功抑制了重叠电位下的电解质分解，打破了硫催化与电解质分解之间的尺寸依赖性权衡，实现了室温超高倍率充放电。","scd":{"b":9.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["电化学性能[全固态锂硫电池限制]: 受限于迟缓的固态硫氧化还原动力学，功率能力受到根本限制","催化负面效应[重叠电位下]: 催化加速不可避免地引发严重的硫化物固态电解质寄生分解"]},{"i":40990,"as":"研究人员开发出一种由Zn(II) Salphen配合物和聚N-异丙烯酰胺（PNIPAM）形成的水性超分子金属纤维。该纤维在稀释水溶液中自组装形成纳米纤维，并能对多种刺激产生响应，可逆地自组装成微米级超结构。这种分级结构策略增强了超分子组装体在水环境中的稳定性，实现了程序化的水凝胶化行为。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["超分子聚合[水相合成挑战]: 非共价相互作用极易破坏水中的超分子聚合","超分子金属纤维[合成体系]: 由Zn(II) Salphen络合物与聚合物功能化形成的水相超分子金属纤维"]},{"i":40991,"as":"研究人员开发出一种双功能PbS胶体量子点二极管，首次在单一短波红外器件中实现了纳秒级快速光电探测和发光发射。通过采用具有高电荷载流子迁移率的超薄活性层和紧凑几何结构，该器件在光电二极管模式下创下了2纳秒的响应时间纪录，并在发光模式下实现了11.7纳秒的上升时间，大幅减小了器件体积并降低了双向光通信成本。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["器件响应时间[短波红外检测与发射]: 纳秒级响应速度","器件功能[胶体量子点二极管]: 单一二极管兼具光探测和光发射双功能以缩小器件尺寸并实现双向通信"]},{"i":40992,"as":"受龟壳生物结构启发，研究人员设计出一种多功能晶格超材料。该材料通过拓扑驱动的混合耦合机制，在单一分级框架内协调机械能量吸收、声学衰减和对流热传输。通过集成拱形板-支柱几何结构与微孔隙，该超结构实现了55.7 kJ/kg的高比压缩能量吸收，并同时具备优异的宽带声学衰减和热管理功能。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["超材料结构[受龟壳启发的晶格设计]: 拱形板-支柱几何结构","超材料特性[多物理场能量调控]: 在单一层级框架内通过拓扑驱动混合耦合，实现机械、声学和热学的多功能同步调控"]},{"i":40993,"as":"研究人员提出了一种用于预测TCV托卡马克动力学平衡的预测工作流。该流程将预测优先的RAPTOR输运模拟与FBT逆平衡计算相耦合。RAPTOR利用脉冲调度信息、限制因子和线平均密度进行快速预发射模拟，生成的温度和旋转剖面随后输入至FBT自由边界求解器进行平衡计算，实现了两种代码在多种等离子体形状和场景下的收敛。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["等离子体建模[托卡马克动力学平衡预测]: 耦合RAPTOR输运模拟与FBT逆平衡计算的新型动力学平衡预测工作流","模拟工具特性[RAPTOR输运代码]: 1.5维输运代码，广泛用于等离子体放电优化和实时建模"]},{"i":40994,"as":"在LATE装置中，研究了通过底部窗口注入电子伯恩斯坦波以抑制捕获电子，从而实现过密球形托卡马克等离子体的非感应启动。实验结果表明，与中平面外侧注入相比，底部注入有效抑制了最后闭合磁通面（LCFS）外捕获电子的形成，改善了对载流穿越电子和体电子的耦合。软X射线分布证实底部注入下等离子体核心电子温度更高，有利于核心等离子体加热。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["微波注入方式[抑制捕获电子形成]: 底部端口注入（相比中外侧注入）能有效抑制捕获电子的发展","等离子体控制[电子伯恩斯坦波加热]: 利用电子伯恩斯坦波加热实现过密球形托卡马克等离子体的非感应启动和形成","耦合改善[载流通行电子]: 改善了向载流通行电子的耦合效果以驱动后期电流"]},{"i":40995,"as":"在ASDEX Upgrade和DIII-D托卡马克中，研究发现外偏滤器腿脱离会导致高场侧刮落层电子密度和中性压力降低。在离子漂移指向X点的有利构型下，多重诊断观测到了这一现象，且未使用杂质注入。偏滤器外腿脱离与高场侧反射测量的内中面电子密度下降相关，内偏滤器靶标处的密度和中性压力也随之降低，此效应在L模和H模中均存在。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["等离子体行为[外偏滤器腿脱离影响]: 导致高场侧刮落层（HFS SOL）的电子密度和中性粒子压力降低","实验条件[托卡马克脱离状态]: 在多诊断观测下且无杂质注入的情况下实现脱离","放电构型[离子漂移方向]: 离子漂移指向X点的有利构型"]},{"i":40996,"as":"在仿星器TJ-II中，向中性束注入加热阶段进行颗粒注射成功诱发了增强约束阶段。与束、气体注入或壁循环供能相比，其运行范围显著扩大，性能提升约1.5倍。此阶段特征为密度梯度变陡、离子温度升高、储存能与粒子约束时间创纪录以及湍流减少。最新数据集证实，与经验仿星器定标律相比，颗粒注射显著延长了能量约束时间。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["性能提升因子[颗粒注射对比中性束/气体注入]: 约1.5倍","等离子体约束阶段[颗粒注射引起]: 密度梯度变陡、离子温度升高、存储能量创纪录"]},{"i":40997,"as":"","scd":null,"kp":[]},{"i":40998,"as":"","scd":null,"kp":[]},{"i":40999,"as":"为克服电催化水分解中活性、稳定性和传质效率之间的权衡，研究采用多尺度超材料催化剂设计策略。通过将拓扑工程的三周期极小表面（TPMS）Zr基金属玻璃支架与脉冲电沉积衍生的NiMo纳米玻璃异质结构相结合，构建了NiMo@Zr多尺度超材料催化剂。该设计耦合了工程化的传质路径与纳米玻璃界面调控的催化活性，实现了整体催化剂性能的协同优化。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["催化剂[水分解]: NiMo纳米玻璃催化剂","超材料设计[催化剂多尺度结构]: 拓扑工程金属玻璃耦合策略"]},{"i":41000,"as":"","scd":null,"kp":[]},{"i":41001,"as":"","scd":null,"kp":[]},{"i":41002,"as":"","scd":null,"kp":[]},{"i":41003,"as":"研究利用飞秒反应显微镜实时监测选定尺寸的水合氢离子簇(H2O)n-1H+的超快形成过程。观察到了时间尺度上的动力学收敛现象，二聚体（n=2）的形成时间约为259飞秒，而三聚体（n=3）骤降至约70飞秒。这表明水三聚体是启动质子传导的最小催化单元。第一性原理分子动力学模拟显示，这种加速并非由初始质子转移引起，而是消除了控制反应的能量势垒。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":["水合氢簇形成时间[n=2水二聚体]: ~259 fs","水合氢簇形成时间[n=3水三聚体]: ~70 fs"]},{"i":41004,"as":"研究开发了一种基于SnOx的无富勒烯电子传输层，可直接刮涂在钙钛矿薄膜上，无需使用C60或其他富勒烯衍生物中间层。使用1-己醇进行溶剂工程延长了湿膜寿命，改善了薄膜的平滑度与致密性；同时钇掺杂优化了界面能级并促进电子提取。该技术使小面积器件实现了19.15%的光电转换效率和1.06V的开路电压，降低了成本并简化了制备工艺。","scd":{"b":6.0,"i":5.0,"r":6.0,"d":8.0,"t":5.0},"kp":["电子传输层[无富勒烯倒置钙钛矿]: 刮涂SnOx","溶剂工程[SnOx电子传输层]: 1-己醇延长湿膜寿命并改善成膜"]},{"i":41005,"as":"","scd":null,"kp":[]},{"i":41006,"as":"","scd":null,"kp":[]},{"i":41007,"as":"","scd":null,"kp":[]},{"i":41008,"as":"","scd":null,"kp":[]},{"i":41009,"as":"","scd":null,"kp":[]},{"i":41010,"as":"研究首次尝试利用医学知识引导多模态大语言模型，用于食管胃十二指肠镜诊断和报告生成（EDR）。基于包含4461名参与者和203,838张内镜图像的大型多中心数据集，提出的MLLM-EDR方法在19种胃肠道疾病诊断中达到0.882的平均准确率，优于先进AI模型（0.720）和初级内镜医生（0.784）。此外，该方法生成的报告在完整性和真实性上表现优异。","scd":{"b":7.0,"i":6.0,"r":8.0,"d":9.0,"t":7.0},"kp":["数据集规模[多中心食管胃十二指肠镜检查]: 4461名参与者，203,838张图像","多模态大模型[内镜诊断报告]: 首次融合医学知识引导"]},{"i":41011,"as":"针对现有蛋白质语言模型在酶特性预测中的局限性，研究提出了一种基于Mamba-Transformer混合架构和分层预训练的酶特异性模型EnzGFM。在酶属性预测基准测试中，该模型不仅比传统Transformer模型加速2至5倍，还在动力学参数预测、酶-反应映射、EC号分类和突变效应评估中分别实现了16.67%、15.69%、13.19%和20.04%的相对性能提升。","scd":{"b":7.0,"i":5.0,"r":7.0,"d":6.0,"t":6.0},"kp":["模型架构[酶特异性蛋白质语言模型]: Mamba-Transformer混合架构","预训练策略[酶特异性蛋白质语言模型]: 层次化预训练以捕获酶特异性模式"]},{"i":41012,"as":"为解决水系锌离子电池中因不均匀锌剥离/电镀引起的枝晶生长问题，研究提出了一种基于纳米多孔CaSO4涂层的人工固体电解质界面策略。原位枝晶可视化与显微技术证实，该涂层具有卓越的抑制枝晶能力，通过均匀化界面电场实现了锌的均匀沉积。优化后的Zn@CaSO4对称电池在1 mA cm-2条件下稳定运行超过1700小时，显著延长了电池寿命。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["阳极涂层策略[水系锌离子电池]: 纳米多孔CaSO4人工SEI","涂层作用机制[锌金属沉积]: 均匀化界面电场以抑制枝晶"]},{"i":41013,"as":"为解决氧化物半导体本征空穴缺乏导致铁电极化翻转不完全的问题，研究开发了一种耗尽电荷增强方法。在铟镓氧化物（IGO）沟道的原子层沉积过程中进行原位Ar+等离子体处理（300 W，60秒）。等离子体诱导产生的电离氧空位作为耗尽电荷，成功克服了沟道限制。该方法无需层间结构，即可实现适用于神经形态应用的铁电场效应晶体管，并与低温CMOS工艺兼容。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["沟道材料[铁电场效应晶体管]: 氧化物半导体","改进策略[无层间铁电晶体管]: 氧化物通道耗尽电荷增强"]},{"i":41014,"as":"传统共价有机框架因难溶和加工性差限制了实际应用。研究提出一种分子设计策略，利用具有空间拥挤双层共轭苯环的非平面单体，构建了可溶性热触发溶解性COF（HTS-COF）。该结构显著增大层间距并削弱π-π堆叠相互作用，在保持结晶度和结构完整性的同时赋予其可逆的热触发溶解性。HTS-COF可通过溶液加工制成均匀的薄膜和气凝胶，在动态过滤中表现出快速的处理能力。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["分子设计策略[可溶性共价有机框架]: 非平面单体","结构特征[热触发溶解性COF (HTS-COF)]: 增大层间距并减弱π-π堆积"]},{"i":41015,"as":"","scd":null,"kp":[]},{"i":41016,"as":"研究分析了大肠杆菌中核心启动子元件（-35和-10）在启动子诞生和转录调控中的作用。体内转录和体外RNA聚合酶-启动子相互作用分析表明，-10元件是启动子从随机序列进化的必需条件；而-35元件虽广泛保守，但对启动子诞生非必需，它通过与转录激活因子和RNA聚合酶的协调相互作用，在基因调控中发挥更大影响。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["核心元件功能[大肠杆菌启动子转录调控]: -10元件在启动子诞生和RNA聚合酶相互作用中发挥独特关键作用"]},{"i":41017,"as":"研究跨度4000公里调查了农业毁林及随后的造林对土壤生物多样性及生态系统多功能性（EMF）的影响。结果表明，农业毁林使土壤多营养级生物多样性降低25%，EMF降低58%。随后的造林虽部分恢复了这两项指标，但仍未能完全恢复至原始水平。","scd":{"b":4.0,"i":3.0,"r":8.0,"d":9.0,"t":5.0},"kp":["研究跨度[森林砍伐与重新造林影响]: 4000公里南北样带","功能测量[生态系统多功能性]: 19项生态功能"]},{"i":41018,"as":"研究提出LocScale-2.0，一种上下文感知的冷冻电镜图优化框架，无需分子结构先验知识即可运行。该技术利用生物大分子电子散射的普遍预期增强局部细节和连通性，同时保留弱结构信息。研究还引入了LocScale-FEM，这是一种模拟上述优化的贝叶斯深度学习方法，能够生成特征增强的体素级冷冻电镜图。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[冷冻电镜图优化]: 采用无需先验了解分子结构或组成的LocScale-2.0上下文感知框架"]},{"i":41019,"as":"一家初创公司计划在地球轨道上部署包含50,000颗携带反射镜的卫星阵列，旨在探索巨型太空镜能否用于增强地球上的绿色能源。天文学家对此表示深切担忧，认为该卫星阵列将严重损害现有天文望远镜的正常观测能力。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":3.0,"t":7.0},"kp":["[太空镜卫星阵列]: 规模达50,000颗带反射镜的卫星"]},{"i":41020,"as":"","scd":null,"kp":[]},{"i":41021,"as":"","scd":null,"kp":[]},{"i":41022,"as":"","scd":null,"kp":[]},{"i":41023,"as":"研究提出将阻塞互连双层乳液（JIBEs）作为一类具有宏观可扩展性的类组织材料。每毫升该材料包含数十亿个由双层分离的水性隔室，能模拟生物组织的结构与特性。其自组装方法几分钟内即可生成分升规模的JIBEs，支持脂质和嵌段共聚物等多种两亲分子。该材料具备直接在水溶液中挤出3D打印的特性，并可通过纳米通道进行功能化。","scd":{"b":7.0,"i":3.0,"r":8.0,"d":8.0,"t":6.0},"kp":["[拥挤互连双层乳液(JIBEs)]: 每毫升包含数十亿个双层分离的水性隔室","自组装体积规模[JIBEs制备]: 高达分升级","自组装耗时[JIBEs制备]: 数分钟内","适用两亲性分子类型[JIBEs制备]: 脂质和嵌段共聚物"]},{"i":41024,"as":"","scd":null,"kp":[]},{"i":41025,"as":"为应对老年人肌肉力量下降导致的行动困难，研究开发了一款用于辅助坐立转换和行走的软性髋关节外骨骼套装。在10名老年人的试验中，该装备使1分钟内的坐立转换次数平均增加1.8次，行走代谢成本降低13.6%，且未改变自然运动学特征。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":5.0,"t":6.0},"kp":["可穿戴辅助技术[老年人日常活动辅助]: 软性髋部外骨骼套装(可同时协助坐到站转换和行走)"]},{"i":41026,"as":"","scd":null,"kp":[]},{"i":41027,"as":"","scd":null,"kp":[]},{"i":41028,"as":"研究开发了一个统一的计算框架，用于标准化设计和制造微米级纵横交错的DNA巨型结构。该框架利用进化算法优化把手序列的分配，最小化DNA组装板之间的寄生相互作用。结合扩展的把手库，该框架有效解决了数千个把手序列分配的复杂性及数百种独特板制造的物流负担问题。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[DNA巨型结构组装]: 采用交叉聚合技术将数百种独特的DNA折纸‘板条’组装成具有纳米级精度的微米级结构","[序列库分配]: 需从固定库中分配数千个手柄序列以编码目标结合架构"]},{"i":41029,"as":"研究通过弹性电阻率测量，在kagome金属CsCr3Sb5常压下已知的T*（约55K）相变之上，发现了一个额外的相变。在约64K时观察到没有发散向错敏感性的旋转对称性破缺，最合理的解释是电荷密度波序的出现。激光光电子发射显微镜等技术进一步揭示了该化合物中电荷与自旋行为的二分法特征。","scd":{"b":9.0,"i":1.0,"r":7.0,"d":7.0,"t":7.0},"kp":["相变温度[常压下CsCr3Sb5]: T* ≈ 55 K（仅发生单次转变）","关联与磁性基态特性[Cr基kagome化合物CsCr3Sb5]: 表现出比其V基类似物更强的关联和磁基态"]},{"i":41030,"as":"针对自相干相干（SHC）传输中偏振态快速波动破坏相干接收的问题，研究基于薄膜钽酸锂开发出超快自适应偏振控制器（APC）。通过光子芯片、有限边界梯度下降（FBGD）算法和低延迟实时控制系统的协同设计，将有限相位边界直接纳入控制策略，实现了无复位的连续偏振态跟踪。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["自适应偏振控制器(APC)[超快无复位集成偏振跟踪]: 基于薄膜钽酸锂并通过光子芯片等协同设计实现"]},{"i":41031,"as":"研究提出一种具有蜂窝状架构的四通道铜管穿透电极（TPE），用于高效电催化二氧化碳还原为甲烷。通过精确控制电极横截面厚度，该设计有效调节气体、电子和电解质的传输，稳定了三相界面，克服了甲烷电合成中多电子动力学和质量传输的限制。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[甲烷电合成反应器]: 四通道管状铜穿透电极"]},{"i":41032,"as":"研究在理论上证明了在强最近邻里德伯阻塞机制下，里德伯原子链的高能态中存在准孤子激发。这些局域波包在与量子多体疤痕相关的特定复苏初始态上定向传播并能携带能量。这些状态具有较长的相干时间，构成了一种非各态历经的量子动力学形式。","scd":{"b":9.0,"i":1.0,"r":7.0,"d":6.0,"t":7.0},"kp":["准孤子激发[里德堡原子链高能态]: 在强最近邻里德堡阻塞下方向性传播","系统特性[强相互作用多体系统]: 局域化波包克服热化破坏保持稳定"]},{"i":41033,"as":"针对中红外超表面存在的低Q共振、弱振幅对比及静态功能限制，研究开发了主动可调的单晶硅膜超表面。该平台结合了高Q共振、强振幅对比和晶圆级可制造性，在中红外波段实现了高达3000的创纪录Q因子，并支持两种动态调制方案。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[中红外光调制器]: 由动态可调的超高Q值硅膜超表面实现"]},{"i":41034,"as":"利用高分辨率激光角分辨光电子能谱仪对七层Bi2Sr2Ca6Cu7O18+δ进行研究，发现了包含多个空穴费米口袋的铜酸盐系统。这些费米面表现出明显的动量、温度和费米面依赖的性能隙。在存在强反铁磁有序的系统中，出现了临界温度约为75K的高温超导性，并在特定方向上观察到了大量的电子配对。","scd":{"b":9.0,"i":1.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[多孔铜酸盐系统]: 具有多个空穴费米袋的Bi2Sr2Ca6Cu7O18+δ (Bi2267)系统","[实验表征方法]: 高分辨率激光空间分辨角分辨光电子能谱"]},{"i":41035,"as":"针对溶液加工钙钛矿串联发光二极管中互连策略损耗大的问题，研究提出一种分层结构的互连层。该互连层集成近简并电荷产生结与晶态-非晶态氧化物复合材料，实现低势垒传输和耐溶剂堆叠。基于此技术制备的双结钙钛矿LED中，两个子单元高效串联运行，实现了42.6%的峰值外量子效率、690 W sr−1 m−2的最大辐射率以及低驱动电压。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["互连层[多结钙钛矿LED]: 结合近简并电荷产生结与晶态-非晶态氧化物复合材料的分层结构","[多结钙钛矿LED]: 降低互连损耗并实现低势垒电荷传输"]},{"i":41036,"as":"研究结合扫描隧道显微镜操控与尖端增强光致发光技术，以亚纳米分辨率可视化了人工环状锌酞菁结构中的离散激子态。通过控制分子间距离，研究映射了从弱耦合到强耦合状态下的激子演化过程，并发现了分子正交简并偶极子引发的跃迁偶极旋转现象。该现象促进了分子间的相干耦合。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["光学暗态探测[远场光学突破衍射极限与偶极选择定则]: 结合扫描隧道显微镜操控与尖端增强光致发光技术","空间分辨率[构建的环状锌酞菁架构中的离散激子态]: 亚纳米级"]},{"i":41037,"as":"受生物体中水在抗冲击中作用的启发，研究将结构受限的结合水网络作为质子富集聚合物支架中的动态交联剂。通过对其解离动力学进行编程，利用动力学冻结实现了冲击下急剧且可逆的软硬转变。基于聚硫辛酸的该体系实现了优异的能量耗散、自愈合和强粘附性能。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":6.0,"t":7.0},"kp":["交联剂[仿生抗冲聚合物]: 结构限制在富质子聚合物网络内的结合水","[抗冲聚合物设计]: 将通常作为增塑剂的水转化为具有速率敏感性的活性动态交联剂"]},{"i":41038,"as":"研究开发了一种基于亚砜催化剂的催化型Mitsunobu反应，用于烷醇C(sp3)-O键的立体专一性转化。该方法底物适用范围广，且仅生成水作为唯一副产物，克服了传统磷化学的环境缺陷。动力学研究、机理分析与密度泛函理论计算揭示了其结构-反应活性关系，建立了一种可持续且具有原子经济性的反应体系。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["催化剂[重铸Mitsunobu反应中的C(sp3)-O键活化]: 亚砜","[烷醇立体转化]: 摒弃传统磷化学缺陷并实现无磷替代催化"]},{"i":41039,"as":"针对反应机理中过渡态和产物生成效率低且难以控制的问题，研究提出了条件流匹配框架MolGEN。该框架利用确定性最优传输将高斯先验映射到化学分布。在过渡态生成中，MolGEN提升了几何构型和能垒预测精度，实现亚秒级采样；在产物生成中，在保持质量和电子平衡的同时达到了极具竞争力的top-k准确率。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["映射机制[MolGEN模型生成反应路径]: 基于确定性最优传输的条件流匹配框架","[反应路径生成]: 将高斯先验直接映射到化学产物，取代传统低效的随机扩散动力学"]},{"i":41040,"as":"为分离介电环境与结构重组的影响，研究了一种在不同溶剂极性下保持堆积几何形状的苝二酰亚胺H-聚集体。瞬态吸收实验表明，介电介质决定性地引发了电荷动力学机制的转变：在非极性环境中，反应动力学由高频振动模式介导的量子隧穿驱动。该研究揭示了溶剂极性独立调节电荷和激子动力学的机制。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[苝二酰亚胺超分子聚集体]: 结构坚固的H-聚集体，其堆积几何形状不受溶剂介电环境影响","[电荷与激子动力学]: 通过调节介电环境实现解耦与精准优化"]},{"i":41041,"as":"针对四角钨青铜（TTB）陶瓷储能性能受限的问题，研究提出了一种在极性活性B位进行微小多元素取代的极性熵调节策略。原子尺度表征表明，该策略精确调制了极性位移并削弱了极性纳米区之间的耦合，重塑了局部极化构型。基于此，成功验证了TTB陶瓷用于先进多层储能器件的可行性。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["调控策略[四方钨青铜多层电容器储能]: 极性活性B位点的微小多元素取代实现靶向极性熵调节","[四方钨青铜电容器]: 精确调制极性位移并减弱耦合以提升储能性能"]},{"i":41042,"as":"研究开发了一种无需三重态发射体、由ZnSe量子点和2,5-二苯基恶唑组成的可见光至紫外上转换系统，实现了24%的上转换量子产率，为量子点敏化上转换的最高值。瞬态光谱表明，三线态能量转移效率超过80%，而总体上转换量子产率主要受控于三线态-三线态湮灭效率。在30 mM的受体浓度下实现了最佳上转换效果。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":8.0,"t":7.0},"kp":["上转换量子产率[ZnSe量子点与2,5-二苯基恶唑无发射器体系]: 24%","浓度峰值参数[上转换量子产率]: 30 mM (2,5-二苯基恶唑)","三重态能量转移效率[ZnSe量子点敏化]: 超过80%"]},{"i":41043,"as":"","scd":null,"kp":[]},{"i":41044,"as":"","scd":null,"kp":[]},{"i":41045,"as":"研究提出一种通过活性墨水空间图案化编程气体发生曲线的产气驱动系统（GAS）打印策略。利用直写式3D打印技术，将高固相载量的柠檬酸和碳酸氢钠墨水打印在纤维素纸基材上，形成空间分离的稳定反应域。在水触发下，该系统能够精确控制气体产生的总量、起始时间、速率和持续时间，从而实现不受束缚的软体机器人驱动。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["驱动策略[无系留软体机器人]: 通过空间图案化活性墨水编码气体发生动力学的产气驱动系统(GAS)打印","[化学反应驱动]: 精确控制气体产生的总量、起始点、速率和持续时间"]},{"i":41046,"as":"","scd":null,"kp":[]},{"i":41047,"as":"研究发现，高结晶度的再生纤维素薄膜能够增强其固有的光致发光（PL）能力。通过光子转换机制，这种薄膜能有效将吸收的紫外波段光子转化为可见光发射，从而提升材料的太阳反射率，增强其被动日间辐射冷却（PDRC）性能。该研究基于天然纤维素大分子的独特结构，提升了再生纤维素材料的冷却效能。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["增强机制[再生纤维素材料被动日间辐射冷却(PDRC)]: 利用高结晶结构增强固有光致发光","[天然纤维素大分子与分层聚集结构]: 赋予材料具备潜力的被动日间辐射冷却性能"]},{"i":41048,"as":"研发出一种肉眼无法察觉且无触感的可穿戴传感器。这些传感器可作为电极附着在人脸上，用于测量脑电波及其他生物电信号，克服了传统传感器可见或带来的异物感问题。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[可穿戴传感器]: 不可见且无异物感，用于脑电波等生理信号测量"]},{"i":41049,"as":"为解决氧化亚铜（Cu2O）催化剂在电化学硝酸盐还原中的自还原和不稳定性问题，研究提出一种稀土镧（La）掺杂策略，构建了Cu2O-LayO异质界面。在Cu2O/La2O2(CO3)界面上，高配位Cu+活性位点与空间位阻共同作用，有效促进了电荷转移并稳定了催化位点，实现了硝酸盐向氨的高效电化学转化。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[电化学硝酸盐还原反应(eNO3-RR)]: 同步实现废水处理与可持续氨合成","催化剂[碱性海水]: 稀土掺杂构建Cu-O-M界面位点稳定Cu+位点的Cu2O催化剂"]},{"i":41050,"as":"研究结合固态核磁共振与计算化学，对Al(Salen)Cl配合物的溶液相立体动力学行为进行了三维结构分析。分析揭示，在分子间卤化物催化的重排作用下，溶液中R,R-(M)和R,R-(P)物种之间存在快速平衡。这一多学科交叉研究为不对称催化中具有代表性的M(Salen)配合物的结构功能模型提供了关键基础。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["[不对称催化]: M(Salen)配合物提供广泛且高选择性的催化作用","[五配位Al(Salen)催化剂]: 深入研究其溶液相的三维立体动力学以建立统一结构功能模型"]},{"i":41051,"as":"探讨基于钙钛矿材料的突触器件技术，致力于实现具备超低功耗特性的仿生边缘智能计算硬件。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":4.0,"t":4.0},"kp":["功耗特性[钙钛矿突触器件]: 超低功耗"]},{"i":41052,"as":"研究通过卤代苯乙胺添加剂工程改善铅锡钙钛矿太阳能电池性能，涉及其在光伏器件领域的应用。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":["添加剂工程[改善铅锡钙钛矿太阳能电池]: 卤代苯乙胺"]},{"i":41053,"as":"研究将稀土铈和过渡金属钌引入NiFe-MOF，实现了局域4f态与离域4d态的轨道互补。这种多中心电子相互作用（3d-4d-4f）改变了催化剂的动态演变，加速了NiFe-MOF向活性NiFeOOH物种的转化。软硬X射线吸收光谱证实了该氧桥联多中心轨道耦合机制，为析氧反应电催化提供了超越传统电荷转移的新型电子调控策略。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["催化剂[析氧反应(OER)]: 稀土Ce与过渡金属Ru掺杂改性的NiFe-MOFs(Ce,Ru-NiFe-MOFs)","[多金属掺杂策略]: 局域4f与离域4d轨道互补实现超越传统电荷转移的电子调控"]},{"i":41054,"as":"研究系统探讨了π-扩展的芳基偶氮低聚噻吩和低聚噻吩并苯在光致变色与电荷传输之间的耦合作用。实验和理论计算表明，π-扩展使得该材料在溶液中可通过可见光实现E→Z光致异构化，但也降低了热Z→E逆向转换的势垒。芳基氟化通过增强分子内S(n)···π相互作用，有效抵消了这一热不稳定性，兼顾了高效电荷传输与稳定的光开关功能。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["[光响应分子材料]: π-扩展芳基偶氮低聚噻吩和低聚噻吩并苯实现光致变色与电荷传输的有效耦合"]},{"i":41055,"as":"评估美国各州生物多样性保护规划，探讨其与大规模风能、太阳能可再生能源开发间的平衡与影响。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":4.0,"t":4.0},"kp":[]},{"i":41056,"as":"提出基于数据驱动与物理信息的控制框架，结合元认知算法优化住宅暖通空调系统运行效率。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":4.0,"t":4.0},"kp":["控制框架[住宅HVAC系统]: 结合元认知算法的数据驱动与物理信息级联控制"]},{"i":41057,"as":"开发基于知识蒸馏的预测框架，应用于质子交换膜燃料电池，实现其运行性能退化的在线预测。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":4.0,"t":4.0},"kp":["预测框架[质子交换膜燃料电池在线降解预测]: 知识蒸馏"]},{"i":41058,"as":"研究直接空气捕获系统的优化控制策略，在保障碳排放可验证性的约束下实现系统能效最大化。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[直接空气捕获系统优化]: 碳排放可验证性约束下实现系统能效最大化"]},{"i":41059,"as":"提出基于惩罚敏感区域的鲁棒优化方法，用于优化孤岛微电网中氢能集成的质子交换膜电解槽运行。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":4.0,"t":4.0},"kp":["优化方法[孤岛微电网氢能集成质子交换膜电解槽]: 基于惩罚敏感区域的鲁棒优化"]},{"i":41060,"as":"结合电池物理约束机制构建物理引导神经网络，用于精确估计锂离子电池的能量状态，涉及电池管理。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":4.0,"t":4.0},"kp":["算法机制[锂离子电池能量状态估计]: 结合电池物理约束机制的物理引导神经网络"]},{"i":41061,"as":"探讨数字双环能源管理技术在电气化住宅建筑中的应用，重点研究提升电网边缘灵活性的方法。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["能源管理技术[电气化住宅建筑电网边缘]: 数字双环管理提升灵活性"]},{"i":41062,"as":"研究基于物理信息的机器学习自适应预测控制技术，用于数据中心的节能混合冷却系统管理。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":"控制技术[数据中心混合冷却系统]: 基于物理信息的机器学习自适应预测控制"},{"i":41063,"as":"提出一种针对大型光伏电站的新型方法，主要涉及故障定位和缺陷量化评估技术。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[大型光伏电站]: 新型故障定位和缺陷量化评估方法"]},{"i":41064,"as":"提出多时间尺度运行模拟方法，研究在极端天气与频率安全约束下储能系统的多维支撑能力。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[极端天气与频率安全约束]: 储能多时间尺度运行模拟方法及多维支撑能力"]},{"i":41065,"as":"聚焦城市建筑脱碳路径，构建涵盖能源、碳排放与经济多维度的综合评估模型与方法。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[城市尺度建筑脱碳]: 涵盖能源、碳排放与经济多维度的综合评估模型与方法"]},{"i":41066,"as":"研究复合相变材料与热电耦合组件的系统集成，提出针对性的热管理调度与优化策略。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[复合相变材料-热电耦合组件]: 系统集成热管理调度与优化策略"]},{"i":41067,"as":"采用一步界面聚合法，将三元酰氯单体与磺化二胺单体在商业隔膜上聚合，形成致密且具有电荷选择性的磺化聚合物薄膜。该涂层有效抑制了锂硫电池中的多硫化物穿梭效应并提升了容量保持率，但会降低锂离子传导率从而影响倍率性能。通过掺入双官能团酰氯替代部分三元单体，降低了薄膜交联密度，成功在保持薄膜均匀性的同时改善了倍率性能。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[商业化隔膜改性]: 磺化聚合物薄膜的一步界面聚合集成","[锂硫电池穿梭效应]: 致密且具有电荷选择性的磺化薄膜涂层有效抑制多硫化物穿梭"]},{"i":41068,"as":"研究表明，对多环芳烃进行碱金属掺杂重塑了其势能表面，实现了在低温（低至250°C）下的高效逆向Stone-Wales重排。钾、铷和铯掺杂的系统表现出此逆向重排，而锂和钠掺杂则专一性地促进隐窝区域的环化脱氢反应。结合密度泛函理论和多种表征手段，分离并鉴定了关键阴离子中间体，揭示了还原作用解锁芳香体系新型重排的机制。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[多环芳烃逆Stone-Wales重排反应]: 碱金属掺杂重塑势能面实现高效逆向重排","反应温度[钾/铷/铯掺杂系统]: 低至 250 °C"]},{"i":41069,"as":"研究报道了一种带有单电子氧化四酰胺大环配体的铁(V)-氧络合物[FeV(O)(TAML•+)]，可通过形成O-O键有效将水氧化生成氧气。其前体络合物[FeIII(TAML)]-在光催化水氧化反应中表现出优异的催化效果。瞬态吸收测量揭示了光驱动反应的逐步路径：前体与DDQ首先通过μ-氧代二聚体中间体生成活性物种，进而参与后续的催化循环。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[水氧化反应]: [FeV(O)(TAML•+)]配合物实现O-O键形成并高效催化水氧化生成氧气","催化剂[光催化水氧化与电子转移]: [FeIII(TAML)]-配合物作为有效光催化剂前体"]},{"i":41070,"as":"研究探讨了碱性电解质中铜单晶电极表面结构对电化学硝酸盐还原选择性的影响。结果表明，Cu(100)和Cu(110)表面在产氨速率和选择性上表现相似，其中Cu(100)表面在最宽的施加电位范围内实现了大于95%的氨法拉第效率。相反，Cu(111)表面在反应中表现出与其他晶面显著不同的选择性特征。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[电化学硝酸盐还原]: 铜单晶Cu(100)、Cu(110)和Cu(111)电极的表面结构影响反应选择性"]},{"i":41071,"as":"针对锂离子电池阳极结构退化和界面动力学迟缓的难题，研究设计了多阳离子钒酸盐化合物LiCuFe2(VO4)3。该电极通过电化学晶格重组和自适应界面调节的耦合机制，在0.5 A g-1电流下循环1000次后，比容量保持高达1178 mAh g-1，并伴随容量持续提升现象。机理研究表明，金属铜纳米颗粒沉淀构建了电荷渗流网络，同时铁物种参与调控，共同提升了结构稳定性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":8.0,"t":6.0},"kp":["比容量[锂离子电池LiCuFe2(VO4)3阳极循环性能]: 1178 mAh g-1","[阳极材料演化]: 电化学晶格重组与自适应界面调制的耦合机制解决结构退化与界面动力学迟缓"]},{"i":41072,"as":"研究探讨了p型LASTT-10热电材料热不稳定性的微观起源。制备的块体样品在673 K下具有约1.05 ± 0.10的高热电优值(zT)。系统的热循环和等温退火实验表明，材料传输性质的不可逆变化源于富含碲的(Ag1-xSbx)1+yTe2二次相的微观结构演变。这一发现阐明了晶界和微观结构演化对热电材料长期高温稳定性的决定性影响。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["材料体系[p型LASTT热电化合物]: 纳米结构PbTe基化合物","具体成分[LASTT-10组成]: Ag0.9(Pb0.5Sn0.5)10Sb0.8Te12","合成工艺[LASTT-10]: 熔融、退火和火花等离子烧结"]},{"i":41073,"as":"液-液相分离（LLPS）是细胞内形成生物分子凝聚层无膜细胞器的普遍机制，在基因转录和信号传导等生理过程中发挥关键作用。受此启发，研究人员开发了由生物聚合物、合成大分子或小分子组成的人工合成凝聚层。通过外部刺激调节其相分离行为并定制结构，是开发具有智能响应功能的先进材料的核心策略。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["相分离过程[液-液相分离 (LLPS)]: 均相溶液分为溶质富集相和贫集相","相分离机制[生物分子凝聚体形成]: 无处不在的基础机制"]},{"i":41074,"as":"","scd":null,"kp":[]},{"i":41075,"as":"","scd":null,"kp":[]},{"i":41076,"as":"","scd":null,"kp":[]},{"i":41077,"as":"","scd":null,"kp":[]},{"i":41078,"as":"利用人多能干细胞衍生的肺类器官模型，研究证明了细胞外基质（ECM）的硬度能够主导肺上皮的区域特异性分化。ECM的逐步软化可生成具有近端至远端上皮组成及生理功能的气道类器官；而在肺泡分化过程中，增加的基质硬度不仅促进了肺泡II型（AT2）和I型（AT1）细胞的成熟，还驱动了AT2向AT1的细胞转化。RNA测序进一步揭示了ECM硬度对上皮命运的转录调控机制。","scd":{"b":7.5,"i":4.0,"r":6.0,"d":6.0,"t":7.0},"kp":["细胞外基质 (ECM)[人呼吸道上皮分化]: 硬度指导区域特异性分化","细胞模型[体外肺类器官]: 嵌入硬度可调水凝胶的hPSC衍生肺类器官"]},{"i":41079,"as":"","scd":null,"kp":[]},{"i":41080,"as":"","scd":null,"kp":[]},{"i":41081,"as":"","scd":null,"kp":[]},{"i":41082,"as":"","scd":null,"kp":[]},{"i":41083,"as":"研究拓展了非交替乙烯/一氧化碳共聚合成光降解聚酮（keto-PEs）的Ni(II)催化剂范围。多种中性Ni(II)络合物被证实可有效催化该反应，其中膦基亚胺酸Ni(II)催化剂的性能与现有先进催化剂相当，而N-杂环卡宾(NHC)苯酚盐Ni(II)催化剂对乙烯掺入表现出异常高的偏好性。密度泛函理论（DFT）计算进一步阐明了催化剂结构调控聚合产物分布的机制。","scd":{"b":8.5,"i":4.5,"r":7.0,"d":6.5,"t":7.0},"kp":["共聚反应[非交替乙烯/一氧化碳共聚]: 长久以来的突破性挑战","产物特性[链内酮官能团聚乙烯]: 具备光降解性","催化剂[非交替共聚]: 基于中性N基序的各类催化剂"]},{"i":41084,"as":"","scd":null,"kp":[]},{"i":41085,"as":"","scd":null,"kp":[]},{"i":41086,"as":"研究开发了一种在环境条件下运行的级联电光化学系统，用于高效转化烷烃。该系统利用溴化物作为介体，成功将丙烷转化为高价值的异丙醇。相较于传统依赖高温高压的能源密集型工业合成工艺，该技术提供了一条低碳、可持续的化学制造新路径。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["合成工艺[丙烷转化为异丙醇]: 环境条件下的级联电光化学系统","反应介质[级联电光化学系统]: 采用溴化物介导剂"]},{"i":41087,"as":"随着汽车行业电气化进程加速，废旧电池的回收能力亟需大幅提升。回收商面临着满足法规要求、建立高效逆向物流以及处理日益复杂的电池设计、形态和化学成分等重大挑战。研究全面评估了现有回收技术与当前及下一代电池的兼容性，指出当前已建立的预处理工艺和直接回收技术在应对复杂多样的电池废料时仍面临显著的技术与经济双重挑战。","scd":{"b":3.0,"i":5.0,"r":5.0,"d":4.0,"t":4.0},"kp":["产业规模[车用电池回收]: 2026年起需大幅扩大回收产能","回收挑战[报废与制造废料]: 回收物流、系统设计及电池形态日益复杂化"]},{"i":41088,"as":"研究提出了一种通过控制前体分化实现钯催化发散性羰基化的新策略，解决了单一底物存在多种竞争反应途径的选择性控制难题。通过条件控制调节底物的演化路径，可以将同一种环丁烯醇底物在催化介入前选择性引导至两种完全不同的反应前体，进而合成出两种结构不同的羰基化产物。这为合成化学中的反应路径精确调控提供了全新范式。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["反应控制策略[钯催化环丁烯醇羰基化]: 通过控制前体分化实现分歧性"]},{"i":41089,"as":"针对体内生理环境复杂导致药物释放效率下降的挑战，研究人员开发了一种基于铪（Hf）的纳米级金属有机层（nMOL）平台。该平台利用独特的“表面限制效应”，将前药共价束缚在Hf-nMOLs表面构建二维纳米反应器。这种设计有效克服了由放疗介导的药物释放中活性中间体在体内被快速猝灭的问题，成功实现了受生理环境影响极小的生物正交药物释放。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":7.0},"kp":["药物释放平台[肿瘤微环境]: 表面限制效应实现生物正交药物释放"]},{"i":41090,"as":"研究团队首次报道了吡咯稠合的萘二酰亚胺（NDPI）框架，并将其作为高性能有机半导体的构建模块。单晶X射线衍射表明，NDPI具有高平面性π核心，π-π堆积距离为3.33 Å，并存在强分子间氢键。基于此合成的给体-受体聚合物光学带隙为1.32-1.39 eV，在有机场效应晶体管（OFET）器件中展现出0.10至0.59 cm² V⁻¹ s⁻¹的迁移率，且电荷传输行为可调。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":8.0,"t":7.0},"kp":["π-π堆积距离[二吡咯稠合萘二酰亚胺单晶]: 3.33 Å","分子间氢键[二吡咯稠合萘二酰亚胺单晶]: N-H···O氢键 (2.07 Å)"]},{"i":41091,"as":"研究将含有三组氨酸面三联体的非血红素Fe酶EgtB改造用于催化C(sp³)-H氟化反应。通过定向进化，获得了对映体偏好相反的氟转移酶EgtBCHF1和EgtBCHF2，总活性显著提高。与含双组氨酸单羧酸面三联体的ACCOCHF不同，进化的EgtBCHF表现出羟基化活性。同位素标记证实羟基源于水。计算研究表明初级配位球影响了阴离子反弹的选择性。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":7.0,"t":7.0},"kp":["催化活性[定向进化EgtB氟转移酶]: 总活性提高达28倍","手性选择性[非血红素Fe酶]: 产生具有相反对映体偏好的新型氟转移酶"]},{"i":41092,"as":"研究开发了一类名为“Truly”降解剂的新型双功能分子，结合了蛋白酶体受体Rpn13配体和脑啡肽（CRBN）配体，可同时启动泛素非依赖性和泛素依赖的蛋白质降解途径。结构导向设计发现，最优连接体长度对底物处理至关重要，其中PEG4衍生物（Truly-4）能在多种细胞中诱导Rpn13和CRBN的强效耗竭，突破了现有靶向蛋白降解技术的局限。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":4.0,"t":7.0},"kp":["双功能降解剂机制[靶向蛋白降解]: 同时结合Rpn13受体和CRBN配体","ByeTACs降解机制[蛋白酶体降解]: 直接招募蛋白且不依赖E3泛素连接酶"]},{"i":41093,"as":"为解决早期微小肿瘤检测难题，研究开发了一种肿瘤微环境响应型纳米探针PR-KAd@CD-AuNC。该探针结合体内近红外二区（NIR-II）荧光成像和体外比色尿液分析进行交叉验证检测。它由可清除的信号输出段、肿瘤靶向与尺寸控制组件（8臂PEG与靶向肽的聚合物）以及MMP2可切割连接体组成，能够引导探针在肿瘤部位选择性积累并释放信号。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["纳米探针[肿瘤微环境响应]: 肾脏清除型信号输出片段（环糊精功能化金）","检测模式[早期癌症筛查]: 体内NIR-II荧光成像与体外比色法尿液分析交叉验证"]},{"i":41094,"as":"为研究Pt(II)-席夫碱配合物的系间窜越电子自旋选择性，研究在其结构中引入苝作为三线态能量受体。该方法利用从金属到配体的电荷转移（3MLCT）态到苝的超快分子内三重态-三重态能量转移（TTET）过程中的自旋角动量守恒，结合偏振转移，成功探测了原本由于零场分裂较大（约25 cm⁻¹）而无法通过时间分辨电子顺磁共振直接观察的3MLCT三重态的电子自旋极化。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":7.0},"kp":["零场分裂参数[Pt(II)-Schiff碱配合物]: ~25 cm^-1"]},{"i":41095,"as":"研究将非交替烃蔻的2,6-位进行大环张力拉伸，成功合成了全蔻类似物[6]环对蔻烯（[6]CPA）。该大环由蔻亚基交替的2,2'和6,6'连接构成，具有对称结构。通过单晶X射线衍射明确了其结构。将非交替烃系统置于张力与大环共轭环境下，改变了其原有的(反)芳香性、光学行为和氧化还原性质，产生出具有全新物理特性的材料。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":7.0},"kp":["光学及氧化还原特性[非交替环共轭烃(Azulene/薁)]: 具有反Kasha荧光规则及高强度属性"]},{"i":41096,"as":"针对高温下反应性金属-载体相互作用（RMSI）导致界面重组和合金形成难以控制的问题，研究在NiIn/CeO₂催化剂中实现了对RMSI的精确调控。在氢气还原条件下，利用原位环境电子显微镜直接观察到了CeO₂载体上InOₓ的高迁移率，并对InOₓ进行了定量调节。这种受控的RMSI策略显著提升了CO₂加氢合成甲醇的催化性能。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["金属-载体相互作用调控[NiIn/CeO2催化剂]: 利用高迁移率的InOx实现对界面重构和合金形成的精确控制"]},{"i":41097,"as":"针对工业费托合成中钴催化剂表面会因碳诱导发生粗糙化以维持活性的传统观点，研究在含有牺牲性碳化物层的Co(0001)表面进行了测试。原位扫描隧道显微镜实验表明，在约1 bar合成气和473 K条件下，随着碳覆盖度增加，表面并未发生预测的粗糙化，而是发生了一种独特的碳诱导表面重建，揭示了催化剂在实际反应条件下的真实表面状态。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":5.0,"t":5.0},"kp":["催化剂表面状态[工业费托合成Co基催化剂]: 验证表面是否发生对其催化活性必不可少的碳诱导粗糙化"]},{"i":41098,"as":"研究通过杂原子取代实现了唑类γ-肽的螺旋构象转换。设计了构象受限的噻唑和恶唑基γ-氨基酸，利用杂环内关键的1,4-X···O相互作用（X=S或N）介导的立体电子效应，使其分别采取由分子内C9或C7氢键驱动的构象。研究表明，噻唑基寡聚物形成典型的9-螺旋，而通过杂环取代可精确调节非共价相互作用来控制多肽骨架的折叠方式。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":4.0},"kp":["骨架折叠控制[唑类γ-肽]: 通过杂原子取代和调节内在立体电子效应实现构象转换"]},{"i":41099,"as":"研究发现在无需外部氧化剂、金属催化剂或热激活的条件下，微滴中的环己酮等环状酮可直接发生六电子氧化并伴随C-C键断裂。机制研究表明，微量水的存在生成了活性自由基物质从而引发转化。同位素标记（D₂O和H₂¹⁸O）实验证实，水自由基阳离子（H₂O•+）是此反应中的活性氧化剂。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["氧化反应特性[微滴中环酮转化]: 无需外部氧化剂、金属催化剂或热激活即可实现直接六电子氧化和C-C键断裂","反应引发机制[微滴氧化体系]: 微量水存在下生成高活性自由基引发氧化转化"]},{"i":41100,"as":"针对固态锂硫电池中Li⁺-阴离子持续配位限制界面稳定性和硫氧化还原动力学的问题，研究在聚合物固态电解质中引入离子液体修饰的ZIF-67（IL@ZIF-67）。该材料在分子水平上重组了离子配位并重构了Li⁺传输路径：ZIF-67位点优先锚定TFSI⁻阴离子，受限的离子液体域重塑了Li⁺传输网络，从而实现了稳定、高效的选择性Li⁺传输。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["离子传输机制[固态锂电池聚合物电解质]: 引入离子液体修饰的ZIF-67构建动态离子对网络以解耦Li+-阴离子配位"]},{"i":41101,"as":"研究发现摩根菌中的I型萜烯环化酶（MmTC）能将α- presodorifen焦磷酸转化为笛卡烷。这是一种结构前所未有的C16高倍半萜烯。与常规萜烯产物不同，笛卡烷完全饱和，不含烯烃和醇官能团，但在一个异常的终止步骤中形成了环丙烷环。这种非经典萜烯生物合成途径突破了传统C5n结构逻辑，扩展了萜烯的结构多样性。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["分子骨架特征[笛卡烷生物合成]: 完全饱和的C16高倍半萜烯，具有由细菌I型萜烯环化酶产生的前所未有的骨架"]},{"i":41102,"as":"为高效处理有机废水中难降解的芳香化合物，研究提出一种协同接力策略，整合了苯氧基自由基介导的低聚和芳环开环过程。该过程通过双单原子铁催化剂，在一个位点由高价铁-氧物种驱动夺氢实现低聚，随后在相邻位点由单线态氧（¹O₂）介导开环反应。该策略解决了传统单一聚合或开环矿化反应途径不明确的问题。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":5.0,"t":5.0},"kp":["[有机废水处理]: 苯氧基自由基介导的低聚和芳环开环协同接力策略","初始反应物[有机废水处理]: 高价铁氧物种"]},{"i":41103,"as":"针对盐聚合物（PIS）固态电解质中残留溶剂引起的界面降解及离子电导率与力学性能难以兼顾的问题，研究提出一种多用途集成填料设计。以CaF₂填料为例，其通过氟空位缺陷促进盐解离并生成离子传导位点，同时利用氢键相互作用增强聚合物基质的机械性能。该策略结合缺陷化学与界面工程，成功实现了长寿命、高安全的固态锂电池。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":6.0,"t":5.0},"kp":["[固态锂电池聚合物电解质]: 多用途集成填料设计","[聚合物盐电解质(PIS)痛点]: 残留溶剂引起的界面降解及离子电导率-力学性能的固有制衡"]},{"i":41104,"as":"研究成功合成了室温下为蓝色气体且极易二聚的六氟硫代丙酮，并通过单晶X射线衍射、核磁共振和密度泛函理论（DFT）对其结构进行了表征。其C═S键长为1.583–1.595 Å，是非累积二烯体系中报道的最短C═S键。DFT计算表明该键为极性较弱的共价键，且由于强吸电子CF₃基团的作用，C═S键的极性发生了反转（Cᵟ⁻═Sᵟ⁺）。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["C═S键长[六氟硫代丙酮非累积体系]: 1.583–1.595 Å","物理状态[六氟硫代丙酮室温]: 蓝色气体","聚合倾向[六氟硫代丙酮]: 极易二聚"]},{"i":41105,"as":"生物信息学分析确定中性粒细胞弹性蛋白酶（NE）是肺炎进展的关键生物标志物。研究开发了由半花青荧光团和NE敏感肽组成的NE响应探针（NERP）。为实现尿液分析，进一步将其优化为亲水性主动靶向响应探针（ATRPᴴ）。该探针在炎症组织中被特异性激活，在体内成像和基于尿液的检测中均展现出极高的敏感性，实现了肺炎的早期准确检测。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":6.0,"t":4.0},"kp":["特异性生物标志物[肺炎进展]: 中性粒细胞弹性蛋白酶(NE)","探针构成[NE响应探针(NERP)]: 由花菁类荧光团连接NE敏感肽组成","激活机制[NE响应探针(NERP)]: 特异性响应并在感染部位激活"]},{"i":41106,"as":"","scd":null,"kp":[]},{"i":41107,"as":"","scd":null,"kp":[]},{"i":41108,"as":"","scd":null,"kp":[]},{"i":41109,"as":"","scd":null,"kp":[]},{"i":41110,"as":"","scd":null,"kp":[]},{"i":41111,"as":"","scd":null,"kp":[]},{"i":41112,"as":"","scd":null,"kp":[]},{"i":41113,"as":"","scd":null,"kp":[]},{"i":41114,"as":"研究开发了一种不对称氮杂环卡宾（NHC）有机催化平台，利用全新设计的整合中环骨架与C2对称手性单元的噻唑催化剂，成功实现了惰性C(sp2)─C(sp3)键的高对映选择性自由基酰化反应。该技术突破了无张力、非极性碳-碳键直接官能化在有机催化领域中长期存在的障碍，实现了极高的对映选择性。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":5.0},"kp":["[NHC有机催化平台]: 实现惰性C(sp2)─C(sp3)键的高度对映选择性酰化"]},{"i":41115,"as":"针对钙钛矿量子点表面原子态复杂无序导致近红外发光二极管（LED）寿命受限的问题，研究人员引入了多功能添加剂4-氨基苯磺酸锌。该物质含有的四个官能团及离子（-NH2、-S-O、-S=O和Zn2+）具有双重氢键效应，能强化表面原子终止并减轻结构无序，使光致发光量子产率提升至90%以上，成功制备出高性能近红外LED器件。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":8.0,"t":5.0},"kp":["表面修饰剂[近红外钙钛矿量子点]: 多功能4-氨基苯磺酸锌(II)","配体特征[近红外钙钛矿量子点表面修饰剂]: 包含四个官能团和离子(-NH2等)","[钙钛矿量子点表面结构紊乱]: 通过多配位协同缓解表面原子态紊乱以提升器件寿命"]},{"i":41116,"as":"为解决太阳能驱动电化学二氧化碳还原生成多碳（C2+）产物的过电位高和效率低的问题，研究开发了碱性环境调制预还原策略，精准合成了碘掺杂铜纳米拓扑结构。该催化剂具备可调的欠配位缺陷和稳定的高能吸附位点，生成C2+产物的起始电位仅为-0.37V（vs RHE），大幅提升了人工光合作用的转化效率。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["催化剂合成策略[太阳能驱动CO2还原]: 碱性环境调制的预还原策略","催化剂形态[太阳能驱动CO2还原]: 碘掺杂铜（热力学控制的Cu-I纳米拓扑结构）","[太阳能驱动CO2还原]: 高效转化为多碳(C2+)产物"]},{"i":41117,"as":"研究报道了一种可重构铁电晶体管（Fe-FET）阵列，通过极化编程的局域电场在双极性二硒化钨（WSe2）通道中实现结势垒工程。该机制能够协同编程光响应、线性模拟计算和非线性激活功能，打破了传统传感与内存计算平台对外围元件的依赖及固定功能划分，满足了边缘人工智能对硬件紧凑、灵活重构的需求。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["硬件功能[可重构铁电晶体管阵列]: 集成硬件本机传感、线性模拟计算和非线性激活","[神经形态视觉系统]: 通过可重构铁电晶体管阵列保持模拟信号路径的完整性并支持功能重分配"]},{"i":41118,"as":"","scd":null,"kp":[]},{"i":41119,"as":"","scd":null,"kp":[]},{"i":41120,"as":"为实现全彩像素化激光显示，研究提出了一种光诱导气固阴离子交换（PVAE）策略。该策略通过精确的时间调制控制CsPbX3（X=Cl, Br, I）钙钛矿的光开关阴离子交换，交换速率可通过照射波长和强度进行调节。在1561.8 μW/cm²的紫外光激活下，PVAE可驱动完整的成分转变，成功实现了对放大自发发射（ASE）的有效控制。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["调控策略[全彩像素化激光显示器]: 光诱导气-固阴离子交换(PVAE)策略","基底材料[放大自发辐射(ASE)控制]: CsPbX3 (X = Cl, Br, I) 钙钛矿"]},{"i":41121,"as":"为克服传统二氧化碳（CO2）捕集系统解吸能耗高且吸收剂易损失的局限，研究开发了微孔碳捕集溶液（MCCS）。该溶液将具有永久孔隙的ZIF-67框架分散于液体吸收剂中，使CO2捕集容量提升约45%。同时采用微泡活化再生（MAR）替代传统热脱附，释放100%物理吸附的CO2，使单乙醇胺损失率降低约38%。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["CO2捕获容量提升[微孔碳捕获溶液(MCCS)]: 相对提升约45%","吸收剂设计[MCCS]: 将具有永久孔隙率的框架(ZIF-67)分散在液体吸收剂中","[CO2再生机制]: 取代传统热解吸，采用接触电催化驱动的微泡激活CO2再生"]},{"i":41122,"as":"针对短历史时间序列数据预测困难的问题，研究引入了元学习模型METAFORS。该模型通过从相关系统的长序列数据训练库中学习并迁移知识，为目标系统量身定制并初始化预测模型。在模拟混沌系统上的测试证明，基于储备池计算的METAFORS能够克服数据量不足的限制，可靠预测系统的短期动态和长期特性。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[短时间序列预测]: 引入元学习(METAFORS)跨系统泛化知识，以实现数据匮乏场景下的定制预测"]},{"i":41123,"as":"巨型金矿床的形成与造山运动及海山俯冲在时空上密切相关。地球化学分析表明，地幔柱将深部金元素泵入洋壳海山中；海山链俯冲时释放金元素并存储于上覆板块底部；随后发生的广泛熔融作用最终促使巨量金矿化。这一三阶段机制揭示了海山俯冲在造山型金矿形成中的核心驱动作用。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":7.0,"t":5.0},"kp":["[海山俯冲带成因]: 提出巨型金矿化的时空与成因联系，揭示金含量随变质程度升高而降低的演化规律"]},{"i":41124,"as":"","scd":null,"kp":[]},{"i":41125,"as":"传统弱值未考虑系统演化，无法有效捕捉量子动力学信息。研究引入了过程弱值（PWV）概念，将前选择和后选择之间观测量的量子演化纳入考量。通过建立PWV与酉算子矩阵元素的联系，构建了直接表征量子过程的理论框架，并在单光子、双光子及非厄米宇称-时间对称量子过程中完成了实验验证。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[量子动力学表征]: 引入过程弱值(PWV)，通过包含前选择和后选择之间可观测量的量子演化来直接表征量子系统动力学"]},{"i":41126,"as":"","scd":null,"kp":[]},{"i":41127,"as":"","scd":null,"kp":[]},{"i":41128,"as":"","scd":null,"kp":[]},{"i":41129,"as":"","scd":null,"kp":[]},{"i":41130,"as":"研究展示了一种三维拓扑极化弹性超材料，通过引入弯曲刚度，将零频率拓扑力学状态提升为有限频率的声子模式。这些模式集中在单一边界，在静态和动态下均产生显著的刚度对比。该三维结构在所有空间维度上表现出高度极化的力学行为，实现了全向不对称拓扑弹性，实验与数值结果证实了其稳健的不对称能量隔离效果。","scd":{"b":9.0,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":["拓扑机械状态[3D弹性超材料]: 将零频率状态提升为有限频率的声子模式","[拓扑极化弹性超材料]: 在静态和有限频率下通过单边界局域模实现不对称能量隔离"]},{"i":41131,"as":"研究提出了一种名为CleanAir的深度学习模型，用于模拟减排响应下的每日PM2.5浓度及其化学成分。该模型基于残差对称三维U-Net架构，提供36公里水平分辨率的预测。CleanAir运算速度极快，能够在中国范围内使用GPU在10秒内或CPU在160秒内估算出365天的PM2.5浓度，有效克服了传统化学传输模型计算耗时的限制。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":7.0,"t":4.0},"kp":["[减排响应预测]: 构建深度学习模型模拟每日PM2.5浓度及其化学成分，以克服传统化学传输模型计算量过大的瓶颈"]},{"i":41132,"as":"","scd":null,"kp":[]},{"i":41133,"as":"研究开发了一种具有周期性屈曲结构的可拉伸有机光电探测器（OPD），能够在单一设备中实现光和应变的双模传感。该设备允许实时估算有效检测位置的变化，解决了可拉伸光探测器变形时检测位置偏移的问题。其开路电压仅取决于光强度，而短路电流则反映应变变化，适用于下一代可穿戴健康监测。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":7.0,"t":4.0},"kp":["传感器[周期性屈曲结构]: 可拉伸有机光电探测器，能够克服形变导致的光检测位置偏移，实现双模态光学和应变传感"]},{"i":41134,"as":"","scd":null,"kp":[]},{"i":41135,"as":"研究提出了一种名为脊辅助微定位（RAMP）的微流控方法，利用通道脊产生的工程微涡流和流体升力，确定性地将聚焦细胞流精确定位到所需的流线上。与惯性聚焦不同，RAMP方法不依赖于颗粒大小和流速，能够使多分散颗粒在宽流速范围内聚焦到同一流线上。通过改变通道脊的放置位置和几何形状，可以实现微米级的精确横向位置控制。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":6.0,"t":4.0},"kp":["细胞微定位[微流控通道]: 脊辅助微定位技术(RAMP)利用通道脊产生的微涡流和流体升力，独立于惯性聚焦实现细胞流的确定性侧向定位"]},{"i":41136,"as":"研究实验演示了利用自旋轨道扭矩（SOT）驱动的皮秒电脉冲，实现三端磁隧道结（MTJ）的无磁场切换，将电气切换速度极限提升了一个数量级。研究进一步利用电压门控（VG）效应探测了宽脉冲宽度范围内的SOT切换机制，发现VG-SOT效率具有非单调性：在长脉冲激发下效率显著，在亚纳秒级时减弱，但当脉冲宽度缩短至13.2皮秒时再次出现。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["切换速度[磁隧道结(MTJ)]: 皮秒级","[自旋轨道扭矩(SOT)切换]: 利用皮秒电脉冲实现三端子器件的无场切换，速度超越现有极限一个数量级"]},{"i":41137,"as":"","scd":null,"kp":[]},{"i":41138,"as":"","scd":null,"kp":[]},{"i":41139,"as":"","scd":null,"kp":[]},{"i":41140,"as":"","scd":null,"kp":[]},{"i":41141,"as":"","scd":null,"kp":[]},{"i":41142,"as":"","scd":null,"kp":[]},{"i":41143,"as":"","scd":null,"kp":[]},{"i":41144,"as":"","scd":null,"kp":[]},{"i":41145,"as":"研究开发了一种低温（120°C）醇解技术，用于聚对苯二甲酸乙二醇酯（PET）的回收和升级循环。该工艺成功应用了功能性生物衍生醇（如异戊二烯醇等萜类化合物）进行解聚，不仅支持高效的PET解聚，还能实现重新聚合。此外，不饱和萜醇解产物还可通过巯基-烯反应制备热固性聚合物网络，克服了传统回收方法反应条件苛刻、效率低下的瓶颈。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["反应温度[聚对苯二甲酸乙二醇酯(PET)醇解]: 120°C"]},{"i":41146,"as":"","scd":null,"kp":[]},{"i":41147,"as":"研究利用范德华亚铁磁体CuCrP2S6中复杂的极性序竞争，提出了一种“极性可重构忆阻器”的新型器件概念。现有忆阻器技术受限于固定的极性，一旦集成到电路中其电响应方向无法改变。这种新器件打破了这一限制，能够实现极性反转，从而满足复杂神经网络对于硬件灵活重构的动态计算需求。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["磁滞反转[范德华铁电体]: 由极性序竞争驱动","[忆阻器件]: 打破固定极性限制，实现单一器件动态重构操作模式以适应计算工作负载"]},{"i":41148,"as":"针对非水氧化还原液流电池（NARFBs）中膜材料面临的导电性-选择性权衡和微孔膜润湿性差等问题，研究开发了一种具有抗溶胀性和优异乙腈润湿性的微孔阴离子导电框架聚合物膜。该膜通过增强稳健微孔与乙腈的亲和力，实现了快速且高度选择性的TFSI-离子传导，有效克服了离子交换膜与有机电解质的不相容性缺陷。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[非水氧化还原液流电池]: 面临多孔隔膜导电性-选择性权衡、微孔膜润湿性差及离子交换膜与有机电解质不兼容等挑战","[非水氧化还原液流电池]: 提出超润湿框架聚合物膜实现快速TFSI−传导"]},{"i":41149,"as":"研究构建了一种CO2介导的锂氧电池（CLOB）。传统锂氧电池受限于缓慢的动力学，实际放电电压低于2.85V，存在容量高但功率输出低的困境。该研究通过优化气体组成和催化架构重新定义氧氧化还原化学，成功将电池的放电电压提升至3.30V，该电压水平与磷酸铁锂（LiFePO4）电池相当。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["放电电压[CO2介导的锂氧气电池]: 3.3 V","放电电压[传统Li-O2电池动力学限制]: 低于2.85 V"]},{"i":41150,"as":"","scd":null,"kp":[]},{"i":41151,"as":"研究报道了一种太阳能驱动的光热策略，用于实现CO2介导的废塑料高效升级回收。该工艺能够将包括聚烯烃、聚酯、共聚物及其混合物在内的多种塑料，转化重组为高附加值的合成气（syngas）和碳纳米管。这种方法克服了传统CO2介导塑料回收工艺中能量需求高、效率低以及对塑料普适性有限的缺陷，实现了两种主要废弃碳资源的同步转化。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[太阳能驱动CO2介导的废塑料升级回收]: 可同时将废弃塑料和CO2转化为高附加值合成气与碳纳米管"]},{"i":41152,"as":"研究报道了一种无需试剂、热驱动的表面单原子编辑策略，成功将杂原子锚定的自组装单层转化为功能性N-杂环卡宾（NHC）层。带有特定取代基的N-杂环硫脲在造币金属表面发生硫到金属吸附原子的交换，形成吸附原子结合的NHC。研究人员利用低温扫描隧道显微镜（LT-STM）、同步辐射X射线光电子能谱（SR-XPS）、飞行时间二次离子质谱（ToF-SSIMS）和密度泛函理论证实了该结构。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[表面单原子编辑]: 提出无试剂、热驱动的表面策略，将杂原子锚定的硫脲自组装单层转化为功能性N-杂环卡宾层"]},{"i":41153,"as":"研究在连续固定床反应器中实现了集成串联催化，直接将硝基苯、CO2和H2转化为N-甲基苯胺。该工艺使用CuZnZrOx催化剂，实现了99%的转化率和95%的选择性，且稳定运行时间超过100小时。机理研究证实，催化过程中的关键活性位点为Cu+-Ov-Zn形态的Cu-ZnO界面。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["合成工艺[直接CO2合成N-甲基苯胺]: 连续固定床反应器中的集成串联催化","反应物[N-甲基苯胺合成]: 硝基苯、CO2和H2"]},{"i":41154,"as":"研究首次开发了硼烷催化的N-环烷叉基（CAD）取代芳基环烷基胺的级联重排反应，实现了在单一步骤中高效构建含有相邻季碳立体中心的角稠合氮杂四环框架。该反应由B(C6F5)3介导的α-氢化物抽象引发，随后经历氮杂-6π电环化和两次连续的扩环反应，最后通过氢化物回弹生成最终产物。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["催化剂[含邻位季碳立构中心的角式氮杂四环骨架构建]: 硼烷催化级联重排","[环烷基胺骨架重排]: 实现无邻位季碳立构中心骨架的高效单步构建"]},{"i":41155,"as":"黄素辅因子在有机合成化学中扮演着全能角色。黄素具有广泛的催化活性谱，可通过合成或生化方法轻松获取，且与其他有机催化剂相比展现出正交反应性。目前，黄素催化已成为多种有机催化和光化学方法的核心组成部分，其应用范围涵盖从全合成到生物相容性光邻近标记等多个领域，且多种黄素介导的有机反应已通过仿生方式成功开发。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":5.0,"t":3.0},"kp":["[有机合成中的黄素催化剂]: 广泛应用于有机催化和光化学方法，并具有生物兼容的光邻近标记能力"]},{"i":41156,"as":"研究利用乙烯基吡啶鎓结构单元的双重光化学活性，在配位聚合物框架内同时整合了[2+2]光环加成和光诱导电子转移过程。这使单一晶体系统产生三重光响应，同时实现光致变色、荧光调制和光致机械致动。高效的光环加成导致框架内快速应力积累与释放，引发光致变色爆炸现象；而框架依赖性的配体构象则产生独特的荧光读数，可用于光学监测反应进程。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[光响应配位聚合物智能材料]: 利用乙烯基吡啶鎓构建单元的双光化学活性，在单一结晶系统中同时实现光致变色、荧光调制和光致驱动三重响应"]},{"i":41157,"as":"研究设计了NiPt-Ni(OH)2界面催化剂以调节局部微环境，实现了在中性条件、室温下从水合肼高效制氢。该界面工程建立了强电子耦合作用并改变了肼的吸附行为。该催化剂的表观转化频率（TOF）达到310.7 h⁻¹，有效克服了水合肼在中性条件下反应动力学缓慢的限制。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[中性介质水合肼脱氢制氢]: 设计NiPt-Ni(OH)2界面调节局部微环境（局部碱度工程），打破中性条件下的迟滞动力学限制"]},{"i":41158,"as":"研究报道了一种水相合成策略，通过一锅法级联反应构建了含有丙烯酮和间吡啶基双键的共价有机框架（COFs）。该方法结合了可逆的羟醛缩合与不可逆的Chichibabin吡啶合成，利用查尔酮单元促进结晶化。作为无金属电催化剂（PYP-3），该双键COF在工业级电流密度下展现出高效的析氢和析氧性能。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["催化剂[析氢和析氧反应]: 具有丙烯酮和间吡啶基双连接的共价有机框架（COF）","合成工艺[双键共价有机框架]: 水相一锅法级联合成","[工业级电流密度]: 实现高效析氢和析氧"]},{"i":41159,"as":"研究设计了一系列基于二硫键的自消除酰基共轭物，用于可逆地保护RNA核糖的2'-羟基位置。该修饰策略能够响应内源性谷胱甘肽水平，在溶液和培养细胞中实现RNA的高效恢复。该修饰使RNA免受核酸酶和翻译机制的降解，提高了细胞稳定性并最小化先天免疫激活。此外，通过改变环大小和电子特性可调控RNA脱保护动力学，从而实现绿色荧光等靶标蛋白的持续合成。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[谷胱甘肽响应性RNA修饰]: 利用基于二硫键的自消除酰基偶联物保护核糖2'-羟基，实现内源性谷胱甘肽响应的高效RNA恢复与可控释放"]},{"i":41160,"as":"研究结合原位ICP-MS与离子交换方法量化了离聚物中滞留的铂，以此分析铂电催化剂的质量平衡。研究发现，离聚体与铂的直接接触会增强其本征溶解，同时捕获溶解的铂离子，导致显著的微观环境差异。该结果有效区分了表观溶解与实际金属损失，揭示了离聚体化学性质与载体孔隙率共同决定催化剂金属流失的真实机制。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[铂电催化剂稳定性损失机制]: 来源于受催化剂微环境强烈影响的溶解、再沉积和重构过程"]},{"i":41161,"as":"","scd":null,"kp":[]},{"i":41162,"as":"","scd":null,"kp":[]},{"i":41163,"as":"","scd":null,"kp":[]},{"i":41164,"as":"","scd":null,"kp":[]},{"i":41165,"as":"研究使用系统的第一性原理计算重新审视了无铅钙钛矿AgNbO3的低能结构。该材料在储能和光电应用方面具有巨大潜力，但其低温晶体结构一直存在争议。研究揭示了AgNbO3中隐藏的手性铁电性，解决了关于其低温晶体结构的长期争议。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[AgNbO3钙钛矿]: 无铅钙钛矿，具有在储能和光电应用方面的巨大潜力"]},{"i":41166,"as":"研究通过形式化的群论证明和系统的群-子群分析证实，在导致对映空间群对的相变中，手性不能充当铁性序参量。尽管周期性固体的结构手性引起了广泛关注，但该工作明确指出在非手性到手性的相变过程中，手性无法作为一种新的铁性序。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":4.0,"t":8.0},"kp":["[手性在对映空间群对的相变中]: 不能是铁性序参量"]},{"i":41167,"as":"","scd":null,"kp":[]},{"i":41168,"as":"研究利用自旋纹理动力学开发了低噪声、高灵敏度的磁传感器。传统磁传感器长期受限于噪声和灵敏度同时增加的根本制约。该研究通过自旋纹理动力学机制打破了这一瓶颈，成功实现了适用于汽车系统、生物医学成像和磁性显微成像等应用的高性能磁传感技术。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":8.0},"kp":["[传统磁传感器性能约束]: 噪声和灵敏度伴随增加，存在根本性制约"]},{"i":41169,"as":"","scd":null,"kp":[]},{"i":41170,"as":"","scd":null,"kp":[]},{"i":41171,"as":"研究探讨了扭曲双层${\\mathrm{MoSe}}_{2}$同质双层中晶格重构演化时多电子激发态的产生。在晶格重构的过渡区域发现了一种新的激子共振现象。该共振源于扭曲层之间原子排列的逐渐变化，为理解莫尔超晶格中的多体物理和电子激发态动力学提供了新视角。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":8.0},"kp":["[扭曲MoSe2同质双层]: 晶格重构演化驱动了激子共振和新型多电子激发态出现"]},{"i":41172,"as":"二维半导体中的激子直接暴露于环境中，对其周围的介电特性非常敏感。研究利用压力调谐技术，探测了封装在六方氮化硼中的单层${\\mathrm{WSe}}_{2}$的激子里德伯激发态系列。通过施加压力改变介电屏蔽效应，实现了对二维范德华异质结构中激子行为和介电环境的精确表征。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":8.0},"kp":["[单层WSe2封装于六方氮化硼中]: 可通过压力调谐激子里德伯系列探测介电屏蔽特性"]},{"i":41173,"as":"","scd":null,"kp":[]},{"i":41174,"as":"","scd":null,"kp":[]},{"i":41175,"as":"利用变分状态分析了能带几何效应对二维维格纳晶体（每个晶胞包含一个或两个电子）的影响。在足够低的电子密度下，增加贝里曲率会驱动系统转变为由自旋三重态配对组成的晶体状态。研究表明，量子能带几何能够稳定自旋三重态配对的维格纳晶体。","scd":{"b":8.0,"i":1.0,"r":6.0,"d":5.0,"t":8.0},"kp":["[二维维格纳晶体]: 足够低的电子密度下，增加贝里曲率会驱动形成由量子几何稳定的自旋三重态配对结晶态"]},{"i":41176,"as":"","scd":null,"kp":[]},{"i":41177,"as":"绿色氢气作为难以减排行业的燃料或原料，已成为众多能源和工业政策的核心。这一发展趋势不仅带来了新的机遇，也引发了相应的技术与政策问题。本焦点专题重点探讨了绿色氢气在当前能源转型和工业应用中的实际角色与面临的挑战。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":3.0,"t":6.0},"kp":["[绿色氢气应用]: 作为燃料或原料用于难以减排的领域"]},{"i":41178,"as":"无机胶体量子点发光二极管因优异的色彩性能和电学稳定性，是新一代电致发光显示器的理想选择。为解决大面积高分辨率像素集成问题，研究人员开发了一种裂解辅助转印技术。该技术通过可控裂解过程断裂量子点间的内聚键，从而高精度地将其拾取并转印到薄膜晶体管背板上，实现了大面积全彩像素阵列的高分辨率图案化。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[裂解辅助转印技术]: 可在有源矩阵背板上沉积量子点阵列并保持均匀性和精度，无颜色交叉污染"]},{"i":41179,"as":"","scd":null,"kp":[]},{"i":41180,"as":"","scd":null,"kp":[]},{"i":41181,"as":"","scd":null,"kp":[]},{"i":41182,"as":"","scd":null,"kp":[]},{"i":41183,"as":"","scd":null,"kp":[]},{"i":41184,"as":"","scd":null,"kp":[]},{"i":41185,"as":"讨论扩张蛋白介导的细胞壁蠕变机制，区分其催化活性与蠕变活性的作用差异。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["作用机制[扩张蛋白介导]: 区分催化活性与蠕变活性"]},{"i":41186,"as":"研究发现，电化学掺杂有机半导体中的电荷载流子（即极化子）受化学组成、电解液性质及材料形貌变化等多重物理化学因素调控。研究团队以π共轭氧化还原共聚物N2200为对象，深入探究了电化学掺杂过程中负极化子的能量、光电、化学及局部结构特性。\n\n关键发现表明，掺杂后的聚合物中并非只存在单一类型的极化子，而是形成了一个极化子集合体，这些极化子展现出截然不同的光电特征。因此，极化子可作为探测电化学掺杂聚合物内部动态纳米级环境的有效探针。","scd":{"b":7.5,"i":2.5,"r":6.0,"d":5.5,"t":5.0},"kp":["调控因素[电化学掺杂π共轭聚合物中的极化子]: 半导体嵌段的化学组成与结构、电解质化学性质、多尺度及时间依赖的形态变异"]},{"i":41187,"as":"","scd":null,"kp":[]},{"i":41188,"as":"AI蛋白质结构预测模型在处理静电相互作用时存在准确性问题。实验生成的一种包含四个可电离残基取代的U1A蛋白变体，表现出与野生型截然不同的三聚体结构。然而，深度学习和基于Transformer的模型预测出的结构却与野生型高度一致，并且错误地将可电离残基置于非极性核心内，这违背了基本的物理化学原理。","scd":{"b":7.0,"i":3.0,"r":6.5,"d":7.0,"t":5.5},"kp":["[U1A蛋白变体螺旋结构]: 约为野生型的两倍且呈三聚体","[AI蛋白质预测模型深度学习预测精度(骨架RMSD)]: < 1 Å"]},{"i":41189,"as":"","scd":null,"kp":[]},{"i":41190,"as":"","scd":null,"kp":[]},{"i":41191,"as":"提出了一种可持续的自下而上策略来制备混合淀粉样氮化硼气凝胶。该方法利用乳清蛋白淀粉样原纤维作为可再生支架，辅助氮硼富集域的组织。通过温和的超声-冷冻干燥工艺，制备出具有分级多孔结构的超轻气凝胶。该气凝胶结合了机械增强性、中等条件下的热稳定性以及优异的声学隔音表现。","scd":{"b":7.5,"i":3.5,"r":6.0,"d":7.5,"t":5.5},"kp":["气凝胶材料[轻质隔音混合气凝胶]: 混合淀粉样氮化硼气凝胶","合成策略[混合硼氮化物-淀粉样原纤维气凝胶]: 可持续的、自下而上的策略（采用乳清蛋白淀粉样原纤维作为可再生支架）"]},{"i":41192,"as":"针对钙钛矿太阳能电池在紫外线辐射下快速降解的问题，研究人员在钙钛矿前驱体溶液中引入了内源性氧化还原敏感紫外线吸收剂TTOB。TTOB具有卓越的紫外线屏蔽能力和持续的化学钝化效应，可不断修复材料缺陷。完全在空气环境中制备的器件最终实现了25.24%的最佳光电转换效率，显著提升了器件的效率和稳定性。","scd":{"b":7.5,"i":4.0,"r":6.5,"d":8.0,"t":6.0},"kp":["紫外线吸收剂[钙钛矿太阳能电池内源性添加剂]: 2,2\"-硫代双-(4-叔辛基苯氧基)-丁胺镍(TTOB)","添加剂特性[内源性氧化还原敏感紫外线吸收剂]: 具有氧化还原敏感性，可提升光伏效率与稳定性"]},{"i":41193,"as":"为解决传统衍射防伪标签易受环境污染变形和信息容量有限的问题，研究提出在光敏聚氨酯薄膜上构建高分辨率、角度可切换的独立衍射图像。该技术利用聚氨酯薄膜上的屈曲诱导微纳米结构，在单一通道内实现了八个独立图像的加密。这为光学加密和高级防伪提供了一种信息容量大且耐候性强的新策略。","scd":{"b":6.0,"i":3.0,"r":5.5,"d":6.5,"t":5.0},"kp":["衍射防伪标签[传统技术应用局限]: 多基于丙烯酸酯材料，加密结构简单且单通道加密信息容量有限"]},{"i":41194,"as":"I型光敏剂在光动力治疗中克服肿瘤缺氧极具潜力。研究利用供体-π桥-受体共轭调制，通过系统调节单三重态能隙、T1能级、氧化还原电位和空间位阻四个关键参数，设计了基于邻苯二甲腈的I型光敏剂。这些光敏剂优化了电子转移路径，表现出聚集诱导的I型活性氧生成能力。","scd":{"b":7.0,"i":2.5,"r":6.0,"d":6.5,"t":5.0},"kp":["光敏剂结构[邻苯二甲腈基I型光敏剂]: 供体-π桥-受体(D-π-A)共轭结构","技术效果[I型光敏剂设计应用于光动力治疗]: 克服肿瘤缺氧，最小化对氧气的依赖"]},{"i":41195,"as":"通过引入范德华相互作用诱导的碳化钼/二硫化钼异质结作为添加剂，实现了宏观超润滑。该异质结结合了二维材料的低层间剪切强度与液体超润滑的优势。构象转变的乙二醇分子与异质结发生协同作用，有效克服了单一二维材料承载能力低的问题，大幅降低了工业应用中的摩擦和磨损。","scd":{"b":8.0,"i":3.5,"r":6.5,"d":7.5,"t":5.5},"kp":["超润滑机制[二维材料与液体分子宏观固液协同]: 碳化钼/二硫化钼异质结与构象转变乙二醇分子协同诱导","超润滑特点[固液协同超润滑]: 结合二维材料的低层间剪切强度与液体超润滑的优势"]},{"i":41196,"as":"研究人员提出了一种可在多种光照度下完全充电的单片集成光充电电池（PRB）设计。该设计被用作模型系统，以揭示光充电电流的衰减与光诱导电荷动力学之间的相关性。结果表明，随着荷电状态的增加，光诱导空穴传输逐渐恶化，这归因于阴极层中阴离子耦合的空穴积累。此外，器件证实空穴传输层与阴极之间的电势差对于驱动光诱导电荷分离和传输至关重要。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["光充电过程限制[集成光充电电池]: 光致电荷动力学与光充电电流衰减密切相关"]},{"i":41197,"as":"本综述提出了一种以水为中心的统一框架，引入了“水行为链”概念，用于指导太阳能界面蒸发（SIE）技术。该框架完整映射了水从传输、状态调节、界面蒸发到产物管理的全过程。研究系统阐明了通过对该链条的分层调节可以实现性能突破，包括优化供水路径以实现最佳热管理，以及利用协同效应来降低蒸发焓并增强蒸发速率。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":4.0,"t":3.0},"kp":["理论框架[太阳能界面蒸发技术]: 以水为中心的统一框架，提出“水行为链”概念（涵盖水传输到水状态调节）"]},{"i":41198,"as":"本综述聚焦于锂离子电池系统中的热失控传播问题。热失控传播是一个由触发路径、传热模式和燃烧行为控制的阶段演化多物理场能量级联过程。文章将被动缓解策略根据热失控的早期、中期和晚期阶段的主导危害进行了重组，把热缓冲、热阻挡和灭火技术整合到了一个单一框架中，并分析了过充、外部加热和内短路等触发路径引发的固相传导和排气对流演变。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":5.0,"t":3.0},"kp":["热失控传播特征[锂离子电池系统]: 阶段性演变的、多物理场耦合的能量级联过程","缓解策略[热失控传播被动缓解]: 根据早、中、晚期的主导危害重新组织被动缓解策略（如热缓冲）"]},{"i":41199,"as":"","scd":null,"kp":[]},{"i":41200,"as":"","scd":null,"kp":[]},{"i":41201,"as":"为提升电卡（EC）制冷器件的温度跨度，研究人员构建了一种六层级联电卡制冷器件（SCECD）。该器件利用静电驱动与自驱动的协同作用，确保静电力和变形力在电卡堆栈上始终沿相同方向作用，从而显著增强热传递效率。此外，通过在电卡堆栈上蒸镀铜电极，进一步增加了器件的结构稳定性并实现了较大的温度跨度。","scd":{"b":6.0,"i":6.0,"r":5.0,"d":6.0,"t":6.0},"kp":["器件构型[电卡冷却装置]: 六层级联电卡冷却器件(SCECD)","技术效果[六层级联电卡冷却器件]: 实现大的温度跨度(ΔTspan)"]},{"i":41202,"as":"研究证明，通过使用InF3进行阴离子-阳离子共掺杂策略减弱离子传输各向异性，能够有效在低成本Li2ZrCl6中实现超离子传导。机制分析表明，适度的共掺杂降低了锂离子传输的固有各向异性，从而促进了更快的大范围扩散；而过量掺杂则会引入局部迁移瓶颈，阻碍离子传输。这为全固态电池卤化物固态电解质的设计提供了关键指导。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["固体电解质[低成本卤化物固态电解质]: Li2ZrCl6","技术途径[Li2ZrCl6实现超离子传导]: 通过阴离子调控减弱离子传输各向异性"]},{"i":41203,"as":"针对水系锌金属电池（AZMBs）界面不稳定的问题，研究建立了一种结合密度泛函理论和分子动力学模拟的合理筛选策略，以重塑水富集且无序的双电层（EDL）结构。结果表明，1-乙基-3-甲基咪唑鎓表现出强烈的界面亲和力，能够形成抑制寄生反应的疏水屏蔽层，实现“静态钝化”效果。该策略通过优化界面亲和力和传输动力学，显著提升了锌电池的稳定性。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["阳离子调节剂[水性锌金属电池界面调节]: 有机与无机阳离子调节剂","筛选策略[重塑内亥姆霍兹层(EDL)]: 结合密度泛函理论与分子动力学模拟"]},{"i":41204,"as":"研究展示了一种无需机器学习、自供电的视网膜形态热释电光电探测器，能够在365至940纳米波长范围内直接进行电学波长编码。该多端器件利用静电平衡的内置电势，将入射光波长转化为独特的光电和热释电电流指纹，从而无需光谱重建和外部神经网络处理，即可直接在传感器内部实现光谱识别和颜色分类。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["波长响应范围[机器学习自驱动视网膜形态热电光电探测器]: 365至940 nm","器件结构[多端端器件]: Ag/ZnO"]},{"i":41205,"as":"研究开发了一种能够协同可见光透明度与光热响应的双隐形软体机器人系统。通过对二维原子级超薄硫化铜（AT-CuS）纳米片进行界面工程，使其在聚合物基体中形成稳定的单层分散，成功实现了光谱解耦。该材料在近红外二区（NIR-II）达到了创纪录的96.3%的光热效率，实现了近红外光驱动的无形控制与光学完整性。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["光响应与透明度[近红外(NIR)光致动软体机器人]: 光谱解耦（打破需深色材料和高填充量以获得强光响应的传统限制）"]},{"i":41206,"as":"针对PbS量子点太阳能电池，研究提出了一种调节电子提取的自限性超薄分子层策略。设计的噻吩基分子通过硫醇锚点与表面的Pb2+离子配位，抑制了非辐射复合；同时，其富电子芳香环参与π-π相互作用，有效提升了电子传输效率。这种基于杂环桥接界面的工程手段，成功实现了高效p-i-n结构太阳能电池的构建。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["电子传输层[自限性超薄杂环分子层]: 具备电子萃取调制功能"]},{"i":41207,"as":"研究在KTaO3(110)二维电子气中预测并提供了轨道埃德尔斯坦效应的实验证据。通过扫描透射电子显微镜和电子能量损失光谱解析了界面原子构型，并结合密度泛函理论计算，研究证实了显著的轨道埃德尔斯坦效应主导了其谐波传输响应的各向异性。这一发现直接将原子结构与电子能带色散联系起来，为轨道电子学提供了微观机制和定量验证。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[轨道埃德尔斯坦效应]: 将电场转换为非平衡轨道极化"]},{"i":41208,"as":"","scd":null,"kp":[]},{"i":41209,"as":"研究利用DNA纳米技术构建了微尺度的多层核-壳DNA折纸晶体。该晶体内部各层具有尺寸、数量、自相似性和形态可调的特性。壳层体积可在700至1800立方微米之间调节，层数最多可扩展至五层。研究还通过将不同的纳米材料选择性地捕获到预定层中，成功制造出八种不同的晶体分布模式，促进了微尺度多功能隔离或级联过程。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["结构设计[微尺度多层核壳DNA折纸晶体]: 具备选择性捕获特定纳米材料至预定层的功能"]},{"i":41210,"as":"针对硅橡胶极难回收的问题，研究人员提出了一种硼辅助热机械剪切（BATS）升级回收策略。该策略在温和且无溶剂的条件下，直接将交联硅橡胶废弃物断裂并重组，使坚固的Si-O-Si骨架转化为动态的Si-O-B连接，成功将其转化为高附加值的聚硼硅氧烷（PBS）。该方法无副产物，有效实现了废旧硅橡胶的高价值转化。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["回收策略[硅橡胶转化为聚硼硅氧烷]: 硼辅助热机械断裂(BATS)升级回收"]},{"i":41211,"as":"为解决有机太阳能电池中自组装单层/多层（SAMs/SAMULs）表面覆盖不足的问题，研究采用共混自组装多层策略，将苯并[b]噻吩-2-基硼酸（BBA）作为客体分子引入主分子体系。研究发现，BBA能够融入主体分子胶束中抑制其生长，在成膜过程中产生协同效应，显著改善了表面覆盖率，成功构建了光电转换效率达21.26%的高效有机太阳能电池。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":8.0,"t":5.0},"kp":["转换效率[有机太阳能电池]: 21.26%","客体材料[共组装自组装多层]: 苯并[b]噻吩-2-基硼酸(BBA)"]},{"i":41212,"as":"研究成功合成了具有空气和湿气稳定性的氮化硼封端sp碳链，即BN嵌入式累积烯（[n]BN, n=3, 5）。结构与光谱分析表明，将BN单元嵌入碳骨架中，利用硼的空p轨道和氮的孤对电子产生的固有轨道极化，有效调控了体系的电子结构。该策略成功实现了对富sp碳体系光电性质的双向光电流调制。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["光电性能[嵌入氮化硼的累积烯]: 双向光电流调制"]},{"i":41213,"as":"研究通过结合光响应和pH响应变色团，开发了一种双波长3D数字光处理（DLP）系统，用于信息编码和加密。该系统使用405纳米波长LED触发光聚合构建无色三维结构，同时利用集成在系统中的365纳米波长LED局部诱导螺吡喃发生异构化产生颜色变化。这种多响应材料与多波长3D打印技术的结合，实现了信息在三维空间内的复杂编码与加密。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["信息编码与加密[3D数字光处理3D打印]: 结合光响应和pH响应生色团（螺吡喃和酚酞衍生物）的双波长3D打印"]},{"i":41214,"as":"","scd":null,"kp":[]},{"i":41215,"as":"研究提出了一种质子化门控策略，通过可逆调节共轭拓扑结构，实现了分子马达在宽可见光窗口下的状态依赖性运转。利用苯并唑取代基修饰香豆素衍生的拥挤烯烃，该分子马达能够在蓝绿光照射下发生高效的光异构化。结合密度泛函理论计算的光物理研究证实，质子化过程会诱导分子发生显著的构象反转，从而实现宽光谱响应的正交控制。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["分子马达[光调控]: 质子化门控策略实现宽可见光窗口下的状态依赖性操作","分子马达[吸收波段]: 红移至宽可见光响应"]},{"i":41216,"as":"","scd":null,"kp":[]},{"i":41217,"as":"研究构建了基于超薄金属有机框架（MOF）衍生电催化剂（Co-PET@NF）的反应物增强氢键网络，实现了高选择性的乙二醇电氧化（EGOR）。该界面具备动态稳定性，支持安培级电流密度下持续的反应物输送和质子耦合电子转移。机制表明，暴露的不饱和钴位点促进了乙二醇的优先吸附，提高了表面覆盖率并加速了补充动力学。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["电催化氧化[乙二醇]: 实现高选择性、安培级电氧化","催化剂-电解质界面[微环境]: 构建反应物增强的动态稳定氢键网络促进连续传质和质子耦合电子转移","催化剂载体[形貌特征]: 超薄金属有机框架"]},{"i":41218,"as":"无阳极锂硫电池通过避免直接使用金属锂，实现了极高的能量密度和本征安全性。为解决硫化锂正极反应迟缓及结构恶化问题，研究采用锚定包封纳米结构与碱土金属硫化物催化相结合的策略。通过密度泛函理论（DFT）计算筛选出优化的MgS电催化剂，并通过燃烧锂镁合金的金属热硫化碳化合成法实现了材料制备。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["电池体系[类型]: 无阳极锂硫电池","电池性能[优势]: 实现极高能量密度和本征安全性","正极结构[Li2S改性]: 锚定封装纳米结构协同碱土金属硫化物催化"]},{"i":41219,"as":"细胞内的过硫化物（如谷胱甘黄过硫化物GS-SH）能淬灭自由基，保护细胞免受铁死亡。研究运用酶抑制剂设计原理，开发了3-巯基丙酮酸硫转移酶（3-MST）的一系列新型人工底物。这些分子在3-MST催化下生成GS-SH并渗透细胞，有效增强了内源性过硫化物，从而保护细胞免受铁死亡，并在动物模型中减轻了全身炎症。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["底物[工程改造]: 硫转移酶的工程底物增强内源性氢过硫化物","生物效应[铁死亡]: 抑制由脂质自由基积累引发的铁死亡"]},{"i":41220,"as":"研究开发了用于氨基醇氧化制备氨基酸的银单原子催化剂。利用表面缺陷捕获策略，成功制备了具有原子级分散特性的Ag1/MOx催化剂（M=Ce, Fe, Ti, Zn, Nb）。载体上的氧 vacancy作为高亲和力捕获位点锚定孤立的银原子。银原子的电子密度由可还原氧化物的功函数调节，低功函数载体引发了更强的电子转移，从而产生富电子的活性位点。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["催化剂[氨基醇氧化]: 功函数可调的银单原子催化剂","催化剂合成[策略]: 表面缺陷捕获策略实现Ag的原子级分散及电子态调控","缺陷位点[作用]: 配位不饱和的MOx氧空位提供高亲和力锚定位点"]},{"i":41221,"as":"研究开发出厚度不足270微米的超薄铝空气电池。该电池采用吸湿性水凝胶电解质，在高浓度“盐包水”体系中，强烈的离子-水相互作用抑制了电解质脱水及铝的自腐蚀。在10 mA cm-2的电流密度下，实现了2479 mAh g-1的高容量。该电池可承受超过3000次弯曲循环，并在揉捏等严重变形下保持功能，满足可穿戴皮肤电子设备连续运行的要求。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["电池厚度[铝空气电池]: <270 µm","电解质[体系]: 吸湿性水凝胶和高盐中水体系","电解质[性能]: 离子-水强相互作用抑制电解质脱水和铝自腐蚀"]},{"i":41222,"as":"为加速电池材料研发，十五个欧洲实验室联合开展了大规模多模式工作流程。研究针对石墨/锂离子全电池，探讨了电解质组成对电极特性的影响以及电池老化失效时电极材料的演化过程。该工作流实现了从样品制备、传送到数据处理的完全标准化，生成了七十五组级联共享数据集。综合分析证实了互补实验技术的科学协同效应。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":5.0,"t":5.0},"kp":["表征工作流程[电池研究]: 跨15个欧洲实验室的大规模多模式表征平台","研究对象[体系]: 石墨/锂离子全电池"]},{"i":41223,"as":"针对碱性析氢反应（HER）中水分解与氢吸附之间的标度关系限制，研究通过引入镓（Ga）构建了具有功能分区活性位点的Ni-Ga-Pt三元催化剂。Ga的介导作用使得Ni位点的d带中心发生特定上移，增强了羟基吸附并加速了水分解；同时，Pt位点的d带中心下移0.22 eV，优化了氢吸附能。该机制实现了海水的高效且持久的析氢。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["催化剂[碱性海水析氢]: 镍-镓-铂三元催化剂实现功能分区","d波段中心[调控机制]: 引入Ga进行特定位置的d波段中心工程","反应路径[优化]: 打破碱性水解离和氢吸附/脱附之间的比例关系"]},{"i":41224,"as":"研究提出了一种基于电化学驱动溶解-结晶的制冷循环（EDCR）概念。该液态电化学冷却技术利用电化学再生氧化还原活性盐的吸热溶解过程产生冷量，将电化学再生过程与溶解冷却过程实现了空间分离，克服了传统电化学制冷中焦耳热抵消效应的问题。该系统实现了5.65 K的最大温降，最大制冷系数高达15.51。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":5.0},"kp":["制冷循环[机制]: 基于氧化还原活性盐溶解-结晶循环的电化学驱动制冷","制冷效应[来源]: 电化学再生的盐发生吸热溶解产生制冷效果"]},{"i":41225,"as":"功能水凝胶涂层能够赋予医疗器械底层基底柔软弹性、润滑性、生物相容性和抗生物污染等特性，同时保持其固有的机械完整性。该综述采用以医疗器械为导向的框架，系统总结了水凝胶涂层的主要功能，并深入剖析了涂层功能、制备策略、基底相容性、器械几何形状与临床应用场景之间的紧密联系。","scd":{"b":4.0,"i":5.0,"r":5.0,"d":4.0,"t":3.0},"kp":["涂层材料[医疗器械]: 功能性水凝胶涂层","涂层特性[界面性能]: 提供柔软弹性、润滑性、生物相容性和抗生物污垢特性"]},{"i":41226,"as":"","scd":null,"kp":[]},{"i":41227,"as":"研究首次将共价有机框架应用于光磁耦合析氢反应。通过合成后金属化策略，将高自旋Mn2+离子（3d5半充满构型）引入化学稳定的sp2碳连接的COFs中。利用电子自旋效应有效抑制了光生载流子的复合，突破了传统抗磁性光催化剂对外部磁场响应微弱的限制，从而显著促进了光磁催化析氢效率。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[光磁催化析氢]: 利用电子自旋抑制光生载流子复合","[常规光催化剂]: 主要为抗磁性，对外加磁场响应微弱","[共价有机框架(COFs)]: 首次应用于光磁耦合体系"]},{"i":41228,"as":"研究开发了一种电子细胞外基质，用于连接电子学和生物学。这是一种三维水合大分子网络，能够通过电信号触发释放储存在其中的蛋白质。释放的蛋白质与周围细胞相互作用，从而实现精确的生物学响应控制和细胞命运的外源传感。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[导电水凝胶/电子细胞外基质]: 通过电信号触发释放3D水合大分子网络中存储的蛋白质以精确控制生物反应"]},{"i":41229,"as":"研究开发了一种无DMSO的冷冻保存生物墨水策略（CAMP），将贴壁细胞作为功能性构建块，实现了按需直接生物打印。冷冻保存的细胞在经历生物打印后，能够发育成坚固且功能完善的组织。该技术突破了传统限制，为复杂组织的生物制造提供了新方法。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[贴壁细胞直接生物打印]: 采用CAMP无DMSO冷冻保存策略，将贴壁细胞作为功能性构建块实现按需生物打印"]},{"i":41230,"as":"研究构建了4-OH-TEMPO/[Fe(CN)6]3-/4--NiHCF||Zn双分子氧化还原靶向液流电池（DMRT）。该系统简化了氧化还原介体与固体材料的匹配过程，展现出高达75.04 Wh L-1的能量密度，是空白液流电池的9.09倍。同时，该电池实现了99.9%的卓越库仑效率，有效提升了水系液流电池的储能性能。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[水系氧化还原靶向液流电池]: 具有高能量密度、长循环寿命和高安全性","双分子氧化还原靶向体系(DMRT)[液流电池]: 简化了氧化还原介体与固体材料之间的匹配","[双介体/固体材料相互作用]: 存在4-OH-TEMPO/[Fe(CN)6]协同作用"]},{"i":41231,"as":"研究将铱纳米颗粒锚定在铁掺杂的MoO2上，制备出适用于酸性整体水分解的Ir/Fe-MoO2催化剂。铁掺杂通过形成Mo-O-Fe键稳定了MoO2晶格，提高了Mo的价态，有效抑制了材料的过度氧化与溶解。形成的Ir-O-Fe界面结构实现了双向电子转移，通过Brønsted酸位点诱导的桥接氧辅助去质子化，同时提升了析氧（OER）和析氢（HER）反应性能。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["催化剂[酸性整体水分解]: Ir纳米粒子锚定在Fe掺杂MoO2上(Ir/Fe-MoO2)","[催化机制]: 通过布朗斯台德酸位点诱导桥接氧辅助去质子化","[性能表现]: 对析氧反应(OER)和全解水均表现出高性能"]},{"i":41232,"as":"研究证实了基于罗丹明-二茂铁二元组的电化学荧光开关可在单个巨型单层囊泡中实现。该二元组通过氧化还原控制的光诱导电子转移调节荧光发射。这种荧光转换具有严格的叶片选择性，仅暴露于电极界面的二元组发生反应，突显了脂质双分子层的绝缘特性。此外，膜表面电荷对转换过程起到了关键的控制作用。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[电化学荧光转换开关]: 基于罗丹明-二茂铁二元组，在仿生膜（巨型单室囊泡）内通过氧化还原控制的光诱导电子转移调节发光"]},{"i":41233,"as":"研究CsPbBr3钙钛矿晶体宽带近红外发光的成因，探讨缺陷与铋杂质的潜在影响。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[CsPbBr3钙钛矿晶体宽带近红外发光成因]: 探讨缺陷与铋杂质的潜在影响"]},{"i":41234,"as":"Cu(II/I)配合物在电子转移反应中由于构型变化通常导致重组能较高，从而反应缓慢。然而，近期发现的Cu(II/I)配合物在氧化还原反应中虽有显著结构变化，却展现出极快的电子转移速率（>105 M-1 s-1）。研究提出预平衡模型，证实氧化态固有的构象流动性使反应能够通过重组能较低的路径进行，从而解释了其快速自交换现象。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[Cu(II/I)络合物电子转移]: 典型结构变化源于d9/d10构型的（伪）姜-泰勒畸变和极化率变化，导致重组能惩罚和缓慢的电子转移速率"]},{"i":41235,"as":"结合场景设计与自下而上建模，量化不同规划替代方案下电力负担能力的不平等问题。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":3.0,"t":3.0},"kp":["[电力负担能力不平等量化]: 结合变革性场景设计与自下而上建模及分配影响评估"]},{"i":41236,"as":"研究典型船舶工况下氢燃料电池的早期退化机制，并采用物理信息神经网络预测健康状态。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":4.0,"t":5.0},"kp":["[PEMFC电池组健康状态预测]: 采用物理信息神经网络(PINN)","[PEMFC电池组退化机制]: 研究典型船舶运行工况下的早期退化"]},{"i":41237,"as":"低频（50-80 Hz）运动丘脑深部脑刺激（DBS）可增强皮层-延髓纤维激活，提升运动输出。在针对创伤性脑损伤（TBI）患者的临床研究中，低频DBS有效改善了患者的慢性吞咽困难和重度构音障碍，显著提升了面部运动、吞咽效率和言语清晰度，证明了其在恢复言语和吞咽功能方面的临床潜力。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["刺激频率[运动丘脑深部脑刺激改善言语和吞咽]: 50-80 Hz（低频）促进相关功能"]},{"i":41238,"as":"探讨零间隙碱性水电解槽内大气泡运动行为对槽电压变化及电解效率的具体影响。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":4.0,"t":4.0},"kp":["槽电压[零间隙碱性水电解槽]: 受大气泡运动行为影响","电解效率[零间隙碱性水电解槽]: 受大气泡运动行为影响"]},{"i":41239,"as":"提出基于数字孪生与云边协作的弹性分层控制策略，解决非理想通信下多能源微电网控制问题。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[多能源微电网非理想通信控制]: 采用基于数字孪生与云边协作的弹性分层控制策略"]},{"i":41240,"as":"通过技术排名与优化组合分析，探讨BIMP区域电网的可持续能源转型路径与方案。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[BIMP区域电网可持续能源转型]: 通过技术排名与优化组合确定路径"]},{"i":41241,"as":"探讨结合图神经网络与加权总体最小二乘法的燃气轮机多故障诊断技术，研究内容侧重于故障诊断中的不确定性分析。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[燃气轮机多故障诊断]: 结合图神经网络与加权总最小二乘法，具备不确定性感知能力"]},{"i":41242,"as":"研究结合气象数据的物理信息驱动模型在热电联产系统中的应用，重点分析系统阻力增强及相关的风险评估。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[热电联产系统阻力增强与风险评估]: 由结合气象数据的物理信息驱动模型实现"]},{"i":41243,"as":"提出一种改进的ImageTime框架，用于生成每小时多站点光伏发电场景，涉及时空预测技术在新能源发电领域的应用。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[每小时多站点光伏发电场景生成]: 采用改进的ImageTime时空预测框架"]},{"i":41244,"as":"介绍一种基于增强条件扩散模型的概率净负荷预测方法，研究重点为利用深度学习提升电力系统负荷预测的准确性。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[电力系统概率净负荷预测]: 采用增强条件扩散模型提升准确性"]},{"i":41245,"as":"分析特定技术指标在脱碳过程中的应用，探讨如何通过这些技术手段及早发现和识别系统脱碳环节的异常或故障。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[系统脱碳环节]: 通过特定技术指标及早发现和识别异常或故障"]},{"i":41246,"as":"","scd":null,"kp":[]},{"i":41247,"as":"","scd":null,"kp":[]},{"i":41248,"as":"","scd":null,"kp":[]},{"i":41249,"as":"","scd":null,"kp":[]},{"i":41250,"as":"吉西他滨治疗通过衰老相关分泌表型诱导胰腺导管腺癌细胞衰老并激活成纤维细胞，导致基质硬度增加。这种生物力学重编程激活机械敏感离子通道Piezo1，促使BRG1阳性肿瘤细胞依赖NRF2介导的抗氧化防御。Piezo1信号促进NRF2入核并与BRG1合作，上调SLC7A11依赖的抗氧化程序，从而抑制铁死亡并促进化疗耐药性。","scd":{"b":7.5,"i":3.5,"r":6.0,"d":6.5,"t":4.5},"kp":["[化疗耐药机制]: 吉西他滨诱导衰老并激活成纤维细胞，导致基质硬度增加并激活机械敏感离子通道Piezo1，引发代谢重排和抗氧化适应"]},{"i":41251,"as":"研究提出利用工程微生物联盟进行分布式信号处理的方法。通过将传感功能分布到微生物群落中，并结合动力学建模与机器学习的计算框架，可以解码群落的时间分辨集体响应。该方法无需消除传感器之间的串扰，即可实现对多种化学输入浓度的定量推断，有效解决了传统生物传感器需要繁琐正交化处理的问题。","scd":{"b":8.0,"i":3.5,"r":7.0,"d":6.0,"t":4.5},"kp":["[微生物联盟分布式信号处理]: 将传感分布到微生物群落中，无需消除串扰即可通过解码时间分辨的集体响应来推断多重输入信号浓度"]},{"i":41252,"as":"研究将工程酶级联整合至静息细胞中，并耦合醇氧化酶，开发出高效的酶-静息细胞级联系统用于甲醇转化。该系统能够将单一的C1甲醇分子定制化转化为L-赤藓酮糖（C4糖）或L-山梨糖（C6糖）。此工艺克服了生长细胞中非天然途径碳利用率低和催化稳定性受限的问题，展现出良好的催化效率和碳原子经济性。","scd":{"b":7.0,"i":3.5,"r":6.0,"d":6.5,"t":4.5},"kp":["[静息细胞生物催化]: 集成工程酶级联以实现单一碳一(C1)甲醇分子向稀有天然糖的转化","[生物制造策略]: 针对非天然途径碳利用率低和催化稳定性有限的问题，采用静息细胞工艺"]},{"i":41253,"as":"","scd":null,"kp":[]},{"i":41254,"as":"对带热能存储的太阳能驱动二氧化碳制冷系统进行动态建模，分析其在全生命周期内的能源、环境与经济效益。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[太阳能驱动吸附式过冷二氧化碳增压制冷装置]: 带有热能存储系统并支持动态建模与全生命周期评估"]},{"i":41255,"as":"","scd":null,"kp":[]},{"i":41256,"as":"对NASA OSIRIS-REx任务返回的小行星Bennu样本进行了岩相学、氧同位素和26Al–26Mg年代学表征。所有难熔包体均较小，形成于太阳系演化的最早阶段，且与Ryugu样本和球粒陨石中的难熔包体具有遗传亲和力。这种共享特征表明早期形成的内盘固体发生了广泛的外向运输和混合。目前分析的Bennu样本中未发现大型（亚毫米级以上）难熔包体。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":7.0,"t":7.0},"kp":["样本来源[小行星贝努(OSIRIS-REx任务)]: 主要成成为水蚀变产物，同时保留稀有的高温难熔包体","[难熔包体特征]: 尺寸微小，26Al–26Mg同位素体系显示其形成于太阳系演化最早期且与难熔物质具遗传亲和性"]},{"i":41257,"as":"针对缺血性脑卒中，研究开发了一种基于双重修饰透明质酸的可注射水凝胶，用于持续递送外泌体-氧化铈纳米复合物（EXO@CeO2）。在氧糖剥夺模型中，EXO@CeO2有效清除活性氧（ROS），减少细胞凋亡并稳定线粒体膜电位。同时，它通过下调促炎细胞因子（IL-1β、IL-6）和上调抗炎因子IL-10来调节炎症微环境，展现出促血管生成的双重功能治疗效果。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["水凝胶载体[脑梗死治疗]: 基于双修饰透明质酸的可注射水凝胶，用于持续递送外泌体-氧化铈纳米复合物","[靶向治疗机制[缺血性脑卒中]: 调节病理脑微环境，改善缺血再灌注后的氧化应激、神经炎症和神经损伤"]},{"i":41258,"as":"研究揭示了铯离子（Cs+）在预嵌入钾离子（K+）的Ti3C2TX中的竞争嵌入机制。K+预嵌入扩大了层间距，降低了Cs+的扩散势垒；而Cs+凭借更大的离子半径和更强的静电作用，竞争性取代大部分K+，进一步增大并稳定了层间距。将所得的K+/Cs+-Ti3C2TX集成到3D导电水凝胶中，有效抑制了材料的重新堆叠，显著提升了锌离子混合超级电容器的性能。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["嵌入策略[MXene层间结构调节]: 顺序进行K+和Cs+双重嵌入，其中K+预嵌入可扩大层间距并降低后续Cs+嵌入的扩散势垒","阳离子竞争机制[Ti3C2TX还原氧化石墨烯水凝胶]: 阐明了K+与Cs+在主体材料中的竞争性嵌脱行为及其对锌离子混合超级电容器性能的增强机制"]},{"i":41259,"as":"基于密度泛函理论（DFT）和非平衡格林函数（NEGF）方法，研究构建了部分倒置的Janus MoSSe纳米带同质结构。不对称的硫族元素层产生的内在应变促使自发皱纹的形成，这降低了形成能并打破了初始扁平结构的空间对称性。这种独特的物理特性为调节光电性能和设计柔性器件提供了额外的自由度。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["结构应变特征[二维Janus MoSSe同质结]: 不对称硫族元素层产生本征应变，驱动材料自发卷曲、折叠和起皱","[部分倒置同质结光电器件]: 提供额外自由度以调制光电特性并设计柔性光电器件"]},{"i":41260,"as":"研究电-氢-气一体化系统的低碳调度问题，涉及考虑协调线路组与罐车效应的综合能源系统优化运行与调度策略。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":4.0,"t":5.0},"kp":["[电-氢-气一体化系统]: 低碳调度需考虑协调线路组与罐车效应的优化运行策略"]},{"i":41261,"as":"最新研究发现，在亚千电子伏特（sub-keV）极低能量区间，凝聚态物质中的环境可显著改变核聚变速率。研究人员利用结合电化学充氘与低能离子束轰击的双腔实验平台，观察到钯和钛氢化物金属箔中的氘-氘聚变在2 keV以下呈现出明显的产额平台。这与传统理论预期的低能聚变概率呈指数级锐减截然不同。在最低测量能量下，其聚变产额较无屏蔽裸核预期值增强了超过10的18次方倍。该研究揭示了一种此前未被认知的固态低能核反应新机制，证明了固态材料的电子与结构环境能极大提升极低能量下的核聚变反应率。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":7.0,"t":8.0},"kp":["反应产率特征[亚千电子伏特(keV)能区氘-氘聚变]: 在2 keV以下表现出明显的非零反应产率平台(有限产率底限)","[凝聚态环境核聚变]: 金属箔片内的电子与结构环境深刻改变了反应核的聚变速率，克服了亚keV下极低的聚变概率"]},{"i":41262,"as":"针对传统电子集成电路能效受限的问题，研究提出一种基于硅基集成光学的可重构计算架构。与以往仅限于基本逻辑门或孤立计算模块不同，该光学子芯片成功实现了多功能算术逻辑计算原语。该技术利用集成光子学的高带宽和超低延迟优势，有效克服了在光子芯片上构建可重构多计算功能系统所面临的挑战。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["核心器件[集成光子学]: 可重构光学算术逻辑单元","[技术优势(光电数字计算)]: 相比传统电子数字方案，在运行速度和能效方面具备固有优势，突破摩尔定律能耗瓶颈"]},{"i":41263,"as":"受自然结构（如珍珠层）启发的复合材料往往表现出高度的各向异性，易在特定载荷下发生突然断裂。研究发现Raphia hookeri种子的独特结构具有多方向弱各向异性的抗裂纹性，这源于其紧密结合的等径细胞和互锁的纹孔。受此启发，研究人员通过组装具有凹坑的聚甲基二丙烯酸甲酯-石墨烯微球层并交织，成功制造出弱各向异性的纳米复合材料。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["断裂阻力[酒椰仁果种子仿生纳米复合材料]: 表现出在多方向上的弱各向异性，避免了高长径比结构单元在特定载荷下的突然失效","[仿生结构设计]: 模仿酒椰仁果种子的独特结构，克服了珍珠质、骨骼等传统仿生材料力学各向异性严重的挑战"]},{"i":41264,"as":"研究提出一种基于法布里-珀罗微腔集成MoS2光电探测器阵列的仿生光电推理架构。该架构在每个像素内统一了感测、加权和累加功能。微腔工程化的波长选择性在光谱域内编码神经网络权重，而MoS2有限的载流子寿命则实现了模拟时间积分。该设计将光谱感测与计算紧密结合，大幅减少了传统光电视觉硬件中的数据移动延迟和能耗。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":6.0},"kp":["神经形态推理架构[微腔MoS2光电探测器阵列]: 生物启发的光电推理架构，将频谱感知与计算紧密耦合","[硬件性能优化(波长编码神经形态计算)]: 以最小化数据移动提取任务相关信息，解决传统视觉硬件光探测与电子计算分离导致的高延迟与高能耗瓶颈"]},{"i":41265,"as":"研究利用超导铝纳米弦作为SQUID一臂并连接微波谐振器的磁通介导腔光力学平台，探测超导纳米弦谐振器中阿布里科索夫涡旋的进入过程。在约85 mK的温度和0.25 mT的面内磁场分辨率下，系统观察到了机械共振频率的离散跳跃，这与单个或少数单量子化阿布里科索夫涡旋的随机进入相一致。这些涡旋的位置导致机械弹性特征发生明显位移。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["探测平台[阿布里科索夫涡旋引入研究]: 由悬浮超导铝纳米弦构成SQUID一臂并端接微波谐振器的磁通介导腔光力学平台","[表征方法[超导纳米弦谐振器]: 利用腔光力学中的位移噪声光谱解决并探测阿布里科索夫涡旋的进入与钉扎问题"]},{"i":41266,"as":"研究开发了一个基于乳液液滴和两亲性三嵌段共聚物（BCP）的简易平台，成功在合成材料中重现了生物形态发生过程。液滴在BCP作用下发生可逆的形状变换和拓扑转变，导致自发且非选择性地内化周围的水相及悬浮胶体物质。在平衡状态下，BCP的界面自组装与液滴溶胀相结合，稳定了一系列非球形的多变形态结构。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[形态发生胶体合成平台]: 乳液液滴暴露于两亲性三嵌段共聚物中可重现生物形态发生的可逆形变与拓扑转变"]},{"i":41267,"as":"研究提出基于强金属-载体相互作用（SMSI）的策略，合成热稳定和电化学稳定的高价铱单原子催化剂，用于提升固体氧化物电解池（SOEC）中的高温CO2电解性能。高温下原位诱导的SMSI效应不仅稳定了高价铱单原子，还通过削弱Fe-O杂化作用调节了LSF阴极的表面电子结构，从而促进了氧空位的形成，显著增强了CO2的吸附和活化能力。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["催化剂[固体氧化物电解池高温CO2电解]: 强金属-载体相互作用(SMSI)诱导的高价铱单原子","[高温抗降解策略]: 电池制造与运行过程中原位诱导SMSI效应以防止单原子聚集与退化"]},{"i":41268,"as":"研究在锰铋碲锑（Sb掺杂的MnBi2Te4）上进行了原子级分辨的锡薄膜生长实验，揭示了两种根本不同的生长动力学机制之间的动态交叉。早期生长遵循Villain-Lai-Das Sarma标度，形成二维岛屿和锡烯层。超过临界沉积时间后，时间相关噪声成为主导因素，驱动α-Sn团簇成核及其生长。这为非平衡系统中的动力学演变提供了直接的实验证据。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[非平衡系统生长动力学]: Sb掺杂MnBi2Te4上Sn薄膜的外延生长呈现由时间相关噪声驱动的KPZ普适类动力学交叉"]},{"i":41269,"as":"研究提出在复合材料多模态表征中引入“序数性”作为核心原则，并构建了ORDinal-aware imagE-tabulaR（ORDER）对齐框架。该方法将微观结构与表格形式的材料描述符相融合，并利用基于物理的代理信号消除了对全属性标注的依赖。ORDER确保了相似目标特征的准确整合，有效解决了传统多模态学习方法难以在数据稀缺下建模连续且非线性的复合材料设计空间的难题。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[多模态人工智能设计框架]: 引入序数性核心原则构建复合材料的多模态表示，以解决连续且非线性设计空间中的数据稀缺问题"]},{"i":41270,"as":"为实现高性能可持续热电技术，研究建立了一种连接宏观连接工程与微观界面调制的跨尺度界面中心设计策略。以n型Mg3(Sb, Bi)2为代表体系，将Mg2Ni转化为跨尺度界面相。该界面相在形成低接触电阻和热稳定的外部结的同时，作为内部界面改性剂，有效缓解了晶界载流子散射，显著增强了器件的稳定性和热电转换效率。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[热电器件跨尺度界面设计策略]: 融合宏观结工程与微观界面调制实现低品位废热回收的高性能与高耐久性","代表性热电材料体系[n型热电]: Mg3(Sb, Bi)2"]},{"i":41271,"as":"施加门电压可猝灭超导纳米线中的超导电流（GCS效应）。研究发现，GCS效应同样表现为迈斯纳效应屏蔽的抑制，证明了该现象是超导体的固有特征。在低于1开尔文的温度下，使用扫描氮-空位（NV）磁力计对微米级铌岛中的GCS抑制区域进行纳米级成像。观测结果与准粒子产生和扩散的微观热点模型相符，排除了焦耳热等其他机制。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":6.0},"kp":["[超导门控效应]: 门控电压不仅抑制超导纳米线超流，还通过扫描氮-空位(NV)探针证实其显著压制了迈斯纳屏蔽效应"]},{"i":41272,"as":"近期在莫尔材料中发现了陈数C=1的拓扑非平庸能带部分掺杂下的分数量子反常霍尔效应。研究提出了一种扭转角约为1.2°的扭曲菱面体三层-双层石墨烯，可作为场效应可调的量子反常陈绝缘体。该材料具有光谱孤立、动力学猝灭且拓扑非平庸的能带，其陈数为C=2或3，在分数掺杂状态下有利于形成非阿贝尔准粒子的奇异分数量子态。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["拓扑能带陈数[扭曲菱面体三层-双层石墨烯体系]: C > 1","[摩尔超晶格电子状态]: 库仑相互作用稳定的孤立窄带，可打破朗道能级范式并可能产生非阿贝尔奇异分馏态"]},{"i":41273,"as":"静态转换型溴化物电池具有高电压和大容量的潜力，但受限于双电子转移反应和不含氧化还原活性的有机配体。研究开发出一种基于乙基紫精二溴化物的有机锂-溴电池正极材料，通过配位化学与插层和转换反应，实现了先进的六电子氧化还原机制。该机制激活了2Br-/2Br+氧化还原对，使电池比容量达到632.8 mAh g−1Br，放电电压提升至3.7V。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["电子转移数[有机锂溴电池]: 六电子转移(基于可逆高价溴氧化还原反应)","正极电极材料[锂溴电池配位电化学驯化]: 乙基紫精二溴化物"]},{"i":41274,"as":"硅作为下一代锂离子电池负极材料具有超高理论容量，但面临体积膨胀、锂离子传输缓慢及固体电解质界面（SEI）不稳定等问题。受细胞膜结构启发，研究通过原位形成共轭微孔热固性（CMT）涂层，在硅颗粒表面构建了保护性界面。该过程只需将分子前驱体与硅手工混合，并通过升华、熔化等热处理步骤即可完成，为解决硅负极缺陷提供了简便且可规模化策略。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[硅负极界面改性策略]: 构建受细胞膜启发的共轭微孔热固性界面，以适应体积膨胀并实现高倍率与耐用性"]},{"i":41275,"as":"扭曲石墨烯异质结的平带电子结构可用于探索相关与拓扑量子相。除了扭曲角度，六方氮化硼（hBN）衬底的晶格对齐也是打破对称性和重建能带结构的关键参数。在由对齐的hBN层封装的扭曲双双层石墨烯（TDBG）中，观察到了可调谐的扩展非费米液体行为。该非费米液体相出现在相关平带的空穴掺杂侧，展现了晶格对齐在调控量子相变中的关键作用。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[对称性破缺机制]: 六方氮化硼衬底的晶格对齐是打破对称性并重构扭曲双层石墨烯能带结构的关键参数，可诱发扩展磁性非费米液体相"]},{"i":41276,"as":"通过合理结构设计精确调控钯的d带中心具有重大技术潜力。研究开发出中熵非晶合金单原子钯纳米片，利用中熵合金化、单原子配位及亲氧性Cr/Mo/W修饰的协同效应，将钯的d带中心调节至最优值。该催化剂在氧还原反应（ORR）和乙二醇氧化反应（EGOR）中表现出卓越的质量活性，分别达到2.15和15.19 A mg⁻¹。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["催化剂[直接乙二醇燃料电池]: 中熵非晶合金单原子钯纳米片"]},{"i":41277,"as":"快速识别高玻璃形成能力（GFA）合金成分是发现新型金属玻璃的主要瓶颈。研究发现，热退火引起的电阻率变化可以作为描述结晶抵抗能力的稳健参数。通过包含约3500种合金成分的组合薄膜库，揭示了明确的成分图谱，其中电阻率变化最小的区域恰好对应具有高GFA的合金。这一趋势与结晶动力学参数直接相关，为高GFA合金成分识别提供了新方法。","scd":{"b":6.5,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["描述符[金属玻璃形成能力]: 结晶时电阻率的变化"]},{"i":41278,"as":"全硅太赫兹互连是下一代片上通信的关键平台。针对以往数据传输率低和色散影响缺乏系统研究的问题，研究展示了一种全硅宽带低色散太赫兹光子晶体波导互连器件。该器件的群速度色散（GVD）低至2.9 ps²/mm，通过七个数据通道成功传输了高达452 Gbps的复杂调制数据，总数据率超过400 Gbps。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":8.0,"t":5.0},"kp":["总数据率[超低色散硅太赫兹光子晶体互连]: >400 Gbps"]},{"i":41279,"as":"准确监测致癌挥发性芳香烃（BTXs）对于评估空气质量至关重要，但在复杂环境中实现高选择性识别极具挑战。研究开发了一种气体分流策略，将功能反转的ZnO材料安装到Ir-WO₃支撑体中。在该机制中，ZnO作为小分子硫化氢和一氧化碳的牺牲反应位点，有效减少了干扰气体的响应，同时引导特定的芳香烃反应物进入Ir-WO₃支撑体，从而实现复杂环境下的选择性检测。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["气体检出策略[挥发性芳香烃监测]: 气体分流及安装功能反转ZnO材料"]},{"i":41280,"as":"","scd":null,"kp":[]},{"i":41281,"as":"定制化3D陶瓷电子器件因其优异的导热、导电和机械性能备受关注。研究提出了一种结合数字光处理和原位激光激活化学镀的混合增材制造方法，用于制造高精度3D陶瓷电子器件。该技术首先使用含有低温共烧陶瓷和氧化锑锡（ATO）的光敏聚合物进行3D打印和烧结。随后，利用激光原位选择性激活烧结后的陶瓷表面的ATO，成功制备出高分辨率3D陶瓷电子器件。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["制造工艺[3D陶瓷电子器件]: 数字光处理结合原位激光激活选择性化学镀的混合增材制造"]},{"i":41282,"as":"","scd":null,"kp":[]},{"i":41283,"as":"非手性共轭聚合物的手性组装为优化光电性能提供了新途径。研究通过溶致液晶（LLC）组装路径，建立了一个将溶剂特性与聚集体结构和超分子手性联系起来的统一框架。研究揭示了两种溶液聚集类型：一是具有弱链间耦合和扭转骨架的纤维状β1聚集体，通过形成螺旋纤维促进LLC介导的手性组装；二是以特定结构为特征的β2聚集体。","scd":{"b":6.5,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["组装机制[OEG官能化共轭聚合物]: 溶剂引导手性组装与化学掺杂"]},{"i":41284,"as":"锂金属电池的凝胶聚合物电解质在机械强度和离子电导率之间存在固有权衡。研究利用竞争性氢键相互作用，在深共晶凝胶电解质中自发形成纳米级相分离结构。通过在含有三氟甲基官能化深共晶溶剂中一步原位共聚丙烯酰胺和N,N-二甲基丙烯酰胺，构建了刚性聚合物互穿网络，在固态锂金属电池中实现了机械强度和离子电导率的同步提升。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["电解质[固态锂金属电池]: 氟化深共晶凝胶电解质","微结构[DEG电解质]: 纳米级相分离结构"]},{"i":41285,"as":"氟化溶剂在高温下易引发寄生界面反应，在低温下会导致锂盐沉淀。研究基于分子几何形状和电子密度分布的协同优化，提出了一种无氟溶剂设计策略。合成的溶剂2-乙酸乙酯（2EA）通过引入大量空间位阻和调节分子间相互作用及Li⁺配位，成功构建了超宽温域锂金属电池无氟电解液，使其在-105°C至70°C的极端温度范围内稳定工作。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":8.0,"t":5.0},"kp":["工作温度[锂金属电池无氟溶剂]: -105°C至70°C","设计策略[无氟电解质]: 基于分子几何与双描述符的协同优化"]},{"i":41286,"as":"在软智能系统中解耦空间不同轴向的叠加力向量是实现人工体感的前提。针对聚合物压电复合材料中随机分布纳米填料导致宏观各向异性丧失和无法区分力向量的问题，研究通过场编程各向异性将力模式选择性编码到磁-压电复合材料中。基于严格的扭矩平衡框架，实现了装饰有Fe₃O₄的BaTiO₃纳米颗粒在空间上的确定性排列，赋予了材料机械感知编码能力。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["材料特性[磁压电复合材料]: 场编程各向异性"]},{"i":41287,"as":"光催化产生羟基自由基（•OH）是灭活水中耐药细菌的有效绿色途径，但缓慢的逐步单电子氧还原路径限制了其效率。研究采用原子级设计策略，将不对称的Zn─N₃O₁单原子位点锚定在超薄石墨相氮化碳纳米片上。这种不对称结构加速了电子转移，有效促进了•OH的生成，实现了在自然光驱动下对耐药细菌的高效灭活。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["催化位点[自然光驱动产羟基自由基]: 不对称Zn-N3O1单原子位点"]},{"i":41288,"as":"无滤波器的偏振分辨光电探测器受限于半导体固有的低吸收各向异性。研究引入了偏振敏感载流子动力学（PSCD）设计原理，将偏振识别从静态吸收各向异性转移到光生载流子随时间的演变上。通过将分子级厚度的p型有机单晶集成到具有二维共晶有机框架浮栅的非易失性浮栅光电晶体管中，正交线偏振光产生不同的光生速率，进而诱导出截然不同的载流子动力学行为，将微小的光学各向异性放大为巨大的线性二向色性。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["偏振分辨光电探测[无滤光片]: 偏振对比度突破半导体固有的低光学吸收各向异性限制","偏振敏感载流子动力学[PSCD设计原理]: 将偏振甄别从静态吸收各向异性转移到光生载流子种群的时间演化上"]},{"i":41289,"as":"在合成材料中实现具有纳米级排列和预期形态的多尺度分级结构极具挑战。研究引入了一种基于DNA的自下而上组装策略，利用DNA折纸框架作为模块化单体，通过可寻址的DNA结合基序引导各向异性外延生长，并成功在3D图案中包裹纳米颗粒。该策略从纳米晶格构建出多种多壳层介观形态，实现了具有特定结构和成分的定制化三维材料组装。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["组装策略[DNA基自组装]: 构建具有规定纳米级排列和所需材料形态的跨尺度多壳中尺度形态"]},{"i":41290,"as":"水系铝离子电池在长循环中面临Al³⁺强溶剂化和氧化物钝化层导致界面电荷转移动力学迟缓的问题。研究提出一种以三氯乙醇（TCE）为添加剂的氯化物桥接策略。TCE在电解质/电极界面自组装形成富含氯化物桥的分子层，重塑了双电层结构。该结构不仅加速了界面电荷转移动力学，还促进了铝的均匀沉积，从而显著提升了电池性能。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["双电层重塑[水系铝离子电池]: 采用三氯乙醇(TCE)添加剂构建氯桥策略，打破Al3+强溶剂化及钝化氧化层界面电荷转移动力学阻碍"]},{"i":41291,"as":"","scd":null,"kp":[]},{"i":41292,"as":"研究建立了菱方相3R-MoS2作为多功能光子学平台。与中心对称的2H相不同，3R-MoS2在块体状态下保持反演对称性破缺，实现了可扩展的二阶非线性。研究表明，3R-MoS2具有与之前假设不同的线性特性，展现出巨大的光学各向异性。该材料成功结合了主动非线性频率转换与被动亚衍射光引导，解决了光子电路微型化的阻碍。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["多功能光子学平台[3R-MoS2]: 具有巨大各向异性和高二阶非线性，打破光子电路微型化中有源非线性频率转换与无源亚衍射光限制难以结合的瓶颈"]},{"i":41293,"as":"研究开发了一种环保且可持续的工艺，用于制造高强度农业再生纤维素纤维。该工艺使用一种新型酸性低共熔溶剂系统，从农业废弃物中选择性提取纤维素。针对农业纤维素聚合度低的特点，研究人员提出了拉伸诱导取向和空间限域策略，实现了高性能农业再生纤维的可扩展制备。该技术为可再生生物质资源的高价值利用提供了有效途径。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":4.0,"t":4.0},"kp":["纤维制造[农业再生纤维素]: 提供克服生物质固有抗解聚结构和低聚合度限制的绿色、可扩展生态高效策略"]},{"i":41294,"as":"研究对比了三种基于扫描探针技术的功函数定量测量方法：谱学、场发射共振（FER）和开尔文探针力谱（KPFS）。研究发现这些方法具有极强的依赖性：谱学由于数据分散仅适用于平坦表面；三角势垒FER外推法稳健性不足，而基于像势校正薛定谔模型的数值FER分析能提供一致结果；KPFS在探针校准后能提供最直接可靠的测量。该方法已成功应用于超导铌的功函数提取。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["测量精度[扫描隧道谱仪(STS)]: 因数据离散度大而存在显著不确定性，仅在平坦表面上可靠","测量精度[三角势垒场发射共振(FER)]: 可提取局部功函数，适用于多种表面"]},{"i":41295,"as":"探索用于单锂离子传导的金属氧化物簇材料，研究重点在于利用表面封闭水技术提升相关电化学储能材料的性能。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[金属氧化物簇单锂离子传导]: 利用表面封闭水技术提升电化学储能材料性能"]},{"i":41296,"as":"研究开发了一种全固态、无掩模电沉积工艺，利用聚合物电解质膜（PEM）印模在柔性基底上直接制造多尺度银图案。银离子由银阳极/PEM界面的阳极溶解提供，并通过PEM中的纳米级水通道进行传输。该自下而上的方法克服了传统光刻工艺材料消耗高和环境负担大的缺点，以及传统自下而上方法图案分辨率不足的局限，在光电器件和柔性传感领域具有应用潜力。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["电沉积制造[银微结构]: 采用聚合物电解质膜印模实现全固态、无掩模的自下而上直接成型，解决传统高耗能与图案化分辨率不足问题"]},{"i":41297,"as":"针对阴离子交换膜水电解制氢技术进行系统级综合建模，旨在通过模型优化提升整体电解系统的制氢效率。","scd":{"b":4.0,"i":2.0,"r":3.0,"d":3.0,"t":4.0},"kp":["[阴离子交换膜水电解制氢]: 进行系统级综合建模以优化并提升整体制氢效率"]},{"i":41298,"as":"构建基于贝叶斯学习代理的模型，研究并优化房主协会供暖系统脱碳的智能决策过程。","scd":{"b":3.0,"i":2.0,"r":3.0,"d":3.0,"t":4.0},"kp":["决策模型[房主协会供暖系统脱碳]: 基于贝叶斯学习代理的模型"]},{"i":41299,"as":"开发定频家用空调的切换感知模型预测控制解决方案，旨在提升设备运行效率与温控性能。","scd":{"b":4.0,"i":3.0,"r":3.0,"d":3.0,"t":4.0},"kp":["控制方案[定频家用空调]: 切换感知模型预测控制解决方案"]},{"i":41300,"as":"探讨结合氢混合技术的海洋能源系统设计，评估其在运行中的设备退化与整体使用寿命。","scd":{"b":5.0,"i":2.0,"r":3.0,"d":3.0,"t":4.0},"kp":["[氢混合海洋能源系统]: 退化感知设计与使用寿命评估"]},{"i":41301,"as":"提出基于动态可行操作区域聚合的优化调度方法，用于实现类存储虚拟资源的协调控制。","scd":{"b":4.0,"i":2.0,"r":3.0,"d":3.0,"t":4.0},"kp":["调度方法[类存储资源协调优化]: 基于动态可行操作区域聚合"]},{"i":41302,"as":"研究医疗废物等离子体气化及综合处理策略，建立鲁棒优化模型以提升废物处置效率。","scd":{"b":5.0,"i":2.0,"r":3.0,"d":3.0,"t":4.0},"kp":["优化模型[医疗废物等离子体气化]: 结合其他废物处理的鲁棒优化策略"]},{"i":41303,"as":"探讨电驱动可持续航空燃料的综合工艺设计，并对其进行技术可行性与经济性评估。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[电驱动可持续航空燃料]: 综合工艺设计与技术经济性评估"]},{"i":41304,"as":"研究互联能源社区间的双重共识电力市场协调机制，以实现去中心化的隐私保护与民主交易。","scd":{"b":3.0,"i":2.0,"r":3.0,"d":3.0,"t":4.0},"kp":["协调机制[互联能源社区]: 双重共识电力市场","技术特征[去中心化电力交易]: 隐私保护与民主化交易"]},{"i":41305,"as":"研究在ITO/玻璃基底上制备了无铅双钙钛矿Cs2AgBiBr6忆阻器，并使用热蒸发银作为顶部电极。器件表现出稳定的低压（+0.239 ± 0.018 V）易失性电阻开关特性，具有极佳的循环重复性。在24次循环中保持超过10^5的最大开关比，在1100次循环中开关比保持在10^2以上。电学分析表明，开关行为由离子迁移诱导的灯丝形成控制，主要涉及可移动的Br-离子、VBr+空位和电极注入的Ag+离子。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["开启电压[Cs2AgBiBr6无铅双钙钛矿忆阻器]: +0.239 ± 0.018 V"]},{"i":41306,"as":"研究预测单层Fe3O5具有混合自旋劈裂机制，结合了交磁性的k路径交替自旋劈裂和亚铁磁性的塞曼劈裂。这种具有极低磁化但显著非相对论自旋劈裂的非常规共线磁体，通过引入铁电性和电荷有序化增加了功能化自由度。基于自旋-电荷耦合的隐藏磁电效应，其自旋劈裂可完全由电场切换。该材料具有高度自旋极化的导电性，并在极化比率上表现优异。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["磁性状态[Fe3O5单层]: 预测展现混合自旋劈裂机制，叠加铁电性和电荷有序实现铁电可开关的交变磁样补偿铁磁体"]},{"i":41307,"as":"研究开发了一种超分子结晶种子策略，通过在D18/L8-BO系统中引入末端羟基、高结晶度的受体（Y-OH），优化有机太阳能电池的形貌和长期稳定性。通过构建分级热力学兼容性梯度，Y-OH在多组分薄膜中表现出界面分布倾向。原位紫外-可见光谱测量表明，Y-OH的时间尺度更接近供体，参与初始形态演化并引导随后的组织过程，有效协调了供体-受体的结晶顺序。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["热力学相容性梯度[D18/L8-BO有机太阳能电池体系]: χD18/Y-OH > χL8-BO/Y-OH > χD18/L8-BO","结晶种子[Y-OH羟基封端高结晶受体]: 诱导原纤维细化，实现最佳形貌和长期稳定性"]},{"i":41308,"as":"研究提出了一种手性导向策略，通过客体介导的手性控制实现了Pt6L4配位胶囊中可编程螺旋度和自旋极化的调节。该策略将(R)-1,1'-联-2-萘酚的手性转移到胶囊中以诱导螺旋度，随后通过主客体相互作用引入(R)-1,1'-联萘酚-2,2'-二基磷酸酯实现受控的螺旋反转。磁圆二色性揭示了依赖于手性的电子态变化，磁导原子力显微镜证实了自旋选择性的电荷传输，实现了对CISS效应符号可逆控制。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[手性诱导自旋极化控制策略]: 将(R)-1,1'-联-2-萘酚手性转移到八面体胶囊中，实现螺旋度的可编程和可逆控制","[分子胶囊结构]: Pt6L4配位胶囊"]},{"i":41309,"as":"研究合成了六对手性3d-4f分子簇：R/S-Ln3Mn4和R/S-Ln12Mn12（Ln = HoIII, TbIII, YIII），并系统研究了它们在近红外三区（1600-2500 nm）的光学特性。圆二色性和磁圆二色性光谱显示，R/S-Ho3Mn4和R/S-Ho12Mn12簇由于长波长HoIII f-f跃迁，在NIR-III区表现出明显的圆二色性和磁圆二色性响应。该研究填补了NIR-III光谱窗口分子磁光现象的研究空白。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":7.0,"t":7.0},"kp":["光学响应波段[NIR-III磁光活性的3d-4f团簇]: 1600-2500 nm","[手性分子团簇组成]: R/S-Ln3Mn4 和 R/S-Ln12Mn12 (Ln = HoIII, TbIII, 和 YIII)"]},{"i":41310,"as":"研究采用双硫键介导的保护策略，在同一合成系统中成功分离出六种不同的铜纳米团簇（Cu12、Cu23-a、Cu23-b、Cu25-a、Cu25-b和Cu61）。通过精确调节反应温度和时间，严格控制了体系内的生长动力学。单晶X射线衍射分析表明，六聚体Cu3S3和八聚体Cu4S4环作为通用模块，包裹着明确的金属核心来主导结构的演化，实现了铜纳米团簇结构演化的原子级晶体学可视化。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[铜纳米团簇结构演化调控保护策略]: 二硫化物介导的保护策略","[分离出的团簇类型]: Cu12, Cu23-a, Cu23-b, Cu25-a, Cu25-b, 和 Cu61"]},{"i":41311,"as":"研究开发了一种活体内化学发光策略，利用分子氧作为直接反应物进行[2+2]分子间光环加成反应，在活体系统内原位生成高能量的1,2-二氧杂环丁烷。设计的供电子基团取代的烯烃提供了氧气特异性结合位点，并通过生物限制催化使中间体寿命延长了25倍（经飞秒瞬态吸收光谱证实）。这一全新设计的化学发光体成功解决了活体应用中缺乏生物相容性策略生成高张力环状过氧化物的难题。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[体内化学发光光环加成反应]: [2 + 2]分子间光环加成","[高能发光核心原位生成方式]: 利用分子氧作为直接反应物原位生成高能1,2-二氧杂环丁烷"]},{"i":41312,"as":"研究设计了具有互补功能的异核Rh-La双原子位点用于乙醇蒸汽重整（ESR）制氢。该催化位点通过电子金属-载体相互作用构建，其中Rh控制C-C键活化和碳中间体转化，而La则促进水的活化。这种设计有效克服了ESR过程中C-C断裂与水活化之间动力学耦合无效导致的副反应和催化剂失活问题，实现了复杂反应中基元步骤的动力学匹配，优化了可持续氢气生产。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[乙醇蒸汽重整制氢催化剂]: 异核Rh-La双原子位点催化剂"]},{"i":41313,"as":"对声诺触发级联乳酸消耗的半导体聚合物纳米反应器在胰腺癌免疫治疗中应用的研究进行更正。","scd":null,"kp":["纳米反应器[胰腺癌免疫治疗]: 声诺触发级联乳酸消耗的半导体聚合物"]},{"i":41314,"as":"研究引入环状三偏磷酸根离子（P3O9^3-）作为网络形成单元，通过简便的机械化学合成法构建了一系列新型非晶态卤氧化物固态电解质。P3O9^3-独特的九氧供体结构能够与金属离子形成坚固的三维配位网络。该材料成功结合了快速Na+传导、高压稳定性和可变形性，为全固态钠离子电池（ASSNIBs）固态电解质的设计提供了突破性方案。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":8.0,"t":7.0},"kp":["[全固态钠离子电池非晶超离子导体网络形成体]: 环状三偏磷酸根阴离子 (P3O9^3-)"]},{"i":41315,"as":"为了解决ITER托卡马克装置面临的侧向力预测高度不确定性（范围在2至60兆牛顿之间，上限可能超过48兆牛顿的设计极限并限制运行）的问题，ITPA组织于2018年启动了MDC-25联合实验。尽管取得了一定进展，但最新发现表明仍需在专用线性装置上进行补充研究，文章据此提出了“Halo装置”的概念设计，专门用于应对侧向力相关问题，避免影响ITER的最终聚变性能。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["侧向力预测范围[ITER壁]: 2至60 MN","[ITER壁侧向力设计阈值上限]: 48 MN"]},{"i":41316,"as":"使用新安装的螺旋线圈（外部旋转变换线圈）在等离子体表面小半径a=22厘米处产生了最大234高斯的m/n=2/2共振磁扰动（RMP）。130高斯的RMP场强足以穿透q=1表面，在边界安全因子qa高达4.3、电子密度ne更高的条件下形成2/2磁岛。该2/2 RMP比J-TEXT托卡马克先前的鞍型RMP线圈产生的扰动强约8倍，成功将锯齿振荡的控制范围扩展至更高的电子密度和边界安全因子范围。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[抑制锯齿振荡的磁扰动模式]: m/n = 2/2 共振磁扰动","磁场扰动强度对比[新螺旋线圈产生的m/n=2/2 RMP]: 约为旧鞍型线圈产生RMP的8倍"]},{"i":41317,"as":"","scd":null,"kp":[]},{"i":41318,"as":"研究通过将CdSe-CdZnS纳米片发光体嵌入高折射率TiO2纳米圆柱中，在发光太阳能聚光器（LSC）波导几何结构中实现了各向异性发光体发射。通过优化单个纳米圆柱内的类米氏多极共振，改变了发光体的角度发射轮廓，增加了全内反射（TIR）角内的发射，从而增强了波导内的光捕获能力。该技术对需要控制光发射的光学系统（如LED、激光器）和需要光捕获的光伏系统具有重要意义。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[发光太阳能聚光器波导光捕获增强技术]: 在波导几何结构中嵌入各向异性发光体以控制其发射"]},{"i":41319,"as":"针对投影微立体光刻制造微针阵列时由于非线性光聚合动力学导致的翘曲和扭曲等缺陷，研究开发了一种光聚合动力学框架。该框架解耦了曝光强度与持续时间，通过自定义UMAT子程序将动态光衰减和聚合过程整合到多尺度有限元分析中。结果显示，极端的曝光时间或强度是有害的：前者引起过度固化和收缩，后者导致缺陷。该模型有效提升了从设计到制造的高保真度一致性。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[投影微立体光刻光聚合动力学框架]: 将曝光强度与持续时间解耦","[微针阵列制造工艺特点]: 高设计到制造的几何保真度"]},{"i":41320,"as":"研究开发了一种二维层状Lax@Ti3C2衍生催化剂，显著提升了Mg-4Ni-2Y合金的储氢性能。添加10 wt% La0.2@Ti3C2的复合材料将起始吸收和脱附温度分别降至23.3 °C和265.5 °C。该复合材料展现出卓越的动力学性能，在150 °C下1分钟内吸收4.80 wt%的氢气，在350 °C下4分钟内释放5.16 wt%的氢气。此外，脱氢表观活化能显著降至85.22 ± 2.38 kJ/mol，克服了镁基合金脱附温度高和动力学不足的障碍。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":7.0,"t":5.0},"kp":["催化剂[Mg-Ni-Y合金中温加氢]: Lax@Ti3C2衍生催化剂","复合材料组成[Mg-4Ni-2Y合金加氢]: Mg-4Ni-2Y + 10 wt% La0.2@Ti3C2"]},{"i":41321,"as":"","scd":null,"kp":[]},{"i":41322,"as":"","scd":null,"kp":[]},{"i":41323,"as":"为解决锌离子混合超级电容器中存在的锌枝晶、腐蚀和析氢等问题，研究人员引入生物质苹果酸（MA）作为水凝胶电解质添加剂和锌阳极的酸蚀刻剂。MA不仅将锌离子转移数从0.303提升至0.598，优化了Zn²⁺溶剂化结构并降低了去溶剂化能，还通过蚀刻在锌阳极表面诱导形成人工固体电解质界面（SEI）层。这种电解质优化与电极保护层协同构建的策略，显著增强了锌阳极的稳定性。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":7.0,"t":5.0},"kp":["水凝胶电解质添加剂[抑制锌枝晶与析氢]: 苹果酸 (MA)","协同调控机制[锌离子混合超级电容器]: 优化电解质组分并诱导形成人工固体电解质界面(SEI)层"]},{"i":41324,"as":"研究人员开发出一种基于聚丙烯酸/羟丙基纤维素/氯化铝（PAA/HPC/AlCl3）的物理交联多功能水凝胶。该网络仅由氢键和Al³⁺配位键构建，具备拉伸性、粘附性和可逆热致变色特性。通过冻融循环这种绿色物理策略调控性能，水凝胶的拉伸强度从0.11 MPa增至3.60 MPa，耗散能量提升至53.699 MJ·m⁻³。核磁共振表明冻融促进了水分重新分布和分子链聚集，在不引入化学交联剂的情况下强化了非共价相互作用，适用于柔性传感。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":7.0,"t":5.0},"kp":["网络交联键[物理交联PAA/HPC/AlCl3水凝胶]: 氢键和Al3+配位键","抗拉强度[冻融循环处理后]: 3.60 MPa","抗拉强度[冻融循环处理前]: 0.11 MPa"]},{"i":41325,"as":"为克服传统光电忆阻器光谱响应窄和易失性存储的限制，研究人员开发出一种基于氧化锌（ZnO，带隙3.2 eV）和二氧化钒（VO2，带隙0.6 eV）的双波段光电忆阻器。该器件结合了多波长传感与非易失性阻变双重功能，能够响应紫外和近红外光。电场可调节并重新分布ZnO和VO2中的离子，光生载流子增强了电荷积累并形成导电丝，且部分导电丝的增加得以保留，从而实现稳定的光电存储功能。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":7.0,"t":5.0},"kp":["带隙[氧化锌(ZnO)]: 3.2 eV","带隙[二氧化钒(VO2)]: 0.6 eV","光电功能[双波段光电忆阻器]: 多波长传感与非易失性阻变存储双重功能"]},{"i":41326,"as":"研究人员提出了一种高性能双波段紫外光电探测器，通过在热氧化生成的Ga2O3/GaN异质结上修饰银纳米颗粒构建而成。引入的Ag纳米颗粒产生局域表面等离子体共振（LSPR）效应，形成双重增益机制：通过局部场放大增强了日盲区（254 nm）的响应度，并通过热电子注入路径实现了低偏压下对近紫外光（365 nm）的高灵敏检测。该设计克服了宽禁带顶层材料对近紫外响应的限制，可应用于可重构逻辑、加密和紫外成像。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["器件架构[双波段紫外光电探测器]: Ag纳米颗粒修饰的热氧化Ga2O3/GaN异质结","Ag纳米颗粒引入方式[固态工艺]: 原位修饰"]},{"i":41327,"as":"针对柔性压力传感器难以同时实现高灵敏度和宽检测范围的问题，研究人员开发了一种具有微穹顶结构的MXene/PDMS复合压阻式传感器。通过原位光学显微镜和有限元分析阐明了微穹顶变形时界面接触面积的渐进演变机制。这种渐进式接触调制有效打破了灵敏度与量程之间的瓶颈。该传感器在低压区域实现了314 kPa⁻¹的极高灵敏度，并在宽检测范围内保持了稳健的传感性能，适用于颈椎姿势识别等应用。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["复合材料结构[柔性压阻传感器]: 微穹顶结构MXene/PDMS复合材料","传感机制[柔性压力传感器]: 界面接触渐进演变"]},{"i":41328,"as":"该研究提出一种界面工程策略，通过将钒掺杂二硫化钨（WS2-V）薄膜与多烷基环戊烷（MACs）凝胶结合，构建了超光滑且自适应的滑动接触界面以增强真空润滑。钒掺杂（约10 at.%）作为关键驱动因素，将WS2薄膜从多孔柱状结构转变为致密纳米复合材料，同时引入V-S物种增强界面相容性。该策略不仅改变了薄膜微观结构，还构建了化学性质活泼且机械强度高的界面，显著提升了摩擦系统的真空润滑性能。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["固液复合体系[真空润滑]: 钒掺杂二硫化钨(WS2-V)薄膜与多烷基环戊烷(MACs)凝胶协同","界面工程特征[滑动接触界面]: 构建超光滑且自适应的滑动接触界面"]},{"i":41329,"as":"研究GeTeC纳米复合薄膜的超低导热率特性，分析其在存储器和热电领域的潜在应用价值。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["导热率[GeTeC纳米复合薄膜]: 超低"]},{"i":41330,"as":"","scd":null,"kp":[]},{"i":41331,"as":"针对创伤后骨髓炎（PTO）中细菌生物膜和酸性病灶对药物递送系统的破坏，研究人员开发出一种耐酸的胺连接异孔共价有机框架（ARCOF）。通过还原胺化策略制备的ARCOF克服了传统COF化学稳定性与载药能力不足的矛盾。其设计的异质通道实现了万古霉素和抗生物膜剂非洛地平的协同负载。与磷酸钙水泥结合时，在炎症环境下这两种药物均可持续释放达240小时，在大鼠PTO模型中展现出显著的协同抗感染疗效。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["共价有机框架[创伤后骨髓炎治疗]: 胺连接的异孔ARCOF","化学稳定性[异孔共价有机框架]: 耐酸"]},{"i":41332,"as":"植物通过根系吸收、共生固氮和叶片衰老吸收三种策略获取氮。基于3193项实地观测和机器学习绘图，研究估算全球植物总氮获取量中，根系吸收占58%（559.2 Tg N/yr），共生固氮占13%（125.5 Tg N/yr），再吸收占29%（279.3 Tg N/yr）。这三种策略的全球变化主要受温度和水分条件决定。氮吸收在全球占主导地位（尤其在温暖湿润的低纬度地区），而当氮可用性下降时，叶片再吸收策略的贡献显著增加。","scd":{"b":5.0,"i":2.0,"r":7.0,"d":9.0,"t":5.0},"kp":["全球氮吸收量[植物根系吸收]: 559.2 ± 56.5","全球固氮量[共生固氮]: 125.5 ± 7.2"]},{"i":41333,"as":"","scd":null,"kp":[]},{"i":41334,"as":"为突破碱基编辑器尺寸过大无法被腺相关病毒（AAV）包装的限制，研究人员开发了由锌指蛋白（ZFP）增强的微型碱基编辑器。该技术整合了可编程的ZFP，提升了基于Un1Cas12f1和OgeuIscB的微型碱基编辑器的效率和靶向范围。研究还利用蛋白质语言模型优化了模块化组装设计的ZFP。工程化改造后的zmBE能够有效诱导SMN2外显子7的靶向突变，为基因治疗提供了新工具。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["碱基编辑器[人工智能优化]: 锌 finger蛋白增强的微型碱基编辑器(zmBE)","技术优势[微型碱基编辑器]: 提高编辑效率和靶向范围"]},{"i":41335,"as":"","scd":null,"kp":[]},{"i":41336,"as":"为了提升作物基因组预测的准确性，研究人员提出一种基于遗传算法的集成学习方法GEG2P，用于基因型到表型的预测。该方法整合了20个基础学习器，通过迭代优化策略动态选择组合，并利用遗传算法优化其权重。在玉米、小麦、水稻、鹰嘴豆等多种作物的实验中，与表现最佳的单个基础学习器相比，GEG2P平均将预测准确性提高了4.02%，有效解决了传统方法跨作物和性状预测性能不稳定的问题。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["预测模型[作物基因型到表型预测]: 基于遗传算法的集成学习方法(GEG2P)","基础学习器数量[GEG2P模型]: 20个"]},{"i":41337,"as":"为解决目标位点染色质分析工具受限的问题，研究人员开发了UNIChro-seq方法，能够数字化计数目标位点的可及性染色质分子。与常规方法相比，该方法在等位基因效应的定量上展现出高准确性、灵敏度和效率。利用UNIChro-seq，研究人员探究了57个自身免疫风险等位基因对染色质可及性的影响，并评估了20个通过基因组编辑产生的人工变体的因果效应，同时指出部分编辑的等位基因会对染色质可及性产生假阳性效应。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["UNIChro-seq方法[染色质可及性定量]: 数字化计数目标位点的可及性染色质分子","方法优势[目标位点等位基因效应分析]: 准确、灵敏且高效"]},{"i":41338,"as":"","scd":null,"kp":[]},{"i":41339,"as":"为替代不可降解的传统石油基粘合剂，研究人员利用工程化大肠杆菌合成了具有热稳定性和热熔粘合剂（HMA）特性的芳香族聚羟基脂肪酸酯共聚物：聚(4HB-co-PhLA)和聚(3HB-co-4HB-co-PhLA)。研究通过优化异源表达、引入额外的CoA转移酶以及时序调控基因表达，增强了细菌从葡萄糖合成聚合物的能力。计算机模拟被系统应用于识别工程化改造的靶点，成功开发出可作为可持续热熔粘合剂的生物基材料。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["共聚物类型[可持续热熔粘合剂]: 芳香族聚羟基脂肪酸酯(PHA)共聚物","材料特性[生物合成粘合剂]: 具有热稳定性和热熔粘合剂(HMA)性能","合成底盘[芳香PHA共聚物]: 工程化大肠杆菌"]},{"i":41340,"as":"针对可穿戴传感器在间质液中长期监测时受功耗和信号漂移限制的问题，研究人员开发了一种用于零偏差化学监测的光门控光电化学微针可穿戴设备。该设备集成了耐溶胀导电水凝胶微针阵列、等离子体增强光电极和微型无线传输模块。在可见光驱动下，通过氧介导的氧化还原反应实现零偏差检测，降低了电化学干扰和功耗。以尿酸为代表性分析物，该设备在皮肤水合作用下实现了间质液的无线、稳定纵向监测。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["监测模式[皮下间质液化学监测]: 零偏差光电化学监测","设备核心组件[光门控微针可穿戴设备]: 耐膨胀导电水凝胶微针阵列、等离激元增强光电极及微型化光发射与传输模块"]},{"i":41341,"as":"","scd":null,"kp":[]},{"i":41342,"as":"","scd":null,"kp":[]},{"i":41343,"as":"","scd":null,"kp":[]},{"i":41344,"as":"","scd":null,"kp":[]},{"i":41345,"as":"","scd":null,"kp":[]},{"i":41346,"as":"","scd":null,"kp":[]},{"i":41347,"as":"","scd":null,"kp":[]},{"i":41348,"as":"","scd":null,"kp":[]},{"i":41349,"as":"","scd":null,"kp":[]},{"i":41350,"as":"","scd":null,"kp":[]},{"i":41351,"as":"","scd":null,"kp":[]},{"i":41352,"as":"研究人员基于薄膜铌酸锂首次实现了利用电光（EO）非互惠强耦合的紧凑型集成光隔离器。该设计突破了以往挑战，通过在波导或谐振器模式之间产生不对称的光色散，成功达到了多太赫兹级别的可调谐宽带宽。这一成果不仅抑制了不需要的边带，还提供了易于实际部署的片上非磁性光隔离解决方案。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["隔离器机制[集成非磁性线性隔离器]: 电光不可逆强耦合","[核心挑战解决]: 减少不需要的边带并实现宽带宽和宽可调谐性"]},{"i":41353,"as":"针对水系锌离子电池正极结构不稳定的问题，研究通过将氟引入V2O3的V-O框架中，诱导不对称电子分布，增强了π键和σ键的共价相互作用。这种共价性的提高降低了轴向氧原子的碱性，有效抑制了高充电电压下的质子攻击和结构畸变。掺杂后的F-V2O3正极表现出了显著提升的循环稳定性和高电压耐受性。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["正极改性机制[V2O3高能氧化钒]: 氟引入V-O框架诱导不对称电子分布","[核心条件]: 通过调节轨道耦合提升正极高压循环结构稳定性"]},{"i":41354,"as":"为提升介电电容器的储能表现，研究人员通过在钨青铜基陶瓷基体中引入第二相并包覆二氧化硅层，实现了多层级涂层工程。该陶瓷材料达到了21.1 J/cm³的能量密度和84.5%的效率。结合多层陶瓷电容器（MLCC）设计与厚度效应，最终实现了23.2 J/cm³的能量密度和92.8%的高效率，创下了钨青铜基电容器能量密度的最高纪录。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":8.0,"t":6.0},"kp":["能量密度[Ba1-xSrxTiO3/Ba1-xSrxNb2-yTayO6多涂层陶瓷]: 21.1 J/cm³","效率[多涂层介电陶瓷]: >82%（提取自文本有效数字截断推演）"]},{"i":41355,"as":"为解决农药在疏水叶片上难以附着的问题，研究提出一种“双向固液界面调节”策略，利用水基天然粘土纳米杂化物（由凹凸棒石纳米棒和表面活性剂AOT组装而成）。该材料不仅能通过表面活性剂快速降低表面张力引发初始沉积，还能实现主动的界面重塑，从而在顽固的疏水叶面上实现高效的农药沉积与除草剂递送。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["界面调控策略[天然粘土纳米杂化物除草剂]: 固液双向主动界面重塑"]},{"i":41356,"as":"通过混合多尺度设计策略，研究人员成功将原始疏水的多壁碳纳米管（MWCNTs）转化为稳定的水性聚氨酯（WPU）直写墨水。该工艺采用超声波辅助模板化和乳化两步法，构建了“游泳圈”状的杂化结构网络，大幅提升了分散体的均匀性和导电性。风干后的结构展现出优异的导电性，在电磁干扰（EMI）屏蔽、传感和热管理领域具有应用潜力。","scd":{"b":6.5,"i":3.5,"r":5.0,"d":6.0,"t":5.0},"kp":["墨水组装工艺[MWCNTs/WPU直写墨水]: 超声辅助模板法两步可持续组装","[核心特征陈述]: 实现原生态疏水多壁碳纳米管在水性体系中的稳定分散与直写成型"]},{"i":41357,"as":"为克服双波段电致变色智能窗户光调制不足和切换速度慢的缺陷，研究人员利用两步原位取向生长策略，构建了金红石相二氧化钛纳米棒与锐钛矿相纳米片的半相干异质结构薄膜。该异质结凭借高晶格兼容性形成了单晶电子通道与机械支架。这种结构设计实现了可见光和近红外光的独立调节，大幅提升了电致变色器件的切换速度和循环稳定性。","scd":{"b":6.0,"i":3.5,"r":5.0,"d":6.0,"t":5.0},"kp":["异质结构[双频段电致变色薄膜]: 纳米棒/纳米片半相干异质界面"]},{"i":41358,"as":"探讨半胱氨酸衍生碳点水凝胶结合光催化疗法在感染伤口愈合应用的研究论文勘误更正信息。","scd":null,"kp":[]},{"i":41359,"as":"针对手性共价有机框架在不对称催化中反应时间长、对映体过量值低的问题，研究人员通过手性单体的对称性控制，精确构建了三种具有不同数量吡咯烷催化中心的手性COFs。研究证实，手性COFs的非均相不对称催化性能与吡咯烷催化中心的数量密切相关，为高效手性催化剂的设计提供了精准调控范例。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["调控机制[手性COF催化剂]: 通过对称匹配精确控制吡咯烷催化中心数量"]},{"i":41360,"as":"在高质量伯纳尔双层石墨烯中，研究人员观测到了高达9.1 µm S V⁻¹的巨大非线性霍尔电导率。这一现象在场驱动的同位旋极化相（即同位旋对称性破缺状态）中尤为显著。与常规非线性系统中的二次方标度不同，该强关联体系中的非线性电导率随线性电导率呈指数级增长，量子振荡测量进一步揭示了其深刻的电子结构机制。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["非线性霍尔电导率[同位旋对称性破坏双层石墨烯]: 9.1 µm S V⁻¹"]},{"i":41361,"as":"研究人员开发了一种钴催化体系，通过动态配体中继催化策略，成功实现了缺电子N-杂芳烃的不对称迁移脱芳环化反应。该策略采用两种不同配体串联工作：一种促进1,4-钴/氢化物迁移，另一种控制对映选择性的脱芳环化。此方法能够以极高的效率和选择性，构建出在配体、材料和药物发现中极具价值的手性N-螺杂环骨架。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":5.0,"t":4.0},"kp":["催化机制[钴催化N-杂芳烃脱芳环化]: 动态配体中继串联催化策略"]},{"i":41362,"as":"研究通过玻璃化一种水杨醛缩苯胺衍生物，证明了无定形分子固体也能表现出耦合的手性光学和铁电响应。这种非晶态虽失去长程有序性，但保留了空间不均匀的局部极性响应，其矫顽场约为5.7 kV cm⁻¹，最大可切换极化达26 μC cm⁻²。此外，该无定形固体在紫外光触发的非手性向手性转换中，恢复速度比晶态快一个数量级以上。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["物理响应机制[非晶分子固体]: 结构无序化解锁耦合的旋光和铁电响应","[光触发特性]: 实现非手性到手性的转变"]},{"i":41363,"as":"研究利用炔烃迁移插入策略，通过钯催化成功实现了未活化外消旋萘衍生物的对映汇聚式动态动力学不对称脱芳构化。借助定制的不对称多氟代亚磷酰胺配体，该反应将构型不稳定的联芳基底物转化为对映体富集的螺环骨架。机制研究证实了其对映汇聚路径，为平面芳香化合物转化为三维手性结构提供了罕见的合成新策略。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":5.0,"t":4.0},"kp":["[未活化外消旋联芳基的动态动力学不对称脱芳构化]: 利用钯催化和炔烃迁移插入策略实现罕见的外消旋底物动态动力学转化","催化剂[不对称脱芳构化]: 钯"]},{"i":41364,"as":"研究通过电路级仿真评估了有噪声互连模块下的横向容错分布式量子计算性能。基于可扩展的仿真库，测试了非局部CNOT和表面码逻辑隐形传态等分布式原语。结果表明，在合适的设备上，分布式qLDPC横向操作的性能优于表面码晶格手术，不仅能实现高效的并行计算，还能显著降低贝尔对的消耗。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[横向容错分布式量子计算操作]: 电路级仿真表明横向非局域CNOT和使用表面码及双变量自行车码的逻辑隐形传态能在含噪模块间实现有效操作"]},{"i":41365,"as":"针对高性能分段热电装置在极端环境下易受热震失效的问题，研究揭示了热震源于焊料与热电材料热膨胀不匹配导致的热应力集中。为此设计了镍泡沫复合焊料层，其网络结构不仅约束焊料基体以降低有效热膨胀，还通过塑性变形吸收应变能。该设计成功使热电腿承受七次热冲击且界面完好，显著提升了使用寿命。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":6.5,"t":5.0},"kp":["[分段热电装置热应力集中原因]: 焊料与热电材料之间的热膨胀错配","[提升抗热震性策略]: 设计网络状镍泡沫复合焊料层以缓解热应力"]},{"i":41366,"as":"研究开发了一种钾促进的Cu2Fe1串联催化剂，用于在工业相关条件下进行光热驱动二氧化碳加氢制碳氢化合物。在250℃和20 bar条件下，该催化剂对C2+碳氢化合物的选择性达77.4%，C2-5碳氢化合物产率为5.04 mmol g−1 h−1。其反应机制为铜先催化逆水煤气变换反应生成一氧化碳，随后在原位形成的χ-Fe5C2上进行费托合成类型的反应。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":8.0,"t":7.0},"kp":["选择性[光热CO2加氢生成C2+烃类]: 77.4%","C2-5烃类产率[光热催化条件]: 5.04 mmol g−1 h−1","反应温度[光照条件]: 250 °C","反应压力[光照条件]: 20 bar","催化剂[光热CO2加氢]: 钾促进的Cu2Fe1串联催化剂"]},{"i":41367,"as":"为准确预测溶液中可交换质子的核磁共振化学位移，研究提出将机器学习分子动力学（ML-MD）与ShiftML3机器学习屏蔽模型相结合的预测框架。该方法有效捕捉了分子间相互作用对屏蔽的影响，成功重现了水、醇、葡萄糖异构体及碱基等多种系统中的实验化学位移，解决了溶质-溶剂相互作用及分子动力学影响的预测难题。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[可交换质子化学位移的定量预测]: 将机器学习分子动力学(ML-MD)与ShiftML3机器学习屏蔽模型相集成，准确捕捉分子间相互作用的影响"]},{"i":41368,"as":"研究利用DNA折纸精确控制纳米颗粒间距，实现了一种可编程的接触依赖型局部电化学奥斯特瓦尔德熟化机制。实验表明，银在金种子上均匀生长，直至颗粒间发生电接触，从而触发由尺寸依赖性电位驱动的非对称熟化。通过编程控制纳米颗粒的接触时间与位置，可定向合成具有增强等离激元特性的定制异质纳米颗粒结构。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":5.0,"t":7.0},"kp":["[电化学奥斯特瓦尔德熟化精确控制]: 使用DNA折纸技术精确控制颗粒间距，实现依赖于接触的局部选择性银颗粒生长"]},{"i":41369,"as":"研究开发了一种用于钠固态电池的共价有机骨架/聚丙烯酸酯-氟化乙烯复合电解质（COF/PNSE）。该设计利用COF的定向纳米孔提供连续的Na⁺传输通道并增强基体力学性能，在30℃下实现1.2 mS cm⁻¹的离子电导率。该电解质表现出极佳的钠金属相容性，使对称钠电池稳定运行达6750小时，满足了快充和长循环需求。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[快充固态钠电池电解质设计]: 通过共价有机骨架/聚丙烯酸钠-共-氟化乙烯(COF/PNSE)复合电解质实现协同结构与化学调控以匹配快充和长循环需求"]},{"i":41370,"as":"针对时间干扰刺激（TIS）非侵入性调节深层脑区时生理效应尚不明确的问题，研究开发了一种软液态金属神经接口。该接口具有极低的侵入性，能稳定记录从脑类器官到小鼠大脑等不同神经组织对TIS的电生理反应。分析揭示了TIS诱导的神经动力学变化，为深脑神经调节机制的研究和监测提供了新的技术工具。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[时间干扰刺激神经生理效应监测]: 采用定制的液态金属基柔性神经接口跨神经系统进行高空间选择性的无创深部脑区神经动力学监测"]},{"i":41371,"as":"","scd":null,"kp":[]},{"i":41372,"as":"研究对比了全规模振动膜生物反应器（VMBR）与传统曝气膜生物反应器（AMBR）连续800天的运行表现。结果表明，VMBR显著增强了营养物去除效率，出水总氮降低22%，除磷药剂消耗减少40%。同时，VMBR表现出更强的抗污染能力，平均特定通量提升20%，有效克服了高能耗曝气和膜污染两大应用瓶颈。","scd":{"b":6.0,"i":8.0,"r":7.0,"d":8.0,"t":6.0},"kp":["处理规模[全规模振动膜生物反应器]: 7500 m³/d","连续运行时间[平行对比测试]: 约800天","[振动膜生物反应器优势]: 相比传统曝气系统，在降低能耗、缓解膜污染的同时保障了长效过滤稳定性和出色的污染物去除性能"]},{"i":41373,"as":"为实现复杂废水的超快速净化，研究开发了一种内含承压水选择性通道的致密光热膜（DPM）。通过机械压缩和亲水聚合物合理选择，精确工程化了膜的层间纳米结构和化学环境。基于空间位阻与化学选择性的协同效应，该膜能够有效拦截高浓度离子和强极性挥发性有机化合物，实现高蒸发率下的高效废水净化。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[复杂废水超快速净化]: 在致密光热膜(DPM)内部构建承压水选择性通道，在高蒸发速率下同步高效拦截高浓度离子和强极性挥发性有机化合物"]},{"i":41374,"as":"为解决乙腈基钠离子电池电解质还原抗性差、与硬碳负极不兼容的问题，研究引入碳酸甲乙酯进行离子-偶极相互作用调节。较弱的溶剂化能力促使更多阴离子进入内溶剂化壳层，在宽温区内形成坚固的电极-电解质界面。这种无氟乙腈基电解质显著提升了界面稳定性，有效解决了硬碳负极容量快速衰减的问题。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[无氟乙腈基电解质抗还原性改进]: 引入碳酸甲乙酯调节离子偶极相互作用，增强阴离子溶剂化化学，从而提升与硬碳负极的兼容性并抑制容量快速衰减"]},{"i":41375,"as":"针对柔性压力传感器在预载下灵敏度急剧下降的问题，研究开发了一种由两个PDMS微脊阵列和薄Pt导电层组成的裂纹互锁脊状结构传感器。该结构将垂直压缩转化为局部拉伸变形，在预设预载附近产生可重现的裂纹介导电阻跃迁。其局部最高灵敏度达2582.8 kPa⁻¹，解决了背贴式监测中在静态大负荷下分辨微小压力变化的技术难题。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["界面结构[背面压力传感预载适应]: 由两相对的PDMS微脊阵列和薄Pt导电层组成的裂纹互锁脊状结构"]},{"i":41376,"as":"该综述系统总结了用于可持续反应的催化剂设计方法论，填补了基础理论知识与明确应用指南的空白。文章对最相关的催化剂设计方法进行了分类和原理解析。指出尽管数字实验室收集的数据带来显著优势，但目前设计仍过于依赖偶然性，催化剂创新设计面临如何实现真正突破性“跳出框架”思维的核心挑战。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":3.0,"t":3.0},"kp":[]},{"i":41377,"as":"介绍虚拟电厂在经济调度中引入强化学习与自适应前瞻算法，以有效应对系统不确定性的研究。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[虚拟电厂经济调度]: 引入强化学习与自适应前瞻算法以应对系统不确定性"]},{"i":41378,"as":"为解决5-羟甲基糠醛（HMF）氧化合成2,5-呋喃二甲酸（FDCA）动力学缓慢和选择性差的问题，研究在二维氮化碳上设计了解偶联催化位点：边缘共价接枝氰酰胺基团，平面π-π堆叠J型镍酞菁二聚体。这种空间解偶联结构实现了级联电荷转移与双位点催化，使HMF转化率和纯水中的析氢速率分别提升54倍和160倍。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["催化位点空间解耦[中性生物质合成FDCA]: 边缘共价接枝氰胺(CA)基序与二维氮化碳(CN)表面π-π堆积的超分子二聚体"]},{"i":41379,"as":"纳米晶体表面的重构结构决定其在催化和半导体等领域的应用表现。研究展示了利用对表面敏感的固态核磁共振（SSNMR）光谱技术，克服了传统电子显微和衍射技术无法提供全局宏观结构的局限。研究成功探明了LaAlO3钙钛矿纳米颗粒的表面终止结构，为跨学科全面解析纳米材料表面结构提供了有效手段。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["表征方法[LaAlO3钙钛矿纳米粒子表面终止]: 固态核磁共振技术"]},{"i":41380,"as":"研究开发了一类带有悬垂季铵盐阳离子基团的Mn(I)和Re(I)羰基配合物双吡啶配体电催化剂，实现在水相中高效选择性还原二氧化碳。在pH 6.8的碳酸氢盐缓冲液中，该锰催化剂在低过电位（0.3 V）下对CO的生成具有完全选择性，反应速率约为10 s⁻¹。其机制为质子化优先，阳离子基团的第二配位层稳定作用大幅提升了水溶性与催化效率。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["反应环境[CO2还原Mn(I)电催化剂]: pH 6.8的碳酸氢盐缓冲液","水溶性及二级球稳定作用[Mn(I)和Re(I)络合物电催化剂]: 联吡啶配体上功能化的-Ph-CH2-(NMe3)+季铵盐基团"]},{"i":41381,"as":"提出基于约束驱动Q学习与混沌协同进化算法，解决多目标经济排放调度优化问题的方法。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[经济排放调度]: 提出基于约束驱动Q学习与混沌协同进化算法解决多目标优化问题"]},{"i":41382,"as":"聚焦四电子转换机制的钒基电池技术，探讨其电化学反应原理及在先进储能领域的应用潜力。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["钒基电池技术[转换机制]: 四电子转换机制"]},{"i":41383,"as":"针对碱性液流电池中传统醌类和酮类负极电解液存在的电子转移数少（≤2e）、异构化及副反应等限制，研究提出偶联异质氧化还原中心的分子工程策略。通过融合不同的氧化还原活性基元，构建出一种全新的复合吩嗪-酮分子。该结构支架能够实现6电子转移过程，克服了传统分子的固有缺陷，大幅提升了能量密度和长期循环稳定性。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["传统醌基和酮基阳极液[电子转移数]: ≤2 e- /分子","[能量存储机制]: 吩嗪酮支架中的多个异质氧化还原中心"]},{"i":41384,"as":"针对蛋白质胞内递送后易被自噬降解的难题，研究开发了一种基于两亲性三嵌段共聚物（mPEG-b）的逐步协调聚合物纳米递送平台。该平台不仅能实现无痕的胞质蛋白递送，还能同步阻断细胞自噬途径。这种双重功能设计有效避免了蛋白在细胞内的降解失活，从而显著增强了蛋白质药物的抗肿瘤治疗效果。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["递送载体[无痕胞质蛋白递送及自噬阻断]: 基于定制的两亲性三嵌段共聚物的逐步协调聚合物纳米平台"]},{"i":41385,"as":"研究结合卫星遥感与机器学习技术，首次对全球145个国家的16,409个湖泊水质进行了标准化评估。结果揭示全球仅有三分之二的湖泊符合联合国可持续发展目标（SDG）的水质标准。这一发现暴露了影响数十亿人口的淡水安全深刻不平等问题，为全球水资源管理与政策制定提供了关键数据支撑。","scd":{"b":6.0,"i":4.0,"r":8.0,"d":8.0,"t":5.0},"kp":["评估范围[全球湖泊水质卫星-机器学习评估]: 145个国家的16,409个湖泊","水质达标率[全球湖泊SDG水质标准]: 三分之二的湖泊达标"]},{"i":41386,"as":"该研究将竹子定位为负碳材料设计的多尺度平台。通过关联竹子的层级结构、化学键选择性、加工工艺、耐用性及全生命周期碳核算，系统阐述了竹基产品实现大规模气候效益的路径。研究明确界定了竹材在封存碳、替代高排放材料方面的具体条件，证明了其作为可持续环保材料的巨大潜力。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":4.0,"t":3.0},"kp":["材料属性[工程竹子作为负碳材料]: 结合高生物量生产力与固碳能力的多尺度材料设计平台"]},{"i":41387,"as":"","scd":null,"kp":[]},{"i":41388,"as":"","scd":null,"kp":[]},{"i":41389,"as":"","scd":null,"kp":[]},{"i":41390,"as":"","scd":null,"kp":[]},{"i":41391,"as":"研究人员利用机器学习算法分析了卫星图像，生成了欧洲湿地环境的高分辨率地图。这些被忽视的生态系统斑块详细分布图将为湿地保护工作提供有力支持。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[制图方法]: 利用机器学习算法分析卫星图像生成高分辨率湿地地图"]},{"i":41392,"as":"Superphane笼在膜中构建了精确工程的亚纳米通道，实现了Grotthuss机制的快速质子传导和尺寸排阻选择性。该设计通过受限超分子相互作用抑制了水分子的迁移，使酸性液流电池的容量衰减率低至每循环0.008%，创下历史新低。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":8.0,"t":6.0},"kp":["容量衰减率[酸性液流电池超薄膜]: 每循环0.008%（创纪录新低）","传导机制[超薄膜亚纳米通道]: Grotthuss机制驱动的快速质子传导与尺寸排阻选择性"]},{"i":41393,"as":"","scd":null,"kp":[]},{"i":41394,"as":"探讨新型非贵金属基替代材料（如催化剂等），分析其在降低成本并超越贵金属性能方面的进展。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":3.0},"kp":["替代材料[成本与性能]: 使用非贵金属基材料降低成本并超越贵金属性能"]},{"i":41395,"as":"","scd":null,"kp":[]},{"i":41396,"as":"可充电镁金属电池因严重的极化和迟缓的阴极动力学受限。研究通过在NASICON型NaTi2(PO4)3中进行Mg取代实现了阳离子空位工程策略。优化的Mg0.25Na0.5Ti2(PO4)3阴极具有0.05V的低电压迟滞、高倍率性能（500 mA g-1下容量保持率87%）和长期循环稳定性。软包电池的极化电压为0.067V，机理揭示了由Na+主导可逆阴极过程的镁钠混合离子存储机制。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":7.0,"t":5.0},"kp":["电压迟滞[镁金属电池NASICON阴极]: 0.05 V","容量保持率[Mg0.25Na0.5Ti2(PO4)3阴极]: 87%","结构工程策略[NASICON型NaTi2(PO4)3阴极]: 通过Mg取代实现阳离子空位工程"]},{"i":41397,"as":"高能量密度锂金属电池能量衰减的主要原因是非活性锂（包括锂枝晶生长产生的金属锂和副反应产生的锂化合物）的积累。研究向电解质中引入2-碘辛烷添加剂，其在负极反应并在正极氧化生成I3−/I−氧化还原介质，将非活性锂转化为Li2O并回收锂离子。得益于非活性锂的回收，半电池表现出99.03%的高库伦效率。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["电池寿命[使用2-碘辛烷电解质添加剂]: 两年"]},{"i":41398,"as":"蛋白质纳米孔通过将化学性质直接转化为单分子电信号，为分析应用提供了平台。受限于可用支架数量和几何演化限制，工程化天然纳米孔面临挑战。人工智能和数据驱动的蛋白质设计正推动日益复杂的膜蛋白架构设计。综述了从最小序列到AI辅助的从头纳米孔设计演变，强调了新兴策略，并指出了数据稀缺、膜建模等关键挑战。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[蛋白质纳米孔设计]: 结合AI与数据驱动方法突破天然支架数量及几何化学进化限制以构建复杂膜蛋白架构"]},{"i":41399,"as":"针对环烷烃/芳烃液体有机氢化物（LOHC）在脱氢动力学缓慢和催化剂易失活的问题，研究设计了一种负载在弯曲石墨烯包覆纳米金刚石上的铂整体异质性催化剂（Ptn+c/ND@G）。该催化剂将完全暴露的亚纳米铂簇与三维铂簇紧密集成。在双环己基及其他环烷烃的无溶剂脱氢产氢反应中，该催化剂表现出显著增强的催化效率和良好的循环稳定性，超越了单一形貌催化剂及其物理混合物。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":7.0,"t":5.0},"kp":["催化剂[LOHC脱氢反应]: 弯曲石墨烯包覆纳米金刚石负载的铂催化剂 (ND@G)","铂簇[整体异质性]: 集成全暴露亚纳米Pt簇(Ptn)和三维Pt簇(Ptc)"]},{"i":41400,"as":"负载型金属纳米颗粒的尺寸和分散控制是多相催化的基本问题。在水平排列碳纳米管阵列生长中，催化剂尺寸直接决定纳米管直径及电子特性。研究报道了一种确定性的硫修饰蓝宝石（S-apphire）界面工程策略，用于调节催化剂分散和碳纳米管直径，建立了内聚调控机制。","scd":{"b":6.5,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["催化剂[水平排列碳纳米管阵列生长]: S-Apphire界面工程调控直径合成"]},{"i":41401,"as":"在可控自由基聚合中实现快速聚合同时保持良好控制是一项巨大挑战。研究通过阳离子基硫代羰基硫试剂与葫芦[7]脲（CB[7]）的主客体络合，提出了一种缓解该问题的超分子策略。这种封装作用使得链转移系数和CTA的光解效率显著提高，适用于水性光引发聚合和RAFT聚合。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["聚合控制[受控自由基聚合]: 超分子策略调控水相光引发和RAFT聚合"]},{"i":41402,"as":"无环二烯的环香叶基基团不对称形成具有挑战性。研究使用受限手性咪锑二磷酸酰胺（IDPi）布朗斯台德酸，结合氟化醇添加剂，实现了香叶基衍生物的一般催化不对称环化。该方法条件温和，具有高效率和优异的区域及对映选择性，适用于多种底物。机理研究支持在受限空间内存在协同的催化剂-添加剂氢键网络和异步协同的类酶过渡态。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":7.0,"t":4.0},"kp":["催化剂[香叶基衍生物不对称环化]: 限制性手性咪唑二磷酰亚胺酸盐 (IDPi) 布朗斯特酸","反应特性[香叶基衍生物不对称环化]: 温和条件下高效率及优异的区域和对映选择性"]},{"i":41403,"as":"原子级控制多元半导体材料面临重大挑战。研究通过自限性阳离子交换精密合成了三元纳米团簇。Cu26Se13(PR3)14模板簇与InCl3-PR'3配合物反应，以近100%的产率和高纯度生成了部分交换的Cu6In8Se13Cl4(PR'3)12团簇。该三元团簇保留了二十面体Se13阴离子骨架，In3+和Cu+自组装成伪核/壳异质结构。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":8.0,"t":4.0},"kp":["合成工艺[I-III-VI三元半导体纳米团簇]: 自限性阳离子交换精密合成","合成模板[三元纳米团簇]: Cu26Se13(PR3)14团簇与InCl3-PR'3络合物反应"]},{"i":41404,"as":"丁二烯电羧化是合成己二烯二酸酯的可持续途径，后者可转化为尼龙主要前体己二酸。研究采用原位衰减全反射表面增强红外吸收光谱（ATR-SEIRAS）、电解实验和密度泛函理论（DFT），考察了Au、Cu和Pt表面的丁二烯电羧化过程。光谱追踪显示丁二烯抑制了界面竞争反应（如二氧化碳还原反应）。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["机理研究[丁二烯电羧化反应]: 非质子介质中ATR-SEIRAS揭示表面中间体和竞争界面反应"]},{"i":41405,"as":"在SnO2催化剂中引入非金属掺杂可在不改变其体相的情况下调节界面水合作用。在氮、磷、硫掺杂剂中，硫能在催化剂-电解质边界独特地稳定无序且主朝下的水合基元，促进水活化并定向传递质子，加速向甲酸生成方向的质子耦合电子转移（PCET）。这揭示了由溶液结构控制的CO2电还原选择性机制。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["界面水结构[SnO2催化剂掺杂]: S掺杂独特地稳定了无序的、以H-down为主的界面水合结构","选择性调控[CO2电还原]: 非金属杂原子掺杂重构界面H2O以调控质子耦合电子转移(PCET)和选择性"]},{"i":41406,"as":"实验上明确解析基于非共价碳键的超分子合成子对接几何结构仍具挑战。研究利用氮原子核处的电场梯度（通过核四极分裂获得）作为超分子拓扑的高灵敏度探针。结合超音速喷射膨胀中的超精细分辨宽带旋转光谱和量子化学计算，考察了四氰基环丙烷衍生物与四氢呋喃形成的复合物，验证了该技术的检测能力。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["检测技术[超分子Synthon架构]: 超精细分辨旋转光谱检测非共价碳键的对接几何构型"]},{"i":41407,"as":"SAPO-34是甲醇制烯烃（MTO）工艺的基准催化剂，但其催化寿命受限。研究发现了SAPO-34失活的新原因：难以用常规粉末X射线衍射检测到的堆积无序结构缺陷。通过结合三维电子衍射（3D ED）、积分差分相位对比扫描透射电子显微镜和电子叠层成像技术，揭示了使用常规四乙基铵模板剂合成的纳米SAPO-34中原子级别的隐藏堆积无序。","scd":{"b":7.5,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["催化剂失活原因[MTO过程]: 原子级堆积无序","检测精度[3D ED技术]: 原子级"]},{"i":41408,"as":"本文报道了一种利用构象控制策略实现芳香族化合物远程间位选择性C-H硼化的新方法。该策略通过芳烃与三羰基铬（Cr(CO)3）的π配位作用实现：铬基形成稳定的三脚架构象以暴露间位C-H键，同时结合含有2-氨基菲咯啉配体的特制铱催化剂，协同克服了底物固有的反应偏向。在多环芳烃中，铬基不仅作为构象导向剂，还发挥电子调节作用，实现了现有无导向方法无法达成的位点选择性和环选择性。先进的DFT理论计算进一步证实，该高选择性源于芳烃π配位与催化剂之间的协同作用。此研究为芳环远程惰性位置的精准修饰提供了全新路径。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["催化剂[间位选择性C-H硼化反应]: 铱/2-氨基菲咯啉配合物","构象控制[单/双取代芳烃]: 三羰基铬(Cr(CO)3)配位"]},{"i":41409,"as":"研究制备了一系列具有六方孔隙的二维共价有机框架(COF)单晶（COF-600、660和666）。这些晶体尺寸达120微米，通过X射线和电子衍射证实其具有高达0.9埃的分辨率。通过剥离技术可将其制备成厚度在50纳米至1.5微米可调的单晶薄膜，用于构建多孔莫尔超结构。框架节点处高密度的弱相互作用是保持剥离后结构完整性和孔隙率的关键，并能在孔隙中捕获无机团簇。","scd":{"b":8.5,"i":2.0,"r":7.0,"d":8.0,"t":6.0},"kp":["晶体尺寸[二维COF单晶]: 最高达120 μm","空间群[二维COF单晶]: P65","晶体结构分辨率[SCXRD和ED表征]: 最高达0.9 Å"]},{"i":41410,"as":"研究提出一种“时间尺度协调”策略解决光催化中 exciton-carrier 动力学与表面反应速率不匹配的瓶颈。该方法将二茂铁甲醛作为智能电荷缓冲器集成到能级匹配的光催化剂上。结合飞秒瞬态吸收光谱和红外光谱分析证实，该分子能在接受电子和给出电子状态间可逆切换，实现多时间尺度的界面化学反应，从而提升光催化效率。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["时间尺度[激子-载体动力学与表面反应]: 皮秒到秒级","调控策略[光催化电荷动力学]: 自调制时间尺度配位策略"]},{"i":41411,"as":"研究通过相分离形成液滴来增强酶模拟催化，将L-苯丙氨酸整合到L-叔亮氨酸衍生的方酰胺中，设计了方酰胺衍生伪肽液滴。该催化系统在α-硝基砜对丙烯酸酯的不对称共轭加成和乙酰丙酮对β-硝基烯烃的Michael加成反应中表现出显著增强的对映选择性催化性能。机制研究表明液滴内局部微环境的改善是催化活性提升的关键。","scd":{"b":7.5,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["催化剂[相分离液滴不对称加成反应]: L-叔亮氨酸衍生方酰胺伪肽"]},{"i":41412,"as":"研究开发了一种比较代谢组学工作流程，用于全面发现人类肠道细菌产生的硫酸化代谢物。该方法利用通用磺基转移酶辅助因子（PAPS），将重硫(34S)或轻硫(32S)同位素结合到代谢物中，从而在复杂样本中实现对含硫酸盐代谢物的精准检测与归属，克服了以往检测方法不足和细菌磺基转移酶底物范围窄的限制。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["代谢物生成酶[肠道细菌硫酸化代谢物]: 磺基转移酶"]},{"i":41413,"as":"研究合成了一系列可化学分离的氢化钌同分异构体。通过改变钌氢键对位的配体（氮杂环卡宾或吡啶），能够调节热力学氢化物供体能力，差异最高达8 kcal mol-1。这些异构体对二氧化碳及有机氢受体表现出不同的反应性。动力学分析、同位素标记和计算研究证实其遵循外层氢化物转移机制，为优化工业和生物催化提供了依据。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":8.0,"t":6.0},"kp":["热力学氢负离子供体能力调节[不同反位配体的钌氢化物异构体]: 最高达 8 kcal mol-1"]},{"i":41414,"as":"介绍一种入耳式片上系统电子设备，结合微型化集成电路技术，用于睡眠状态的监测与调节。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[入耳式睡眠监测与调节设备]: 结合微型化集成电路技术的片上系统"]},{"i":41415,"as":"观点文章提出利用脉冲调制技术实现电池化学的主动实时调控，突破传统稳态运行的动力学和热力学瓶颈。通过产生非平衡瞬态，脉冲激发能够在时间上解耦离子溶剂化鞘重组、界面电荷转移和长程质量传输等相互纠缠的物理化学过程。这一高维度调控框架为高能电化学储能系统的设计提供了基础性范式转变。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["电池调控范式[非平衡瞬态过程]: 脉冲调制"]},{"i":41416,"as":"探讨能够在极低温（毫开尔文级）环境下稳定工作的极低温数模转换器芯片的设计与应用。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":3.0,"t":6.0},"kp":["工作温度[数模转换器芯片]: 毫开尔文级极低温"]},{"i":41417,"as":"研究开发了一锅湿化学合成法，成功制备出具有六方密排相(2H型)的铜纳米晶，打破了铜常规热力学稳定的面心立方相。在电化学二氧化碳还原反应中，与常规铜纳米晶相比，2H-Cu纳米晶展现出更高的催化活性和选择性。在碱性流动电池中，于600 mA cm-2电流密度下生成多碳(C2+)产物的法拉第效率高达73.1%。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["物相结构[湿化学法合成的铜纳米晶]: 六方密排(2H型)","物相结构[热力学稳定的常规铜纳米晶]: 面心立方型"]},{"i":41418,"as":"研究构建了一种基于DNA编码的可编程二聚化网络，用于实现无细胞转录的动态和竞争性控制。通过SPAAC化学反应，带有正交把手的设计DNA单体组合形成二聚体，其中特定二聚体能激活无活性启动子并转录发光RNA。扩大网络单体数量可精细调节RNA产量。该系统通过多对多模拟网络，实现了对转录过程的定量控制。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["组装网络[无细胞转录控制]: 基于DNA编码的可编程二聚化网络"]},{"i":41419,"as":"分析主动配电网中电池储能系统的技术经济规划方案，以提升电网对可再生能源的托管容量。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[电池储能系统技术经济规划]: 提升主动配电网对可再生能源的托管容量"]},{"i":41420,"as":"研究发现冰冻酸性电解质可作为质子选择性反应环境，用于确定性单原子构建。在零下温度的冰冻水溶液中，氢键冰晶格支持质子电荷传输，同时抑制了较重离子的长程质量迁移。这种传输不对称性使得通过电荷编程实现聚集抑制成为可能，从而成功构建并维持了孤立的金属原子位点结构，突破了传统液相电解质的限制。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[电化学单原子构建质子选择性反应环境]: 冷冻的酸性电解质作为质子传导且限制质量传输的介质","工作温度[冷冻水系电解质]: 零下温度窗口"]},{"i":41421,"as":"综述利用氢气热化学还原二氧化碳生成甲醇的技术，重点探讨突破化学反应平衡限制的策略。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":3.0,"t":3.0},"kp":["[CO2加氢生成甲醇工艺]: 重点突破热化学反应平衡限制"]},{"i":41422,"as":"针对电动汽车和电动航空对极高能量密度的需求，该观点文章通过热力学矩阵计算指出，传统的嵌入化学已逼近极限。研究明确界定interhalogens（卤素间化合物）和过渡金属氟化物是极具前景的转换阴极材料体系，有潜力将可充电电池的能量密度提升至1,000 Wh kg−1的水平。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":8.0,"t":6.0},"kp":["目标能量密度[可充电电池转换正极]: 1000 Wh/kg","潜在正极材料[热力学矩阵计算]: 卤素间化合物和过渡金属氟化物"]},{"i":41423,"as":"研究通过形态发生设计开发出一种极弹性超材料。该超材料通过弱耦合各向同性等容特征模态，解耦了固体模量与弹性波速之间的限制关系，使刚度增强效果超越各向同性极限达6.8倍。将其与橡胶结合制成的复合材料，在最高达4.5 MPa的流体静压下仍能保持大于0.9的平均吸声系数，覆盖三个倍频程的低频波段。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":8.0,"t":6.0},"kp":["吸声系数[水下超材料]: 平均吸声系数>0.9","弹性极限突破[形态发生设计超材料]: 解耦模量与波速，各向同性极限提升6.8倍"]},{"i":41424,"as":"","scd":null,"kp":[]},{"i":41425,"as":"研究利用冷冻电子断层扫描和显微镜技术，直接观察了艾可病毒18型(E18)进入宿主细胞并释放基因组的动态机制。感染后30分钟，在细胞内体和细胞质中发现了缺失一个或多个衣壳蛋白五聚体的空衣壳。这提供了直接的视觉证据，表明E18在体内通过衣壳开放的方式释放其病毒基因组，并与新生儿Fc受体发生相互作用。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["感染后时间点[体内释放基因组]: 30 min postinfection","空衣壳形态[体内释放基因组特征]: missing one or several pentamers of capsid proteins","疏水囊袋因子[体外FcRn结合诱导]: expulsion of pocket factors from hydrophobic pockets in VP1","病毒激活中间体[体内感染状态]: 未检测到，表明其短暂存在且快速释放基因组","[体内基因组释放机制]: 衣壳开放"]},{"i":41426,"as":"","scd":null,"kp":[]},{"i":41427,"as":"","scd":null,"kp":[]},{"i":41428,"as":"","scd":null,"kp":[]},{"i":41429,"as":"","scd":null,"kp":[]},{"i":41430,"as":"","scd":null,"kp":[]},{"i":41431,"as":"","scd":null,"kp":[]},{"i":41432,"as":"观点文章强调，变革性人工智能治理不仅需要制定实质性规则，更关键的是构建相应的法律和监管基础设施来生成与执行规则。文章重点审查了三个关键基础设施构建方向：为前沿AI大模型建立注册制度；为自主智能体建立注册和识别机制；以及设计监管市场，引入私营企业参与创新并提供AI监管服务，从而完善整体的AI治理框架。","scd":{"b":2.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":[]},{"i":41433,"as":"","scd":null,"kp":[]},{"i":41434,"as":"","scd":null,"kp":[]},{"i":41435,"as":"生成式AI开发者因使用大量版权作品作为训练数据而面临侵权诉讼。若“合理使用”抗辩成功，开发者可继续免费使用版权数据构建或微调模型；若版权方胜诉，开发者不仅面临数十亿美元的赔偿，还可能被禁止进一步开发甚至被勒令销毁侵权模型。作为折中方案，业界专家提出了版权作品集体许可制度。","scd":{"b":2.0,"i":2.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[大规模生成式AI系统训练]: 面临版权所有者提起的版权侵权诉讼，合理使用为主要抗辩理由"]},{"i":41436,"as":"研究构建了一个战略模型，探讨通用AI安全监管对技术创作者和领域专家的影响。模型设定AI技术具有安全性和性能两个关键属性，监管机构在开发链的特定环节设定最低安全要求。分析指出，针对AI开发链不同环节的监管措施会直接影响博弈结果，揭示了不同监管方法的实际功效。","scd":{"b":2.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":[]},{"i":41437,"as":"AI系统依赖自然语言规则，面临与法律系统类似的法律解释歧义挑战。缺乏透明上诉审查等制度保障的规则对齐流水线，容易因对同一规则的不同解释导致模型行为不一致。研究借鉴美国法律理论，提出了一个计算框架，以在规则创建和应用阶段约束歧义，弥补当前AI对齐管线的缺陷。","scd":{"b":2.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":[]},{"i":41438,"as":"传统回归模型在审计不包含种族等受保护因素的机器决策算法时存在局限。基于法律对差异性影响的理解，研究提出了一种称为“风险调整回归”的三步分析方法，旨在精准测量人类和机器决策中存在的“不合理”差异，为涉及歧视的案件提供更有效的经验性审计策略。","scd":{"b":2.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":[]},{"i":41439,"as":"随着机器学习（ML）系统在大学招生中的广泛应用，结合最高法院禁止“基于种族”招生的裁决，教育机构面临界定ML系统如何产生种族差异的难题。研究将相关法庭裁决映射到预测性AI的不同种族使用场景中，探讨了ML招生算法与现行法律之间的冲突与合规问题。","scd":{"b":2.0,"i":2.0,"r":5.0,"d":3.0,"t":5.0},"kp":[]},{"i":41440,"as":"研究应用Louvain社区发现算法分析了1790至2024年间包含76万份意见书和830万条引文的美国联邦司法引文网络。这些无监督提取出的引文社区成功恢复了已知的制度结构，并呈现出连贯的实体和程序法律方法，为量化研究法律传统演变与关键联邦法规带来的影响提供了可靠的实证基础。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["司法引文社区检测算法[全美联邦司法引文图]: Louvain算法","数据规模[全美联邦司法引文图(1790–2024)]: 760,000份意见书和830万条引文"]},{"i":41441,"as":"本文探讨了法律人工智能领域建立公共基准测试的迫切需求。当前，法律AI工具存在严重的“幻觉”风险（即模型捏造法律事实与判例），且整个生态系统缺乏透明度，公众无法获取商业系统设计与性能的有效信息。\n\n文章指出，法律AI未能像其他领域那样通过基准测试来有效衡量和推动创新与规范使用。此外，作者深入剖析了基准测试在机构制度设计中面临的挑战，警告基准测试可能被利益方操纵、标准被降低或遭到滥用，并强调了必须进行严谨的制度设计，以确保AI在法律领域的负责任应用。","scd":{"b":3.0,"i":2.0,"r":5.0,"d":4.0,"t":4.0},"kp":["核心风险[法律人工智能工具]: 模型存在捏造事实、法律和先例的“幻觉”风险","技术建议[法律人工智能]: 需要建立公共法律人工智能基准测试"]},{"i":41442,"as":"","scd":null,"kp":[]},{"i":41443,"as":"","scd":null,"kp":[]},{"i":41444,"as":"研究鉴定了玉米转录因子ZmWRKY38是增强干旱耐受性的正调控因子。ZmWRKY38通过结合并抑制蔗糖合酶基因ZmSUS2的转录来发挥功能，而ZmSUS2是耐旱的负调控因子。此外，定位于细胞膜的激酶ZmRIPK2参与调控该过程。ZmSnRK2.10-ZmRIPK2-ZmWRKY38磷酸化级联通过解除ZmSUS2的抑制作用来调节玉米的干旱反应。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":8.0,"t":5.0},"kp":["磷酸化级联模块[玉米抗旱反应调控]: ZmSnRK2.10–ZmRIPK2–ZmWRKY38","功能特征[ZmWRKY38转录因子]: 结合蔗糖合成酶基因ZmSUS2启动子并抑制其表达"]},{"i":41445,"as":"光合放氧复合物（OEC）的Mn4CaO5簇催化光合作用中的氧气释放。研究发现，当蓝细菌中结合该簇的Asp或Glu配体被突变替换后，能发生翻译后修饰重新生成原有的羧酸残基。研究进一步探讨了缺乏反应性侧链的脂肪族氨基酸是否也能经历类似的翻译后转化生成羧酸配体，以解析OEC在原始光系统中的起源与演化。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":8.0,"t":6.0},"kp":["催化剂[光合放氧复合物OEC]: Mn4CaO5簇","[配体生成机制]: 脂肪族侧链翻译后生成羧酸配体"]},{"i":41446,"as":"为应对东非木薯褐条病（CBSD），研究开发了名为ELLA的电化学侧流检测法。这是一种无需电池、由智能手机供电且完全一次性的设备，集成了近场通信、单芯片恒电位仪和二茂铁标记纳米颗粒。在坦桑尼亚的广泛现场试验中，ELLA无需光学仪器或集中式实验室即可实现95%准确率的ELISA级定量蛋白检测。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":6.0,"t":6.0},"kp":["检测性能[电化学侧流测定法ELLA]: 达到ELISA级蛋白检测水平","设备特性[植物病害检测ELLA系统]: 无电池、智能手机供电且集成近场通信与单芯片恒电位仪"]},{"i":41447,"as":"","scd":null,"kp":[]},{"i":41448,"as":"","scd":null,"kp":[]},{"i":41449,"as":"","scd":null,"kp":[]},{"i":41450,"as":"","scd":null,"kp":[]},{"i":41451,"as":"","scd":null,"kp":[]},{"i":41452,"as":"","scd":null,"kp":[]},{"i":41453,"as":"","scd":null,"kp":[]},{"i":41454,"as":"","scd":null,"kp":[]},{"i":41455,"as":"","scd":null,"kp":[]},{"i":41456,"as":"","scd":null,"kp":[]},{"i":41457,"as":"","scd":null,"kp":[]},{"i":41458,"as":"","scd":null,"kp":[]},{"i":41459,"as":"L-赖氨酸衍生生物碱的微生物合成长期受制于前体失衡和天然代谢通路的刚性调控。研究在谷氨酸棒杆菌中构建了一个可编程的生物合成平台，实现了从葡萄糖直接从头生产该类生物碱。通过系统性的代谢重塑，开发了高流量的尸胺生产底盘，有效积累了下游生物碱组装所需的核心含氮前体。","scd":{"b":7.5,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[L-赖氨酸衍生生物碱从头合成]: 双重自我调节的可编程生物合成平台"]},{"i":41460,"as":"趋磁性在细菌中多次独立演化，但在真核生物中的演化机制尚不明确。研究分离了一种厌氧趋磁纤毛虫，该物种通过三方共生关系获得了趋磁性。其细胞内的亚铁磁性磁铁矿纳米颗粒形成椭球形的“项链状”平行链，这些磁铁矿产生的磁矩使纤毛虫能够沿着地球磁场线游动，揭示了真核生物通过共生获取复杂表型的新机制。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":5.0,"t":5.0},"kp":["[趋磁性机制(厌氧纤毛虫)]: 通过三方共生的营养方式获得"]},{"i":41461,"as":"","scd":null,"kp":[]},{"i":41462,"as":"","scd":null,"kp":[]},{"i":41463,"as":"","scd":null,"kp":[]},{"i":41464,"as":"","scd":null,"kp":[]},{"i":41465,"as":"","scd":null,"kp":[]},{"i":41466,"as":"","scd":null,"kp":[]},{"i":41467,"as":"","scd":null,"kp":[]},{"i":41468,"as":"全纹理钙钛矿/硅串联太阳能电池的商业化受限于宽带隙钙钛矿的离子迁移不稳定性。研究提出一种B位阳离子合金化策略，利用锶离子替代铅离子进行局部晶格工程。由于锶离子具有更低的电负性和极化率，该合金化方法有效稳定了宽带隙钙钛矿材料，提升了太阳能电池的耐用性。","scd":{"b":7.5,"i":5.0,"r":6.0,"d":7.0,"t":7.0},"kp":["表面纹理特征[钙钛矿/硅串联太阳能电池]: 双面全纹理(3-5 µm)","稳定性策略[宽带隙钙钛矿顶电池]: B位阳离子合金化(锶/铅合金)"]},{"i":41469,"as":"二维低维材料由于电热传输的复杂耦合，其热电性能受到限制。研究提出一种几何拓扑策略，利用毛细管力将单层二硫化钨纳米带转变为纳米卷轴结构。这种结合全局曲率和局部多维形变的独特架构，显著提升了材料的热电性能，为下一代纳米系统片上能量收集提供了新途径。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["热电性能提升机制[纳米卷轴结构二维材料]: 解决低维材料电声输运复杂耦合的限制"]},{"i":41470,"as":"研究开发了一种超材料屈曲辅助表面声波传感器（mBASES），通过将生物交联水凝胶超材料与表面声波器件集成，引入结构触发的物理放大机制。目标分子结合会引起水凝胶溶胀达到超材料屈曲阈值，这种失稳机制能将微弱的生物分子识别高效转化为可检测信号，实现多功能、超灵敏的生物标志物检测。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["信号转换机制[超材料屈曲辅助表面声波传感器(mBASES)]: 引入结构触发的物理放大机制，无需分子扩增即可转换微弱生物分子扰动"]},{"i":41471,"as":"传统的阿蒙顿-库仑摩擦定律假设材料间的摩擦力与滑动速度无关，但在实际应用中摩擦力通常与滑动速度的对数存在二阶依赖关系。该研究通过实验在云母上实现了与速度完全无关的干摩擦，验证了理想状态下的阿蒙顿-库仑摩擦定律。","scd":{"b":8.0,"i":1.0,"r":7.0,"d":5.0,"t":7.0},"kp":["[云母干摩擦机制]: 摩擦力与滑动速度无关，实现理想阿蒙顿-库仑摩擦","[经典摩擦定律修正]: 摩擦力与滑动速度的对数存在二阶依赖关系"]},{"i":41472,"as":"","scd":null,"kp":[]},{"i":41473,"as":"","scd":null,"kp":[]},{"i":41474,"as":"自注入锁定技术使集成孤子微梳易于启动，但限制了泵浦光的失谐范围。研究引入一个辅助谐振器来动态混合泵浦模式，实现了绝热调谐，成功突破了“交钥匙”启动极限，从而能够获取更大的失谐量以实现更宽的微梳光谱。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["梳状光谱拓宽机制[集成孤子微梳]: 利用辅助谐振腔动态杂化泵浦模式以实现更大失谐访问"]},{"i":41475,"as":"研究证实，AI驱动的程序综合技术可自主发现光子网络中西矩阵分解的基础策略。通过将DreamCoder系统扩展至复值线性代数领域，系统生成了实现最小N(N−1)/2个马赫-曾德尔干涉仪的分解程序，实现了通用酉算子的自动化设计。","scd":{"b":7.5,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[光子网络酉矩阵分解策略]: AI驱动的程序综合可自主发现基本策略，生成的分解程序可实现最小$N(N−1)/2$的马赫-曾德尔干涉仪配置"]},{"i":41476,"as":"","scd":null,"kp":[]},{"i":41477,"as":"","scd":null,"kp":[]},{"i":41478,"as":"量子计量学理论上利用最大纠缠态（GHZ态）作为最佳探针，但其对环境噪声极为敏感。研究提出一种利用乱序相关器进行设备上学习的方法，能够自适应噪声环境并学习出最佳的量子探针，有效克服了噪声对量子计量的限制。","scd":{"b":8.5,"i":4.0,"r":7.0,"d":6.0,"t":9.0},"kp":["最佳量子计量探头[噪声自适应环境]: 最大纠缠GHZ态（但易受环境噪声影响而性能受限）"]},{"i":41479,"as":"该前瞻性论文探讨了高能量密度科学的前沿进展，重点聚焦于物质在极端压力和广泛温度等极端条件下的显著物理行为，这些极端状态常见于行星内核、恒星内部以及核聚变反应中。","scd":null,"kp":["物质状态[高能量密度极限条件]: 极端高压和极宽温度范围下的状态演化特征"]},{"i":41480,"as":"","scd":null,"kp":[]},{"i":41481,"as":"在凝聚态系统中，局域磁矩与巡游电子的相互作用会引发新奇的量子态。研究在魔角扭曲三层石墨烯中展示了电可调的重费米子相图，该相图通过电学控制近藤杂化效应实现，证明了该材料体系在量子态调控上的潜力。","scd":{"b":9.0,"i":3.0,"r":7.0,"d":6.0,"t":9.0},"kp":["重费米子相图调控机制[魔角扭曲三层石墨烯]: 通过控制Kondo杂化实现电可调的重费米子相变"]},{"i":41482,"as":"将物理先验整合到深度学习第一性原理方法中是一个关键基础问题。研究证明，通过将学习目标更改为旋转不变量，可以显著改进深度学习密度泛函理论哈密顿量（DeepH）方法在实空间中的计算表现与准确度。","scd":{"b":8.5,"i":3.5,"r":7.0,"d":6.5,"t":9.0},"kp":["深度学习DFT哈密顿量方法优化[实空间物理先验]: 将学习目标更改为旋转不变量以提升方法性能"]},{"i":41483,"as":"","scd":null,"kp":[]},{"i":41484,"as":"将无限投影纠缠对态变分框架扩展至费米子拓扑序，用于变分优化模拟费米子分数陈绝缘体。该框架此前已被广泛用于二维量子物质及包括手性自旋液体在内的玻色子拓扑序的模拟。","scd":{"b":8.0,"i":2.5,"r":7.0,"d":6.0,"t":9.0},"kp":["费米子分数陈绝缘体模拟方法[无限投影纠缠对态(iPEPS)]: 扩展变分方法以捕捉费米子拓扑序"]},{"i":41485,"as":"系统比较了基于密度泛函理论（DFT）扩展方法（如DFT+U和DFT+DMFT）中计算屏蔽库仑相互作用U值的两种途径：约束随机相位近似和线性响应理论，强调了使用真实U值对这些方法预测准确性的关键影响。","scd":null,"kp":["参数计算方法[DFT+U与DFT+DMFT的Hubbard参数U]: 约束随机相位近似与线性响应理论的系统化结合"]},{"i":41486,"as":"受AKLT模型启发，提出并求解了包含双线性和双二次项的扩展自旋-1 Kitaev链模型。在精确可解点，该模型的哈密顿量被重新表示为投影算符之和，并得到了精确的分数基态解。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":7.0,"t":8.0},"kp":["模型构建[自旋1扩展Kitaev链]: 包含双线性和双二次项的哈密顿量","基态特性[精确可解点(AKLT模型启发)]: 哈密顿量重构为投影算符之和并存在精确分数基态"]},{"i":41487,"as":"研究了共线亚铁磁体中对称破缺引发的手性磁振子混合现象。铁磁体中的磁振子由绕磁化方向的右旋进动定义，而反铁磁体在无外加磁场下左旋和右旋磁振子是简并的。亚铁磁体具有未补偿的磁矩，导致磁振子手性对称性破缺。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":8.0},"kp":["磁振子自旋[铁磁体]: 由围绕磁化方向的右旋进动定义的角动量","手性简并[反铁磁体(无外加磁场)]: 左旋与右旋磁振子能量简并","手性混合[共线亚铁磁体]: 对称破缺导致的手性磁振子混合"]},{"i":41488,"as":"实验研究了基于AlGaN/GaN二维电子系统的等离子体晶体在太赫兹频段的等离子体激元激发谱。该结构中容易观察到具有线性色散的屏蔽等离子体激元模式，而局域于狭缝间的非屏蔽模式表现出反常的反射相位特征。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":8.0},"kp":["等离子体激元色散[AlGaN/GaN二维电子系统(屏蔽模式)]: 线性色散","局域模式特征[AlGaN/GaN狭缝结构(未屏蔽模式)]: 局域于狭缝之间","反常相位[狭缝等离子体激元]: 反常反射相位"]},{"i":41489,"as":"","scd":null,"kp":[]},{"i":41490,"as":"","scd":null,"kp":[]},{"i":41491,"as":"","scd":null,"kp":[]},{"i":41492,"as":"","scd":null,"kp":[]},{"i":41493,"as":"","scd":null,"kp":[]},{"i":41494,"as":"","scd":null,"kp":[]},{"i":41495,"as":"","scd":null,"kp":[]},{"i":41496,"as":"","scd":null,"kp":[]},{"i":41497,"as":"首次在URhSn材料中直接观测到自发电子手性序的核磁共振（NMR）证据。这一发现发生于没有内在手性晶格结构的强关联材料中，从根本上挑战了电子手性必然需要手性晶体框架的现有观念。","scd":{"b":9.0,"i":1.0,"r":7.0,"d":5.0,"t":8.0},"kp":["[URhSn材料电子手性特征]: 首次在无内在手性晶格结构的材料中直接证实自发电子手性顺序"]},{"i":41498,"as":"","scd":null,"kp":[]},{"i":41499,"as":"报道了在含过量Fe的kagome晶格(Sc,Ti)Fe2材料中发现的显著负热膨胀现象（100-200 K时热膨胀系数为-32.4×10^-6 K^-1）。中子衍射和理论分析表明，钪含量影响层内反铁磁耦合，过量Fe稳定了铁磁序，加热导致的Fe子晶格磁矩急剧降低引发了负热膨胀。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":8.0,"t":8.0},"kp":["体膨胀系数[富铁Kagome(Sc,Ti)Fe2合金]: -32.4 × 10-6 K-1 (100-200 K)","负热膨胀物理机制[Sc/Ti含量的影响]: 钪含量通过影响自旋重定向显著降低局部力矩"]},{"i":41500,"as":"","scd":null,"kp":[]},{"i":41501,"as":"通过添加简单的化学添加剂（碱基苯并咪唑盐）成功对金属有机框架（MOF）玻璃的性质实现了改性。这种方法类似于调控传统无机玻璃，为调控MOF玻璃的结构与物理化学性质提供了新途径。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.0,"t":8.0},"kp":["材料性质调制方法[金属有机框架玻璃]: 添加碱基苯并咪唑盐类化学添加剂"]},{"i":41502,"as":"","scd":null,"kp":[]},{"i":41503,"as":"研究团队展示了一种基于Sn-Pb钙钛矿的突触场效应晶体管(FET)，能够实现高效的940nm近红外光传感和神经形态调控。该器件采用均匀且高结晶度的FASn0.8Pb0.2I3薄膜。研究通过引入分子添加剂1-溴-4-(甲基亚磺酰基)苯(BMSB)精确调控钙钛矿的结晶过程，扩大了晶粒尺寸，解决了高质量半导体薄膜成膜的难题，在高效人脸识别等神经形态光电领域展现出应用潜力。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":8.0},"kp":["探测与神经形态调制能力[Sn-Pb钙钛矿突触场效应晶体管]: 实现940 nm高效近红外光电传感","材料核心优势[Sn-Pb钙钛矿]: 窄带隙且具备稳健的近红外吸收能力"]},{"i":41504,"as":"研究人员以CPDT-BT为给受体骨架，设计了带有不同侧链的共轭聚电解质(CPE-K, CPE-Br, CPE-Zw)，并将其作为固态电解质栅极有机电化学突触晶体管(OEST)的沟道材料。光谱电化学测试表明，阳离子型CPE-Br由于聚合物内部高效的电解质离子扩散，比阴离子型和两性离子型实现了更高、更密集的掺杂水平，从而在OEST中实现了确定性的离子进入和良好的记忆保持能力。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":7.0,"t":8.0},"kp":["沟道材料[有机电化学突触晶体管]: 基于CPDT-BT给受体骨架的侧链工程化共轭聚电解质(CPE-K, CPE-Br, CPE-Zw)"]},{"i":41505,"as":"","scd":null,"kp":[]},{"i":41506,"as":"针对衰老过程中线粒体电子传递链(ETC)功能障碍导致的细胞衰老和骨再生受损问题，研究开发了一种线粒体供氢系统(EMHS)。该系统基于质子耦合电子转移(PCET)机制，其产生的活性氢渗入衰老细胞的线粒体，实现质子和电子等效物的成对递送。这能够原位恢复ETC相关的线粒体生物能学，逆转衰老相关表型，从而促进衰老骨骼的再生与愈合。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["递送系统[线粒体电子传输链重建]: 线粒体氢气供给系统(EMHS)"]},{"i":41507,"as":"研究开发了一种几何可编程的活体免疫材料，用于先天免疫信号的空间控制。利用DNA折纸技术精确编码双链DNA(dsDNA)的价键和间距，以促进cGAS聚集和STING激活。系统性测试发现最佳构型为周期约16.3 nm的60 bp dsDNA配体，其诱导的STING信号强度是游离dsDNA的两倍。该折纸结构进一步通过转运蛋白与益生菌大肠杆菌Nissle 1917整合，实现了活体免疫材料的构建。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["空间组装架构[cGAS-STING先天免疫信号控制]: 几何可编程DNA折纸"]},{"i":41508,"as":"软材料在抗疲劳与各向同性之间存在难以兼顾的挑战。研究发现鲢鱼鱼鳔具有非凡的各向同性抗疲劳性能，其疲劳阈值约为6000 J·m⁻²，极其接近其断裂韧性。这种优异性能源于其多层级纤维结构。与现有通过刚性增强或微结构排列等抑制裂纹但会引发各向异性的策略不同，鱼鳔的这种结构能够有效抵抗多方向载荷，为生物医学植入物和软体机器人材料设计提供了新思路。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["抗疲劳性能[鱼鳔软材料]: 本质非凡的各向同性抗疲劳性能"]},{"i":41509,"as":"为提升废旧锂离子电池中LiCoO2 (LCO)的直接回收效能，研究人员提出一种升级回收策略。利用废LCO的衰减特性作为跳板，通过晶格重构和离子交换诱导的相变，成功将其再生为具有O2-O3共生结构的新型LCO材料。这种共生架构克服了传统商业O3相LCO在高压下稳定性差的缺陷，显著提升了材料的高压稳定性和循环性能，使其满足现代储能系统的需求。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["升级回收工艺[废LiCoO2电池材料]: O2-O3共生相变升级回收"]},{"i":41510,"as":"研究在室温范德华铁磁体Fe3GaTe2中实现了一种节能的磁化切换技术。针对传统自旋霍尔材料在扭矩效率和能耗上的局限，该研究利用轻金属铬作为轨道电流源，实验验证了轨道霍尔效应(OHE)可以诱导产生自旋轨道扭矩(SOT)。与传统的自旋霍尔效应相比，基于OHE的切换在二维范德华磁性材料中展现出更高的能效，为开发二维SOT-MRAM存储器提供了直接实验支持。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["工作温度[范德华铁磁体Fe3GaTe2磁化切换]: 室温"]},{"i":41511,"as":"研究提出了一种利用光催化将有毒草甘膦废物升级回收为玉米生长复合肥的策略。通过使用具有不同主导晶面(001)、(010)和(102)的溴氧化铋(BiOBr)纳米片对草甘膦进行晶面依赖性光催化降解。光谱和理论分析表明，BiOBr-(010)和BiOBr-(102)通过增强电荷分离以及对羧基和磷酸基团的双重吸附实现了更快的降解，将废料转化为可用的复合肥料。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["废物转化[草甘膦废物处理]: 光催化降解并将其升级回收为玉米生长复合肥"]},{"i":41512,"as":"针对阻变存储器(RM)中实现类增量学习时面临的材料与算法不匹配问题，研究提出了一种自适应氧化还原编程方案。传统全编程方法通过反复读写验证来克服细丝RM器件的随机性，但能耗高且增加器件磨损。新提出的硬件-算法协同方案有效解决了这一高强度的写入更新难题，在保证网络模型稳健更新的同时，显著降低了能耗、延迟和器件磨损，推动了边缘AI的高效执行。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["算法-材料协同[类增量学习电阻式存储器]: 自适应氧化还原编程以克服细丝型器件的随机编程限制"]},{"i":41513,"as":"为解决锂金属全固态电池的界面不稳定问题，研究提出了一种基于纳米红磷的界面设计。该界面在与锂金属接触时能够自发产生化学润湿，原位形成富含Li3P的中间相，被称为自生化学润湿界面层。该反应层通过原位化学转化自主调节离子传输和界面粘附，产生均匀的锂离子通量和分布良好的界面电流，从而实现了高电流密度下稳定的锂沉积和剥离。","scd":{"b":8.0,"i":5.0,"r":7.0,"d":7.0,"t":6.0},"kp":["界面化学设计[锂金属固态电池]: 纳米红磷界面设计，接触锂时自发形成富Li3P界面相"]},{"i":41514,"as":"针对微米硅阳极在循环过程中超300%体积膨胀导致的应用瓶颈，研究提出了一种全新的离散微区键合(DMB)粘合剂范式。有别于传统依靠聚合物构建连续内部键合网络的策略，DMB系统利用离散分布的短链粘合剂分子，实现了对微米硅颗粒的精准锚定。这种机制能够有效适应并缓冲巨大的体积变化，使微米硅阳极在锂离子电池中表现出优异的机械坚固性和电化学稳定性。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["体积膨胀率[微米硅阳极循环过程]: 超过300%","粘合剂架构[微米硅阳极机械稳定性]: 离散微区键合粘合剂"]},{"i":41515,"as":"为了克服糖尿病伤口中耐药菌感染难以愈合的问题，研究人员构建了一种协同纳米平台。该平台将抗菌肽Indolicidin与光敏剂PTBT结合，并封装在温度敏感的F127水凝胶(PTBT/I@F127)中。此系统弥补了光动力疗法中活性氧(ROS)寿命短、扩散有限，以及抗菌肽结构不稳定、具有细胞毒性的缺陷，在水环境中形成均匀且高度光敏的纳米颗粒，从而显著增强了抗菌作用并加速了糖尿病伤口的愈合。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["ROS寿命[PDT产生的活性氧]: 10–320 ns","扩散范围[PDT产生的活性氧]: 10–55 nm","抗菌肽特性[高剂量条件]: 具有潜在细胞毒性"]},{"i":41516,"as":"为降低全球建筑能耗，研究设计了一种基于ITO/WO3/LiNbO3/NiO/ITO全薄膜堆栈的多光谱协同电致变色调节器。通过不对称法布里-珀罗(F-P)腔的器件架构，该调节器实现了三大大气窗口的多光谱正协同调节：在制冷模式下，同时反射阳光并在大气窗口具有选择性的高辐射率；在加热模式下，吸收阳光并保持低红外辐射率，有效改善了建筑围护结构的被动散热与保温性能。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["器件结构[电致变色多光谱调节器]: ITO/WO3/LiNbO3/NiO/ITO全薄膜叠层","器件架构[非对称光学设计]: Fabry–Pérot腔","调节特性[多光谱调节器]: 具有三大气窗口选择性"]},{"i":41517,"as":"光重整和光电重整技术是利用太阳能将废料转化为燃料和高附加值化学品的 promising 途径。与传统的热化学和生物过程不同，这些光催化和光电催化方法在温和条件下即可利用太阳能激活复杂的有机基底。人工光合合成领域在催化剂设计、反应工程和界面电荷动力学方面的最新进展有效提升了反应的选择性和效率，但在精确控制反应途径和抑制副反应方面仍存在根本性挑战。","scd":{"b":4.5,"i":2.0,"r":6.0,"d":3.0,"t":3.0},"kp":["反应条件[废物原料光重整和光电重整]: 温和条件","驱动力[光催化和光电催化过程]: 太阳能"]},{"i":41518,"as":"针对压电催化水分解制氢过程中极性弱和电荷分离动力学慢的难题，研究合成了一种强极性的羟基化Bi2O2CO3 (BOC)压电催化剂。该材料以非中心对称的平面[CO3]三角形和表面羟基为特征。BOC中排列整齐的非中心对称[CO3]三角形能够引起偶极矩的定向积累，产生强烈的自发极化；同时协同表面羟基化引发的几何电子不对称性，显著增强了应力条件下的电荷分离效率，从而促进了高效氢气演化。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["材料结构[强极性羟基化压电催化剂]: 非中心对称(NCS)平面三角形[CO3]","材料组成[压电析氢催化剂]: 羟基化Bi2O2CO3 (BOC)"]},{"i":41519,"as":"偏滤器托卡马克测试设施(DTT)是正在意大利Frascati建设的超导托卡马克装置，具备能量平衡级性能。其核心目标是开发未来聚变反应堆排热和排粒子的可行方案。该装置采用核芯-边缘集成的方法，评估排气方案与反应堆级核心性能的兼容性。由国际团队制定的DTT研究计划涵盖了该设施的程序目标、研究策略以及与装置特性相关的预期科学贡献。","scd":{"b":6.0,"i":5.0,"r":5.0,"d":4.0,"t":4.0},"kp":["装置类型[聚变研究设施]: 超导托卡马克","性能等级[DTT设施设计]: 达到能量平衡级别性能","研发目标[偏滤器托卡马克]: 开发热和粒子排出的可靠解决方案"]},{"i":41520,"as":"采用SOLPS-ITER边缘等离子体数值模型，对拟议中的欧洲体积中子源(EU-VNS)小型托卡马克装置的排气操作空间进行了评估。该研究允许注入氪气来耗散和重新分配热量，扩展了以往使用氩气的研究。结果表明，排气运行空间受到偏滤器等离子体面临部件峰值热通量工程极限的制约，同时需要保持足够低的核心有效电荷和电子温度。使用氪气注入不仅获得了比氩气更大的操作空间，还降低了氚的使用量。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["杂质注入[托卡马克排气运行空间拓展]: 氪(Kr)播撒","限制因素[EU-VNS装置运行空间]: 偏滤器等离子体面向组件的峰值热通量工程极限"]},{"i":41521,"as":"研究展示了JET(类似ITER壁)实验中由快离子与固有金属壁杂质反应驱动聚变性能的验证集成建模。通过射频加热氦(He)和氘(D)等离子体中的少数氢(H)，开发出以质子-铍聚变为主、中子产额高达6×10^x的稳态L模等离子体。该聚变反应通过中性粒子分析仪、快离子损失探测器和伽马射线诊断明确证实。研究构建了包含TRANSP、JETTO和LOCUST的集成建模框架，用于模拟质子-铍聚变链及高保真聚变产物源项。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":8.0,"t":4.0},"kp":["中子产额[稳态L模式质子-铍聚变]: 高达 6×10^x (具体量级受限于文本)","聚变驱动[JET He和D等离子体]: 射频加热H少数离子产生快离子与金属壁杂质反应"]},{"i":41522,"as":"在无边缘局域模(QH模式)的等离子体运行中，边缘局域模(ELM)被低频边缘谐波振荡(EHO)取代。利用KSTAR上的电子回旋辐射成像和宽带电子回旋辐射诊断，研究解析了EHO的本征模结构。EHO定域于 pedestal 最大压力梯度附近，沿离子抗磁方向传播，其径向包络随剪切增加而扩展，表明旋转剪切与EHO的结构演化密切相关。信息论中的传递熵分析揭示了EHO在边缘输运中的自调节机制。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["工作模式[无ELM的等离子体状态]: 静稳高约束模式(QH-mode)","振荡特性[边缘谐振现象]: 低频边缘谐波振荡(EHO)替代边缘局域模式(ELM)","空间分布[边缘谐波振荡]: 局限于台座区内部"]},{"i":41523,"as":"采用粒子追踪方法研究了EAST装置中锂弹丸诱发ELM产生的电磁扰动对钨离子传输动力学的影响。基于BOUT++三场模拟获取的电磁扰动数据，进行了钨离子的全轨道模拟。结果显示，漂移是ELM期间钨离子传输的主要驱动力，其中扰动的电场起到了主导决定作用。此外，弹丸沉积位置研究表明，沉积在台基顶部的弹丸对钨离子传输影响更显著。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["模拟方法[托卡马克中钨输运研究]: 粒子追踪全轨道模拟","扰动来源[Li弹丸诱导的ELM]: 基于BOUT++三场模拟的电磁扰动"]},{"i":41524,"as":"KSTAR装置安装钨偏滤器后，为未来反应堆的高性能长脉冲等离子体研究提供了平台。2023-2024年实验在钨偏滤器调试和实时控制方面取得进展。对比研究发现，相比碳偏滤器，钨偏滤器增加了芯部辐射损失并导致性能下降。通过优化中性束注入时间、硼粉播撒和气体喷吹杂质控制等策略，成功减少了钨积累并延长了等离子体持续时间。","scd":{"b":5.0,"i":6.0,"r":5.0,"d":6.0,"t":5.0},"kp":["核心部件[KSTAR新阶段升级]: 钨单块偏滤器","实验进展[2023-2024实验活动]: 实现等离子体运行场景的实时控制"]},{"i":41525,"as":"MAST-Upgrade偏滤器安装低温泵以增强密度控制、脱离前沿管理及杂质排除。带挡板的偏滤器室实现了偏滤器中性环境与主室的准隔离，允许局部调节中性压力而对上游等离子体密度影响极小。实验和SOLPS-ITER模拟证实，启动低温泵能在维持上游线平均密度不变的情况下降低偏滤器局部压力，促进等离子体贴壁并将脱离前沿拉近。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":6.0,"t":4.0},"kp":["密度控制及脱离管理[MAST-U偏滤器低温泵]: 提升密度控制、脱离前沿管理和杂质去除能力，并扩展至低密度运行空间","偏滤器中性环境隔离[紧密挡板偏滤器室]: 准隔离偏滤器中性环境与主室，实现对局部中性压力的微调且对上游影响极小"]},{"i":41526,"as":"研究了负离子中性束注入（N-NBI）系统束流传输中的空间电荷补偿（SCC）及其影响。背景气体与负离子碰撞产生的正离子能减轻空间电荷效应。基于Vlasov算法的3D模拟表明，SCC的演化与下游束流光学特性由背景气压和束能量共同控制。较高的气压和束能量能增强SCC效应，从而减轻束流发散，优化传输性能。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["空间电荷补偿(SCC)[负离子中性束注入系统(N-NBI)束流传输]: 正离子与背景气体碰撞产生的正离子 mitigate 空间电荷效应，影响束流发散和包络演化"]},{"i":41527,"as":"总结了J-TEXT托卡马克在三维磁场物理与应用方面的进展。通过升级ICRF系统和包含谐振磁扰动线圈、岛偏滤器线圈等先进3D磁场线圈，开展了对MHD不稳定性、破裂和输运的研究。关键发现是，新经典撕裂模（NTM）触发了电子内部输垒的形成，其中磁岛与湍流发生非线性相互作用，成功抑制了输运并使芯部温度梯度变陡。","scd":{"b":6.0,"i":5.0,"r":6.0,"d":6.0,"t":5.0},"kp":["硬件升级[J-TEXT托卡马克3D磁场系统]: 新增ICRF系统及包含共振磁微扰(RMP)线圈、岛偏滤器(ID)线圈和外旋转变换(ERT)线圈的先进3D磁场线圈系统"]},{"i":41528,"as":"提出了一种基于表面氧化还原介导的化学循环策略，在钴钼双金属氮化物（Co3Mo3N）载体上，利用CO2加氢反应作为触发器，在常压下驱动合成氨。机理研究表明，CO2引发动态表面氧化，削弱了Mo-N键，促使晶格氮加氢并释放出氨。随后的氮化步骤去除了表面氧并再生了氮载体，完成整个催化循环。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["合成氨条件[CO2耦合加氢化学链策略]: 常压","合成氨催化剂[表面氧化还原介导化学链]: 钴钼双金属氮化物(Co3Mo3N)"]},{"i":41529,"as":"通过调节小分子受体中硫原子的数量，设计了CHSMe等四种受体材料。这些受体凭借分子间强烈的C-H···S和C═S···S非共价相互作用，形成了清晰的双分子结构单元。单晶X射线衍射分析证实，硫原子参与了多重分子间非共价相互作用。这种多重非共价组装策略有效解决了分子排序受限和激子结合能高的问题，使有机太阳能电池的能量转换效率接近21%。","scd":{"b":7.0,"i":5.0,"r":7.0,"d":8.0,"t":6.0},"kp":["能量转换效率[多重非共价组装二聚体受体有机太阳能电池]: 接近21%","分子结构设计[小分子受体(CHSMe, CHSPh, CH2SPh, CHDF)]: 调节硫原子数量，通过强分子间C-H···S和C═S···S非共价相互作用形成清晰的双分子结构单元"]},{"i":41530,"as":"开发了一种由分层有序多孔碳基质负载的双官能团钴单原子催化剂（Co-N4/HPC），利用甲酸还原剂，实现了末端烯烃与硝基苯和甲醛的羟氨甲基化反应。该反应具有原子经济性高、底物范围广、选择性好及催化剂可重复使用等优点。机制表明，Co-N4位点负责介导温和还原，而介孔氮掺杂碳载体则富集甲醛，两者协同实现了大宗化学品向γ-芳基氨基醇的高效合成。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":5.0},"kp":["催化剂[末端烯烃双官能化合成γ-芳基氨基醇]: 负载在分级有序多孔碳基质上的双功能单原子钴催化剂(Co-N4/HPC)","反应体系[非活化末端烯烃的羟氨基甲基化]: 使用硝基芳烃和甲醛作为反应物，甲酸(HCOOH)作为还原剂"]},{"i":41531,"as":"探讨了量子点与维氏固氮菌杂交体系中，碳源介质对光驱动固氮产氨的影响。在光照下，杂交体系膜极化增加，胞内NADH/NAD+和ATP水平升高。质子载体对产氨的强烈抑制表明该过程依赖ATP的固氮酶催化。在富含蔗糖的培养基中，杂交体系能够长期维持胞外铵根离子的积累，实现环境条件下的可充电光驱动产氨操作。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["光合固氮系统[量子点-维氏固氮菌杂化物]: 在环境条件下实现氮气(N2)转化为氨(NH3)","长期氨生产控制机制[碳介导体系]: 培养基的碳状态主导着光驱动的胞外NH4+积累和长期生产过程"]},{"i":41532,"as":"发现λ核酸外切酶的一种拓扑特性，即两端带有5'磷酸的双链底物可经历自持的循环切割-重构过程，实现无外部扩增的信号更新。结合CRISPR/Cas13技术，设计了隐藏5'磷酸的拓扑门控哑铃探针。目标RNA识别后，Cas13特异性切割发夹环暴露出磷酸，从而激活λ核酸外切酶介导的信号放大。该机制有效解决了CRISPR-RNA诊断中无扩增信号增强的难题。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":6.0,"t":6.0},"kp":["信号放大机制[拓扑门控λ核酸外切酶]: 两端带有5'磷酸基团的双链底物经历自持的循环切割-重构过程，实现无扩增的信号更新"]},{"i":41533,"as":"通过量子力学/分子力学元动力学模拟，揭示了微滴中CO2和NH3在常温常压下自发形成尿素的离子对介导途径。CO2与两个NH3分子反应，生成稳定的H2NCOO-⋯NH4+离子对中间体，该步骤的活化能仅为约9.4 kcal/mol。此外，微滴气-水界面的固有电场（约0.1 V/Å）进一步降低了反应能垒，合理解释了微滴环境下高效生成尿素的分子机制。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":7.0,"t":6.0},"kp":["尿素合成机制[微滴界面的CO2和NH3]: 离子对介导路径，在环境条件下无需催化剂或外部能量输入自发形成尿素，且具有低活化能垒"]},{"i":41534,"as":"结合物理建模、学习曲线和生命周期可持续性评估，提出了“氨彩虹”分类框架，评估了8种制氨技术的净零排放转型。模型表明，假设全球氨需求翻倍以满足粮食和能源需求，在当前任何政策或技术情景下，均无法在2050年前实现净零氨排放。即使乐观部署绿氨等环保路线，也将消耗超过40%的可用绿氢，并需要依赖大量的碳捕获基础设施。","scd":{"b":5.0,"i":5.0,"r":7.0,"d":8.0,"t":5.0},"kp":["分类评估框架[净零氨技术评估]: 结合基于物理的建模、学习曲线分析和生命周期可持续性评估的“氨彩虹”分类体系"]},{"i":41535,"as":"","scd":null,"kp":[]},{"i":41536,"as":"","scd":null,"kp":[]},{"i":41537,"as":"通过金(III)叠氮络合物的光化学挤出N2反应，在晶体中成功捕获了难以捉摸的金氮宾。计算研究证实其具有三重基态，且这种金氮宾能够与氧气、一氧化碳、醛和炔烃发生反应。这一发现确立了金作为进行氮宾原子转移化学反应的可行平台。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["金氮宾捕获[金(III)叠氮络合物]: 通过光化学挤出N2在晶体中捕获","基态与反应性[金氮宾]: 确认具有三重态基态，且对O2、CO、醛和炔烃具有反应性"]},{"i":41538,"as":"构建了一种名为PLAQ-SCAN的近红外“AND”逻辑门控双锁荧光探针，用于同时感应超氧阴子和粘度。其荧光开启严格依赖这两种刺激的共存，精准匹配早期动脉粥样硬化中巨噬细胞脂质摄取与氧化应激形成的“双重失调”微环境。这种设计有效避免了单一刺激引发的假阳性信号，实现了对早期动脉粥样硬化斑块的精准实时监测。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":5.0},"kp":["荧光探针[早期动脉粥样硬化监测]: “AND”逻辑门控近红外双锁探针PLAQ-SCAN","感应机制[复杂微环境化学与物理变化]: 同时感应超氧阴离子和粘度"]},{"i":41539,"as":"提出了一种基于稀土离子掺杂手性钙钛矿量子点的手性量子切割策略，成功在985纳米处实现强烈的近红外圆偏振发光。该量子点同时表现出高达0.092的大不对称因子和157.2%的高光致发光量子产率（PLQY）。其优异的优值（FM = |glum| × PLQY）达到0.145，刷新了已报道手性钙钛矿的最高纪录。飞秒瞬态吸收光谱证实了超快能量转移过程。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":7.0,"t":5.0},"kp":["发射波长[手性量子切割策略]: 985 nm","材料体系[稀土离子掺杂]: 手性钙钛矿量子点","光学特性[突破能隙定律限制]: 实现近红外区高荧光量子产率(PLQY)与大的不对称因子(glum)"]},{"i":41540,"as":"首次成功合成了块体铯银碘化物双钙钛矿半导体，包含微晶和薄膜形态。通过纯相Cs2AgBiBr6微晶的阴离子交换法制备出微晶粉末。这种无铅卤化物吸收层在整个可见光谱范围内表现出宽泛的吸收，其光学带隙为1.70 ± 0.05 eV，并在1.03 eV处表现出近红外光致发光特性，克服了先前的热力学不稳定性合成难题。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":7.0,"t":5.0},"kp":["材料合成[无铅卤化物钙钛矿]: 块状Cs 2 AgBiI 6","材料形貌[首次合成]: 微晶与光电导薄膜"]},{"i":41541,"as":"探讨摩擦学领域对能够自我进化、智能优化的研究平台的需求，可能涉及人工智能在摩擦磨损研究中的应用。","scd":{"b":3.0,"i":2.0,"r":3.0,"d":3.0,"t":3.0},"kp":["研究平台[摩擦学领域]: 需具备自我进化与智能优化能力"]},{"i":41542,"as":"","scd":null,"kp":[]},{"i":41543,"as":"在一维关联玻色子对称保护拓扑（SPT）相中提出了一种非阿贝尔统计新范式。研究表明，由实哈密顿量描述的玻色SPT相，其拓扑零模的对称保护非阿贝尔统计可分为截然不同的两类：第一类表现出硬核玻色子零模的传统编织；第二类则表现出以非线性变换为特征的非常规编织统计，体现了第一类的分数化特征。该发现丰富了拓扑量子计算的方案。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":6.0,"t":5.0},"kp":["量子统计机制[一维关联玻色对称保护拓扑(SPT)相]: 玻色对称保护拓扑相的非阿贝尔(SPNA)统计","应用前沿[拓扑量子计算]: 丰富了拓扑量子计算的方案"]},{"i":41544,"as":"","scd":null,"kp":[]},{"i":41545,"as":"直接空气捕获（DAC）技术是实现大规模碳去除的有效途径，但其部署面临工程挑战。研究总结了DAC扩大规模的四个关键瓶颈：接触器设计、热管理、水管理和系统耦合。通过技术经济分析将这些环节相连，指明了加速实现DAC碳捕获目标的关键路径。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":["技术瓶颈[直接空气捕获(DAC)规模化放大]: 接触器设计、热管理、水管理系统耦合"]},{"i":41546,"as":"神经丝轻链（NFL）蛋白组装成丝状网络，其无序尾部结构对维持神经元完整性至关重要。研究发现，与腓骨肌萎缩症（CMT）相关的NFL尾部突变会导致水凝胶结构压缩，通过产生微域破坏丝状向列有序性，并改变水分特征，从分子层面揭示了突变对自组装网络的重塑机制。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["突变效应[神经丝光尾部无序突变]: 重塑自组装网络结构并改变向列型水凝胶形成"]},{"i":41547,"as":"通过计算引导设计了装饰有金纳米片的铁蛋白纳米笼。这种生物活性纳米结构在全身给药后，能够选择性地解聚阿尔茨海默病中的纤维状淀粉样蛋白-β斑块，有效降低淀粉样蛋白负荷，并改善小鼠模型的突触和认知功能。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["纳米结构[计算引导设计]: 金纳米片修饰的铁蛋白纳米笼","药理机制[阿尔茨海默病小鼠模型]: 系统给药后选择性解聚纤维状淀粉样-β斑块，改善突触和认知功能"]},{"i":41548,"as":"研究开发了能够空间和能量上对齐氧化还原中心的代谢物响应型纳米杂合物。该纳米杂合物能够量化细胞外囊泡的动态生物能量特征，并成功绘制出肿瘤微环境中的代谢变化图谱，揭示了细胞外囊泡的催化谱图对癌症代谢的调节作用。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":4.0},"kp":["纳米杂化物[细胞外囊泡检测]: 代谢物响应型","催化谱图机制[肿瘤微环境代谢监测]: 空间与能量上对齐氧化还原中心"]},{"i":41549,"as":"各国在设计绿色产业政策时，识别未来具有优势的能源技术至关重要。通过全面评估技术特征，政策制定者能够有策略地挑选出具备全球成本竞争力且能为国内带来经济回报的胜出技术，从而推动技术智能型绿色产业政策的发展。","scd":{"b":1.0,"i":2.0,"r":5.0,"d":4.0,"t":3.0},"kp":["政策制定[绿色产业政策]: 需识别并战略选择具备全球成本竞争力和国内经济回报的获胜能源技术"]},{"i":41550,"as":"研究探讨了钠氧键离子性对钠层氧化物阴极产气行为和晶格稳定性的影响。在NaNiO2中引入5%的锂或钾发现：钾取代会增加气体逸出；而锂取代在仅降低16%容量的情况下，可将产气量减少近80%，揭示了通过感应效应调节阴极稳定性的关键机制。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":8.0,"t":4.0},"kp":["掺杂比例[层状NaNiO 2改性]: 引入5%的锂(Li)或钾(K)","晶格稳定性调控机制[钠层状氧化物阴极]: 通过调节钠-氧键离子性来抑制产气"]},{"i":41551,"as":"利用反芳香性作为分子设计原理，在低能量激发下增强手性光学响应。将平面反芳香性s-茚烯核心与[5]螺旋烯支架融合，构建出的手性系统在短波近红外区表现出显著的不对称因子。分析表明，反芳香性环流电流使前沿激发态偏向增强的磁性贡献。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["设计原理[增强磁手性光学各向异性]: 反芳香性","分子构建[低能量激发态]: 将平面顺磁s-茚(4nπ)核心与[5]螺烯支架融合"]},{"i":41552,"as":"使用2-卤代苯并呋喃和吲哚作为新型卤素氧化剂，实现碱促进的苄基C-H键直接胺化反应。该反应利用卤素转移活性，将去质子化、卤化和亲核取代协同合并。热力学上不利去质子化步骤产生的中间体，有效避免了金属化-卤化过程中常见的二聚化问题。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["氧化剂[苄基C-H胺化反应]: 2-卤代苯并呋喃和吲哚","碱和亲核氨源[合成伯苄基胺]: 六甲基二硅氮烷(HMDS)"]},{"i":41553,"as":"水泥和混凝土支撑着现代社会，但对其真实的资源需求及高效使用的动力学机制仍知之甚少。最新研究表明，推动建筑材料效率和可持续性变革的最强有力杠杆，实际上并不在水泥工厂内部，而在于其他未被充分关注的环节。","scd":{"b":2.0,"i":4.0,"r":5.0,"d":3.0,"t":3.0},"kp":["变革关键驱动力[建筑环境水泥与混凝土资源利用]: 可能不在水泥厂内部环节"]},{"i":41554,"as":"","scd":null,"kp":[]},{"i":41555,"as":"在基于芘的锆氧金属有机框架（MOF）NU-1000中实现了光诱导质子耦合电子转移（PCET）过程。该人工光合系统I在单重态流形中运行，无需任何助催化剂即可直接生成NADH模型类似物以及[Zr氧节点]离子对，成功复刻了自然光合作用的电子转移机制。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["光系统I模拟[Zr-金属-有机框架]: 芘基锆氧金属有机框架中的光诱导质子耦合电子转移(PCET)过程"]},{"i":41556,"as":"","scd":null,"kp":[]},{"i":41557,"as":"","scd":null,"kp":[]},{"i":41558,"as":"利用超高真空扫描隧道显微镜和光谱学，对胶体法合成的金纳米立方体实现了原子级成像。在去除液相配体后，观察到立方体顶面存在未重构的Au(100)-(1×1)表面。退火后会出现准六边形重构畴区，同时光谱在+1.2 eV附近揭示了未重构表面的表面态共振。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["表面结构[湿法合成的金纳米立方体]: 未重构的Au(100)","表征手段[单个湿法合成金纳米立方体]: 超高真空扫描隧道显微镜和光谱学"]},{"i":41559,"as":"研究揭示了人类和小鼠在不确定性决策中存在的“稀有性偏差”，即稀有事件对后续决策产生更强且持久的影响。光遗传学操作表明，后顶叶皮层（PPC）在未受训阶段会驱动该偏差并干扰最优决策，而在专家阶段，PPC则成为基于刺激的决策过程的关键基础。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["后顶叶皮层(PPC)功能[未学习阶段]: 驱动稀有性引起的决策偏差并干扰最优决策"]},{"i":41560,"as":"","scd":null,"kp":[]},{"i":41561,"as":"一种受日本传统宝塔结构启发而设计的建筑新技术“移动地板”，通过特定的建筑设计机制吸收和耗散动能，能够有效防止现代高层建筑在强风环境中发生剧烈摇晃，从而提升高层建筑的抗风安全性。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":["防风抗震设计[现代高层建筑结构]: 借鉴日本传统塔式建筑(塔心柱原理)的移动地板设计"]},{"i":41562,"as":"利用局部活性空间框架内的多参考方法，成功解析了双中心过渡金属团簇AlM2O4+（M = Fe, Co）的红外光解离光谱。研究确定了其低能结构及基态电子排布，证实实验观测到的光谱是由不同异构体及其电子态共存所产生的，解决了以往难以准确分配振动光谱的难题。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[AlM2O4+ (M = Fe, Co)结构]: 振动光谱分配受配体场分裂、自旋耦合、结构及价态异构化的共同影响"]},{"i":41563,"as":"化石燃料勘探技术正推动石油和天然气钻探活动向海洋最深处转移。面对深海油气开发，工程团队必须采取严格的工程技术手段与防范措施，以确保将深水作业带来的海洋生态风险控制在可管理的极低水平之内。","scd":{"b":2.0,"i":4.0,"r":5.0,"d":3.0,"t":4.0},"kp":["化石燃料勘探[深海钻探技术]: 正向海洋最深部分转移且需控制生态风险"]},{"i":41564,"as":"","scd":null,"kp":[]},{"i":41565,"as":"空间转录组学技术在学术界和工业界的反馈循环推动下持续发展。该技术在过去十年中通过绘制组织中的基因表达图谱，极大地提升了人类对生物体发育过程以及疾病机制的认知与理解。","scd":{"b":5.0,"i":5.0,"r":6.0,"d":4.0,"t":3.0},"kp":["转录组学技术[空间分辨基因表达图谱绘制]: 持续通过学术界与工业界的反馈循环增强对发育和疾病的理解"]},{"i":41566,"as":"","scd":null,"kp":[]},{"i":41567,"as":"月之暗面公司表示，其最新的人工智能模型“Kimi K3”能够匹配甚至超越当前最前沿的模型性能。然而，由于该模型参数规模过于庞大，这可能会限制其在实际应用中的普及和采纳率。","scd":{"b":8.0,"i":5.0,"r":6.0,"d":5.0,"t":7.0},"kp":["模型性能[文本模型Kimi K3]: 能够匹敌或超越前沿模型","模型限制[Kimi K3]: 庞大的模型规模可能会限制其采用率"]},{"i":41568,"as":"《自然》杂志调查了读者对于科研工作的热爱之处。科学家们表示，尽管在工作中广泛使用聊天机器人，但他们拒绝将工作中带来的核心快乐和特定职责移交给人工智能。","scd":null,"kp":[]},{"i":41569,"as":"研究揭示了镰刀菌中细胞分裂素（CKs）独特的生物合成与失活途径。该过程核心逻辑包括：融合酶FexA催化AMP生成iP；CYP450酶FexB将其羟化生成植物型CKs并催化环化产生吡咯衍生物；后续还有BBE样氧化酶参与。这解析了真菌病原体中CKs的酶学机制。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":["催化机制[镰刀菌细胞分裂素生物合成]: IPT-LOG融合酶FexA催化N6-二甲基烯丙基化"]},{"i":41570,"as":"研究开发了一种光氧化还原催化的转氨基策略，无需预功能化即可实现胺到胺的直接转化。反应通过极性反转途径，将胺转化为亲电亚胺离子中间体再与另一胺亲核试剂偶联。该方法适用于苄基、未活化和叔胺，且选择性与亲核性及空间位阻有关。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":["适用范围[烷基胺亲核转氨基]: 苄基、未活化和叔胺"]},{"i":41571,"as":"研究报道了一种通过双环氧化物与由天然氨基酸衍生的二醇进行线性逐步聚合，温和且原子经济地合成聚醚酰胺（PEAs）的方法。在含多种质子的系统中，路易斯碱对催化剂的化学选择性实现了对环氧开环的优先活化，为制备主链含酰胺基团的聚合物提供了新路径。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["聚合方法[聚醚酰胺合成]: 氨基醇原位形成含酰胺二元醇与二环氧化物的温和、原子经济性线性逐步聚合"]},{"i":41572,"as":"研究开发了一种集成了密度泛函理论、机器学习和自动化实验的高通量工作流，用于稀土元素的pH控制溶剂萃取分离。筛选确认草酰乙酸为有效的水相阻尼剂，结合D2EHPA萃取剂，成功实现了对Nd、Eu、Dy、Ho四种镧系元素的选择性高效提取。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":8.0,"t":5.0},"kp":["分离策略[稀土元素选择性分离]: pH控制溶剂萃取结合水相阻萃剂"]},{"i":41573,"as":"研究结合计算分子设计与定向进化，开发了小分子调控的生物正交化学脱笼技术，用于在活体系统中精确调节带负电的天冬氨酸和谷氨酸侧链。通过构建对叠氮苄基天冬氨酸（PABD），克服了传统光触发脱笼在穿透深度限制和潜在光损伤方面的应用缺陷。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["调节对象[生命系统中带负电蛋白质侧链]: 天冬氨酸和谷氨酸侧链"]},{"i":41574,"as":"研究利用变温瞬态吸收光谱等技术，分析了茚并茚并二苯并噻吩双自由基的激发态弛豫动力学。实验发现，非前沿轨道和前沿轨道跃迁吸收中存在明显的振动量子化，揭示了电子激发与分子振动之间的强烈自旋振动耦合，并确认了多步激发态弛豫过程。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["分子结构特性[茚并茚并二苯并噻吩双自由基]: syn型和anti型结构"]},{"i":41575,"as":"天文学家发现了一颗名为“Beta Pictoris d”的系外行星，这是地球上迄今发现的最暗的行星。发现该行星所使用的观测方法有望在未来帮助天文学家揭示其他隐藏在明亮恒星光芒下的极其暗淡的系外行星。","scd":null,"kp":[]},{"i":41576,"as":"研究开发了一种在泡沫镍上直接生长的缺陷工程FeMoO4/CeS2双相电催化剂，用于常温电催化合成氨。优化的2-FeMoCe催化剂在-0.70 V vs RHE条件下，氨产率和法拉第效率分别高达5124 μg cm-2 h-1和46%，并在膜分离单叠电池配置中表现出持续强劲的性能。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["电催化剂[常温电催化氨合成]: 缺陷工程FeMoO4/CeS2双相","最佳比例[电催化氮还原反应]: Fe:Mo:Ce = 2:4:1"]},{"i":41577,"as":"研究通过溶剂热条件下的席夫碱缩合反应，合成了三种富含氮、缩醛胺连接的多孔有机聚合物。其中TBAL-POP-5表现出最佳性能，具有1053 m2 g-1的比表面积、84%的分级介孔比例，并在273 K条件下展现出1.92 mmol g-1的二氧化碳高吸附容量，能同时捕获并转化CO2。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["多孔有机聚合物[CO2捕获与转化]: 富氮缩醛胺连接的多孔有机聚合物 (TBAL-POP)"]},{"i":41578,"as":"研究开发了一种含二硫键的自组装多肽无载体纳米药物，作为简化配方并最大化治疗效果的抗癌制剂。该纳米颗粒能响应肿瘤内谷胱甘肽并聚集，通过消耗谷胱甘肽、抑制SLC7A11和GPX4诱发脂质过氧化，从而引发铁死亡和二硫死亡，实现双重氧化还原癌症治疗。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["纳米药物机制[核心成分]: 含二硫键自组装肽Fmoc-Cys(StBu)-Phe-Phe-Tyr-Lys-Cys(StBu)","纳米药物形态[自发组装]: 均匀球形纳米颗粒","纳米药物特性[体内行为]: 具有良好的血液相容性、谷胱甘肽响应性结构转变和增强的肿瘤聚集能力","治疗机制[双重氧化还原癌症疗法]: 协调诱导铁死亡和二硫死亡"]},{"i":41579,"as":"研究通过金(III)叠氮配合物的光化学脱氮反应，成功分离并表征了一种真正的光环-氮烯。晶体和固态分析揭示了其多样化的反应特性，包括通过氧气活化实现的氮烯到硝基的转化，以及分子内和分子间的C-H键活化反应，推进了金介导的原子转移化学。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["光化学催化[反应物]: 光化学产生的氮烯","催化剂体系[C-N键形成]: 金","反应中间体[金介导氮烯转移]: 金杂氮烯"]},{"i":41580,"as":"研究通过将二维MXene纳米片掺入聚醚砜（PES）支撑层并界面聚合聚酰胺，制备了新型薄膜复合正向渗透（FO）膜。表征证实MXene的加入有效改善了膜的亲水性和表面形貌，解决了传统FO膜水通量低、内部浓度极化和膜污染问题，显著增强了对垃圾渗滤液中PFAS的去除能力。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["膜材料结构[复合薄膜制备]: 在聚醚砜(PES)支撑层中掺入MXene纳米片后通过界面聚合形成聚酰胺活性层","膜改性材料[正向渗透膜]: 二维过渡金属碳化物MXene纳米片","技术目标[正渗透技术]: 增强水通量并高效去除垃圾渗滤液中的PFAS"]},{"i":41581,"as":"研究将季戊四醇四(3-巯基丙酸酯)（PETMP）引入CsPbI2Br钙钛矿前驱体溶液中，成功在环境空气中组装高效太阳能电池。PETMP与CsPbI2Br的配位作用减缓了结晶过程，其还原性-SH基团有效抑制了氧气触发的碘化物氧化，显著提升了常温处理的钙钛矿太阳能电池的效率和稳定性。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["添加剂[前驱体溶液]: 季戊四醇四(3-巯基丙酸酯)(PETMP)","添加剂作用[空气处理CsPbI2Br钙钛矿]: 协同抑制碘化物氧化和调节结晶过程","制备环境[钙钛矿太阳能电池]: 空气环境处理"]},{"i":41582,"as":"研究使用极紫外光刻技术制造晶圆级过渡金属通道，涉及先进半导体器件制造与新型沟道材料应用。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":3.0,"t":6.0},"kp":["制造工艺[晶圆级过渡金属通道]: 极紫外光刻技术"]},{"i":41583,"as":"介绍一种具有3纳米超薄铪锆氧化物层的铁电电容器，涉及先进铁电存储器材料及微电子器件技术。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":4.0,"t":6.0},"kp":["厚度[铁电电容器铪锆氧化物层]: 3纳米","器件类型[超薄铪锆氧化物层]: 铁电电容器"]},{"i":41584,"as":"提出一种用于智能电网的因果推理框架，并将其应用于需求响应管理，涉及数据驱动的电力系统优化。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[智能电网需求响应管理]: 采用因果推理框架"]},{"i":41585,"as":"利用天然气网络的全局线性端口模型来加速电-气综合能源系统的能量流分析，涉及电力系统仿真计算。","scd":{"b":4.0,"i":2.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[电-气综合能源系统能量流分析]: 利用全局线性端口模型加速计算"]},{"i":41586,"as":"评估在含水层驱动的储层中实现大规模地下储氢的技术与经济可行性，涉及清洁能源储存与地质工程。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":5.0,"t":5.0},"kp":"[含水层驱动储层]: 实现大规模地下储氢技术与经济可行性评估"},{"i":41587,"as":"提出一种基于随机森林的PEMFC（质子交换膜燃料电池）冷启动电化学阻抗快速测试替代方法。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":"[PEMFC冷启动条件]: 基于随机森林特征频率提取的替代实验引导快速EIS测试方法"},{"i":41588,"as":"通过3D多物理场建模和电压击穿分析，揭示高性能干阴极阴离子交换膜水电解（AEMWE）的设计原理。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":"[高性能干阴极AEMWE]: 3D多物理场建模和电压击穿分析揭示设计原理"},{"i":41589,"as":"为解决骨肿瘤切除后的骨缺损修复难题，研究设计了一种涂覆超薄Nb2C MXene纳米片的3D打印多孔氮化硅支架（MPSNS）。该仿生多功能支架通过改变表面物理化学性质增强了生物相容性，既能利用光热效应精准消除残留肿瘤细胞，又能有效驱动骨缺损重建。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["支架结构[骨肿瘤治疗]: 掺杂超薄铌碳化物(Nb2C MXene)的3D多孔氮化硅(Si3N4)支架","功能特性[多功能生物支架]: 具有光热消融残余肿瘤细胞并同时驱动骨缺损重建的双重功能"]},{"i":41590,"as":"研究在聚酰亚胺柔性基底上生长了高质量Pt/CoPt/Ru/CoTb合成反铁磁体，实现了室温下的自旋轨道力矩（SOT）无场垂直磁化翻转。3%的拉伸应变导致层间交换耦合场偏移390 Oe，并使无场SOT翻转比例降至约28%。该器件在无磁场下展现出近线性的非易失性突触可塑性和神经元非线性。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["无场切换机制[聚酰亚胺基底自旋电子学]: 自旋轨道力矩(SOT)驱动的垂直磁化翻转","磁性薄膜结构[柔性合成反铁磁体]: Pt/CoPt/Ru/CoTb","薄膜特性[室温补偿磁化强度]: 高质量且展现室温下的补偿磁化"]},{"i":41591,"as":"光系统修饰电极被开发用于将太阳能转化为化学能或电能。光系统作为天然光合作用中的光活性蛋白质，具有极高的光捕获效率、显著的电荷分离能力，且完全由地球储量丰富的元素组成。其主要局限性在于稳定性有限及难以与电极实现高效界面结合。综述回顾了将光系统II、光系统I和细菌反应中心三大类光系统整合到功能器件中的策略，并探讨了生物光电阳极、生物光电阴极等电极架构及其组装成生物光电化学器件的方法。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":4.0,"t":3.0},"kp":["光电器件[太阳能转换体系]: 基于光系统的生物光电极","光活性材料[生物光电极]: 自然光合作用的光活性蛋白质（光系统）"]},{"i":41592,"as":"针对锂离子电池在低温下受限于去溶剂化动力学迟缓和电极界面不稳定的问题，研究开发了一种无氟化溶剂的低温电解液FBN-442。该电解液包含1.0m混合盐（LiFSI/LiODFB比例为7:3）、0.15m的LiNO3添加剂以及丙酮、醋酸甲酯和碳酸亚乙烯酯混合溶剂。丙酮促进盐解离，醋酸甲酯提供适中的锂离子亲和力和低熔点，碳酸亚乙烯酯促成有效成膜。该优化的溶剂化结构平衡了体相离子传输与界面电荷转移动力学。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":8.0,"t":4.0},"kp":["电解液配方[低温电解液FBN-442]: 1.0 m盐(LiFSI/LiODFB = 7:3)与0.15 m LiNO3添加剂溶于丙酮、醋酸甲酯和碳酸亚乙烯酯混合溶剂","电解液特性[无氟溶剂低温电池]: 无氟化溶剂、改善低温去溶剂化动力学且构建稳定电极界面"]},{"i":41593,"as":"为克服二维层流膜在渗透性与选择性上的制约，研究提出了一种针对还原氧化石墨烯膜的纳米级“缺陷挖掘”策略，在分子水平上构建双重传输路径。利用温和的KOH蚀刻垂直纳米孔，选择性针对易产生缺陷的sp3杂化碳域，在层状结构中开辟高速捷径。同时引入离子液体插层的热力学稳定步骤，通过强阳离子-π相互作用锚定并扩展层间距。这种协同整合成功打破了渗透率与选择性的权衡限制。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":["刻蚀工程[氧化石墨烯膜]: 纳米级缺陷选择性刻蚀策略","造孔机制[rGO膜垂直纳米孔]: 通过KOH温和刻蚀选择性靶向易出现缺陷的sp3杂化碳域","膜分离性能[二维层状膜]: 克服渗透性与选择性的权衡限制"]},{"i":41594,"as":"针对胰腺导管腺癌（PDAC）高度纤维化的细胞外基质（ECM）及应激诱导的神经免疫串扰导致的免疫治疗抗性，研究开发了一种超声响应仿生纳米载体（CT@SM）。该载体包载β受体阻滞剂卡维地洛和aTIM-3，外层覆有Pan02肿瘤细胞膜以实现同源靶向并延长循环。嵌入的蔗糖用于调节声阻抗，在超声激发下产生惯性空化效应。超声触发的空化作用有效破坏ECM，使药物深入肿瘤内部释放。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["纳米载体[超声响应仿生纳米颗粒CT@SM]: 蔗糖杂交的Pan02胰腺肿瘤细胞膜包覆载体","负载药物[胰腺导管腺癌免疫治疗]: 卡维地洛(β受体阻滞剂)与aTIM-3","治疗机制[应激下PDAC免疫治疗]: 通过超声响应释药阻断交感神经-T细胞相互作用"]},{"i":41595,"as":"为解决碳酸氢盐溶液电催化转化过程中难以在宽pH范围内维持高法拉第效率（FE）的问题，研究在质子交换膜（PEM）和铋基阴极电催化剂之间引入了混合纤维素酯多孔膜。该结构促使电解槽内的碳酸氢根离子发生质子化，生成原位CO2直接用于电还原，显著提高了甲酸盐的法拉第效率。研究探讨了该中间多孔膜的作用及不同纤维素材料在电流密度超过100 mA cm-2时的电解性能表现。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":8.0,"t":4.0},"kp":["Faradaic efficiency[碳酸氢盐电化学转化制甲酸盐]: 通过引入混合纤维素酯多孔膜得到增强","核心材料配置[Bi阴极与PEM之间]: 混合纤维素酯(MCE)多孔膜"]},{"i":41596,"as":"为提升光电化学水分解效率，研究展示了一种由NiSe2纳米颗粒助催化剂修饰的WO3光电阳极。WO3半导体与金属NiSe2之间形成的异质结极大地提升了器件性能。在最优NiSe2负载量下，WO3/NiSe2光电阳极在1.23 V（相对于可逆氢电极）的可见光照射下，获得了1.66 mA cm-2的光电流密度，超过纯WO3光电阳极性能七倍以上。其优异的性能归因于异质结改善了电极与电解液界面的电荷载流子转移效率。","scd":{"b":6.0,"i":3.0,"r":4.0,"d":7.0,"t":5.0},"kp":["光阳极[光电催化水分解]: NiSe2纳米颗粒修饰的WO3","异质结[提升电荷分离与传输]: WO3半导体与金属NiSe2之间形成"]},{"i":41597,"as":"柔性无机纳米纤维结合了无机材料固有的稳定性与纳米尺度赋予的柔韧性，在隔热、光电、催化和生物医学等高端领域展现出显著应用潜力。其柔韧性起源涉及多尺度结构耦合与多机制协同。现有研究尚未建立通用的柔性无机材料理论体系，限制了其精准设计与工业应用。本文系统综述了柔性无机纳米纤维的内在机理（如缺陷调控）、调控策略及评价方法。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":4.0,"t":3.0},"kp":["柔性起源[无机纳米纤维]: 涉及多尺度结构耦合及多种因素的协同作用"]},{"i":41598,"as":"针对明胶甲基丙烯酰基水凝胶在三维细胞培养中实验采样受限的问题，研究开发了一条基于贝叶斯神经网络的建模流程。该模型将水凝胶的交联参数映射至线性粘弹性模量和非线性临界应力，将所有配方的力学窗口划分为低、中、高稳定级别。利用C2C12成肌细胞进行的校准证实，非线性临界应力能补充线性流变参数，细化细胞相容性水凝胶配方的筛选优先级。原代心肌细胞的验证显示了与其一致的形态学趋势。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":7.0,"t":5.0},"kp":["建模方法[GelMA水凝胶筛选]: 基于贝叶斯神经网络(BNN)的建模流程","力学性能窗口分类[GelMA水凝胶]: 低/中/高稳定性机械窗口"]},{"i":41599,"as":"研究液体碱性电解槽中采用连续与脉冲沉积法制备的镍铁氢氧化物阳极在催化活性上的收敛现象。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":"[液体碱性电解槽]: 采用连续与脉冲沉积法制备镍铁氢氧化物阳极并存在催化活性收敛现象"},{"i":41600,"as":"多晶InGaSb薄膜是极具潜力的近室温薄膜热电材料。研究系统探究了沉积在玻璃基底上的多晶InGaSb薄膜，发现沉积温度和In通量是控制相竞争和纳米级成分波动的关键参数。通过调节In供应，形成了不连续的富In沉淀物并调整了基质成分；改变沉积温度则进一步控制了结构无序度与纳米特征。在维持薄膜连续性的最高沉积温度（560℃）下，薄膜实现了极高的功率因数。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":7.0,"t":5.0},"kp":["关键沉积参数[多晶InGaSb薄膜相竞争]: 沉积温度和铟(In)通量","微观结构调控[调节铟供应]: 产生不连续的富铟沉淀物"]},{"i":41601,"as":"将光学与磁性功能结合到忆阻器中有助于拓展其在图像识别和信息存储等领域的应用。研究制造了由铁磁体-富勒烯-氧化锰组成的结构，表现出磁化和光偏振向量依赖的光伏效应。电压诱导氧离子从氧化锰迁移至分子层，使器件电阻率降低数个数量级，消除非线性传输并淬灭光伏响应。这构建了一种光敏忆阻器，其光电流同时受电场和磁场状态控制。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["器件结构[光电磁多功能忆阻器]: 铁磁-富勒烯-氧化锰结构","光电效应机制[磁记录离子迁移]: 光电流依赖于磁化强度和光偏振矢量的相对排列","开关机制[可逆电压诱导]: 氧迁移"]},{"i":41602,"as":"研究从头设计了一种能够形成二聚体的双螺旋α螺旋蛋白，其中心空腔可容纳卟啉分子。混合该蛋白与卟啉形成的复合物表现出可见光驱动的氮还原催化活性。通过选择三个突变层并预测结构，筛选出七个保留原始折叠结构的突变体用于光催化产氨。其中表现最佳的突变体结合卟啉后，合成氨的催化速率达到9.704 mg gcat-1 h-1，优于目前报道的大多数人工光催化剂。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["催化剂[光催化固氮反应]: 结合卟啉的从头设计双螺旋α-螺旋蛋白","蛋白突变优化[光催化固氮反应]: 设计了三个突变层并筛选出七种突变体"]},{"i":41603,"as":"流体优先流动通常归因于静态孔隙结构非均质性，而研究表明流体极性变化能在富高岭石黏土介质中重组孔隙网络并放大优先流动。渗透实验显示，用低极性氢氟醚替换水后，仅18.8%的低极性饱和度即可触发早期突破，渗透率比标准相对渗透率预测值高出约62.7倍。多尺度成像表明孔隙结构由单峰微孔向连通的孔隙-裂缝双峰架构转变，低极性流体削弱了颗粒间的静电排斥力从而引发了这一变化。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":8.0,"t":5.0},"kp":["突破时间[低极性流体渗入高岭土粘土]: ~0.4天","渗透率提升[低极性流体替代水]: 高于标准相对渗透率预测值~62.7倍"]},{"i":41604,"as":"","scd":null,"kp":[]},{"i":41605,"as":"","scd":null,"kp":[]},{"i":41606,"as":"本研究利用先进的蛋白质组学策略，成功构建了水稻叶片中1691个半胱氨酸位点的过硫化动态图谱。研究发现，在持续盐胁迫下，水稻蛋白质过硫化水平发生全局性动态变化，显著影响金属催化、氧化还原代谢及磷酸戊糖途径（PPP）。进一步研究证实，硫化氢（H2S）通过介导非氧化性PPP中关键酶的过硫化修饰，有效调节了细胞的氧化还原代谢通量。这一分子机制揭示了H2S在植物抗逆反应中的关键作用，是水稻能够在盐胁迫后恢复生长活力的核心生化和代谢基础。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":7.0,"t":7.0},"kp":["蛋白质过硫化机制[水稻盐胁迫恢复]: H2S介导蛋白质半胱氨酸(Cys)残基过硫化以调节氧化还原代谢通量","过硫化组学分析技术[植物Cys残基位点特异性图谱]: 基于N-乙基马来酰亚胺-生物素的蛋白质组学技术"]},{"i":41607,"as":"","scd":null,"kp":[]},{"i":41608,"as":"","scd":null,"kp":[]},{"i":41609,"as":"","scd":null,"kp":[]},{"i":41610,"as":"","scd":null,"kp":[]},{"i":41611,"as":"","scd":null,"kp":[]},{"i":41612,"as":"","scd":null,"kp":[]},{"i":41613,"as":"","scd":null,"kp":[]},{"i":41614,"as":"","scd":null,"kp":[]},{"i":41615,"as":"","scd":null,"kp":[]},{"i":41616,"as":"","scd":null,"kp":[]},{"i":41617,"as":"","scd":null,"kp":[]},{"i":41618,"as":"","scd":null,"kp":[]},{"i":41619,"as":"研究提出了一种结合植物修复、生物炭生产和增强风化的可扩展修复策略，用于处理全氟和多氟烷基物质（PFAS）污染的农业土壤。该策略通过从土壤中去除PFAS、固定残留污染物并实现长效二氧化碳移除。基于实验数据的随机模型表明，通过碱性岩石改良进行土壤pH管理可加速全氟辛烷磺酸（PFOS）的去除，从而缩短修复时间。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["修复策略[PFAS污染农业土壤]: 结合植物修复、生物炭生产和强化风化"]},{"i":41620,"as":"","scd":null,"kp":[]},{"i":41621,"as":"","scd":null,"kp":[]},{"i":41622,"as":"","scd":null,"kp":[]},{"i":41623,"as":"","scd":null,"kp":[]},{"i":41624,"as":"","scd":null,"kp":[]},{"i":41625,"as":"","scd":null,"kp":[]},{"i":41626,"as":"该研究采用物理信息神经网络（PINNs）求解了相对论重离子碰撞产生的膨胀热 QCD 介质中重夸克的扩散和动力学演化问题。研究首先在完全动力学热化的假设下对重夸克动力学进行建模，随后通过神经网络算法深入模拟并分析了重夸克在膨胀介质中的演化过程。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["求解算法[膨胀热QCD介质中重夸克扩散演化]: 物理信息神经网络(PINNs)"]},{"i":41627,"as":"","scd":null,"kp":[]},{"i":41628,"as":"研究利用超相对论量子分子动力学、多相传输模型（AMPT）和 JAM 模型生成重离子碰撞数据，在质心能量为 4 和 11 GeV 的 Au+Au 碰撞中重构了碰撞参数 b。通过使用机器学习中的监督学习方法，有效证明了跨模型检验在提取重离子碰撞中碰撞参数的准确性和鲁棒性。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":7.0},"kp":["碰撞能量[重离子碰撞]: 4和11 GeV","碰撞参数[重离子碰撞Au+Au]: 冲击参数b","[模型算法]: 结合UrQMD、AMPT和JAM模型生成数据，并利用超级/机器学习重构碰撞参数"]},{"i":41629,"as":"","scd":null,"kp":[]},{"i":41630,"as":"该研究通过合并脱芳香功能化与双原子骨架编辑技术，实现了对简单芳烃（如苯）的可编程三重功能化。新安装的三个取代基均可独立改变，且区域选择性受电子效应控制。该反应无需预装活化或导向基团，即可高效生成三至六取代苯衍生物，并成功合成了一种具有大斯托克斯位移的新型内酯型六苯并晕苯纳米石墨烯。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[功能化机制]: 通过合并脱芳香功能化与双原子交换实现苯的可编程三重功能化","[区域选择性]: 由电子效应预测且三个取代基可独立改变"]},{"i":41631,"as":"针对直接空气捕获（DAC）技术中胺基电动摆动吸附（ESA）受限于 2:1 的胺/CO2 化学计量比瓶颈，该研究通过在 ESA 吸附剂中设计点缺陷介导的质子阱网络，实现了 1:1 的胺/CO2 化学计量比。工程化吸附剂在 400 ppm CO2 下的吸附量达到 6.57 mmol/g，比现有技术提高 28.8%，且仅需 3.4 GJ/t 的低能耗再生，CO2 释放速率显著提升。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":8.0,"t":7.0},"kp":["[吸附瓶颈突破]: 通过工程化引入点缺陷介导的质子捕获网络，克服传统胺基的2:1化学计量比限制，实现1:1的胺-CO2化学计量比"]},{"i":41632,"as":"研究利用机器学习分子动力学模拟捕捉并研究了氮纳米气泡的奥斯特瓦尔德成熟过程。结果表明，不同环境下的成熟速率依次为：酸性 > 碱性 ≈ 纯水 > 盐水。进一步分析揭示，反离子在调节界面水分子的取向排列和氢键网络中起着至关重要的作用，从而影响纳米气泡的粗化动力学和稳定性。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[研究方法]: 使用机器学习分子动力学模拟研究电解质离子对纳米气泡奥斯特瓦尔德成熟动力学的影响"]},{"i":41633,"as":"该研究通过在18个不同电化学体系的电池内部植入光纤布拉格光栅（FBG）传感器，实现了对电池内部应力的原位监测。研究发现，化成阶段的内部应力由于固相生长和气相积累的动态竞争而呈现双相特征。其中，SEI 形成应变（SFS）与SEI的厚度和致密性高度相关，决定了电池的退化路径。SFS 与电池容量损失之间存在高度相关性，实现了超早期的电池寿命预测。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[实验设计]: 在3种不同电化学体系的18个电池中植入光纤布拉格光栅(FBG)传感器原位监测内部应变","[早期寿命感知]: 通过解码化成阶段内部应变的双相特征实现超早期寿命预测"]},{"i":41634,"as":"介绍了一种将双极膜电渗析（BMED）与CO2电解槽耦合的集成系统，用于海水的联合碳捕获与转化。该系统能够从浓度范围0.0025M至0.5M的溶解无机碳中电化学提取并转化CO2。测试表明，该系统的特定能耗为3.90 kWh/kg，集成系统成功实现了向CO转化的过程。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[系统集成]: 将双极膜电渗析(BMED)与CO2电解槽(CO2E)耦合在单一BMEED系统中实现海水联合碳捕获与转化"]},{"i":41635,"as":"结合化学生物学工具，开发出具有用户可编程布尔逻辑降解特性的拓扑特异性蛋白质交联剂。通过将交联剂进行共价逐步聚合形成蛋白质水凝胶，这种智能材料能够根据预设的逻辑响应，精准释放生物活性蛋白或细胞治疗药物等货物，提升了重组蛋白生物材料的多重刺激响应性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[材料特征]: 重组蛋白生物材料前体具有接近完美的单分散性和序列特异性","[降解与释放控制]: 结合化学生物学工具，基于布尔逻辑自主控制实现多刺激响应性降解和治疗药物递送"]},{"i":41636,"as":"综述了基于木材的太阳能驱动界面蒸发器（W-SDIE）在水净化中的研究进展。木材因其固有的分层多孔结构、亲水性、低导热性和生物相容性，成为该技术的理想基板。利用木材替代高耗能材料可降低整体碳排放。文章重点阐述了提升W-SDIE性能的结构设计策略。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":5.0,"t":5.0},"kp":["基材特征[太阳能驱动界面蒸发器(SDIE)]: 木材具备天然分层多孔结构、出色的亲水性、低热导率和生物相容性","[可持续性]: 木材替代高耗能材料以减少隐含碳，降低常规水净化的高能耗限制"]},{"i":41637,"as":"提出一种利用氟化富勒烯（C60F30）纳米颗粒作为大分子添加剂的熵驱动电解质设计，用于提升锂金属电池的界面稳定性。该策略突破了传统小分子添加剂仅调节体相溶剂化的局限，通过大分子添加剂调制界面溶剂化环境，改善醚基电解质在高速率运行下的性能表现。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["电解质体系[锂金属电池]: 醚基电解质(如LiFSI/DME)具备低粘度、高离子传导率及良好的Li金属相容性","[界面稳定策略]: 熵驱动电解质设计，利用氟化富勒烯纳米颗粒添加剂实现界面稳定性"]},{"i":41638,"as":"针对靶向脂质纳米颗粒在纳米尺度上存在异质性限制其理性设计的问题，提出一种基于溶液的生物物理分析方法。该方法整合了非对称流场流分离、在线UV光谱分析、光散射和同步辐射小角X射线散射技术（AF4-UV-D），有效解析了tLNPs的物理化学特性，以满足孕期应用中核酸精准递送的需求。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":5.0,"t":5.0},"kp":["[靶向递送机制]: 通过靶向配体的共价连接驱动受体介导的LNP摄取，实现细胞特异性核酸递送","[分析技术]: 采用基于溶液的生物物理分析方法解决靶向脂质纳米颗粒(tLNPs)的异质性问题"]},{"i":41639,"as":"开发了一种基于大气集水技术的多相电磁波吸收系统。该系统利用表面张力和毛细作用将无机溶液限制在泡沫表面，形成超薄液膜。这种结构实现了空气、水和聚合物三相之间的协同作用，改善了阻抗匹配，结合了离子传导损耗和偶极子极化损耗机制来吸收电磁波。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":5.0,"t":5.0},"kp":["大气水储量[全球]: 1.3 × 10^16 升"]},{"i":41640,"as":"研发了一种受水母启发的仿生水凝胶，通过水合锁定渗透策略构建水合多酚网络，用于海洋生物电子学。该网络能有效抑制非特异性吸附和早期生物膜演化，实现防污功能；结合湿锚固和局部溶胀控制，克服了海水环境下的高盐度漂移和噪声问题，辅助AI多模式信号解码。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":5.0,"t":5.0},"kp":["[受水母启发的水凝胶防污与导电机制]: 采用水合锁定渗透策略，实现了协同防污和抗漂移导电"]},{"i":41641,"as":"报道了一种抗腐蚀的钴钒氧化物催化剂，用于高电流密度下的高效稳定海水电解。随着电流密度增加，催化剂表面的钒酸盐单体动态自组装形成具有大空间位阻的多金属氧酸盐，有效排斥工业级安培高电流密度条件下的氯离子，解决了传统催化剂容易失效的痛点。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[海水电解阳极]: 电流自适应多钒酸盐保护阳极","阳极催化剂[耐氯腐蚀]: 钴钒氧化物(Cobalt-vanadium-ox)","[工业级海水电解]: 具备安培级高电流密度(HCD)下的活性和稳定性"]},{"i":41642,"as":"提出一种镧系元素多阳离子混合策略，向Li3YCl6卤化物固态电解质中引入构型熵增效应和电子结构调控。熵增引起的局部结构畸变有效降低了锂离子的迁移势垒，同时提高了抗氧化性，实现全固态锂电池中固态电解质离子传输动力学和界面稳定性的同步增强。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[固态电解质改性策略]: 引入镧系元素多阳离子混合策略，产生构型熵增效应与电子结构调控，增强界面稳定性与离子传输动力学"]},{"i":41643,"as":"受自然分层结构启发，开发出一种将三价金属氯化物（MCl3）掺入壳聚糖基质的生物复合气凝胶。在水介质中通过配位驱动组装，无需外加酸或交联剂即可形成CTS-M气凝胶。该气凝胶在湿度刺激下表现出可逆的脆性到柔性转变，具备优异的机械弹性，可实现极端温度下的自适应隔热。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":5.0,"t":5.0},"kp":["[生物复合气凝胶构筑策略]: 将三价金属氯化物(MCl3)引入壳聚糖基质，在水性介质中通过配位驱动组装直接形成具有自适应热调节和能量存储功能的多级结构"]},{"i":41644,"as":"全面综述了尖晶石和六方铁氧体纳米材料在生物医学领域的最新进展，揭示了其结构、性能与生物活性之间的关系。重点探讨了通过阳离子分布、缺陷调制和形态各向异性等原子级工程，调节其磁化率、纳米酶催化活性和磁热疗比吸收率（SAR），以拓展其在核磁共振和药物递送等前沿领域的应用。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":5.0,"t":3.0},"kp":["[铁氧体纳米材料进化方向]: 从简单的磁性造影剂演变为能够主动调节生物微环境的多功能平台"]},{"i":41645,"as":"提出一种通过构建有机-无机杂化网络来诱导薄膜晶体管分子取向转变的策略。通过引入特定无机金属氧化物（如In2O3），建立包含强界面吸附和热力学驱动的机制框架，有效避免了传统方法引起的分子无序现象，使器件和传感性能显著提升了近20倍。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":6.0,"t":5.0},"kp":["[有机-无机杂化网络调控机制]: 引入特定无机金属氧化物(如铟基氧化物)调制结构与性能关系，诱导分子取向转变，避免分子无序带来的性能退化"]},{"i":41646,"as":"通过直接提取模拟二维伊辛晶格的胶体单层中的自旋构型，将液体和玻璃的熵缩放定律成功扩展到自旋系统领域。研究揭示了构型熵与自旋弛豫时间之间存在的通用指数关系，深化了对屈曲胶体单层弛豫特性的物理理解。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":7.0,"t":9.0},"kp":["[自旋系统构型熵标度律]: 构型熵与自旋弛豫时间之间存在普适的指数关系"]},{"i":41647,"as":"通过分子束外延技术成功制备出共掺杂的Fe5GeTe2单层材料。研究证实，该原子级厚度的外延单层材料突破了常规磁性范德华材料低于150 K的限制，在较高温度下依然能够维持长程磁有序状态，展现出高温铁磁性。","scd":{"b":8.5,"i":3.0,"r":6.0,"d":7.0,"t":9.0},"kp":["[Fe5GeTe2外延单层]: 共掺杂可实现高温铁磁性"]},{"i":41648,"as":"提出一种利用Floquet工程方法在光晶格超冷原子系统中实现Hubbard模型内的Sachdev-Ye-Kitaev（SYK）物理机制。该研究证实了超冷原子可用于模拟与黑洞和高温超导体相关联的量子物质前沿模型。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":9.0},"kp":["[光晶格中超冷原子]: 可用于Floquet工程方法模拟Sachdev-Ye-Kitaev(SYK)物理学"]},{"i":41649,"as":"通过计算机模拟首次在原子尺度上观察到金属钨的初级辐射损伤向线性状态转变的四个阶段。钨作为核聚变反应堆中关键的等离子体面对材料，该研究详细揭示了其在高能粒子辐照下内部缺陷产生的具体线性演化机制。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":9.0},"kp":["[钨的初级辐射损伤]: 首次在计算模拟中观察到初级损伤产生向线性状态的转变"]},{"i":41650,"as":"","scd":null,"kp":[]},{"i":41651,"as":"利用非线性回旋动力学模拟和理论分析，研究了托卡马克等离子体中反剪切阿尔芬本征模的非线性饱和过程。研究发现，在保持线性 energetic particle dynamics 的条件下，环向流场能够通过特定物理机制有效抑制RSAEs，这对高性能燃烧等离子体的控制至关重要。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":9.0},"kp":["非线性饱和机制[反剪切阿尔芬本征模(RSAEs)]: 由环向场抑制","研究方法[托卡马克等离子体中的RSAEs]: 非线性回旋动理学模拟与理论分析"]},{"i":41652,"as":"","scd":null,"kp":[]},{"i":41653,"as":"","scd":null,"kp":[]},{"i":41654,"as":"","scd":null,"kp":[]},{"i":41655,"as":"本研究探讨了在有限掺杂下SU(3)对称费米-哈伯德模型在三角晶格t-J模型中的磁相关性。基于超冷碱土原子和分子实现SU(N)对称实验的背景，填补了该系统在强耦合极限和有限掺杂条件下的理论空白。该成果为理解复杂量子多体系统的磁性提供了理论基础。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":9.0},"kp":["实验实现途径[SU(N)-对称费米-哈伯德模型]: 超冷碱土原子和分子","理论研究核心[有限掺杂下SU(3)对称Fermi-Hubbard模型]: 强耦合极限下的磁相关性"]},{"i":41656,"as":"本研究通过超导三光子自发参量下转换（SPDC）源，成功观测到了真正的三方非高斯纠缠。传统SPDC技术受限于光子对的产生，本研究利用超导电路的强非线性特性突破了这一限制，为量子光学领域的纠缠光子生成及其相关关键量子技术提供了新的实验手段。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":7.0,"t":8.0},"kp":["量子光学资源[三方非高斯纠缠]: 超导三光子自发参量下转换(SPDC)源","技术突破[SPDC技术]: 利用超导强非线性突破历史光子对限制实现三方纠缠"]},{"i":41657,"as":"本研究深入探讨了超导氢化物H3S的结构相变与位移量子临界点。H3S因在约155 GPa压力下具有203 K的高超导临界温度而备受关注。研究揭示了其作为超导氢化物前驱体的详细结构相变特征，加深了对超导氢化物机制及量子临界行为的理解。","scd":{"b":8.0,"i":1.0,"r":6.0,"d":7.0,"t":8.0},"kp":["超导临界温度Tc[硫化氢(H3S)]: 203 K","临界压力pc[硫化氢(H3S)]: 155 GPa","物理机制[超导氢化物H3S]: 位移量子临界点主导"]},{"i":41658,"as":"","scd":null,"kp":[]},{"i":41659,"as":"本研究提出了一种将金属有机笼作为构建基块，组装具有高导电性多孔材料的新策略。通过在MOCs表面附加四硫富瓦烯（TTF）电子供体基团，再将其与分子电子受体反应，成功在保持分子溶解加工性和永久孔隙率的同时构建了导电路径，为电催化和储能材料提供了新的物理形态控制方法。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["材料构建单元[多孔导电材料]: 金属有机笼","物理形态特征[金属有机笼材料]: 具备溶液可加工性","潜在应用[多孔导电材料]: 电催化与能量存储"]},{"i":41660,"as":"本研究开发了一种深共晶溶剂（DES）介导策略，成功制备出具有可调谐发光的非晶态氯化铟混合金属卤化物玻璃。通过3-氨基哌啶二盐酸盐和2-羟基丙酰胺组成的DES动态交联氢键网络，动力学上抑制了离子框架结晶。该基质在消除晶态的同时保留了关键的短程结构基元，促进了高效系间窜越。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":6.0,"t":7.0},"kp":["热力学屏障克服策略[混合金属卤化物(HMH)玻璃]: 深共晶溶剂(DES)介导策略","动力学抑制机制[HMH玻璃结晶倾向]: 利用动态交联氢键网络抑制长程有序化","深共晶溶剂网络组成[抑制长程有序化]: 3-氨基哌啶(3-aminopiper...)"]},{"i":41661,"as":"本研究揭示了扬-特勒效应在金属卤化物晶格磁光特性中的主导作用，实现了左手定则的光学不对称性。与传统的引入手性阳离子或利用氢键扭曲晶格的方法不同，本研究通过含有孤立SbCl6八面体的高对称单晶（如DMA4InCl7:Sb3+和DETABiCl6:Sb3+）实现了精确的立体化学不对称空间控制。","scd":{"b":6.0,"i":1.0,"r":6.0,"d":5.0,"t":7.0},"kp":["不对称性引入机制[金属卤化物晶格]: 扬-特勒效应主导","传统不对称引入手段[无机-有机杂化金属卤化物]: 导入手性A位阳离子或利用氢键扭曲晶格"]},{"i":41662,"as":"本研究发现负化学压力能够诱导(Ca1–xSrx)3CrN3形成电子化物。有别于传统的阴离子去除或施加高压策略，Sr元素的引入产生负化学压力，导致过键合的Cr发生氧化并释放电子，驱动了晶体框架重构，使电子占据晶格间隙并充当阴离子，为稳定电子化物提供了新方法。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":6.0,"t":7.0},"kp":["材料类型[(Ca1–xSrx)3CrN3]: 电子化物","稳定化新策略[电子化物形成]: 负化学压力诱导","传统稳定化策略[电子化物]: 阴离子去除或施加高压"]},{"i":41663,"as":"修正利用静电排斥调节无序岩盐结构以增强锂电池储能性能的相关研究。","scd":{"b":3.0,"i":1.0,"r":3.0,"d":3.0,"t":6.0},"kp":["[无序岩盐结构增强锂存储]: 利用静电排斥调节1-TM通道"]},{"i":41664,"as":"本研究提出了一种在吲哚并咔唑嵌入式多重共振热活化延迟荧光（MR-TADF）发射器上的分子取向定向异构化策略，实现了高性能纯绿光电致发光。该设计构建了一种新颖的顺式对位N–π–N双硼架构，平衡了分子内强电荷转移（ICT）与短程电荷转移（SRCT），成功实现了高效、窄带的纯绿光发射。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["分子构建策略[高性能纯绿光电致发光]: 在吲哚并咔唑(ICz)结构单元上进行取向定向异构化","材料特性[多重共振热活化延迟荧光(MR-TADF)发射器]: 高效率、窄带纯绿色发射"]},{"i":41665,"as":"本研究通过原位晶格取代构建了Sm3+掺杂的Bi2WO6（Sm-BWO）纳米片，实现了甲苯高选择性氧化为苯甲醛。Sm掺杂诱导产生氧 vacancy，形成具有界面协同作用的空间耦合双活性位点。该催化剂的甲苯转化率高达8550 µmol·g−1·h−1，且对苯甲醛的选择性超过86%。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":7.0,"t":7.0},"kp":["催化剂[甲苯选择性氧化制苯甲醛]: Sm3+掺杂Bi2WO6 (Sm-BWO) 纳米片","催化剂合成方法[Sm-BWO纳米片]: 原位晶格取代法","活性位点特征[Sm-BWO纳米片]: 具有界面协同效应的空间耦合双活性位点"]},{"i":41666,"as":"本研究开发了一种镍催化的脱硫氘化策略，利用重水（D2O）作为氘源，实现了（杂）芳基硫化物的选择性氘代。该反应条件兼容性好，成功合成了87例（涵盖10余种杂环）氘代（杂）芳烃，产率和氘掺入量均表现优异，并支持高达6倍以上的放大规模合成。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":7.0},"kp":["氘源[D2O]: D2O","用量[(杂)芳基硫醚脱硫氘化]: 1.5或3.0当量","催化剂[脱硫氘化反应]: 镍"]},{"i":41667,"as":"本研究以96%超高镍富镍层状氧化物正极和混合Si@C负极组成的电池为模型系统，深入剖析了下一代高能量密度锂离子电池热失控过程中的产气机制。研究实时监测了正负极电极的产气行为及其交叉反应，揭示了Si@C负极是严重的气体排放源（包含H2等），阐明了限制低空经济设备商用的热安全根本问题。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":7.0,"t":7.0},"kp":["正极材料[超高能量密度锂离子电池]: 超高镍层状氧化物（Ni占比96%）","负极材料[超高能量密度锂离子电池]: 混合硅碳（Si@C）"]},{"i":41668,"as":"本研究在缺陷MOF（UiO-66）中成功设计了空间排列限域的Cu+-Cu0簇对，实现了高度协同的二氧化碳加氢制甲醇。通过L-抗坏血酸制造缺失配体缺陷，随后锚定高密度且相邻的Cu+-Cu0双位点，实现了对二氧化碳和氢气同步激活的时空导向机制，解决了多价铜位点精确排列的挑战。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":7.0,"t":7.0},"kp":["催化活性位点[CO2加氢制甲醇]: Cu+-Cu0团簇对","载体材料[限域Cu位点]: UiO-66 (U66)缺陷MOF","催化机制[CO2和H2同步活化]: 空间阵列化的多价Cu位点实现时空定向催化"]},{"i":41669,"as":"修正协同利用浓度场与电子场提升炔醇电催化半加氢反应效率的研究。","scd":{"b":4.0,"i":1.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[炔醇电催化半加氢]: 协同利用界面浓度场和电子场促进反应"]},{"i":41670,"as":"修正六核铁化合物中自旋交叉与菱形变形耦合产生各向异性热膨胀的发现。","scd":{"b":4.0,"i":1.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[六核{FeIII4FeII2}化合物]: 自旋交叉与菱形变形耦合产生巨大各向异性热膨胀"]},{"i":41671,"as":"本研究报道了一种具有原子级分散Cu位点的氢键卟啉框架（SACu-GTUB5），有效解决了可充电H2-Cl2电池中氯气限制能力差和界面Cl2/Cl-氧化还原动力学迟缓的问题。该框架固有的孔隙率与原子级Cu位点相结合，实现了高效的氯气存储并加速了Cl2/Cl-转化反应。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["核心技术[可充电H2-Cl2电池]: 原子级界面调节","解决瓶颈[氯氧化还原化学]: 实现高效的Cl2限域与提升Cl2/Cl-界面氧化还原动力学"]},{"i":41672,"as":"本研究受自然界叶绿体启发，设计了一种基于超分子生物仿生异质结（Zn-TIPP/CdS）的光催化剂，通过人工光合作用高效生产乙醇。Zn-TIPP的超分子笼结构与CdS耦合，成功模拟了叶绿体基质和基粒的全面功能，有效克服了C1中间体的空间利用和C-C键耦合动力学缓慢的挑战，实现了高达138.9 µmol的高乙醇产率。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":5.0,"t":7.0},"kp":["光催化剂[CO2还原制乙醇]: Zn-TIPP/CdS超分子仿生异质结","设计原理[模拟叶绿体人工光合作用]: 利用超分子笼的空间限域效应克服C1中间体空间局限与C-C键偶联动力学迟缓"]},{"i":41673,"as":"本研究报道了一类基于N-杂环氮烯（NHN）框架的全新氮基配体，能够表现出L型、X型和Z型三种配位模式，并在L型和X型之间实现了可逆切换。这是首个氮基Z型配体示例，能够根据配位环境在供体和受体模式间切换，通过添加或移除配位溶剂即可改变过渡金属的形式氧化态。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":6.0,"t":7.0},"kp":["配体特性[N-杂环硝鎓(NHN)]: 实现L-、X-和Z-型多模态配位","配体开关行为[L-型和X-型状态间]: 可逆转换"]},{"i":41674,"as":"本研究通过将原子级分散的Ni引入Co3O4空心纳米盒中构建不对称Ni-O-Co活性位点，打破了尿素电解中尿素激活与CO2脱附之间的Sabatier限制。不对称位点引发了八面体Co3+从低自旋到中间自旋的关键自旋态跃迁，显著提升了尿素辅助水解的催化效率。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["活性位点结构[尿素电解]: 不对称Ni-O-Co位点","催化机制[打破Sabatier权衡关系]: 引入原子级分散Ni诱导自旋态跃迁，解除尿素活化与CO2脱附间的性能限制"]},{"i":41675,"as":"本研究证实了离聚物在与中性表面接触带电过程中的电荷载体确实是离子，并揭示了其转移机制由可移动离子与离聚物基体间的结合亲和力控制。通过对固定阴离子和阳离子的离聚物进行离子交换实验，证明了离子的结合能力主导了接触界面的电荷转移过程与充电特性。","scd":{"b":8.0,"i":1.0,"r":6.0,"d":5.0,"t":7.0},"kp":["电荷转移机制[离聚物接触带电]: 离子转移导致表面带电","充电控制机理[接触起电]: 由离子与固定反电荷的结合亲和力控制"]},{"i":41676,"as":"本研究提出了一种同分异构设计策略，通过调控羰基的空间排列来优化蒽醌基共价有机框架（TPAQ-COF）的储钠性能。通过工程化处理具有相邻羰基配位位点的同分异构体（i-TPAQ-COF），利用协同螯合效应克服了低温环境下离子扩散缓慢和晶格收缩导致的动力学迟缓问题，在低温下实现了153 mAh g-1的优异可逆容量。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["负极材料设计[低温钠储存]: 蒽醌基共价有机框架","低温性能优化策略[钠离子电池]: 同分异构设计调控羰基的空间排列以优化钠储存"]},{"i":41677,"as":"均质单网络弹性体在高于玻璃化转变温度时具有高拉伸性，但普遍面临机械强度低和耐久性有限的缺点，容易失去弹性并变脆破裂。这对其在运动防护装备和阻尼系统等领域的应用构成了挑战。研究旨在探讨弹性体能否同时兼具刚度、韧性和抗疲劳性。","scd":{"b":4.5,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":["材料分类[弹性体]: 无溶剂聚合物网络","相变特征[弹性体工作机制]: 在玻璃化转变温度(Tg)以上呈现高弹性"]},{"i":41678,"as":"氧还原和析出反应(ORR/OER)的多物理场特性对电催化剂的理性设计构成挑战。为此，研究人员开发了由人工智能驱动的两阶段材料筛选(TSMS)框架。该框架集成了密度泛函理论(DFT)计算、主动学习引导的实验反馈循环和机制解释，可实现高效电催化剂的快速发现与系统评估，并在质子固体氧化物电池中进行了验证。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[ORR/OER合理设计]: 开发了两阶段材料筛选技术(TSMS)以克服结构-性能关系挑战"]},{"i":41679,"as":"针对耐甲氧西林金黄色葡萄球菌(MRSA)生物膜引起的骨髓炎，研究人员受天然骨膜结构启发，通过巯基-点击化学开发了一种负载NiSr MOF@Mem纳米复合物的可注射仿生水凝胶。该系统能作为物理屏障覆盖骨缺损，并在交变磁场激活下协同执行化学动力学治疗、控释抗生素和免疫调节，有效激活NADPH氧化酶并重新编程中性粒细胞胞外陷阱的形成。","scd":{"b":7.5,"i":3.5,"r":6.0,"d":6.0,"t":6.0},"kp":["仿生髓膜系统[MRSA骨髓炎治疗]: 由硫醇-点击化学制备的水凝胶负载NiSr MOF@Mem纳米复合材料构成的注射型水凝胶"]},{"i":41680,"as":"低价氮族体系常被用作C-F键活化的氧化还原催化剂，但通常局限于依赖还原消除的加氢脱氟途径。研究提出由两性离子磷亚胺介导的脱氟功能化平台，可在温和条件下将多氟(杂)芳烃转化为多种C-X键(X = C, O, S, N, P, Se)。实验与DFT计算表明，催化过程通过Sb(III)-F物质在氧化还原中性条件下促进C-F键取代，催化剂形态成为决定性的机制分支点。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[多氟(杂)芳烃的脱氟官能化]: 由两性离子磷亚胺介导，在温和条件下实现多种C-X键(X = C, O, S, N, P, Se)的生成"]},{"i":41681,"as":"针对纳米酶体内动态实时追踪和生物安全性挑战，研究人员开发了一类单组分、无金属的自发荧光纳米酶(AFNZs)。通过在花青前驱体的溶剂热转化过程中精确控制硫/氮(S/N)化学计量比，该纳米酶同时具备超亮的第二近红外(NIR-II)区荧光和强效的类多酶活性。其NIR-II荧光量子产率大于1.4%，最大发射波长超过1100纳米，可实现高分辨率成像与肿瘤催化免疫治疗。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["荧光纳米酶[生物成像与肿瘤治疗]: 单组分、无金属且自发荧光的纳米酶，同时具备超亮近红外-II(NIR-II)荧光和强效多酶模拟活性"]},{"i":41682,"as":"传统分子催化通常利用客体在宿主空腔内的内源性结合，而基于尺寸不匹配的外源性结合(客体选择性与宿主外表面结合)仍是控制化学反应选择性的新范式。研究发现，天然环糊精(CD)与多金属氧酸盐光催化剂之间的外源性结合，使得它们之间的氢原子转移具有高度的位点选择性。该光活性多金属氧酸盐(十钨酸阴离子)因此实现了特异性的催化转化。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[选择性化学反应控制]: 利用分子主客体尺寸不匹配导致的外表面结合(外源结合)实现选择性的氢原子转移"]},{"i":41683,"as":"针对高级烯烃多相催化加氢甲酰化中面临的底物扩散限制和活性物种不明确的问题，研究利用自支柱MFI沸石锚定铑(Rh)单原子予以克服。通过一锅法合成了Rh1@SPP-MFI催化剂。X射线吸收分析和球差校正HAADF-STEM证实，每个Rh原子与四个氧原子配位形成明确的RhO4物种。该纳米反应器结构有效提升了催化加氢甲酰化的效率。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["锚定Rh单原子的催化剂[高级烯烃加氢甲酰化]: RhO4物种(通过控制反应和煅烧条件合成)限制于自柱五硅沸石(SPP-MFI)中形成高效纳米反应器"]},{"i":41684,"as":"α-叔烷基胺是具有较高生物活性倾向的骨架结构，但其直接构建一直是一项长期挑战。研究提出了一种三组分组装方法，利用儿茶酚的双重作用，从容易获取且稳定的反应物中模块化合成α-叔胺。该合成方法具有出色的官能团耐受性，能够构建包括连续季碳中心和邻位全碳季铵中心在内的多种复杂分子结构。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[α-叔烷基胺的构建]: 利用儿茶酚的双重功能，通过三组分组装直接合成受阻的α-叔胺"]},{"i":41685,"as":"修正纳米级金属有机层在深度穿透X射线诱导光动力治疗中的应用研究。","scd":{"b":2.0,"i":1.0,"r":2.0,"d":2.0,"t":2.0},"kp":["[深度穿透X射线诱导光动力治疗]: 纳米级金属有机层应用修正"]},{"i":41686,"as":"锌溴(Zn-Br2)水系电池的广泛部署受到正极分子溴不受控扩散引起的自放电和容量衰减的阻碍。研究通过将Gemini型溴络合剂(BCA)浸渍到多孔碳主体的油相中，有效缓解了溴的交叉穿梭问题。该方法促使溴原位转化为水不溶性的多溴化物BCA相，将活性物质限制在电极结构内。Gemini BCA分子中的芳环连接体显著增强了对活性物质的束缚能力。","scd":{"b":7.5,"i":3.5,"r":5.0,"d":6.0,"t":6.0},"kp":["[抑制Zn-Br2液流电池溴交叉]: 采用浸渍在碳中的双子型溴络合剂作为溴主体"]},{"i":41687,"as":"手性磷酰胺盐是药物发现和手性配体设计中的关键结构，但其催化对映选择性合成极具挑战。研究首次报道了镍催化炔烃的不对称氢磷酰胺化反应。该协议能够高效、高对映选择性地合成多种结构的烯基磷酰胺盐，兼容多种N,N-二烷基和N-烷基取代的H-磷酰胺，且生成的产物在四个不同位点上表现出正交反应性。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["催化体系[炔烃不对称氢磷酰胺化]: 镍催化，实现具有P-立体中心的磷酰胺的高效和对映选择性合成"]},{"i":41688,"as":"赋予点击反应可逆性因高能量收益而导致断键困难，极具挑战。研究报道了高度可定制的硫桥联N-芳基喹啉衍生物与硫醇之间的可逆点击反应。该闭环过程通过向芳香化方向拮抗亲核加成实现，其点击和解点击过程可分别通过使用碱和酸来操控，且这两种特征均具有近乎通用的广谱适用性。","scd":{"b":7.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["[水相可逆合成]: 高度可定制的硫基组分之间可在水中发生稳健且可控的可逆点击反应"]},{"i":41689,"as":"基因靶向疗法在治疗多种“不可成药”的癌基因时，常受到脱靶毒性和肿瘤异质性的阻碍。研究人员设计了一种逻辑响应型超球形核酸(SSNA)。该结构具有按需激活的功能，能够实现肿瘤特异性的多重基因沉默，从而精准靶向癌基因，在有效规避脱靶毒性的同时，实现高效的癌症治疗。","scd":{"b":8.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["响应机制[超球形核酸]: 逻辑响应型且特异性针对肿瘤","应用目标[癌症治疗]: 多重基因沉默"]},{"i":41690,"as":"针对活细胞中细胞骨架网络时空控制及全蛋白质组图谱描绘工具缺乏的问题，研究人员开发了一种生成产生单线态氧(1O2)的小分子光敏剂的模块化策略。通过在罗丹明光敏剂骨架上安装磺酰胺-PEG2配体，生成了结合激活型探针。该探针在溶液中主要以不可激发的螺内酰胺形式存在，与目标结合后激活，从而实现对细胞骨架的控制和蛋白质组解码。","scd":{"b":7.5,"i":2.5,"r":5.0,"d":6.0,"t":5.0},"kp":["光敏剂种类[细胞骨架蛋白质组图谱]: 结合激活单线态氧(1O2)基因小分子光敏剂","控制机制[活细胞网络控制]: 模块化时空控制"]},{"i":41691,"as":"Eu2+离子因其允许的5d→4f跃迁是蓝光激发近红外发射体，但大斯托克斯位移限制了其发光效率。传统策略通过增强晶体场来红移发射，但这会增加电子-声子耦合并促进非辐射弛豫，导致波长与效率间的内禀权衡。研究提出一种晶体场弱化工程策略，成功打破这一权衡，降低了非辐射跃迁，为新兴光谱应用解锁了超高效的Eu2+近红外发射。","scd":{"b":7.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["发射性能[Eu2+离子]: 蓝光激发近红外发射","常规策略[晶体场强化]: 导致发射红移但不可避免地增强电子-声子耦合"]},{"i":41692,"as":"将金属中心引入共价有机框架是调控电子特性的有效策略，但构建模块库仍然有限。研究人员设计了两种氨基功能化四氮杂[14]轮烯镍(TAA)构筑单元，并将其引入二维COFs中。通过在TAA外围苯环的近端引入可修饰位点，实现了对中心镍离子电子态的轻松调控。通过构建一对含有相同数量氟原子但位于近端或远端的同分异构体COFs，系统研究了取代基的位置效应。","scd":{"b":7.0,"i":2.5,"r":5.0,"d":6.0,"t":5.0},"kp":["构建单元[共价有机框架]: 氨基功能化四官能镍四氮杂[14]轮烯(TAA)","调控机制[电子态调制]: TAA外围苯环丰富的取代基变化"]},{"i":41693,"as":"稳定高活性超细金属纳米粒子需合理设计新型载体。研究人员基于多孔有机笼(POC)，通过四凹型四甲酰基杯[4]间苯二酚冠醚与长链聚乙二醇功能化二氨基咪唑连接体的缩合，设计合成了一种新型多孔液体CPOC-PL。该多孔液体材料能有效稳定钯纳米团簇，使其在室温下实现H2的捕获以及炔烃的高效选择性半氢化反应。","scd":{"b":7.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["载体材料[钯纳米团簇稳定]: 多孔有机笼液体(多孔液体)","催化应用[Pd纳米团簇]: 环境条件下H2捕获与炔烃半氢化"]},{"i":41694,"as":"传统无机光致变色材料通常在固定波长下操作，应用便利性不及有机物。近期研究表明方钠石族铝硅酸盐可在整个可见光波长范围内进行高可调谐性变色。该研究进一步证明，一种davyne型结构是首个表现出仅在近红外区域发生选择性吸收的光致变色材料，且在变色过程中不伴随可见光波段的吸收，成功将光致变色定制范围拓展至人眼可见度之外。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["刺激响应[无机光致变色材料]: 紫外辐射触发变色，白光和/或加热逆向恢复","吸收特性[铝硅酸盐材料]: 可开关的近红外吸收"]},{"i":41695,"as":"通过非自由基途径进行的选择性氧化在催化中至关重要，但在固液界面构建既能高效活化氧化剂又能稳定活性中间体的催化界面十分困难。研究在埋藏界面处构建了不对称的Co─O─Mo垂直直通键桥连结构。该桥连氧连接了CoOOH层，在原子尺度上耦合了两个不同的氧化还原中心，成功构建了优先催化非自由基反应的垂直通道，实现了双位点非自由基选择性氧化。","scd":{"b":8.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["界面结构[双位点非自由基氧化]: 垂直直通键 Co─O─Mo 桥","常规策略[非自由基选择性氧化]: 平面或准平面界面工程无法有效耦合催化位点"]},{"i":41696,"as":"在石墨烯晶格上实现空间分辨的化学功能化对制造高级二维架构至关重要。现有共价图案化策略难以兼顾降低晶格损伤与化学多样性调节。研究开发了一种模块化的二芳基锍平台，用于单层石墨烯的超低阈值共价图案化。在石墨烯介导的热电子单电子转移(SET)机制驱动下，该策略降低了活化能，实现了低至特定毫瓦级的无损激光图案化，并实现了基于取代基编码的局部功函数可编程调控。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["阈值特性[石墨烯激光图案化]: 超低阈值","功能平台[可编程功函数工程]: 模块化二芳基锍平台"]},{"i":41697,"as":"纳米酶的被动和不可控催化特性阻碍了其临床转化。受天然酶静电预组织理论启发，相关研究系统分析了电场调控的纳米酶。相比于传统物理刺激，电场输入为主动精准治疗提供了可调节的互补框架。多种电输入模式为精确调控纳米酶催化提供了驱动力，在原子尺度上，电场输入能优化催化剂的d带中心、表面电荷等性质，实现了从被动适应到主动精准治疗的跨越。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":3.0,"t":3.0},"kp":["调节机制[纳米酶催化性能]: 电场调控(主动精准时空调节)","理论基础[电场赋能纳米酶]: 自然高效酶的静电预组织理论"]},{"i":41698,"as":"提出一种从任意参考分布构建物理一致平衡态的通用方法。该方法通过沿未扰动轨迹进行迭代扩散提取最近的正则平衡，无需显式轨道积分即可收敛到轨道平均分布。该过程在弹跳点和捕获-穿透边界附近数值稳健，适当预处理可加速收敛。应用表明，在带平衡更新的离子温度梯度模拟中，提取的平衡态能将带状分量一致吸收到背景分布中。","scd":{"b":5.0,"i":1.0,"r":6.0,"d":4.0,"t":4.0},"kp":["核心算法[正则平衡提取]: 最近正则平衡提取方法","数值特性[回旋模拟边界]: 在反弹点附近和捕获-越界边界处数值鲁棒性强"]},{"i":41699,"as":"通过二维辐射流体动力学模拟研究了在非局域电子传输条件下，不同硅掺杂比例对直接驱动靶丸内爆性能的影响。结果表明，随着硅掺杂比例增加，向内的电子热通量降低，辐射温度升高。6.25%和12.5%掺杂比例使预热燃料温度分别升高9.30%和18.6%，最大扰动幅度分别降低39.5%和66.3%。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["Si掺杂比例[直接驱动内爆]: 0%, 6.25%, 12.5%","[非局域电子传输下的2D辐射流体力学模拟]: 模拟了不同Si掺杂比例对靶丸直接驱动内爆性能的影响"]},{"i":41700,"as":"","scd":null,"kp":[]},{"i":41701,"as":"","scd":null,"kp":[]},{"i":41702,"as":"提出一种在拓扑和参数信息缺失情况下，用于水电系统的鲁棒学习电压控制方法。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":["[拓扑和参数信息缺失]: 水电系统鲁棒学习电压控制方法"]},{"i":41703,"as":"研究揭示了聚合物电解质燃料电池中电催化剂降解过程存在的路径依赖性。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[电催化剂降解过程]: 存在路径依赖性"]},{"i":41704,"as":"提出基于双流多尺度卷积Transformer与动态融合的超短期风电功率预测模型。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[超短期风电功率预测]: 结合双流多尺度卷积Transformer与动态融合模型"]},{"i":41705,"as":"基于节能电器补贴证据，分析补贴率与绝对定价对应用能效的影响。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[应用能效影响机制]: 节能电器补贴率与绝对定价"]},{"i":41706,"as":"结合机理模型与数据驱动方法，探索数字孪生可逆固体氧化物电池的实时模拟。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[可逆固体氧化物电池实时模拟]: 结合机理模型与数据驱动方法的数字孪生技术"]},{"i":41707,"as":"提出一种用于优化包含power-to-X等复杂过程能源系统运行的分解方法。针对详细过程模型计算困难的问题，该方法通过为每个过程引入代理模型，将原始优化问题分解为具有不同模型粒度级别的子问题。该研究在先前单一连续过程系统的基础上，扩展至处理多个和更复杂的系统。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[Power-to-X能源系统优化]: 提出一种分解方法来解决包含详细过程模型的复杂能源系统运行优化的计算难题"]},{"i":41708,"as":"提出一种结合全局自适应谱和局部动态交互的模型，用于预测多条件运行下燃料电池的老化情况。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[多条件运行下燃料电池老化]: 结合全局自适应谱和局部动态交互的在线预测模型"]},{"i":41709,"as":"结合元学习与共形分位数回归算法，精准评估和估计系统中细粒度的潜在负载灵活性。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[细粒度潜在负载灵活性评估]: 结合元学习与共形分位数回归算法"]},{"i":41710,"as":"探讨如何协同碳市场、电力市场与CCER市场，助力中国电力行业实现经济高效的脱碳目标。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[中国电力行业脱碳]: 协同碳市场、电力市场与CCER市场以实现经济高效的脱碳目标"]},{"i":41711,"as":"综合评估碳捕集、利用与封存技术及可再生能源在中国铝工业脱碳过程中的协同作用。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":4.0,"t":4.0},"kp":["[中国铝工业脱碳]: 综合协同应用碳捕集、利用与封存技术及可再生能源"]},{"i":41712,"as":"研究利用UCB-Q值辅助的差分进化算法，优化含有柔性负荷的低碳微电网调度问题。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":3.0,"t":4.0},"kp":["[含柔性负荷的低碳微电网调度]: 采用UCB-Q值辅助的差分进化算法进行优化"]},{"i":41713,"as":"分析光伏系统中应用机器人进行清洁的实际效果，并评估其对光伏模块退化的影响。","scd":{"b":4.0,"i":6.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[光伏系统维护]: 应用机器人清洁实际效果及对光伏模块退化的影响评估"]},{"i":41714,"as":"展示了分子混合卤化物玻璃作为宿主保护和调节钼团簇三线态发射的能力。通过比较具有氯化物、溴化物和碘化物端基配体的同构团簇盐，阐明了顶端卤化物化学如何控制电子结构和近红外辐射动力学。氯化物端基团簇效率最高，将其掺入氯化镉基混合卤化物玻璃后，实现了优异的近红外发射性能。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[Mo6簇掺杂混合卤化物玻璃]: 分子混合卤化物玻璃可作为钼簇三线态发射的保护和调节基质，实现高效且稳定的近红外发射"]},{"i":41715,"as":"在半导体固态平台中演示了连续时间晶体的非局域同步现象。当两个相距40微米的自振荡电子-核自旋系统受到光泵浦时，它们不同的频率锁定到一个共同值，表现出长程耦合。随着距离进一步增大，同步消失。相互作用距离与电子自旋扩散长度相匹配，证明自旋传输是介导耦合的机制。","scd":{"b":9.0,"i":1.0,"r":7.0,"d":6.0,"t":5.0},"kp":["振荡器间距[固态平台连续时间晶体非局域同步]: 高达40 μm","[半导体电子-核自旋系统]: 空间分离的自激振荡器在光学泵浦下实现统一集体行为的非局域同步"]},{"i":41716,"as":"通过对水稳定的柱撑层状Cu-MOF（NJU-Bai5）进行合理结构演化，实现了对骨架灵活性的精确调控。策略是用甲基吡啶 strategically 替代结构中的吡啶基配体，从而在分子水平上引发对特定气体的选择性响应。该材料可通过水相规模合成，有效放大了相似分子间的微小差异，促进了丙烯与丙烷的高效分离。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[柔性MOF框架]: 通过孤对电子精确控制气体识别灵活性，实现C3H6/C3H8的高效选择性分离"]},{"i":41717,"as":"报道了一种在单个设备中耦合能量存储和化学制造的开环液流电池。放电时将VO2+还原与有机化合物氧化为高附加值化学品配对，充电时将VO2+氧化与析氢反应配对。该电池适用于13种有机底物，并与大多数典型正极电解液兼容。以乙二醇转化为乙醇酸和产氢为例，该电池的电压和能量效率均超过100%。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[开环液流电池单设备耦合]: 放电时耦合VO2+还原与有机化合物氧化，充电时耦合VO2+氧化与析氢反应，实现储能与化学品制造同步"]},{"i":41718,"as":"通过晶界偏析策略合成了晶态-非晶态Ni/TiO2异质结，结合多模式操作技术，直接可视化了碱性析氢反应中亲氧位点局域配位在偏压下的可逆重构现象。这一发现打破了以往对亲氧相关位点催化作用的静态解释，证明了其在实际工作条件下的动态演变，为通过亲氧调节促进水活化提供了新见解。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":4.0,"t":4.0},"kp":["[镍基碱性析氢电催化剂]: 引入亲氧组分并通过多模态方法动态可视化了亲氧调节在碱性析氢中的水活化催化作用"]},{"i":41719,"as":"","scd":null,"kp":[]},{"i":41720,"as":"采用分层策略评估了第三代PEG化碳硅烷树枝状聚合物及其siRNA复合物的细胞相容性、血脑屏障模型完整性和小鼠生物分布。从血脑屏障相关单层细胞培养到毛细血管加权血脑屏障模型，再到小鼠体内/体外分布。在内皮细胞、周细胞和星形胶质细胞中进行了线粒体/氧化还原分析，验证了其在靶向阿尔茨海默病中的潜力。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":5.0,"t":4.0},"kp":["树状聚合物代数[碳硅烷纳米平台]: 第三代 (G3Si PEG6000)","[纳米平台多级评估]: 评估了其细胞相容性、血脑屏障模型完整性及小鼠模型生物分布"]},{"i":41721,"as":"对使用超低电子温度等离子体进行TiN薄膜等离子体增强原子层沉积的研究内容进行修正。","scd":{"b":2.0,"i":2.0,"r":3.0,"d":3.0,"t":3.0},"kp":["[TiN薄膜沉积]: 采用超低电子温度等离子体增强原子层沉积工艺"]},{"i":41722,"as":"通过配体-基体界面工程策略，将高可溶性碘化铜簇与自修复含氟嵌段共聚物结合，制备了高度可拉伸且具备自主自修复能力的闪烁体薄膜。界面配位与离子偶极相互作用引导聚合物基体中均匀分散的簇发生原位自组装，解决了传统柔性X射线闪烁体在颗粒分散、闪烁效率和机械稳健性之间的持久权衡问题。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["基底材料[柔性X射线闪烁体]: 自修复含氟嵌段共聚物","[碘化铜闪烁体界面工程]: 采用配体-基质界面策略将高可溶性碘化铜簇集成，克服颗粒分散、闪烁效率与机械鲁棒性之间的权衡"]},{"i":41723,"as":"提出了一种“关联门控”策略，用于惰性卤代芳烃的多光子激活。该系统构建了顺序电子供体-受体络合物，作为可编程反应微环境。首先通过硫化物/萘酰亚胺络合物捕获单光子，生成的自由基阴离子作为支架组织第二个不同的电子供体-受体络合物，形成反应口袋，有效控制了常规多光子光催化中超还原剂能量耗散的问题。","scd":{"b":8.0,"i":2.0,"r":5.0,"d":5.0,"t":5.0},"kp":["[惰性卤代芳烃多光子激活]: 引入“关联门控”策略构建电子供体-受体复合物作为可编程反应微环境，控制高能中间体以实现多光子激活"]},{"i":41724,"as":"通过在ZnSO4电解质中引入羧化纤维素纳米纤维（CNF），解决了水系锌离子电池的负极腐蚀和析氢问题。CNF分子具有强供电子能力，优先吸附在锌表面，动态占据界面活性位点，限制水分子与锌负极直接接触，形成贫H2O的双电层缓冲层。该界面调控有效抑制了析氢、腐蚀和枝晶生长。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["电解液添加剂[水系锌离子电池]: 羧基化纤维素纳米纤维(CNF)","吸附特性[CNF分子]: 具有高HOMO能级和强供电子能力，优先吸附在锌表面"]},{"i":41725,"as":"开发了一种载有源自鱼腥草的两种生物活性纳米制剂的抗感染和免疫调节水凝胶，用于治疗糖尿病伤口。该水凝胶包含经聚乙烯亚胺修饰的碳点，能够有效应对细菌感染、调节过度炎症并促进细胞增殖，克服了传统策略中抗生素耐药性的限制，实现了糖尿病伤口的综合协同治疗。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":5.0,"t":4.0},"kp":["伤口敷料[糖尿病伤口治疗]: 阴离子型多功能水凝胶","[多功能水凝胶]: 协同实现抗感染、调节过度炎症和促进细胞增殖"]},{"i":41726,"as":"在形貌可控的SrTiO3纳米立方体上构建了低稀土载量的CuOx-CeO2活性相，用于富氢流中CO优先氧化（CO-PROX）。表征显示，增加铈负载量提高了铜基物质的分散性，增加了CuOx-CeO2界面位点的密度。这种高密度界面位点增加了参与CO氧化的Cu+活性中心数量，优化了催化性能并实现了铈的高效利用。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["稀土负载量[CO-PROX催化剂]: 2、4、8 wt% Ce","催化活性相[SrTiO3纳米立方体载体]: CuOx-CeO2","[CO优先氧化催化剂]: 最大化原子效率并减少关键原材料使用"]},{"i":41727,"as":"通过引入三元乙丙橡胶（EPDM）改性高硬度热塑性聚氨酯（TPU），并利用马来酸酐接枝EPDM和辐射诱导网络形成来调整界面相容性和结构稳健性，开发了用于碳化硅化学机械抛光（CMP）的复合泡沫垫。该设计解决了单一TPU在机械与氧化耦合条件下局部应力集中和疲劳损伤的问题。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":5.0,"t":5.0},"kp":["抛光垫材料[碳化硅化学机械抛光(CMP)]: 界面设计的热塑性聚氨酯(TPU)/三元乙丙二烯单体复合泡沫","[碳化硅CMP工况]: 承受同步机械载荷和强氧化环境"]},{"i":41728,"as":"证明了广泛用于受激发发射耗尽（STED）显微技术启发的亚衍射自由基光刻中的光引发剂DETC，也能有效引发EDOT的氧化逐步聚合。利用可见光，通过多光子聚合（MPP）光刻技术直接光刻形成亚100纳米的PEDOT纳米结构。研究采用了低速扫描低激发功率等多种途径实现亚衍射极限的多光子聚合加工。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["光引发剂[亚衍射多光子聚合(MPP)]: 7-二乙氨基-3-噻吩甲酰香豆素(DETC)","[光引发剂DETC]: 可有效引发PEDOT的氧化聚合"]},{"i":41729,"as":"深入评估二元合金至复杂浓缩合金中，由相互扩散现象所驱动的材料相变过程与机理。","scd":{"b":5.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[合金相变机理]: 由相互扩散现象驱动的材料相变过程（涵盖二元合金至复杂浓缩合金）"]},{"i":41730,"as":"开发了一种由地衣芽孢杆菌模板化纳米银与单宁酸-铁金属酚醛网络组成的复合生物杂化纳米治疗平台。该复合材料具有稳定的表面结构和均匀的纳米银沉积，在TNBS诱导的结肠炎模型中表现出剂量响应性的保护作用。该平台通过调节Wnt和趋化因子信号通路，实现了对发炎肠道上皮完整性及炎症稳态的多模式修复。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["复合材料[发炎结肠治疗]: 地衣芽孢杆菌模板化纳米银结合单宁酸-铁金属多酚网络(TA-Fe)","[炎症性肠病治疗机制]: 通过Wnt和趋化因子重新校准实现多模式修复"]},{"i":41731,"as":"研究团队开发出超长红色磷光碳纳米点。结合机器学习优化的激发态工程，该碳纳米点的磷光寿命达353秒，发光持续超4000秒。光谱分析表明，其超长磷光主要由慢速3(π, π*)到1(π, π*)跃迁通道主导。基于此概念验证，已制成可穿戴无源发光二极管指示器。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":8.0,"t":5.0},"kp":["磷光寿命[红光碳纳米点]: 353秒","发光持续时间[红光碳纳米点]: 超过4000秒","[激发态工程]: 结合机器学习优化实现分钟级超长红光磷光"]},{"i":41732,"as":"为实现碳中和的大容量远距离可再生能源传输，研究提出一种下一代高功率混合换向转换器。该转换器通过强制和增强恢复换向的混合运行模式消除了换相失败风险。克服了第一代电网换相换流器的换相失败隐患，以及第二代电压源换流器碳排放高、鲁棒性低和功率损耗大等缺陷。","scd":{"b":5.0,"i":4.0,"r":4.0,"d":4.0,"t":5.0},"kp":["第一代直流输电系统[基于电网换相换流器]: 存在换相失败风险","第二代直流输电系统[基于电压源换流器]: 具备高可控性"]},{"i":41733,"as":"","scd":null,"kp":[]},{"i":41734,"as":"为解决超高分子量聚乙烯（UHMWPE）人工关节植入物因磨损导致失效的问题，受天然关节润滑机制启发，研究采用本体接枝改性策略，制备出延长使用寿命的生物润滑UHMWPE复合材料。通过引入亲水性阴离子聚合物刷（聚甲基丙烯酸3-磺丙基钾盐），成功实现了增强的水化润滑效果。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":5.0,"t":5.0},"kp":["复合材料[人工关节轴承材料]: 嵌入聚合物刷的超高分子量聚乙烯(UHMWPE)/埃洛石纳米管复合材料","[UHMWPE/埃洛石纳米管复合材料]: 具有增强的水化润滑性能"]},{"i":41735,"as":"针对单质锑（Sb）超快结晶但非晶态稳定性差的问题，研究提出Sb/GaSb4类同质结层状结构。该结构通过界面锑隔离-排出机制稳定富锑局域环境。器件实现了5纳秒的超快开关、大于10^5次的耐久循环和低电阻漂移。界面密度的增加显著提升了结晶温度和数据保持能力。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["器件架构[相变存储器]: Sb/GaSb4类同质结层状结构","相变行为调控[类同质结界面]: 界面密度增加显著提高结晶温度并增强数据保持力","[Sb/GaSb4类同质结界面机制]: 界面锑隔离-排出机制"]},{"i":41736,"as":"针对感染伤口愈合的挑战，研究设计了一种本质多功能的肽卷曲螺旋智能水凝胶。该水凝胶由抗菌四聚体、多肽单体和星形PEG原位共价聚合而成，具备固有的抗菌能力。在Zn2+处理下，水凝胶发生快速可控的动态收缩，主动拉拢伤口边缘，实现物理闭合伤口与环境调节的双重功能。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["智能水凝胶[成胶组分]: 抗菌四聚体与刺激响应二聚体整合的肽卷曲螺旋基序","[主动感染伤口管理]: 能够同时调节伤口微环境并实现物理收缩闭合伤口"]},{"i":41737,"as":"为打破多相加氢反应中活性与选择性的权衡限制，研究提出协同调节皮克林乳液界面微环境与双金属活性位点电子结构的策略。利用功能化季铵盐聚醚表面活性剂在二氧化硅纳米颗粒表面自组装形成微反应器，原位锚定PdCu双金属催化剂。实验与DFT计算揭示了该体系在对氯硝基苯选择性加氢中的独特协同机制。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[催化剂设计]: 利用皮克林乳液界面工程与双金属电子调制协同调控","[选择性加氢]: 打破多相催化中催化活性与选择性的权衡限制"]},{"i":41738,"as":"","scd":null,"kp":[]},{"i":41739,"as":"研究开发了名为DentVLM的牙科视觉语言模型，能够联合解释图像与文本，支持7种牙科成像模态和36项任务的专家级口腔疾病诊断。该模型基于110,447张图像和246万个双语视觉问答对构建，在内外部测试中优于领先的开源与医疗专有模型。在32人参与的研究中，其表现超越初级医师，达到中级医师水平。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["多模态视觉语言模型[牙科诊断]: 支持跨七种牙科成像模态的专家级疾病诊断"]},{"i":41740,"as":"受细胞中双水相系统（ATPS）微滴的启发，研究利用含偶氮苯的自组装肽的超分子纳米纤维成功稳定了富含葡聚糖的微滴。纳米纤维网络有效防止了微滴融合。这一稳定机制使得这些微滴可作为人工微反应器，应用于生化反应的灵敏检测、时空控制以及超灵敏的病毒感染分析。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["微滴[超分子纳米纤维稳定化]: 抑制快速融合并实现病毒感染的超灵敏分析"]},{"i":41741,"as":"研究提出一种利用分子转子共聚焦显微镜揭示粘液及其相关细菌3D粘性结构的技术。该技术能够在无损伤的情况下观测微观形态。对不同来源粘液内部粘度的量化表明，微观粘度变化结构化了微生物的分布与生态相互作用，为探究细菌在粘液栖息地中的个体行为与生态互动提供了新视角。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[粘液定植细菌观测]: 利用共聚焦显微镜与分子转子技术无损揭示3D粘性栖息地"]},{"i":41742,"as":"为解决碳点内禀手性微弱且难以应用于电致发光器件的问题，研究报道了由氟化π共轭碳点组成的超分子自组装体。在M/P-[N]六螺烯手性诱导剂的作用下，通过强烈的静电和氢键相互作用形成定向的超分子自组装。该结构成功应用于明亮的圆偏振电致发光二极管，在三维显示和光电子学等领域具应用前景。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":6.0},"kp":["碳点[手性发光器件]: 通过氟化π共轭超分子自组装诱导手性用于圆偏振电致发光"]},{"i":41743,"as":"研究在二维超原子超导体Au6Te12Se8中观察到一系列反常电荷密度波（CDW）行为。与由纵声子介导、晶格扭曲极小的常规CDW不同，该CDW由横声子主导，并表现出约4埃的实空间位移。此外，该二维材料表现出持续至微米级厚度的维度响应特性，打破了常规CDW在逼近原子极限时消失的现象。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":6.0,"t":6.0},"kp":["晶格畸变[常规电荷密度波]: 10^-12至10^-11米（皮米级）","[二维超原子超导体]: 展现出超越常规声子介导的异常电荷密度波行为"]},{"i":41744,"as":"研究报道了二维磷硫化钴（CoPS3）纳米晶体作为动力学模板，重新编程薄膜形成过程中的分子自组装。通过集体电子相互作用调节分子致密化和相分离路径，成功构建出长程原纤维网络。该形态增强了激子解离和电荷传输并抑制复合，使有机太阳能电池实现了21%的光电转换效率。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":8.0,"t":6.0},"kp":["能量转换效率[有机太阳能电池]: 21%","[薄膜成型工艺]: 利用二维CoPS3纳米晶体作为动力学模板重编程长程定向原纤维自组装"]},{"i":41745,"as":"为解决太阳能蒸发器水传输效率和盐分污垢问题，研究3D打印了具有不同晶格单元的多细胞结构蒸发器，明确了毛细供水和传热的几何参数。优化的FBCC-+_5蒸发器达到了6.90 kg m^-2 h^-1的高蒸发率，并维持零液体排放运行。结合高、低蒸发率单元的混合多细胞架构实现了空间盐结晶。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["[3D打印多细胞太阳能蒸发器]: 识别出液固接触周长、孔隙率和热界面面积作为调控蒸发与空间结晶的关键几何因素"]},{"i":41746,"as":"研究展示了一种基于MoS2、(BA)2PbI4和石墨炔（GDY）三层范德华异质结构的神经形态图像传感晶体管阵列。顶层高迁移率MoS2作为载流子传输通道并保护钙钛矿免受空气影响；夹层2D-(BA)2PbI4将光转化为电并作为光控隧道结。该器件解决了横向导电、空气稳定性和光响应线性度问题，适用于动态视觉处理。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":7.0,"t":7.0},"kp":["神经形态晶体管阵列[范德华异质结]: 由MoS2、(BA)2PbI4和石墨二炔构成的三层结构","[图像传感]: 具备夹层隧道层以实现高线性度并解决横向导电和空气稳定性挑战"]},{"i":41747,"as":"二维材料的晶圆级兼容转移对埃米时代的互补场效应晶体管逻辑器件至关重要。其核心在于将原子级薄的沟道材料从生长晶圆无损转移到目标晶圆叠层中，全程避免污染、应变或界面损伤。实现这一目标需要可扩展的脱层、键合和晶圆级计量技术，以弥合实验室性能与300毫米CMOS制造之间的鸿沟。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":6.0},"kp":["晶圆尺寸[2D材料CMOS制造]: 300-mm","[2D材料转移工艺]: 需在无污染、无应变或无界面损伤下将原子级薄层通道从生长晶圆转移至目标堆叠"]},{"i":41748,"as":"研究证实高阶光子简并性可实现连续体中束缚态（BIC）的拓扑重构。在单层全介电超表面中，Γ点处的E2型高阶简并性充当多电荷库，在对称破缺下释放、反转和合并拓扑电荷。这一机制解锁了Q∝k^-10的极强辐射抑制状态，在纳米光子学中实现了对自由空间辐射的极限压制。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":7.0,"t":7.0},"kp":["Q-k标度指数[常规连续体中束缚态(BICs)]: n = 2-8","[高阶光子简并性]: 驱动拓扑重构以抑制自由空间辐射"]},{"i":41749,"as":"研究利用分子弓（MBs）弓弦中拉伸的C=C键，探究了外力下的开环复分解聚合（ROMP）。实验和理论证明，施加在顺式C=C双键上的拉力增加会显著减缓ROMP反应；而在相同拉伸条件下，反式异构体的ROMP反应则显著加速。这种截然相反的力学响应归因于拉伸条件下不同分子构型的张力变化差异。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[分子弓拉伸应变]: 通过在分子弓弦中引入拉伸的碳碳双键(C=C)调控开环复分解聚合(ROMP)反应"]},{"i":41750,"as":"针对单原子催化剂在电化学二氧化碳还原中的动态配位演化问题，研究提出具有动态配位特性的锌磷（Zn-P3）纳米域。与Zn-N4构型相比，弱键相互作用的Zn-P3在工作条件下表现出电位依赖的结构调制，可能形成类似低配位Zn-Px的亚稳态。原位光谱和理论计算表明，低配位锌和磷位点构成了高效的活性中心。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["[Zn-P3纳米域]: 具有动态配位演化和电位依赖性结构调制特性","[单原子催化剂(CO2还原)]: 具有明确的催化位点 motif 和显著的CO选择性"]},{"i":41751,"as":"研究报道了一种异构集成的量子点敏敏光电晶体管有源像素传感器阵列。该阵列在垂直堆叠架构中集成了基于CMOS的陡峭亚阈值开关晶体管。此技术解决了传统多光谱融合系统存在的分辨率不匹配、面积开销大以及漏电流和信噪比退化等问题，实现了从紫外到近红外波段的光谱信息融合。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":6.0,"t":7.0},"kp":["成像波段[宽带多光谱图像传感器]: 紫外到近红外","[异构集成系统]: 通过宽带图像传感器与亚玻尔兹曼晶体管集成解决读出电路面积、功耗及暗电流问题"]},{"i":41752,"as":"研究报道了用于光谱分辨X射线光子计数的CsPbBr3单晶钙钛矿探测器。该探测器能够分辨透射X射线光谱中的K边缘特征。相较于传统探测器，晶体质量和器件制造工艺的提升使其能承受约13 kV cm–1的电场，在59.5 keV和12 keV能量下分别实现了约5.2%和2.9%的能量分辨率，并具备极高的光子计数率。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":7.0},"kp":["探测器材料[光谱分辨X射线光子计数]: CsPbBr3单晶钙钛矿","[X射线探测能力]: 能够分辨透射光谱中铟、钡和铅的K边特征"]},{"i":41753,"as":"针对2025年能源领域的学术期刊进行引文分析，揭示该领域内文献的引用趋势与影响力。","scd":{"b":1.0,"i":2.0,"r":4.0,"d":3.0,"t":3.0},"kp":[]},{"i":41754,"as":"","scd":null,"kp":[]},{"i":41755,"as":"研究提出一种全维度的第一阶瞬态光传输矩阵（TLTM-1）测量方法，用于非视距成像。通过使用密集激光扫描和16×16单光子雪崩二极管阵列对可见中继表面的TLTM-1进行全采样，可计算恢复隐藏表面之间的时间分辨光传输（TLTM-2），进而在隐藏场景中独立实现虚拟照明和检测的计算聚焦。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[非视距成像算法]: 利用可见中继表面测量的全一阶瞬态光传输矩阵(TLTM-1)恢复时间分辨的二阶矩阵(TLTM-2)"]},{"i":41756,"as":"研究成功在室温下将持久性氮宾转化为可分离的自由基阴离子。该阴离子具有非构造电子排布，表现出亲核氮自由基的特性。在温和条件下，该物质能够成功形成全新的N-Se、N-Si和N-C化学键，为含氮分子的合成提供了新方法。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[氮宾自由基阴离子]: 常温下可分离且具有非构造电子构型","[氮宾自由基阴离子(亲核合成子)]: 在温和条件下形成新的N-Se、N-Si和N-C键"]},{"i":41757,"as":"聚焦半导体器件领域，探讨栅极间距为42纳米的三对三结构特征及其相关技术影响。","scd":{"b":6.0,"i":4.0,"r":8.0,"d":4.0,"t":7.0},"kp":["栅极间距[三对三结构]: 42 nm"]},{"i":41758,"as":"","scd":null,"kp":[]},{"i":41759,"as":"研究人员开发了一种利用糖类合成高价值C-糖苷分子的平台技术。该策略采用糖基磺酰肼作为易得的自由基前体，能够靶向并在碳水化合物支架上实现特定碳-碳键的形成，同时具备对目标三维原子排列的特异性控制能力。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["自由基前体[C-糖苷分子合成]: 糖基磺酰肼","[成键特征]: 具有特定三维原子排列的靶向碳碳键形成"]},{"i":41760,"as":"","scd":null,"kp":[]},{"i":41761,"as":"美国宇航局（NASA）备受瞩目的阿耳忒弥斯二号任务宇航员团队在获得极高知名度的同时，也面临着公众关注带来的不同影响。部分宇航员能够很好地适应这种名气，而另一部分宇航员则可能感到困难，团队可能需要保留一定的个人空间以应对压力。","scd":{"b":2.0,"i":4.0,"r":4.0,"d":2.0,"t":7.0},"kp":[]},{"i":41762,"as":"人工智能正在成为缺乏专业图形设计经验人员的强大辅助工具，使其能够在几分钟内制作出图形摘要。为了确保学术和科学交流的严谨性，研究人员在使用此类AI工具生成图形时，必须保持谨慎和负责任的态度。","scd":{"b":2.0,"i":8.0,"r":4.0,"d":3.0,"t":5.0},"kp":["[无图形设计经验人员]: 人工智能可作为平民化力量辅助制作图形摘要"]},{"i":41763,"as":"《自然》杂志采访了五位专业的科学插画师，探讨了他们如何通过视觉艺术传达科学理念的方法。艺术家们一致认为，尽管人工智能技术在不断发展，但优秀的设计仍然需要深厚的专业掌控力和艺术造诣。","scd":{"b":1.0,"i":3.0,"r":4.0,"d":2.0,"t":5.0},"kp":["[科学插画领域]: 优秀的视觉设计仍需要专业掌控力"]},{"i":41764,"as":"研究人员利用AlphaFold3成功预测了基因组编辑酶（CRISPR复合物）在靶向DNA序列过程中形成的分子接触位点。基于这些高精度的AI预测结果，研究人员有效改进了该酶对其目标DNA序列的选择性和编辑特异性。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":5.0,"t":7.0},"kp":["[AlphaFold3预测基因组编辑酶分子接触]: 用于提高酶对目标DNA序列的选择性"]},{"i":41765,"as":"","scd":null,"kp":[]},{"i":41766,"as":"随着全球气温不断上升，传统空调系统在维持人类凉爽方面已显现出局限性。科学家和工程师正致力于通过研发先进的冷却材料和技术，使建筑物能够更高效地降温，以寻找传统空调的可行替代方案。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":3.0,"t":4.0},"kp":["[建筑降温替代方案]: 材料学进展可实现气温上升时的建筑冷却"]},{"i":41767,"as":"人工智能工具在头脑风暴和图形创作方面具有实用性，但极易引入科学性错误。为避免AI生成的图像在科学研究中出现误导，文章提出了三个实用技巧，指导研究人员如何识别并规避这些AI图像生成过程中的潜在问题。","scd":{"b":2.0,"i":4.0,"r":5.0,"d":3.0,"t":4.0},"kp":["[科学领域AI生成图像]: 需采取三个关键技巧以规避引入的错误"]},{"i":41768,"as":"","scd":null,"kp":[]},{"i":41769,"as":"","scd":null,"kp":[]},{"i":41770,"as":"","scd":null,"kp":[]},{"i":41771,"as":"","scd":null,"kp":[]},{"i":41772,"as":"","scd":null,"kp":[]},{"i":41773,"as":"通过纳米结构化处理，纳米级金属系统在力学、机器人技术、催化和光子学领域的独特性能可得到显著放大。这篇综述重点介绍了用于生产此类金属系统（包括金属、合金和金属氧化物）的关键纳米级增材制造技术，及其在下一代应用中的独特优势。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[纳米尺度金属系统]: 通过纳米结构化放大材料性能以在力学、机器人、催化和光子学中实现独特表现","[纳米尺度金属、合金及金属氧化物]: 关键纳米尺度增材制造技术及新一代应用"]},{"i":41774,"as":"探讨利用自蔓延化学反应实现环境含氟聚合物的回收与升级循环技术。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[环境含氟聚合物升级循环]: 利用自蔓延化学反应实现自我回收"]},{"i":41775,"as":"为解决卤化物钙钛矿在神经形态光电器件中操作稳定性不足的问题，研究采用气相生长技术，成功制备出成分可调的二维无机钙钛矿（Csx）。该材料作为光电突触，能够提供持续且可重复的光电响应，满足传感器内计算的需求。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["[神经形态光电子学中的卤化物钙钛矿]: 操作不稳定性为关键障碍","[神经形态视觉二维钙钛矿光电突触]: 采用气相生长技术制备成分可调的二维无机钙钛矿(Csx)以解决稳定性问题"]},{"i":41776,"as":"研究提出一种利用手性诱导自旋选择性效应调节Co3O4催化剂自旋态的新策略。通过调节手性不对称因子g来操控电子自旋，有效提升了催化剂的活性，成功实现了锂硫电池电化学动力学的加速。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":7.0,"t":7.0},"kp":["[手性催化剂不对称因子g]: 通过手性诱导自旋选择效应调节以加速锂硫电池电化学动力学","[Co3O4自旋态调节]: 依赖手性诱导自旋选择效应的创新策略"]},{"i":41777,"as":"传统有机光催化常因聚集导致的激发态失活而受限。研究利用超分子染料聚合物，通过激发态限域和分子刚性化来利用聚集效应，成功改善了光化学反应活性，为太阳能到化学能的转化提供了有效的新途径。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":6.0},"kp":["[超分子染料聚合物]: 利用激发态限制和分子刚性化引发的聚集效应实现高效光催化"]},{"i":41778,"as":"","scd":null,"kp":[]},{"i":41779,"as":"","scd":null,"kp":[]},{"i":41780,"as":"","scd":null,"kp":[]},{"i":41781,"as":"研究采用自下而上的合成策略，成功制备出结合了半导体特性与铁磁性的镧系MXene（Ln2CT2）。该新型二维材料通过插层卤化物制备，在自旋电子学应用领域展现出重要前景。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[插层卤化物稀土MXene(Ln2CT2)]: 采用自下而上的合成策略兼具半导体特性与铁磁性"]},{"i":41782,"as":"","scd":null,"kp":[]},{"i":41783,"as":"研究设计出一种具有定制纳米通道的合成共价有机框架（COF）膜。该膜利用水分子在亚纳米孔中单列排列并快速通过的现象，在保持高水流通量的同时，实现了对盐分和有害挥发物的高效双重截留，突破了传统净水膜的局限。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[亚纳米孔道水传输]: 水分子呈单链排列实现超快传输","脱盐脱挥发分性能[COF合成膜]: 高截留率且允许水流快速通过"]},{"i":41784,"as":"为解决钙钛矿太阳能电池中自组装单分子层（SAMs）因界面键合强度有限而易脱落的问题，研究设计了具有供体-受体-供体（D-A-D）共振结构的分子。电子共振效应显著增加了受体锚定基团上的负电荷密度，极大增强了膦酸与铟锡氧化物（ITO）之间的锚定强度，提升了器件的电荷提取能力和长期稳定性。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["自组装单分子层(SAMs)[钙钛矿太阳能电池]: 锚定于透明导电氧化物形成界面分子偶极子以提取载流子","[SAMs应用瓶颈]: 配位位点电子密度受限导致键合强度不足，在运行应力下易发生脱附并损害电荷提取"]},{"i":41785,"as":"","scd":null,"kp":[]},{"i":41786,"as":"","scd":null,"kp":[]},{"i":41787,"as":"近期的技术突破表明，实用化的量子计算机设备有望在未来十年内面世。","scd":null,"kp":["[量子计算机]: 预计在未来十年内出现可用设备"]},{"i":41788,"as":"","scd":null,"kp":[]},{"i":41789,"as":"","scd":null,"kp":[]},{"i":41790,"as":"研究将溶液生长的钙钛矿微板与化学惰性单壁碳纳米管电极集成并嵌入光学微腔中。这种新型微器件能够在8K的低温环境下，在恒定直流电的驱动下实现极化激元激光发射，且无需采用外延技术。","scd":{"b":8.5,"i":3.5,"r":8.0,"d":7.5,"t":7.5},"kp":["极化激元激光[溶液生长钙钛矿微盘结合单壁碳纳米管电极嵌入光学微腔]: 恒定直流下实现","工作温度[极化激元激光二极管]: 8 K"]},{"i":41791,"as":"","scd":null,"kp":[]},{"i":41792,"as":"利用冷冻电子显微镜技术，研究解析了布氏锥虫线粒体编辑体（editosome）的精细结构。研究揭示了该复合物如何通过精准插入和删除尿苷核苷酸的方式介导mRNA编辑的分子机制。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["[布氏锥虫线粒体编辑体]: 介导mRNA编辑的尿苷插入与缺失级联反应","结构基础[冷冻电镜]: 揭示了RNA编辑级联的架构"]},{"i":41793,"as":"研究开发了一种使用烷基肼和酰肼作为自由基前体的统一合成平台。这些前体在温和的热激活条件下释放氮气（N2）生成烷基自由基，能够高化学选择性地合成结构复杂且富含官能团的亚磺酸盐、磺酰氟和亚磺酰胺等烷基硫（VI）化合物。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.5,"t":7.0},"kp":["反应条件[烷基肼和酰肼自由基前体]: 简单的热激活下发生N2挤出","化学选择性[温和条件]: 高度化学选择性地生成亚磺酸盐、磺酰氟和亚磺酰胺"]},{"i":41794,"as":"","scd":null,"kp":[]},{"i":41795,"as":"","scd":null,"kp":[]},{"i":41796,"as":"研究开发了一种虚拟现实嗅觉范式，允许头部固定的果蝇探索结构化的化学环境。研究发现，果蝇会利用气味遭遇的记忆来推断化学环境的空间结构，通过沿着气味走廊的边界交替移动来追踪嗅觉线索。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":7.0},"kp":["[嗅觉导航策略]: 可利用过往气味遭遇记忆推断化学环境的空间结构及自身位置"]},{"i":41797,"as":"ContactSeek是一种基于AlphaFold3的接触建模工具，旨在提高基因组编辑工具（如DNA碱基编辑）的精确度。","scd":{"b":8.5,"i":3.0,"r":8.0,"d":6.0,"t":8.0},"kp":["[ContactSeek模型]: 基于AlphaFold3的接触建模，可提升基因组编辑工具的精确度"]},{"i":41798,"as":"研究利用AI模型ProteinMPNN重新设计了三种肉毒杆菌神经毒素（BoNT）蛋白酶，生成了具有更高稳定性和完全催化效率的变体。以AI重设计的酶作为起点进行噬菌体辅助连续进化，能够更有效地进化出具有新功能的酶。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["[AI蛋白质序列设计]: 基于ProteinMPNN模型重新设计肉毒杆菌神经毒素蛋白酶(BoNT)","[AI改造蛋白性能]: 生成具有改善稳定性和完全催化效率的变体"]},{"i":41799,"as":"研究发布了大堡礁微生物基因组数据库（GBR-MGD），包含5,283个源自大堡礁海水样本的原核生物基因组。通过结合Nanopore和Illumina测序技术，成功获取了代表性不足的海洋菌群高质量基因组，解决了标准短读长组装会遗漏这些种群的问题。","scd":{"b":6.0,"i":2.0,"r":8.0,"d":6.0,"t":6.0},"kp":["[海洋微生境基因组数据库]: 存在Pelagibacter和Prochlorococcus等优势谱系代表性不足的问题"]},{"i":41800,"as":"研究构建了黑腹果蝇神经索的高分辨率发育转录图谱，聚合覆盖度达到参考基因组的38倍。该图谱系统揭示了果蝇出生顺序与神经元分子身份及感觉运动回路连接性之间的全球分子密码，将神经元分子身份与神经回路架构直接联系起来。","scd":{"b":7.0,"i":1.0,"r":7.0,"d":4.0,"t":7.0},"kp":["[单细胞转录组学与连接组学]: 实现对神经系统多样性的系统和高分辨率表征，以解析神经元分子身份与回路的关联"]},{"i":41801,"as":"核基因组通过染色体结构域与亚核区室（如核纤层和核斑点）的物理相互作用，形成三维空间架构。研究绘制了妊娠中期人类皮层神经源性细胞系中基因组与核纤层及核斑点相互作用的高分辨率图谱，揭示了亚核基因组区室化与二价染色质活性之间的紧密联系。","scd":{"b":7.0,"i":1.0,"r":7.0,"d":4.0,"t":7.0},"kp":["[核基因组三维空间组织]: 通过染色体结构域与亚核区室物理结合进行组织","[亚核基因组区室化机制]: 控制二价染色质活性"]},{"i":41802,"as":"单原子测量揭示了在连续相变过程中存在非高斯有序参数波动和临界标度现象，这表明在理解相变的普适性时，完整的统计分布分析至关重要。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[相变过程临界标度]: 具有非高斯有序参数波动"]},{"i":41803,"as":"冷冻扫描透射电子显微镜（Cryo-STEM）观察发现，量子顺电材料SrTiO3在105 K以下会形成周期性极性纳米畴，而在40 K以下这些纳米畴会发生碎裂。该现象将量子顺电性与纳米尺度的极性有序及无序化联系了起来。","scd":{"b":7.0,"i":2.0,"r":8.0,"d":7.0,"t":7.0},"kp":["[SrTiO3极性纳米畴形成]: < 105 K","[SrTiO3极性纳米畴碎裂]: < 40 K","[量子顺电性表征]: 纳米级极性纹理"]},{"i":41804,"as":"","scd":null,"kp":[]},{"i":41805,"as":"研究通过径向速度分析技术，在恒星亚星伴星（褐矮星 CD-35 2722 B）周围直接成像并检测到了行星质量的系外卫星。这是首次在围绕褐矮星伴星运行的轨道上发现系外卫星的证据。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["[已发现系外行星数量]: > 6000"]},{"i":41806,"as":"研究开发了一种裂解辅助转移印刷方法，实现了无镉的红、绿、蓝量子点纳米像素的超高分辨率图案化 patterning。该技术突破了量子点高分辨率图案化的制造难题，为制造具有极宽色域的全彩有源矩阵显示器铺平了道路。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":4.0,"t":6.0},"kp":["[量子点图案化技术]: 裂解辅助转移印刷方法","[全彩显示器核心组件]: 无镉红绿蓝量子点纳米像素"]},{"i":41807,"as":"研究开发了一种光驱动的宪法泵，通过在可逆的动态共价复分解反应中嵌入单向且动力学主导的路径，使系统在连续光照下能够达到高度的非平衡状态。该技术克服了热平衡共价反应微观可逆性带来的限制，实现了生物模拟的耗能型分子重组行为。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[动态共价化学状态]: 实现高度非平衡"]},{"i":41808,"as":"针对尖晶石型锂超离子导体中骨架短程有序现象的观察进行学术更正与补充说明。","scd":{"b":3.0,"i":2.0,"r":3.0,"d":2.0,"t":4.0},"kp":[]},{"i":41809,"as":"介绍基于激发态分子内质子转移机制，在活细胞内实现自我报告的荧光光亲和标记技术。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":3.0,"t":5.0},"kp":["荧光光亲和标记技术[活细胞内]: 基于激发态分子内质子转移机制实现自我报告"]},{"i":41810,"as":"研究开发了一种由重氮硼烷（RLBN2）介导的新型硼化反应。重氮硼烷作为双配位硼烯，能够直接发生插入烯属C-H键的反应，这与传统依赖不饱和键加成或离去基团取代的硼化过程不同。该反应具有广泛的底物适用性，涵盖单取代和双取代烯烃。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[烯属C-H键硼化反应]: 由重氮硼烷介导并发生硼插入"]},{"i":41811,"as":"介绍通过烯炔氢胺化反应策略，全合成二萜类生物碱Thelepogine的化学研究过程。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":3.0,"t":5.0},"kp":["全合成策略[二萜类生物碱Thelepogine]: 烯炔氢胺化反应"]},{"i":41812,"as":"对先前关于无需并四苯衍生物、利用近红外二区激发实现三重态光子上转换研究的更正。","scd":{"b":3.0,"i":1.0,"r":3.0,"d":2.0,"t":4.0},"kp":[]},{"i":41813,"as":"研究利用光驱动手段，对超分子纳米管中的激子态实现选择性控制的光物理机制。","scd":{"b":6.5,"i":2.0,"r":4.0,"d":3.0,"t":5.0},"kp":["激子态控制[超分子纳米管]: 光驱动选择性控制"]},{"i":41814,"as":"研究评估了机器学习模型在预测合成化学反应产率时，描述符复杂度对模型准确性的影响。通过在包含Buchwald-Hartwig胺化反应等四个公开高通量实验数据集上进行基准测试，证实了使用较简单的描述符和经典机器学习模型即可实现高效的反应结果预测，且具有更好的可解释性和可扩展性。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[合成化学反应产率预测]: 采用简单描述符的机器学习模型具有良好准确性与可扩展性"]},{"i":41815,"as":"研究提出了一种基于正交纳米佐剂（Mn/Al层状双氢氧化物纳米片）的呼吸道合胞病毒（RSV）F亚基纳米疫苗平台。其中铝作为佐剂促进强大的体液免疫和抗体反应，而锰和CpG基序通过激活cGAS-STING途径和Toll样受体增强细胞免疫，有效解决了RSV亚基疫苗接种中细胞免疫不足的挑战。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["[RSV亚基疫苗构建]: 基于Mn/Al层状正交纳米佐剂平台","[RSV亚基疫苗免疫效应]: 类高熵免疫刺激，克服细胞免疫不足"]},{"i":41816,"as":"报道通过精确融合共轭有机硼烷，制备具有窄带荧光及微尺度激光特性的硼掺杂碳分子。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":4.0,"t":5.0},"kp":["发光特性[硼掺杂分子碳]: 窄带荧光及微尺度激光"]},{"i":41817,"as":"热蒸发技术提供了一种无溶剂制备钙钛矿太阳能电池和叠层结构的方法，能够精确控制薄膜生长、界面和层厚。共蒸发、顺序蒸发和混合气相加工支持了多层和大规模集成；然而，源稳定性、沉积速率、材料利用率和面积均匀性仍是实现高效器件向可扩展模块转化的主要障碍。","scd":{"b":5.0,"i":5.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[钙钛矿光伏制备工艺]: 热蒸发路线（无溶剂）","[钙钛矿光伏规模化关键障碍]: 源稳定性、沉积速率、材料利用率和大面积均匀性"]},{"i":41818,"as":"结合中子散射和固态核磁共振（NMR）技术，研究确定了混合有机-无机金属氧化物（混合青铜）（4,4'-bipy）0.5HxMoO3 中插入质子的具体位置。实验观察到氢原子局域在金属氧化物层的桥氧和端氧位置上，为平衡混合化合价提供了电荷，解决了影响混合青铜基础和应用潜力的关键结构问题。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["测试温度[中子散射分析微晶粉末]: 10 K","测试温度[固态核磁共振分析]: 室温","[混合钼青铜中间隙质子定位]: 观察到氢原子局部化的明确证据"]},{"i":41819,"as":"","scd":null,"kp":[]},{"i":41820,"as":"研究提出了一种以缠结为主导的设计策略，将密集的物理链缠结与稀疏的触发可裂解共价交联相结合。该策略使得高性能热固性塑料能够实现代际不变的再生，为循环工程塑料的开发开辟了新途径。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":5.0,"t":5.0},"kp":["设计策略[工程塑料热固性聚合物]: 密集的物理链纠缠与稀疏的触发可裂解共价交联相结合","再生特性[高性能热固性材料]: 具有跨代不变的再生能力"]},{"i":41821,"as":"研究使用双金属Pt-Co催化剂解开了催化反应中界面协同效应与电子效应的关联。实验结果表明，相比Pt/Al2O3，Pt-Co/Al2O3催化剂表现出更高的CO氧化速率。特别是Pt3Co1/Al2O3催化剂的转化频率增加了46倍，且反应级数的负值减小，证实了通过电子调节改变CO吸附行为可显著提升催化氧化效率。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["催化机制[双金属纳米粒子催化剂上的CO氧化]: 通过调节电子效应改变CO吸附行为，从而将界面协同作用转化为反应速率的提升"]},{"i":41822,"as":"光控SPAAC（光点击）反应能够高效制备中环至大环结构。带有环丙烯酮保护的二苯并环辛炔和叠氮基团的双官能团线性分子发生环化，产率高至定量。该方法在溶液和本体状态下均成功合成了18至51元环的大分子，反应物表现出极高的有效摩尔浓度且无二聚体或低聚物生成。此外，通过SPAAC-光SPAAC反应序列也成功制备了17至34元环结构。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["大环结构尺寸范围[光SPAAC环化反应制备]: 18元环至51元环","反应产率[光SPAAC分子内环化制备大环]: 高至定量产率"]},{"i":41823,"as":"","scd":null,"kp":[]},{"i":41824,"as":"探讨硅化镍种子层技术在3D NAND闪存制造工艺中的应用及其对器件性能的影响。","scd":{"b":6.0,"i":6.0,"r":5.0,"d":3.0,"t":6.0},"kp":["工艺技术[3D NAND闪存]: 硅化镍种子层应用"]},{"i":41825,"as":"研究结合各向同性与各向异性NMR观测数据、增强采样模拟和密度泛函理论（DFT）计算，系统探究了含有芳基和杂联芳基的环肽在溶液中的构象。大环肽具有潜在的口服生物利用度，引入芳香杂环可赋予其特定的构象偏好。通过残余偶极耦合（RDC）测量等综合分析方法，有效揭示了这些复杂大环分子的溶液态结构和动力学特征。","scd":{"b":5.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["大分子特性[引入（杂）芳基的大环多肽]: 赋予分子独特的构象偏好并扩展结构空间","技术难点[（杂）芳基大环分子的溶液态结构解析]: 准确测定其溶液态结构和动力学仍具挑战性"]},{"i":41826,"as":"研究利用SpyTag/SpyCatcher生物正交系统合成了具有化学不对称性的核小体，以区分H3K9me3识别位点与泛素受体赖氨酸。实验表明，H3K9me3标记通过分子内（顺式）机制优先激活UHRF1 E3连接酶。生化分析证实，这一激活过程依赖于UHRF1对H3K9me3修饰的协同识别与其在同一分子上的催化活性之间的物理耦合，对表观遗传至关重要。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["合成方法[预定义化学不对称核小体]: 利用SpyTag/SpyCatcher生物正交系统进行合成","分子机制[UHRF1 E3连接酶受H3K9me3标记激活]: 确证了其精准的分子内作用模式"]},{"i":41827,"as":"研究针对工业硅氢加化反应提出了可回收的双相催化体系。通过在室温下将K2PtCl4溶于水（或含KBr的水中）仅需2分钟即可制备出Pt/H2O和Pt/KBr/H2O催化剂。机理研究揭示了一种此前未知的、具有极高催化活性的物质。这种新型催化体系不仅解决了传统工艺的痛点，还实现了从功能化单体到聚合物材料的高效合成。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":6.0,"t":7.0},"kp":["催化体系[可回收双相水硅烷化反应]: 铂/水（Pt/H2O）催化体系和铂/溴化钾/水（Pt/KBr/H2O）催化体系"]},{"i":41828,"as":"研究报道了一种由手性磷酸（CPA）催化烯丙基伯醇的不对称SN1反应。碳正离子由于不稳定且反应活性高，极难实现精确的立体控制。该策略通过离去基团与手性催化剂形成复合物来调节反应活性并控制对映选择性，成功在SN1反应中构建了最优的手性环境，克服了传统碳正离子反应在精确立体控制方面的巨大挑战。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":7.0},"kp":["立体控制策略[手性磷酸催化的不对称SN1反应]: 通过手性催化剂在碳正离子周围建立最佳的局部手性环境以实现高对映选择性"]},{"i":41829,"as":"针对钙钛矿-硅叠层太阳能电池中宽带隙钙钛矿在自组装分子（SAM）上结晶时易受溶剂损伤的问题，研究提出了一种界面工程策略。通过在SAM与钙钛矿活性层之间引入3-噻吩甲胺盐酸盐（3-TMA）分子层，利用芳香噻吩单元与底层SAM建立强烈的π-π堆积作用，形成了抗溶剂中间层，从而在结晶过程中稳定了SAM的锚定结构，提升了器件性能。","scd":{"b":6.0,"i":5.0,"r":6.0,"d":6.0,"t":7.0},"kp":["界面工程策略[宽带隙钙钛矿结晶调节]: 在SAM和钙钛矿层间引入噻吩-3-基甲胺盐酸盐（3-TMA）分子层"]},{"i":41830,"as":"针对双缆共轭聚合物单组分有机太阳能电池（SCOSC）中快速发生孪生复合导致效率受限的问题，研究提出一种热力学策略。该策略利用D18聚合物层设计了具有0.02 eV精确最高占据分子轨道（HOMO）能级偏移的界面能量阶梯。这将被视为能量陷阱的“冷”孔的超长寿命转化为热活化电荷提取的资源，成功克服了复合限制，实现了15.6%的光电转换效率。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":7.0},"kp":["能量转换效率[单组件有机太阳能电池]: 15.6%","电荷转移态寿命[双缆共轭聚合物供体-受体系统]: >5 ns","物理机制[热激活单组件有机太阳能电池]: 通过热激活“冷”孔克服单组件器件中的复合限制"]},{"i":41831,"as":"研究证实，配体诱导的结构转变是精确操纵银团簇几何与电子结构及理化性质的有效策略。研究发现，碗状锑钨酸盐（{Sb3W30}-3）配体构象的微小变化，即可对多金属氧酸盐（POM）封装银簇（Agn@POM）的合成产生巨大影响。该工作展示了通过微小结构调整来实现特定多金属氧酸盐封装金属团簇及其结构衍生物的合成。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":7.0},"kp":["多金属氧酸盐[结构形态]: 碗状","原子级精确银簇[封装基元]: {Ag7}5+ 簇","[结构调控机制]: 配体诱导的结构转变"]},{"i":41832,"as":"研究报道了二聚体倍半萜Myltayloriones A和B的首次不对称全合成。合成路线包括：利用立体发散的Echavarren Au催化反应从共同前体制备两个亚基，并发生内型Diels-Alder杂二聚化。其他关键反应还包括用于C1异构化的配体控制Pd催化还原氢解，以及通过金属催化氢原子转移（MHAT）引发的Baran-Giese环化构建拥挤的五取代环丙烷。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":4.0,"t":7.0},"kp":["[二聚倍半萜类化合物Myltayloriones A-B]: 首次不对称全合成","[关键成环反应]: 立体发散型Echavarren金催化反应及endo-狄尔斯-阿尔德杂二聚化","[C1位官能化]: 配体控制的钯催化还原氢解"]},{"i":41833,"as":"针对质子交换膜燃料电池（PEMFC）中全氟磺酸离聚物在Pt表面强吸附导致催化剂中毒和传质受阻的问题，研究引入了羟基功能化共价有机框架（COF-366-OH）作为多功能添加剂。该材料周期性排列的羟基基团构建了强化的氢键网络，工程化了Pt/离聚物界面，协同提升了活性位点的可利用性、质子传导率和氧气通量，实现了高性能低铂燃料电池。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":7.0},"kp":["催化剂/离聚物界面[低铂燃料电池]: 强化氢键网络设计","质子导电性与氧渗透性[羟基功能化界面]: 达到有效平衡"]},{"i":41834,"as":"研究实现了一种由Ti(IV)配合物发生的全新四电子转化，生成了具有螺戊烷骨架的罕见双（二硫化物）钛配合物（Ti(S2)2）。利用该富硫配合物快速且高选择性形成的特点，成功将其应用于异腈类化合物催化合成异硫氰酸酯的硫原子转移反应中，拓展了钛元素在多电子转化及原子转移反应中的应用。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":7.0},"kp":["催化转化过程[Ti(IV)双二硫化物配合物]: 四电子转化","[钛双配合物]: 实现了罕见的硫原子转移催化"]},{"i":41835,"as":"为解决硅负极在锂离子电池充放电过程中的巨大体积膨胀问题，研究开发了一种可扩展的原子级工程硅碳复合负极材料合成策略。该工艺将硅单原子和纳米簇（小于1.0 nm）化学锚定在坚固的碳基质微孔中。这种结构利用预留的内部空隙吸收硅嵌锂产生的膨胀，显著减轻了电极宏观肿胀。组装成2 Ah软包电池后，展现出了高耐用性和低膨胀率。","scd":{"b":7.0,"i":6.0,"r":6.0,"d":7.0,"t":7.0},"kp":["硅尺寸限制[微孔碳基体]: < 1.0 nm (单原子及纳米团簇)","硅碳复合负极[合成策略]: 可规模化的原子级精密锚定工艺"]},{"i":41836,"as":"为解决钠离子电池锰基层状氧化物（MRLO）正极材料结构不稳定和钠离子扩散缓慢等问题，研究提出了一种连续两步热处理工艺。该工艺结合了传统马弗炉煅烧与高温冲击（HTS）技术，实现了对MRLO相组成的精确调控。由于单一的O3或P2相无法同时满足结构稳定性与离子传输的需求，这种精确的相调控策略成功增强了材料的电化学性能。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":4.0,"t":5.0},"kp":["锰基层状氧化物[钠离子电池正极]: 具有高理论容量和低成本的定性特征","[相变机制]: 存在超快相变途径"]},{"i":41837,"as":"研究开发了一种基于泡沫镍的活化磷化镍（A-Ni3P@NF）集成非贵金属阳极，用于直接氨燃料电池（AEM-DAFC）。通过磷掺杂策略引入可调的缺陷中心，该阳极在氧气和空气环境中均表现出优异的催化活性和长期的稳定性。这一成果克服了传统粉末基非贵金属催化剂功率密度低和耐久性差的局限，摆脱了对贵金属的依赖，促进了可持续能源转换。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":4.0,"t":5.0},"kp":["阳极催化剂[直接氨燃料电池]: 集成非贵金属","[非贵金属阳极]: 在纯氧和空气中均表现出高活性和长稳定性"]},{"i":41838,"as":"针对硫化物固态电解质（如Li6PS5Cl）在高压下易发生严重氧化分解的问题，研究指出其降解是由碳界面处的离子-电子耦合传输（IECT）机制控制的。为此，研究提出了一种“低离子电子传输”（LIET）策略，通过在导电添加剂上工程化修饰含氮杂环共轭聚合物层，同时阻挡电子隧穿并锚定界面锂离子，无需进行正极改性即可有效抑制电解质氧化，实现全固态电池稳定运行。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":4.0,"t":5.0},"kp":["降解机制[硫化物固态电解质]: 离子-电子耦合传输 (IECT)","[全固态电池稳定性策略]: 降低电子传输以抑制高压氧化分解，无需阴极改性"]},{"i":41839,"as":"为解决锂-空气电池中多相界面（锂离子、氧气和电子汇聚点）难以维持稳定的问题，研究开发了一种简便且可扩展的重力辅助渗透（GAI）策略制备空气阴极。该技术将催化剂锚定在整个气体扩散层骨架中，构建了空间扩展且动态稳定的多相界面，保障了放电产物可逆生成与分解的持续进行，有效推动了高能量密度锂空气电池的实用化。","scd":{"b":8.0,"i":2.0,"r":4.0,"d":4.0,"t":5.0},"kp":["多相界面构建[锂空气电池空气阴极]: 重力辅助渗透策略","[空间扩展和动态稳定]: 实现了多相界面的空间扩展与动态稳定"]},{"i":41840,"as":"研究开发了一种基于镍催化各种取代连二烯（包括单取代和1,3-二取代）的通用平台，高效模块化地实现了不对称硅氢加成反应。利用新开发的SPSiOL衍生双亚磷酸酯配体（SPSiOP），单取代连二烯的硅氢加成反应展现出优异的区域选择性和对映选择性，成功制备出多种光学纯的烯丙基硅烷，并进行了首例动力学研究分析。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":4.0,"t":5.0},"kp":["[多种丙二烯衍生物]: 实现了高效、模块化的对映选择性氢硅烷化","[光学纯烯丙基硅烷合成]: 镍催化通用平台"]},{"i":41841,"as":"为解决质子交换膜水电解槽中金属氧化物析氧（OER）与析氢（HER）活性难以兼顾的矛盾，研究利用冰盐模板法制备了具有原子无序度和不饱和度的超薄RuIr双金属烯氧化物。这种无序结构触发了局域电子态，协同促进HER和OER反应；原子级薄层结构则诱导配位不对称，打破了Ru/Ir-O键的共价性，为实现经济高效的对称质子交换膜水电解提供了理想材料。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":4.0,"t":5.0},"kp":["双金属催化剂[对称PEMWE]: 超薄原子无序RuIr双金属烯氧化物","催化特性[酸性OER/HER]: 打破活性-稳定性悖论并克服金属氧化物HER天然惰性"]},{"i":41842,"as":"硫化物电解质基全固态锂金属电池面临热-电化学耦合失效问题。研究提出双热稳定策略：引入氟化石墨烯（FG）中间层以增强散热并偏转锂枝晶，同时添加富氧空位氧化铜（CuO1−x）捕获充放电正极释放的活性氧，缓解电解质氧化。该策略从根本上提升了电池在滥用条件下的安全性和热稳定性。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":4.0,"t":5.0},"kp":["热稳定策略[硫化物基ASSLMBs]: 引入氟化石墨烯(FG)层进行双热稳定修饰","界面功能[FG层]: 增强散热并偏转锂枝晶"]},{"i":41843,"as":"倒置钙钛矿太阳能电池的电压输出和耐久性受限于表面缺陷和界面能。研究开发了一种沉积后表面修饰技术，在界面处植入由SCP分子构成的超薄多功能层。该分子的特定基团与未配位的Pb2+配位，同时Na+提供离子补偿。这种多点位协同作用有效降低了陷阱辅助复合，抑制了界面离子活性，从而提升器件效率。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":4.0,"t":5.0},"kp":["表面修饰剂[倒置钙钛矿太阳能电池]: 1-(4'-磺酸基苯基)-3-羧基-5-吡唑酮钠盐(SCP)超薄多功能分子层","修饰机制[钙钛矿电子接触界面]: 磺酸基/羧基与吡唑酮协同实现表面钝化与能量管理"]},{"i":41844,"as":"为克服非贵金属单原子催化剂因缺电子和缺乏相邻金属位点导致的氢化活性受限问题，研究通过浸渍-热解法在ZIF-8上合成含有Co-Co键的同核双原子钴位点催化剂（Co-DAC）。该催化剂在硝基芳烃氢化和炔烃半氢化反应中表现出优异的本征选择性，其转化频率（TOF）达到431 h−1，显著提升了催化效率。","scd":{"b":7.0,"i":2.0,"r":4.0,"d":4.0,"t":5.0},"kp":["催化剂结构[选择性氢化]: 含Co-Co键的同核双原子钴位点催化剂(Co-DAC)","制备工艺[Co-DAC]: 通过简单配体吸附法将Co2络合物吸附至ZIF-8上"]},{"i":41845,"as":"","scd":null,"kp":[]},{"i":41846,"as":"","scd":null,"kp":[]},{"i":41847,"as":"为解决传统非手术迷走神经刺激（VNS）中电流扩散广、阻抗高及易刺激周围组织等问题，研究开发了一种无线贴皮VNS贴片。该贴片采用3D液态金属电极，其低弹性模量能模拟生物组织，穿透角质层从而改善电极-组织耦合，并最大程度减少组织损伤。该平台为抑郁症小鼠模型中的VNS生物机制研究提供了微创工具。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["电极材料[迷走神经刺激贴片]: 模拟生物组织低模量的三维液态金属电极","技术优势[无线VNS贴片]: 克服电流扩散广、电极-皮肤阻抗高及意外刺激周围组织等缺陷"]},{"i":41848,"as":"研究探讨了TmVO4单晶中Tm离子的超精细耦合如何影响电子铁四极有序基态及其量子相变。当温度降至超精细能量尺度时，核矩降低了电子有序的临界磁场，导致铁四极有序相边界发生显著回弯现象。该行为符合单离子半经典平均场模型（低至50 mK），有效哈密顿量分析预测存在由4f电子介导的自发核磁有序。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["物理效应[TmVO4电核量子相变]: 超精细耦合作用导致核矩降低电子有序态的临界磁场"]},{"i":41849,"as":"二维II型多铁性材料NiI2具有自旋诱导铁电极化的强磁电耦合特性。结合广义自旋流模型与第一性原理计算，研究构建了自旋诱导极化的综合磁电模型。结果表明，第三近邻自旋对对电极化的贡献出人意料地大，可与第一近邻相媲美。该模型成功预测了螺旋畴界处由极化产生的束缚电荷及极性涡旋晶格。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["磁电耦合机制[2D type-II multiferroic NiI2]: 第三近邻相互作用诱导自旋极化"]},{"i":41850,"as":"","scd":null,"kp":[]},{"i":41851,"as":"","scd":null,"kp":[]},{"i":41852,"as":"","scd":null,"kp":[]},{"i":41853,"as":"","scd":null,"kp":[]},{"i":41854,"as":"错误折叠蛋白的寡聚体是疾病治疗的关键早期靶点，但其异质性和瞬时性导致观测困难。研究利用单分子质量光度法（MP）直接观察与额颞叶痴呆相关的tau蛋白P301L突变体寡聚体群的变化。通过全局拟合各寡聚体群的动力学数据，确立了微观聚集机制模型，该模型扩展后同样适用于淀粉样纤维的动力学过程，为靶向抑制剂开发提供了精确方法。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":6.0},"kp":["表征方法[蛋白质聚集机制]: 单分子质量光度法(MP)","技术特点[低聚物检测]: 直接观测并解析异质且瞬态的早期小分子低聚物群体变化"]},{"i":41855,"as":"","scd":null,"kp":[]},{"i":41856,"as":"","scd":null,"kp":[]},{"i":41857,"as":"","scd":null,"kp":[]},{"i":41858,"as":"","scd":null,"kp":[]},{"i":41859,"as":"","scd":null,"kp":[]},{"i":41860,"as":"针对不同弹性材料界面的剪切粘附力问题，研究建立了一个跨越广泛模量对比的统一力学框架。通过推导弹性粘合剂的分析解并进行实验和有限元模拟验证，发现尽管系统承受全局剪切载荷，但界面失效主要由边缘引发的剥离主导。该机制解释了硬化粘合剂并不能单调增强剪切粘附力，澄清了力学领域中关于刚度与粘附强度相互矛盾的长期争议。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["力学机制[宽模量对比]: 剪切粘附力不能通过硬化单调增强","分析框架[异质弹性材料界面]: 提供适用于大刚度跨度剪切粘附的统一解析框架"]},{"i":41861,"as":"","scd":null,"kp":[]},{"i":41862,"as":"","scd":null,"kp":[]},{"i":41863,"as":"","scd":null,"kp":[]},{"i":41864,"as":"针对导电聚合物水凝胶在水环境中与疏水基材易分层的问题，研究人员开发了一种使用光活化表面活性剂（PAS）的原位稳定策略。PAS能降低界面表面能，并在紫外线激活下与可拉伸基材形成共价键。该分子设计为水凝胶生物电子器件提供了强黏附力和长期稳定性，解决了电气绝缘和化学保护难题。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["界面稳定剂[水凝胶生物电子学]: 光活化表面活性剂原位稳定策略","技术功效[疏水基材结合]: 解决水环境中润湿性差和界面脱层问题实现原位稳定"]},{"i":41865,"as":"研究人员通过在弹性聚合物基板上线性组装金纳米球（AuNSs），制备出具有方向依赖性等离子体手性光学响应的薄膜。当光传播方向从前向后反转时，该薄膜的圆二色性（CD）信号手性发生反转，且CD强度从-0.8显著增强至10。这种打破前后对称性的材料突破了传统CD在波长、强度和手性上的调制限制。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["光学材料[方向依赖性手性响应]: 具有高度不对称和动态可调的等离子体手性光学薄膜","光学特征[打破前后向对称性]: 表现出打破前向-后向对称性的方向依赖性圆二色性(CD)信号"]},{"i":41866,"as":"","scd":null,"kp":[]},{"i":41867,"as":"","scd":null,"kp":[]},{"i":41868,"as":"","scd":null,"kp":[]},{"i":41869,"as":"","scd":null,"kp":[]},{"i":41870,"as":"研究人员设计并合成了一种富含自由基的聚轮烷共价有机框架（VCB COF）。该框架通过葫芦[8]脲（CB[8]）大环机械联锁紫精自由基阳离子二聚体，形成双壁结构，显著增强了自由基稳定性、光物理性质和光响应性。电子顺磁共振分析表明，VCB在空气中暴露7天后仍保留超过72%的自由基信号。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["框架材料[有机自由基]: 机械联锁双壁共价有机框架(VCB COF)","超分子结构[光电子/传感应用]: 葫芦[8]脲(CB[8])大环稳定紫精自由基阳离子二聚体"]},{"i":41871,"as":"受超嗜极酶在近100°C高温下保持高活性的启发，研究人员提出一种“极端酶启发”的设计策略，构建了具有三聚体二聚体架构的六聚体铝卟啉催化剂。利用卟啉间的共价与非共价相互作用产生的几何约束，催化剂形成了两个三角锥形空腔，成功复制了酶的稳定空间排列和受限多点位催化微环境。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["催化活性维持温度[超嗜极酶启发设计]: 接近 100 °C","催化剂构型[环氧化物聚合]: 六聚体铝卟啉"]},{"i":41872,"as":"针对立体不稳定大环因快速立体平均难以进行手性解析的问题，研究发现基于柱[5]芳烃的大环在结晶时发生自发拆分形成聚集体。X射线衍射表明单晶包含单一手性构象体，结合圆二色性测量和密度泛函理论计算确定了其绝对构型。该分子的手性还体现在可区分的半面晶面上，可通过外部形态进行手动分拣。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["手性拆分行为[立体易变大环化合物结晶过程]: 自发拆分形成聚集体","构型手性特征[溶液态支柱[5]芳烃大环]: 动态外消旋"]},{"i":41873,"as":"","scd":null,"kp":[]},{"i":41874,"as":"","scd":null,"kp":[]},{"i":41875,"as":"为克服传统花青素光敏剂在光动力治疗中系间窜越差、缺氧敏感等缺陷，研究人员设计了首例具有杂化局部和电荷转移（HLCT）特性的不对称D-π-A-D'花青染料。该染料通过调节T2态三重态激子促进ISC并提升活性氧生成，结合电荷转移态与局部激发态，实现缺氧环境下的I型PDT和高量子产率的NIR-II成像引导治疗。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["分子结构[不对称花青染料]: D-π-A-D' 型","发光特性[不对称花青染料]: 具有杂化局部和电荷转移（HLCT）特性","系间窜越增强机制[T2态三线态激子精确调控]: 促进S1到T2态的跃迁"]},{"i":41876,"as":"研究人员利用极化MXene独特的离子-电子耦合特性，模拟静息电位下的跨膜离子传输，开发出全MXene固态离子电子学渗透能源（IOPS）。密度泛函理论和多尺度表征表明，其运行机制基于浓度梯度下的K+扩散动力学及两种极化MXene之间的费米能级差，解决了过度工程带来的离子-电子解耦和复杂结构问题。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":["材料核心机制[极化MXene模拟静息电位跨膜离子传输]: 离子-电子耦合特性"]},{"i":41877,"as":"","scd":null,"kp":[]},{"i":41878,"as":"","scd":null,"kp":[]},{"i":41879,"as":"","scd":null,"kp":[]},{"i":41880,"as":"","scd":null,"kp":[]},{"i":41881,"as":"针对传统无机光刻胶电子剂量敏感性低、溶解度对比度弱的问题，研究人员开发了一种分子络合物平台。该平台通过油胺配位，将普通金属卤化物（MXn，包含九种成分）直接转化为具有内禀电子束响应和溶液可加工性的光刻胶。该策略在无添加剂的无机光刻胶中实现了极低的剂量敏感性（0.81 mC cm-2）。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["材料转化能力[金属卤化物光刻平台]: 9种成分转化为本征电子敏感材料","电子剂量敏感性[传统无机及纳米晶体光刻胶]: 低"]},{"i":41882,"as":"研究开发了一种兼具高导热与电磁干扰屏蔽功能的多功能柔性相变复合材料。该材料通过将柔性固-固相变材料与多维导热网络相结合，克服了传统相变材料导热率低的缺陷。通过优化结构与组分比例，系统平衡了材料的热力学性能、柔性与热管理能力，为解决电子器件界面传热和高效温度调节提供有效方案。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":6.0},"kp":["材料设计策略[多功能柔性相变材料]: 结合本征柔性固-固PCM与多维导热网络","核心应用挑战[柔性相变材料]: 导热性本征上低"]},{"i":41883,"as":"研究提出利用硫修饰的NiCo基催化剂，在电压波动（1.4–2.3 V vs RHE）的电解槽中实现聚对苯二甲酸乙二醇酯(PET)废料中乙二醇(EG)的高效电氧化。在宽电位范围内，生成甲酸盐的法拉第效率保持在95%以上。该反应的高效性源于由硫氧化还原化学主导的结构重构工程，其提供的活性羟基氧化物位点促进了关键C-C键的断裂。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":8.0,"t":6.0},"kp":["电氧化电位范围[PET废弃乙二醇升级制备甲酸盐]: 1.4–2.3 V (vs. 参比电极)","核心稳定机制[高电压波动电解]: 动态材料重构主导"]},{"i":41884,"as":"研究报道了一种用于实时概率推理的单材料、单沟道分栅高斯镜像晶体管(SC-GMT)。该器件克服了传统反双极性晶体管依赖异质结导致的固有不对称性缺陷，通过分栅控制独立调节载流子浓度并反转电压偏置，成功生成对称且可调的高斯型转移曲线。这为概率计算模型在硬件层面的精确实施提供了基础。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["核心挑战[反双极性晶体管实现高斯分布函数]: 异质结引入载流子迁移率、界面质量和能带对齐的内在不对称性"]},{"i":41885,"as":"为解决太阳能界面蒸发中的热质不匹配瓶颈，研究提出结合高熵合金氧化物(HEAO)纳米粒子与双网络水凝胶的Janus界面能量质量中继架构。水凝胶作为焓调节剂预活化水分子并阻断热传导损失；顶部HEAO层加速剪切残余氢键，使O-H键拉伸至1.209 Å。该蒸发器最终实现了4.02 kg m^-2 h^-1的高蒸发速率。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["水预处理与隔热机制[双网络水凝胶]: 作为焓调节剂预活化体相水并阻断传导热损失","催化加速机制[高熵合金氧化物(HEAO)顶层]: 利用活性位点和氧空位作为熵加速器"]},{"i":41886,"as":"传统光电催化主要依赖无机金属材料，受限于周期性晶格结构对轨道和能级的约束。研究探讨了纯有机光电催化材料的新范式：基于π共轭框架，通过分子设计精确编程前沿轨道、能级分裂与电子离域。利用供体-受体(D-A)架构和电子不对称性，实现对激子结合、电荷分离及反应 flux 的分子尺度控制，为催化剂优化提供新路径。","scd":{"b":8.5,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":["活性优化维度[传统无机光电催化材料]: 晶体场调控、能带对齐和缺陷工程","核心限制[周期性晶格结构]: 内在地限制了轨道简并、能级重构以及对中间体吸附、电子转移和反应通量的分子级控制"]},{"i":41887,"as":"研究采用“反向生长”策略，通过亚纳米CoSe_x O_y-POM组件从钯纳米颗粒中捕获单原子，成功制备出原子级分散的亚稳态富电子钯簇。亚纳米尺度的电子离域诱导了整个结构的电子重排，使钯簇表现出更负的价态。该材料具备新颖的电子结构，能够有效响应肿瘤微环境并增强催化、声动力与免疫治疗效果。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":6.0},"kp":["金属分散度[肿瘤微环境响应催化剂]: 原子级分散","载体[亚稳态富电子钯簇反向生长]: 亚纳米CoSe_xO_y-POM组装体","生长策略[块体钯纳米粒子捕获形成原子级分散钯]: 动力学捕获反向生长"]},{"i":41888,"as":"研究提出一种具有瞬态几何结构的微创生物电子植入物平台。该植入物可植入皮下，通过优化几何结构解决了缩减尺寸与集成无线供电、数据交互及电化学监测空间之间的矛盾。其能够直接获取内部生物学信息，用于实时监测pH值、温度、心肺活动以及体内锂离子动态等重要生理和化学标记物。","scd":{"b":5.5,"i":3.0,"r":5.0,"d":4.0,"t":6.0},"kp":["[生物电子植入物(几何瞬态平台)]: 解决设备微型化以降低手术侵入性与留足空间集成无线电子器件的几何优化冲突"]},{"i":41889,"as":"受皮肤梯度模量结构的启发，研究开发了一种基于赫兹接触理论的梯度模量电致发光压力显示器。该人工触觉系统能将机械应力直接转化为空间分辨的光学信号。通过引入模量工程，该器件有效调控应力传输分布及其耦合的内部电场，从而激活智能触觉感知，解决机械刺激转化为精确电信号的机制问题。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":4.0,"t":6.0},"kp":["[应力传输(皮肤启发的人工触觉系统)]: 耦合应力传输以控制内部电场分布并实现智能功能集成"]},{"i":41890,"as":"研究引入一种基于翻转机制的可重构机械超表面。该设计利用双稳态翻转元件交替呈现不同电磁响应与视觉颜色的元原子，实现电磁波前操控与光学显示的同步。集成永久磁铁的翻转元件由微控制器驱动的磁控模块致动，通过短暂的电脉冲即可实现快速、非易失性的机械翻转，极大降低了功耗与制造复杂性。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":5.0,"t":6.0},"kp":["[机械可重构超表面(MetaScreen)]: 利用独特的翻转机制在具有不同电磁响应的超原子之间进行能量高效转换"]},{"i":41891,"as":"受生物多感觉协同机制启发，研究提出一种视觉-嗅觉双峰神经形态器件，用于克服人工嗅觉传感器在识别精度、体积和功耗之间的权衡限制。该器件无需依赖大规模传感器阵列，通过模拟生物双峰感知加权与增强过程，融合视觉提示与气体传感信息，大幅提升了微机器人、医疗设备等领域气体分类的准确性与紧凑性。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":6.0},"kp":["传感器阵列规模[提升气体识别精度的现有策略]: 高达 10^4 个元件"]},{"i":41892,"as":"研究分析了由相分离介导的降解型负反馈环路中的振荡现象。该最小化反馈环路在线性级联反应中，由末端产物酶解级联起始端的组分来驱动。结合平均场常微分方程与物理模型，揭示了生命非平衡态过程中相分离作用对分子振荡行为的决定性影响。","scd":{"b":7.5,"i":1.0,"r":5.0,"d":4.0,"t":7.0},"kp":["[降解介导的负反馈环路振荡(相分离)]: 级联反应终产物酶促降解初始组分产生振荡"]},{"i":41893,"as":"研究探讨了准晶体中的交变磁性。交变磁体结合了反铁磁体的共线零磁化自旋结构与铁磁体自旋劈裂能带的特征。这种独特的物理性质源于联合时间反演对称性的破缺。研究表明，这一新近发现的磁性相同样存在于非周期性的准晶体结构中。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":4.0,"t":7.0},"kp":["[交变磁性]: 共线的零磁化自旋结构与自旋劈裂能带共存"]},{"i":41894,"as":"交变磁性以对称性保护的动量依赖自旋劈裂和共线补偿磁矩为特征。此前该概念主要在周期性晶体中被探索，本研究首次将交变磁性的概念扩展至无周期的准晶体系统中，并在超空间射影结构下揭示了准晶体非常规交变磁性状态的存在与特征。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":4.0,"t":7.0},"kp":["[交变磁性(准晶体)]: 具有对称性保护、动量依赖的自旋劈裂和共线补偿磁矩的新奇磁相"]},{"i":41895,"as":"研究针对谷不平衡的菱面体四层石墨烯，揭示了其中的超导不稳定性。分析表明，在该材料系统中会形成有限动量的配对态，并产生超晶格超导体。这一发现丰富了二维范德华异质结材料在非常规超导领域的物理特性研究。","scd":{"b":9.0,"i":1.0,"r":6.0,"d":4.0,"t":7.0},"kp":["[谷不平衡菱面体石墨烯(超导不稳定性)]: 形成有限动量配对态和超晶格超导体"]},{"i":41896,"as":"研究探讨了掺杂引起的小极化子对5d²双钙钛矿(Ba2CaOsO6)低温多极序的影响。第一性原理计算表明，通过计算局域5d¹空穴极化子与5d²磁性离子之间的晶格交换相互作用，掺杂诱导的极化子能够直接切换并影响材料内部的八极序状态。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":6.0,"t":9.0},"kp":["极化子序转变[掺杂5d²双钙钛矿(Ba₂CaOsO₆)]: 掺杂诱导的极化子影响材料的低温度多极序"]},{"i":41897,"as":"研究揭示了拓扑绝缘体中存在一种不依赖背散射或退相干的隐藏耗散通道。有限频率的局部散粒噪声可作为近场辐射的源。这种隐藏的能量损失机制无法通过传统输运测量观察到，但可以通过近场显微镜技术在拓扑导体中直接探测到。","scd":{"b":8.5,"i":1.0,"r":8.0,"d":6.0,"t":9.0},"kp":["[有限频率局部散粒噪声作为近场辐射源]: 揭示了不依赖背散射或退相干的隐藏能量损失通道","[拓扑导体能量损耗检测]: 可通过近场显微技术而非传统输运测量进行探测"]},{"i":41898,"as":"","scd":null,"kp":[]},{"i":41899,"as":"","scd":null,"kp":[]},{"i":41900,"as":"研究提出了一种利用自由电子激光(FEL)驱动微聚束结合激光康普顿散射效应，产生高能光子脉冲串的新方案。该方案能够稳定可靠地生成处于阿秒与介秒(10^-21 s)尺度的高能γ射线脉冲，为超快时间分辨的核物理与量子电动力学实验提供了关键工具。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":8.0,"t":9.0},"kp":["高能光子脉冲区间[FEL驱动微聚簇与激光康普顿散射协同作用]: 阿秒与仄秒量级"]},{"i":41901,"as":"","scd":null,"kp":[]},{"i":41902,"as":"研究将半导体与磁性材料结合，实现类似晶体管的操作与非易失性，从而推动“存算一体”架构的发展。研究人员利用相关电输运测量与扫描氮-空位中心磁成像技术，阐明了范德华自旋晶体管的概念，并揭示了空间电荷限制的物理机制。","scd":{"b":8.5,"i":3.0,"r":8.0,"d":7.0,"t":9.0},"kp":["[范德华自旋晶体管架构]: 结合半导体与磁性材料，实现晶体管操作与非易失性存储（存内逻辑）","[空间电荷限制效应]: 阐明了相关自旋晶体管的工作机制"]},{"i":41903,"as":"信使RNA（mRNA）与蛋白质水平之间的关系是基因表达的核心。尽管学界已广泛观察到两者间存在强相关性，但其背后的演化驱动力尚不明确。这项研究探讨了由适应性演化驱动的mRNA与蛋白质水平之间的缩放定律，以解决利用mRNA丰度预测蛋白质丰度时的可靠性问题。","scd":{"b":6.0,"i":1.0,"r":7.0,"d":5.0,"t":9.0},"kp":["[mRNA与蛋白质水平相关性]: 进化选择（适应性）驱动构建了两者间的缩放规律"]},{"i":41904,"as":"研究利用少于10飞秒的泵浦-探测反射率测量技术与模型计算，在给体-受体型金属有机框架（MOF）中发现了光诱导隐藏态。实验表明，瞬态光谱在约30飞秒的时间尺度上形成了一个额外的吸收带。该发现揭示了键级波在驱动超快光诱导隐藏态形成中的关键作用。","scd":{"b":9.0,"i":1.0,"r":8.0,"d":7.0,"t":9.0},"kp":["泵浦探针反射率测量时间分辨率[金属有机框架隐藏态观测]: 亚10飞秒","[光诱导隐藏态形成机制]: 由键级波驱动","附加吸收带发展时间[光诱导隐藏态]: 约30飞秒"]},{"i":41905,"as":"研究人员在俘获离子和超导这两个量子计算平台上实现了可调谐量子神经网络的构建。通过在这些不同硬件平台上对量子神经网络进行基准测试，评估并验证了这类系统能否在实际运行中可靠地实现其理论性能，推动了量子机器学习技术的物理验证与发展。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":6.0,"t":9.0},"kp":["[量子神经网络硬件基准测试]: 在俘获离子和超导两种量子计算平台上实现并评估了可调谐系统"]},{"i":41906,"as":"本研究开发了一种结合极高柔软度与强韧性的高度缠结洗瓶刷弹性体。传统洗瓶刷聚合物虽能抑制缠结从而实现类似组织的柔软度，但其侧链的位阻效应会导致材料变脆。为此，研究人员利用短聚乙二醇侧链合成了分子量超300万克/摩尔、且在室温下保持无定形态的高分子量洗瓶刷聚合物。研究测得其缠结阈值约为240万克/摩尔，缠结模量约1.3 kPa，比传统线性聚合物低近1000倍。该成果成功克服了材料柔软度与韧性难以兼得的传统矛盾。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[洗瓶刷聚合物]: 具有密集接枝短侧链的长主链结构，能够抑制分子缠结","[无溶剂聚合物网络]: 实现了类似组织的超软特性"]},{"i":41907,"as":"研究确立了α-MoO3作为一种高折射率、低损耗的各向异性材料，有效弥合了中红外极化激元与短波长纳米光子学之间的差距。结合椭圆偏振光谱、第一性原理计算和近场光学显微技术，研究确定了其在250-1700纳米波段宽带的各向异性光学常数，并将其与中红外波段的声子模型结合至30微米。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["材料特性[α-MoO3纳米光子学]: 高折射率、低损耗的各向异性材料","[α-MoO3]: 成功弥合了中红外极化激元与短波长（紫外）纳米光子学之间的应用间隙"]},{"i":41908,"as":"分子基闪烁体具有高水氧稳定性、低成本和低毒性的优势，但激子利用率限制了其发光效率。本研究报道了首个基于热受激延迟磷光（TSDP）分子的超亮金配合物闪烁体Au(TFPP)3。该材料利用三重态到单重态的自旋允许反向内转换（RIC）机制，实现了优异的放射发光性能与温度惰性。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[分子基闪烁体材料瓶颈]: 表现出高水氧稳定性、低成本和低毒性，但受限于激子利用率和发光效率","[金配合物闪烁体]: 具有超亮、温度惰性以及热受激延迟磷光特性"]},{"i":41909,"as":"生物活性分子可自组装形成具有压电响应的非中心对称超分子材料。研究系统调查了基于生物活性β-内酰胺类药物的超分子组装体的压电特性，并通过X射线衍射分析揭示了不同药物组装体具有多样化的有序堆积结构。该发现阐明了压电性与抗菌活性的协同机制，为多功能压电材料在健康监测和伤口愈合中的应用提供设计依据。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[压电生物活性药物超分子组件]: 首次系统研究了抗生素分子组装体的非中心对称结构及其压电响应","[多功能压电材料设计]: 阐明了生物活性分子组装体的结构-压电关系，可用于健康监测和伤口愈合"]},{"i":41910,"as":"光响应配位聚合物能将分子级运动转化为宏观机械形变，但存在脆性大和加工性差的问题。研究提出一种分层复合策略，将能够发生拓扑化学[2+2]环加成反应的一维锌配位聚合物嵌入聚乙烯醇基体中，并涂覆聚己内酯，制备出机械强度高、可扩展且耐水的光机械薄膜。该复合材料表现出波长选择性激活和膨胀可编程变形，致动保真度超过98%，力学强度接近承重聚合物系统。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":4.0},"kp":["光响应配位聚合物[宏观机械运动控制]: 精确的分子到宏观控制但受限于脆性和加工性","复合材料结构[拓扑化学[2+2]环加成反应的1D Zn(II)配位聚合物嵌入聚乙烯醇基质并涂覆聚己内酯]: 机械稳健、可扩展且水稳定"]},{"i":41911,"as":"受微囊藻的主动浮力调节机制启发，研究提出了一种可漂浮的集成变形水凝胶（FISS）。该材料兼具固体般的坚韧性与液体般的适应性。原位生成的无定形碳酸镁纳米颗粒提供了动态交联点，氨基功能化空心微球的引入则作为可调浮力单元和次级交联中心。这种微结构工程使水凝胶具备热响应性，可用作先进的水上漂浮载体。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["水凝胶载体[微囊藻主动浮力调节启发]: 固体般稳健性与液体般适应性相结合"]},{"i":41912,"as":"硫酸铁钠（Alluaudite型）是钠离子电池中极具潜力的低成本、高电压（约3.8V）正极材料。然而，其较差的内在框架稳定性导致Fe-Fe库仑排斥引起的反位缺陷、缓慢的Na+扩散以及水分诱发的表面水化问题。研究开发了一种阳离子取代策略，同时调节Na2+2x材料的体相和表面框架稳定性，以推动其实际应用。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":4.0},"kp":["氧化还原电位[硫酸根强诱导效应提升Fe2+/Fe3+氧化还原电对]: ~3.8 V","阴极材料[钠离子电池]: 低成本、高压的alluaudite型硫酸铁钠","失效机制[内在框架稳定性差]: 导致Fe-Fe库仑排斥"]},{"i":41913,"as":"研究提出了一种利用氧化膦吲哚（PIO）支架上的构型异构体作为编码生物选择性的决定性变量的可编程分子策略。在特定几何位置的取代生成了具有独特构象偏好、水相自组装行为和表面静电分布的异构对。其中一种异构体能够实现对癌细胞的选择性标记，优于正常哺乳动物细胞，适用于靶向光动力治疗。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["生物选择性编码[氧化膦吲哚(PIO)骨架上的构型异构]: 在几何定义位置进行战略取代以生成异构体对"]},{"i":41914,"as":"单层过渡金属二硫化物（TMDs）具有实现超低阈值纳米激光器的潜力，但常规光学谐振腔难以同时实现超小模式体积和超高品质因子，且介电界面会抑制激子发射。研究利用扭曲工程的光子晶体腔中的空气模式克服了这些局限性，成功在室温下实现了具有超低阈值的连续波WS2纳米激光器。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":4.0},"kp":["运行温度[WS2纳米激光器光子晶体腔]: 室温","激光器特征[超低阈值连续波]: 具有无悬键表面和强激子效应的单层过渡金属二硫化物"]},{"i":41915,"as":"基于金属-配体配位键的高可逆性和高度可调性，研究人员证明了配位键在构建各类动态聚合物中的有效性，包括自修复、可回收、形状记忆和自适应材料。在功能性金属离子或配体的辅助下，这类基于配位键的动态聚合物可表现出发光、磁性、催化、导电和介电等多种功能特性，在智能响应和可持续材料领域展现出广泛应用前景。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":3.0,"t":3.0},"kp":["动态聚合物构建[金属-配体配位键]: 具有可逆性和高度可调性，适用于自修复、可回收、形状记忆、响应和自适应材料"]},{"i":41916,"as":"该研究开发了一种用于长期和个性化治疗管理的化学感应导管。长期静脉导管置入（如化疗或肠外营养）易引发代谢紊乱、血液感染及肝肾损伤，而传统临床监测存在明显滞后。这种新型导管集成了肌酐、牛磺胆酸、胆红素和牛磺酸等多种分析物传感器，可实现对并发症的实时原位监测。通过采用金属凝胶材料与双网络分子印迹聚合物技术，该导管在经历100万次弯曲变形后仍能保持信号完整，并在植入3个月后维持稳定的体内监测性能，有效克服了现有设备在体内长期稳定性方面的不足。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["临床监测[长期静脉导管插入术]: 临床监测方法存在明显延迟，且实时血液监测装置无法确保体内长期稳定性","导管[化学感应导管]: 集成化学传感功能"]},{"i":41917,"as":"研究报道了一种锚定在缺氧CeO2纳米棒上的协同镍-钴双单原子催化剂，用于高效稳定的光热甲烷干重整（DRM）反应。在12.17 W cm−2的光照强度下，优化的Ni8Co4/CeO2催化剂表现出优异的性能，氢气和一氧化碳的生成速率分别高达3383.01和4703.36 mmol g⁻¹。该技术为太阳能驱动温室气体转化为合成气提供了抗积碳的高效途径。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["光功率密度[甲烷光热干重整(DRM)反应条件]: 12.17 W cm-2","催化剂[DRM抗结焦光热催化]: 锚定在缺氧CeO2纳米棒上的协同Ni-Co双单原子催化剂"]},{"i":41918,"as":"研究通过石墨/氮化硼范德华异质结构的结构转变，直接合成出了高质量的六方金刚石/纤锌矿氮化硼（HD/wBN）共价异质结构。金刚石和氮化硼同属等电子体，能够形成立方和纤锌矿多形体。该研究成功克服了合成亚稳态HD/wBN共价异质结构及澄清其界面化学键合的重大挑战，实现了不同组分间的有效整合。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["异质结构[六方金刚石/纤锌矿氮化硼(HD/w-BN)]: 通过界面化学键合补偿单一组分缺点并实现奇异特性","合成挑战[亚稳态HD/w-BN共价异质结构]: 极具挑战性"]},{"i":41919,"as":"阴离子交换膜水电解（AEMWE）是连接实验室研究与大规模制氢的关键技术，但其商业化受到跨尺度失效机制的限制，包括催化剂溶解、膜电极三相界面退化、双极板腐蚀和电堆组装不均。本文系统研究了AEM电解槽从原子到系统级别的失效行为，并提出了结合创新膜电极架构和仿生流场设计的跨尺度协同设计策略，以加速其工业化应用。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":5.0,"t":5.0},"kp":["商业化制约[阴离子交换膜电解槽(AEMWE)规模化制氢]: 受限于从原子到整个系统的多尺度失效机制，包括催化剂溶解与重构、膜电极组件三相界面降解、双极板腐蚀和气体/液体传输不均"]},{"i":41920,"as":"研究在非极性a面GaN上建立了晶体学极性与各向异性光响应之间的直接联系，实现了本征偏振敏感的紫外光电探测。晶体场引起的价带分裂使得重空穴带和晶体场分裂带向导带底跃迁时具有截然不同的跃迁偶极矩，从而实现了对垂直或平行于c轴偏振光的选择性吸收。利用纤锌矿氮化物的非极性面，成功克服了传统极性面各向同性的限制。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["偏振敏感紫外检测[非极性a面GaN]: 基于晶体极性与各向异性光响应的直接关联实现本征偏振敏感探测"]},{"i":41921,"as":"锂金属电池在高压和贫液条件下的性能衰减严重制约其实用化。研究提出了一种溶剂锚定电解质（SAE）策略，通过引入刚性阳离子（F-TEDA+）作为分子锚定添加剂，构建了富阴离子的溶剂化结构。该结构促使生成富含无机物的固体电解质界面（SEI），从而确保了电池在高压下的稳定运行。该技术成功使能量密度达600 Wh Kg−1的锂金属软包电池实现稳定循环。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":8.0,"t":5.0},"kp":["能量密度[溶剂锚定电解质锂金属软包电池]: 600 Wh/kg","稳定运行机制[高压贫液条件]: 构建富阴离子溶剂化结构生成富无机物固态电解质界面(SEI)"]},{"i":41922,"as":"本文探讨了基于拓扑绝缘体（TI）与磁体构成的异质结构中的量子反常霍尔效应。该效应可在零外加磁场下实现无耗散边缘态，但传统磁性掺杂或异质结构方法通常仅在极低温度（数开尔文或低于100毫开尔文）下才能保持霍尔量子化，这严重限制了其实际应用与发展。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":5.0,"t":5.0},"kp":["量子反常霍尔态[机械组装拓扑绝缘体/磁体异质结构]: 磁掺杂拓扑绝缘体实现的极低温限制状态及零磁场下的无耗散边缘态"]},{"i":41923,"as":"研究提出了一种热独立界面重构策略，用于在不依赖热激活的条件下形成纯相的n=1二维钙钛矿。该方法避免了传统热退火引发的底层三维钙钛矿降解问题，抑制了高n相的形成，克服了二维钙钛矿面外导电性低导致的稳定性与电荷传输效率之间的权衡限制。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["界面重构[n=1纯相二维钙钛矿]: 热独立界面重构打破面外导电性与稳定性之间的权衡"]},{"i":41924,"as":"文章全面综述了面向高级具身智能的多模态人工感官融合范式。多感官融合构建了仿生传感架构，能够并行采集和处理多源信息，有效增强了智能体在复杂环境下的信息感知能力，并确保了更高决策可靠性，是连接数字世界与物理现实的基石。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":4.0,"t":4.0},"kp":["感知架构[具身智能多模态人工感官融合]: 能够并行获取和处理多源信息的仿生传感框架"]},{"i":41925,"as":"研究探讨了磁剪切对W7-X和H-J仿星器中动力气球模式（KBMs）和电磁湍流的影响。模拟发现增大磁剪切和减弱不良曲率能稳定亚阈值KBMs。W7-X中较低磁剪切配置因产生更强带状流而实现了更低的热传输。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["等离子体稳定性[W7-X和H-J仿星器]: 增强磁剪切和减弱不良曲率可稳定阈值下的动力气球模式"]},{"i":41926,"as":"分析企业成长对碳强度的影响，探讨环境税收政策与绿色技术创新生态系统的作用。","scd":null,"kp":["评估要素[企业成长对碳强度的影响]: 环境税收政策与绿色技术创新生态系统"]},{"i":41927,"as":"研究开发了一种利用3,4,9,10-苝四甲酸（PTCA）在二甲亚砜中有限溶解性的直接激光写入（DLW）工艺，成功制备出带隙较窄的聚萘二萘（PPN）及碳薄膜（厚度<1微米）。优化条件下制备的DLW薄膜电导率达120 S·cm-1，塞贝克系数为8.5 μV·K-1，功率因子为0.96 μW·m-1·K-2。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["薄膜厚度[直接激光写入加工产物]: <1 μm","加工方法[窄带隙导电聚合物聚萘和碳薄膜]: 利用3,4,9,10-苝四甲酸在二甲亚砜中的有限溶解度进行CO2激光直写"]},{"i":41928,"as":"研究在由贵金属纳米球（20-200纳米）与平面金属薄膜通过结构对称分子桥接构建的隧道结中，观察到了强烈的电致发光和电流整流现象，整流比高达102-103。整流行为高度依赖于电极几何形状和连接分子化学特性。替换为纳米立方体或增大纳米球直径会显著抑制整流效应。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["整流比[镜上等离激元纳米球隧道结]: 10^2-10^3","纳米球尺寸[贵金属(银或金)]: 20-200 nm"]},{"i":41929,"as":"研究开发了一种基于铜的多孔金属氨基酸纳米酶（MAzyme），用于负载CD47-SIRPα信号通路抑制剂并包裹巨噬细胞膜，构建了仿生纳米平台（MMAzyme-S）。该平台具有媲美天然超氧化物歧化酶的抗氧化活性，能通过消除活性氧有效缓解炎症，并阻断CD47以促进胞吞作用，实现动脉粥样硬化的多途径治疗。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["纳米平台[多孔金属氨基酸纳米酶]: 铜基多孔纳米酶负载CD47-SIRPα抑制剂并包覆巨噬细胞膜","治疗机制[动脉粥样硬化]: 抗氧化与促进胞吞作用的多途径联合治疗"]},{"i":41930,"as":"研究介绍了一种紧凑型完全集成的智能环，能够通过被动渗透提取的汗液，实时连续监测葡萄糖、酮、乳酸等多种生化标志物。该设备由高容量柔性Zn-AgO电池供电，支持约12小时连续监测，且个性化校准稳定性可保持约2个月。","scd":{"b":8.0,"i":4.0,"r":8.0,"d":8.0,"t":6.0},"kp":["监测指标[完全集成智能环的汗液分析]: 葡萄糖、酮、抗坏血酸、尿酸、乳酸和酒精","汗液提取方式[智能环被动连续监测]: 渗透提取"]},{"i":41931,"as":"针对老年组织再生难题，研究开发了名为“纳米中心体”的空间分区融合纳米囊泡系统（SMNV）。该系统由装载S-腺苷甲硫氨酸（SAM）的融合脂质体包裹间充质干细胞纳米囊泡组成。SMNV通过膜融合实现胞质递送，在巨噬细胞中减弱炎症激活并促进胞吞和代谢重编程，有效修复老年雌性大鼠组织。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[组织再生表观遗传重编程]: S-腺苷甲硫氨酸(SAM)显著耗竭","[生物正交纳米中心体系统]: 空间区室化融合型纳米囊泡(SMNV)，由载有SAM的融合脂质体包封间充质干细胞构成"]},{"i":41932,"as":"研究展示了一种使用拓扑调制器的晶圆级非易失性光子计算芯片。结合铁电薄膜（PZT）的拓扑光子约束特性，该芯片实现了1000倍加速重构、近零静态功耗运行，计算密度达266 TOPS/mm²。16通道波分复用芯片实现了1.92 TOPS的吞吐量及高精度的数字识别率。","scd":{"b":8.5,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["[光子计算芯片]: 晶圆级非易失性且使用拓扑调制器","[电光响应频率][PZT薄膜拓扑光子限制]: GHz级别","[材料组件]: 铁电相锆钛酸铅(PZT)薄膜"]},{"i":41933,"as":"研究提出原位界面聚酯化辅助键合策略，用于构建富MOF自支撑膜。在UiO-66体系中，三乙醇胺（TEOA）在热处理下诱导局部界面反应，在MOF接触处生成锚定聚酯物质，增强颗粒键合并抑制非选择性界面缺陷。所得膜UiO-66负载量达92.7 wt%，展现出优异的CO2渗透选择性。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[界面成键策略]: 原位界面聚酯化辅助成键","[自支撑富MOF膜材料体系]: UiO-66系统且使用三乙醇胺(TEOA)"]},{"i":41934,"as":"研究展示了一种高精度纳米级磁性位制造与控制概念验证。利用像差校正的原子级电子探针，通过电子束诱导相变直接在反铁磁岩盐间隔层中雕刻出亚铁磁NiFe2O4磁性位。原位电子磁圆二向色性（EMCD）测试证实，横向宽度约4纳米的单畴结构具有可检测的热力学稳定的磁信号。","scd":{"b":9.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[加工尺度][磁性位]: 纳米级紧密间距且具有原子级尖锐边界","[可控制造工艺]: 像差校正的原子级电子探针直接通过电子束诱导雕刻"]},{"i":41935,"as":"研究利用表面工程化的微生物网络，通过自下而上的设计构建了可编程生命力传感器。通过基因重写细菌展示表面锚定亲和对，介导其组装成宏观尺度的微生物网络作为导电与传感层，并封装在弹性管中。该活体传感器克服了传统传感器易碎和拉伸敏感性等局限，具有可调节的传感能力。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[传感器类型]: 可编程生命力传感器","[制造工艺]: 自下而上设计的表面工程微生物网络"]},{"i":41936,"as":"研究引入了误差缓解的纠缠增强学习方法，用于表征大规模量子过程。通过实验和理论分析证实，利用量子存储和纠缠操作可将非交换测量转化为对交换可观测量的测量，从而指数级降低采样复杂度。即使在存在噪声的现实设备中，该策略依然展现出显著的采样优势。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[参数复杂度][一般量子过程表征]: 需呈指数级增长的测量参数样本复杂度","[纠缠增强学习策略][保利信道]: 利用量子存储器和纠缠操作将任务转换为对易可观测量的测量以降低复杂度"]},{"i":41937,"as":"研究在三维大孔氮掺杂碳中混合了电子耦合的钴单原子与CoPd合金（CoPd/Co@3D NC），构建了高性能肼辅助锌空气电池。钴单原子与CoPd合金之间的电子耦合相互调节了电子结构，削弱了钴单原子上的氧吸附并增强了CoPd合金上的肼吸附，成功用热力学更有利的肼氧化反应取代了缓慢的析氧反应。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[催化机制]: 将析氧反应替换为热力学上更有利的N2H4(肼)氧化反应","[催化剂结构]: 电子耦合的Co单原子与CoPd合金杂化于三维大孔N掺杂碳(3D NC)中"]},{"i":41938,"as":"基于MAVEN任务的原位探测数据，研究表明火星小尺度地壳磁场相关的极光过程，可理解为一种微型磁通量和等离子体循环的邓吉循环（Dungey cycle）。不同于地球依赖全球性偶极子场的邓吉循环，火星上的该循环在磁场强度低约100倍、空间尺度小约20倍的条件下运作。","scd":{"b":6.0,"i":5.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[火星极光等离子体动力学]: 由小尺度地壳磁场驱动的磁通与等离子体循环微型邓吉循环"]},{"i":41939,"as":"研究利用扫描隧道显微镜，在范德华半金属CeTe3中揭示了三种竞争性多q反铁磁电荷有序态。这些状态具有特定的传播矢量，并受约1.5特斯拉的面内磁场调控。准粒子干涉成像确定了三个不同的嵌套通道和费米面重构，谱学揭示了伴随着这些状态出现的广泛电子结构重构。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[电子相特征][CeTe3范德华半金属]: 相互交织的多重挫败产生的三种竞争条纹型和棋盘型多q反铁磁电荷有序态","[传播向量][磁场可调谐状态]: (0.33, 0) 和 (0, 0.08)"]},{"i":41940,"as":"","scd":null,"kp":[]},{"i":41941,"as":"研究在NaNbO3基钙钛体中引入高熵组成设计，创造出类似纳米纤维的极性配置，实现了弛豫铁电体的超高储能性能。该方法在A位和B位引入具有显著铁电活性和离子半径差异的多种阳离子，同时破坏了长程铁电和反铁电畸变序，形成了具有纳米级极性纳米纤维结构的域。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[储能策略]: 高熵组分设计构建类纳米纤维极性配置","[材料体系]: 基于NaNbO3的钙钛矿型弛豫铁电体"]},{"i":41942,"as":"研究开发了一种由介孔二氧化硅壳层和氮化硼晶核组成的各向异性核壳陶瓷纳米纤维膜，用于高能激光防护。通过双通道静电纺丝技术制备的该结构在1064纳米处实现了约100%的高反射率，并具备各向异性热传导功能，能够沿膜面快速散热，有效应对高能激光照射环境。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["纳米纤维膜结构[各向异性核壳陶瓷]: 介孔二氧化硅壳层和结晶氮化硼核心","应用目标[极端条件下的高能激光防护]: 兼顾光学反射率和定向热管理"]},{"i":41943,"as":"","scd":null,"kp":[]},{"i":41944,"as":"","scd":null,"kp":[]},{"i":41945,"as":"","scd":null,"kp":[]},{"i":41946,"as":"研究利用超导共面波导和微波测量技术，表征了二维范德华超导体少层二硒化铌（NbSe2）的动态电感。结果表明，该材料的动态电感与层数成反比，在单层极限下达1.2 nH/□。此外，测得的动态电感表现出从清洁极限到肮脏极限行为的厚度依赖性转变，在超薄区域中肮脏极限贡献显著增加。这些结果证明了层数减少对超导体物理特性的直接影响。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["材料体系[范德华超导体]: 原子层级薄二硒化铌(NbSe2)","物理特性[微波测量技术]: 动感随厚度呈反比缩放"]},{"i":41947,"as":"将液态相变材料嵌入纤维以实现被动温度控制面临微尺度液核不稳定和无法连续生产的挑战。研究通过在热拉丝和冷拉丝过程中采用尺寸减小和速度匹配策略，成功制备出长达35米、厚度为200微米的均匀核壳结构相变纤维（PCFs）。这种可扩展的相变纤维展现出创纪录的热机械性能，为无主动冷却的高效服装热调节提供了有效解决方案。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["温度控制机制[相变纤维]: 在固液相变过程中被动存储和释放热量"]},{"i":41948,"as":"有限温度下的临界现象研究常受限于相变附近的计算瓶颈。研究引入了一种结合实时温度推断和精细能量尺度控制的采样协议，以克服量子退火器中的噪声、硬件限制和热涨落问题。借助精心设计的嵌入策略，研究人员在环面晶格上精确捕捉了经典二维伊辛铁磁体的有限温度临界行为，证明了量子退火技术在精确解析有限温度临界现象方面的有效性。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["计算技术[有限温度临界相变研究]: 克服噪声和热涨落，利用量子退火精确解析临界现象"]},{"i":41949,"as":"针对高能量密度锂离子电池高负载电极的结构完整性问题，研究提出了一种由氨纶和聚丙烯酸交联网络组成的双效混合聚合物湿法粘合剂。氨纶提供高弹性并对富镍正极具有强亲和力，聚丙烯酸则会在电极表面形成聚丙烯酸锂以增强界面锂离子传输。这种双重作用确保了电极的均匀电荷转移和结构稳定，成功开发出能量密度达450 Wh/kg的锂离子电池。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":8.0,"t":5.0},"kp":["能量密度[湿法加工高面积容量电极锂离子电池]: 450 Wh/kg","粘合剂材料[高负载富镍正极材料]: 氨纶-聚丙烯酸混合聚合物"]},{"i":41950,"as":"基于胶体半导体纳米晶的发光二极管（LED）性能高度依赖界面层的能级匹配。研究调查了多层全溶液加工LED结构中不同空穴传输（HT）和电子注入（EI）聚合物的协同作用，该结构采用CdSe/CdZnS纳米片作为深红光发射器。研究评估了三种具有不同空穴迁移率的商业HT聚合物，证实了合理设计溶液加工的聚合物中间层能够有效控制阳极和阴极的界面特性，实现高效电荷注入和平衡的载流子传输。","scd":{"b":5.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["界面工程[纳米晶体LED]: 采用溶液加工的半导体聚合物中间层调节阳极和阴极界面能级排列"]},{"i":41951,"as":"研究受植物蒸腾作用启发，通过定向冷冻干燥技术制备了一种具有垂直通道结构的仿生碳纳米管（CNT）/壳聚糖（CS）气凝胶。该气凝胶耦合了光热转换和光催化功能，在提供出色的热约束以提升光热效率的同时，还能增强催化降解能力。该系统能有效应对高盐度和有机污染物共存的复杂水环境，实现了协同太阳能驱动界面水蒸发与光催化降解。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["气凝胶结构[仿生植物气凝胶]: 具有垂直排列通道的碳气凝胶","协同功能[太阳能驱动界面蒸发与光催化降解]: 同时产出洁净水并去除有机污染物"]},{"i":41952,"as":"为提升聚合物炸药（PBX）的安全性和可靠性，研究开发了一种结合水悬浮和泥浆法的多级复合策略。在仅添加0.5 wt%碳纳米管（CNTs）的条件下，成功构建了分层的热/机械网络。测试表明，在0.5 wt%的极低CNT负载下，材料的热导率提升了52.09%，达到0.6993 W·m-1·K-1，同时巴西劈裂强度激增181.6%。理论建模与COMSOL仿真进一步证实了该策略的有效性。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":8.0,"t":5.0},"kp":["碳纳米管负载量[聚合物炸药超低添加量]: 0.5 wt%","复合策略[增强热机械性能]: 结合水悬浮和浆料法构建分层热/机械网络"]},{"i":41953,"as":"为解决传统聚丙烯（PP）外科网片在治疗盆腔器官脱垂时存在的机械不匹配和生物惰性导致的应力集中与慢性炎症，研究设计了一种多功能复合网片。该网片以临床级PP为机械支撑基底，结合了3D打印的季铵化壳聚糖（QCS）修饰的聚己内酯（PCL）仿生网络，并通过静电吸附载入人脐带间充质干细胞外泌体。PP/PCL/QCS复合网片有效减轻了应力集中，并显著促进了胶原蛋白再生。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["网片结构[修复盆腔器官脱垂3D复合网片]: 临床级聚丙烯基底结合载有外泌体的结构","功能特性[减轻应力集中与促进组织再生]: 减缓应力集中并促进胶原蛋白再生"]},{"i":41954,"as":"针对气相表面增强拉曼光谱（SERS）检测锂离子电池电解质泄漏的难题，研究开发了一种基于周期性银纳米颗粒多聚体阵列和单层石墨烯覆盖层的杂化SERS平台。该基底采用毛细辅助粒子组装（CAPA）和聚乙烯醇（PVA）辅助热压转移工艺制备，实现了有序AgNP阵列向玻璃的转移和空间选择性石墨烯集成。该平台解决了气态分析物在等离子体热点停留时间短的问题，有效实现了气相检测。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["SERS平台[气相检测锂离子电池电解质]: 周期性银纳米颗粒多聚体阵列集成单层石墨烯","检测目标[气相表面增强拉曼光谱]: 锂离子电池电解质蒸汽泄漏成分"]},{"i":41955,"as":"核酸疫苗在临床转化中受制于复杂的生物屏障，因此需要高效的递送系统。由于具有可调的理化性质、多样的结构工程和良好的生物相容性，生物医学聚合物已成为核酸纳米载体的核心。文章综述了核酸疫苗聚合物递送载体的合理设计策略，系统阐述了包括界面屏蔽、靶向配体修饰等在内的功能化聚合物工程如何克服生理屏障，确保递送的有效性。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":4.0,"t":3.0},"kp":["载体材料优势[核酸疫苗聚合物递送系统]: 可调物理化学性质、灵活结构工程、强生物相容性"]},{"i":41956,"as":"受细胞外基质结构启发，研究开发了一种基于聚偏氟乙烯（PVDF）的三元介电储能薄膜。该薄膜在含氟甲基丙烯酸酯交联网络中引入了羟丙基-β-环糊精（HP-β-CD）。交联网络作为绝缘骨架，而HP-β-CD的丰富羟基与PVDF链形成氢键，增强了界面粘附并调节局部链构象。在外加电场下，HP-β-CD的极性基团产生取向极化，使介电常数提升至9.7，显著改善了薄膜的介电与储能性能。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["介电储能薄膜[受细胞外基质启发的三元复合材料]: 基于PVDF并引入羟丙基-β-环糊精和含氟甲基丙烯酸酯交联网络"]},{"i":41957,"as":"研究提出了一种用于可见光光聚合的可持续双组分引发策略，将生物衍生肟酯与天然或仿生光敏剂结合用于405纳米光固化。实验表明，合成的肟酯（OXE1）与甲萘醌（MD，维生素K3）组合表现最佳，实现了丙烯酸酯类树脂（TMPTA）的快速光聚合，且配方均匀、着色度低、储存稳定性好。电化学分析证实，该高效引发性能得益于光敏剂与肟酯之间的三重态-三重态能量转移机制。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["光固化波长[生物基光敏剂与肟酯组合]: 405 nm"]},{"i":41958,"as":"研究通过手性α-甲基苄胺与甲脒盐在180°C下的无溶剂热缩合，开发了本征手性且可溶于有机溶剂的碳纳米胶体。与传统的表面功能化碳点不同，该纳米颗粒（尺寸5-10 nm）形成了无定形碳氮氧网络，其中共价嵌入了手性脒生色团。该材料在极性和非极性溶剂中均具有优异的分散性，展现出双模光学响应，可应用于非极性对映选择性传感及卤化铅钙钛矿的表面钝化。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["合成温度[手性有机可溶性碳纳米胶体]: 180 °C","合成工艺[手性有机可溶性碳纳米胶体]: 手性α-甲基苄胺与甲脒盐的无溶剂热缩合"]},{"i":41959,"as":"研究开发了一种基于镓基液态金属（Ga-LM）的可回收仿生柔性传感器，用于实时心电信号监测。该传感器以静电纺丝纳米纤维膜为柔性基底，通过机械剪切和超声制备导电墨水，并打印成仿生蛛网结构。该传感器具备高信噪比、低界面阻抗和保形性。实验表明，传感器在700次拉伸循环后相对电阻变化低于50%，展现出极佳的拉伸耐用性、高导电性以及可回收利用的特性。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["柔性电极材料[可拉伸心电传感器]: 镓基液态金属","基底材料[柔性传感器]: 静电纺丝纳米纤维膜","核心特性[镓基液态金属]: 高电导率、优异变形性、可回收性、生物相容性","传感性能要求[可拉伸心电传感器]: 高信噪比、低界面阻抗、适形性"]},{"i":41960,"as":"研究采用级联聚合策略，在海绵状PNIPAM水凝胶中依次引入了电致传感和机械增强聚合物网络相，制备出具备快速响应、高强度和自感知能力的多相水凝胶。该水凝胶致动器在承受远超自身质量的外部载荷下仍能执行快速驱动任务，并可产生数字逻辑信号。该研究解决了传统驱动水凝胶在致动性能与机械强度之间的权衡问题，适用于承载驱动和逻辑人机交互。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["聚合策略[高强度自感知水凝胶]: 级联聚合策略","功能相[水凝胶网络]: 电学传感聚合物网络相、机械增强聚合物网络相","[驱动水凝胶]: 解决驱动力与机械强度之间的权衡问题"]},{"i":41961,"as":"通过结合密度泛函理论（DFT）和实验，研究建立了金属-聚合物杂化物界面电子 donor-acceptor 统一框架。研究表明，界面金属氧化物与聚合物羧基通过金属空位3p与氧孤对电子2p轨道间的p-p σ杂化，促进了μ₂-桥接配位。此外，引入表面氧空位增强了金属位点的电子接受能力，使配位界面能够抵抗热力学波动，从而将材料的拉伸剪切强度提高了400%以上。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["界面化学键合机制[金属-聚合物杂化物]: 金属氧化物与聚合物羧基间通过p-p σ杂化驱动的μ₂-桥接配位"]},{"i":41962,"as":"研究开发了一种基于胶体自组装、利用双空间可见光信号协同认证机制的高安全性物理不可克隆功能（PUF）系统。该系统通过实空间布拉格反射和倒易空间衍射信号的结合，对由二维空间坐标和晶体取向定义的三维虚拟空间内的多晶单层形貌进行高效认证。多晶形态提供的双重空间验证解决了传统随机无序结构认证耗时且昂贵的问题，实现了基于硬件的安全信息加密。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["认证机制[物理不可克隆功能]: 双空间可见光信号协同认证","图案生成机制[物理不可克隆功能]: 非确定性自组装","结构特征[自组装PUF系统]: 多晶单层形貌"]},{"i":41963,"as":"随机动力学常用于高维分布采样，但极易陷入亚稳态。研究证实，对于多变量离散分布，可通过亚稳态样本恢复真实的平稳模型。其核心在于满足强亚稳态条件的分布，其单变量条件概率平均极度接近真实平稳分布，即便两者在全局度量（如KL散度）上差异显著也是如此。基于这一发现，能够有效从受困的亚稳态样本中提取并还原出真实的平稳分布模型。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[多变量离散分布]: 真实平稳模型可从亚稳态样本中恢复"]},{"i":41964,"as":"通过在非晶固体中掺杂进行逃逸-翻滚或主动布朗动力学的自驱动粒子，可以动态控制玻璃的剪切带形成与脆性断裂。模拟表明，剪切带的演化受三个时间尺度的竞争控制：外加剪切时间、活性保持时间和剪切带跨越系统的固有时间。在低保持时间下，主动掺杂能逐步改变系统的力学响应，实现无定形固体屈服行为和流变特性的可调节性。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["屈服行为调控[非晶态玻璃固体]: 通过掺杂自推进活性粒子可动态控制剪切带的形成与扩展"]},{"i":41965,"as":"利用150-200纳米波长范围内的亚4飞秒超短脉冲，结合时间分辨光电子能谱与量子动力学计算，研究了最简单的孤立碳-碳双键发色团（乙烯）及其全氘代同位素化合物的超快动力学。结果揭示了1B3g(σπ*)态在其中的关键作用，它通过扭转等运动产生强烈耦合。该发现明确了碳-碳双键在光异构化等基础光化学过程中的核心激发态动力学机制。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["[乙烯碳-碳双键基本光动力学]: 几飞秒光电子能谱揭示了其超快激发态动力学"]},{"i":41966,"as":"环境湿度敏感导致的薄膜结晶受损和器件不稳定是钙钛矿太阳能电池商业化的主要障碍。引入二苯基乙烯基膦（DPVP）作为路易斯碱添加剂，可在20-40%相对湿度的环境空气制造中抑制水分诱导的缺陷形成并稳定结晶过程。该技术显著提高了薄膜均匀性并降低了缺陷密度，使小面积器件和12平方厘米刀片涂层微型模块的光电转换效率分别达到24.2%和20.5%。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":7.0,"t":6.0},"kp":["Lewis碱添加剂[钙钛矿太阳能电池]: 二苯基乙烯基膦(DPVP)","工艺湿度鲁棒性[环境空气制造]: 20-40%"]},{"i":41967,"as":"手性π-两亲物结合了两亲性分子的亲水-疏水双重性、π共轭体系的功能性以及手性特征，成为超分子化学的重要构建基块。这类分子通常由疏水的π延伸发色团和亲水的手性单元通过化学键共价连接而成。手性、功能性π体系与两亲性的多维度协同集成，极大扩展了材料的设计空间，赋予分层自组装结构以特定的纳米形貌和新兴功能特性。","scd":{"b":7.0,"i":1.0,"r":6.0,"d":4.0,"t":6.0},"kp":["分子基元[超分子组装]: 手性π-两亲物","[功能扩展]: 具有固有亲水-疏水二重性并整合了π共轭与手性功能"]},{"i":41968,"as":"","scd":null,"kp":[]},{"i":41969,"as":"固态氧化物离子导体是高温电化学技术的核心组件，但在较低温度下维持足够离子迁移率的材料十分稀缺。研究开发出Aurivilius型((Na0.5Bi0.5)n–1TinO3n)(Bi2O2)相的薄膜导体，通过结构设计构建出周期性的快速离子通道。实验表明，该新型结构导体能够在350℃的相对低温下展现出优异的氧化物离子传导性能。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":6.0},"kp":["氧化物离子电导率[Aurivillius型薄膜导体(350°C)]: 具备良好的低温传导率","[低温离子传导机制]: 形成周期性快速离子通道"]},{"i":41970,"as":"揭示硫化物全固态电池中由质子驱动自放电引发的苯醌化学降解机制及其影响。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":4.0,"t":6.0},"kp":["降解机制[硫化物全固态电池中苯醌]: 质子驱动自放电引发化学降解"]},{"i":41971,"as":"针对质子交换膜（PEM）电解槽制氢面临的电力成本和设备退化问题，提出一种多尺度模型预测控制框架。该框架联合优化了日前市场与实时市场中的电力采购和电解槽运行，并显式纳入了高保真电化学行为和薄膜退化机制。研究证实，这种跨市场的灵活协调策略能够有效对齐运行小时，显著降低设备退化程度，从而大幅降低制氢的整体技术经济成本。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":7.0,"t":6.0},"kp":["[柔性PEM电解槽]: 跨电力市场协调运行可降低产氢成本"]},{"i":41972,"as":"","scd":null,"kp":[]},{"i":41973,"as":"儿童纸尿裤、成人失禁产品和女性生理期用品等吸收性卫生产品（AHPs）构成了当前主要的塑料垃圾来源之一。该报告揭示了AHP废物在材料组成与社会管理上的复杂性，并明确指出了科研人员在解决这一日益严峻的AHP垃圾危机中所具备的机遇与作用，呼吁科学家参与寻找应对方案。","scd":{"b":1.0,"i":2.0,"r":5.0,"d":3.0,"t":5.0},"kp":["[吸收性卫生产品废物]: 塑料废物的主要来源"]},{"i":41974,"as":"","scd":null,"kp":[]},{"i":41975,"as":"研究定量评估了全球内河航运的碳排放情况。结果显示，全球内河船舶的二氧化碳排放量约占总船舶排放量的四分之一。这些排放高度集中在北半球，且其空间分布与该区域的经济活动水平呈现出密切的正相关联系。该数据弥补了此前对内河航运碳排限制认知不足的问题。","scd":{"b":1.0,"i":6.0,"r":8.0,"d":8.0,"t":6.0},"kp":["全球CO2排放占比[内河船舶]: 约占全球船舶总排放量的四分之一","[排放空间分布]: 集中在北半球且与经济活动相关"]},{"i":41976,"as":"二维金属氧化物单晶薄膜的合成是实现“超越摩尔”路线图（涵盖自旋电子学、类脑和量子计算）的关键挑战。研究提出一种基于云母的范德华表面重构技术，通过重构云母的氧原子平面，实现了二维金属氧化物及其掺杂材料的大规模、单向外延生长。这些材料能够无缝合并成单晶薄膜，为二维金属单晶的规模化制备提供了通用方法。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":6.0,"t":7.0},"kp":["基底表面重构[二维金属氧化物外延生长]: 云母的范德华表面重构","[外延生长特征]: 实现大规模、定向的二维单晶薄膜合成"]},{"i":41977,"as":"多主元单原子材料（MPSAMs）受高熵材料成分复杂性和单原子催化位点可控性的双重启发。该研究界定了相关术语，阐述了高熵原理如何指导原子级分散结构的设计，并评估了控制原子排列的策略。MPSAMs能在受限空间内跨多个金属位点实现协同作用，展现出常规单原子材料无法达到的反应活性和选择性。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":4.0,"t":6.0},"kp":["[多主元单原子材料]: 受高熵材料启发，在有限空间内实现跨多个金属位点的协同催化功能"]},{"i":41978,"as":"","scd":null,"kp":[]},{"i":41979,"as":"","scd":null,"kp":[]},{"i":41980,"as":"","scd":null,"kp":[]},{"i":41981,"as":"研发出一款新型紧凑型呼气分析检测设备。该仪器能够通过单次呼气准确测定人体是否处于酮症状态（即正在燃烧脂肪）。这一技术为个人体重管理和代谢状态监控提供了实时、便捷的科学数据支持。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":4.0,"t":7.0},"kp":["[呼气分析仪]: 可通过单次呼气检测机体是否处于生酮及燃脂状态"]},{"i":41982,"as":"","scd":null,"kp":[]},{"i":41983,"as":"","scd":null,"kp":[]},{"i":41984,"as":"","scd":null,"kp":[]},{"i":41985,"as":"","scd":null,"kp":[]},{"i":41986,"as":"报道了一种利用金的长程亲金吸引力合成主链完全由金属原子通过连续金属-金属键连接的聚合物的直接一锅法。该方法实现了超过50的聚合度和溶液中稳定的链完整性。系统表征揭示了一维Au主链通过准共价键与配体保护的协同作用形成的连续Au-Au键，为光电磁材料领域提供了高效合成途径。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["主链结构[金属主链聚合物]: 仅由金属原子通过连续金属-金属键连接构成","驱动力[金属主链聚合物合成]: 金的长程亲金引力","合成工艺[金属主链聚合物]: 直接的一锅法"]},{"i":41987,"as":"开发了一种正交二维X射线衍射(2D XRD)绘图技术，用于对大面积完整钙钛矿太阳能组件进行无损结构表征。该技术平台能够同时可视化整个薄膜上的结晶度、晶体取向和残余应变的空间分布，揭示了结构均匀性如何决定大规模、高效太阳能组件的制造过程。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["表征技术[大面积完整钙钛矿组件]: 正交二维X射线衍射mapping技术","测试特性[正交二维X射线衍射mapping]: 非破坏性结构表征","探测维度[钙钛矿薄膜]: 结晶度、晶体取向和残余应力的空间同步可视化"]},{"i":41988,"as":"针对电池脆性正极活性材料在充放电过程中因局部机械应力导致断裂降解的问题，提出了一种利用引发式化学气相沉积制备形状记忆聚合物纳米涂层的方法。该涂层能够动态离域富镍层状氧化物和磷酸铁锂等多种正极材料内部的集中应力。断裂模拟和理化表征证实，该涂层提高了材料的电化学和机械稳定性。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":6.0,"t":7.0},"kp":["涂层方法[脆性电池正极活性材料应力离域]: 形状记忆聚合物纳米涂层方法","涂层工艺[形状记忆聚合物纳米涂层]: 引发化学气相沉积"]},{"i":41989,"as":"利用低温磁红外散射型扫描近场光学显微镜，在纳米尺度上对ZrTe5中的自旋极化螺旋边缘通道进行了成像。研究揭示了磁场诱导的增亮效应，这是高频电动力学下稳健边缘模式的特征，为纳米电子器件中实现无耗散电荷传输和纳米级模式控制提供了直接的空间电动力学可视化依据。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":6.0,"t":7.0},"kp":["边缘模式[ZrTe5]: 拓扑保护的无耗散且抗背散射的螺旋边缘模式"]},{"i":41990,"as":"总结了通过形状记忆聚合物纳米涂层处理电池正极活性材料的技术成果。实验表明，经过这种纳米涂层处理后的电池正极材料，在电池运行过程中展现出了显著提升的电化学性能和机械稳定性。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":4.0,"t":6.0},"kp":["改性效果[涂覆形状记忆聚合物的电池正极材料]: 提升了电池运行期间的电化学和机械稳定性"]},{"i":41991,"as":"系统回顾智能交通系统促进交通减碳的机制、实施约束与部署路径，聚焦绿色低碳交通技术。","scd":{"b":2.0,"i":3.0,"r":6.0,"d":2.0,"t":3.0},"kp":["[智能交通系统]: 促进交通减碳的机制、实施约束与部署路径"]},{"i":41992,"as":"提出基于竞价共识的多主体协同综合能源系统P2P交易策略，涉及日前日内多能市场交易机制。","scd":{"b":3.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":["[多主体协同综合能源系统]: 基于竞价共识的P2P交易策略","[多能市场交易]: 日前日内协同机制"]},{"i":41993,"as":"研究结合分布式光伏发电与电动汽车双向充电的可持续能源管理技术，探索车网互动与清洁能源利用。","scd":{"b":3.0,"i":2.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[可持续能源管理]: 分布式光伏发电与电动汽车双向充电结合"]},{"i":41994,"as":"探讨共享自动驾驶电动汽车对能源系统的灵活性价值，分析其需求增长与降低系统成本间的关联。","scd":{"b":2.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":["[共享自动驾驶电动汽车]: 具备能源系统灵活性价值并降低系统成本"]},{"i":41995,"as":"构建结合大语言模型与燃料电池热电联产的综合能源系统自适应调度框架，应对源荷不确定性。","scd":{"b":5.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":["[综合能源系统自适应调度]: 结合大语言模型与燃料电池热电联产应对源荷不确定性"]},{"i":41996,"as":"研究利用机械信息辅助技术评估大型方形磷酸铁锂电池健康状态，涉及电池诊断与寿命预测方法。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[大型方形磷酸铁锂电池健康状态评估]: 利用机械信息辅助技术进行电池诊断与寿命预测"]},{"i":41997,"as":"开发基于电化学与磁集成技术的质子交换膜燃料电池实时诊断方法，实现负载不变的在线监测。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["[PEMFC实时诊断]: 基于电化学与磁集成技术实现负载不变的在线监测"]},{"i":41998,"as":"报道了一种以白磷(P4)和简单氟化物为原料，一步直接合成六氟磷酸盐(PF6-)的技术。利用DDQ等对苯醌作为氧化剂，在乙腈中实现了高达95%的产率。研究证实DDQ与氟化物之间的供体-受体相互作用有效提高了氟化物浓度，并明确了PF3和PF5加合物等关键中间产物的形成过程。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["合成产率[白磷和氟化物一步法合成六氟磷酸盐]: 高达95%","溶剂[白磷氟化反应]: 乙腈(MeCN)","反应中间体[DDQ介导的P4氟化反应]: PF3和PF5·MeCN","合成路径[六氟磷酸盐(MPF6)]: 以白磷(P4)和简单氟化物(MF)为原料的一步法合成","氧化剂[选择性氟化路径]: 对苯醌类(如2,3-二氯-5,6-二氰基-1,4-苯醌/DDQ)"]},{"i":41999,"as":"提出了一种以坚固的二维金属碳化物Y2C电子化合物为平台的双位点催化剂。氮气在富电子层间被活化，氢气则在负载的镍纳米颗粒上解离，从而实现高效稳定的氨合成。研究揭示了二维电子化合物中氮气活化结合能与中间体形成的比例关系，并通过镧掺杂La-Y2C进一步优化了氮气活化过程。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":["双位点催化剂[二维金属碳化物Y2C电子化合物]: 以Y2C为载体，N2在富电子层间活化，H2在负载的Ni纳米颗粒上解离","催化载体[二维电子化合物]: 坚固的二维金属碳化物Y2C"]}]);